@316 צְפִיר בַּר עִזִין חַד לְחַטָאתָא:
@317 וּלְנִכְסַת קוּדְשַׁיָא תּוֹרִין תְּרֵין דִכְרִין חַמְשָׁא גְדָיֵי חַמְשָׁא אִמְרִין בְּנֵי שַׁתָּא חַמְשָׁא דֵין קֻרְבַּן אֲחִיעֶזֶר בַּר עַמִישַׁדָי:
@318 בְּיוֹמָא חַד עֲשַׂר יוֹמָא רַבָא לִבְנֵי אָשֵׁר פַּגְעִיאֵל בַּר עָכְרָן:
@319 קֻרְבָּנֵה מְגִסְתָּא דִכְסַף חֲדָא מְאָה וּתְלָתִין סִלְעִין הֲוָה מַתְקְלַהּ מִזְרְקָא חַד דִכְסַף מַתְקְלֵהּ שַׁבְעִין סִלְעִין בְּסִלְעֵי קוּדְשָׁא תַּרְוֵיהוֹן מְלַן סֻלְתָּא דְפִילָא בִמְשַׁח לְמִנְחָתָא:
@320 בָּזִיכָא חֲדָא מַתְקַל עֲשַׂר סִלְעִין הִיא דִדְהַב מַלְיָא קְטֹרֶת בּוּסְמַיָא:
@321 תּוֹר חַד בַּר תּוֹרֵי דְכַר חַד אִמַר חַד בַּר שַׁתֵּהּ לַעֲלָתָא:
@322 צְפִיר בַּר עִזִין חַד לְחַטָאתָא:
@323 וּלְנִכְסַת קוּדְשַׁיָא תּוֹרִין תְּרֵין דִכְרִין חַמְשָׁא גְדָיֵי חַמְשָׁא אִמְרִין בְּנֵי שַׁתָּא חַמְשָׁא דֵין קֻרְבַּן פַּגְעִיאֵל בַּר עָכְרָן:
@324 בְּיוֹמָא תְּרֵי עֲשַׂר יוֹמָא רַבָּא לִבְנֵי נַפְתָּלִי אֲחִירַע בַּר עֵינָן:
@325 קֻרְבָּנֵהּ מְגִסְתָּא דִכְסַף חֲדָא מְאָה וּתְלָתִין סִלְעִין הֲוָה מַתְקְלַהּ מִזְרְקָא חַד דִכְסַף מַתְקְלֵהּ שַׁבְעִין סִלְעִין בְּסִלְעֵי קוּדְשָׁא תַּרְוֵיהוֹן מְלַן סֻלְתָּא דְפִילָא בִמְשַׁח לְמִנְחָתָא:
@326 בָּזִיכָא חֲדָא מַתְקַל עֲשַׂר סִלְעִין הִיא דִדְהַב מַלְיָא קְטֹרֶת בּוּסְמַיָא:
@327 תּוֹר חַד בַּר תּוֹרֵי דְכַר חַד אִמַר חַד בַּר שַׁתֵּהּ לַעֲלָתָא:
@328 צְפִיר בַּר עִזִין חַד לְחַטָּאתָא:
@329 וּלְנִכְסַת קוּדְשַׁיָא תּוֹרִין תְּרֵין דִכְרִין חַמְשָׁא גְדָיֵי חַמְשָׁא אִמְרִין בְּנֵי שַׁתָּא חַמְשָׁא דֵין קֻרְבַּן אֲחִירַע בַּר עֵינָן:
@330 דָא חֲנֻכַּת מַדְבְּחָא בְּיוֹמָא דְרַבִּיוּ יָתֵהּ מִן רַבְרְבֵי יִשְׂרָאֵל מְגִיסֵי כַסְפָּא תַּרְתָּא עַשְׂרֵי מִזְרְקֵי כַסְפָּא תְּרֵין עֲשַׂר בָּזִיכֵי דְדַהֲבָא תַּרְתָּא עַשְׂרֵי:
@331 מְאָה וּתְלָתִין סִלְעִין הֲוָה מַתְקְלָא דִמְגִיסְתָּא חֲדָא דְכַסְפָּא וְשַׁבְעִין דְמִזְרְקָא חָד כֹּל כְּסַף מָנַיָא תְּרֵין אַלְפִין וְאַרְבַּע מְאָה בְּסִלְעֵי קוּדְשָׁא:
@332 בָּזִיכֵי דְדַהֲבָא תַּרְתֵּי עַשְׂרֵי מַלְיָן קְטֹרֶת בּוּסְמַיָא מַתְקַל עֲשַׂר סִלְעִין הֲוָה מַתְקְלָא דְבָזִיכָא בְּסִלְעֵי קוּדְשָׁא כָּל דְהַב בָּזִיכַיָא מְאָה וְעַשְׂרִין:
@333 כָּל תּוֹרֵי לַעֲלָתָא תְּרֵי עֲשַׂר תּוֹרִין דִכְרִין תְּרֵי עֲשַׂר אִמְרִין בְּנֵי שַׁתָּא תְּרֵי עֲשַׂר וּמִנְחַתְהוֹן וּצְפִירֵי בַּר עִזִין תְּרֵי עֲשַׂר לְחַטָאתָא:
@334 וְכֹל תּוֹרֵי לְנִכְסַת קוּדְשַׁיָא עַשְׂרִין וְאַרְבְּעָא תּוֹרִין דִכְרִין שִׁתִּין גַדְיַן שִׁתִּין אִמְרִין בְּנֵי שַׁתָּא שִׁתִּין דָא חֲנֻכַּת מַדְבְּחָא בָּתַר דְרַבִּיוּ יָתֵהּ:
@335 וְכַד עָלִיל משֶׁה לְמַשְׁכַּן זִמְנָא לְמַלָלָא עִמֵהּ וּשְׁמַע יָת קָלָא דְמִתְמַלֵל עִמֵהּ מֵעִלָוֵי כַפֻּרְתָּא דִי עַל אֲרוֹנָא דְסַהֲדוּתָא מִבֵּין תְּרֵין כְּרוּבַיָא וּמִתְמַלֵל עִמֵהּ: פפפ:
@336 וּמַלִיל יְיָ עִם משֶׁה לְמֵימָר:
@337 מַלֵל עִם אַהֲרֹן וְתֵימַר לֵהּ בְּאַדְלָקוּתָךְ יָת בּוֹצִינַיָא לָקֳבֵל אַפֵּי מְנַרְתָּא יְהוֹן מְנַהֲרִין שִׁבְעָא בוֹצִינַיָא:
@338 וַעֲבַד כֵּן אַהֲרֹן לָקֳבֵל אַפֵּי מְנַרְתָּא אַדְלֵק בּוֹצִינָהָא כְּמָא דִי פַקִיד יְיָ יָת משֶׁה:
@339 וְדֵין עוֹבַד מְנַרְתָּא נְגִידָא דְהַב עַד שִׁידַהּ עַד שׁוֹשַׁנַהּ נְגִידָא הִיא כְּחֶזְוָא דִי אַחֲזֵי יְיָ יָת משֶׁה כֵּן עֲבַד יָת מְנַרְתָּא:
@340 וּמַלִיל יְיָ עִם משֶׁה לְמֵימָר:
@341 קָרֵב יָת לֵוָאֵי מִגוֹ בְּנֵי יִשְׂרָאֵל וּתְדַכֵּי יָתְהוֹן:
@342 וּכְדֵין תַּעְבֵּד לְהוֹן לְדַכּוֹאֵיהוֹן אֲדֵי עֲלֵיהוֹן מַיָא דְחַטָאתָא וְיַעְבְּרוּן מַסְפַּר עַל כָּל בִּשְׂרְהוֹן וִיחַוְרוּן לְבוּשֵׁיהוֹן וְיִדְכּוּן:
@343 וְיִסְבוּן תּוֹר בַּר תּוֹרֵי וּמִנְחָתֵהּ סֻלְתָּא דְפִילָא בִמְשָׁח וְתוֹר תִּנְיָן בַּר תּוֹרֵי תִּסַב לְחַטָאתָא:
@344 וּתְקָרֵב יָת לֵוָאֵי לִקְדָם מַשְׁכַּן זִמְנָא וְתִכְנוֹשׁ יָת כָּל כְּנִשְׁתָּא דִבְנֵי יִשְׂרָאֵל:
@345 וּתְקָרֵב יָת לֵוָאֵי קֳדָם יְיָ וְיִסְמְכוּן בְּנֵי יִשְׂרָאֵל יָת יְדֵיהוֹן עַל לֵוָאֵי:
@346 וִירִים אַהֲרֹן יָת לֵוָאֵי אֲרָמָא קֳדָם יְיָ מִן בְּנֵי יִשְׂרָאֵל וִיהוֹן לְמִפְלַח יָת פֻּלְחָנָא דַיְיָ:
@347 וְלֵוָאֵי יִסְמְכוּן יָת יְדֵיהוֹן עַל רֵישׁ תּוֹרַיָא וַעֲבֵיד יָת חַד חַטָאתָא וְיָת חַד עֲלָתָא קֳדָם יְיָ לְכַפָּרָא עַל לֵוָאֵי:
@348 וּתְקֵם יָת לֵוָאֵי קֳדָם אַהֲרֹן וְקֳדָם בְּנוֹהִי וּתְרֵים יָתְהוֹן אֲרָמָא קֳדָם יְיָ:
@349 וְתַפְרֵישׁ יָת לֵוָאֵי מִגוֹ בְּנֵי יִשְׂרָאֵל וִיהוֹן מְשַׁמְשִׁין קֳדָמַי לֵוָאֵי:
@350 וּבָתַר כֵּן יַעֲלוּן לֵוָאֵי לְמִפְלַח יָת מַשְׁכַּן זִמְנָא וּתְדַכֵּי יָתְהוֹן וּתְרֵים יָתְהוֹן אֲרָמָא:
@351 אֲרֵי אַפְרָשָׁא מַפְרְשִׁין אִנוּן לִי מִגוֹ בְּנֵי יִשְׂרָאֵל חֲלַף פְּתַח כָּל וַלְדָא בּוּכְרָא כֹלָא מִבְּנֵי יִשְׂרָאֵל קָרֵבִית יָתְהוֹן קֳדָמָי:
@352 אֲרֵי דִילִי כָל בּוּכְרָא בִּבְנֵי יִשְׂרָאֵל בֶּאֱנָשָׁא וּבִבְעִירָא בְּיוֹמָא דִקְטָּלִית כָּל בּוּכְרָא בְּאַרְעָא דְמִצְרַיִם אַקְדֵשִׁית יָתְהוֹן קֳדָמַי:
@353 וְקָרֵבִית יָת לֵוָאֵי חֲלַף כָּל בּוּכְרָא בִּבְנֵי יִשְׂרָאֵל:
@354 וִיהָבִית יָת לֵוָאֵי מְסִירִין לְאַהֲרֹן וְלִבְנוֹהִי מִגוֹ בְּנֵי יִשְׂרָאֵל לְמִפְלַח יָת פּוּלְחָן בְּנֵי יִשְׂרָאֵל בְּמַשְׁכַּן זִמְנָא וּלְכַפָרָא עַל בְּנֵי יִשְׂרָאֵל וְלָא יְהֵי בִּבְנֵי יִשְׂרָאֵל מוֹתָא בְּמִקְרַב בְּנֵי יִשְׂרָאֵל לְקוּדְשָׁא:
@355 וַעֲבַד משֶׁה וְאַהֲרֹן וְכָל כְּנִשְׁתָּא דִבְנֵי יִשְׂרָאֵל לְלֵוָאֵי כְּכֹל דִי פַקֵיד יְיָ יָת משֶׁה לְלֵוָאֵי כֵּן עֲבָדוּ לְהוֹן בְּנֵי יִשְׂרָאֵל:
@356 וְאִדַכִּיוּ לֵוָאֵי וְחַוָרוּ לְבוּשֵׁיהוֹן וַאֲרֵם אַהֲרֹן יָתְהוֹן אֲרָמָא קֳדָם יְיָ וְכַפֵּר עֲלֵיהוֹן אַהֲרֹן לְדַכּוֹאֵיהוֹן:
@357 וּבָתַר כֵּן עֲלוּ לֵוָאֵי לְמִפְלַח יָת פּוּלְחַנְהוֹן בְּמַשְׁכַּן זִמְנָא קֳדָם אַהֲרֹן וְקָדָם בְּנוֹהִי כְּמָא דִי פַקִיד יְיָ יָת משֶׁה עַל לֵוָאֵי כֵּן עֲבָדוּ לְהוֹן:
@358 וּמַלִיל יְיָ עִם משֶׁה לְמֵימָר:
@359 דָא דִי לְלֵוָאֵי מִבַּר חָמֵשׁ וְעַשְׂרִין שְׁנִין וּלְעֵלָא יֵיתֵי לְחֲיָלָא חֵילָא בְּפוּלְחַן מַשְׁכַּן זִמְנָא:
@360 וּמִבַּר חַמְשִׁין שְׁנִין יְתוּב מֵחֵיל פּוּלְחָנָא וְלָא יִפְלַח עוֹד:
@361 וִישַׁמֵשׁ עִם אֲחוֹהִי בְּמַשְׁכַּן זִמְנָא לְמִטַּר מַטָרָא וּפוּלְחָנָא לָא יִפְלָח כְּדֵין תַּעֲבֵיד לְלֵוָאֵי בְּמַטְרַתְהוֹן:
@362 וּמַלִיל יְיָ עִם משֶׁה בְּמַדְבְּרָא דְסִינַי בְּשַׁתָּא תִנְיֵתָא לְמִפַּקְהוֹן מֵאַרְעָא דְמִצְרַיִם בְּיַרְחָא קַדְמָאָה לְמֵימָר:
@363 וְיַעְבְּדוּן בְּנֵי יִשְׂרָאֵל יָת פִּסְחָא בְּזִמְנֵיהּ:
@364 בְּאַרְבַּעַת עַשְׂרָא יוֹמָא בְּיַרְחָא הָדֵין בֵּין שִׁמְשַׁיָא תַּעְבְּדוּן יָתֵהּ בְּזִמְנֵהּ כְּכָל גְזֵרָתֵהּ וּכְכָל דְחָזֵי לֵהּ תַּעְבְּדוּן יָתֵהּ:
@365 וּמַלִיל משֶׁה עִם בְּנֵי יִשְׂרָאֵל לְמֶעְבַּד פִּסְחָא:
@366 וַעֲבָדוּ יָת פִּסְחָא בְּנִיסָן בְּאַרְבַּעַת עַשְׂרָא יוֹמָא לְיַרְחָא בֵּין שִׁמְשַׁיָא בְּמַדְבְּרָא דְסִינָי כְּכֹל דִי פַקִיד יְיָ יָת משֶׁה כֵּן עֲבָדוּ בְּנֵי יִשְׂרָאֵל:
@367 וַהֲווֹ גֻבְרַיָא דִי הֲווֹ מְסָאֲבִין לִטְמֵי נַפְשָׁא דֶאֱנָשָׁא וְלָא יְכִילוּ לְמֶעְבַּד פִּסְחָא בְּיוֹמָא הַהוּא וּקְרִיבוּ קֳדָם משֶׁה וְקָדָם אַהֲרֹן בְּיוֹמָא הַהוּא:
@368 וַאֲמָרוּ גֻבְרַיָא הָאִנוּן לֵהּ אֲנַחְנָא מְסָאֲבִין לִטְמֵי נַפְשָׁא דֶאֱנָשָׁא לְמָא נִתְמְנַע בְּדִיל דְלָא לְקָרָבָא יָת קֻרְבָּנָא דַיְיָ בִּזִמְנֵיה בְּגוֹ בְּנֵי יִשְׂרָאֵל:
@369 וַאֲמַר לְהוֹן משֶׁה אוֹרִיכוּ עַד דְאֶשְׁמָע מָה דְיִתְפַּקֵד מִן קֳדָם יְיָ עַל דִילְכוֹן:
@370 וּמַלִיל יְיָ עִם משֶׁה לְמֵימָר:
@371 מַלֵל עִם בְּנֵי יִשְׂרָאֵל לְמֵימָר גְבַר גְבַר אֲרֵי יְהֵי מְסָאָב לִטְמֵי נַפְשָׁא דֶאֱנָשָׁא אוֹ בְאָרְחָא רְחִיקָא לְכוֹן אוֹ לְדָרֵיכוֹן וְיַעְבֵּד פִּסְחָא קֳדָם יְיָ:
@372 בְּיַרְחָא תִנְיָנָא בְּאַרְבְּעַת עַשְׂרָא יוֹמָא בֵּין שִׁמְשַׁיָא יַעְבְּדוּן יָתֵהּ עַל פַּטִּיר וּמְרָרִין יֵיכְלִנֵהּ:
@373 לָא יַשְׁאֲרוּן מִנֵהּ עַד צַפְרָא וְגַרְמָא לָא יִתְבְּרוּן בֵּהּ כְּכָל גְזֵרַת פִּסְחָא יַעְבְּדוּן יָתֵהּ:
@374 וְגַבְרָא דְהוּא דְכֵי וּבְאֹרַח לָא הֲוָה וְיִתְמְנַע לְמֶעְבַּד פִּסְחָא וְיִשְׁתֵּצֵי אֲנָשָׁא הַהִיא מֵעַמֵהּ אֲרֵי קֻרְבָּנָא דַיְיָ לָא קָרִיב בְּזִמְנֵהּ חוֹבֵהּ יְקַבֵּל גַבְרָא הַהוּא:
@375 וַאֲרֵי יִתְגַיַר עִמְכוֹן גִיוֹרָא וְיַעְבֵּד פִּסְחָא קֳדָם יְיָ כִּגְזֵרַת פִּסְחָא וְכִדְחָזֵי לֵהּ כֵּן יַעְבֵּד קְיָמָא חַד יְהֵי לְכוֹן וּלְגִיוֹרָא וּלְיַצִיבָא דְאַרְעָא:
@376 וּבְיוֹמָא דְאִתָּקַם יָת מַשְׁכְּנָא חֲפָא עֲנָנָא יָת מַשְׁכְּנָא לְמַשְׁכְּנָא דְסַהֲדוּתָא וּבְרַמְשָׁא הֲוָה עַל מַשְׁכְּנָא כְּחֵזוּ אֶשָׁתָא עַד צַפְרָא:
@377 כֵּן הֲוָה תְדִירָא עֲנָנָא חָפֵי לֵּהּ וְחֵיזוּ אֵשָׁתָא בְּלֵילְיָא:
@378 וּלְפוּם אִסְתַּלָקוּת עֲנָנָא מֵעִלָוֵי מַשְׁכְּנָא וּבָתַר כֵּן נָטְלִין בְּנֵי יִשְׂרָאֵל וּבְאַתְרָא דְשָׁרֵי תַמָן עֲנָנָא תַּמָן שָׁרָן בְּנֵי יִשְׂרָאֵל:
@379 עַל מֵימְרָא דַיְיָ נָטְלִין בְּנֵי יִשְׂרָאֵל וְעַל מֵימְרָא דַיְיָ שָׁרָן כָּל יוֹמִין דִי שָׁרֵי עֲנָנָא עַל מַשְׁכְּנָא שָׁרָן:
@380 וּבְאוֹרָכוּת עֲנָנָא עַל מַשְׁכְּנָא יוֹמִין סַגִיאִין וְיִטְרוּן בְּנֵי יִשְׂרָאֵל יָת מַטְרַת מֵימְרָא דַיְיָ וְלָא נָטְלִין:
@381 וְאִית דִי הֲוָה עֲנָנָא יוֹמֵי דְמִנְיָן עַל מַשְׁכְּנָא עַל מֵימְרָא דַיְיָ שָׁרָן וְעַל מֵימְרָא דַיְיָ נָטְלִין:
@382 וְאִית דִי הֲוָה עֲנָנָא מֵרַמְשָׁא וְעַד צַפְרָא וּמִסְתַּלֵק עֲנָנָא בְּצַפְרָא וְנָטְלִין אוֹ יֵמָם וְלֵילֵי וּמִסְתַּלֵק עֲנָנָא וְנָטְלִין:
@383 אוֹ תְרֵין יוֹמִין אוֹ יַרְחָא אוֹ עִדָן בְּעִדָן בְּאוֹרָכוּת עֲנָנָא עַל מַשְׁכְּנָא לְמִשְׁרֵי עֲלוֹהִי שָׁרָן בְּנֵי יִשְׂרָאֵל וְלָא נָטְלִין וּבְאִסְתַּלָקוּתֵהּ נָטְלִין:
@384 עַל מֵימְרָא דַיְיָ שָׁרָן:ועַל מֵימְרָא דַיְיָ נָטְלִין יָת מַטְרַת מֵימְרָא דַיְיָ נָטְרִין עַל מֵימְרָא דַיְיָ בִּידָא דְמשֶׁה:
@385 וּמַלִיל יְיָ עִם משֶׁה לְמֵימָר:
@386 עֲבֵיד לָךְ תַּרְתֵּין חֲצוֹצְרָן דִכְסַף נְגִיד תַּעְבֵּד יַתְהוֹן וִיהֶוְיָן לָךְ לְעַרְעָא כְנִשְׁתָּא וּלְאַטָלָא יָת מַשִׁרְיָתָא:
@387 וְיִתְקְעוּן בְּהוֹן וְיִזְדַמְנוּן לְוָתָךְ כָּל כְּנִשְׁתָּא לִתְרַע מַשְׁכַּן זִמְנָא:
@388 וְאִם בַּחֲדָא יִתְקְעוּן וְיִזְדַמְנוּן לְוָתָךְ רַבְרְבַיָא רֵישֵׁי אַלְפַיָא דְיִשְׂרָאֵל:
@389 וְתִתְקְעוּן יַבֶּבְתָּא וְיִטְלוּן מַשִׁרְיָתָא דְשָׁרָן קִדוּמָא:
@390 וְתִתְקְעוּן יַבֶּבְתָּא תִּנְיָנוּת וְיִטְלוּן מַשִׁרְיָתָא דְשָׁרָן דָרוֹמָא יַבָּבָא יִתְקְעוּן לְמַטְלָנֵיהוֹן:
@391 וּבְמִכְנַשׁ יָת קְהָלָא תִּתְקְעוּן וְלָא תְיַבְּבוּן:
@392 וּבְנֵי אַהֲרֹן כַּהֲנַיָא יִתְקְעוּן בַּחֲצוֹצְרָתָא וִיהֶוְיָן לְכוֹן לִקְיַם עֲלָם לְדָרֵיכוֹן:
@393 וַאֲרֵי תֵעֲלוּן לְאַגָחָא קְרָבָא בְּאַרְעַכוֹן עַל מְעִיקֵי דִמְעִיקִין לְכוֹן וּתְיַבְּבוּן בַּחֲצוֹצְרָתָא וְיֵיעוֹל דוּכְרָנֵיכוֹן לְטָּבָא קֳדָם יְיָ אֱלָהָכוֹן וְתִתְפָּרְקוּן מִסַנְאֵיכוֹן:
@394 וּבְיוֹם חֶדְוַתְכוֹן וּבְמוֹעֲדֵיכוֹן וּבְרֵישֵׁי יַרְחֵיכוֹן וְתִתְקְעוּן בַּחֲצוֹצְרָתָא עַל עֲלָוַתְכוֹן וְעַל נִכְסַת קוּדְשֵׁיכוֹן וִיהֶוְיָן לְכוֹן לְדוּכְרָנָא קֳדָם אֱלָהָכוֹן אֲנָא יְיָ אֱלָהָכוֹן:
@395 וַהֲוָה בְּשַׁתָּא תִנְיֵתָא בְּיַרְחָא תִנְיָנָא בְּעַשְׂרִין לְיַרְחָא אִסְתַּלֵק עֲנָנָא מֵעִלַוֵי מַשְׁכְּנָא דְסַהֲדוּתָא:
@396 וּנְטָלוּ בְנֵי יִשְׂרָאֵל לְמַטְלָנֵיהוֹן מִמַדְבְּרָא דְסִינַי וּשְׁרָא עֲנָנָא בְּמַדְבְּרָא דְפָארָן:
@397 וּנְטָלוּ בְקַדְמֵיתָא עַל מֵימְרָא דַיְיָ בִּידָא דְמשֶׁה:
@398 וּנְטַל טֵקַס מַשְׁרִית בְּנֵי יְהוּדָה בְּקַדְמֵיתָא לְחֵילֵיהוֹן וְעַל חֵילֵהּ נַחְשׁוֹן בַּר עַמִינָדָב:
@399 וְעַל חֵילָא דְשִׁבְטָא דִבְנֵי יִשָׂשׂכָר נְתַנְאֵל בַּר צוּעָר:
@400 וְעַל חֵילָא דְשִׁבְטָא דִבְנֵי זְבוּלֻן אֱלִיאָב בַּר חֵלוֹן:
@401 וּמִתְפְּרַק מַשְׁכְּנָא וְנָטְלִין בְּנֵי גֵרְשׁוֹן וּבְנֵי מְרָרִי נָטְלֵי מַשְׁכְּנָא:
@402 וּנְטַל טֵקַס מַשְׁרִית רְאוּבֵן לְחֵילֵיהוֹן וְעַל חֵילֵהּ אֱלִיצוּר בַּר שְׁדֵיאוּר:
@403 וְעַל חֵילָא דְשִׁבְטָּא דִבְנֵי שִׁמְעוֹן שְׁלֻמִיאֵל בַּר צוּרִישַׁדָי:
@404 וְעַל חֵילָא דְשִׁבְטָא דִבְנֵי גָד אֶלְיָסָף בַּר דְעוּאֵל:
@405 וְנָטְלִין בְּנֵי קְהָת נָטְלֵי מַקְדְשָׁא וּמְקִימִין יָת מַשְׁכְּנָא עַד מֵיתֵיהוֹן:
@406 וּנְטַּל טֵקַס מַשְׁרִית בְּנֵי אֶפְרַיִם לְחֵילֵיהוֹן וְעַל חֵילֵהּ אֱלִישָׁמָע בַּר עַמִהוּד:
@407 וְעַל חֵילָא דְשִׁבְטָא דִבְנֵי מְנַשֶׁה גַמְלִיאֵל בַּר פְּדָהצוּר:
@408 וְעַל חֵילָא דְשִׁבְטָא דִבְנֵי בִנְיָמִן אֲבִידָן בַּר גִדְעוֹנִי:
@409 וּנְטַל טֵקַס מַשְׁרִית בְּנֵי דָן מַכְנִישׁ לְכָל מַשִׁרְיָתָא לְחֵילֵיהוֹן וְעַל חֵילֵהּ אֲחִיעֶזֶר בַּר עַמִישַׁדָי:
@410 וְעַל חֵילָא דְשִׁבְטָא דִבְנֵי אָשֵׁר פַּגְעִיאֵל בַּר עָכְרָן:
@411 וְעַל חֵילָא דְשִׁבְטָא דִבְנֵי נַפְתָּלִי אֲחִירַע בַּר עֵינָן:
@412 אִלֵין מַטְלָנֵי בְּנֵי יִשְׂרָאֵל לְחֵילֵיהוֹן וּנְטָלוּ:
@413 וַאֲמַר משֶׁה לְחוֹבָב בַּר רְעוּאֵל מִדְיָנָאָה חֲמוֹהִי דְמשֶׁה נָטְלִין אֲנַחְנָא לְאַתְרָא דִי אֲמַר יְיָ יָתֵהּ אֶתֵּן לְכוֹן אִיתָא עִמָנָא וְנוֹטֵיב לָךְ אֲרֵי יְיָ מַלֵיל לְאַיְתָאָה טָּבָא עַל יִשְׂרָאֵל:
@414 וַאֲמַר לֵהּ לָא אֵזִל אֶלָהֵן לְאַרְעִי וּלְיַלָדוּתִי אֵזִל:
@415 וַאֲמַר לָא כְעַן תִּשְׁבּוֹק יָתָנָא אֲרֵי עַל כֵּן יְדַעַתְּ כַּד הֲוֵינָא שָׁרַן בְּמַדְבְּרָא וּגְבוּרָן דְאִתְעֲבִידָן לָנָא חֲזֵיתָא בְעֵינָיִךְ:
@416 וִיהֵי אֲרֵי תֵזִל עִמָנָא וִיהֵי טָבָא הַהוּא דִי יוֹטִיב יְיָ עִמָנָא וְנוֹטִיב לָךְ:
@417 וּנְטָּלוּ מִטוּרָא דְאִתְגְלֵי עֲלוֹהִי יְקָרָא דַיְיָ מַהֲלַךְ תְּלָתָא יוֹמִין וַאֲרוֹן קְיָמָא דַיְיָ נְטַּל קֳדָמֵיהוֹן מַהֲלַךְ תְּלָתָא יוֹמִין לְאַתְקְנָאָה לְהוֹן אֲתַר בֵּית מֵישְׁרֵי:
@418 וַעֲנַן יְקָרָא דַיְיָ מַטֵיל עֲלֵיהוֹן בִּימָמָא בְּמֵטַלְהוֹן מִן מַשְׁרִיתָא:
@419 וַהֲוָה בְּמֵטַל אֲרוֹנָא וַאֲמַר משֶׁה אִתְגְלֵי יְיָ וְיִתְבַּדְרוּן סַנְאָיךְ וִיעַרְקוּן בַּעֲלֵּי דְבָבָךְ מִן קֳדָמָךְ:
@420 וּבְמַשְׁרוֹהִי אֲמַר תּוּב יְיָ שְׁרֵי בִיקָרָךְ בְּגוֹ רִבְבָן אַלְפַיָא דְיִשְׂרָאֵל:
@421 וַהֲוָה עַמָא כַּד מִסְתַּקְפִין בִּישׁ קֳדָם יְיָ וּשְׁמִיעַ קֳדָם יְיָ וּתְקֵף רוּגְזֵיהּ וּדְלֵקַת בְּהוֹן אֶשָׁתָא מִן קֳדָם יְיָ וְשֵׁצִיאַת בִּסְיָפֵי מַשְׁרִיתָא:
@422 וּצְוַח עַמָא עַל משֶׁה וְצַלִי משֶׁה קֳדָם יְיָ וְאִשְׁתְּקַעַת אֶשָׁתָא:
@423 וּקְרָא שְׁמָא דְאַתְרָא הַהוּא דְלֶקְתָּא אֲרֵי דְלֵקַת בְּהוֹן אֶשָׁתָא מִן קֳדָם יְיָ:
@424 וַעָרַבְרְבִין דִי בֵּינֵיהוֹן שְׁאִילוּ שְׁאֶלְתָּא וְתָבוּ וּבְכוֹ אַף בְּנֵי יִשְׂרָאֵל וַאֲמָרוּ מַאן יֵיכְלִנָנָא בִּשְׂרָא:
@425 דְכִירִין אֲנַחְנָא יָת נוּנַיָא דַהֲוֵינָא אָכְלִין בְּמִצְרַיִם מַגָן יָת בּוֹצִינַיָא וְיָת אֲבַטִיחַיָא וּכְרָתֵי וּבוּצְלֵי וְתוּמֵי:
@426 וּכְעַן נַפְשָׁנָא תְאִיבָא לֵית כָּל מִדָעַם אֶלָהֵן לְמַנָא עֵינָנָא:
@427 וּמַנָא כְּבַר זְרַע גִדָא הוּא וְחֶזְוֵהּ כְּחֵזוּ בְדֹלְחָא:
@428 שַׁיְטִין עַמָא וְלָקְטִין דְצָבֵי טָחִין בְּרֵיחַיָא אוֹ דְצָבֵי דָאִיךְ בִּמְדֻכְתָּא וּמְבַשְׁלִין לֵהּ בְּקִדְרָא וְעָבְדִין יָתֵהּ גְרִיצָן וַהֲוָה טַּעֲמֵהּ כִּטְעֵם דְלִישׁ בְּמִשְׁחָא:
@429 וְכַד נַחִית טַלָא עַל מַשְׁרִיתָא לֵילְיָא נָחִית מַנָא עֲלוֹהִי:
@430 וּשְׁמַע משֶׁה יָת עַמָא בָּכַן לְזַרְעֲיַתְהוֹן גְבַר בִּתְרַע מַשְׁכְּנֵה וּתְקֵף רוּגְזָא דַיְיָ לַחֲדָא וּבְעֵינֵי משֶׁה בִּישׁ:
@431 וַאֲמַר משֶׁה קֳדָם יְיָ לְמָא אַבְאֶשְׁתָּא לְעַבְדָךְ וּלְמָא לָא אַשְׁכָּחִית רַחֲמִין קֳדָמָךְ לְשַׁוָאָה יָת מַטוּל כָּלּ עַמָא הָדֵין עָלָי:
@432 הֲאַב אֲנָא לְכָל עַמָא הָדֵין אִם בְּנַי אִנוּן דְאָמְרֵתּ לִי סוֹבַרְהִי בְתוּקְפָךְ כְּמָא דִמְסוֹבַר תֻּרְבְּיָנָא יָת יַנְקָא עַל אַרְעָא דִי קַיֵמְתָּא לַאֲבָהָתוֹהִי:
@433 מְנַן לִי בִּשְׂרָא לְמִיתַּן לְכָל עַמָא הָדֵין אֲרֵי בָּכַן עֲלַי לְמֵימַר הַב לָנָא בִשְׂרָא וְנֵיכוּל:
@434 לֵית אֲנָא יָכִיל בִּלְחוֹדִי לְסוֹבָרָא יָת כָּל עַמָא הָדֵין אֲרֵי יַקִיר מִנִי:
@435 וְאִם כְּדֵין אַתְּ עָבֵד לִי קְטָלְנִי כְעַן קְטוֹל אִם אַשְׁכָּחִית רַחֲמִין קֳדָמָךְ וְלָא אֶחֱזֵי בְּבִישְׁתִּי:
@436 וַאֲמַר יְיָ לְמשֶׁה כְּנוֹשׁ קֳדָמַי שַׁבְעִין גַבְרָא מִסָבֵי יִשְׂרָאֵל דִי יְדַעַתְּ אֲרֵי אִנוּן סָבֵי עַמָא וְסַרְכוֹהִי וְתַדְבֵּר יָתְהוֹן לְמַשְׁכַּן זִמְנָא וְיִתְעַתְּדוּן תַּמָן עִמָךְ:
@437 וְאִתְגְלֵי וַאֲמַלֵל עִמָךְ תַּמָן וַאֲרַבֵּי מִן רוּחָא דִי עֲלָךְ וֶאֱשַׁוֵּי עֲלֵיהוֹן וִיסוֹבְרוּן עִמָךְ בְּמַטוּל עַמָא וְלָא תְסוֹבַר אַתְּ בִּלְחוֹדָךְ:
@438 וּלְעַמָא תֵימַר אִזְדַמְנוּ לִמְחַר וְתֵיכְלוּן בִּשְׂרָא אֲרֵי בְּכִיתוּן קֳדָם יְיָ לְמֵימַר מָן יֵכְלִנָנָא בִּשְׂרָא אֲרֵי טַב לָנָא בְּמִצְרָיִם וְיִתֵּן יְיָ לְכוֹן בִּשְׂרָא וְתֵיכְלוּן:
@439 לָא יוֹמָא חַד תֵּיכְלוּן וְלָא תְרֵין יוֹמִין וְלָא חַמְשָׁא יוֹמִין וְלָא עַשְׂרָא יוֹמִין וְלָא עַשְׂרִין יוֹמִין:
@440 עַד יְרַח יוֹמִין עַד דִי תְקוּצוּן בֵּהּ וִיהֵי לְכוֹן לְתַקְלָא חֲלַף דְקַצְתּוּן יָת מֵימְרָא דַיְיָ דִשְׁכִנְתֵּהּ שַׁרְיַת בֵּינֵיכוֹן וּבְכִיתוּן קֳדָמוֹהִי לְמֵימַר לְמָא דְנַן נְפַקְנָא מִמִצְרָיִם:
@441 וַאֲמַר משֶׁה שִׁית מְאָה אַלְפִין גַבְרָא רִגְלָאָה עַמָא דִי אֲנָא בֵינֵיהוֹן וְאַתְּ אֲמַרְתְּ בִּשְׂרָא אֶתֵּן לְהוֹן וְיֵיכְלוּן יְרַח יוֹמִין:
@442 הֲעָן וְתוֹרִין יִתְנַכְסוּן לְהוֹן הַיְסַפְּקוּן לְהוֹן אִם יָת כָּל נוּנֵי יַמָא יִתְכַנְשׁוּן לְהוֹן הַיְסַפְּקוּן לְהוֹן:
@443 וַאֲמַר יְיָ לְמשֶׁה הֲמֵימְרָא דַיְיָ יִתְעַכָּב כְּעַן תֶּחֱזֵי הַיְעַרְעִנָךְ פִּתְגָמִי אִם לָא:
@444 וּנְפַק משֶׁה וּמַלִיל לְעַמָא יָת פִּתְגָמַיָא דַיְיָ וּכְנַשׁ שַׁבְעִין גַבְרָא מִסָבֵי עַמָא וַאֲקֵים יָתְהוֹן סְחוֹר סְחוֹר לְמַשְׁכְּנָא:
@445 וְאִתְגְלִי יְיָ בַּעֲנָנָא וּמַלִיל עִמֵהּ וְרַבֵּי מִן רוּחָא דִי עֲלוֹהִי וִיהַב עַל שַׁבְעִין גַבְרָא סָבַיָא וַהֲוָה כַּד שְׁרַת עֲלֵיהוֹן רוּחַ נְבוּאָה וּמִתְנַבְּאִין וְלָא פָסְקִין:
@446 וְאִשְׁתַּאֲרוּ תְּרֵין גַבְרִין בְּמַשְׁרִיתָא שׁוּם חָד אֶלְדָד וְשׁוּם תִּנְיָנָא מֵידָד וּשְׁרַת עֲלֵיהוֹן רוּחַ נְבוּאָה וְאִנוּן בַּכְּתִיבַיָא וְלָא נְפָקוּ לְמַשְׁכְּנָא וְאִתְנַבִּיאוּ בְּמַשְׁרִיתָא:
@447 וּרְהַט עוּלֵמָא וְחַוֵי לְמשֶׁה וַאֲמַר אֶלְדָד וּמֵידָד מִתְנַבְּאִין בְּמַשְׁרִיתָא:
@448 וַאֲתֵב יְהוֹשֻׁעַ בַּר נוּן מְשֻׁמְשִׁנֵהּ דְמשֶׁה מֵעוּלֵמוֹהִי וַאֲמַר רִבּוֹנִי משֶׁה אֲסָרִנוּן:
@449 וַאֲמַר לֵהּ משֶׁה הֲקִנְאָתִי אַתְּ מְקַנֵא לִי רְעֵינָא פוּן דִיהוֹן כָּל עַמָא דַיְיָ נְבִיאִין אֲרֵי יִתֵּן יְיָ יָת רוּחַ נְבוּאֲתֵהּ עֲלֵיהוֹן:
@450 וְאִתְכְּנֵשׁ משֶׁה לְמַשְׁרִיתָא הוּא וְסָבֵי יִשְׂרָאֵל:
@451 וְרוּחָא נְטַל מִן קֳדָם יְיָ וְאַפְרַח שְׂלָיו מִן יַמָא וּרְמָא עַל מַשְׁרִיתָא כְּמַהֲלַךְ יוֹמָא לְכָא וּכְמַהֲלַךְ יוֹמָא לְכָא סְחוֹר סְחוֹר לְמַשְׁרִיתָא וּכְרוּם תַּרְתֵּין אַמִין עַל אַפֵּי אַרְעָא:
@452 וְקָם עַמָא כָּל יוֹמָא הַהוּא וְכָל לֵילְיָא וְכָל יוֹמָא דְבַתְרוֹהִי וּכְנָשׁוּ יָת שְׂלָיו דְאַזְעַר כְּנַשׁ עַשְׂרָא דְגוֹרִין וּשְׁטָחוּ לְהוֹן מַשְׁטִיחִין סְחוֹר סְחוֹר לְמַשְׁרִיתָא:
@453 בִּשְׂרָא עַד כְּעַן בֵּין שִׁנֵיהוֹן עַד לָא פְסַק וְרָגְזָא דַיְיָ תְּקֵיף בְּעַמָא וּקְטַל יְיָ בְּעַמָא קְטוֹל סַגִי לַחֲדָא:
@454 וּקְרָא יָת שְׁמָא דְאַתְרָא הַהוּא קִבְרֵי דִמְשַׁאֲלֵי אֲרֵי תַמָן קְבָרוּ יָת עַמָא דְשָׁאִילוּ:
@455 מִקִבְרֵי דִמְשַׁאֲלֵי נְטָּלוּ עַמָא לַחֲצֵרוֹת וַהֲווֹ בַּחֲצֵרוֹת:
@456 וּמַלֵלַת מִרְיָם וְאַהֲרֹן בְּמשֶׁה עַל עֵסַק אִתְּתָא שַׁפִּרְתָּא דִי נְסִיב אֲרֵי אִתְּתָא שַׁפֻּרְתָּא דִנְסִיב רָחִיק:
@457 וַאֲמָרוּ הַלְחוֹד בְּרַם בְּמשֶׁה מַלִיל יְיָ הֲלָא אַף עִמָנָא מַלִיל וּשְׁמִיעַ קֳדָם יְיָ:
@458 וְגַבְרָא משֶׁה עִנְוְתָן לַחֲדָא מִכֹּל אֱנָשָׁא דִי עַל אַפֵי אַרְעָא:
@459 וַאֲמַר יְיָ בִּתְכֵּף לְמשֶׁה וּלְאַהֲרֹן וּלְמִרְיָם פּוּקוּ תְלָתֵיכוֹן לְמַשְׁכַּן זִמְנָא וּנְפָקוּ תְּלָתֵיהוֹן:
@460 וְאִתְגְלֵי יְיָ בְּעַמוּדָא דַעֲנָנָא וְקָם בִּתְרַע מַשְׁכְּנָא וּקְרָא אַהֲרֹן וּמִרְיָם וּנְפָקוּ תַּרְוֵיהוֹן:
@461 וַאֲמַר שְׁמָעוּ כְעַן פִּתְגָמָי אִם יְהוֹן לְכוֹן נְבִיאִין אֲנָא יְיָ בְּחֶזְוָן אֲנָא מִתְגְלֵי לְהוֹן בְּחֶלְמִין אֲנָא מְמַלֵל עִמְהוֹן:
@462 לָא כֵן עַבְדִי משֶׁה בְּכָל בֵּיתִי מְהֵימָן הוּא:
@463 מַמְלַל עִם מַמְלַל מַלֶלְנָא עִמֵהּ בְּחֵזוּ וְלָא בְחִדְוָן וּדְמוּת יְקָרָא דַיְיָ מִסְתַּכַּל וּמָא דֵין לָא דְחֶלְתּוּן לְמַלָלָא בְּעַבְדִי בְמשֶׁה:
@464 וּתְקֵיף רוּגְזָא דַיְיָ בְּהוֹן וְאִסְתַּלֵק:
@465 וַעֲנָנָא אִסְתַּלַק מֵעִלָוֵי מַשְׁכְּנָא וְהָא מִרְיָם חַוְרָא כְּתַלְגָא וְאִתְפְּנֵי אַהֲרֹן לְוָת מִרְיָם וְהָא סְגִירָת:
@466 וַאֲמַר אַהֲרֹן לְמשֶׁה בְּבָעוּ רִבּוֹנִי לָא כְעַן תְּשַׁוִי עֲלָנָא חוֹבָא דְאִטְפַּשְׁנָא וְדִי סָרֲחְנָא:
@467 לָא כְעַן תִּתְרַחֵק דָא מִבֵּינָנָא אֲרֵי אֲחַתָנָא הִיא צַלִי כְעַן עַל בִּסְרָא מִיתָא הָדֵין דִי בָהּ וְיִתָּסֵי:
@468 וְצַלִי משֶׁה קֳדָם יְיָ לְמֵימָר אֱלָהָא בְּבָעוּ אַסֵי כְעַן יָתָהּ:
@469 וַאֲמַר יְיָ לְמשֶׁה וְאִלוּ אָבוּהָא מִנְזַף נְזִיף בָּהּ הֲלָא תִתְכְּלֵם שַׁבְעָא יוֹמִין תִּסְתַּגֵר שַׁבְעָא יוֹמִין מִבָּרָא לְמַשְׁרִיתָא וּבָתַר כֵּן תִּתְכְּנֵשׁ:
@470 וְאִסְתְּגָרַת מִרְיָם מִבָּרָא לְמַשְׁרִיתָא שַׁבְעָא יוֹמִין וְעַמָא לָא נְטַל עַד דְאִתְכְּנֵשַׁת מִרְיָם:
@471 וּבָתַר כֵּן נְטָלוּ עַמָא מֵחֲצֵרוֹת וּשְׁרוֹ בְּמַדְבְּרָא דְפָארָן: פפפ:
@472 וּמַלִיל יְיָ עִם משֶׁה לְמֵימָר:
@473 שְׁלַח לָךְ גֻבְרִין וִיאַלְלוּן יָת אַרְעָא דִכְנָעַן דִי אֲנִי יָהֵב לִבְנֵי יִשְׂרָאֵל גַבְרָא חַד גַבְרָא חַד לְשִׁבְטָא דַאֲבָהָתוֹהִי תְּשַׁלְחוּן כֹּל רַבָּא דִבְהוֹן:
@474 וּשְׁלַח יָתְהוֹן משֶׁה מִמַדְבְּרָא דְפָארָן עַל מֵימְרָא דַיְיָ כֻּלְהוֹן גֻבְרִין רֵישֵׁי בְנֵי יִשְׂרָאֵל אִנוּן:
@475 וְאִלֵין שְׁמָהַתְהוֹן לְשִׁבְטָא דִרְאוּבֵן שַׁמוּעַ בַּר זַכּוּר:
@476 לְשִׁבְטָא דְשִׁמְעוֹן שָׁפָטּ בַּר חוֹרִי:
@477 לְשִׁבְטָא דִיהוּדָה כָּלֵבּ בַּר יְפֻנֶה:
@478 לְשִׁבְטָא דְיִשָׂשׂכָר יִגְאָל בַּר יוֹסֵף:
@479 לְשִׁבְטָא דְאֶפְרַיִם הוֹשֵׁעַ בַּר נוּן:
@480 לְשִׁבְטָא דְבִנְיָמִן פַּלְטִי בַּר רָפוּא:
@481 לְשִׁבְטָא דִזְבוּלֻן גַדִיאֵל בַּר סוֹדִי:
@482 לְשִׁבְטָא דְיוֹסֵף לְשִׁבְטָא דִמְנַשֶׁה גַדִי בַּר סוּסִי:
@483 לְשִׁבְטָא דְדָן עַמִיאֵל בַּר גְמַלִי:
@484 לְשִׁבְטָא דְאָשֵׁר סְתוּר בַּר מִיכָאֵל:
@485 לְשִׁבְטָא דְנַפְתָּלִי נַחְבִּי בַּר וָפְסִי:
@486 לְשִׁבְטָּא דְגָד גְאוּאֵל בַּר מָכִי:
@487 אִלֵין שְׁמָהַת גֻבְרַיָא דִי שְׁלַח משֶׁה לְאַלָלָא יָת אַרְעָא וּקְרָא משֶׁה לְהוֹשֵׁעַ בַּר נוּן יְהוֹשֻׁעַ:
@488 וּשְׁלַח יָתְהוֹן משֶׁה לְאַלָלָא יָת אַרְעָא דִכְנָעַן וַאֲמַר לְהוֹן סָקוּ דָא בִּדְרוֹמָא וְתִסְקוּן לְטוּרָא:
@489 וְתֶחֱזוּן יָת אַרְעָא מָה הִיא וְיָת עַמָא דְיָתֵב עֲלַהּ הֲתַקִיף הוּא אִם חֲלָשׁ הַזְעֵר הוּא אִם סַגִי:
@490 וּמָה אַרְעָא דִי הוּא יָתֵב בָּהּ הֲטָבָא הִיא אִם בִּישָׁא וּמָה קִרְוַיָא דִי הוּא יָתֵב בְהוֹן הַבְּפַצְחִין אִם בִּכְרַכִּין:
@491 וּמָה אַרְעָא הֲעַתִּירָא הִיא אִם מִסְכֵּנָא הֲאִית בַּהּ אִילָנִין אִם לָא וְתִתְקְפוּן וְתִסְבוּן מֵאִבָּא דְאַרְעָא וְיוֹמַיָא יוֹמֵי בִּכּוּרֵי עִנְבִין:
@492 וסְלִיקוּ וְאַלִילוּ יָת אַרְעָא מִמַדְבְּרָא דְצִין עַד רְחוֹב לִמְטֵי חֲמָת:
@493 וּסְלִיקוּ בְדָרוֹמָא וַאֲתָא עַד חֶבְרוֹן וְתַמָן אֲחִימָן שֵׁשַׁי וְתַלְמַי בְּנֵי גִבָּרַיָא וְחֶבְרוֹן שְׁבַע שְׁנִין אִתְבְּנִיאַת קֳדָם טָנֵס דְמִצְרָיִם:
@494 וַאֲתוֹ עַד נַחֲלָא דְאִתְכָּלָא וּקְצוֹ מִתַּמָן עוֹבַרְתָּא וְאַתְכַּל עִנְבִין חַד וּנְטָלוֹהִי בַאֲרִיחָא בִּתְרֵין וּמִן רִמוֹנַיָא וּמִן תְּאֵנַיָא:
@495 לְאַתְרָא הַהוּא קְרָא נַחְלָא דְאִתְכָּלָא עַל עֵסַק אִתְכָּלָא דִקְצוֹ מִתַּמָן בְּנֵי יִשְׂרָאֵל:
@496 וְתָבוּ מִלְאַלָלָא יָת אַרְעָא מִסוֹף אַרְבְּעִין יוֹמִין:
@497 וַאֲזָלוּ וְאָתוּ לְוַת משֶׁה וּלְוַת אַהֲרֹן וּלְוַת כָּל כְּנִשְׁתָּא דִבְנֵי יִשְׂרָאֵל לְמַדְבְּרָא דְפָארָן לִרְקָם וַאֲתִיבוּ יָתְהוֹן פִּתְגָמָא וְיָת כָּל כְּנִשְׁתָּא וְאַחֲזֵיאֻנוּן יָת אִבָּא דְאַרְעָא:
@498 וְאִשְׁתָּעִיאוּ לֵהּ וַאֲמָרוּ אֲתֵינָא לְאַרְעָא דִי שְׁלַחְתָּנָא וְאַף עַבְדָא חֲלַב וּדְבַשׁ הִיא וְדֵין אִבַּהּ:
@499 לְחוֹד אֲרֵי תַקִיף עַמָא דְיָתֵב בְּאַרְעָא וְקִרְוַיָא כְּרִיכָן רַבְרְבִין לַחֲדָא וְאַף בְּנֵי גִבָּרַיָא חֲזֵינָא תַמָן:
@500 עֲמַלְקָאָה יָתֵב בַּאֲרַע דָרוֹמָא וְחִתָּאָה וִיבוּסָאָה וֶאֱמוֹרָאָה יָתֵב בְּטּוּרָא וּכְנַעֲנָאָה יָתֵב עַל יַמָא וְעַל כֵּיף יַרְדְנָא:
@501 וַאֲצֵית כָּלֵב יָת עַמָא לְמשֶׁה וַאֲמַר מֵיסַק נִיסַק וְנִירַת יָתַהּ אֲרֵי מֵיכַל נֵיכוּל לָהּ:
@502 וְגֻבְרַיָא דִי סְלִיקוּ עִמֵהּ אֲמָרוּ לָא נֵיכוֹל לְמֵיסַק לְוַת עַמָא אֲרֵי תַּקִיף הוּא מִנָנָא:
@503 וְאַפִּיקוּ שׁוּם בִּישׁ עַל אַרְעָא דִי אַלִילוּ יָתָהּ לְוַת בְּנֵי יִשְׂרָאֵל לְמֵימָר אַרְעָא דִי עֲבַרְנָא בָהּ לְאַלָלָא יָתָהּ אַרְעָא מְקַטְלָא יַתְבָהָא הִיא וְכָל עַמָא דִי חֲזֵינָא בְגַוָהּ אֱנָשִׁין דְמִשְׁחָן:
@504 וְתַמָן חֲזֵינָא יָת גִבָּרַיָא בְּנֵי עֲנָק מִן גִבָּרַיָא וַהֲוֵינָא בְעֵינֵי נַפְשָׁנָא כְּקַמְצִין וְכֵן הֲוֵינָא בְּעֵינֵיהוֹן:
@505 וַאֲרֵימַת כָּל כְּנִשְׁתָּא וִיהָבוּ יָת קָלְהוֹן וּבְכוֹ עַמָא בְּלֵילְיָא הַהוּא:
@506 וְאִתְרַעֲמוּ עַל משֶׁה וְעַל אַהֲרֹן כֹּל בְּנֵי יִשְׂרָאֵל וַאֲמָרוּ לְהוֹן כָּל כְּנִשְׁתָּא לְוַי דְמִיתְנָא בְּאַרְעָא דְמִצְרַיִם אוֹ בְּמַדְבְּרָא הָדֵין לְוַי דְמִיתְנָא:
@507 וּלְמָא יְיָ מָעֵל יָתָנָא לְּאַרְעָא הָדָא לְּמִנְפַּלּ בְּחַרְבָּא נְשָׁנָא וְטַּפְלָנָא יְהוֹן לְבִזָא הֲלָא טַב לָנָא דִי נְתוּב לְמִצְרָיִם:
@508 וַאֲמָרוּ גְבַר לַאֲחוֹהִי נְמַנֵי רֵישָׁא וּנְתוּב לְמִצְרָיִם:
@509 וּנְפַל משֶׁה וְאַהֲרֹן עַל אַפֵּיהוֹן קֳדָם כָּל קְהַל כְּנִשְׁתָּא דִבְנֵי יִשְׂרָאֵל:
@510 וִיהוֹשֻׁעַ בַּר נוּן וְכָלֵב בַּר יְפֻנֶה מִן מְאַלְלֵי יָת אַרְעָא בְּזָעוּ לְבוּשֵׁיהוֹן:
@511 וַאֲמָרוּ לְכָל כְּנִשְׁתָּא דִבְנֵי יִשְׂרָאֵל לְמֵימָר אַרְעָא דִי עֲבַרְנָא בָהּ לְאַלָלָא יָתַהּ טָבָא אַרְעָא לְחֲדָא לַחֲדָא:
@512 אִם רַעֲוָא בָנָא קֳדָם יְיָ וְיָעֵל יָתָנָא לְאַרְעָא הָדָא וְיִתְּנִנַהּ לָנָא אַרְעָא דִי הִיא עַבְדָא חֲלַב וּדְבָשׁ:
@513 בְּרַם בְּמֵימְרָא דַיְיָ לָא תִמְרְדוּן וְאַתּוּן לָא תִדַחֲלוּן מִן עַמָא דְאַרְעָא אֲרֵי בִידָנָא מְסִירִין אִנוּן עֲדָא תָקְפְהוֹן מִנְהוֹן וּמֵימְרָא דַיְיָ בְּסַעְדָנָא לָא תִדְחֲלוּן מִנְהוֹן:
@514 וַאֲמָרוּ כָּל כְּנִשְׁתָּא לְמִרְגַם יַתְהוֹן בְּאַבְנַיָא וִיקָרָא דַיְיָ אִתְגְלֵי בְּמַשְׁכַּן זִמְנָא לְכָל בְּנֵי יִשְׂרָאֵל:
@515 וַאֲמַר יְיָ לְמשֶׁה עַד אֵימָתַי יְהוֹן מְרַגְזִין קֳדָמַי עַמָא הָדֵין וְעַד אֵימָתַי לָא יְהֵימְנוּן בְּמֵימְרִי בְּכֹל אָתַיָא דִי עֲבָדִית בֵּינֵיהוֹן:
@516 אֶמְחִנוּן בְּמוֹתָא וַאֲשֵׁצִנוּן וְאֶעְבֵּד יָתָךְ לְעַם רַב וְתַקִיף מִנְהוֹן:
@517 וַאֲמַר משֶׁה קֳדָם יְיָ וְיִשְׁמְעוּן מִצְרָאֵי אֲרֵי אַסֶקְתָּא בְחֵילָךְ יָת עַמָא הָדֵין מִבֵּינֵיהוֹן:
@518 וְיֵימְרוּן לְיָתֵב אַרְעָא הָדָא דִשְׁמָעוּ אֲרֵי אַתְּ יְיָ דִשְׁכִנְתָּךְ שַׁרְיַת בְּגוֹ עַמָא הָדֵין דִי בְעֵינֵיהוֹן חָזַן שְׁכִינַת:יְקָרָא דַיְיָ וַעֲנָנָךְ מַטֵל עִלַוֵהוֹן וּבְעַמוּדָא דַעֲנָנָא אַתְּ מְדַבַּר קֳדָמֵיהוֹן בִּימָמָא וּבְעַמוּדָא דְאֵשָׁתָא בְּלֵילְיָא:
@519 וּתְקַטֵּל יָת עַמָא הָדֵין כְּגַבְרָא חָד וְיֵימְרוּן עַמְמַיָא דִי שְׁמָעוּ יָת שְׁמַע גְבֻרְתָּךְ לְמֵימָר:
@520 מִדְלֵית יוּכְלָא קֳדָם יְיָ לְאָעָלָא יָת עַמָא הָדֵין לְאַרְעָא דִי קַיֵם לְהוֹן וְקַטְלִנוּן בְּמַדְבְּרָא:
@521 וּכְעַן סַגִי כְעַן חֵילָא (מִן) קֳדָם יְיָ כְּמָא דִי מַלֵילְתָּא לְמֵימָר:
@522 יְיָ מַרְחֵק רְגַז וּמַסְגֵי לְמֶעְבַּד טַבְוָן (וּקְשׁוֹט) שָׁבֵק לַעֲוָיָן וְלִמְרוֹד וּלְחוֹבִין סַלַח לִדְתַיְיבִין לְאוֹרַיְתֵהּ וּדְלָא תַיְיבִין לָא מְזַכֵּי מַסְעַר חוֹבֵי אֲבָהָן עַל בְּנִין מְרָדִין עַל דַר תְּלִיתָאֵי וְעַל דַר רְבִיעָאֵי:
@523 שְׁבוֹק כְּעַן לְחוֹבֵי עַמָא הָדֵין כִּסְגִיאוּת טַבְוָתָךְ וּכְמָא דִי שְׁבַקְתָּא לְעַמָא הָדֵין מִמִצְרַיִם וְעַד כְּעָן:
@524 וַאֲמַר יְיָ שְׁבָקִית כְּפִתְגָמָךְ:
@525 וּבְרַם קַיָים אֲנָא וּמַלְיָא יְקָרָא דַיְיָ יָת כָּל אַרְעָא:
@526 אֲרֵי כָל גֻבְרַיָא דַחֲזוֹ יָת יְקָרִי וְיָת אַתְוָתַי דִי עֲבָדִית בְּמִצְרַיִם וּבְמַדְבְּרָא וְנַסִיאוּ קֳדָמַי דְנַן עֲשַׂר זִמְנִין וְלָא קַבִּילוּ בְּמֵימְרִי:
@527 אִם יֶחֶזוּן יָת אַרְעָא דִי קַיֵמִית לַאֲבָהַתְהוֹן וְכָל דְאַרְגִיזוּ קֳדָמַי לָא יֶחֱזִנַהּ:
@528 וְעַבְדִי כָלֵב חֲלַף דַהֲוָה רוּחַ אוֹחֲרִי עִמֵהּ וְאַשְׁלֵם בָּתַר דַחַלְתִּי וְאַעֵלִנֵהּ לְאַרְעָא דִי עַאל לְתַמָן וּבְנוֹהִי יְתַרְכִנַהּ:
@529 וַעֲמַלְקָאָה וּכְנַעֲנָאָה יָתֵב בְּמֵישְׁרָא מְחַר אִתְפְּנוּ וְטוּלוּ לְכוֹן לְמַדְבְּרָא אוֹרַח יַמָא דְסוּף:
@530 וּמַלִיל יְיָ עִם משֶׁה וְעִם אַהֲרֹן לְמֵימָר:
@531 עַד אֵימָתַי לִכְנִשְׁתָּא בִישָׁתָא הָדָא דִי אִנוּן מִתְרַעֲמִין עָלָי יָת תֻּרְעֲמַת בְּנֵי יִשְׂרָאֵל דִי אִנוּן מִתְרַעֲמִין עֲלַי שְׁמִיעַ קֳדָמָי:
@532 אֱמַר לְהוֹן קַיָם אֲנָא אֲמַר יְיָ אִם לָא כְּמָא דִי מַלֵילְתּוּן קֳדָמָי כֵּן אֶעְבֵּד לְכוֹן:
@533 בְּמַדְבְּרָא הָדֵין יִפְּלוּן פִּגְרֵיכוֹן וְכָל מִנְיָנֵיכוֹן לְכָל חֻשְׁבַּנְכוֹן מִבַּר עַשְׂרִין שְׁנִין וּלְעֵלָא דִי אִתְרַעַמְתּוּן עֲלָי:
@534 אִם אַתּוּן תֵּעֲלוּן לְאַרְעָא דִי קַיֵמִית בְמֵימְרִי לְאַשְׁרָאָה יַתְכוֹן בַּהּ אֱלָהֵן כָּלֵב בַּר יְפֻנֶה וִיהוֹשֻׁעַ בַּר נוּן:
@535 וְטַּפְלְכוֹן דִי אֲמַרְתּוּן לְבִזָא יְהֵי וְאָעֵל יַתְהוֹן וְיֵדְעוּן יָת אַרְעָא דִי קַצְתּוּן בַּהּ:
@536 וּפִגְרֵיכוֹן דִי לְכוֹן יִפְּלוּן בְּמַדְבְּרָא הָדֵין:
@537 וּבְנֵיכוֹן יְהוֹן מְאַחֲרִין בְּמַדְבְּרָא אַרְבְּעִין שְׁנִין וִיקַבְּלוּן יָת חוֹבֵיכוֹן עַד דִיסוּפוּן פִגְרֵיכוֹן בְּמַדְבְּרָא:
@538 בְּמִנְיַן יוֹמַיָא דִי אַלֶלְתּוּן יָת אַרְעָא אַרְבְּעִין יוֹמִין יוֹמָא לְשַׁתָּא יוֹמָא לְשַּׁתָּא תְּקַבְּלוּן יָת חוֹבֵיכוֹן אַרְבְּעִין שְׁנִין וְתִדְעוּן יָת דְאִתְרַעַמְתּוּן עֲלָי:
@539 אֲנָא יְיָ גְזָרִית בְּמֵימְרִי אִם לָא דָא אֶעְבֵּד לְכָל כְּנִשְׁתָּא בִישְׁתָא הָדָא דְאִזְדַמְנוּ עֲלָי בְּמַדְבְּרָא הָדֵין יְסוּפוּן וְתַמָן יְמוּתוּן:
@540 וְגֻבְרַיָא דִי שְׁלַח משֶׁה לְאַלָלָא יָת אַרְעָא וְתָבוּ וְאַרְעִימוּ עֲלוֹהִי יָת כָּל כְּנִשְׁתָּא לְאַפָּקָא שׁוּם בִּישׁ עַל אַרְעָא:
@541 וּמִיתוּ גֻבְרַיָא דְאַפִּיקוּ שׁוּם בִּישׁ עַל אַרְעָא בְּמוֹתָנָא קֳדָם יְיָ:
@542 וִיהוֹשֻׁעַ בַּר נוּן וְכָלֵב בַּר יְפֻנֶה אִתְקַיְימוּ מִן גֻבְרַיָא הָאִנוּן דַאֲזָלוּ לְאַלָלָא יָת אַרְעָא:
@543 וּמַלִיל משֶׁה יָת פִּתְגָמַיָא הָאִלֵין לְכָל בְּנֵי יִשְׂרָאֵל וְאִתְאַבָּלוּ עַמָא לַחֲדָא:
@544 וְאַקְדִימוּ בְצַפְרָא וּסְלִיקוּ לְרֵישׁ טוּרָא לְמֵימָר הָא אֲנַחְנָא סָלְקִין לְאַתְרָא דִי אֲמַר יְיָ אֲרֵי חַבְנָא:
@545 וַאֲמַר משֶׁה לְמָא דְנַן אַתּוּן עָבְרִין עַל גְזֵרַת מֵימְרָא דַיְיָ וְהִיא לָא תַצְלָח:
@546 לָא תִסְקוּן אֲרֵי לֵית שְׁכִנְתָּא דַיְיָ בֵּינֵיכוֹן וְלָא תִתַּבְּרוּן קֳדָם בַּעֲלֵי דְבָבֵיכוֹן:
@547 אֲרֵי עֲמַלְקָאָה וּכְנַעֲנָאָה תַמָן קֳדָמֵיכוֹן וְתִפְּלוּן בְּחַרְבָּא אֲרֵי עַל כֵּן תַּבְתּוּן מִבָּתַר פּוּלְחָנָא דַיְיָ וְלָא יְהֵי מֵימְרָא דַיְיָ בְּסַעְדְכוֹן:
@548 וְאַרְשָׁעוּ לְמִסַק לְרֵישׁ טוּרָא וַאֲרוֹן קְיָמָא דַיְיָ וּמשֶׁה לָא עֲדוֹ מִגוֹ מַשְׁרִיתָא:
@549 וּנְחַת עֲמַלְקָאָה וּכְנַעֲנָאָה דְיָתֵב בְּטוּרָא הַהוּא וּמְחֻנוּן וּטְרָדֻנוּן עַד חָרְמָה:
@550 וּמַלִיל יְיָ עִם משֶׁה לְמֵימָר:
@551 מַלֵל עִם בְּנֵי יִשְׂרָאֵל וְתֵימַר לְהוֹן אֲרֵי תֵעֲלוּן לַאֲרַע מוֹתְבָנֵיכוֹן דִי אֲנָא יָהֵב לְכוֹן:
@552 וְתַעְבְּדוּן קֻרְבָּנָא קָדָם יְיָ עֲלָתָא אוֹ נִכְסַת קוּדְשַׁיָא לְאַפְרָשָׁא נִדְרָא אוֹ בִנְדַבְתָּא אוֹ בְּמוֹעֲדֵיכוֹן לְמֶעְבַּד לְאִתְקַבָּלָא בְרַעֲוָא קֳדָם יְיָ מִן תּוֹרֵי אוֹ מִן עָנָא:
@553 וִיקָרֵב דִמְקָרֵב קֻרְבָּנֵהּ קֳדָם יְיָ מִנְחָתָא סֻלְתָּא עַשְׂרוֹנָא דְפִילָא בְּרַבְעוּת הִינָא מִשְׁחָא:
@554 וְחַמְרָא לְנִסְכָּא רַבְעוּת הִינָא תַּעְבֵּד עַל עֲלָתָא אוֹ לְנִכְסַת קוּדְשַׁיָא לְאִמְרָא חָד:
@555 אוֹ לְדִכְרָא תַּעְבֵּד מִנְחָתָא סֻלְתָּא תְּרֵין עַשְׂרוֹנִין דְפִילָא בִמְשַׁח תַּלְתּוּת הִינָא:
@556 וְחַמְרָא לְנִסְכָּא תַּלְתּוּת הִינָא תְּקָרֵב לְאִתְקַבָּלָא בְרַעֲוָא קֳדָם יְיָ:
@557 וַאֲרֵי תַעְבֵּד בַּר תּוֹרֵי עֲלָתָא אוֹ נִכְסַת קוּדְשַּׁיָא לְפָרָשָׁא נִדְרָא אוֹ נִכְסַת קוּדְשַׁיָא קֳדָם יְיָ:
@558 וִיקָרֵב עַל בַּר תּוֹרֵי מִנְחָתָא סֻלְתָּא תְּלָתָא עַשְׂרוֹנִין דְפִילָא בִמְשַׁח פַּלְגוּת הִינָא:
@559 וְחַמְרָא תְּקָרֵב לְנִסְכָּא פַּלְגוּת הִינָא קֻרְבַּן דְמִתְקַבֵּל בְּרַעֲוָא קֳדָם יְיָ:
@560 כְּדֵין יִתְעֲבֵיד לְתוֹרָא חַד אוֹ לְּדִכְרָא חָד אוֹ לְאִמַר בְּאִמְרַיָא אוֹ בְעִזַיָא:
@561 כְּמִנְיָן דִי תַעְבְּדוּן כְּדֵין תַּעְבְּדוּן לְחַד כְּמִנְיָנֵהוֹן:
@562 כָּל יַצִיבָא יַעְבֵּד כְדֵין יָת אִלֵין לְקָרָבָא קֻרְבַּן דְמִתְקַבֵּל בְּרַעֲוָא קֳדָם יְיָ:
@563 וַאֲרֵי יִתְגַיַר עִמְכוֹן גִיוֹרָא אוֹ דִי בֵינֵיכוֹן לְדָרֵיכוֹן וְיַעְבֵּד קֻרְבַּן דְמִתְקַּבֵּל בְּרַעֲוָא קֳדָם יְיָ כְּמָא דִי תַעְבְּדוּן כֵּן יַעְבֵּד:
@564 קְהָלָא קְיָמָא חַד לְכוֹן וּלְגִיוֹרָא דְיִתְגַיָר קְיַם עָלָם לְדָרֵיכוֹן כְּוַתְכוֹן כְּגִיוֹרָא יְהֵי:קָדָם יְיָ:
@565 אוֹרַיְתָא חֲדָא וְדִינָא חַד יְהֵי לְכוֹן וּלְגִיוֹרָא דְיִתְגַיַר עִמְכוֹן:
@566 וּמַלִיל יְיָ עִם משֶׁה לְמֵימָר:
@567 מַלֵל עִם בְּנֵי יִשְׂרָאֵל וְתֵימַר לְהוֹן בְּמֵעַלְכוֹן לְאַרְעָא דִי אֲנָא מָעֵל יָתְכוֹן לְתַמָן:
@568 וִיהֵי בְמֵיכַלְכוֹן מִלַחְמָא דְאַרְעָא תַּפְרְשׁוּן אַפְרָשׁוּתָא קֳדָם יְיָ:
@569 רֵישׁ אַצְוַתְכוֹן חַלְתָא תַּפְרְשׁוּן אַפְרָשׁוּתָא כְּמָא דִי מַפְרְשִׁין מִן אִדְרָא כֵּן תַּפְרְשׁוּן יָתַהּ:
@570 מֵרֵישׁ אַצְוַתְכוֹן תִּתְּנוּן קֳדָם יְיָ אַפְרָשׁוּתָא לְדָרֵיכוֹן:
@571 וַאֲרֵי תִשְׁתְּלוּן וְלָא תַעְבְּדוּן יָת כָּל פִּקוֹדַיָא הָאִלֵין דִי מַלִיל יְיָ עִם משֶׁה:
@572 יָת כָּל דִי פַקִיד יְיָ יָתְכוֹן בִּידָא דְמשֶׁה מִן יוֹמָא דִי פָקִיד יְיָ וּלְהָלָא לְדָרֵיכוֹן:
@573 וִיהֵי אִם מֵעֵינֵי כְנִשְׁתָּא אִתְעֲבִדַת לְשָׁלוּ וְיַעְבְּדוּן כָּל כְּנִשְׁתָּא תּוֹר בַּר תּוֹרֵי חַד לַעֲלָתָא לְאִתְקַבָּלָא בְרַעֲוָא קֳדָם יְיָ וּמִנְחָתֵהּ וְנִסְכֵּהּ כִּדְחָזֵי וּצְפִיר בַּר עִזֵי חַד לְחַטָּאתָא:
@574 וִיכַפַּר כַּהֲנָא עַל כָּל כְּנִשְׁתָּא דִבְנֵי יִשְׂרָאֵל וְיִשְׁתְּבֵק לְהוֹן אֲרֵי שָׁלוּתָא הִיא וְאִנוּן אַיְתִיאוּ יָת קֻרְבַּנְהוֹן קֻרְבָּנָא קֳדָם יְיָ וְחוֹבַתְהוֹן קֳדָם יְיָ עַל שָׁלוּתְהוֹן:
@575 וְיִשְׁתְּבֵק לְכָל כְּנִשְׁתָּא דִבְנֵי יִשְׂרָאֵל וּלְגִיוֹרָא דְיִתְגַיַר בֵּינֵיהוֹן אֲרֵי לְכָל עַמָא בְּשָׁלוּתָא:
@576 וְאִם אֱנַשׁ חַד יֵחוֹב בְּשָׁלוּ וִיקָרֵב עִזָא בַּת שַׁתַּהּ לְחַטָאתָא:
@577 וִיכַפַּר כַּהֲנָא עַל אֱנַשׁ דְאִשְׁתְּלֵי בְּמֵחֲבֵהּ בְּשָׁלוּ קֳדָם יְיָ לְכַפָּרָא עֲלוֹהִי וְיִשְׁתְּבֵק לֵהּ:
@578 יַצִיבָא בִּבְנֵי יִשְׂרָאֵל וּלְגִיוֹרָא דְיִתְגַיַר בֵּינֵיהוֹן אוֹרַיְתָא חֲדָא יְהֵי לְכוֹן לִדְיַעְבֵּד בְּשָׁלוּ:
@579 וֶאֱנַשׁ דְיַעְבֵּד בְּרֵישׁ גְלֵי מִן יַצִיבַיָא וּמִן גִיוֹרַיָא קֳדָם יְיָ הוּא מַרְגֵז וְיִשְׁתֵּצֵי אֲנָשָׁא הַהִיא מִגוֹ עַמֵהּ:
@580 אֲרֵי עַל מֵימְרָא דַיְיָ בְּסַר וְיָת פִּקוּדוֹהִי אַשְׁנֵי אִשְׁתֵּצָאָה תִשְׁתֵּצֵי אֲנָשָׁא הַהִיא חוֹבֵיהּ בֵּיהּ:
@581 וַהֲווֹ בְנֵי יִשְׂרָאֵל בְּמַדְבְּרָא וְאַשְׁכָּחוּ גַבְרָא כַּד מְגַבֵּב אָעִין בְּיוֹמָא דְשַׁבְּתָא:
@582 וְקָרִיבוּ יָתֵהּ דְאַשְׁכַּחוּ יָתֵהּ כַּד מְגַבֵּב אָעִין לְוָת משֶׁה וּלְוָת אַהֲרֹן וּלְוָת כָּל כְּנִשְׁתָּא:
@583 וַאֲסָרוּ יָתֵהּ בְּבֵית מַטְרָא אֲרֵי לָא אִתְפְּרֵשׁ לְהוֹן מָה דְיַעֲבְּדוּן לֵהּ:
@584 וַאֲמַר יְיָ לְמשֶׁה אִתְקְטָלָא יִתְקְטֵל גַבְרָא רְגוּמוּ יָתֵיהּ בְּאַבְנַיָא כָּל כְּנִשְׁתָּא מִבָּרָא לְמַשְׁרִיתָא:
@585 וְאַפִּיקוּ יָתֵיהּ כָּל כְּנִשְׁתָּא לְמִבָּרָא לְמַשְׁרִיתָא וּרְגָמוּ יָתֵהּ בְּאַבְנַיָא וּמִית כְּמָא דִי פַקִיד יְיָ יָת משֶׁה:
@586 וַאֲמַר יְיָ לְמשֶׁה לְמֵימָר:
@587 מַלֵל עִם בְּנֵי יִשְׂרָאֵל וְתֵימַר לְהוֹן וְיַעֲבְּדוּן לְהוֹן כְּרוּסְפְּדִין עַל כַּנְפֵי כְסוּתְהוֹן לְדָרֵיהוֹן וְיִתְּנוּן עַל כְּרוּסְפְּדָא דְכַנְפָא חוּטָא דִתְכֶלְתָּא:
@588 וִיהוֹן לְכוֹן לִכְרוּסְפְּדִין וְתֶחֱזוּן יָתֵיהּ וְתִדְכְּרוּן יָת כָּל פִּקוּדַיָא דַיְיָ וְתַעְבְּדוּן יָתְהוֹן וְלָא תִטְעוּן בָּתַר הִרְהוּר לִבְּכוֹן וּבָתַר חֵיזוּ עֵינֵיכוֹן דִי אַתּוּן טָּעַן בַּתְרֵיהוֹן:
@589 בְּדִיל דְתִדְכְּרוּן וְתַעְבְּדוּן יָת כָּל פִּקוּדָי וּתְהוֹן קַדִישִׁין קֳדָם אֱלָּהָכוֹן:
@590 אֲנָא יְיָ אֱלָהָכוֹן דִי אַפֵּקִית יָתְכוֹן מֵאַרְעָא דְמִצְרַיִם לְמֵהֲוֵי לְכוֹן לֶאֱלָהָא אֲנָא יְיָ אֱלָהָכוֹן: פפפ:
@591 וְאִתְפְּלֵג קֹרַח בַּר יִצְהָר בַּר קְהָת בַּר לֵוִי וְדָתָן וַאֲבִירָם בְּנֵי אֱלִיאָב וְאוֹן בַּר פֶּלֶת בְּנֵי רְאוּבֵן:
@592 וְקָמוּ לְאַפֵּי משֶׁה וְגֻבְרַיָא מִבְּנֵי יִשְׂרָאֵל מָאתָן וְחַמְשִׁין רַבְרְבֵי כְנִשְׁתָּא מְעַרְעֵי זְמַן אֱנָשִׁין דִשְׁמָא:
@593 וְאִתְכְּנָשׁוּ עַל משֶׁה וְעַל אַהֲרֹן וַאֲמָרוּ לְהוֹן סַגִי לְכוֹן אֲרֵי כָל כְּנִשְׁתָּא כֻּלְהוֹן קַדִישִׁין וּבֵינֵיהוֹן שַׁרְיָא שְׁכִנְתָּא דַיְיָ וּמָא דֵין אַתּוּן מִתְרַבְרְבִין עַל קְהָלָא דַיְיָ:
@594 וּשְׁמַע משֶׁה וּנְפַל עַל אַפּוֹהִי:
@595 וּמַלִיל עִם קֹרַח וְעִם כָּל כְּנִשְׁתֵּהּ לְמֵימַר בְּצַפְרָא וִיהוֹדַע יְיָ יָת דְכָשַׁר לֵהּ וְיָת דְקַדִישׁ וִיקָרֵב לָקֳדָמוֹהִי וְיָת דִי יִתְרְעֵי בֵהּ יְקָרֵב לְשִׁמוּשֵׁהּ:
@596 דָא עַבִידוּ סָבוּ לְכוֹן מַחְתְּיָן קֹרַח וְכָל כְּנִשְׁתֵּהּ:
@597 וְהָבוּ בְהוֹן אֵשָׁתָא וְשַׁוִיאוּ עֲלֵיהוֹן קְטוֹרֶת בּוּסְמִין קֳדָם יְיָ מְחַר וִיהֵי גַבְרָא דְיִתְרְעֵי יְיָ הוּא קַדִישּׁ סַגִי לְכּוֹן בְּנֵי לֵוִי:
@598 וַאֲמַר משֶׁה לְקֹרַח שְׁמָעוּ כְעַן בְּנֵי לֵוִי:
@599 הַזְעֵר לְכוֹן אֲרֵי אַפְרֵשׁ אֱלָהָא דְיִשְׂרָאֵל יָתְכוֹן מִכְּנִשְׁתָּא דְיִשְׂרָאֵל לְקֳרָבָא יָתְכוֹן קֳדָמוֹהִי לְמִפְלַח יָת פּוּלְחַן מַשְׁכְּנָא דַיְיָ וּלְמֵקַם קֳדָם כְּנִשְׁתָּא לְשַׁמָשׁוּתְהוֹן:
@600 וְקָרֵב יָתָךְ וְיַת כָּל אֲחָךְ בְּנֵי לְוֵי עִמָךְ וּכְעַן אַתּוּן בָּעָן אַף כְּהוּנְתָא רַבְּתָא:
@601 בְּכֵן אַתְּ וְכָל כְּנִשְׁתָּךְ דְאִזְדַמַנְתּוּן עַל יְיָ וְאַהֲרֹן מַה הוּא אֲרֵי אִתְרַעַמְתּוּן עֲלוֹהִי:
@602 וּשְׁלַח משֶׁה לְמִקְרֵי לְדָתָן וְלַאֲבִירָם בְּנֵי אֱלִיאָב וַאֲמָרוּ לָא נִסָק:
@603 הַזְעֵיר אֲרֵי אַסֵקְתָּנָא מֵאַרְעָא עָבְדָא חֲלַב וּדְבָשׁ לְקַטָלוּתָנָא בְּמַדְבְּרָא אֲרֵי אִתְרַבְרַבְתְּ עֲלָנָא אַף אִתְרַבְרָבָא:
@604 בְּרַם לָא לְאַרְעָא עָבְדָא חֲלָב וּדְבָשׁ אַעֵלְתָּנָא וִיהַבְתְּ לָנָא אַחֲסָנַת חַקְלִין וְכַרְמִין הַעֵינֵי גֻבְרַיָא הָאִינוּן תְּשַׁלַח לְעַוָרָא לָא נִסָק:
@605 וּתְקֵף לְמשֶׁה לַחֲדָא וַאֲמַר קֳדָם יְיָ לָא תְקַבֵּל בְּרַעֲוָא קוּרְבַּנְהוֹן לָא חֲמָרָא דְחַד מִנְהוֹן שְׁחָרִית וְלָא אַבְאֵישִׁית יַת חָד מִנְהוֹן:
@606 וַאֲמַר משֶׁה לְקֹרַח אַתְּ וְכָל כְּנִשְׁתָּךְ הֱווֹ זְמִינִין לָקֳדָם יְיָ אַתְּ וְאִינוּן וְאַהֲרֹן מְחָר:
@607 וּסְבוּ גְבַר מַחְתִּיתֵיהּ וּתְשַׁווּן עֲלֵיהוֹן קְטוֹרֶת בּוּסְמִין וְתִקָרְבוּן קֳדָם יְיָ גְבַר מַחְתִּיתֵיהּ מָאתָן וְחַמְשִׁין מַחְתְּיָן וְאַתְּ וְאַהֲרֹן גְבַר מַחְתִּיתֵהּ:
@608 וּנְסִיבוּ גְבַר מַחְתִּיתֵהּ וִיהָבוּ עֲלֵיהוֹן אֵשָׁתָא וְשַׁוִיאוּ עֲלֵיהוֹן קְטֹרֶת בּוּסְמִין וְקָמוּ בִּתְרַע מַשְׁכַּן זִמְנָא וּמשֶׁה וְאַהֲרֹן:
@609 וְאַכְנֵשׁ עֲלֵיהוֹן קֹרַח יָת כָּל כְּנִשְׁתָּא לִתְרַע מַשְׁכַּן זִמְנָא וְאִתְגְלֵי יְקָרָא דַיְיָ לְכָל כְּנִשְׁתָּא:
@610 וּמַלֵיל יְיָ עִם משֶׁה וְעִם אַהֲרֹן לְמֵימָר:
@611 אִתְפְּרָשׁוּ מִגוֹ כְּנִשְׁתָּא הָדָא וֶאֱשֵׁיצֵי יַתְהוֹן כְּשָׁעָה:
@612 וּנְפָלוּ עַל אַפֵּיהוֹן וַאֲמָרוּ אֵל אֱלָהָא רוּחַיָא לְכָל בִּשְׂרָא גַבְרָא חָד יֵיחוֹב וְעַל כָּל כְּנִשְׁתָּא יְהֵי רוּגְזָא:
@613 וּמַלֵיל יְיָ עִם משֶׁה לְמֵימָר:
@614 מַלֵל עִם כְּנִשְׁתָּא לְמֵימָר אִסְתַּלָקוּ מִסְחוֹר סְחוֹר לְמַשְׁכְּנָא דְקֹרַח דָתָן וַאֲבִירָם:
@615 וְקָם משֶׁה וַאֲזַל לְוַת דָתָן וַאֲבִירָם וַאֲזָלוּ בַּתְרוֹהִי סָבֵי יִשְׂרָאֵל:
@616 וּמַלֵיל עִם כְּנִשְׁתָּא לְמֵימָר זוּרוּ כְעַן מֵעִלַוֵי מַשְׁכְּנֵי גֻבְרַיָא חַיָיבַיָא הָאִלֵין וְלָא תְקָרְבוּן בְּכָל דִי לְהוֹן דִלְמָא תִלְקוּן בְּכָל חוֹבֵיהוֹן:
@617 וְאִסְתַּלָקוּ מֵעִלַוֵי מַשְׁכְּנָא דְקֹרַח דָתָן וַאֲבִירָם מִסְחוֹר סְחוֹר וְדָתָן וַאֲבִירָם נְפָקוּ קַיְימִין בִּתְרַע מַשְׁכְּנֵיהוֹן וּנְשֵׁיהוֹן וּבְנֵיהוֹן וְטַפְלְהוֹן:
@618 וַאֲמַר משֶׁה בְּדָא תִדְעוּן אֲרֵי יְיָ שַׁלְחַנִי לְמֶעְבַּד יָת כָּל עוֹבָדַיָא הָאִלֵין אֲרֵי לָא מֵרְעוּתִי:
@619 אִם כְּמוֹתָא דְכָל אֱנָשָׁא יְמוּתוּן אִלֵין וּסְעָרָא דְכָל אֱנָשָׁא יִסְתְּעַר עֲלֵיהוֹן לָא יְיָ שַׁלְחַנִי:
@620 וְאִם בְּרִיאָה יִבְרֵי יְיָ וּפְתָחַת אַרְעָא יָת פּוּמַהּ וְתִבְלַע יַתְהוֹן וְיַת כָּל דִי לְהוֹן וְיֶחֱתוּן כַּד חַיִין לִשְׁאוֹל וְתִדְעוּן אֲרֵי אַרְגִיזוּ גוּבְרַיָא הָאִלֵין קֳדָם יְיָ:
@621 וַהֲוָה כַּד שֵׁיצֵי לְמַלָלָא יָת כָּל פִּתְגָמַיָא הָאִלֵין וְאִתְבְּזָעַת אַרְעָא דִי תְּחוֹתֵיהוֹן:
@622 וּפְתָחַת אַרְעָא יָת פּוּמָהּ וּבְלָעַת יַתְהוֹן וְיַת אֱנַשׁ בָּתֵּיהוֹן וְיַת כָּל אֱנָשָׁא דִי לְקֹרַח וְיַת כָּל קִנְיָנָא:
@623 וּנְחָתוּ אִינוּן וְכָל דִי לְהוֹן כַּד חַיִין לִשְׁאוֹל וַחֲפַת עֲלֵיהוֹן אַרְעָא וַאֲבָדוּ מִגוֹ קְהָלָא:
@624 וְכָל יִשְׂרָאֵל דִי בְסַחֲרָנֵיהוֹן עֲרָקוּ לְקַלְהוֹן אֲרֵי אֲמָרוּ דִלְמָא תִבְלְעִנָנָא אַרְעָא:
@625 וְאֶשָׁתָא נְפָקַת מִן קֳדָם יְיָ וַאֲכָלַת יָת מָאתָן וְחַמְשִׁין גַבְרָא מְקַרְבֵי קְטוֹרֶת בּוּסְמַיָא:
@626 וּמַלֵיל יְיָ עִם משֶׁה לְמֵימָר:
@627 אֱמַר לְאֶלְעָזָר בַּר אַהֲרֹן כַּהֲנָא וְיַפְרֵשׁ יָת מַחְתְּיָתָא מִבֵּין יְקִידַיָא וְיָת אֶשָׁתָא יַרְחִיק לְהָלָא אֲרֵי אִתְקַדָשׁוּ:
@628 יָת מַחְתְּיַת חַיָיבַיָא הָאִלֵין דְאִתְחַיְיבוּ בְּנַפְשָׁתֵיהוֹן וְיַעְבְּדוּן יַתְהוֹן טַסִין רְדִידִין חוֹפָאָה לְמַדְבְּחָא אֲרֵי קָרֵבֻנוּן קֳדָם יְיָ וְאִתְקַדָשׁוּ וִיהֶוְיָן לְאָת לִבְּנֵי יִשְׂרָאֵל:
@629 וּנְסִיב אֶלְעָזָר כַּהֲנָא יָת מַחְתְּיָתָא דִנְחָשָׁא דְקָרִיבוּ יוֹקִידַיָא וְרַדִידֻנוּן חוֹפָאָה לְמַדְבְּחָא:
@630 דָכְרָנָא לִבְנֵי יִשְׂרָאֵל בְּדִיל דִי לָא יִקְרַב גְבַר חִלוֹנַי דִי לָא מִזַרְעָא דְאַהֲרֹן הוּא לְאַסָקָא קְטוֹרֶת בּוּסְמִין קֳדָם יְיָ וְלָא יְהֵי כְקֹרַח וְכִכְנִשְׁתֵּיהּ כְּמָא דִי מַלֵיל יְיָ בִּידָא דְמשֶׁה לֵיהּ:
@631 וְאִתְרַעֲמוּ כָּל כְּנִשְׁתָּא דִבְנֵי יִשְׂרָאֵל מִיוֹמָא דְבַתְרוֹהִי עַל משֶׁה וְעַל אַהֲרֹן לְמֵימָר אַתּוּן גְרַמְתּוּן דְמִית עַמָא דַיְיָ:
@632 וַהֲוָה בְּאִתְכַּנָשׁוּת כְּנִשְׁתָּא עַל משֶׁה וְעַל אַהֲרֹן וְאִתְפְּנִיאוּ לְמַשְׁכַּן זִמְנָא וְהָא חֲפָהִי עֲנָנָא וְאִתְגְלִי יְקָרָא דַיְיָ:
@633 וְעָאל משֶׁה וְאַהֲרֹן לָקֳדָם מַשְׁכַּן זִמְנָא:
@634 וּמַלֵיל יְיָ עִם משֶׁה לְמֵימָר:
@635 אִתְפְרָשׁוּ מִגוֹ כְּנִשְׁתָּא הָדָא וְאֱשֵׁיצֵי יָתְהוֹן כְּשָׁעָה וּנְפָלוּ עַל אַפֵּיהוֹן:
@636 וַאֲמַר משֶׁה לְאַהֲרֹן סַב יָת מַחְתִּיתָא וְהַב עֲלַהּ אֶשָׁתָא מֵעִלָוֵי מַדְבְּחָא וְשַׁו קְטוֹרֶת בּוּסְמַיָא וְאוֹבִיל בִּפְרִיעַ לִכְנִשְׁתָּא וְכַפֵּר עֲלֵיהוֹן אֲרֵי נְפַק רָגְזָא מִן קֳדָם יְיָ שָׁרֵי מוֹתָנָא:
@637 וּנְסֵיב אַהֲרֹן כְּמָא דְמַלֵיל משֶׁה וּרְהַט לְגוֹ קְהָלָא וְהָא שָׁרֵי מוֹתָנָא בְּעַמָא וִיהַב יָת קְטּוֹרֶת בּוּסְמַיָא וְכַפֵּר עַל עַמָא:
@638 וְקָם בֵּין מֵתַיָא וּבֵין חַיַיָא וְאִתְכְּלִי מוֹתָנָא:
@639 וַהֲווֹ דְמִיתוּ בְּמוֹתָנָא אַרְבַּעַת עֲשַׂר אַלְפִין וּשְׁבַע מְאָה בַּר מִדְמִיתוּ עַל פְּלֻגְתָּא דְקֹרַח:
@640 וְתָב אַהֲרֹן לְמשֶׁה לִתְרַע מַשְׁכַּן זִמְנָא וּמוֹתָנָא אִתְכְּלִי:
@641 וּמַלֵיל יְיָ עִם משֶׁה לְמֵימָר:
@642 מַלֵיל עִם בְּנֵי יִשְׂרָאֵל וְסַב מִנְהוֹן חוּטְרָא חוּטְרָא לְבֵית אַבָּא מִן כָּל רַבְרְבָנֵיהוֹן לְבֵית אֲבָהַתְהוֹן תְּרֵי עֲשַׂר חוּטְרִין גְבַר יָת שְׁמֵיהּ תִּכְתּוֹב עַל חוּטְרֵיהּ:
@643 וְיָת שְׁמָא דְאַהֲרֹן תִּכְתּוֹב עַל חוּטְרָא דְלֵוִי אֲרֵי חוּטְרָא חָד לְרֵישׁ בֵּית אֲבָהַתְהוֹן:
@644 וְתַצְנְעִינוּן בְּמַשְׁכַּן זִמְנָא קֳדָם סַהֲדוּתָא דִי אֲזַמִין מֵימְרִי לְכוֹן תַּמָן:
@645 וִיהֵי גַבְרָא דִי אִתְרְעֵי בֵּהּ חוּטְרֵיהּ יִנְעֵי וַאֲנִיחַ מִן קֳדָמַי יָת תּוּרְעֲמַת בְּנֵי יִשְׂרָאֵל דִי אִנוּן מִתְרַעֲמִין עֲלֵיכוֹן:
@646 וּמַלֵיל משֶׁה עִם בְּנֵי יִשְׂרָאֵל וִיהָבוּ לֵיהּ כָּל רַבְרְבָנֵיהוֹן חוּטְרָא לְרַבָּא חָד חוּטְרָא לְרַבָּא חָד לְבֵית אֲבָהַתְהוֹן תְּרֵי עֲשַׂר חוּטְרִין וְחוּטְרָא דְאַהֲרֹן בְּגוֹ חוּטְרֵיהוֹן:
@647 וְאַצְנַע משֶׁה יָת חוּטְּרַיָא קֳדָם יְיָ בְּמַשְׁכְּנָא דְסַהֲדוּתָא:
@648 וַהֲוָה בְּיוֹמָא דְבַתְרוֹהִי וְעַאל משֶׁה לְמַשְׁכְּנָא דְסַהֲדוּתָא וְהָא נְעָא חוּטְרָא דְאַהֲרֹן לְבֵית לְוֵי וְאַפֵּק לַבְלְבִין וְאָנֵץ נֵץ וְכָפֵית שִׁיגְדִין:
@649 וְאַפֵיק משֶׁה יָת כָּל חוּטְרַיָא מִן קֳדָם יְיָ לְוָת כָּל בְּנֵי יִשְׂרָאֵל וְאִשְׁתְּמוֹדָעוּ וּנְסִיבוּ גְבַר חוּטְרֵיהּ:
@650 וַאֲמַר יְיָ לְמשֶׁה אָתֵיב יַת חוּטְרָא דְאַהֲרֹן לְקֳדָם סַהֲדוּתָא לְמַטָרָא לְאָת לְעַמָא סַרְבָנָא וִיסוּפַן תּוּרְעֲמַתְהוֹן מִן קֳדָמַי וְלָא יְמוּתוּן:
@651 וַעֲבַד משֶׁה כְּמָא דִי פַקֵיד יְיָ יָתֵיה כֵּן עֲבָד:
@652 וַאֲמָרוּ בְּנֵי יִשְׂרָאֵל לְמשֶׁה לְמֵימָר הָא מִנָנָא קְטָלַת חַרְבָּא הָא מִנָנָא בְּלָעַת אַרְעָא וְהָא מִנָנָא דְמִיתוּ בְמוֹתָנָא:
@653 כֹּל דְקָרֵב מִקְרַב לְמַשְׁכְּנָא דַיְיָ מָאִית הָא אַנַחְנָא סַיְפִין לִמְמָת:
@654 וַאֲמַר יְיָ לְאַהֲרֹן אַתְּ וּבְנָךְ וּבֵית אֲבוּךְ עִמָךְ תְּסַלְחוּן עַל חוֹבֵי מַקְדְשָׁא וְאַתְּ וּבְנָךְ עִמָךְ תְּסַלְחוּן עַל חוֹבֵי כְּהוּנַתְכוֹן:
@655 וְאַף יָת אֲחָיךְ שִׁבְטָא דְלֵוִי שִׁבְטָא דַאֲבוּךְ קָרֵיב לְוָתָךְ וְיִתּוֹסְפוּן עֲלָךְ וִישַׁמְשׁוּנָךְ וְאַתְּ וּבְנָךְ עִמָךְ קֳדָם מַשְׁכְּנָא דְסַהֲדוּתָא:
@656 וְיִטְרוּן מַטַרְתָּךְ וּמַטְרַת כָּל מַשְׁכְּנָא בְּרַם לְמָנֵי קוּדְשָׁא וּלְמַדְבְּחָא לָא יִקְרְבוּן וְלָא יְמוּתוּן אַף אִינוּן אַף אַתּוּן:
@657 וְיִתּוֹסְפוּן עֲלָךְ וְיִטְרוּן יָת מַטְרַת מַשְׁכַּן זִמְנָא לְכָל פּוּלְחַן מַשְׁכְּנָא וְחִילוֹנֵי לָא יִקְרַב לְוָתְכוֹן:
@658 וְתִטְרוּן יָת מַטְרַת קוּדְשָׁא וְיָת מַטְרַת מַדְבְּחָא וְלָא יְהֵי עוֹד רוּגְזָא עַל בְּנֵי יִשְׂרָאֵל:
@659 וַאֲנָא הָא קְרֵיבִית יָת אֲחֵיכוֹן לֵוָאֵי מִגוֹ בְּנֵי יִשְׂרָאֵל לְכוֹן מַתְּנָא יְהִיבִין קֳדָם יְיָ לְמִפְלַח יָת פּוּלְחַן מַשְׁכַּן זִמְנָא:
@660 וְאַתְּ וּבְנָךְ עִמָךְ תִּטְרוּן יָת כְּהוּנַתְכוֹן לְכָל פִּתְגַם מַדְבְּחָא וּלְמִגָיו לְפָרוּכְתָּא וְתִפְלְחוּן פוּלְחַן מַתְּנָא אֵיהַב יָת כְּהוּנַתְכוֹן וְחִילוֹנֵי דְיִקְרַב יִתְקְטֵיל:
@661 וּמַלֵיל יְיָ עִם אַהֲרֹן וַאֲנָא הָא יְהָבִית לָךְ יָת מַטְרַת אַפְרָשׁוּתָי לְכָל קוּדְשַׁיָא דִבְנֵי יִשְׂרָאֵל לָךְ יְהַבְתִּינוּן לִרְבוּ וְלִבְנָךְ לִקְיָם עֲלָם:
@662 דֵין יְהֵי לָךְ מִקוֹדֶשׁ קוּדְשַׁיָא מוֹתַר מִן אֶשָׁתָא כָּל קוּרְבַּנְהוֹן לְכָל מִנְחַתְהוֹן וּלְכָל חַטְוַתְהוֹן וּלְכָל אֲשַׁמְהוֹן דִי יְתִיבוּן קֳדָמַי קוֹדֶשׁ קוּדְשִׁין דִילָךְ הִיא וְלִבְנָךְ:
@663 בְּקֹדֶשׁ קוּדְשִׁין תֵּיכְלוּנֵיהּ כָּל דְכוּרָא יֵיכוֹל יָתֵיהּ קוּדְשָׁא יְהֵי לָךְ:
@664 וְדֵין לָךְ אַפְרָשׁוּת מַתְּנַתְהוֹן לְכָל אֲרָמוּת בְּנֵי יִשְׂרָאֵל לָךְ יְהַבְתִּינוּן וְלִבְנָיךְ וְלִבְנְתָיךְ עִמָךְ לִקְיַם עֲלָם כָּל דִדְכֵי בְּבֵיתָךְ יֵיכוֹל יָתֵיהּ:
@665 כָּל טוּב מְשַׁח וְכָל טוּב חֲמַר וְעִבּוּר רֵאשִׁיתְהוֹן דִי יִתְּנוּן קֳדָם יְיָ לָךְ יְהַבְתִּינוּן:
@666 בִּכּוּרֵי כָּל דִי בְאַרְעֲהוֹן דִי יַיְתוּן קֳדָם יְיָ דִילָךְ יְהֵי כָּל דִדְכֵי בְּבֵיתָךְ יֵיכְלִנֵיהּ:
@667 כָּל חֶרְמָא בְּיִשְׂרָאֵל דִילָךְ יְהֵי:
@668 כָּל פְּתַח וַלְדָא לְכָל בִּשְׂרָא דִי יְקָרְבוּן קֳדָם יְיָ בֶּאֱנָשָׁא וּבִבְעִירָא יְהֵי לָךְ בְּרַם מִפְרַק תִּפְרוֹק יָת בּוּכְרָא דֶאֱנָשָׁא וְיָת בּוּכְרָא דִבְעִירָא מְסַאֲבָא תִּפְרוֹק:
@669 וּפוּרְקָנֵיהּ מִבַּר יַרְחָא תִּפְרוֹק בְּפוּרְסָנֵיהּ כְּסַף חַמְשָׁא סִלְעִין בְּסִלְעֵי קוּדְשָׁא עַשְׂרִין מָעִין הוּא:
@670 בְּרַם בּוּכְרָא דְתוֹרָא אוֹ בּוּכְרָא דְאִמְרָא אוֹ בּוּכְרָא דְעִזָא לָא תִפְרוֹק קוּדְשָׁא אִינוּן יָת דִמְהוֹן תִּזְרוֹק עַל מַדְבְּחָא וְיָת תַּרְבְּהוֹן תַּסֵיק קוּרְבַּן לְאִתְקַבָּלָא בְּרַעֲוָא קֳדָם יְיָ:
@671 וּבִשְׂרְהוֹן יְהֵי לָךְ כְּחַדְיָא דַאֲרָמוּתָא וּכְשַׁקָא דְיַמִינָא דִילָךְ יְהֵי:
@672 כָּל אַפְרָשׁוּת קוּדְשַׁיָא דִי יִפְרְשׁוּן בְּנֵי יִשְׂרָאֵל קֳדָם יְיָ יְהָבִית לָךְ וְלִבְנָיךְ וְלִבְנָתָיךְ עִמָךְ לִקְיַם עֲלָם קְיַים מְלַח עֲלָם הִיא קֳדָם יְיָ לָךְ וְלִבְנָךְ עִמָךְ:
@673 וַאֲמַר יְיָ לְאַהֲרֹן בְּאַרְעֲהוֹן לָא תַחֲסִין וְחוּלַק לָא יְהֵי לָךְ בֵּינֵיהוֹן מַתְּנָן דִי יְהָבִית לָךְ אִנוּן חוּלְקָךְ וְאַחֲסַנְתָּךְ בְּגוֹ בְּנֵי יִשְׂרָאֵל:
@674 וְלִבְנֵי לֵוִי הָא יְהָבִית כָּל מַעַשְׂרָא בְּיִשְׂרָאֵל לְאַחֲסָנָא חֲלַף פּוּלְחַנְהוֹן דִי אִינוּן פָּלְחִין יָת פּוּלְחַן מַשְׁכַּן זִמְנָא:
@675 וְלָא יִקְרְבוּן עוֹד בְּנֵי יִשְׂרָאֵל לְמַשְׁכַּן זִמְנָא לְקַבָּלָא חוֹבָא לִמְמָת:
@676 וְיִפְלְחוּן לֵוָאֵי אִינוּן יָת פּוּלְחַן מַשְׁכַּן זִמְנָא וְאִינוּן יְקַבְּלוּן חוֹבֵיהוֹן קְיַם עֲלָם לְדָרֵיכוֹן וּבְגוֹ בְּנֵי יִשְׂרָאֵל לָא יַחְסְנוּן אַחְסָנָא:
@677 אֲרֵי יָת מַעַשְׂרָא דִבְנֵי יִשְׂרָאֵל דִי יִפְרְשׁוּן קֳדָם יְיָ אַפְרָשׁוּתָא יְהָבִית לְלֵוָאֵי לְאַחֲסָנָא עַל כֵּן אֲמָרִית לְהוֹן בְּגוֹ בְּנֵי יִשְׂרָאֵל לָא יַחְסְנוּן אַחֲסָנָא:
@678 וּמַלֵיל יְיָ עִם משֶׁה לְמֵימָר:
@679 וּלְלֵוָאֵי תְּמַלֵיל וְתֵימַר לְהוֹן אֲרֵי תִסְבוּן מִן בְּנֵי יִשְׂרָאֵל יָת מַעַשְׂרָא דִי יְהָבִית לְכוֹן מִנְהוֹן בְּאַחֲסַנְתְּכוֹן וְתַפְרְשׁוּן מִנֵיהּ אַפְרָשׁוּתָא קֳדָם יְיָ מַעַשְׂרָא מִן מַעַשְׂרָא:
@680 וְתִתְחַשֵׁב לְכוֹן אַפְרָשׁוּתְכוֹן כְּעִבּוּרָא מִן אִדְרָא וְכִמְלֵאָתָא מִן מַעְצַרְתָּא:
@681 כֵּן תַּפְרְשׁוּן אַף אַתּוּן אַפְרָשׁוּתָא קֳדָם יְיָ מִכֹּל מַעַשְׂרָתֵיכוֹן דִי תִסְבוּן מִן בְּנֵי יִשְׂרָאֵל וְתִתְּנוּן מִנֵיהּ יָת אַפְרָשׁוּתָא קֳדָם יְיָ לְאַהֲרֹן כַּהֲנָא:
@682 מִכֹּל מַתְּנָתֵכוֹן תִּפְרְשׁוּן יָת כָּל אַפְרָשׁוּתָא דַיְיָ מִכָּל שׁוּפְרֵיהּ יָת מַקְדְשֵׁיהּ מִנֵיהּ:
@683 וְתֵימַר לְהוֹן בְּאַפְרָשׁוּתְכוֹן יָת שׁוּפְרֵיהּ מִנֵיהּ וְיִתְחַשֵׁב לְלֵּוָאֵי כַּעֲלָלַת אִדְרָא וְכַעֲלָלַת מַעֲצַרְתָּא:
@684 וְתֵיכְלוּן יָתֵיהּ בְּכָל אֲתַר אַתּוּן וֶאֱנַשׁ בָּתֵּיכוֹן אֲרֵי אַגְרָא הוּא לְכוֹן חֲלַף פָּלְחַנְכוֹן בְּמַשְׁכַּן זִמְנָא:
@685 וְלָא תְקַבְּלוּן עֲלוֹהִי חוֹבָא בְּאַפְרָשׁוּתְכוֹן יָת שׁוּפְרֵיהּ מִנֵיהּ וְיָת קוּדְשַׁיָא דִבְנֵי יִשְׂרָאֵל לָא תְחַלְלוּן וְלָא תְמוּתוּן: פפפ:
@686 וּמַלִיל יְיָ עִם משֶׁה וְעִם אַהֲרֹן לְמֵימָר:
@687 דָא גְזֵירַת אוֹרַיְתָא דִי פַקִיד יְיָ לְמֵימָר מַלֵיל עִם בְּנֵי יִשְׂרָאֵל וְיִסְבוּן לָךְ תּוֹרְתָא סִמוּקְתָּא שְׁלֶמְתָּא דִי לֵית בָּהּ מוּמָא דְלָא סְלִיק עֲלַהּ נִירָא:
@688 וְתִתְּנוּן יָתַהּ לְאֶלְעָזָר כַּהֲנָא וְיַפֵּק יָתַהּ לְמִבָּרָא לְמַשְׁרִיתָא וְיִכּוֹס יָתַהּ קֳדָמוֹהִי:
@689 וְיִסַב אֶלְעָזָר כַּהֲנָא מִדְמַהּ בְּאֶצְבְּעֵיהּ וְיַדֵי לָקֳבֵל אַפֵּי מַשְׁכַּן זִמְנָא מִדְמַהּ שְׁבַע זִמְנִין:
@690 וְיוֹקֵד יָת תּוֹרְתָא לְעֵינוֹהִי יָת מַשְׁכַּהּ וְיָת בִּשְׂרַהּ וְיָת דְמַהּ עַל אָכְלַהּ יוֹקֵיד:
@691 וְיִסַב כַּהֲנָא אָעָא דְאַרְזָא וְאֵזוֹבָא וּצְבַע זְהוֹרִי וְיִרְמֵי לְגוֹ יְקִידַת תּוֹרְתָא:
@692 וִיצַבַּע לְבוּשׁוֹהִי כַּהֲנָא וְיַסְחֵי בִשְׂרֵיהּ בְמַיָא וּבָתַר כֵּן יֵיעוּל לְמַשְׁרִיתָא וִיהֵי מְסָאָב כַּהֲנָא עַד רַמְשָׁא:
@693 וּדְמוֹקֵד יָתַהּ יְצַבַּע לְבוּשׁוֹהִי בְּמַיָא וְיַסְחֵי בִשְׂרֵיהּ בְּמַיָא וִיהֵי מְסָאָב עַד רַמְשָׁא:
@694 וְיִכְנוֹשׁ גְבַר דְכֵי יָת קִטְמָא דְתוֹרְתָא וְיַצְנַע לְמִבָּרָא לְמַשְׁרִיתָא בַּאֲתַר דְכֵי וּתְהֵי לִכְנִשְׁתָּא דִבְנֵי יִשְׂרָאֵל לְמַטָּרָא לְמֵי אַדָיוּתָא חַטָאתָא הִיא:
@695 וִיצַבַּע דְכַנֵישׁ יָת קִטְמָא דְתוֹרְתָא יָת לְבוּשׁוֹהִי וִיהֵי מְסָאָב עַד רַמְשָׁא וּתְהֵי לִבְנֵי יִשְׂרָאֵל וּלְגִיוֹרַיָא דְיִתְגַיְירוּן בֵּינֵיהוֹן לִקְיַים עֲלָם:
@696 דְיִקְרַב בְּמִיתָא לְכָל נַפְשָׁא דֶאֱנָשָׁא וִיהֵי מְסָאָב שַׁבְעָא יוֹמִין:
@697 הוּא יַדֵי עֲלוֹהִי בְּיוֹמָא תְלִיתָאָה וּבְיוֹמָא שְׁבִיעָאָה יִדְכֵּי וְאִם לָא יַדֵי עֲלוֹהִי בְּיוֹמָא תְלִיתָאָה וּבְיוֹמָא שְׁבִיעָאָה לָּא יִדְכֵּי:
@698 כָּלּ דְיִקְרַבּ בְּמִיתָא בְּנַפְשָׁא דֶאֱנָשָׁא דִי יְמוּת וְלָא יַדֵי עֲלוֹהִי יָת מַשְׁכְּנָא דַיְיָ סָאֵב וְיִשְׁתֵּצֵי אֱנָשָׁא הַהוּא מִיִשְׂרָאֵל אֲרֵי מֵי אַדָיוּתָא לָא אִזְדְרִיקוּ עֲלוֹהִי מְסָאָב יְהֵי עוֹד סְאוֹבְתֵּיהּ בֵּיהּ:
@699 דָא אוֹרַיְתָא אֱנַשׁ אֲרֵי יְמוּת בְּמַשְׁכְּנָא כָּל דְעָלֵל לְמַשְׁכְּנָא וְכָל דִי בְמַשְׁכְּנָא יְהֵי מְסָאָב שַׁבְעָא יוֹמִין:
@700 וְכָל מַן דַחֲסַף פְּתִיחַ דְלֵית מִגוּפַת שְׁיִיעַ מַקַף עַלוֹהִי מְסָאָב הוּא:
@701 וְכֹל דִי יִקְרַב עַל אַפֵּי חַקְלָא בִּקְטֵל חַרְבָּא אוֹ בְמִיתָא אוֹ בְגַרְמָא דֶאֱנָשָׁא אוֹ בְקִבְרָא יְהֵי מְסָאָב שַׁבְעָא יוֹמִין:
@702 וְיִסְבוּן לְדִמְסָאָב מֵעֲפַר יְקִידַת חַטָאתָא וְיִתֵּן עֲלוֹהִי מֵי מַבּוּעַ לְמָן:
@703 וְיִסַב אֵזוֹבָא וְיִטְבּוֹל בְּמַיָא גְבַר דְכֵי וְיַדֵי עַל מַשְׁכְּנָא וְעַל כָּל מָנַיָא וְעַל נַפְשָׁתָא דִי הֲווֹ תַמָן וְעַל דְיִקְרַב בְּגַרְמָא אוֹ בְקָטִילָא אוֹ בְמִיתָא אוֹ בְקִבְרָא:
@704 וְיַדֵי דַכְיָא עַל מְסָאֲבָא בְּיוֹמָא תְלִיתָאָה וּבְיוֹמָא שְׁבִיעָאָה וִידַכִּינֵיהּ בְּיוֹמָא שְׁבִיעָאָה וִיצַבַּע לְבּוּשׁוֹהִי וְיַסְחֵי בְמַיָא וְיִדְכֵּי בְרַמְשָׁא:
@705 וּגְבַר דִי יִסְתָּאֵב וְלָא יַדֵי עֲלוֹהִי וְיִשְׁתֵּיצֵי אֱנָשָׁא הַהוּא מִגוֹ קְהָלָא אֲרֵי יָת מַקְדְשָׁא דַיְיָ סָאֵיב מֵי אַדָיוּתָא לָא אִזְדְרִיקוּ עֲלוֹהִי מְסָאָבּ הוּא:
@706 וּתְהֵי לְהוֹן לִקְיַם עֲלָם וּדְיַדֵי מֵי אַדָיוּתָא יְצַבַּע לְבוּשׁוֹהִי וּדְיִקְרַב בְּמֵי אַדָיוּתָא יְהֵי מְסָאָב עַד רַמְשָׁא:
@707 וְכָל דִי יִקְרַב בֵּיהּ מְסָאָבָא יְהֵי מְסָאָב וֶאֱנַשׁ דְיִקְרַב בֵּיהּ יְהֵי מְסָאָב עַד רַמְשָׁא:
@708 וַאֲתוֹ בְנֵי יִשְׂרָאֵל כָּל כְּנִשְׁתָא לְמַדְבְּרָא דְצִין בְּיַרְחָא קַדְמָאָה וִיתֵיב עַמָא בִּרְקָם וּמִיתַת תַּמָן מִרְיָם וְאִתְקְבָרַת תַּמָן:
@709 וְלָא הֲוָה מַיָא לִכְנִשְׁתָּא וְאִתְכַּנָשׁוּ עַל משֶׁה וְעַל אַהֲרֹן:
@710 וּנְצָא עַמָא עִם משֶׁה וַאֲמָרוּ לְמֵימָר וּלְוַי דְמִתְנָא בְּמוֹתָא דַאֲחָנָא קֳדָם יְיָ:
@711 וּלְמָא אַעֶלְתּוּן יָת קְהָלָא דַיְיָ לְמַדְבְּרָא הָדֵין לִמְמַת תַּמָן אֲנַחְנָא וּבְעִירָנָא:
@712 וּלְמָא אַסֶקְתּוּנָא מִמִצְרַיִם לְאַיְתָאָה יָתָנָא לְאַתְּרָא בִישָׁא הָדֵין לָא אֲתַר כְּשַׁר לְבֵית זְרַע וְאַף לָא תְּאֵנִין וְגוּפְנִין וְרִמוֹנִין וּמַיָא לֵית לְמִשְׁתֵּי:
@713 וְעַאל משֶׁה וְאַהֲרֹן מִן קֳדָם קְהָלָא לִתְרַע מַשְׁכַּן זִמְנָא וּנְפָלוּ עַל אַפֵּיהוֹן וְאִתְגְלֵי יְקָרָא דַיְיָ לְהוֹן:
@714 וּמַלֵיל יְיָ עִם משֶׁה לְמֵימָר:
@715 סַב יָת חוּטְרָא וְאַכְנֵשׁ יָת כְּנִשְׁתָּא אַתְּ וְאַהֲרֹן אָחוּךְ וּתְמַלְלוּן עִם כֵּיפָא לְעֵינֵיהוֹן וְיִתֵּן מוֹהִי וְתַפֵּיק לְהוֹן מַיָא מִן כֵּיפָא וְתַשְׁקֵי יָת כְּנִשְׁתָּא וְיָת בְּעִירְהוֹן:
@716 וּנְסִיב משֶׁה יָת חוּטְרָא מִן קֳדָם יְיָ כְּמָא דִי פַקְדֵיהּ:
@717 וְאַכְנִישׁוּ משֶׁה וְאַהֲרֹן יָת קְהָלָא לְקֳדָם כֵּיפָא וַאֲמַר לְהוֹן שְׁמָעוּ כְעַן סַרְבָנַיָא הֲמִן כֵּיפָא הָדֵין נַפֵּיק לְכוֹן מַיָא:
@718 וַאֲרֵם משֶׁה יָת יְדֵיהּ וּמְחָא יָת כֵּיפָא בְּחוּטְּרֵיהּ תְּרֵין זִמְנִין וּנְפָקוּ מַיָא סַגִיאֵי וּשְׁתִיאַת כְּנִשְׁתָּא וּבְעִירְהוֹן:
@719 וַאֲמַר יְיָ לְמשֶׁה וּלְאַהֲרֹן חֲלַף דִי לָא הֵימַנְתּוּן בְּמֵימְרִי לְקַדָשׁוּתִי לְעֵינֵי בְּנֵי יִשְׂרָאֵל בְּכֵן לָא תֵעֲלוּן יָת קְהָלָא הָדֵין לְאַרְעָא דִי יְהָבִית לְהוֹן:
@720 אִינוּן מֵי מַצוּתָא דִנְצוֹ בְנֵי יִשְׂרָאֵל קֳדָם יְיָ וְאִתְקַדַשׁ בְּהוֹן:
@721 וּשְׁלַח משֶׁה אִזְגַדִין מֵרְקָם לְוַת מַלְכָּא דֶאֱדוֹם כִּדְנַן אֲמַר אָחוּךְ יִשְׂרָאֵל אַתְּ יְדַעְתְּ יָת כָּל עָקְתָא דִי אַשְׁכַּחְתָּנָא:
@722 וּנְחָתוּ אֲבָהָתָנָא לְמִצְרַיִם וִיתֵיבְנָא בְמִצְרַיִם יוֹמִין סַגִיאִין וְאַבְאִישׁוּ לָנָא מִצְרָאֵי וְלַאֲבָהָתָנָא:
@723 וְצַלֵינָא קֳדָם יְיָ וְקַבִּיל צְלוֹתָנָא וּשְׁלַח מַלְאָכָא וְאַפְקָנָא מִמִצְרָיִם וְהָא אֲנַחְנָא בִּרְקַם קַרְתָּא דְבִסְטַר תְּחוּמָךְ:
@724 נְעִיבַּר כְּעַן בְּאַרְעָךְ לָא נְעִיבֵּר בַּחֲקַל וּבִכְרָם וְלָא נִשְׁתֵּי מֵי גוֹב בְּאֹרַח מַלְכָּא נֵיזֵיל לָא נִסְטֵּי לְיַמִינָא וְלִשְׂמָאלָא עַד דִנְעִיבַּר תְּחוּמָךְ:
@725 וַאֲמַר לֵיהּ אֱדוֹמָאָה לָא תְעִבַּר בִּתְחוּמִי דִלְמָא בִדְקָטְלִין בְּחַרְבָּא אֶפּוֹק לָקָדָמוּתָךְ:
@726 וַאֲמָרוּ לֵיהּ בְּנֵי יִשְׂרָאֵל בְּאֹרַח כְּבִישָׁא נִסַק וְאִם מֵימַךְ נִשְׁתֵּי אֲנָא וּבְעִירַי וְאֶתֵּן דְמֵיהוֹן לְחוֹד לֵית פִּתְגַם דְבִישׁ בְּרַגְלַי אֵעִיבַּר:
@727 וַאֲמַר לָא תְעִבָּר וּנְפַק אֱדוֹמָאָה לָקֳדָמוּתֵיהּ בְּחֵיל רַב וּבִידָא תַקִיפָא:
@728 וְסָרֵיב אֱדוֹמָאָה לְמִשְׁבַּק יָת יִשְׂרָאֵל לְמֶעֱבַר בִּתְחוּמֵיהּ וּסְטָּא יִשְׂרָאֵל מִלְוָתֵיהּ:
@729 וּנְטָלוּ מֵרְקָם וַאֲתוֹ בְנֵי יִשְׂרָאֵל כָּל כְּנִשְׁתָּא לְהֹר טוּרָא:
@730 וַאֲמַר יְיָ לְמשֶׁה וּלְאַהֲרֹן בְּהוֹר טוּרָא עַל תְּחוּם אַרְעָא דֶאֱדוֹם לְמֵימָר:
@731 יִתְכְּנֵשׁ אַהֲרֹן לְעַמֵיהּ אֲרֵי לָא יֵעוֹל לְאַרְעָא דִי יְהָבִית לִבְנֵי יִשְׂרָאֵל עַל דִי סְרֵיבְתּוּן עַל מֵימְרִי לְמֵי מַצוּתָא:
@732 דְבַר יָת אַהֲרֹן וְיָת אֶלְעָזָר בְּרֵיהּ וְאַסֵיק יָתְהוֹן לְהֹר טּוּרָא:
@733 וְאַשְׁלַח יָת אַהֲרֹן יָת לְבוּשׁוֹהִי וְתַלְבֵּישִׁנוּן יָת אֶלְעָזָר בְּרֵיהּ וְאַהֲרֹן יִתְכְּנֵישׁ וִימוּת תַּמָן:
@734 וַעֲבַד משֶׁה כְּמָא דִי פַקִיד יְיָ וּסְלִיקוּ לְהֹר טוּרָא לְעֵינֵי כָּל כְּנִשְׁתָּא:
@735 וְאַשְׁלַח משֶׁה יָת אַהֲרֹן יָת לְבוּשׁוֹהִי וְאַלְבִּישׁ יָתְהוֹן יָת אֶלְעָזָר בְּרֵיהּ וּמִית אַהֲרֹן תַּמָן בְּרֵישׁ טוּרָא וּנְחַת משֶׁה וְאֶלְעָזָר מִן טוּרָא:
@736 וַחֲזוֹ כָּל כְּנִשְׁתָּא אֲרֵי מִית אַהֲרֹן וּבְכוֹ יָת אַהֲרֹן תְּלָתִין יוֹמִין כֹּל בֵּית יִשְׂרָאֵל:
@737 וּשְׁמַע כְּנַעֲנָאָה מַלְכָּא דַעֲרָד יָתֵיב דָרוֹמָא אֲרֵי אֲתָא יִשְׂרָאֵל אֹרַח מְאַלְלַיָא וְאַגַח קְרָבָא בְּיִשְׂרָאֵל וּשְׁבָא מִנֵיהּ שִׁבְיָא:
@738 וְקַיֵים יִשְׂרָאֵל קְיָים קֳדָם יְיָ וַאֲמַר אִם מִמְסַר תִּמְסַר יָת עַמָא הָדֵין בִּידִי וַאֲגַמַר יָת קִרְוֵיהוֹן:
@739 וְקַבֵּיל יְיָ צְלוֹתֵיהּ דְיִשְׂרָאֵל וּמְסַר יָת כְּנַעֲנָאָה וְגַמַר יָתְהוֹן וְיָת קִרְוֵיהוֹן וּקְרָא שְׁמָא דְאַתְרָא חָרְמָה:
@740 וּנְטָלוּ מֵהֹר טוּרָא אֹרַח יַמָא דְסוּף לְאַקָפָא יָת אַרְעָא דֶאֱדוֹם וַעֲקַת נַפְשָׁא דְעַמָא בְּאוֹרְחָא:
@741 וְאִתְרַעַם עַמָא בְּמֵימְרָא דַיְיָ וְעִם משֶׁה נְצוֹ לְמָא אַסֵקְתּוּנָא מִמִצְרַיִם לִמְמָת בְּמַדְבְּרָא אֲרֵי לֵית לַחְמָא וְלֵית מַיָא וְנַפְשָׁנָא עָקַת בְּמַנָא הָדֵין דְמֵיכְלֵיהּ קָלֵיל:
@742 וְגָרֵי יְיָ בְּעַמָא יָת חִיוַן קָלָן וּנְכִיתוּ יָת עַמָא וּמִית עַם סַגִי מִיִשְׂרָאֵל:
@743 וַאֲתָא עַמָא לְמשֶׁה וַאֲמָרוּ חַבְנָא אֲרֵי אִתְרַעַמְנָא קֳדָם יְיָ וְעִמָךְ נְצֵינָא צַלִי קֲדָם יְיָ וְיַעֲדִי מִנָנָא יָת חִוְיָא וְצַלִי משֶׁה עַל עַמָא:
@744 וַאֲמַר יְיָ לְמשֶׁה עֲבֵיד לָךְ קַלְיָא וְשַׁוִי יָתֵיהּ עַל אָת וִיהֵי כָּל דְיִתְנְכִית וְיֶחֱזֵי יָתֵהּ וְיִתְקַיָם:
@745 וַעֲבַד משֶׁה חִוְיָא דִנְחָשָׁא וְשַׁוְיֵהּ עַל אָת וַהֲוָה כַּד נְכֵית חִוְיָא יָת גַבְרָא וּמִסְתַּכֵּל לְחִוְיָא דִנְחָשָׁא וּמִתְקַיָם:
@746 וּנְטָלוּ בְּנֵי יִשְׂרָאֵל וּשְׁרוֹ בְּאוֹבוֹת:
@747 וּנְטָלוּ מֵאוֹבוֹת וּשְׁרוֹ בִמְגִיזַת עֲבָרָאֵי בְּמַדְבְּרָא דִי עַל אַפֵּי מוֹאָב מִמַדְנַח שִׁמְשָׁא:
@748 מִתַּמָן נְטָלוּ וּשְׁרוֹ בְּנַחֲלָא דְזָרֶד:
@749 מִתַּמָן נְטָלוּ וּשְׁרוֹ מֵעִבְרָא דְאַרְנוֹן דִי בְּמַדְבְּרָא דְנָפֵיק מִתְּחוּם אֱמוֹרָאָה אֲרֵי אַרְנוֹן תְּחוּם מוֹאָב בֵּין מוֹאָב וּבֵין אֱמוֹרָאָה:
@750 עַל כֵּן יִתְאַמַר בְּסִפְרָא קְרָבִין דַעֲבַד יְיָ עַל יַמָא דְסוּף וּגְבוּרָן דְעַל נַחֲלֵי אַרְנוֹן:
@751 וְשָׁפוּךְ נַחֲלַיָא דְמִדַבְּרִין לְקָבֵל לְחָיַת וּמִסְתְּמִיךְ לִתְחוּם מוֹאָב:
@752 וּמִתַּמָן אִתְיְהִיבַת לְהוֹן בֵּירָא הִיא בֵירָא דִי אֲמַר יְיָ לְמשֶׁה כְּנוֹשׁ יָת עַמָא וְאֶתֵּן לְהוֹן מַיָא:
@753 בְּכֵן שַׁבַּח יִשְׂרָאֵל יָת תּוּשְׁבַּחְתָּא הָדָא סַקִי בֵירָא שַׁבָּחוּ לָהּ:
@754 בֵּירָא דְחָפְרוּהָ רַבְרְבַיָא כְּרוּהָ רֵישֵׁי עַמָא סַפְרַיָא בְּחוּטְרֵיהוֹן וּמִמַדְבְּרָא אִתְיְהִיבַת לְהוֹן:
@755 וּמִדְאִתְיְהִיבַת לְהוֹן נַחֲתָא עִמְהוֹן לְנַחֲלַיָא וּמִנַחֲלַיָא סָלְקָא עִמְהוֹן לְרָמָתָא:
@756 וּמֵרָמָתָא לְחֵילַיָא דִי בְּחַקְלֵי מוֹאָב רֵישׁ רָמָתָא וּמִסְתַּכְיָא עַל אַפֵּי בֵּית יְשִׁימוֹן:
@757 וּשְׁלַח יִשְׂרָאֵל אִזְגַדִין לְוָת סִיחוֹן מַלְכָּא דֶאֱמוֹרָאָה לְמֵימָר:
@758 אֵעִיבַּר בְּאַרְעָךְ לָא נִסְטֵי בַּחֲקַל וּבִכְרַם לָא נִשְׁתֵּי מֵי גוֹב בְּאֹרַח מַלְכָּא נֵיזֵיל עַד דִי נְעִבַּר תְּחוּמָךְ:
@759 וְלָא שְׁבַק סִיחוֹן יָת יִשְׂרָאֵל לְמֶעְבַּר בִּתְחוּמֵיהּ וּכְנַשׁ סִיחוֹן יָת כָּל עַמֵיהּ וּנְפַק לָקֳדָמוּת יִשְׂרָאֵל לְמַדְבְּרָא וַאֲתָא לְיָהַץ וְאַגִיחַ קְרָבָא בְּיִשְׂרָאֵל:
@760 וּמְחָהִי יִשְׂרָאֵל לְפִתְגַם דְחָרֶב וִירֵת יָת אַרְעֵיהּ מֵאַרְנוֹנָא עַד יוּבְקָא עַד בְּנֵי עַמוֹן אֲרֵי תַקִיף תְּחוּמָא דִבְנֵי עַמוֹן:
@761 וּכְבַשׁ יִשְׂרָאֵל יָת כָּל קִרְוַיָא הָאִלֵין וִיתֵיב יִשְׂרָאֵל בְּכָל קִרְוֵי אֱמוֹרָאָה בְּחֶשְׁבּוֹן וּבְכָל כַּפְרָנָהָא:
@762 אֲרֵי חֶשְׁבּוֹן קַרְתָּא דְסִיחוֹן מַלְכָּא דֶאֱמוֹרָאָה הִיא וְהוּא אַגַח קְרָבָא בְּמַלְכָּא דְמוֹאָב קַדְמָאָה וּנְסֵיב יָת כָּל אַרְעֵיהּ מִידֵיהּ עַד אַרְנוֹן:
@763 עַל כֵּן יֵימְרוּן מְתָלַיָא עוּלוּ לְחֶשְׁבּוֹן תִּתְבְּנֵי וְתִשְׁתַּכְלַל קַרְתָּא דְסִיחוֹן:
@764 אֲרֵי קִידוּם תַּקִיף כְּאֶשָׁא נְפַק מֵחֶשְׁבּוֹן עָבְדֵי קְרָבָא כְּשַׁלְהוֹבִיתָא מִקַרְתָּא דְסִיחוֹן קַטִילוּ עַמָא דִשְׁרוֹ בִּלְחָיַת מוֹאָב כּוּמְרַיָא דְפַלְחִין בֵּית דַחֲלָא רָמָתָא דְאַרְנוֹן:
@765 וַי לְכוֹן מוֹאֲבָאֵי אֲבַדְתּוּן עַמָא דְפָלְחִין לִכְמוֹשׁ מְסַר בְּנוֹהִי צִירִין וּבְנָתֵיהּ בְּשִׁבְיָא לְמַלְכָּא דֶאֱמוֹרָאָה סִיחוֹן:
@766 וּמַלְכוּ פְסָקַת מֵחֶשְׁבּוֹן עֲדָא שׁוּלְטַן מִדִיבוֹן וְצֲדִיאוּ עַד נֹפַח דִסְמִיךְ עַד מֵידְבָא:
@767 וִיתֵב יִשְׂרָאֵל בַּאֲרַע אֱמוֹרָאָה:
@768 וּשְׁלַח משֶׁה לְאַלָלָא יָת יַעְזֵר וּכְבָשׁוּ כַּפְרָנָהָא וְתָרִיךְ יָת אֱמוֹרָאָהּ דִי תַמָן:
@769 וְאִתְפְּנִיאוּ וּסְלִיקוּ לְאֹרַח מַתְנָן וּנְפַק עוֹג מַלְכָּא דְמַתְנָן לְקֳדָמוּתְהוֹן הוּא וְכָל עַמֵּיהּ לְאַגָחָא קְרָבָא לְאֶדְרֶעִי:
@770 וַאֲמַר יְיָ לְמשֶׁה לָא תִדְחַל מִנֵיהּ אֲרֵי בִידָךְ מְסָרִית יָתֵיהּ וְיָת כָּל עַמֵיהּ וְיָת אַרְעֵיהּ וְתַעֲבֵד לֵיהּ כְּמָא דִי עֲבַדְתְּ לְסִיחוֹן מַלְכָּא דֶאֱמוֹרָאָה דִי יָתֵב בְּחֶשְׁבּוֹן:
@771 וּמְחוֹ יָתֵיהּ וְיָת בְּנוֹהִי וְיָת כָל עַמֵּיהּ עַד דְלָא אִשְׁתָּאַר לֵיהּ מְשֵׁיזִיב וִירִיתוּ יָת אַרְעֵיהּ:
@772 וּנְטָלוּ בְּנֵי יִשְׂרָאֵל וּשְׁרוֹ בְּמֵישְׁרַיָא דְמוֹאָב מֵעִבְרָא לְיַרְדְנָא דִירֵחוֹ: פפפ:
@773 וַחֲזָא בָּלָק בַּר צִפּוֹר יָת כָּל דִי עֲבַד יִשְׂרָאֵל לֶאֱמוֹרָאֵי:
@774 וּדְחִיל מוֹאֲבָאָה מִן קֳדָם עַמָא לַחֲדָא אֲרֵי סַגִי הוּא וַעֲקַת לְמוֹאֲבָאָה מִן קֳדָם בְּנֵי יִשְׂרָאֵל:
@775 וַאֲמַר מוֹאָב לְסָבֵי מִדְיָן כְּעַן יְשֵׁיצוּן קְהָלָא יָת כָּל סַחֲרָנָנָא כְּמָא דִמְלַחֵיךְ תּוֹרָא יָת יְרוֹקָא דְחַקְלָא וּבָלָק בַּר צִפּוֹר מַלְכָּא לְמוֹאָב בְּעִידָנָה הַהִיא:
@776 וּשְׁלַח אִזְגַדִין לְוָת בִּלְעָם בַּר בְּעוֹר לִפְּתוֹר אֲרָם דְעַל פְּרָת אֲרַע בְּנֵי עַמֵיהּ לְמִקְרֵי לֵיהּ לְמֵימָר הָא עַמָא נְפַק מִמִצְרַיִם הָא חֲפָא יַת עֵין שִׁמְשָׁא דְאַרְעָא וְהוּא שָׁרֵי מִלְקִבְלִי:
@777 וּכְעַן אִיתָא כְּעַן לוֹט לִי יָת עַמָא הָדֵין אֲרֵי תַקִיף הוּא מִנִי מָאִים אֵכוּל לְאַגָחָא בֵּיהּ קְרָב וַאֲתָרֵכִינֵיהּ מִן אַרְעָא אֲרֵי יְדַעֲנָא יָת דִי תְבָרַךְ מְבָרָךְ וְדִי תְלוֹט לִיט:
@778 וַאֲזָלוּ סָבֵי מוֹאָב וְסָבֵי מִדְיָן וְקִסְמַיָא בִּידֵיהוֹן וַאֲתוֹ לְוַת בִּלְעָם וּמַלִילוּ עִמֵיהּ פִּתְגָמֵי בָּלָק:
@779 וַאֲמַר לְהוֹן בִּיתוּ הָכָא בְּלֵילְיָא וְאָתֵב יַתְכוֹן פִּתְגָמָא כְּמָא דִי יְמַלֵיל יְיָ עִמִי וְאוֹרִיכוּ רַבְרְבֵי מוֹאָב עִם בִּלְעָם:
@780 וַאֲתָא מֵימַר מִן קֳדָם יְיָ לְוַת בִּלְעָם וַאֲמַר מָן גוּבְרַיָא הָאִלֵין דְעִמָךְ:
@781 וַאֲמַר בִּלְעָם קֳדָם יְיָ בָּלָק בַּר צִפּוֹר מַלְכָּא דְמוֹאָב שְׁלַח לְוָתִי:
@782 הָא עַמָא דִי נְפַק מִמִצְרַיִם וַחֲפָא יָת עֵין שִׁמְשָׁא דְאַרְעָא כְּעַן אִיתָא לוֹט לִי יָתֵיהּ מָאִים אֵיכוּל לְאַגָחָא בֵּיהּ קְרָב וְאֲתָרֵיכִינֵיהּ:
@783 וַאֲמַר יְיָ לְבִלְעָם לָא תֵיזִיל עִמְהוֹן לָא תְלוֹט יָת עַמָא אֲרֵי בְרִיךְ הוּא:
@784 וְקָם בִּלְעָם בְּצַפְרָא וַאֲמַר לְרַבְרְבֵי בָלָק אִיזִילוּ לְאַרְעֲכוֹן אֲרֵי לֵית רַעֲוָא קֳדָם יְיָ לְמִשְׁבְּקִי לְמֵיזַל עִמְכוֹן:
@785 וְקָמוּ רַבְרְבֵי מוֹאָב וַאֲתוֹ לְוָת בָּלָק וַאֲמָרוּ סָרֵיב בִּלְעָם לְמֵיתֵי עִמָנָא:
@786 וְאוֹסִיף עוֹד בָּלָק לְמִשְׁלַח רַבְרְבִין סַגִיאִין:ויַקִירִין מֵאִלֵין:
@787 וַאֲתוֹ לְוָת בִּלְעָם וַאֲמָרוּ לֵיהּ כִּדְנַן אֲמַר בָּלָק בַּר צִפּוֹר לָא כְעַן תִּתְמְנַע מִלְמֵיתֵי לְוָתִי:
@788 אֲרֵי יְקָרָא אֲיַקְרִינָךְ לַחֲדָא וְכֹל דִי תֵימַר לִי אַעְבֵּד וְאִיתָא כְעַן לוֹט לִי יַת עַמָא הָדֵין:
@789 וַאֲתֵיב בִּלְעָם וַאֲמַר לְעַבְדֵי בָלָק אִם יִתֶּן לִי בָלָק מְלֵי בֵיתֵיהּ כְּסַף וּדְהַב לֵית לִי רְשׁוּ לְמֶעֱבַּר עַל גְזֵירַת מֵימְרָא דַיְיָ אֱלָהָי לְמֶעְבַּד זְעֵרְתָּא אוֹ רַבְּתָא:
@790 וּכְעַן אוֹרִיכוּ כְעַן הָכָא אַף אַתּוּן בְּלֵילְיָא וְאִדַע מָה יוֹסֵף יְיָ לְמַלָלָא עִמִי:
@791 וַאֲתָּא מֵימַר מִן קֳדָם יְיָ לְבִלְעָם בְּלֵילְיָא וַאֲמַר לֵיהּ אִם לְמִקְרֵי לָךְ אֲתוֹ גֻבְרַיָא קוּם אִיזֵיל עִמְהוֹן וּבְרַם יַת פִּתְגָמָא דִי אֲמַלֵיל עִמָךְ יָתֵיהּ תַּעְבֵיד:
@792 וְקָם בִּלְעָם בְּצַפְרָא וְזָרֵיז יַת אֲתָנֵיהּ וַאֲזַל עִם רַבְרְבֵי מוֹאָב:
@793 וּתְקֵיף רָגְזָא דַיְיָ אֲרֵי אָזֵיל הוּא וְאִתְעַתַּד מַלְאָכָא דַיְיָ בְּאוֹרְחָא לְשָׂטָן לֵהּ וְהוּא רָכִיב עַל אַתָּנֵיהּ וּתְרֵין עוּלֵימוֹהִי עִמֵהּ:
@794 וַחֲזַת אֲתָּנָא יַת מַלְאָכָא דַיְיָ מְעַתַּד בְּאָרְחָא וְחַרְבֵּיהּ שְׁלִיפָא בִּידֵיהּ וּסְטַת אֲתָּנָא מִן אוֹרְחָא וַאֲזָלַת בְּחַקְלָא וּמְחָא בִּלְעָם יַת אֲתָּנָא לְאַסְטָיוּתַהּ לְאָרְחָא:
@795 וְקָם מַלְאָכָא דַיְיָ בִּשְׁבִיל כַּרְמַיָא אַתְרָא דְגָדֵירָא מִכָּא וְגָדֵירָא מִכָּא:
@796 וַחֲזַת אֲתָּנָא יַת מַלְאָכָא דַיְיָ וְאִדְחֵיקַת לְכָתְלָא וּדְחֵיקַת יַת רִגְלָא דְבִלְעָם לְכָתְלָא וְאוֹסִיף לְמִמְחַהּ:
@797 וְאוֹסֵף מַלְאָכָא דַיְיָ לְמֶעְבָּר וְקָם בַּאֲתַר עָק דִי לֵית אֹרַח לְמִסְטֵי לְיַמִינָא וְלִשְׂמָאלָא:
@798 וַחֲזַת אֲתָּנָא יַת מַלְאָכָא דַיְיָ וּרְבָעַת תְּחוֹת בִּלְעָם וּתְקֵיף רוּגְזָא דְבִלְעָם וּמְחָא יַת אֲתָּנָא בְּחֻטְרָא:
@799 וּפְתַח יְיָ יַת פּוּמָא דַאֲתָּנָא וַאֲמָרַת לְבִּלְעָם מָה עֲבָדִית לָךְ אֲרֵי מְחִיתַנִי דְנַן תְּלַת זִמְנִין:
@800 וַאֲמַר בִּלְעָם לַאֲתָּנָא אֲרֵי חַיִיכְתְּ בִּי אִלוּפוֹן אִית חַרְבָּא בִּידִי אֲרֵי כְעָן קְטַלְתִּיךְ:
@801 וַאֲמָרַת אֲתָּנָא לְבִלְעָם הֲלָא אֲנָא אֲתָּנָךְ דְרָכַבְתְּ עֲלַי מִדְאִיתָךְ עַד יוֹמָא הָדֵין הֲמֵילַף אַלִפְנָא לְמֶעֱבַּד לָךְ כְּדֵין וַאֲמַר לָא:
@802 וּגְלָא יְיָ יַת עֵינֵי בִלְעָם וַחֲזָא יַת מַלְאָכָא דַיְיָ מְעַתַּד בְּאָרְחָא וְחַרְבֵּיהּ שְׁלִיפָא בִידֵיהּ וּכְרַע וּסְגִיד לְאַפּוֹהִי:
@803 וַאֲמַר לֵיהּ מַלְאָכָא דַיְיָ עַל מָה מָחִיתָא יַת אֲתָּנָךְ דְנַן תְּלַת זִמְנִין הָא אֲנָא נְפָקִית לְמִשְׂטַן אֲרֵי גְלֵי קֳדָמַי דְאַתְּ רָעֵי לְמֵיזַל בְּאוֹרְחָא לְקִבְּלִי:
@804 וַחֲזַתְנִי אֲתָּנָא וּסְטַת מִן קֳדָמַי דְנַן תְּלַת זִמְנִין אִילוּפוֹן לָא סְטַּת מִן קֳדָמַי אֲרֵי כְעַן אַף יָתָךְ קְטָלִית וְיָתַהּ קַיֵימִית:
@805 וַאֲמַר בִּלְעָם לְמַלְאָכָה דַיְיָ חָבִית אֲרֵי לָא יְדָעִית אֲרֵי אַתְּ מְעַתֵּד לָקֳדָמוּתִי בְּאָרְחָא וּכְעַן אִם בִּישׁ בְּעֵינָךְ אֵיתוּב לִי:
@806 וַאֲמַר מַלְאָכָא דַיְיָ לְבִלְעָם אִיזֵיל עִם גוּבְרַיָא וּלְחוֹד יַת פִּתְגָמָא דִי אֲמַלֵיל עִמָךְ יָתֵיהּ תְּמַלֵיל וַאֲזַל בִּלְעָם עִם רַבְרְבֵי בָּלָק:
@807 וּשְׁמַע בָּלָק אֲרֵי אָתָא בִלְעָם וּנְפַק לָקֳדָמוּתֵה לְקַרְתָּא דְמוֹאָב דִי עַל תְּחוּם אַרְנוֹן דִי בִּסְטַר תְּחוּמָא:
@808 וַאֲמַר בָּלָק לְבִלְעָם הֲלָא מִשְׁלַח שַׁלְחִית לְוָתָךְ לְמִקְרֵי לָךְ לְמָא לָא אֲתֵיתָא לְוָתִי הַבְקוּשְׁטָא הֲוֵיתָא אָמַר לֵית אֲנָא יָכִיל לְיַקְרוּתָךְ:
@809 וַאֲמַר בִּלְעָם לְבָלָק הָא אֲתֵיתִי לְוָתָךְ כְּעַן הֲמֵיכַל יְכִלְנָא לְמַלָלָא מִדַעַם פִּתְגָמָא דִי יְשַׁוֵי יְיָ בְּפוּמִי יָתֵיהּ אֲמַלֵיל:
@810 וַאֲזַל בִּלְעָם עִם בָּלָק וַאֲתוֹ לְקִרְיַת מְחוֹזוֹהִי:
@811 וּנְכֵיס בָּלָק תּוֹרִין וְעָאן וּשְׁלַח לְבִלְעָם וּלְרַבְרְבַיָא דִי עִמֵיהּ:
@812 וַהֲוָה בְּצַפְרָא וּדְבַר בָּלָק יַת בִּלְעָם וְאַסְקֵיהּ לְרָמַת דַחַלְתֵּיהּ וַחֲזָא מִתַּמָן קְצַת מִן עַמָא:
@813 וַאֲמַר בִּלְעָם לְבָלָק בְּנֵה לִי הָכָא שַׁבְעָא מַדְבְּחִין וְאַתְקִין לִי הָכָא שַׁבְעָא תוֹרִין וְשַׁבְעָא דִכְרִין:
@814 וַעֲבַד בָּלָק כְּמָא דִי מַלֵיל בִּלְעָם וְאַסֵיק בָּלָק וּבִלְעָם תּוֹר וּדְכַר עַל כָּל מַדְבְּחָא:
@815 וַאֲמַר בִּלְעָם לְבָלָק אִתְעַתֵּד עַל עֲלָתָךְ וְאֵיהַךְ מָאִים יְעָרַע מֵימַר מִן קֳדָם יְיָ לָקֳדָמוּתִי וּפִתְגָמָא דְיַחֲזִנַנִי וְאֵחַוֵי לָךְ וַאֲזַל יְחִידִי:
@816 וְעָרַע מֵימַר מִן קֳדָם יְיָ לְוַת בִּלְעָם וַאֲמַר לֵיהּ יַת שַׁבְעָא מַדְבְּחִין סְדָרִית וְאַסֵקִית תּוֹר וּדְכַר עַל כָּל מַדְבְּחָא:
@817 וְשַׁוִי יְיָ פִּתְגָמָא בְּפוּמָא דְבִלְעָם וַאֲמַר תּוּב לְוַת בָּלָק וּכְדֵין תְּמַלֵיל:
@818 וְתַב לְוָתֵיהּ וְהָא מְעַתֵּד עַל עֲלָתֵיהּ הוּא וְכָל רַבְרְבֵי מוֹאָב:
@819 וּנְטַל מַתְלֵיהּ וַאֲמַר מִן אֲרָם דַבְּרַנִי בָלָק מַלְכָּא דְמוֹאָב מִטוּרֵי מַדִנְחָא אִיתָא לוֹטּ לִי יַעֲקֹב וְאִיתָא תָּרֵיךְ לִי יִשְׂרָאֵל:
@820 מָה אֲלוֹטֵיהּ דְלָא לַטְיֵהּ אֵל וּמָה אֲתָרְכֵיהּ דְלָא תָרְכֵיהּ יְיָ:
@821 אֲרֵי מֵרֵישׁ טוּרַיָא חֲזִיתֵיהּ וּמֵרָמָתָא סְכִיתֵיהּ הָא עַמָא בִּלְחוֹדֵיהוֹן עֲתִידִין דְיַחְסְנוּן עַלְמָא וּבְעַמְמַיָא לָא יִתְדְנוּן גְמִירָא:
@822 מָן יֵיכוֹל לְמִמְנֵי דַעַדְקַיָא דְבֵית יַעֲקֹב דְאָמִיר עֲלֵיהוֹן יִסְגוּן כְּעַפְרָא דְאַרְעָא אוֹ חֲדָא מֵאַרְבַּע מַשִׁרְיָתָא דְיִשְׂרָאֵל תְּמוּת נַפְשִׁי מוֹתָא דְקַשִׁיטוֹהִי וּתְהֵי סוֹפִי כְּוַתְהוֹן:
@823 וַאֲמַר בָּלָק לְבִלְעָם מֶה עֲבַדְתָּא לִי לְמֵילַט סַנְאַי דְבַרְתִּיךְ וְהָא בְּרָכָא מְבָרְכַת לְהוֹן:
@824 וַאֲתֵיב וַאֲמַר הֲלָא יָת דִי יְשַׁוֵי יְיָ בְּפוּמִי יָתֵיהּ אֶטַר לְמַלָלָא:
@825 וַאֲמַר לֵיהּ בָּלָק אִיתָא כְעַן עִמִי לַאֲתַר אוֹחֲרָן דְתֶחֱזִנֵיהּ מִתַּמָן לְחוֹד קְצָתֵיהּ תֶּחֱזֵי וְכוּלֵיהּ לָא תֶחֱזֵי וּתְלוּטֵיהּ לִי מִתַּמָן:
@826 וְדַבְּרֵיהּ לַחֲקַל סְכוּתָא לְרֵישׁ רָמָתָא וּבְנָא שַׁבְעָא מַדְבְּחִין וְאַסֵיק תּוֹר וּדְכַר עַל כָּל מַדְבְּחָא:
@827 וַאֲמַר לְבָלָק אִתְעַתֵּד הָכָא עַל עֲלָתָךְ וַאֲנָא אִתְמְטֵי עַד כָּא:
@828 וְעָרַע מֵימַר מִן קֳדָם יְיָ לְבִלְעָם וְשַׁוִי פִתְגָמָא בְּפוּמֵיהּ וַאֲמַר תּוּב לְוָת בָּלָק וּכְדֵין תְּמַלֵיל:
@829 וַאֲתָא לְוָתֵיהּ וְהוּא מְעַתַּד עַל עֲלָתֵיהּ וְרַבְרְבֵי מוֹאָב עִמֵיהּ וַאֲמַר לֵיהּ בָּלָק מָה מַלִיל יְיָ:
@830 וּנְטַל מַתְלֵיהּ וַאֲמַר קוּם בָּלָק וּשְׁמַע אָצִית לְמֵימְרִי בַּר צִפֹּר:
@831 לָא כְמִלֵי בְּנֵי אֱנָשָׁא מֵימַר אֱלָהָא בְּנֵי אֱנָשָׁא אָמְרִין וּמְכַדְבִין וְאַף לָא כְעוֹבָדֵי בְּנֵי בִּשְׂרָא דְאִינוּן גָזְרִין לְמֶעְבַּד וְתַיְבִין וּמִתְמַלְכִין דְהוּא אָמַר וְעָבֵיד וְכָל מֵימְרֵהּ מִתְקַיָם:
@832 הָא בִּרְכָן קַבֵּילִית וַאֲבָרֵכִינֵיהּ לְיִשְׂרָאֵל וְלָא אָתֵב בִּרְכְּתִי מִינֵיה:
@833 אִסְתַּכָּלִית לֵית פָּלְחֵי גִלוּלִין בִּדְבֵית יַעֲקֹב וְאַף לָא עָבְדֵי לֵיאוּת שְׁקַר בְּיִשְׂרָאֵל מֵימְרָא דַיְיָ אֱלָהָהוֹן בְּסַעְדְהוֹן וּשְׁכִינַת מַלְכְּהוֹן בֵּינֵיהוֹן:
@834 אֱלָהָא דְאַפֵּקִנוּן מִמִצְרָיִם תּוּקְפָא וְרוּמָא דִילֵיהּ:
@835 אֲרֵי לָא נַחֲשַׁיָא צָבָן דְיִיטַב לִדְבֵית יַעֲקֹב וְאַף לָא קְסָמַיָא רְעַן בִּרְבוּת בֵּית יִשְׂרָאֵל כְּעִדַן יִתְאַמַר לְיַעֲקֹב וּלְיִשְׂרָאֵל מָה עֲבַד אֱלָהָא:
@836 הָא עַמָא כְּלֵיתָא שָׁרֵי וּכְאַרְיָא יִתְנַטֵל לָא יִשְׁרֵי בְאַרְעֵיהּ עַד דְיִקְטוֹל קְטוֹל וְנִכְסֵי עֲמְמַיָא יֵירָת:
@837 וַאֲמַר בָּלָק לְבִלְעָם אַף מֵילַט לָא תְלוּטִּינוּן אַף בְּרָכָא לָא תְבָ רֵ כִ י נוּ ן:
@838 וַאֲתֵיב בִּלְעָם וַאֲמַר לְבָלָק הֲלָא מַלֵילִית עִמָךְ לְמֵימַר כֹּל דִי יְמַלֵל יְיָ יָתֵיהּ אַעֲבֵיד:
@839 וַאֲמַר בָּלָק לְבִלְעָם אִיתָא כְּעַן אֲדַבְּרִינָךְ לַאֲתַר אָחֳרָן מָאִים יְהֵי רַעֲוָא מִן קֳדָם יְיָ וּתְלוּטֵיהּ לִי מִתַּמָן:
@840 וּדְבַר בָּלָק יַת בִּלְעָם רֵישׁ רָמָתָא דְמִסְתַּכְּיָא עַל אַפֵּי בֵּית יְשִׁימוֹן:
@841 וַאֲמַר בִּלְעָם לְבָלָק בְּנֵה לִי הָכָא שַׁבְעָא מַדְבְּחִין וְאַתְקִין לִי הָכָא שַׁבְעָא תוֹרִין וְשַׁבְעָא דִכְרִין:
@842 וַעֲבַד בָּלָק כְּמָא דִי אֲמַר בִּלְעָם וְאַסֵיק תּוֹר וּדְכַר עַל כָּל מַדְבְּחָא:
@843 וַחֲזָא בִלְעָם אֲרֵי תַקִין קֳדָם יְיָ לְבָרָכָא יַת יִשְׂרָאֵל וְלָא הַלַךְ כִּזְמַן בִּזְמַן אֱלָהֵין לָקֳדָמוּת נְחָשַׁיָא וְשַׁוִי לָקָבֵיל עֶגְלָא דַעֲבָדוּ יִשְׂרָאֵל בְּמַדְבְּרָא אַפּוֹהִי:
@844 וּזְקֵף בִּלְעָם יָת עֵינוֹהִי וַחֲזָא יָת יִשְׂרָאֵל שָׁרָן לְשִׁבְטוֹהִי וּשְׁרַת עֲלוֹהִי רוּחַ נְבוּאָה מִן קֳדָם יְיָ:
@845 וּנְטַל מַתְלֵיהּ וַאֲמַר אֵימַר בִּלְעָם בְּרֵיהּ בְעוֹר וְאֵימַר גַבְרָא דְשַׁפִּיר חָזֵי:
@846 אֵימַר דִשְׁמַע מֵימַר מִן קֳדָם אֵל וְחֵזוּ מִן קֳדָם שַׁדַי חָזֵי שְׁכִיב וּמִתְגְלֵי לֵיהּ:
@847 מָה טָבָא מַשְׁכְּנָךְ יַעֲקֹב בֵּית מֵישְׁרָךְ יִשְׂרָאֵל:
@848 כְּנַחֲלִין דִמְדַבְּרִין כְּגִינַת שַׁקְיָא דְעַל פְּרָת כְּבוּסְמַיָא דִנְצִיב יְיָ כְּאַרְזִין דִנְצִבִין עַל מַיָא:
@849 יִסְגֵי מַלְכָּא דְיִתְרַבָּא מִבְּנוֹהִי וְיִשְׁלוֹט בְּעַמְמִין סַגִיאִין וְיִתְקוֹף מֵאֲגַג מַלְכֵּיהּ וְתִתְנַטֵל מַלְכוּתֵיהּ:
@850 אֱלָהָא דְאַפֵּקִינוּן מִמִצְרַיִם תּוּקְפָא וְרוּמָא דִילֵיהּ יֵיכְלוּן בְּנֵי יִשְׂרָאֵל נִכְסֵי עַמְמַיָא סַנְאֵיהוֹן וּבְבִזַת מַלְכֵּיהוֹן יִתְפַּנְקוּן וְאַרְעֲתְהוֹן יַחְסְנוּן:
@851 יְנוּחַ יִשְׁרֵי בִתְקוֹף כְּאַרְיָא וּכְלֵתָא לֵית מַלְכוּ דְתִזַעֲזְעִינֵיהּ בְּרִיכָךְ יְהוֹן בְּרִיכִין וְלִיטָךְ יְהוֹן לִיטִין:
@852 וּתְקֵיף רוּגְזָא דְבָלָק בְּבִלְעָם וּשְׁקָפִינוּן לִידוֹהִי וַאֲמַר בָּלָק לְבִלְעָם לְמֵילַט סַנְאַי קְרִיתָךְ וְהָא בָּרָכָא מְבָרְכַת לְהוֹן דְנַן תְּלַת זִמְנִין:
@853 וּכְעַן אִזֵיל לָךְ לְאַתְרָךְ אֲמָרִית יְקָרָא אֲיַקְרִינָךְ וְהָא מְנָעָךְ יְיָ מִן יְקָר:
@854 וַאֲמַר בִּלְעָם לְבָלָּק הֲלָא אַף לְאִזְגַדָךְ דִי שַׁלְחַת לְוָתִי מַלֵילִית לְמֵימָר:
@855 אִם יִתֶּן לִי בָלָק מְלֵי בֵיתֵיהּ כְּסַף וּדְהַב לֵית לִי רְשׁוּ לְמֶעֱבַּר עַל גְזֵירַת מֵימְרָא דַיְיָ לְמֶעֱבַּד טַבְתָּא אוֹ בִּישְׁתָּא מֵרְעוּתִי דִי יְמַלֵל יְיָ יָתֵיהּ אֲמַלֵיל:
@856 וּכְעַן הָא אֲנָא אָזֵיל לְעַמִי אִיתָא אֲמַלְכִינָךְ מָה דְתַּעְבֵיד וַאֲחַוֵי לָךְ מָא דְיַעֲבֵד עַמָא הָדֵין לְעַמָךְ בְּסוֹף יוֹמַיָא:
@857 וּנְטַל מַתְלֵיהּ וַאֲמַר אֵימַר בִּלְעָם בְּרֵיהּ בְעוֹר וְאֵימַר גַבְרָא דְשַׁפִּיר חָזֵי:
@858 אֵימַר דִשְׁמַע מֵימַר מִן קֳדָם אֵל וִידַע מַדַע מִן קֳדָם עִילָאָה חֵיזוּ מִן קֳדָם שַׁדַי חָזֵי שְׁכִיב וּמִתְגְלֵי לֵיהּ:
@859 חֲזִיתֵיהּ וְלָא כְעַן סְכִיתֵיהּ וְלָא אִיתוֹהִי קָרִיב כַּד יְקוּם מַלְכָּא מִיַעֲקֹב וְיִתְרַבָּא מְשִׁיחָא מִיִשְׂרָאֵל וְיִקְטּוֹל רַבְרְבֵי מוֹאָב וְיִשְׁלוֹט בְּכָל בְּנֵי אֱנָשָׁא:
@860 וִיהֵי אֱדוֹם יְרוּתָּא וִיהֵי יְרוּתָּא שֵׂעִיר לְבַעֲלֵי דְבָבוֹהִי וְיִשְׂרָאֵל יַצְלַח בְּנִכְסִין:
@861 וְיֵיחוּת חָד מִדְבֵית יַעֲקֹב וְיוֹבִיד מְשֵׁיזִיב מִקִרְיַת עַמְמַיָא:
@862 וַחֲזָא יַת עֲמַלְקָאָה וּנְטַל מַתְלֵיהּ וַאַמַר רֵישׁ קְרָבַיָא דְיִשְׂרָאֵל הֲוָה עֲמַלְקָאָה וְסוֹפֵיהּ לְעָלְמָא יֵיבָד:
@863 וַחֲזָא יַת שַׁלְמָאָה וּנְטַל מַתְלֵיהּ וַאֲמַר תַּקִיף בֵּית מוֹתְבָךְ וְשַׁוֵי בִכְרַךְ תַּקִּיף מְדוֹרָךְ:
@864 אֲרֵי אִם יְהֵי לְשֵׁיצָאָה שַׁלְמָאָה עַד מָה אֲתוּרָאָה יִשְׁבִּינָךְ:
@865 וּנְטַל מַתְלֵיהּ וַאֲמַר וַי לְחַיָיבַיָא דְיֵחוֹן כַּד יַעֲבֵּד אֱלָהָא יָת אִלֵין:
@866 וְסִיעַן יִצְטַרְחַן מֵרוֹמָאֵי וִיעֲנוּן לְאָתוּר וְיִשְׁתַּעְבְּדוּן לְעֵבַר פְּרָת וְאַף אִינוּן לְעָלְמָא יֵיבְדוּן:
@867 וְקָם בִּלְעָם וַאֲזַל וְתָב לְאַתְרֵיהּ וְאַף בָּלָק אֲזַל לְאוֹרְחֵיהּ:
@868 וִיתֵיב יִשְׂרָאֵל בְּשִׁיטִין וּשְׁרֵי עַמָא לְמִטְּעֵי בָּתַר בְּנַת מוֹאָב:
@869 וּקְרָאָן לְעַמָא לְדִבְחֵי טַעֲוַתְהוֹן וַאֲכַל עַמָא וּסְגִידוּ לְטַעֲוַתְהוֹן:
@870 וְאִתְחַבַּר יִשְׂרָאֵל לְבַעֲלָא פְעוֹר וּתְקֵף רוּגְזָא דַיְיָ בְּיִשְׂרָאֵל:
@871 וַאֲמַר יְיָ לְמשֶׁה דְבַר יַת כָּל רֵישֵׁי עַמָא וְדוּן וּקְטוֹל דְחַיָב קְטוֹל קֳדָם יְיָ לָקֳבֵל שִׁמְשָׁא וִיתוּב תְּקוֹף רוּגְזָא דַיְיָ מִיִשְׂרָאֵל:
@872 וַאֲמַר משֶׁה לְדַיָנֵי יִשְׂרָאֵל קְטִילוּ גְבַר גַבְרוֹהִי דְאִתְחַבָּרוּ לְבַעֲלָא פְעוֹר:
@873 וְהָא גַבְרָא מִבְּנֵי יִשְׂרָאֵל אֲתָא וְקָרֵב לְוָת אֲחוֹהִי יָת מִדְיָנֵיתָא לְעֵינֵי משֶׁה וּלְעֵינֵי כָּל כְּנִשְׁתָּא דִבְנֵי יִשְׂרָאֵל וְאִינוּן בָּכָן בִּתְרַע מַשְׁכַּן זִמְנָא:
@874 וַחֲזָא פִּינְחָס בַּר אֶלְעָזָר בַּר אַהֲרֹן כַּהֲנָא וְקָם מִגוֹ כְנִשְׁתָּא וּנְסֵיב רוֹמְחָא בִידֵיהּ:
@875 וְעַל בָּתַר גַבְרָא בַּר יִשְׂרָאֵל לְקוּבָּתָא וּבְזַע יַת תַּרְוֵיהוֹן יַת גַבְרָא בַּר יִשְׂרָאֵל וְיַת אִתְּתָא לִמְעָהָא וְאִתְכְּלִי מוֹתָנָא מֵעַל בְּנֵי יִשְׂרָאֵל:
@876 וַהֲווֹ דְמִיתוּ בְּמוֹתָנָא עַשְׂרִין וְאַרְבְּעָה אַלְפִין: פפפ:
@877 וּמַלִיל יְיָ עִם משֶׁה לְמֵימָר:
@878 פִּינְחָס בַּר אֶלְעָזָר בַּר אַהֲרֹן כַּהֲנָא אֲתֵיב יַת חֵמְתִי מֵעַל בְּנֵי יִשְׂרָאֵל בִּדְקַנֵי יַת קִנְאָתִי בֵּינֵיהוֹן וְלָא שֵׁיצֵיתִי יַת בְּנֵי יִשְׂרָאֵל בְּקִנְאָתִי:
@879 בְּכֵן אֵימַר הָא אֲנָא גְזַר לֵיהּ יַת קְיָמִי שְׁלָם:
@880 וּתְהֵי לֵיהּ וְלִבְנוֹהִי בַּתְרוֹהִי קְיַם כְּהֻנַת עֲלָם חֲלַף דִי קַנֵי קֳדָם אֱלָהֵהּ וְכַפֵּר עַל בְּנֵי יִשְׂרָאֵל:
@881 וְשׁוּם גַבְרָא בַּר יִשְרָאֵל קְטִילָא דִי אִתְקְטֵל עִם מִדְיָנֵיתָא זִמְרִי בַּר סָלוּא רַב בֵּית אַבָּא לְבֵית שִׁ מְעוֹן:
@882 וְשׁוּם אִתְּתָא דְאִתְקְטִילַת מִדְיָנֵיתָא כָּזְבִּי בַּת צוּר רֵישׁ אוּמֵי בֵּית אַבָּא בְּמִדְיָן הוּא:
@883 וּמַלִיל יְיָ עִם משֶׁה לְמֵימָר:
@884 אָעֵק יַת מִדְיָנָאֵי וְתִקְטְלוּן יָתְהוֹן:
@885 אֲרֵי מְעִיקִין אִינוּן לְכוֹן בְּנִכְלֵיהוֹן דִי נְכִילוּ לְכוֹן עַל עֵיסַק פְּעוֹר וְעַל עֵיסַק כָּזְבִּי בַּת רַבָּא דְמִדְיָן אֲחַתְהוֹן דְאִתְקְטִילַת בְּיוֹמָא דְמוֹתָנָא עַל עֵיסַק פְּעוֹר:
@887 וַהֲוָה בָּתַר מוֹתָנָא וַאֲמַר יְיָ לְמשֶׁה וּלְאֶלְעָזָר בַּר אַהֲרֹן כַּהֲנָא לְמֵימָר:
@888 קַבִּילוּ יַת חוּשְׁבַּן כָּל כְּנִשְׁתָּא דִבְנֵי יִשְׂרָאֵל מִבַּר עַשְׂרִין שְׁנִין וּלְעֵילָא לְבֵית אֲבָהַתְהוֹן כָּל נָפֵיק חֵילָא בְּיִשְׂרָאֵל:
@889 וּמַלִיל משֶׁה וְאֶלְעָזָר כַּהֲנָא וַאֲמָרוּ לְמִמְנֵי יָתְהוֹן בְּמֵישְׁרַיָא דְמוֹאָב עַל יַרְדְנָא דִירִיחוֹ לְמֵימָר:
@890 מִבַּר עַשְׂרִין שְׁנִין וּלְעֵילָא כְּמָא דְפַקֵיד יְיָ יָת משֶׁה וּבְנֵי יִשְׂרָאֵל דִנְפָקוּ מֵאַרְעָא דְמִצְרָיִם:
@891 רְאוּבֵן בּוּכְרָא דְיִשְׂרָאֵל בְּנֵי רְאוּבֵן חֲנוֹךְ זַרְעִית חֲנוֹךְ לְפַלוּא זַרְעִית פַּלוּא:
@892 לְחֶצְרוֹן זַרְעִית חֶצְרוֹן לְכַרְמִי זַרְעִית כַּרְמִי:
@893 אִלֵין זַרְעֲיַת רְאוּבֵן וַהֲווֹ מִנְיָנֵיהוֹן אַרְבְּעִין וּתְלָתָא אַלְפִין וּשְׁבַע מְאָה וּתְּלָתִין:
@894 וּבְנֵי פַלוּא אֱלִיאָב:
@895 וּבְנֵי אֱלִיאָב נְמוּאֵל וְדָתָן וַאֲבִירָם הוּא דָתָן וַאֲבִירָם מְעַרְעֵי כְּנִשְׁתָּא דְאִתְכְּנָשׁוּ עַל משֶׁה וְעַל אַהֲרֹן בִּכְנִשְׁתָּא דְקֹרַח בְּאִתְכַּנוֹשֵׁיהוֹן עַל יְיָ:
@896 וּפְתָחַת אַרְעָא יַת פּוּמָהּ וּבְלָעַת יָתְהוֹן וְיָת קֹרַח בְּמוֹתָא דִכְנִשְׁתָּא כַּד אֲכָלַת אֵשָׁתָא יַת מָאתָן וְחַמְשִׁין גַבְרָא וַהֲווֹ לְאָת:
@897 וּבְנֵי קֹרַח לָא מִיתוּ:
@898 בְּנֵי שִׁמְעוֹן לְזַרְעֲיַתְהוֹן לִנְמוּאֵל זַרְעִית נְמוּאֵל לְיָמִין זַרְעִית יָמִין לְיָכִין זַרְעִית יָכִין:
@899 לְזֶרַח זַרְעִית זֶרַח לְשָׁאוּל זַרְעִית שָׁאוּל:
@900 אִלֵין זַרְעֲיַת שִׁמְעוֹן עַשְׂרִין וּתְרֵין אַלְפִין וּמָאתָן:
@901 בְּנֵי גָד לְזַרְעֲיַתְהוֹן לִצְפוֹן זַרְעִית צְפוֹן לְחַגִי זַרְעִית חַגִי לְשׁוּנִי זַרְעִית שׁוּנִי:
@902 לְאָזְנִי זַרְעִית אָזְנִי לְעֵרִי זַרְעִית עֵרִי:
@903 לַאֲרוֹד זַרְעִית אֲרוֹדִי לְאַרְאֵלִי זַרְעִית אַרְאֵלִי:
@904 אִלֵין זַרְעֲיַת בְּנֵי גָד לְמִנְיָנֵהוֹן אַרְבְּעִין אַלְפִין וַחֲמֵשׁ מְאָה:
@905 בְּנֵי יְהוּדָה עֵר וְאוֹנָן וּמִית עֵר וְאוֹנָן בְּאַרְעָא דִכְנָעַן:
@906 וַהֲווֹ בְנֵי יְהוּדָה לְזַרְעֲיַתְהוֹן לְשֵׁלָה זַרְעִית שֵׁלָה לְפֶרֶץ זַרְעִית פֶּרֶץ לְזֶרַח זַרְעִית זָרַח:
@907 וַהֲווֹ בְנֵי פֶרֶץ לְחֶצְרוֹן זַרְעִית חֶצְרוֹן לְחָמוּל זַרְעִית חָמוּל:
@908 אִלֵין זַרְעֲיַת יְהוּדָה לְמִנְיָנֵיהוֹן שִׁבְעִין וְשִׁתָּא אַלְפִין וַחֲמֵשׁ מְאָה:
@909 בְּנֵי יִשָשׂכָר לְזַרְעֲיַתְהוֹן תּוֹלָע זַרְעִית תּוֹלָע לְפֻוָה זַרְעִית פּוּנִי:
@910 לְיָשׁוּב זַרְעִית יָשׁוּב לְשִׁמְרוֹן זַרְעִית שִׁמְרוֹן:
@911 אִלֵין זַרְעֲיַת יִשָׂשׂכָר לְמִנְיָנֵיהוֹן שִׁתִּין וְאַרְבְּעָה אַ:לפִין וּתְלַת מְאָה:
@912 בְּנֵי זְבוּלוּן לְזַרְעֲיַתְהוֹן לְסֶרֶד זַרְעִית סֶרֶד לְאֵלוֹן זַרְעִית אֵלוֹן לְיַחְלְאֵל זַרְעִית יַחְלְאֵל:
@913 אִלֵין זַרְעֲיַת זְבוּלוּן לְמִנְיָנֵיהוֹן שִׁתִּין אַלְפִין:וְחֲמֵשׁ מְאָה:
@914 בְּנֵי יוֹסֵף לְזַרְעֲיַתְהוֹן מְנַשֶׁה וְאֶפְרָיִם:
@915 בְּנֵי מְנַשֶׁה לְמָכִיר זַרְעִית מָכִיר וּמָכִיר אוֹלִיד יַת גִלְעָד לְגִלְעָד זַרְעִית גִלְעָד:
@916 אִלֵין בְּנֵי גִלְעָד אִיעֶזֶר זַרְעִית אִיעֶזֶר לְחֵלֶק זַרְעִית חֵלֶק:
@917 וְאַשְׂרִיאֵל זַרְעִית אַשְׂרִיאֵלִי וְשֶׁכֶם זַרְעִית שֶׁכֶם:
@918 וּשְׁמִידָע זַרְעִית שְׁמִידָע וְחֵפֶר זַרְעִית חֵפֶר:
@919 וּצְלָפְחָד בַּר חֵפֶר לָא הֲווֹ לֵיהּ בְּנִין אֱלָהֵין בְּנָן וְשׁוּם בְּנַת צְלָפְחָד מַחְלָה וְנוֹעָה חָגְלָה מִלְכָּה וְתִרְצָה:
@920 אִלֵין זַרְעֲיַת מְנַשֶׁה וּמִנְיָנֵיהוֹן חַמְשִׁין וּתְרֵין אַלְפִין וּשְׁבַע מְאָה:
@921 אִלֵין בְּנֵי אֶפְרַיִם לְזַרְעֲיַתְהוֹן לְשׁוּתֶלַח זַרְעִית שׁוּתֶלַח לְבֶכֶר זַרְעִית בֶּכֶר לְתַחַן זַ:רעִית תַּחַן:
@922 וְאִלֵין בְּנֵי שׁוּתָלַח לְעֵרָן זַרְעִית עֵרָן:
@923 אִלֵין זַרְעֲיַת בְּנֵי אֶפְרַיִם לְמִנְיָנֵיהּוֹן תְּלָתִין וּתְרֵין אַלְפִין וַחֲמֵשׁ מְאָה אִלֵין בְּנֵי יוֹסֵף לְזַרְעֲיַתְהּוֹן:
@924 בְּנֵי בִנְיָמִין לְזַרְעֲיַתְהוֹן לְבֶלַע זַרְעִית בֶּלַע לְאַשְׁבֵּל זַרְעִית אַשְׁבֵּל לַאֲחִירָם זַרְעִית אֲחִירָם:
@925 לִשְׁפוּפָם זַרְעִית שְׁפוּפָם לְחוּפָם זַרְעִית חוּפָם:
@926 וַהֲווֹ בְנֵי בֶלַע אַרְדְ וְנַעֲמָן זַרְעִית הָאַרְדִי לְנַעֲמָן זַרְעִית נַעֲמִי:
@927 אִלֵין בְּנֵי בִנְיָמִן לְזַרְעֲיַתְהוֹן וּמִנְיָנֵיהוֹן אַרְבְּעִין וְחַמְשָׁא אַלְפִין וְשִׁית מְאָה:
@928 אִלֵין בְּנֵי דָן לְזַרְעֲיַתְהוֹן לְשׁוּחָם זַרְעִית שׁוּחָם אִלֵין זַרְעֲיַת דָן לְזַרְעֲיַתְהוֹן:
@929 כָל זַרְעֲיַת שׁוּחָם לְמִנְיָנֵיהוֹן שִׁתִּין וְאַרְבַּע אַלְפִין וְאַרְבַּע מְאָה:
@930 בְּנֵי אָשֵׁר לְזַרְעֲיַתְהוֹן לְיִמְנָה זַרְעִית יִמְנָה לְיִשְׁוִי זַרְעִית יִשְׁוִי לִבְרִיעָה זַרְעִית בְּרִיעָה:
@931 לִבְנֵי בְרִיעָה לְחֵבֶר זַרְעִית חֵבֶר לְמַלְכִּיאֵל זַרעִית מַלְכִּיאֵל:
@932 וְשׁוּם:בַּת אָשֵׁר סָרַח:
@933 אִלֵין זַרְעֲיַת בְּנֵי אָשֵׁר לְמִנְיָנֵיהוֹן חַמְשִׁין וּתְלָתָא אַלְפִין:ואַ:רבַּע מְאָה:
@934 בְּנֵי נַפְתָּלִי לְזַרְעֲיַתְהוֹן לְיַחְצְאֵל זַרְעִית יַחְצְאֵל לְגוּנִי זַרְעִית גוּנִי:
@935 לְיֵצֶר זַרְעִית יֵצֶר לְשִׁלֵם זַרְעִית שִׁלֵם:
@936 אִלֵין זַרְעֲיַת נַפְתָּלִי לְזַרְעֲיַתְהוֹן וּמִנְיָנֵיהוֹן אַרְבְּעִין וְחַמְשָׁא אַלְפִין וְאַרְבַּע מֵאָה:
@937 אִלֵין מִנְיָנֵי בְּנֵי יִשְׂרָאֵל שִׁית מְאָה וְחַד אַלְפִין שְׁבַע מְאָה וּתְלָתִין:
@938 וּמַלֵיל יְיָ עִם משֶׁה לְמֵימָר:
@939 לְאִלֵין תִּתְפְּלֵיג אַרְעָא בְּאַחֲסָנָא בְּמִנְיַן שְׁמָהָן:
@940 לְסַגִיאֵי תִּסְגוּן אַחֲסַנְתְּהוֹן וְלִזְעֵירֵי תַּזְעֲרוּן אַחֲסַנְתְּהוֹן גְבַר לְפוּם מִנְיָנוֹהִי תִּתְיְהֵב אַחֲסַנְתֵּיהּ:
@941 בְּרַם בְּעַדְבָא תִּתְפְּלֵיג יַת אַרְעָא לִשְׁמָהָן שִׁבְטֵי אֲבָהָתְהוֹן יַחְסְנוּן:
@942 עַל פּוּם עַדְבָא תִּתְפְּלֵיג אַחֲסַנְתְּהוֹן בֵּין סַגִיאֵי לִזְעֵירֵי:
@943 וְאִלֵין מִנְיָנֵי לֵוָאֵי לְזַרְעֲיַתְהוֹן לְגֵרְשׁוֹן זַרְעִית גֵרְשׁוֹן לִּקְהָת זַרְעִית קְהָת לִמְרָרִי זַרְעִית מְרָרִי:
@944 אִלֵין זַרְעֲיַת לֵוִי זַרְעִית לִבְנִי זַרְעִית חֶבְרוֹן זַרְעִית מַחְלִי זַרְעִית מוּשִׁי זַרְעִית קֹרַח וּקְהָת אוֹלִיד יָת עַמְרָם:
@945 וְשׁוּם אִתַּת עַמְרָם יוֹכֶבֶד בַּת לֵוֵי דִילֵדַת יָתַהּ לְלֵוִי בְּמִצְרָיִם וִילֵידַת לְעַמְרָם יָת אַהֲרֹן וְיָת משֶׁה וְיָת מִרְיָם אֲחַתְהוֹן:
@946 וְאִתְיְלִיד לְאַהֲרֹן יַת נָדָב וְיַת אֲבִיהוּא יַת אֶלְעָזָר וְיַת אִיתָמָר:
@947 וּמִית נָדָב וַאֲבִיהוּא בְּקָרוֹבֵיהוֹן אֶשָׁתָא נוּכְרֵיתָא קֳדָם יְיָ:
@948 וַהֲווֹ מִנְיָנֵיהוֹן עַשְׂרִין וּתְלָתָא אַלְפִין כָּל דְכוּרָא מִבַּר יַרְחָא וּלְעֵילָא אֲרֵי לָא אִתְמְנִיאוּ בְּגוֹ בְּנֵי יִשְׂרָאֵל אֲרֵי לָא אִתְיְהִיבַת לְהוֹן אַחֲסָנָא בְּגוֹ בְּנֵי יִשְׂרָאֵל:
@949 אִלֵין מִנְיָנֵי משֶׁה וְאֶלְעָזָר כַּהֲנָא דִי מְנוֹ יַת בְּנֵי יִשְׂרָאֵל בְּמֵישְׁרַיָא דְמוֹאָב עַל יַרְדְנָא דִירֵיחוֹ:
@950 וּבְאִלֵין לָא הֲוָה גְבַר מִמִנְיָנֵי משֶׁה וְאַהֲרֹן כַּהֲנָא דִי מְנוֹ יָת בְּנֵי יִשְׂרָאֵל בְּמַדְבְּרָא דְסִינָי:
@951 אֲרֵי אֲמַר יְיָ לְהוֹן מֵימַת יְמוּתוּן בְּמַדְבְּרָא וְלָא אִשְׁתְּאַר מִנְהוֹן אֱנַשׁ אֶלָהֵן כָּלֵב בַּר יְפֻנֶה וִיהוֹשֻׁעַ בַּר נוּן:
@952 וְקָרֵיבָא בְּנַת צְלָפְחָד בַּר חֵפֶר בַּר גִלְעָד בַּר מָכִיר בַּר מְנַשֶׁה לְזַרְעֲיַת מְנַשֶׁה בַּר יוֹסֵף וְאִלֵין שְׁמָהַת בְּנָתֵיהּ מַחְלָה נוֹעָה וְחָגְלָה וּמִלְכָּה וְתִרְצָה:
@953 וְקָמָן קֳדָם משֶׁה וְקֳדָם אֶלְעָזָר כַּהֲנָא וְקֳדָם רַבְרְבַיָא וְכָל כְּנִשְׁתָּא בִּתְרַע מַשְׁכַּן זִמְנָא לְמֵימָר:
@954 אָבוּנָא מִית בְּמַדְבְּרָא וְהוּא לָא הֲוָה בְּגוֹ כְנִשְׁתָּא דְאִזְדַמָנוּ עַל יְיָ בְּכְנִשְׁתָּא דְקֹרַח אֲרֵי בְחוֹבֵיהּ מִית וּבְנִין לָא הֲווֹ לֵיהּ:
@955 לְמָא יִתְמְנַע שְׁמָא דַאֲבוּנָא מִגוֹ זַרְעִיתֵיהּ אֲרֵי לֵית לֵיהּ בָּר הַב לָנָא אַחֲסָנָא בְּגוֹ אֲחֵי אָבוּנָא:
@956 וְקָרֵב משֶׁה יָת דִינְהוֹן קֳדָם יְיָ:
@957 וַאֲמַר יְיָ לְמשֶׁה לְמֵימָר:
@958 יָאוּת בְּנַת צְלָפְחָד מְמַלְלָן מִתַּן תִּתֵּן לְהוֹן אֲחוּדַת אַחֲסָנָא בְּגוֹ אֲחֵי אֲבוּהֶן וְתַעֲבַר יַת אַחֲסָנַת אֲבוּהֶן לָהֶן:
@959 וְעִם בְּנֵי יִשְׂרָאֵל תְּמַלֵיל לְמֵימָר גְבַר אֲרֵי יְמוּת וּבַר לֵית לֵיהּ וְתַעַבְרוּן יָת אַחֲסַנְתֵּיהּ לִּבְרַתֵּיהּ:
@960 וְאִם לֵית לֵיהּ בְּרַתָּא וְתִתְּנוּן יָת אַחֲסַנְתֵּיה לַאֲחוֹהִי:
@961 וְאִם לֵית לֵיהּ אַחִין וְתִתְּנוּן יָת אַחֲסַנְתֵּיהּ לְאֲחֵי אֲבוּהִי:
@962 וְאִם לֵית אַחִין לַאֲבוּהִי וְתִתְּנוּן יָת אַחֲסַנְתֵּיהּ לְקָרִיבֵיהּ דְקָרֵיבּ לֵיהּ מִזַרְעִיתֵיהּ וְיֵרַת יָתַהּ וּתְהֵי לִבְנֵי יִשְׂרָאֵל לִגְזֵירַת דִין כְּמָא דִי פַקִיד יְיָ יָת משֶׁה:
@963 וַאֲמַר יְיָ לְמשֶׁה סַק לְטוּרָא דַעֲבָרָאֵי הָדֵין וַחֲזֵי יָת אַרְעָא דִי יְהָבִית לִבְנֵי יִשִׂרָאֵל:
@964 וְתֶחֱזֵי יָתָהּ וְתִתְכְנֵּשׁ לְעַמָיךְ אַף אָתְּ כְּמָא דִי אִתְכְּנִישׁ אַהֲרֹן אָחוּךְ:
@965 כְּמָא דִסָרֵיבְתּוּן עַל מֵימְרִי בְּמַדְבְּרָא דְצִן בְּמַצוּת כְּנִשְׁתָּא לְקַדָשׁוּתִי בְמַיָא לְעֵינֵיהוֹן אִנוּן מֵי מַצוּת רְקָם מַדְבְּרָא דְצִן:
@966 וּמַלִיל משֶׁה קֳדָם יְיָ לְמֵימָר:
@967 יְמַנֵי יְיָ אֱלָהָא רוּחַיָא לְכָל בִּשְׂרָא גְבַר עַל כְּנִשְׁתָּא:
@968 דִי יִפּוֹק קֳדָמֵיהוֹן וְדִי יֵעוֹל קֳדָמֵיהוֹן וְדִי יַפֵּקִנוּן וְדִי יָעֵלִינוּן וְלָא תְהֵי כְּנִשְׁתָּא דַיְיָ כְּעָנָא דִי לֵית לְהֵן רָעֵי:
@969 וַאֲמַר יְיָ לְמשֶׁה דְבַר לָךְ יָת יְהוֹשֻׁעַ בַּר נוּן גְבַר דִי רוּחַ נְבוּאָה בֵּיהּ וְתִסְמוֹךְ יָת יְדָךְ עֲלוֹהִי:
@970 וּתְקֵים יָתֵיהּ לָקֳדָם אֶלְעָזָר כַּהֲנָא וְלָקֳדָם כָּל כְּנִשְׁתָּא וּתְפַקֵד יָתֵיהּ לְעֵינֵיהוֹן:
@971 וְתִתֵּן מִזִיוָךְ עֲלוֹהִי בְּדִיל דִי יְקַבְּלוּן מִנֵיהּ כָּל כְּנִשְׁתָּא דִבְנֵי יִשְׂרָאֵל:
@972 וְלִקֳדָם אֶלְעָזָר כַּהֲנָא יְקוּם וְיִשְׁאַל לֵיהּ בְּדִין אוּרַיָא קֳדָם יְיָ עַל מֵימְרֵיהּ יְהוֹן נַפְקִין וְעַל מֵימְרֵא יְהוֹן עָאלִין הוּא וְכָל בְּנֵי יִשְׂרָאֵל עִמֵיהּ וְכָל כְּנִשְׁתָּא:
@973 וַעֲבַד משֶׁה כְּמָא דִי פַקֵיד יְיָ יָתֵיהּ וּדְבַר יָת יְהוֹשֻׁע וַאֲקִימֵיהּ קֳדָם אֶלְעָזָר כַּהֲנָא וּקְדָם כָּל כְּנִשְׁתָּא:
@974 וּסְמַךְ יָת יְדוֹהִי עֲלוֹהִי וּפַקְדֵיהּ כְּמָא דִי מַלִיל יְיָ בִּידָא דְמשֶׁה:
@975 וּמַלֵיל יְיָ עִם משֶׁה לְמֵימָר:
@976 פַקֵיד יָת בְּנֵי יִשְׂרָאֵל וְתֵימַר לְהוֹן יָת קוּרְבָּנִי לְחֵם סִדוּר לְקוּרְבָּנַי לְאִתְקַבָּלָא בְּרַעֲוָא תִּטְרוּן לְקָרָבָא קֳדָמַי בְּזִמְנֵיהּ:
@977 וְתֵימַר לְהוֹן דֵין קוּרְבָּנָא דִי תְקַרְבוּן קֳדָם יְיָ אִימְּרִין בְּנֵי שְׁנָא שַׁלְמִין תְּרֵין לְּיוֹמָא עֲלָתָא תְּדִירָא:
@978 יָת אִמְרָא חָד תַּעֲבֵד בְּצַפְרָא וְיָת אִמְרָא תִנְיָנָא תַּעֲבֵד בֵּין שִׁמְשַׁיָא:
@979 וְחָד מִן עַשְׂרָא בִּתְלַת סָאִין סוּלְתָּא לְמִנְחָתָא דְפִילָא בִּמְשַׁח כְּתִישָׁא רַבְעוּת הִינָא:
@980 עֲלָתָא תְּדִירָא דְאִתְעֲבִידָא בְּטוּרָא דְסִינַי לְאִתְקַבָּלָא בְרַעֲוָא קוּרְבָּנָא קֳדָם יְיָ:
@981 וְנִסְכֵּיהּ רַבְעוּת הִינָא לְאִמְרָא חָד בְּקוּדְשָׁא יִתְנַסַךְ נִסוּךְ דַחֲמַר עַתִּיק קֳדָם יְיָ:
@982 וְיָת אִמְרָא תִנְיָנָא תַּעֲבֵיד בֵּין שִׁמְשַׁיָא כְּמִנְחַת צַפְרָא וּכְנִסְכֵּיהּ תַּעְבֵיד קוּרְבַּן דְמִתְקַבֵּל בְּרַעֲוָא קֳדָם יְיָ:
@983 וּבְיוֹמָא דְשַׁבַּתָּא תְּרֵין אִימְרִין בְּנֵי שְׁנָא שַׁלְמִין וּתְרֵין עִשְׂרוֹנִין סוּלְתָּא דְמִנְחָתָא דְפִילָא בִּמְשַׁח וְנִסְכֵּיהּ:
@984 עֲלַת שַׁבְּתָא דְתִּתְעֲבֵיד בְּשַׁבַּתָּא עַל עֲלָתָא תְּדִירָא וְנִסְכַּהּ:
@985 וּבְרֵישֵׁי יַרְחֵיכוֹן תְּקַרְבוּן עֲלָתָא קֳדָם יְיָ תּוֹרִין בְּנֵי תּוֹרֵי תְּרֵין וּדְכַר חָד אִימְרִין בְּנֵי שְׁנָא שַׁבְעָא שַׁלְמִין:
@986 וּתְלָתָא עִשְׂרוֹנִין סוּלְתָּא מִנְחָתָא דְפִילָא בִמְשַׁח לְתוֹרָא חָד וּתְרֵין עִשְׂרוֹנִין סֻלְתָּא מִנְחָתָא דְפִילָא בִמְשַׁח לְדִכְרָא חָד:
@987 וְעִשְׂרוֹנָא עִשְׂרוֹנָא סֻלְתָּא מִנְחָתָא דְפִילָא בִמְשַׁח לְאִמְרָא חָד עֲלָתָא לְאִתְקַבָּלָא בְּרַעֲוָא קוּרְבָּנָא קֳדָם יְיָ:
@988 וְנִסְכֵּיהוֹן פַּלְגוּת הִינָא יְהֵי לְתוֹרָא וְתַלְתּוּת הִינָא לְדִכְרָא וְרַבְעוּת הִינָא לְאִמְרָא חַמְרָא דָא עֲלַת רֵישׁ יַרְחָא בְּאִתְחַדָתוּתֵיהּ כֵּן לְכָל רֵישֵׁי יַרְחֵי שַׁתָּא:
@989 וּצְפִיר בַּר עִזִין חָד לְחַטָאתָא קֳדָם יְיָ עַל עֲלָתָא תְּדִירָא יִתְעֲבֵד וְנִסְכֵּיהּ:
@990 וּבְיַרְחָא קַדְמָאָה בְּאַרְבַּעַת עַשְׂרָא יוֹמָא לְיַרְחָא פִּסְחָא קֳדָם יְיָ:
@991 וּבְחַמְשַׁת עַשְׂרָא יוֹמָא לְיַרְחָא הָדֵין חַגָא שַׁבְעָא יוֹמִין פַּטִיר יִתְאָכֵל:
@992 בְּיוֹמָא קַדְמָאָה מְעָרַע קַדִישׁ כָּל עֲבִידַת פּוּלְחַן לָא תַעְבְדוּן:
@993 וּתְקַרְבוּן קוּרְבָּנָא עֲלָתָא קֳדָם יְיָ תּוֹרִין בְּנֵי תוֹרֵי תְּרֵין וּדְכַר חָד וְשַׁבְעָא אִימְרִין בְּנֵי שְׁנָא שַׁלְמִין יְהוֹן לְכוֹן:
@994 וּמִנְחַתְהוֹן סוּלְתָּא דְפִילָא בִּמְשַׁח תְּלָתָא עִשְׂרוֹנִין לְתוֹרָא וּתְרֵין עִשְׂרוֹנִין לְדִכְרָא תַּעְבְּדוּן:
@995 עִשְׂרוֹנָא עִשְׂרוֹנָא תַּעֲבֵיד לְאִמְרָא חָד כֵּן לְשַׁבְעָא אִימְרִין:
@996 וּצְפִירָא דְחַטָאתָא חָד לְכַפָּרָא עֲלֵיכוֹן:
@997 בַּר מֵעֲלַת צַפְרָא דְהִּיא עֲלַת תְּדִירָא תַּעְבְּדוּן יָת אִלֵין:
@998 כְּאִלֵין תַּעַבְדוּן לְיוֹמָא שַׁבְעָא יוֹמִין לְחֵם קוּרְבַּן דְמִתְקַבֵּל בְּרַעֲוָא קֳדָם יְיָ עַל עֲלָתָא תְדִירָא יִתְעֲבֵיד וִנִסִכֵּיהּ:
@999 וּבְיוֹמָא שְׁבִיעָאָה מְעָרַע קַדִישׁ יְהֵי לְכוֹן כָּל עִיבִידַת פּוּלְחַן לָא תַעַבְדוּן:
@1000 וּבְיוֹמָא דְבִכּוּרַיָא בְּקָרוֹבֵיכוֹן מִנְחֲתָא חֲדַתָּא קֳדָם יְיָ בְּעַצְרָתֵיכוֹן מְעָרַע קַדִישׁ יְהֵי לְכוֹן כָּל עִבִידַת פּוּלְחַן לָא תַעַבְדוּן:
@1001 וּתְקַרְבוּן עֲלָתָא לְאִתְקַבָּלָא בְרַעֲוָא קֳדָם יְיָ תּוֹרִין בְּנֵי תוֹרֵי תְּרֵין וּדְכַר חָד שַׁבְעָא אִימְרִין בְּנֵי שְׁנָא:
@1002 וּמִנְחַתְהוֹן סֻלְתָּא דְפִילָא בִמְשָׁח תְּלָתָא עִשְׂרוֹנִין לְתוֹרָא חָד תְּרֵין עִשְׂרוֹנִין לְדִכְרָא חָד:
@1003 עִשְׂרוֹנָא עִשְׂרוֹנָא לְאִמְרָא חָד לְשַׁבְעָא אִימְרִין:
@1004 צְפִיר בַּר עִזִין חָד לְכַפָּרָא עֲלֵיכוֹן:
@1005 בַּר מֵעֲלַת תְּדִירָא וּמִנְחָתֵהּ תַּעְבְּדוּן שַׁלְמִין יְהוֹן לְכוֹן וְנִסְכֵּיהוֹן:
@1006 וּבְיַרְחָא שְׁבִיעָאָה בְּחָד לְיַרְחָא מְעָרַע קַדִישׁ יְהֵי לְכוֹן כָּל עִבִידַת פּוּלְחַן לָא תַעַבְדוּן יוֹם יַבָּבָא יְהֵי לְכוֹן:
@1007 וְתַעַבְדוּן עֲלָתָא לְאִתְקַבָּלָא בְּרַעֲוָא קֳדָם יְיָ תּוֹר בַּר תּוֹרֵי חָד דְכַר חָד אִימְרִין בְּנֵי שְׁנָא שַׁבְעָא שַׁלְמִין:
@1008 וּמִנְחַתְהוֹן סוּלְתָּא דְפִילָא בִמְשַׁח תְּלָתָא עִשְׂרוֹנִין לְתוֹרָא תְּרֵין עִשְׂרוֹנִין לְדִכְרָא:
@1009 וְעִשְׂרוֹנָא חָד לְאִימְרָא חָד לְשַׁבְעָא אִימְרִין:
@1010 וּצְפִיר בַּר עִזִין חָד לְחַטָאתָא לְכַפָּרָא עֲלֵיכוֹן:
@1011 בַּר מֵעֲלַת יַרְחָא וּמִנְחָתַהּ וַעֲלַת תְּדִירָא וּמִנְחָתַהּ וְנִסְכֵּיהוֹן כִּדְחָזֵי לְהוֹן לְאִתְקַבָּלָא בְרַעֲוָא קוּרְבָּנָא קֳדָם יְיָ:
@1012 וּבְעַשְׂרָא לְיַרְחָא שְׁבִיעָאָה הָדֵין מְעָרַע קַדִישׁ יְהֵי לְכוֹן וּתְעַנוּן יָת נַפְשָׁתֵיכוֹן כָּל עִבִידְתָּא לָא תַעַבְדוּן:
@1013 וּתְקָרְבוּן עֲלָתָא קֳדָם יְיָ לְאִתְקַבָּלָא בְרַעֲוָא תּוֹר בַּר תּוֹרֵי חָד דְכַר חָד אִימְרִין בְּנֵי שְׁנָא שַׁבְעָא שַׁלְמִין יְהוֹן לְכוֹן:
@1014 וּמִנְחַתְהוֹן סֻלְתָּא דְפִילָא בִמְשָׁח תְּלָתָא עִשְׂרוֹנִין לְתוֹרָא תְּרֵין עִשְׂרוֹנִין לְדִכְרָא חָד:
@1015 עִשְׂרוֹנָא עִשְׂרוֹנָא לְאִימְרָא חָד לְשַׁבְעָא אִימְרִין:
@1016 צְפִיר בַּר עִזִין חָד חַטָּאתָא בַּר מֵחַטָאתָא דְכִפוּרַיָא וַעֲלַת תְּדִירָא וּמִנְחָתַהּ וְנִסְכֵּיהוֹן:
@1017 וּבְחַמְשַׁת עַשְׂרָא יוֹמָא לְיַרְחָא שְׁבִיעָאָה מְעָרַע קַדִישׁ יְהֵי לְכוֹן כָּל עִבִידַת פּוּלְחַן לָא תַעַבְדוּן וּתְחַגוּן חַגָא קֳדָם יְיָ שַׁבְעָא יוֹמִין:
@1018 וּתְקַרְבוּן עֲלָתָא קוּרְבַּן דְמִתְקַבֵּל בְּרַעֲוָא קֳדָם יְיָ תּוֹרִין בְּנֵי תוֹרֵי תְּלַת עֲשַׂר דִכְרִין תְּרֵין אִימְרִין בְּנֵי שְׁנָא אַרְבְּעָא עֲשַׂר שַׁלְמִין יְהוֹן:
@1019 וּמִנְחַתְהוֹן סוּלְתָּא דְפִילָא בִמְשַׁח תְּלָתָא עִשְׂרוֹנִין לְתוֹרָא חָד לִתְלַת עֲשַׂר תּוֹרִין תְּרֵין עִשְׂרוֹנִין לְדִכְרָא חָד לִתְרֵין דִכְרִין:
@1020 וְעִשְׂרוֹנָא עִשְׂרוֹנָא לְאִימְרָא חָד לְאַרְבְּעָא עֲשַׂר אִימְרִין:
@1021 וּצְפִיר בַּר עִזִין חָד חַטָאתָא בַּר מֵעֲלַת תְּדִירָא מִנְחָתַהּ וְנִסְכַּהּ:
@1022 וּבְיוֹמָא תִנְיָנָא תּוֹרִין בְּנֵי תוֹרֵי תְּרֵי עֲשַׂר דִכְרִין תְּרֵין אִימְרִין בְּנֵי שְׁנָא אַרְבְּעָא עֲשַׂר שַׁלְמִין:
@1023 וּמִנְחַתְהוֹן וְנִסְכֵּיהוֹן לְתוֹרִין לְדִכְרִין וּלְאִימְרִין בְּמִנְיָנֵיהוֹן כִּדְחָזֵי:
@1024 וּצְפִיר בַּר עִזִין חָד חַטָאתָא בַּר מֵעֲלַת תְּדִירָא וּמִנְחָתַהּ וְנִסְכֵּיהוֹן:
@1025 וּבְיוֹמָא תְּלִיתָאָה תּוֹרִין חָד עֲשַׂר דִכְרִין תְּרֵין אִימְרִין בְּנֵי שְׁנָא אַרְבְּעָא עֲשַׂר שַׁלְמִין:
@1026 וּמִנְחַתְהוֹן וְנִסְכֵּיהוֹן לְתוֹרִין לְדִכְרִין וּלְאִמְרִין בְּמִנְיָנֵיהוֹן כִּדְחָזֵי:
@1027 וּצְפִירָא דְחַטָאתָא חָד בַּר מֵעֲלַת תְּדִירָא וּמִנְחָתַהּ וְנִסְכַּהּ:
@1028 וּבְיוֹמָא רְבִיעָאָה תּוֹרִין עַשְׂרָא דִכְרִין תְּרֵין אִימְרִין בְּנֵי שְׁנָא אַרְבְּעָא עֲשַׂר שַׁלְמִין:
@1029 מִנְחַתְהוֹן וְנִסְכֵּיהוֹן לְתוֹרִין לְדִכְרִין וּלְאִימְרִין בְּמִנְיָנֵיהוֹן כִּדְחָזֵי:
@1030 וּצְפִיר בַּר עִזִין חָד חַטָאתָא בַּר מֵעֲלַת תְּדִירָא מִנְחָתַהּ וְנִסְכַּהּ:
@1031 וּבְיוֹמָא חֲמִישָׁאָה תּוֹרִין תְּשַׁע דִכְרִין תְּרֵין אִימְרִין בְּנֵי שְׁנָא אַרְבְּעָא עֲשַׂר שַׁלְמִין:
@1032 וּמִנְחַתְהוֹן וְנִסְכֵּיהוֹן לְתוֹרִין לְדִכְרִין וּלְאִימְרִין בְּמִנְיָנֵיהוֹן כִּדְחָזֵי:
@1033 וּצְפִירָא דְחַטָאתָא חָד בַּר מֵעֲלַת תְּדִירָא וּמִנְחָתַהּ וְנִסְכַּהּ:
@1034 וּבְיוֹמָא שְׁתִיתָאָה תּוֹרִין תְּמַנְיָא דִכְרִין תְּרֵין אִמְרִין בְּנֵי שְׁנָא אַרְבְּעָא עֲשַׂר שַׁלְמִין:
@1035 וּמִנְחַתְהוֹן וְנִסְכֵּיהוֹן לְתוֹרִין לְדִכְרִין וּלְאִימְרִין בְּמִנְיָנֵיהוֹן כִּדְחָזֵי:
@1036 וּצְפִירָא דְחַטָאתָא חָד בַּר מֵעֲלַת תְּדִירָא מִנְחָתַהּ וְנִסְכָּהָא:
@1037 וּבְיוֹמָא שְׁבִיעָאָה תּוֹרִין שַׁבְעָא דִכְרִין תְּרֵין אִימְרִין בְּנֵי שְׁנָא אַרְבְּעָא עֲשַׂר שַׁלְמִין:
@1038 וּמִנְחַתְהוֹן וְנִסְכֵּיהוֹן לְתוֹרִין לְדִכְרִין וּלְאִימְרִין בְּמִנְיָנֵיהוֹן כִּדְחָזֵי לְהוֹן:
@1039 וּצְפִירָא דְחַטָאתָא חָד בַּר מֵעֲלַת תְּדִירָא מִנְחָתָהּ וְנִסְכָּהּ:
@1040 בְּיוֹמָא תְּמִינָאָה כְּנִישִׁין תְּהֵא לְכוֹן כָּל עִבִידַת פּוּלְחַן לָא תַעְבְדוּן:
@1041 וּתְקַרְבוּן עֲלָתָא קוּרְבַּן דְמִתְקַבֵּל בְּרַעֲוָא קֳדָם יְיָ תּוֹר חָד דְכַר חָד אִמְרִין בְּנֵי שְׁנָא שַׁבְעָא שַׁלְמִין:
@1042 מִנְחַתְהוֹן וְנִסְכֵּיהוֹן לְתוֹרָא לְדִכְרָא וּלְאִימְרִין בְּמִנְיָנֵיהוֹן כִּדְחָזֵי:
@1043 וּצְפִירָא דְחַטָאתָא חָד בַּר מֵעֲלַת תְּדִירָא וּמִנְחָתַהּ וְנִסְכַּהּ:
@1044 אִלֵין תַּעְבְדוּן קֳדָם יְיָ בְּמוֹעֲדֵיכוֹן בַּר מִנִדְרֵיכוֹן וְנִדְבוֹתֵיכוֹן לְעֲלְוַתְכוֹן וּלְמִנְחַתְכוֹן וּלְנִסְכֵּיכוֹן וּלְנִכְסַת קוּדְשֵׁיכוֹן:
@1045 וַאֲמַר משֶׁה לִבְנֵי יִשְׂרָאֵל כְּכֹל דִי פַקֵיד יְיָ יָת משֶׁה: פפפ:
@1046 וּמַלִיל משֶׁה עִם רֵישֵׁי שִׁבְטַּיָא לִבְנֵי יִשְׂרָאֵל לְמֵימָר דֵין פִּתְגָמָא דִי פַקֵיד יְיָ:
@1047 גְבַר אֲרֵי יִדַר נְדַר קֳדָם יְיָ אוֹ יְקַיֵים קְיַם לְמֵיסַר אִסַר עַל נַפְשֵׁיהּ לָא יְבַטֵל פִּתְגָמֵיהּ כְּכָל דִי יִפּוֹק מִפּוּמֵיה יַעֲבֵּד:
@1048 וְאִתְּתָא אֲרֵי תִדַר נְדַר קֳדָם יְיָ וְתֵיסַר אִסָר בְּבֵית אֲבוּהָא בְּרַבְיוּתָהָא:
@1049 וְיִשְׁמַע אֲבוּהָא יָת נִדְרָהּ וְאֵסָרָהּ דִי אֲסָרַת עַל נַפְשָׁהּ וְיִשְׁתּוֹק לָהּ אֲבוּהָא וִיקוּמוּן כָּל נִדְרָהָא וְכָל אֱסָרֵי דִי אֲסָרַת עַל נַפְשָׁהּ יְקוּמוּן:
@1050 וְאִם אַעְדֵי אָבוּהָא יָתַהּ בְּיוֹמָא דִשְׁמַע כָּל נִדְרָהָא וֶאֱסָרָהָא דִי אֲסָרַת עַל נַפְשָׁהּ לָא יְקוּמוּן וּמִן קֳדָם יְיָ יִשְׁתְּבֵק לָהּ אֲרֵי אַעְדִי אֲבוּהָא יָתַהּ:
@1051 וְאִם מֶהֱוָה תֶהֱוֵי לִגְבַר וְנִדְרָהָא עֲלָהּ אוֹ פֵּירוּשׁ סִפְוָתָהָא דִי אֲסָרַת עַל נַפְשָׁהּ:
@1052 וְיִשְׁמַע בַּעֲלַהּ בְּיוֹמָא דִשְׁמַע וְיִשְׁתּוֹק לַהּ וִיקוּמוּן נִדְרָהָא וֶאֱסָרָהָא דִי אֲסָרַת עַל נַפְשַׁהּ יְקוּמוּן:
@1053 וְאִם בְּיוֹמָא דִשְׁמַע בַּעֲלַהּ אַעְדִי יָתַהּ וִיבַטֵּל יָת נִדְרָהָא דִי עֲלַהּ וְיָת פֵּירוּשׁ סִפְוָתָהָא דִי אֲסָרַת עַל נַפְשַׁהּ וּמִן קֳדָם יְיָ יִשְׁתְּבֵק לַהּ:
@1054 וּנְדַר אַרְמְלָא וּמְתַרְכָא כֹּל דִי אֲסָרַת עַל נַפְשַׁהּ יְקוּם עֲלַהּ:
@1055 וְאִם בֵּית בַּעֲלַהּ נְדָרַת אוֹ אֲסָרַת אִסַר עַל נַפְשַׁהּ בְּקִיוּם:
@1056 וְיִשְׁמַע בַּעֲלַהּ וְיִשְׁתּוֹק לַהּ לָא אַעֲדֵי יָתַהּ וִיקוּמוּן כָּל נִדְרָהָא וְכָל אֱםָרֵי דִי אֲסָרַת עַל נַפְשַׁהּ יְקוּמוּן:
@1057 וְאִם בַּטָלָא יְבַטֵל יָתְהוֹן בַּעֲלַהּ בְּיוֹמָא דִשְׁמַע כָּל אַפָּקוּת סִפְוָתָהָא לְנִדְרָהָא וּלְאִסַר נַפְשַׁהּ לָא יְקוּמוּן בַּעֲלַהּ בְּטֵלִינוּן וּמִן קֳדָם יְיָ יִשְׁתְּבֵק לַהּ:
@1058 כָּל נְדַר וְכָל קִיוּמַת אִסַר לְסַגָפָא נְפָשׁ בַּעֲלַהּ יְקַיְמִינוּן וּבַעֲלַהּ יְבַטְלִינוּן:
@1059 וְאִם מִשְׁתַּק יִשְׁתּוֹק לַהּ בַּעֲלַהּ מִיוֹם לְיוֹם וִיקַיֵים יָת כָּל נִדְרָהָא אוֹ יָת כָּל אֱסָרָהָא דִי עֲלָהּ קַיֵים יָתְהוֹן אֲרֵי שָׁתֵק לַהּ בְּיוֹמָא דִשְׁמָע:
@1060 וְעִם בַּטָלָא יְבַטֵּל יָתְהוֹן בָּתַר דִשְׁמָע וִיקַבַּל יָת חוֹבַהּ:
@1061 אִלֵין קְיָמַיָא דִי פַקֵיד יְיָ יָת משֶׁה בֵּין גְבַר לְאִתְּתֵיהּ בֵּין אַבָּא לִבְרַתֵּיהּ בְּרַבְיוּתָהָא בֵּית אָבוּהָא:
@1062 וּמַלֵיל יְיָ עִם משֶׁה לְמֵימָר:
@1063 אִתְפְּרַע פֻּרְעֲנוּת בְּנֵי יִשְׂרָאֵל מִן מִדְיָנָאֵי בָּתַר כֵּן תִּתְכְּנֵישׁ לְעַמָּךְ:
@1064 וּמַלֵיל משֶׁה עִם עַמָא לְמֵימָר זְרִיזוּ מִנְכוֹן גֻבְרִין לְחֵילָא וִיהוֹן עַל מִדְיָן לְמִתַּן פּוּרְעֲנוּת דִין עַמָא דַיְיָ בְּמִדְיָן:
@1065 אַלְפָא לְשִׁבְטָא אַלְפָא לְשִׁבְטָּא לְכֹל שִׁבְטַיָא דְיִשְֹׁרָאֵל תְּשַׁלְחוּן לְחֵילָא:
@1066 וְאִתְבְּחָרוּ מֵאַלְפַיָא דְיִֹשְׂרָאֵל אַלְפָא לְשִׁבְטָא תְּרֵי עֲֹשַׂר אַלְפִין מְזָרְזֵי חֵילָא:
@1067 וּשְׁלַח יָתְהוֹן משֶׁה אַלְפָא לְשִׁבְטָא לְחֵילָא יָתְהוֹן וְיָת פִּינְחָס בַּר אֶלְעָזָר כַּהֲנָא לְחֵילָא וּמָנֵי דְקוּדְשָׁא וַחֲצוֹצְרוֹת יַבֶּבְתָּא בִּידֵיהּ:
@1068 וְאִתְחַיָילוּ עַל מִדְיָן כְּמָא דְפַקֵיד יְיָ יָת משֶׁה וּקְטָלוּ כָּל דְכוּרָא:
@1069 וְיָת מַלְכֵי מִדְיָן קְטָלוּ עַל קְטִילֵיהוֹן יָת אֱוִי וְיָת רֶקֶם וְיָת צוּר וְיָת חוּר וְיָת רֶבַע חַמְשָׁא מַלְכֵי מִדְיָן וְיָת בִּלְעָם בַּר בְּעוֹר קְטָלוּ בְּחַרְבָּא:
@1070 וּשְׁבוֹ בְנֵי יִשְׂרָאֵל יָת נְשֵׁי מִדְיָן וְיָת טַּפְלְהוֹן וְיָת כָּל בְּעִירְהוֹן וְיָת כָּל גֵיתֵיהוֹן וְיָת כָּל נִכְסֵיהוֹן בְּזוֹ:
@1071 וְיָת כָּל קִרְוֵיהוֹן בְּמוֹתְבָנֵיהוֹן וְיָת כָּל בֵּית סִגְדַתְהוֹן אוֹקִידוּ בְּנוּרָא:
@1072 וּנְסִיבוּ יָת כָּל עֲדָאָה וְיָת כָּל דְבַרְתָּא בֶּאֱנָשָׁא וּבִבְעִירָא:
@1073 וְאַיתִיוּ לְוָת משֶׁה וּלְוָת אֶלְעָזָר כַּהֲנָא וּלְוָת כְּנִשְׁתָּא דִבְנֵי יִשְׂרָאֵל יָת שִׁבְיָא וְיָת דְבַרְתָּא וְיָת עֲדָאָה לְמַשְׁרִיתָא לְמֵישְׁרַיָא דְמוֹאָב דִי עַל יַרְדְנָא דִירֵחוֹ:
@1074 וּנְפָקוּ משֶׁה וְאֶלְעָזָר כַּהֲנָא וְכָל רַבְרְבֵי כְנִשְׁתָּא לְקֳדָמוּתְהוֹן לְמִבָּרָא לְמַשְׁרִיתָא:
@1075 וּרְגֵיז משֶׁה עַל דִמְמַנָן עַל חֵילָא רַבָּנֵי אַלְפִין וְרַבָּנֵי מַאֲוָותָא דְאָתוּ מֵחֵיל קְרָבָא:
@1076 וַאֲמַר לְהוֹן משֶׁה הֲקַיֵמְתּוּן כָּל נוּקְבָא:
@1077 הָא אִינוּן הֲוָאָה לִבְנֵי יִשְׂרָאֵל בַּעֲצַת בִּלְעָם לְשַׁקָרָא שְׁקָר קֳדָם יְיָ עַל עֵסַק פְּעוֹר וַהֲוַת מוֹתָנָא בִּכְנִשְׁתָּא דַיְיָ:
@1078 וּכְעַן קְטוּלוּ כָּל דְכוּרָא בְּטַפְלָא וְכָל אִתְּתָא דִידַעַת גְבַר לְמִשְׁכַּב דְכוּרָא קְטּוּלוּ:
@1079 וְכָל טַפְלָא בִנְשַׁיָא דִי לָא יְדָעוּ מִשְׁכַּב דְכוּרָא קַיְימוּ לְכוֹן:
@1080 וְאַתּוּן שְׁרוֹ מִבָּרָא לְמַשְׁרִיתָא שַׁבְעָא יוֹמִין כָּל דִי קְטַל נַפְשָׁא וְכֹל דִי קְרַב בְּקָטִילָא תַּדוּן עֲלוֹהִי בְּיוֹמָא תְלִיתָאָה וּבְיוֹמָא שְׁבִיעָאָה אַתּוּן וּשְׁבִיכוֹן:
@1081 וְכָל לְבוּשׁ וְכָל מַאן דִמְשַׁךְ וְכָל עוֹבַד מֵעַזֵי וְכָל מַאן דְעָא תַּדוּן עֲלוֹהִי:
@1082 וַאֲמַר אֶלְעָזָר כַּהֲנָא לְגַבְרֵי חֵילָא דַאֲתוֹ לִקְרָבָא דָא גְזֵירַת אוֹרַיְיתָא דִי פַקֵיד יְיָ יָת משֶׁה:
@1083 בְּרַם יָת דַהֲבָא וְיָת כַסְפָּא יָת נְחָשָׁא יָת פַּרְזְלָא יָת אֲבָצָא וְיָת אֲבָרָא:
@1084 כָּל מִדַעַם דְמִתָּעַל בְּנוּרָא תַּעֲבְרוּנֵיהּ בְּנוּרָא וְיִדְכֵּי בְּרַם בְּמֵי אַדָיוּתָא יִתָּדֵי וְכָל דִי לָא מִתָּעַל בְּנוּרָא תַּעַבְרוּנֵיהּ בְּמַיָא:
@1085 וּתְחַוְרוּן לְבוּשֵׁיכוֹן בְּיוֹמָא שְׁבִיעָאָה וְתִדְכּוּן וּבָתַר כֵּן תַּעֲלוּן לְמַשְׁרִיתָא:
@1086 וַאֲמַר יְיָ לְמשֶׁה לְמֵימָר:
@1087 קַבֵּל יָת חוּשְׁבַּן דַבְרַת שִׁבְיָא בֶּאֱנָשָׁא וּבִבְעִירָא אַתְּ וְאֶלְעָזָר כַּהֲנָא וְרֵישֵׁי אֲבָהַת כְּנִשְׁתָּא:
@1088 וּתְפַלֵג יָת דְבַרְתָּא בֵּין גַבְרֵי מַגִיחֵי קְרָבָא דְנְפָקוּ לְחֵילָא וּבֵין כָּל כְּנִשְׁתָּא:
@1089 וְתַפְרֵשׁ נְסִיבָא קֳדָם יְיָ מִן גַבְרֵי מְגִיחֵי קְרָבָא דִנְפָקוּ לְחֵילָא חָד נַפְשָׁא מֵחֲמֵשׁ מְאָה מִן אֱנָשָׁא וּמִן תּוֹרֵי וּמִן חֲמָרֵי וּמִן עָנָא:
@1090 מִפַּלְגוּתְהוֹן תִּסְבוּן וְתִתֵּן לְאֶלְעָזָר כַּהֲנָא אַפְרָשׁוּתָא קֳדָם יְיָ:
@1091 וּמִפַּלְגוּת בְּנֵי יִשְׂרָאֵל תִּסַב חָד דְאִתַּחָד מִן חַמְשִׁין מִן אֱנָשָׁא מִן תּוֹרֵי מִן חֲמָרֵי וּמִן עָנָא מִכָּל בְּעִירָא וְתִתֵּן יָתְהוֹן לְלֵוָאֵי נַטְרֵי מַטְרַת מַשְׁכְּנָא דַיְיָ:
@1092 וַעֲבַד משֶׁה וְאֶלְעָזָר כַּהֲנָא כְּמָא דִי פַקֵיד יְיָ יָת משֶׁה:
@1093 וַהֲוָה דְבַרְתָּא שְׁאָר בִּיזָא דִי בְזוֹ עַמָא דִי נְפָקוּ לְחֵילָא עָנָא שִׁית מְאָה וְשַׁבְעִין וְחַמְשָׁא אַלְפִין:
@1094 וְתוֹרֵי שַׁבְעִין וּתְרֵין אַלְפִין:
@1095 וַחֲמָרֵי שִׁיתִּין וְחָד אַלְפִין:
@1096 וְנַפְשָׁא דֶאֱנָשָׁא מִן נְשַׁיָא דִי לָא יְדָעָא מִשְׁכְּבֵי דְכוּרָא כָּל נַפְשָׁתָא תְּלָתִין וּתְרֵין אַלְפִין:
@1097 וַהֲוַת פַלְגוּתָא חוּלַק גוּבְרַיָא דִנְפָקוּ לְחֵילָא מִנְיַן עָנָא תְּלַת מְאָה וּתְלָתִין וּשְׁבַע אַלְפִין וַחֲמֵשׁ מְאָה:
@1098 וַהֲוָה נְסִיבָא קֳדָם יְיָ מִן עָנָא שִׁית מְאָה שַׁבְעִין וַחֲמֵשׁ:
@1099 וְתוֹרֵי תְּלָתִין וְשִׁתָּא אַלְפִין וּנְסֵיבְהוֹן קֳדָם יְיָ שַׁבְעִין וּתְרֵין:
@1100 וַחֲמָרֵי תְּלָתִין אַלְפִין וַחֲמֵשׁ מְאָה וּנְסֵיבְהוֹן קֳדָם יְיָ שִׁתִּין וְחָד:
@1101 וְנַפְשָׁא אֱנָשָׁא שִׁתָּא עֲשַׂר אַלְפִין וּנְסֵבְהוֹן קֳדָם יְיָ תְּלָתִין וּתְרֵין נַפְשִׁין:
@1102 וִיהַב משֶׁה יָת נְסִיב אַפְרָשׁוּתָא קֳדָם יְיָ לְאֶלְעָזָר כַּהֲנָא כְּמָא דִי פַקֵיד יְיָ יָת משֶׁה:
@1103 וּמִפַּלְגוּת בְּנֵי יִשְׂרָאֵל דִי פְּלַג משֶׁה מִן גוּבְרַיָא דִנְפָקוּ לְחֵילָא:
@1104 וַהֲוַת פַּלְגוּת כְּנִשְׁתָּא מִן עָנָא תְּלַת מְאָה וּתְלָתִין וְשַׁבְעָא אַלְפִין וַחֲמֵשׁ מְאָה:
@1105 וְתוֹרֵי תְּלָתִין וְשִׁתָּא אַלְפִין וַחֲמֵשׁ מְאָה:
@1106 וַחֲמָרֵי תְּלָתִין אַלְפִין וַחֲמֵשׁ מְאָה:
@1107 וְנַפְשָׁא דְאֱנָשָׁא שִׁתָּא עֲשַׂר אַלְפִין:
@1108 וּנְסֵב משֶׁה מִפַּלְגוּת בְּנֵי יִשְׂרָאֵל יָת דְאִתַּחָד חָד מִן חַמְשִׁין מִן אֱנָשָׁא וּמִן בְּעִירָא וִיהַב יָתְהוֹן לְלֵוָאֵי נַטְּרֵי מַטְרַת מַשְׁכְּנָא דַיְיָ כְּמָא דִי פַקֵיד יְיָ יָת משֶׁה:
@1109 וּקְרִיבוּ לְוָת משֶׁה דִמְמַנָן עַל אַלְפֵי חֵילָא רַבָּנֵי אַלְפִין וְרַבָּנֵי מַאֲוָתָא:
@1110 וַאֲמָרוּ לְמשֶׁה עַבְדָיךְ קַבִּילוּ יָת חוּשְׁבַּן גַבְרֵי מְגִיחֵי קְרָבָא דִי עִמָנָא וְלָא שְׁגָא מִנָנָא אֱנָשׁ:
@1111 וְקָרֶבְנָא יָת קוּרְבָּנָא דַיְיָ גְבַר דְאַשְׁכַּח מַאן דִדְהַב שִׁירִין וְשִׁבְּכִין עִזְקָן קַדָשִׁין וּמָחוֹךְ לְכַפָּרָא עַל נַפְשָׁתָנָא קֳדָם יְיָ:
@1112 וּנְסֵיב משֶׁה וְאֶלְעָזר כַּהֲנָא יָת דַהֲבָא מִנְהוֹן כָּל מַאן דְעוֹבָדָא:
@1113 וַהֲוָה כָּל דְהַב אַפְרָשׁוּתָא דְאַפְרָשׁוּ קֳדָם יְיָ שִׁתָּא עַשֲׂר אַלְפִין שְׁבַע מְאָה וְחַמְשִׁין סִלְעִין מִן רַבָּנֵי אַלְפִין וּמִן רַבָּנֵי מַאֲוָתָא:
@1114 גַבְרֵי דְחֵילָא בָּזוּ גְבַר לְנַפְשֵׁיהּ:
@1115 וּנְסֵיב משֶׁה וְאֶלְעָזָר כַּהֲנָא יָת דַהֲבָא מִן רַבָּנֵי אַלְפִין וּמַאֲוָתָא וְאַיְתִיאוּ יָתֵיהּ לְמַשְׁכַּן זִמְנָא דָכְרָנָא לִבְנֵי יִשְׂרָאֵל קֳדָם יְיָ:
@1116 וּבְעִיר סַגִי הֲוָה לִבְנֵי רְאוּבֵן וְלִבְנֵי גָד תַּקֵּיף לַחֲדָא וַחֲזוֹ יָת אֲרַע יַעְזֵר וְיָת אֲרַע גִּלְעָד וְהָא אַתְרָא אֲתַר כְּשַׁר לְבֵית בְּעִיר:
@1117 וַאֲתוֹ בְנֵי גָד וּבְנֵי רְאוּבֵן וַאֲמָרוּ לְמשֶׁה וּלְאֶלְעָזָר כַּהֲנָא וּלְרַבְרְבֵי כְּנִשְׁתָּא לְמֵימָר:
@1118 מַכְלֶלְתָּא וּמַלְבֶּשְׁתָּא וְכוּמְרִין וּבֵית נִמְרִין וּבֵית חוּשְׁבָּנָא וּבַעֲלֵי דְבָבָא וְסִימָא וּבֵית קְבוּרְתָּא דְמשֶׁה וּבְעוֹן:
@1119 אַרְעָא דִי מְחָא יְיָ יַת יָתְבָהָא קֳדָם כְּנִשְׁתָּא דְיִשְׂרָאֵל אֲרַע כָּשְׁרָא לְבֵית בְּעִיר הִיא וּלְעַבְדָיךְ אִית בְּעִיר:
@1120 וַאֲמָרוּ אִם אַשְׁכַּחְנָא רַחֲמִין בְּעֵינָיךְ תִּתְיְהִיב יָת אַרְעָא הָדָא לְעַבְדָךְ לְאַחֲסָנָא לָא תְעַבְרִינָנָא יָת יַרְדְנָא:
@1121 וַאֲמַר משֶׁה לִבְנֵי גָד וְלִבְנֵי רְאוּבֵן הַאֲחֵיכוֹן יֵיתוּן לִקְרָבָא וְאַתּוּן תֵּתְבוּן הָכָא:
@1122 וּלְמָא תוֹנוּן יָת לִבָּא דִבְנֵי יִשְׂרָאֵל מִלְמֶעֱבַר לְאַרְעָא דִיהַב לְהוֹן יְיָ:
@1123 כְּדֵין עֲבָדוּ אֲבָהַתְכוֹן כַּד שְׁלָחִית יָתְהוֹן מֵרְקַם גֵיאָה לְמֶחֱזֵי יָת אַרְעָא:
@1124 וּסְלִיקוּ עַד נַחֲלָא דְאַתְכָּלָא וַחֲזוֹ יָת אַרְעָא וְאוֹנִיאוּ יָת לִבָּא דִבְנֵי יִשְׂרָאֵל בְּדִיל דְלָא לְמֵיעַל לְאַרְעָא דִיהַּב לְהוֹן יְיָ:
@1125 וּתְקֵיף רוּגְזָא דַיְיָ בְּיוֹמָא הַהוּא וְקַיֵים לְמֵימָר:
@1126 אִם יֶחֱזוּן גֻבְרַיָא דִסְלִיקוּ מִמִצְרַיִם מִבַּר עַשְׂרִין שְׁנִין וּלְעֵילָא יָת אַרְעָא דִי קַיֵימִית לְאַבְרָהָם לְיִצְחָק וּלְיַעֲקֹב אֲרֵי לָא אַשְׁלִימוּ בָּתַר דַחַלְתִּי:
@1127 אֱלָהֵן כָּלֵב בַּר יְפֻנֶה קְנִזָאָה וִיהוֹשֻׁעַ בַּר נוּן אֲרֵי אַשְׁלִימוּ בָּתַר דַחַלְתָּא דַיְיָ:
@1128 וּתְקֵיף רוּגְזָא דַיְיָ בְּיִשְׂרָאֵל וּטְרָדִנוּן בְּמַדְבְּרָא אַרְבְּעִין שְׁנִין עַד דְסַף כָּל דָרָא דְעָבִיד דְבִישׁ קֳדָם יְיָ:
@1129 וְהָא קַמְתּוּן חֲלַף אֲבָהַתְכוֹן תַּלְמִידֵי גֻבְרַיָא חַיָבַיָא לְאוֹסָפָא עוֹד עַל תְּקוֹף רוּגְזָא דַיְיָ לְיִשְׂרָאֵל:
@1130 אֲרֵי תְתוּבוּן מִבָּתַר דַחַלְתֵּיהּ וְיוֹסִיף עוֹד לְאַחֲרוּתְהוֹן בְּמַדְבְּרָא וּתְחַבְּלוּן לְכָל עַמָא הָדֵין:
@1131 וּקְרִיבוּ לְוָתֵיהּ וַאֲמָרוּ חַטְרִין דְעָאן נִבְנֵי לִבְעִירָנָא הָכָא וְקִרְוִין לְטַפְלָנָא:
@1132 וַאֲנַחְנָא נִזְדָרֵיז מַבְעִין קֳדָם בְּנֵי יִשְׂרָאֵל עַד דִי נְעֵלִינוּן לְאַתְרֵהוֹן וְיֵתְבוּן טַפְלָנָא בְּקִרְוִין כְּרִיכִין מִן קֳדָם יַתְבֵי אַרְעָא:
@1133 לָא נְתוּב לְבֵיתָנָא עַד דְיַחְסְנוּן בְּנֵי יִשְׂרָאֵל גְבַר אַחֲסַנְתֵּיהּ:
@1134 אֲרֵי לָא נַחֲסִין עִמְהוֹן מֵעִבְרָא לְיַרְדְנָא וּלְהָלָא אֲרֵי קַבֵּילְנָא אַחֲסַנְתָּנָא לָנָא מֵעִבְרָא לְיַרְדְנָא מַדִינְחָא:
@1135 וַאֲמַר לְהוֹן משֶׁה אִם תַּעְבְדוּן יָת פִּתְגָמָא הָדֵין אִם תִּזְדָרְזוּן קֳדָם עַמָא דַיְיָ לִקְרָבָא:
@1136 וְיַעְבֵר לְכוֹן כָּל דִמְזָרֵז יָת יַרְדְנָא קֳדָם עַמָא דַיְיָ עַד דִיתָרַךְ יָת בַּעֲלֵי דְבָבוֹהִי מִן קֳדָמוֹהִי:
@1137 וְתִתְכְּבֵשׁ אַרְעָא קֳדָם עַמָא דַיְיָ וּבָתַר כֵּן תְּתוּבוּן וּתְהוֹן זַכָּאִין מִן קֳדָם יְיָ וּמִיִשְׂרָאֵל וּתְהֵי אַרְעָא הָדָא לְכוֹן לְאַחֲסָנָא קֳדָם יְיָ:
@1138 וְאִם לָא תַעְבְדוּן כֵּן הָא חַבְתּוּן קֳדָם יְיָ וְתֵדְעוּן חוֹבַתְכוֹן דְתַשְׁכַּח יָתְכוֹן:
@1139 בְּנוּ לְכוֹן קִרְוִין לְטַפְלְכוֹן וְחַטְרִין לְעַנְכוֹן וּדְיִפּוֹק מִפּוּמְכוֹן תַּעְבְּדוּן:
@1140 וַאֲמָרוּ בְנֵי גָד וּבְנֵי רְאוּבֵן לְמשֶׁה לְמֵימָר עַבְדָיךְ יַעְבְדוּן כְּמָא דִי רִבּוֹנִי מְפַקֵד:
@1141 טַפְלָנָא נְשָׁנָא גֵיתָנָא וְכָל בְּעִירָנָא יְהוֹן תַּמָן בְּקִרְוֵי גִלְעָד:
@1142 וְעַבְדָיךְ יַעְבְּרוּן כָּל מְזָרַז חֵילָא קֳדָם עַמָא דַיְיָ לִקְרָבָא כְּמָא דִי רִבּוֹנִי מְמַלֵל:
@1143 וּפַקֵד לְהוֹן משֶׁה יָת אֶלְעָזָר כַּהֲנָא וְיָת יְהוֹשֻׁעַ בַּר נוּן וְיָת רֵישֵׁי אֲבָהַת שִׁבְטַיָא לִבְנֵי יִשְׂרָאֵל:
@1144 וַאֲמַר משֶׁה לְהוֹן אִם יַעְבְּרוּן בְּנֵי גָד וּבְנֵי רְאוּבֵן עִמְכוֹן יָת יַרְדְנָא כָּל דִמְזָרַז לִקְרָבָא קֳדָם עַמָא דַיְיָ וְתִתְכְּבֵשׁ אַרְעָא קֳדָמֵיכוֹן וְתִתְּנוּן לְהוֹן יָת אַרְעָא דְגִלְעָד לְאַחֲסָנָא:
@1145 וְאִם לָא יַעְבְרוּן מְזָרְזִין עִמְכוֹן וְיַחְסְנוּן בֵּינֵיכוֹן בְּאַרְעָא דִכְנָעַן:
@1146 וְאָתִיבוּ בְנֵי גָד וּבְנֵי רְאוּבֵן לְמֵימָר יָת דִי מַלִיל יְיָ לְעַבְדָךְ כֵּן נַעְבֵּד:
@1147 נַחְנָא נַעֲבֵר מְזָרְזִין קֳדָם עַמָא דַיְיָ לְאַרְעָא דִכְנָעַן וְעִמָנָא אֲחוּדַת אַחֲסַנְתָּנָא מֵעִבְרָא לְיַרְדְנָא:
@1148 וִיהַב לְהוֹן משֶׁה לִבְנֵי גָד וְלִבְנֵי רְאוּבֵן וּלְפַלְגוּת שִׁבְטָא דִמְנַשֶׁה בַּר יוֹסֵף יָת מַלְכְּוַת סִיחוֹן מַלְכָּא דֶאֱמוֹרָאָה וְיָת מַלְכְּוַת עוֹג מַלְכָּא דְמַתְנָן אַרְעָא לְקִרְוָהָא בִּתְחוּמִין קִרְוֵי אַרְעָא סְחוֹר סְחוֹר:
@1149 וּבְנוֹ בְנֵי גָד יָת דִיבוֹן וְיָת עֲטָּרוֹת וְיָת עֲרֹעֵר:
@1150 וְיָת עַטְרוֹת שׁוֹפָן וְיָת יַעְזֵר וְרָמָתָא:
@1151 וְיָת בֵּית נִמְרָה וְיָת בֵּית הָרָן קִרְוִין כְּרִיכָן וְחַטְרִין דְעָאן:
@1152 וּבְנֵי רְאוּבֵן בְּנוֹ יָת חֶשְׁבּוֹן וְיָת אֶלְעָלֵא וְיָת קִרְיָתָיִם:
@1153 וְיָת נְבוֹ וְיָת בַּעַל מְעוֹן מַקְפָן שְׁמָהָן וְיָת שִׂבְמָה וּקְרוֹ בִשְׁמָהָן יָת שְׁמָהַת קִרְוַיָא דִי בְנוֹ:
@1154 וַאֲזָלוּ בְּנֵי מָכִיר בַּר מְנַשֶׁה לְגִלְעָד וְכִבְשׁוּהָ וְתָרִיךְ יָת אֱמוֹרָאָה דִי בָּהּ:
@1155 וִיהַב משֶׁה יָת גִלְעָד לְמָכִיר בַּר מְנַשֶׁה וִיתֵב בַּהּ:
@1156 וְיָאִיר בַּר מְנַשֶׁה אֲזַל וּכְבַשׁ יָת כַּפְרָנֵיהוֹן וּקְרָא יַתְהֶן כַּפְרָנֵי יָאִיר:
@1157 וְנֹבַח אֲזַל וּכְבַשׁ יָת קְנַת וְיָת כַּפְרָנָהָא וּקְרָא לָה נֹבַח בִּשְׁמֵהּ: פפפ:
@1158 אִלֵין מַטְלָנֵי בְנֵי יִשְׂרָאֵל דִי נְפָקוּ מֵאַרְעָא דְמִצְרַיִם לְחֵילֵיהוֹן בִּידָא דְמשֶׁה וְאַהֲרֹן:
@1159 וּכְתַב משֶׁה יָת מַפְּקָנֵיהוֹן לְמַטְלָנֵיהוֹן עַל מֵימְרָא דַיְיָ וְאִלֵין מַטְלָנֵיהוֹן לְמַפְּקָנֵיהוֹן:
@1160 וּנְטָלוּ מֵרַעְמְסֵס בְּיַרְחָא קַדְמָאָה בְּחַמְשָׁא עַשְׂרָא יוֹמָא לְיַרְחָא קַדְמָאָה מִבָּתַר יוֹמָא דְפִסְחָא נְפָקוּ בְנֵי יִשְרָאֵל בְּרֵישׁ גְלֵי לְעֵינֵי כָּל מִצְרָאֵי:
@1161 וּמִצְרָאֵי מְקַבְּרִין יָת דִי קְטַל יְיָ בְּהוֹן כָּל בּוּכְרָא וּבְטַעֲוַתְהוֹן עָבַד יְיָ דִינִין:
@1162 וּנְטָלוּ בְנֵי יִשְׂרָאֵל מֵרַעְמְסֵס וּשְׁרוֹ בְּסֻכֹּת:
@1163 וּנְטָּלוּ מִסֻכֹּת וּשְרוֹ בְאֵתָם דִי בִּסְטַר מַדְבְּרָא:
@1164 וּנְטָלוּ מֵאֵתָם וְתָב עַל פּוּם חִירָתָא דִי קֳדָם בְּעֵיל צְפוֹן וּשְׁרוֹ קֳדָם מִגְדֹל:
@1165 וּנְטָלוּ מִן פּוּם חִירָתָא וַעֲבָרוּ בְּגוֹ יַמָא לְמַדְבְּרָא וַאֲזָלוּ מַהֲלַךְ תְּלָתָא יוֹמִין בְּמַדְבְּרָא דְאֵתָם וּשְׁרוֹ בְּמָרָה:
@1166 וּנְטָלוּ מִמָרָה וַאֲתוֹ לְאֵילִם וּבְאֵילִם תְּרֵי עֲשַׂר מַבּוּעִין דְמַיִן וְשַׁבְעִין דִקְלִין וּשְׁרוֹ תַמָן:
@1167 וּנְטָלוּ מֵאֵילִם וּשְׁרוֹ עַל יַמָא דְסוּף:
@1168 וּנְטָּלוּ מִיַמָא דְסוּף וּשְׁרוֹ בְּמַדְבְּרָא דְסִין:
@1169 וּנְטָלוּ מִמַדְבְּרָא דְסִין וּשְׁרוֹ בְּדָפְקָה:
@1170 וּנְטָלוּ מִדָפְקָה וּשְׁרוֹ בְּאָלוּשׁ:
@1171 וּנְטָלוּ מֵאָלוּשׁ וּשְׁרוֹ בִּרְפִידִם וְלָא הֲוָה תַמָן מַיָא לְעַמָא לְמִשְׁתֵּי:
@1172 וּנְטָלוּ מֵרְפִידִם וּשְׁרוֹ בְּמַדְבְּרָא דְסִינָי:
@1173 וּנְטָלוּ מִמַדְבְּרָא דְסִינָי וּשְׁרוֹ בְּקִבְרֵי דִמְשַׁאֲלֵי:
@1174 וּנְטָּלוּ מִקִבְרֵי דִמְשַׁאֲלֵי וּשְׁרוֹ בַּחֲצֵרוֹת:
@1175 וּנְטָלוּ מֵחֲצֵרֹת וּשְׁרוֹ בְּרִתְמָה:
@1176 וּנְטָלוּ מֵרִתְמָה וּשְׁרוֹ בְּרִמוֹן פָּרֶץ:
@1177 וּנְטָלוּ מֵרִמוֹן פָּרֶץ וּשְׁרוֹ בְּלִבְנָה:
@1178 וּנְטָלוּ מִלִבְנָה וּשְׁרוֹ בְּרִסָה:
@1179 וּנְטָלוּ מֵרִסָה וּ:שׁרוֹ בִּקְהֵלָתָה:
@1180 וּנְטָלוּ מִקְהֵלָתָה וּשְׁרוֹ בְּטוּרָא דְשָׁפֶר:
@1181 וּנְטָלוּ מִטוּרָא דְשָׁפֶר וּשְׁרוֹ בַּחֲרָדָה:
@1182 וּנְטָּלוּ מֵחֲרָדָה וּשְׁרוֹ בְּמַקְהֵלוֹת:
@1183 וּנְטָלוּ מִמַקְהֵלוֹת וּשְׁרוֹ בְּתָחַת:
@1184 וּנְטָלוּ מִתָּחַת וּשְׁרוֹ בְּתָרַח:
@1185 וּנְטָלוּ מִתָּרַח וּ:שׁרוֹ בְּמִתְקָה:
@1186 וּנְטָלוּ מִמִתְקָה וּשְׁרוֹ בְּחַשְׁמוֹנָה:
@1187 וּנְטָלוּ מֵחַשְׁמוֹנָה וּשְׁרוֹ בְּמוֹסֵרוֹת:
@1188 וּנְטָלוּ מִמוֹסֵרוֹת וּשְׁרוֹ בִּבְנֵי יַעֲקָן:
@1189 וּנְטָּלוּ מִבְּנֵי יַעֲקָן וּשְׁרוֹ בְּחוֹר הַגִדְגָד:
@1190 וּנְטָלוּ מֵחוֹר הַגִדְגָד וּשְׁרוֹ בְּיָטְבָתָה:
@1191 וּנְטָלוּ מִיָטְבָתָה וּשְׁרוֹ בְּעַבְרֹנָה:
@1192 וּנְטָלוּ מֵעַבְרוֹנָה וּשְׁרוֹ בְּעֶצְיוֹן גָבֶר:
@1193 וּנְטָלוּ מֵעֶצְיוֹן גָבֶר וּשְׁרוֹ בְּמַדְבְּרָא דְצִן הִיא רְקָם:
@1194 וּנְטָלוּ מֵרְקָם וּשְׁרוֹ בְּהוֹר טוּרָא בִּסְיָפֵי אַרְעָא דֶאֱדוֹם:
@1195 וּסְלֵק אַהֲרֹן כַּהֲנָא לְהוֹר טּוּרָא עַל מֵימְרָא דַיְיָ וּמִית תַּמָן בִּשְׁנַת אַרְבְּעִין לְמֵפַּק בְּנֵי יִשְׂרָאֵל מֵאַרְעָא דְמִצְרַיִם בְּיַרְחָא חֲמִשָׁאָה בּחַד לְיַרְחָא:
@1196 וְאַהֲרֹן בַּר:מְאָה וְעַשְׂרִין וּתְלַת שְׁנִין כַּד מִית בְּהוֹר טוּרָא:
@1197 וּשְׁמַע כְּנַעֲנָאָה מַלְכָּא דַעֲרָד וְהוּא יָתֵב בִּדְרוֹמָא בְּאַרְעָא דִכְנָעַן בְּמֵיתֵי בְּנֵי יִשְׂרָאֵל:
@1198 וּנְטָלוּ מֵהוֹר טוּרָא וּשְׁרוֹ בְּצַלְמוֹנָה:
@1199 וּנְטָלוּ מִצַלְמוֹנָה וּשְׁרוֹ בְּפוּנוֹן:
@1200 וּנְטָלוּ מִפּוּנוֹן וּשְׁרוֹ בְּאֹבוֹת:
@1201 וּנְטָלוּ מֵאֹבוֹת וּשְׁרוֹ בִּמְגִזַת עֲבָרָאֵי בִּתְחוּם מוֹאָב:
@1202 וּנְטָלוּ מִמְגִזָתָא וּשְׁרוֹ:בּדִיבוֹן גָד:
@1203 וּנְטָלוּ מִדִיבוֹן גָד וּשְׁרוֹ בְּעַלְמוֹן דִבְלָתָיְמָה:
@1204 וּנְטָלוּ מֵעַלְמוֹן דִבְלָתָיְמָה וּשְׁרוֹ בְּטוּרֵי דַעֲבָרָאֵי דִקֳדָם נְבוֹ:
@1205 וּנְטָלוּ מִטוּרֵי דַעֲבָרָאֵי וּשְׁרוֹ בְּמֵישְׁרַיָא דְמוֹאָב עַל יַרְדְנָא דִירֵחוֹ:
@1206 וּשְׁרוֹ עַל יַרְדְנָא מִבֵּית יְשִׁימוֹת עַד מֵישַׁר שִׁטִין בְּמֵישְׁרַיָא דְמוֹאָב:
@1207 וּמַלִיל יְיָ עִם משֶׁה בְּמֵישְׁרַיָא דְמוֹאָב עַל יַרְדְנָא דִירֵחוֹ לְמֵימָר:
@1208 מַלֵל עִם בְּנֵי יִשְׂרָאֵל וְתֵימַר לְהוֹן אֲרֵי אַתּוּן עָבְרִין יָת יַרְדְנָא לְאַרְעָא דִכְנָעַן:
@1209 וּתְתָרְכוּן יָת כָּל יָתְבֵי אַרְעָא מִן קֳדָמֵיכוֹן וְתֵבְדוּן יָת כָּל בֵּית סִגְדַתְהוֹן וְיָת כָּל צַלְמֵי מַתְּכַתְהוֹן תֵּבְדוּן וְיָת כָּל בָּמַתְהוֹן תְּשֵׁצוּן:
@1210 וּתְתָרְכוּן יָת יָתְבֵי אַרְעָא וְתֵיתְבוּן בָּהּ אֲרֵי לְכוֹן יְהָבִית יָת אַרְעָא לְמֵירַת יָתָהּ:
@1211 וְתַחְסְנוּן יָת אַרְעָא בְעַדְבָא לְזַרְעֲיַתְכוֹן לְסַגִיאֵי תַּסְגוּן יָת אַחֲסַנְתְּהוֹן וְלִזְעִירֵי תַּזְעִירוּן יָת אַחֲסַנְתְּהוֹן לִדְיִפּוֹק לֵהּ תַּמָן עַדְבָא דִי לֵהּ יְהֵי לְשִׁבְטֵי אֲבָהַתְכוֹן תַּחְסְנוּן:
@1212 וְאִם לָא תְתָרְכוּן יָת יָתְבֵי אַרְעָא מִן קֳדָמֵיכוֹן וִיהֵי דִי תַשְׁאֲרוּן מִנְהוֹן לְסִיעַן נַטְלַן זְיַן לְקִבְלֵיכוֹן וּלְמַשִׁרְיַן מַקְפַּנְכוֹן וִיעִיקוּן לְכוֹן עַל אַרְעָא דִי אַתּוּן יָתְבִין בָּהּ:
@1213 וִיהֵי כְּמָא דִי חֲשָׁבִית לְמֶעְבַּד לְהוֹן אַעֲבֵד לְכוֹן:
@1214 וּמַלִיל יְיָ עִם משֶׁה לְמֵימָר:
@1215 פַּקֵד יָת בְּנֵי יִשְׂרָאֵל וְתֵימַר לְהוֹן אֲרֵי אַתּוּן עָאלִין לְאַרְעָא דִכְנָעַן דָא אַרְעָא דִי תִתְפְּלֵג לְכוֹן בְּאַחֲסָנָא אַרְעָא דִכְנַעַן לִתִחוּמָאָה:
@1216 וִיהֵי לְכוֹן רוּחַ דָרוֹמָא מִמַדְבְּרָא דְצִן עַל תְּחוּמֵי אֱדוֹם וִיהֵי לְכוֹן תְּחוּם דָרוֹמָא מִסְיָפֵי יַמָא דְמִלְחָא קִדוּמָא:
@1217 וְיַסְחַר לְכוֹן תְּחוּמָא מִדְרוֹמָא לְמַסְקָנָא דְעַקְרַבִּים וִיעִבַר לְצִן וִיהוֹן מַפְקָנוֹהִי מִדְרוֹמָא לִרְקָם גֵיאָה וְיִפּוֹק לַחֲצַר אַדָר וִיעִבַר לְעַצְמוֹן:
@1218 וְיַסְחַר תְּחוּמָא מֵעַצְמוֹן לְנַחֲלָא דְמִצְרָיִם וִיהוֹן מַפְקָנוֹהִי לְיַמָא:
@1219 וּתְחוּם מַעַרְבָא וִיהֵי לְכוֹן יַמָא רַבָּא וּתְחוּמֵהּ דֵין יְהֵא לְכוֹן תְּחוּם מַעֲרְבָא:
@1220 וְדֵין יְהֵי לְכוֹן תְּחוּם צִפּוּנָא מִן יַמָא רַבָּא תְּכַוְנוּן לְכוֹן לְהוֹר טוּרָא:
@1221 מֵהוֹר טוּרָא תְּכַוְנוּן לִמְטֵי חֲמָת וִיהוֹן מַפְּקָנוֹהִי דִתְחוּמָא לִצְדָד:
@1222 וְיִפּוֹק תְּחוּמָא לְזִפְרוֹן וִיהוֹן מַפְּקָנוֹהִי לַחֲצַר עֵינָן דֵין יְהֵי לְכוֹן תְּחוּם צִפּוּנָא:
@1223 וּתְכַוְנוּן לְכוֹן לִתְחוּם קִדוּמָא מֵחֲצַר עֵינָן לִשְׁפָם:
@1224 וְיֵחוֹת תְּחוּמָא מִשְׁפָם לְרִבְלָה מִמַדְנַח לָעָיִן וְיֵחוֹת תְּחוּמָא וְיִמְטֵי עַל כֵּיף יַם גִנוֹסַר קִדוּמָא:
@1225 וְיֵחוֹת תְּחוּמָא לְיַרְדְנָא וִיהוֹן מַפְקָנוֹהִי לְיַמָא דְמִלְחָא דָא תְהֵי לְכוֹן אַרְעָא לִתְחוּמָאָה סְחוֹר סְחוֹר:
@1226 וּפַקִיד משֶׁה יָת בְּנֵי יִשְׂרָאֵל לְמֵימָר דָא אַרְעָא דְתִתְחַסְנוּן יָתַהּ בְּעַדְבָא דִי פַקֵיד יְיָ לְמִתַּן לְתִשְׁעַת שִׁבְטִין וּפַלְגוּת שִׁבְטָא:
@1227 אֲרֵי קַבִּילוּ שִׁבְטָא דִבְנֵי רְאוּבֵן לְבֵית אֲבָהַתְהוֹן וְשִׁבְטָא דִבְנֵי גָד לְבֵית אֲבָהַתְהוֹן וּפַלְגוּת שִׁבְטָא דִמְנַשֶׁה קַבִּילוּ אַחֲסַנְתְּהוֹן:
@1228 תְּרֵין שִׁבְטִין וּפַלְגוּת שִׁבְטָא קַבִּילוּ אַחֲסַנְתְּהוֹן מֵ עִבְרָא לְיַרְדְנָא דִירֵחוֹ קִדוּמָא מַדִינְחָא:
@1229 וּמַלִיל יְיָ עִם משֶׁה לְמֵימָר:
@1230 אִלֵין שְׁמָהַת גֻבְרַיָא דִי יַחְסְנוּן לְכוֹן יָת אַרְעָא אֶלְעָזָר כַּהֲנָא וִיהוֹשֻׁע בַּר נוּן:
@1231 וְרַבָּא חָד רַבָּא חָד מִשִׁבְטָא תִּסְבוּן לְאַחֲסָנָא יָת אַרְעָא:
@1232 וְאִלֵין שְׁמָהַת גֻבְרַיָא לְשִׁבְטָא דִיהוּדָה כָּלֵב בַּר יְפֻנֶה:
@1233 וּלְשִׁבְטָא דִבְנֵי שִׁמְעוֹן שְׁמוּאֵל בַּר עַמִיהוּד:
@1234 לְשִׁבְטָא דְבִנְיָמִן אֱלִידָד בַּר כִּסְלוֹן:
@1235 וּלְשִׁבְטָא דִבְנֵי דָן רַבָּא בֻּקִי בַּר יָגְלִי:
@1236 לִבְנֵי יוֹסֵף לְשִׁבְטָא דִבְנֵי מְנַשֶׁה רַבָּא חַנִיאֵל בַּר אֵפוֹד:
@1237 וּלְשִׁבְטָא דִבְנֵי אֶפְרָיִם רַבָּא קְמוּאֵל בַּר שִׁפְטָן:
@1238 וּלְשִׁבְטָא דִבְנֵי זְבוּלֻן רַבָּא אֱלִיצָפָן בַּר פַּרְנָךְ:
@1239 וּלְשִׁבְטָא דִבְנֵי יִשָׂשכָר רַבָּא פַלְטִיאֵל בַּר עַזָן:
@1240 וּלְשִׁבְטָּא דִבְנֵי אָשֵׁר רַבָּא אֲחִיהּוּד בַּר שְׁלֹמִי:
@1241 וּלְשִׁבְטָא דִבְנֵי נַפְתָּלִי רַבָּא פְּדַהְאֵל בַּר עַמִיהוּד:
@1242 אִלֵין דִי פַּקִיד יְיָ לְאַחֲסָנָא יָת בְּנֵי יִשְׂרָאֵל בְּאַרְעָא דִכְנָעַן:
@1243 וּמַלִיל יְיָ עִם משֶׁה בְּמֵישְׁרַיָא דְמוֹאָב עַל יַרְדְנָא דִירֵיחוֹ לְמֵימָר:
@1244 פַּקֵד יָת בְּנֵי יִשְׂרָאֵל וְיִתְּנוּן לְלֵוָאֵי מֵאַחֲסָנַת אֲחוּדַתְהּוֹן קִרְוִין לְמִתָּב וְרֶוַח לְּקִרְוַיָא סַחֲרָנֵיהוֹן תִּתְּנוּן לְלֵוָאֵי:
@1245 וִיהוֹן קִרְוַיָא לְהוֹן לְמִתָּב וְרַוְחֵיהוֹן יְהוֹן לִבְעִירְהוֹן וּלְקִנְיָנֵיהוֹן וּלְכָל חֵוַתְהוֹן:
@1246 וּרְוָחֵי קִרְוַיָא דִי תִתְּנוּן לְלֵוָאֵי מִכּוֹתֵל קַרְתָּא וּלְבָרָא אֲלַף אַמִין סְחוֹר סְחוֹר:
@1247 וְתִמְשְׁחוּן מִבָּרָא לְקַרְתָּא יָת רוּחַ קִדוּמָא תְּרֵין אַלְפִין בְּאַמִין וְיָת רוּחַ דְרוֹמָא תְּרֵין אַלְפִין בְּאַמִין וְיָת רוּחַ מַעֲרְבָא תְּרֵין אַלְפִין בְּאַמִין וְיָת רוּחַ צִפּוּנָא תְּרֵין אַלְפִין בְּאַמִין וְקַרְתָּא בִמְצִיעָא דֵין יְהֵי לְהוֹן רְוָחֵי קִרְוַיָא:
@1248 וְיָת קִרְוַיָא דִי תִתְּנוּן לְלֵוָאֵי יָת שִׁית קִרְוֵי שֵׁזָבוּתָא דִי תִתְּנוּן לְמֵעֲרַק תַּמָן קָטוֹלָא וַעֲלֵיהוֹן תִּתְּנוּן אַרְבְּעִין וְתַרְתֵּין קִרְוִין:
@1249 כָּל קִרְוַיָא דִי תִתְּנוּן לְלֵוָאֵי אַרְבְּעִין וְתַמְנֵי קִרְוִין יָתְהֶן וְיָת רְוָחֵיהֶן:
@1250 וְקִרְוַיָא דִי תִתְּנוּן מֵאֲחוּדַת בְּנֵי יִשְׂרָאֵל מִן סַגִיאֵי תַּסְגוּן וּמִן זְעִירֵי תַּזְעִירוּן גְבַר כְּפוּם אַחֲסַנְתֵּהּ דִי יַחְסְנוּן יִתֵּן מִקִרְווֹהִי לְלֵוָאֵי:
@1251 וּמַלִיל יְיָ עִם משֶׁה לְמֵימָר:
@1252 מַלֵיל עִם בְּנֵי יִשְׂרָאֵל וְתֵימַר לְהוֹן אֲרֵי אַתּוּן עָבְרִין יָת יַרְדְנָא לְאַרְעָא דִכְנָעַן:
@1253 וּתְזַמְנוּן לְכוֹן קִרְוִין קִרְוֵי שֵׁזָבוּתָא יֶהֶוְיָן לְכוֹן וְיַעֲרוֹק לְתַמָן קָטוֹלָא דְיִקְטוֹל נַפְשָׁא בְּשָׁלוּ:
@1254 וִיהוֹן לְכוֹן קִרְוַיָא לְשֵׁזָבָא מִגָאֵל דְמָא וְלָא יְמוּת קָטוֹלָא עַד דְיֵקוּם קֳדָם כְּנִשְׁתָּא לְדִינָא:
@1255 וְקִרְוַיָא דִי תִתְּנוּן שִׁית קִרְוֵי שֵׁזָבוּתָא יֶהֶוְיַן לְכוֹן:
@1256 יָת תְּלַת קִרְוַיָא תִתְּנוּן מֵעִבְרָא לְיַרְדְנָא וְיָת תְּלַת קִרְוַיָא תִתְּנוּן בְּאַרְעָא דִכְנָעַן קִרְוֵי שֵׁזָבוּתָא יֶהֶוְיָן:
@1257 לִבְנֵי יִשְׂרָאֵל וּלְגִיוֹרַיָא וּלְתוֹתָבַיָא דְבֵינֵיכוֹן יֶהֶוְיַן שִׁית קִרְוַיָא הָאִלֵין לְשֵׁזָבָא לְמֵעֲרַק לְתַמָן כָּל דְיִקְטוֹל נַפְשָׁא בְּשָׁלוּ:
@1258 וְאִם בְּמָאן דְפַרְזְלָא מְחָהִי וְקַטְלֵהּ קָטוֹלָא הוּא אִתְקְטָלָא יִתְקְטֵל קָטוֹלָא:
@1259 וְאִם בְּאַבְנָא דְמִתְנָסְבָא בִידָא דְהִיא כְמִסַת דִי יְמוּת בַּהּ מְחָהִי וְקָטְלֵהּ קָטוֹלָא הוּא אִתְקְטָלָא יִתְקְטֵל קָטוֹלָא:
@1260 אוֹ בְּמָאן דְעָא דְמִתְנָסֵב בִּידָא דְהִיא כְמִסַת דִי יְמוּת בֵּה מְחָהִי וְקַטְּלֵהּ קָטוֹלָא הוּא אִתְקְטָלָא יִתְקְטַל קָטוֹלָא:
@1261 גָאֵל דְמָא הוּא יִקְטוֹל יָת קָטוֹלָא כַּד אִתְחַיַב לֵהּ מִן דִינָא הוּא יְקַטְלִנֵהּ:
@1262 וְאִם בְּסַנְאָה דְחָהִי אוֹ רְמָא עֲלוֹהִי בְּכַמְנָא וְקַטְלֵהּ:
@1263 אוֹ בִדְבָבוּ מְחָהִי בִידֵהּ וְקָטְלֵהּ אִתְקְטָלָא יִתְקְטֵל מַחְיָא קָטוֹלָא הוּא גָאֵל דְמָא יִקְטוֹל יָת קָטוֹלָא כַּד אִתְחַיֵב לֵיהּ מִן דִינָא:
@1264 וְאִם בִּתְכֵיף בְּלָא דְבָבוּ דְחָהִי אוֹ רְמָא עֲלוֹהִי כָּל מָאן בְּלָא כְמָן לֵיהּ:
@1265 אוֹ בְּכָל אַבְנָא דְהִיא כְמִסַת דִי יְמוּת בָּהּ בְּלָא חָזֵי וּרְמָא עֲלוֹהִי וְקָטְלֵהּ וְהוּא לָא סָנֵי לֵיהּ וְלָא תָבַע בִּישְׁתֵיהּ:
@1266 וִידוּנוּן כְּנִשְׁתָּא בֵּין מַחְיָא וּבֵין גָאֵל דְמָא עַל דִינַיָא הָאִלֵין:
@1267 וִישֵׁזְבוּן כְּנִשְׁתָּא יָת קָטוֹלָא מִיַד גָאֵל דְמָא וִיתִיבוּן יָתֵיהּ כְּנִשְׁתָּא לְקִרְיַת שֵׁזָבוּתֵהּ דִי עֲרַק לְתַמָן וִיתֵב בָּהּ עַד דִימוּת כַּהֲנָא רַבָּא דִי רַבֵּי יָתֵהּ בִּמְשַׁח קוּדְשָׁא:
@1268 וְאִם מִפַּק יִפּוֹק קָטוֹלָא יָת תְּחוּם קִרְיַת שֵׁזָבוּתֵהּ דִי עֲרַק לְתַמָן:
@1269 וְיַשְׁכַּח יָתֵהּ גָאֵל דְמָא מִבָּרָא לִתְחוּם קִרְיַת שֵׁזָבוּתֵהּ וְיִקְטוֹל גָאֵל דְמָא יָת קָטוֹלָא לֵית לֵהּ דְמָא:
@1270 אֲרֵי בְקִרְיַת שֵׁזָבוּתֵהּ יִתֵּב עַד דִימוּת כַּהֲנָא רַבָּא וּבָתַר דִימוּת כַּהֲנָא רַבָּא יְתוּב קָטּוֹלָא לְאֲרַע אַחֲסַנְתֵּה:
@1271 וִיהוֹן אִלֵין לְכוֹן לִגְזֵרַת דִין לְדָרֵיכוֹן בְּכֹל מוֹתְבָנֵיכוֹן:
@1272 כָּל דְיִקְטוֹל נַפְשָׁא לְפוּם סַהֲדִין יִקְטוֹל יָת קָטוֹלָא וְסָהִיד חַד לָא יַסְהִד בֶּאֱנַשׁ לְמִקְטָל:
@1273 וְלָא תְקַבְּלוּן מָמוֹן עַל אֱנַשׁ קָטוֹל דִי הוּא חַיָב לְמִקְטָל אֲרֵי אִתְקְטָלָא יִתְקְטֵל:
@1274 וְלָא תְקַבְּלוּן מָמוֹן לְמֵעֲרוֹק לְקִרְיַת שֵׁזָבוּתֵהּ לְמֵתוּב לְמִתַּב בְּאַרְעָא עַד דִימוּת כַּהֲנָא:
@1275 וְלָא תְּחַיְבוּן יָת אַרְעָא דִי אַתּוּן בָּהּ אֲרֵי דְמָא הוּא מְחַיַב יָת אַרְעָא וּלְאַרְעָא לָא מִתְכַפֵּר עַל דַם זַכַּאי דִי אִתְאַשֵׁד בַּהּ אֶלָהֵן בְּדַם אַשְׁדֵהּ:
@1276 וְלָא תְסַאֲבוּן יָת אַרְעָא דִי אַתּוּן יָתְבִין בָּהּ דִי שְׁכִנְתִּי שַׁרְיָא בְּגַוָהּ אֲרֵי אֲנָא יְיָ דִשְׁכִנְתִּי שַׁרְיָא בְּגוֹ בְּנֵי יִשְׂרָאֵל:
@1277 וְקָרִיבוּ רֵישֵׁי אֲבָהָתָא לְּזַרְעִית בְּנֵי גִלְעָד בַּר מָכִיר בַּר מְנַשֶׁה מִזַרְעֲיַת בְּנֵי יוֹסֵף וּמַלִילוּ קֳדָם משֶׁה וְקָדָם רַבְרְבַיָא רֵישֵׁי אֲבָהָתָא לִבְנֵי יִשְׂרָאֵל:
@1278 וַאֲמָרוּ יָת רִבּוֹנִי פַּקִיד יְיָ לְמִתַּן יָת אַרְעָא בְאַחֲסָנָא בְּעַדְבָא לִבְנֵי יִשְׂרָאֵל וְרִבּוֹנִי אִתְפַּקֵד בְּמֵימְרָא דַיְיָ לְמִתַּן יָת אַחֲסָנַת צְלָפְחָד אָחוּנָא לִבְנָתֵהּ:
@1279 וִיהֶוְיַן לְחַד מִבְּנֵי שִׁבְטַיָא דִבְנֵי יִשְׂרָאֵל לִנְשִׁין וְתִתְמְנַע אַחֲסַנְתְּהוֹן מֵאַחֲסָנַת אֲבְהָתָנָא וְתִתּוֹסַף עַל אַחֲסָנַת שִׁבְטַיָא דִיֶהֶוְיָן לְהוֹן וּמֵעֲדַב אַחֲסַנְתָּנָא יִתְמְנָע:
@1280 וְאִם יְהֵי יוֹבֵלָא לִבְנֵי יִשְׂרָאֵל וְתִתּוֹסַף אַחֲסַנְתְּהוֹן עַל אַחֲסָנַת שִׁבְטָא דִי תְהֶוְיָן לְהוֹן וּמֵאַחֲסָנַת שִׁבְטָא דְאֲבְהָתָנָא יִתְמְנַע אַחֲסַנְתְּהֶן:
@1281 וּפַקִיד משֶׁה יָת בְּנֵי יִשְׂרָאֵל עַל מֵימְרָא דַיְיָ לְמֵימָר יָאוּת שִׁבְטָא דִבְנֵי יוֹסֵף מְמַלְלִין:
@1282 דֵין פִּתְגָמָא דִי פַקִיד יְיָ לִבְנַת צְלָפְחָד לְמֵימַר לִדְתַקִין בְּעֵינֵיהוֹן תְּהֶוְיַן לִנְשִׁין בְּרַם לְזַרְעִית שִׁבְטָא דַאֲבוּהֶן תְּהֶוְיַן לִנְשִׁין:
@1283 וְלָא תַסְחַר אַחֲסָנָא לִבְנֵי יִשְׂרָאֵל מִשִׁבְטָא לְשִׁבְטָא אֲרֵי גְבַר בְּאַחֲסָנַת שִׁבְטָא דַאֲבָהָתוֹהִי יִדְבְּקוּן בְּנֵי יִשְׂרָאֵל:
@1284 וְכָל בְּרַתָּא יַרְתַת אַחֲסָנָא מִשִׁבְטַּיָא דִבְנֵי יִשְׂרָאֵל לְחַד מִזַרְעִית שִׁבְטָא דַאֲבוּהָא תְּהֵי לְאִנְתּוּ בְּדִיל דְיֵרְתוּן בְּנֵי יִשְׂרָאֵל גְבַר אַחֲסָנַת אֲבָהָתוֹהִי:
@1285 וְלָא תַסְחַר אַחֲסָנָא מִשִׁבְטָא לְשִׁבְטָא אוֹחֲרָנָא אֲרֵי גְבַר בְּאַחֲסַנְתֵּהּ יִדְבְּקוּן שִׁבְטַיָא דִבְנֵי יִשְׂרָאֵל:
@1286 כְּמָא דִי פַקִיד יְיָ יָת משֶׁה כֵּן עֲבָדוּ בְּנַת צְלָפְחָד:
@1287 וַהֲוָאָה מַחְלָה תִרְצָה וְחָגְלָה וּמִלְכָּה וְנֹעָה בְּנַת צְלָפְחָד לִבְנֵי אֲחֵי אֲבוּהֶן לִנְשִׁין:
@1288 מִזַרְעֲיַת בְּנֵי מְנַשֶׁה בַר יוֹסֵף הֲוָאָה לִנְשִׁין וַהֲוַת אַחֲסַנְתְּהֶן עַל שִׁבְטָא זַרְעִית אֲבוּהֶן:
@1289 אִלֵין פִּקוּדַיָא וְדִינַיָא דִי פַקִיד יְיָ בִּידָא דְמשֶׁה לְוַת בְּנֵי יִשְׂרָאֵל בְּמֵישְׁרַיָא דְמוֹאָב עַל יַרְדְנָא דִירֵיחוֹ: חזק:

@1 **וידבר. במדבר סיני באחד לחדש.** וגו' . מתוך חבתן לפניו מונה אותם כל שעה, כשיצאו ממצרים מנאן, וכשנפלו בעגל מנאן לידע מנין הנותרים. כשבא להשרות שכינתו עליהן מנאן' באחד בניסן הוקם המשכן, ובאחד באיר מנאם:
@2 **למשפחתם.** דע מנין כל שבט ושבט: **לבית אבתם.** מי שאביו משבט אחד ואמו משבט אחר יקום על שבט אביו: **לגלגלתם.** על ידי שקלים בקע לגלגלת:
@3 **כל יצא צבא.** מגיד שאין יוצא בצבא פחות מבן עשרים:
@4 **ואתכם יהיו.** כשתפקדו אותם יהיו עמכם נשיא כל שבט ושבט:
@16 **אלה קרואי העדה.** הנקראים לכל דבר חשיבות שבעדה:
@17 **את האנשים האלה.** את שנים עשר נשיאים הללו: **אשר נקבו.** לו כאן בשמות:
@18 **ויתילדו על משפחתם.** הביאו ספרי יחוסיהם ועדי חזקת (לידתם) [לידת] כל אחד ואחד, להתיחס על השבט:
@49 **אך את מטה לוי לא תפקד.** כדאי הוא לגיון של מלך להיות נמנה לבדו. דבר אחר, צפה הקדוש ברוך הוא שעתידה לעמוד גזרה על כל הנמנין מבן עשרים שנה ומעלה שימותו במדבר, אמר אל יהיו אלו בכלל, לפי שהם שלי, שלא טעו בעגל:
@50 **ואתה הפקד את הלוים.** כתרגומו מני, לשון מנוי שררה על דבר שהוא ממנה עליו, כמו (אסתר ב' ג) ויפקד המלך פקידים:
@51 **יורידו אתו.** כתרגומו יפרקון, כשבאין לסע במדבר ממסע למסע היו מפרקין אותו מהקמתו, ונושאין אותו עד מקום אשר ישכון שם הענן ויחנו שם ומקימין אותו: **והזר הקרב.** לעבודתם זו: **יומת.** בידי שמים:
@52 **ואיש על דגלו.** כמו שהדגלים סדורים בספר זה, שלשה שבטים לכל דגל:
@53 **ולא יהיה קצף.** אם תעשה כמצותי לא יהיה קצף, ואם לאו שיכנסו זרים בעבודתם זו יהיה קצף, כמו שמצינו במעשה קרח (במדבר יז, יא) כי יצא הקצף וגו' :
@56 **באתת.** כל דגל יהיה לו אות. מפה צבועה תלויה בו. צבעו של זה לא כצבעו של זה, צבע כל אחד כגון אבנו הקבועה בחשן, ומתוך כך יכיר כל אחד את דגלו. דבר אחר באותות לבית אבתם באות שמסר להם יעקב אביהם כשנשאוהו ממצרים, שנאמר (בראשית נ, יב) ויעשו בניו לו כן כאשר צום, יהודה ויששכר וזבולן ישאוהו מן המזרח, וראובן ושמעון וגד מן הדרום וכו' , כדאיתא בתנחומא (במדבר יב) בפרשה זו: **מנגד.** מרחוק מיל, כמו שנאמר ביהושע (יהושע ג, ד) אך רחוק יהיה ביניכם וביניו כאלפים אמה, שיוכלו לבא בשבת, משה ואהרן ובניו והלוים חונים בסמוך לו:
@57 **קדמה.** לפנים הקרויה קדם, ואיזו, זו רוח מזרחית. והמערב קרוי אחור:
@63 **ראשנה יסעו.** כשרואין הענן מסתלק, תוקעין הכהנים בחצוצרות ונוסע מחנה יהודה תחלה, וכשהולכין, הולכין כדרך חניתן, הלוים והעגלות באמצע, דגל יהודה במזרח, ושל ראובן בדרום, ושל אפרים במערב, ושל דן בצפון:
@71 **ונסע אהל מועד.** לאחר שני דגלים הללו: **כאשר יחנו כן יסעו.** כמו שפרשתי, הליכתן כחניתן, כל דגל מהלך לרוח הקבועה לו: **על ידו.** על מקומו. ואין לשון יד זז ממשמעו, רוח שלצדו, קרוי על ידו, הסמוכה לו לכל הושטת ידו. אי''ן שו''ן איש''א בלע''ז [על ידו] :
@74 **ועליו.** כתרגומו ודסמיכין עלוהי:
@89 **ואלה תולדת אהרן ומשה.** ואינו מזכיר אלא בני אהרן. ונקראו תולדות משה, לפי שלמדן תורה. מלמד שכל המלמד את בן חברו תורה, מעלה עליו הכתוב כאלו ילדו: **ביום דבר ה' את משה.** נעשו אלו התולדות שלו, שלמדן מה שלמד מפי הגבורה:
@92 **על פני אהרן.** בחייו:
@94 **ושרתו אתו.** ומהו השרות, ושמרו את משמרתו, לפי ששמירת המקדש עליו שלא יקרב זר, כמו שנאמר (במדבר יח, א) אתה ובניך ובית אביך אתך תשאו את עון המקדש, והלוים הללו מסיעין אותם, זה הוא השרות:
@95 **ושמרו את משמרתו.** כל מנוי שהאדם ממנה עליו ומטל עליו לעשותו, קרוי משמרת בכל המקרא ובלשון משנה, כמו שאמרו בבגתן ותרש (מגילה יג, ב) והלא אין משמרתי ומשמרתך שוה, וכן משמרות כהנה ולויה:
@96 **ואת משמרת בני ישראל.** שכלן היו זקוקין לצרכי המקדש, אלא שהלוים באים תחתיהם בשליחותם, לפיכך לוקחים מהם המעשרות בשכרן, שנאמר (במדבר יח, לא) כי שכר הוא לכם חלף עבודתכם:
@97 **נתונים המה לו.** לעזרה: **מאת בני ישראל.** כמו מתוך בני ישראל, כלומר משאר כל העדה נבדלו לכך בגזרת המקום, והוא נתנם לו, שנאמר (במדבר ח, יט) ואתנה את הלוים נתונים וגו':
@98 **ואת אהרן ואת בניו תפקד.** לשון פקידות ואינו לשון מנין: **ושמרו את כהנתם.** קבלת דמים וזריקה והקטרה ועבודות המסורות לכהנים:
@100 **ואני הנה לקחתי.** ואני מהיכן זכיתי בהן: **מתוך בני ישראל.** שיהיו ישראל שוכרין אותן לשרות שלי. על ידי הבכורות זכיתי בהם ולקחתים תמורתם, לפי שהיתה העבודה בבכורות, וכשחטאו בעגל נפסלו, והלוים שלא עבדו עבודה זרה נבחרו תחתיהם:
@103 **מבן חדש ומעלה.** משיצא מכלל נפלים הוא נמנה לקרא שומר משמרת הקדש. אמר ר' יהודה ברבי שלום למוד הוא אותו השבט להיות נמנה מן הבטן, שנאמר (במד' כו, כט) אשר ילדה אתה ללוי במצרים, עם כניסתה בפתח מצרים ילדה אתה. ונמנית בשבעים נפש, שכשאתה מונה חשבונם לא תמצאם אלא שבעים חסר אחת, והיא השלימה את המנין:
@104 **על פי ה'.** אמר משה לפני הקדוש ברוך הוא היאך אני נכנס לבתי כלם ולתוך אהליהם לדעת מנין יונקיהם. אמר לו הקדוש ברוך הוא עשה אתה את שלך ואני אעשה את שלי. הלך משה ועמד על פתח האהל והשכינה מקדמת לפניו, ובת קול יוצאת מן האהל ואומרת כך וכך תינוקות יש באהל זה, לכך נאמר על פי ה':
@109 **לגרשון משפחת הלבני.** כלומר לגרשון היו הפקודים משפחת הלבני ומשפחת השמעי פקודיהם כך וכך:
@113 **המשכן.** יריעות התחתונות: **והאהל.** יריעות עזים העשויות לגג: **מכסהו.** עורות אילים ותחשים: **ומסך פתח.** הוא הוילון:
@114 **ואת מיתריו.** של משכן והאהל ולא של חצר:
@117 **משפחת בני קהת יחנו** וגו' **תימנה.** וסמוכין להם דגל ראובן החונים תימנה, אוי לרשע ואוי לשכנו, לכך לקו מהם דתן ואבירם ומאתים וחמשים איש עם קרח ועדתו, שנמשכו עמהם במחלקתם:
@119 **והמסך.** היא הפרכת, שאף היא קרויה פרכת המסך:
@120 **ונשיא נשיאי הלוי.** ממנה על כלם. ועל מה היא נשיאותו, פקדת שומרי משמרת הקדש, על ידו היה פקדת כלם:
@126 **משה ואהרן ובניו.** וסמוכין להם דגל מחנה יהודה, והחונים עליו יששכר וזבולן, טוב לצדיק טוב לשכנו, לפי שהיו שכניו של משה שהיה עוסק בתורה, נעשו גדולים בתורה, שנאמר (תהלים ס, ט) יהודה מחקקי, ומבני יששכר יודעי בינה וגו' (דה''י א' יב לג) מאתים ראשי סנהדראות, ומזבולן משכים בשבט סופר (שופטים ה יד) :
@127 **אשר פקד משה ואהרן.** נקוד על ואהרן, לומר שלא היה במנין הלוים: **שנים ועשרים אלף.** ובפרטן אתה מוצא שלש מאות יתרים, בני גרשון שבעת אלפים וחמש מאות, בני קהת שמונת אלפים ושש מאות, בני מררי ששת אלפים ומאתים, [הרי שנים ועשרים אלף ושלש מאות] . ולמה לא כללן עם השאר ויפדו את הבכורות, ולא יהיו זקוקים השלשה ושבעים ומאתים בכורות העודפים על המנין לפדיון, אמרו רבותינו במסכת בכורות (בכורות ה א) אותן שלש מאות לוים בכורות היו ודים שיפקיעו עצמם מן הפדיון:
@128 **פקד כל בכור זכר** וגו' **מבן חדש ומעלה.** משיצא מכלל ספק נפלים:
@133 **ואת בהמת הלוים** וגו' **.** לא פדו בהמות הלוים את בכורי בהמה טהורה שלישראל, אלא את פטרי חמוריהם, ושה אחד של בן לוי פטר כמה פטרי חמורים שלישראל, תדע שהרי מנה העודפים באדם ולא מנה העודפים בבהמה:
@134 **ואת פדויי השלשה** וגו' **.** ואת הבכורות הצריכין להפדות בהם, אלו השלשה ושבעים ומאתים העודפים בהם, יתרים על הלוים, מהם תקח חמשת שקלים לגלגלת, כך היתה מכירתו של יוסף עשרים כסף, שהיה בכורה של רחל:
@137 **העדפים על פדויי הלוים.** על אותן שפדו הלוים בגופן:
@138 **חמשה וששים ושלש מאות ואלף.** כך סכום החשבון חמשת שקלים לגלגלת. למאתים בכורות אלף שקל, לשבעים בכורות שלש מאות וחמשים שקל, לשלש בכורות חמשה עשר שקל. אמר כיצד אעשה, בכור שאומר לו תן חמשת שקלים, יאמר לי אני מפדויי הלוים. מה עשה, הביא שנים ועשרים אלף פתקין וכתב עליהן בן לוי, ומאתים ושבעים ושלשה פתקין כתב עליהן חמשה שקלים, בללן ונתנן בקלפי, אמר להם בואו וטלו פתקיכם לפי הגורל:
@141 **נשא את ראש** וגו' **.** מנה מהם את הראויין לעבודת משא, והם מבן שלשים ועד בן חמשים שנה, והפחות משלשים לא נתמלא כחו. מכאן אמרו בן שלשים לכח, והיותר על בן חמשים כחו מכחיש מעתה:
@143 **קדש הקדשים.** המקדש שבכלן הארון והשלחן והמנורה והמזבחות והפרוכת וכלי שרת:
@144 **ובא אהרן ובניו** וגו' **.** יכניסו כל כלי וכלי לנרתקו המפורש לו בפרשה זו, ולא יצטרכו הלוים בני קהת אלא לשאת: **בנסוע המחנה.** כשהענן מסתלק הם יודעין שיסעו:
@146 **קערת וכפות קשות ומנקיות.** כבר פרשתי במלאכת המשכן: **הנסך.** הכסוי לשון מסך, כדכתיב (שמות כה, כט) אשר יסך בהן:
@148 **מלקחיה.** כמין צבת שמושך בה את הפתילה לכל צד שירצה: **מחתתיה.** כמין כף קטנה ושוליה פשוטין ולא סגלגלים, ואין לה מחצה לפניה אלא מצדיה, וחותה בה את דשן הנרות כשמטיבן: **נרתיה.** לוצי''ש בלע''ז [מנורות] שנותנים בהן השמן והפתילות:
@149 **אל מכסה עור תחש.** כמין מרצוף:
@151 **את כל כלי השרת אשר ישרתו בם בקדש.** בתוך המשכן שהוא קדש, והן כלי הקטרת שמשרתין בהם במזבח הפנימי:
@152 **ודשנו את המזבח.** מזבח הנחשת: **ודשנו.** יטלו את הדשן מעליו: **ופרשו עליו בגד ארגמן.** ואש שירדה מן השמים רבוצה תחת הבגד כארי בשעת המסעות, ואינה שורפתו, שהיו כופין עליה פסכתר של נחשת:
@153 **מחתת.** שבהן חותים גחלים לתרומת הדשן, שעשויה כמין מחבת שאין לה אלא שלש מחצות, ומלפניה שואבת את הגחלים: **מזלגות.** צנוריות של נחשת שבהן מכין באברים שעל המזבח להפכן כדי שיתעכלו יפה ומהר: **יעים.** הם מגרפות ובלע''ז ודי''ל [מגרפה] והן של נחשת ובהן מכבדין את הדשן מעל המזבח:
@154 **לכסת את הקדש.** הארון והמזבח: **ואת כל כלי הקדש.** המנורה וכלי שרת: **ומתו.** שאם יגעו חייבין מיתה בידי שמים:
@155 **ופקדת אלעזר.** שהוא ממנה עליהם לשאת אותם, שמן וקטרת ושמן המשחה ומנחת התמיד, עליו מטל לצוות ולזרז ולהקריב בעת חנייתן: **פקדת כל המשכן.** ועוד היה ממנה על משא בני קהת לצוות איש איש על עבודתו ועל משאו, והוא המשכן וכל אשר בו, כל הסדורים למעלה בפרשה זו, אבל משא בני גרשון ומררי שאינן מקדש הקדשים, על פי איתמר היה, כמו שכתוב בפרשת נשא (פסוק כח) :
@157 **אל תכריתו.** אל תגרמו להם שימותו:
@159 **ולא יבאו לראות כבלע את הקדש.** לתוך נרתק שלו, כמו שפרשתי למעלה (פסוק ה) בפרשה זו, ופרשו עליו בגד פלוני וכסו אותו במכסה פלוני, ובלוע שלו הוא כסויו:
@161 **נשא את ראש בני גרשון גם הם.** כמו שצויתיך על בני קהת לראות כמה יש שהגיעו לכלל עבודה:
@164 **את יריעת המשכן.** עשר תחתונות: **ואת אהל מועד.** יריעות עזים העשויות לאהל עליו: **מכסהו.** עורות אילים מאדמים: **מסך פתח.** וילון המזרחי:
@165 **אשר על המשכן.** כלומר הקלעים והמסך של חצר הסוככים ומגינים על המשכן ועל מזבח הנחשת סביב: **ואת כל אשר יעשה להם.** כתרגומו ית כל דיתמסר להון, לבני גרשון:
@166 **על פי אהרן ובניו.** ואיזה מהבנים ממנה עליהם, ביד איתמר בן אהרן הכהן:
@171 **ויתדתם ומיתריהם.** של עמודים, שהרי יתדות ומיתרי הקלעים במשא בני גרשון היו, ויתדות ומיתרים היו ליריעות ולקלעים מלמטה, שלא תגביהם הרוח, ויתדות ומיתרים היו לעמודים סביב לתלות בהם הקלעים בשפתם העליונה, בכלנסות וקנדסין [וקנטסין] , כמו ששנויה במלאכת המשכן:
@186 **עבדת עבדה.** הוא השיר במצלתים וכנורות, שהיא עבודה לעבודה אחרת: **ועבודת משא.** כמשמעו:
@188 **ופקדיו אשר צוה ה' את משה.** ואותן הפקודים היו במצוה מבן שלשים שנה ועד בן חמשים שנה:
@190 **צו את בני ישראל** וגו' **.** פרשה זו נאמרה ביום שהוקם המשכן, ושמנה פרשיות נאמרו בו ביום, כדאיתא במסכת גיטין בפרק הנזקין (ס, א) : **וישלחו מן המחנה.** שלש מחנות היו שם בשעת חניתן, תוך הקלעים היא מחנה שכינה, חנית הלוים סביב כמו שמפורש בפרשת במדבר סיני היא מחנה לויה, ומשם ועד סוף מחנה הדגלים לכל ארבע הרוחות היא מחנה ישראל. הצרוע נשתלח חוץ לכלן, הזב מתר במחנה ישראל ומשלח מן השתים, וטמא לנפש מתר אף בשל לויה ואינו משלח אלא משל שכינה, וכל זה דרשו רבותינו מן המקראות במסכת פסחים (סז) : **טמא לנפש.** דמסאב לטמי נפשא דאנשא. אומר אני שהוא לשון עצמות אדם בלשון ארמי, והרבה יש בבראשית רבה אדרינוס שחיק טמיא, שחיק עצמות:
@194 **למעל מעל בה'.** הרי חזר וכתב כאן פרשת גוזל ונשבע על שקר, היא האמורה בפרשת ויקרא (ה, כא) ומעלה מעל בה' וכחש בעמיתו וגו' , ונשנית כאן בשביל שני דברים שנתחדשו בה האחד, שכתב והתודו, למד שאינו חיב חומש ואשם על פי עדים עד שיודה בדבר. והשני על גזל הגר שהוא נתון לכהנים:
@195 **את אשמו בראשו.** הוא הקרן שנשבע עליו: **לאשר אשם לו.** למי שנתחיב לו:
@196 **ואם אין לאיש גואל.** שמת התובע שהשביעו, ואין לו יורשים: **להשיב האשם אליו.** כשנמלך זה להתודות על עונו. ואמרו רבותינו וכי יש לך אדם בישראל שאין לו גואלים או בן או אח או שאר בשר הקרוב ממשפחת אביו למעלה עד יעקב, אלא זה הגר שמת ואין לו יורשים: **האשם המושב.** זה הקרן והחומש: **לה' לכהן.** קנאו השם ונתנו לכהן שבאותו משמר: **מלבד איל הכפורים.** האמור בויקרא (ויקרא ה, כה) שהוא צריך להביא:
@197 **וכל תרומה** וגו' **.** אמר רבי ישמעאל וכי תרומה מקריבין לכהן, והלא הוא המחזר אחריה לבית הגרנות. ומה תלמוד לומר אשר יקריבו לכהן, אלו הבכורים, שנאמר בהם תביא בית ה' אלהיך, (שמות כג, יט) . ואיני יודע מה יעשה בהם, תלמוד לומר לכהן לו יהיה, בא הכתוב ולמד על הבכורים שיהיו נתנין לכהן:
@198 **ואיש את קדשיו לו יהיו.** לפי שנאמרו מתנות כהנה ולויה יכול יבואו ויטלום בזרוע, תלמוד לומר ואיש את קדשיו לו יהיו, מגיד שטובת הנאתן לבעלים, ועוד מדרשים הרבה דרשו בו בספרי. ומדרש אגדה ואיש את קדשיו לו יהיו, מי שמעכב מעשרותיו ואינו נותנן, לו יהיו המעשרות, סוף שאין שדהו עושה אלא אחד מעשרה שהיתה למודה לעשות: **איש אשר יתן לכהן.** מתנות הראויות לו: **לו יהיה.** ממון הרבה:
@200 **איש איש כי תשטה אשתו.** מה כתיב למעלה מן הענין ואיש את קדשיו לו יהיו, אם אתה מעכב מתנות הכהן, חייך שתצטרך לבא אצלו להביא לו את הסוטה: **איש איש.** ללמדך שמועלת בשתים, באיש מלחמה של מעלה ואישה מלמטה: **כי תשטה אשתו.** שנו רבותינו אין המנאפין נואפין עד שתכנס בהן רוח שטות, דכתיב כי תשטה, וכתוב בו נואף אשה חסר לב (משלי ו, לב) . ופשוטו של מקרא כי תשטה. תט מדרכי צניעות ותחשד בעיניו, כמו שטה מעליו ועבר (שם ד, טו) , אל ישט אל דרכיה לבך (שם ז, כה) : **ומעלה בו מעל.** ומהו המעל, ושכב איש אותה:
@201 **ושכב איש.** פרט לקטן ומי שאינו איש: **אתה שכבת זרע.** שכיבתה פוסלת אותה, ואין שכיבת אחותה פוסלת אותה כמעשה בשתי אחיות שהיו דומות זו לזו: **ונעלם מעיני אישה.** פרט לסומא הא אם היה רואה ומעמעם [ומעלים] אין המים בודקין אותה: **ונסתרה.** שיעור שתראה לטמאת ביאה: **ועד אין בה.** הא אם יש בה אפלו עד אחד שאמר נטמאת לא היתה שותה: **ועד אין בה.** לטמאה אבל יש עדים לסתירה: **נתפשה.** נאנסה, כמו ותפשה ושכב עמה (דברים כב, כח) :
@202 **ועבר עליו.** קודם לסתירה: **רוח קנאה וקנא.** פרשו רבותינו לשון התראה, שמתרה בה אל תסתרי עם איש פלוני: **והיא נטמאה או עבר עליו** וגו' **.** כלומר הוא התרה בה ועברה על התראתו, ואין ידוע אם נטמאה אם לאו:
@203 **קמח.** שלא יהא מסלת: **שערים.** ולא חטים, היא עשתה מעשה בהמה וקרבנה מאכל בהמה: **לא יצק עליו שמן.** שלא יהא קרבנה מהדר, שהשמן קרוי אור והיא עשתה בחשך: **ולא יתן עליו לבנה.** שהאמהות נקראות לבונה, שנאמר ואל גבעת הלבונה (שה''ש ד, ו) , והיא פרשה מדרכיהן: **כי מנחת קנאת הוא.** הקמח הזה, קמח לשון זכר: **מנחת קנאת.** מעוררת עליה שתי קנאות, קנאת המקום וקנאת הבעל:
@205 **מים קדשים.** שקדשו בכיור, לפי שנעשה מנחשת מראות הצובאות, וזו פרשה מדרכיהן שהיו נבעלות לבעליהן במצרים תחת התפוח, וזו קלקלה לאחר, תבדק בו: **בכלי חרש.** היא השקתה את הנואף יין משבח בכוסות משבחים, לפיכך תשתה מים המרים במקדה בזויה של חרש:
@206 **והעמיד הכהן** וגו' **.** והלא כבר נאמר והעמידה לפני ה', אלא מסיעין היו אותה ממקום למקום כדי ליגעה ותטרף דעתה ותודה: **ופרע.** סתר את קליעת שערה כדי לבזותה, מכאן לבנות ישראל שגלוי הראש גנאי להן: **לפני ה'.** בשער נקנור, הוא שער העזרה המזרחי, דרך כל הנכנסים: **ונתן על כפיה.** ליגעה אולי תטרף דעתה ותודה, ולא ימחה שם המיוחד על המים: **המרים.** על שם סופן שהם מרים לה: **המאררים.** המחסרים אותה מן העולם, לשון סלון ממאיר (יחזקאל כח, כד) . ולא יתכן לפרש מים ארורים, שהרי קדושים הן, ולא ארורים כתב הכתוב, אלא מאררים את אחרים. ואף אנקלוס לא תרגם ליטיא, אלא מלטטיא, שמראות קללה בגופה של זו:
@207 **והשביע אתה** וגו' **.** ומה היא השבועה אם לא שכב, הנקי, הא אם שכב חנקי [לא תנקי] , שמכלל לאו אתה שומע הן, אלא שמצוה לפתוח בדיני נפשות תחלה לזכות:
@208 **ואת כי שטית.** כי משמש בלשון אם:
@209 **בשבעת האלה.** שבועה של קללה: **יתן ה' אותך לאלה.** שיהיו הכל מקללין ביך יבואך כדרך שבא לפלונית: **ולשבועה.** שיהיו הכל נשבעין ביך לא יארע לי כדרך שארע לפלונית וכן הוא אומר והנחתם שמכם לשבועה לבחירי (ישעיה סה, טו) , שהצדיקים נשבעים בפרענותן של רשעים, וכן לענין הברכה ונברכו וגו' (בראש' יב, ג) בך יברך ישראל לאמר (בראש' מח, כ) : **את ירכך.** בקללה הקדים ירך לבטן לפי שבה התחילה בעברה תחלה: **צבה.** כתרגומו נפוחה:
@210 **לצבות בטן.** כמו להצבות בטן, זהו שמוש פתח שהלמ''ד נקודה בו, וכן לנחותם הדרך (שמות יג, כא) , לראותכם בדרך אשר תלכו בה (דברים א, לג) , וכן לנפיל ירך להנפיל ירך, שהמים מצבים את הבטן ומפילים את הירך: **לצבות בטן ולנפיל ירך.** בטנו וירכו של בועל, או אינו אלא של נבעלת, כשהוא אומר את ירכך נופלת ואת בטנך צבה, הרי של נבעלת אמור: **אמן אמן.** קבלת שבועה, אמן על האלה אמן על השבועה, אמן אם מאיש זה, אמן אם מאיש אחר, אמן שלא סטיתי ארוסה ונשואה שומרת יבם וכנוסה:
@212 **והשקה את האשה.** אין זה סדר המעשה, שהרי בתחלה מקריב מנחתה, אלא הכתוב מבשרך שכשישקנה יבואו בה למרים. לפי שנאמר בטן וירך, מנין לשאר כל הגוף, תלמוד לומר ובאו בה בכלה, אם כן מה תלמוד לומר בטן וירך, לפי שהן התחילו בעברה תחלה, לפיכך התחילה מהן הפרענות: **למרים.** להיות לה רעים ומרים:
@213 **והניף.** מוליך ומביא מעלה ומוריד, ואף היא מניפה עמו שידה למעלה מידו של כהן: **והקריב אתה.** זו היא הגשתה בקרן דרומית מערבית של מזבח קודם קמיצה כשאר מנחות:
@214 **אזכרתה.** הוא הקומץ, שעל ידי הקטרתו המנחה באה לזכרון לגבוה:
@215 **והשקה את המים.** לרבות שאם אמרה איני שותה לאחר שנמחקה מגלה, מערערין אתה ומשקין אתה בעל כרחה, אלא אם כן אמרה טמאה אני: **וצבתה בטנה** וגו' **.** אף על פי שבקללה הזכיר ירך תחלה, המים אין בודקין אלא דרך כניסתן בה: **והיתה האשה לאלה.** כמו שפרשתי שהיו הכל אלין בה: **בקרב עמה.** הפרש יש בין אדם המתנול במקום שנכר, לאדם המתנול במקום שאינו נכר:
@216 **ואם לא נטמאה האשה.** בסתירה זו: **וטהרה היא.** ממקום אחר: **ונקתה.** ממים המאררים, ולא עוד אלא ונזרעה זרע, אם היתה יולדת בצער תלד ברוח, אם היתה יולדת שחורים יולדת לבנים:
@218 **או איש.** כמו או נודע (שמות כא, לו) , כלומר אם איש קנאי הוא, לכך והעמיד את האשה:
@219 **ונקה האיש מעון.** אם בדקוה המים אל ידאג לומר חבתי במיתתה, נקי הוא מן הענש. דבר אחר משישקנה תהיה אצלו בהתר ונקה מעון, שהסוטה אסורה לבעלה:
@221 **כי יפלא.** יפריש. למה נסמכה פרשת נזיר לפרשת סוטה, לומר לך שכל הרואה סוטה בקלקולה יזיר עצמו מן היין, שהוא מביא לידי ניאוף: **נדר נזיר.** אין נזירה בכל מקום אלא פרישה, אף כאן שפרש מן היין: **להזיר לה'.** להבדיל עצמו מן היין לשם שמים:
@222 **מיין ושכר.** כתרגומו מחמר חדת ועתיק, שהיין משכר כשהוא ישן: **וכל משרת.** לשון צביעה במים וכל משקה, ובלשון משנה יש הרבה אין שורין דיו וסמנים (שבת יז, ב) , נזיר ששרה פתו ביין (נזיר לד, ב) :
@223 **חרצנים.** הם הגרענין: **זג.** הם קלפות שמבחוץ, שהחרצנים בתוכן כענבל בזוג:
@224 **קדש יהיה.** השער שלו, לגדל הפרע של שער ראשו: **פרע.** נקוד פתח קטן לפי שהוא דבוק לשער ראשו, פרע של שער. ופרושו של פרע, גדול של שער, וכן את ראשו לא יפרע (ויקרא כא, י) , ואין קרוי פרע פחות משלושים יום:
@227 **כל ימי נזרו קדש הוא.** זו קדשת הגוף מלטמא למתים:
@228 **בפתע.** זה אונס: **פתאם.** זה שוגג. ויש אומרים פתע פתאום דבר אחד הוא, מקרה של פתאום: **וכי ימות מת עליו.** באהל שהוא בו: **ביום טהרתו.** ביום הזאתו, או אינו אלא בשמיני שהוא טהור לגמרי, תלמוד לומר ביום השביעי, אי שביעי יכול אפלו לא הזה, תלמוד לומר ביום טהרתו:
@229 **וביום השמיני יבא שתי תרים.** להוציא את השביעי. או אינו אלא להוציא את התשיעי, קבע זמן לקרבין וקבע זמן למקריבין, מה קרבין הכשיר שמיני ומשמיני והלאה, אף מקריבין שמיני ומשמיני והלאה:
@230 **מאשר חטא על הנפש.** שלא נזהר מטמאת המת, רבי אלעזר הקפר אומר שציער עצמו מן היין: **וקדש את ראשו.** לחזור ולהתחיל מנין נזירותו:
@231 **והזיר לה' את ימי נזרו.** יחזור וימנה נזירותו כבתחלה: **והימים הראשונים יפלו.** לא יעלו מן המנין:
@232 **יביא אתו.** יביא את עצמו, זה אחד משלשה אתים שהיה ר' ישמעאל דורש כן. כיוצא בו והשיאו אותם עון אשמה (ויקרא כב, טז) , את עצמם, כיוצא בו ויקבור אותו בגיא (דברים לד, ו) , הוא קבר את עצמו:
@234 **ומנחתם ונסכיהם.** של עולה ושלמים, לפי שהיו בכלל ויצאו לדון בדבר חדש שיטעינו לחם, החזירן לכללן שיטעינו נסכים כדין עולה ושלמים: **חלת בלולת ורקיקי מצות.** עשר מכל מין:
@236 **זבח שלמים לה' על סל המצות.** ישחט את השלמים על מנת לקדש את הלחם: **את מנחתו ואת נסכו.** של איל:
@237 **וגלח הנזיר פתח אהל מועד.** יכול יגלח בעזרה, הרי זה דרך בזיון. אלא וגלח הנזיר לאחר שחיטת השלמים שכתוב בהן ושחטו פתח אהל מועד (ויקרא ג, ב) , ספרי: **אשר תחת זבח השלמים.** תחת הדוד שהוא מבשלן בו, לפי ששלמי נזיר היו מתבשלין בעזרה, שצריך לטול הכהן הזרוע אחר שנתבשלה ולהניף לפני ה':
@238 **הזרוע בשלה.** לאחר שנתבשלה:
@239 **קדש הוא לכהן.** החלה והרקיק והזרוע תרומה הן לכהן: **על חזה התנופה.** מלבד חזה ושוק הראויים לו מכל שלמים מוסף על שלמי נזיר הזרוע הזה, לפי שהיו שלמי נזיר בכלל ויצאו לדון בדבר החדש להפרשת זרוע הצרך להחזירן לכללן לדון אף בחזה ושוק:
@240 **מלבד אשר תשיג ידו.** שאם אמר הריני נזיר על מנת לגלח על מאה עולות ועל מאה שלמים, **כפי נדרו אשר ידור כן יעשה מוסף על תורת נזרו.** על תורת הנזיר יוסיף ולא יחסר, שאם אמר הריני נזיר חמש נזירות על מנת לגלח על שלש בהמות הללו, אין אני קורא בו כאשר ידור כן יעשה:
@242 **אמור להם.** כמו זכור שמור, בלע''ז דישנ''ט (באמרכם) : **אמור להם.** שיהיו כלם שומעים: **אמור.** מלא, לא תברכם בחפזון ובהלות, אלא בכונה ובלב שלם:
@243 **יברכך.** שיתברכו נכסיך: **וישמרך.** שלא יבואו עליך שודדים לטול ממונך, שהנותן מתנה לעבדו אינו יכול לשמרו מכל אדם, וכיון שבאים לסטים עליו ונוטלין אותה ממנו, מה הנאה יש לו במתנה זו, אבל הקדוש ברוך הוא הוא הנותן הוא השומר. והרבה מדרשים דרשו בו בספרי:
@244 **יאר ה' פניו אליך.** יראה לך פנים שוחקות, פנים צהובות: **ויחנך.** יתן לך חן:
@245 **ישא ה' פניו אליך.** יכבוש כעסו:
@246 **ושמו את שמי.** יברכום בשם המפורש: **ואני אברכם.** לישראל ואסכים עם הכהנים. דבר אחר ואני אברכם לכהנים:
@247 **ויהי ביום כלות משה.** כלת כתיב, יום הקמת המשכן היו ישראל ככלה הנכנסת לחפה: **כלות משה.** בצלאל ואהליאב וכל חכם לב עשו את המשכן, ותלאו הכתוב במשה, לפי שמסר נפשו עליו לראות תבנית כל דבר ודבר כמו שהראהו בהר להורות לעושי המלאכה, ולא טעה בתבנית אחת וכן מצינו בדוד לפי שמסר נפשו על בנין בית המקדש, שנאמר זכור ה' לדוד את כל ענותו אשר נשבע לה' וגו' (תהלים קלב, א. ב) , לפיכך נקרא על שמו, שנאמר ראה ביתך דוד (מלכים א' יב, טז) : **ביום כלות משה להקים.** ולא נאמר ביום הקים מלמד שכל שבעת ימי המלואים היה משה מעמידו ומפרקו ובאותו היום העמידו ולא פרקו, לכך נאמר ביום כלות משה להקים, אותו היום כלו הקמותיו וראש חדש ניסן היה, בשני נשרפה הפרה, בשלישי הזו הזיה ראשונה, ובשביעי גלחו:
@248 **הם נשיאי המטת.** שהיו שוטרים עליהם במצרים והיו מכים עליהם, שנאמר (שמות ה) ויכו שוטרי בני ישראל וגו' : **הם העומדים על הפקדים.** שעמדו עם משה ואהרן כשמנו את ישראל, שנאמר (במדבר א) ואתכם יהיו וגו' :
@249 **שש עגלת צב.** אין צב אלא מחפים וכן (ישעיה סו, כ) בצבים ובפרדים, עגלות מכסות קרויות צבים: **ויקריבו אותם לפני המשכן.** שלא קבל משה מידם עד שנאמר לו מפי המקום. אמר רבי נתן מה ראו הנשיאים להתנדב כאן בתחלה, ובמלאכת המשכן לא התנדבו תחלה, אלא כך אמרו הנשיאים יתנדבו צבור מה שיתנדבו, ומה שמחסרין אנו משלימין, כיון שראו שהשלימו צבור את הכל, שנאמר (שמות לו, ז) והמלאכה היתה דים, אמרו מעתה מה לנו לעשות, הביאו את אבני השוהם והמלואים לאפוד ולחשן, לכך התנדבו כאן תחלה:
@253 **כפי עבדתם.** שהיה משא בני גרשון קל משל מררי, שהיו נושאים הקרשים והעמודים והאדנים:
@255 **כי עבדת הקדש עליהם.** משא דבר הקדשה הארון והשלחן וגו' , לפיכך בכתף ישאו:
@256 **ויקריבו הנשאים את חנכת המזבח.** לאחר שהתנדבו העגלות והבקר לשאת המשכן, נשאם לבם להתנדב קרבנות המזבח לחנכו: **ויקריבו הנשיאים את קרבנם לפני המזבח.** כי לא קבל משה מידם עד שנאמר לו מפי הגבורה:
@257 **יקריבו את קרבנם לחנכת המזבח.** ועדין לא היה יודע משה היאך יקריבו, אם כסדר תולדותם, אם כסדר המסעות, עד שנאמר לו מפי הקדוש ברוך הוא יקריבו למסעות, איש יומו:
@258 **ביום הראשון.** אותו היום נטל עשר עטרות, ראשון למעשה בראשית, ראשון לנשיאים וכו' , כדאיתא בסדר עולם: **למטה יהודה.** יחסו הכתוב על שבטו, ולא שגבה משבטו והקריב. או אינו אומר למטה יהודה אלא שגבה משבטו והביא, תלמוד לומר זה קרבן נחשון, משלו הביא:
@259 **שניהם מלאים סלת.** למנחת נדבה:
@260 **עשרה זהב.** כתרגומו, משקל עשר שקלי הקדש היה בה: **מלאה קטרת.** לא מצינו קטרת ליחיד ולא על מזבח החיצון אלא זו בלבד, והוראת שעה היתה:
@261 **פר אחד.** מיוחד שבעדרו:
@262 **שעיר עזים אחד לחטאת.** לכפר על קבר התהום וטמאת ספק:
@265 **הקריב נתנאל בן צוער. הקרב את קרבנו.** מה תלמוד לומר הקריב בשבטו של יששכר, מה שלא נאמר בכל השבטים, לפי שבא ראובן וערער ואמר די שקדמני יהודה אחי, אקריב אני אחריו. אמר לו משה מפי הגבורה נאמר לי שיקריבו כסדר מסען לדגליהם. לכך אמר הקרב את קרבנו, והוא חסר יו''ד, שהוא משמע הקרב, לשון צווי, שמפי הגבורה נצטוה הקרב. ומהו הקריב הקרב שני פעמים, שבשביל שני דברים זכה להקריב שני לשבטים אחת שהיו יודעים בתורה, שנאמר (ד''ה א' יב, לג) ומבני יששכר יודעי בינה לעתים, ואחת שהם נתנו עצה לנשיאים להתנדב קרבנות הללו. וביסודו שלר' משה הדרשן מצאתי אמר רבי פנחס בן יאיר, נתנאל בן צוער השיאן עצה זו: **קערת כסף.** מנין אותיותיו בגימטריה תתק''ל כנגד שנותיו של אדם הראשון: **שלשים ומאה משקלה.** על שם שכשהעמיד תולדות לקיום העולם בן מאה ושלשים שנה היה, שנאמר (בראשית ה, ג) ויחי אדם שלשים ומאת שנה ויולד בדמותו וגו' : **מזרק אחד כסף.** בגימטריה תק''כ, על שם נח שהעמיד תולדות בן ת''ק שנה, ועל שם עשרים שנה שנגזרה גזרת המבול קודם תולדותיו, כמו שפרשתי אצל (בראשית ו, ג) והיו ימיו מאה ועשרים שנה, לפיכך נאמר מזרק אחד כסף ולא נאמר מזרק כסף אחד, כמו שנאמר בקערה, לומר שאף אותיות של אחד מצטרפות למנין: **שבעים שקל.** כנגד שבעים אמות שיצאו מבניו:
@266 **כף אחת.** כנגד התורה שנתנה מידו של הקדוש ברוך הוא: **עשרה זהב.** כנגד עשרת הדברות: **מלאה קטרת.** גימטריה של קטרת תרי''ג מצות, ובלבד שתחליף קו''ף בד,, ל על ידי א''ת ב''ש ג''ר ד''ק:
@267 **פר אחד.** כנגד אברהם, שנאמר בו (בראשית יח, ז) ויקח בן בקר: **איל אחד.** כנגד יצחק (שם כב, יג) ויקח את האיל וגו' : **כבש אחד.** כנגד יעקב (שם ל, מ) והכשבים הפריד יעקב:
@268 **שעיר עזים.** לכפר על מכירת יוסף, שנאמר בו (שם לז, לא) וישחטו שעיר עזים:
@269 **ולזבח השלמים בקר שנים.** כנגד משה ואהרן, שנתנו שלום בין ישראל לאביהם שבשמים: **אילם עתדים כבשים.** שלשה מינים כנגד כהנים ולוים וישראלים, וכנגד תורה נביאים וכתובים. שלש חמשיות כנגד חמשה חמשין, וחמשת הדברות הכתובין על לוח אחד, וחמשה הכתובין על השני. עד כאן מיסודו של ר' משה הדרשן:
@270 **ביום השלישי נשיא** וגו' **.** ביום השלישי היה נשיא המקריב לבני זבולן, וכן כלם, אבל בנתנאל שנאמר בו הקריב נתנאל, נופל אחריו הלשון לומר נשיא יששכר, לפי שכבר הזכיר שמו והקרבתו, ובשאר שלא נאמר בהן הקריב, נופל עליהן לשון זה נשיא לבני פלוני, אותו היום היה הנשיא המקריב לשבט פלוני:
@330 **ביום המשח אתו.** בו ביום שנמשח הקריב, ומה אני מקים אחרי המשח, שנמשח תחלה ואחר כך הקריב. או אחרי המשח לאחר זמן, ולא בא ללמד ביום המשח אלא לומר שנמשח ביום, כשהוא אומר (ויקרא ז, לו) ביום משחו אתם, למדנו שנמשח ביום, ומה תלמוד לומר ביום המשח אתו, ביום שנמשח הקריב: **קערת כסף שתים עשרה.** הם הם שהתנדבו ולא ארע בהם פסול:
@331 **שלשים ומאה הקערה האחת** וגו' **.** מה תלמוד לומר, לפי שנאמר שלשים ומאה משקלה, ולא פרש באיזו שקל, לכך חזר ושנאה כאן, וכלל בכלן כל כסף הכלים בשקל הקדש: **כל כסף הכלים** וגו' **.** למדך שהיו כלי המקדש מכונים במשקלן, שוקלן אחד אחד ושוקלן כלן כאחד, לא רבה ולא מעט:
@332 **כפות זהב שתים עשרה.** למה נאמר, לפי שנאמר כף אחת עשרה זהב, היא של זהב, ומשקלה עשרה שקלים של כסף, או אינו אלא כף אחת של כסף ומשקלה עשרה שקלי זהב, ושקלי זהב אין משקלם שוה לשל כסף, תלמוד לומר כפות זהב, של זהב היו:
@335 **ובבא משה.** שני כתובים המכחישים זה את זה, בא שלישי והכריע ביניהם. כתוב אחד אומר (ויקרא א, א) וידבר ה' אליו מאהל מועד, והוא חוץ לפרכת, וכתוב אחד אומר (שמות כה, כב) ודברתי אתך מעל הכפרת, בא זה והכריע ביניהם, משה בא אל אהל מועד ושם שומע את הקול הבא מעל הכפרת: **מבין שני הכרובים.** הקול יוצא מן השמים לבין שני הכרובים ומשם יצא לאהל מועד: **וישמע את הקול.** יכול קול נמוך, תלמוד לומר את הקול, הוא הקול שנדבר עמו בסיני, וכשמגיע לפתח היה נפסק, ולא היה יוצא חוץ לאהל: **מדבר.** כמו מתדבר, כבודו של מעלה לומר כן מדבר בינו לבין עצמו, ומשה שומע מאליו: **וידבר אליו.** למעט את אהרן מן הדברות:
@337 **בהעלתך.** למה נסמכה פרשת המנורה לפרשת הנשיאים, לפי שכשראה אהרן חנכת הנשיאים חלשה דעתו, שלא היה עמהם בחנכה, לא הוא ולא שבטו, אמר לו הקדוש ברוך הוא חייך, שלך גדולה משלהם, שאתה מדליק ומטיב את הנרות: **בהעלתך.** על שם שהלהב עולה, כתוב בהדלקתן לשון עליה, שצריך להדליק עד שתהא שלהבת עולה מאליה. ועוד דרשו רבותינו, מכאן שמעלה היתה לפני המנורה שעליה הכהן עומד ומטיב: **אל מול פני המנורה.** אל מול נר אמצעי שאינו בקנים, אלא בגוף של מנורה: **יאירו שבעת הנרות.** ששה שעל ששת הקנים, שלשה המזרחיים פונים למול האמצעי, הפתילות שבהן, וכן שלשה המערביים ראשי הפתילות למול האמצעי. ולמה, כדי שלא יאמרו לאורה הוא צריך:
@338 **ויעש כן אהרן.** להגיד שבחו של אהרן שלא שנה:
@339 **וזה מעשה המנורה.** שהראהו הקדוש ברוך הוא באצבע לפי שנתקשה בה, לכך נאמר וזה: **מקשה.** בטדי''ץ בלע''ז [עשוי בהכאה] לשון דא לדא נקשן (דניאל ה, ו) . עשת של ככר זהב היתה, ומקיש בקרנס וחותך בכשיל לפשט אבריה כתקונן, ולא נעשית אברים אברים על ידי חבור: **עד ירכה עד פרחה.** ירכה היא השדה שעל הרגלים, חלול כדרך מנורות כסף שלפני השרים: **עד ירכה עד פרחה.** כלומר גופה של מנורה כלה וכל התלוי בה: **עד ירכה.** שהוא אבר גדול: **עד פרחה.** שהוא מעשה דק שבה הכל מקשה. ודרך עד לשמש בלשון זה, כמו (שופטים טו, ה) מגדיש ועד קמה ועד כרם זית: **כמראה אשר הראה** וגו' **.** כתבנית אשר הראהו בהר, כמו שנאמר (שמות כה, מ) וראה ועשה בתבניתם וגו' : **כן עשה את המנורה.** מי שעשאה. ומדרש אגדה על ידי הקדוש ברוך הוא נעשית מאליה:
@341 **קח את הלוים.** קחם בדברים, אשריכם שתזכו להיות שמשים למקום:
@342 **הזה עליהם מי חטאת.** של אפר הפרה מפני טמאי מתים שבהם: **והעבירו תער.** מצאתי בדברי רבי משה הדרשן, לפי שנתנו כפרה על הבכורות שעבדו עבודה זרה והיא קרויה זבחי מתים, והמצורע קרוי מת, הזקיקם תגלחת כמצורעים:
@343 **ולקחו פר בן בקר.** והוא עולה, כמו שנאמר (פסוק יב) ועשה את האחד עולה, והוא קרבן צבור בעבודה זרה: **ופר שני.** מה תלמוד לומר שני, לומר לך, מה עולה לא נאכלת, אף חטאת לא נאכלת. ובזו יש סמך לדבריו בתורת כהנים. ואומר אני שהוראת שעה היתה, ששעיר היה להם להביא לחטאת עבודה זרה עם פר העולה:
@344 **והקהלת את כל עדת.** לפי שהלוים נתנים קרבן כפרה תחתיהם, יבואו ויעמדו על קרבנם ויסמכו את ידיהם עליהם:
@346 **והניף אהרן את הלוים תנופה.** כדרך שאשם מצורע טעון תנופה חי. שלש תנופות נאמרו בפרשה זו, הראשונה לבני קהת, לכך נאמר בם והיו לעבוד את עבודת ה', לפי שעבודת קדש הקדשים עליהם הארון והשלחן וגו' . השניה לבני גרשון, לכך נאמר בם תנופה לה', שאף עליהם היתה עבודת הקדש יריעות וקרסים הנראים בבית קדש הקדשים, והשלישית לבני מררי:
@351 **נתנים נתנים.** נתונים למשא נתונים לשיר: **פטרת.** פתיחת:
@352 **כי לי כל בכור.** שלי היו הבכורות בקו הדין, שהגנתי עליהם בין בכורי מצרים ולקחתי אותם לי עד שטעו בעגל, ועכשיו ואקח את הלוים:
@354 **ואתנה** וגו' **.** חמשה פעמים נאמר בני ישראל במקרא זה, להודיע חבתן שנכפלו אזכרותיהן במקרא אחד כמנין חמשה חמשי תורה, וכך ראיתי בבראשית רבה: **ולא יהיה בבני ישראל נגף.** שלא יצטרכו לגשת אל הקדש, שאם יגשו יהיה נגף:
@355 **ויעש משה ואהרן וכל עדת** וגו' **.** משה העמידן ואהרן הניפן וישראל סמכו את ידיהם:
@357 **כאשר צוה ה'** וגו' **כן עשו.** להגיד שבח העושין והנעשה בהן, שאחד מהן לא עכב:
@359 **זאת אשר ללוים.** שנים פוסלים בהם, ואין המומים פוסלים בהם: **מבן חמש ועשרים.** ובמקום אחר אומר (במדבר ד, ג) מבן שלשים שנה, הא כיצד, מבן עשרים וחמש בא ללמוד הלכות עבודה ולומד חמש שנים, ובן שלשים עובד, מכאן לתלמיד שלא ראה סימן יפה במשנתו בחמש שנים, ששוב אינו רואה:
@360 **ולא יעבד עוד.** עבודת משא בכתף, אבל חוזר הוא לנעילת שערים ולשיר ולטעון עגלות, וזהו ושרת את אחיו עם אחוהי, כתרגומו:
@361 **לשמר משמרת.** לחנות סביב לאהל, ולהקים ולהוריד בשעת המסעות:
@362 **בחדש הראשון.** פרשה שבראש הספר לא נאמרה עד איר, למדת שאין סדר מקדם ומאחר בתורה. ולמה לא פתח בזו, מפני שהוא גנותן של ישראל, שכל ארבעים שנה שהיו ישראל במדבר לא הקריבו אלא פסח זה בלבד:
@363 **במועדו.** אף בשבת. במועדו אף בטמאה:
@364 **ככל חקתיו.** אלו מצות שבגופו, שה תמים זכר בן שנה: **וככל משפטיו.** אלו מצות שעל גופו ממקום אחר, כגון שבעת ימים למצה ולבעור חמץ. [מצות שבגופו, שה תמים זכר בן שנה. שעל גופו, צלי אש ראשו על כרעיו ועל קרבו. שחוץ לגופו, מצה ובעור חמץ] :
@365 **וידבר משה** וגו' **.** מה תלמוד לומר, והלא נאמר (ויקרא כג, מד) וידבר משה את מועדי ה', אלא כששמע פרשת מועדים מסיני, אמרה להם, וחזר והזהירם בשעת מעשה:
@367 **לפני משה ולפני אהרן.** כששניהם יושבין בבית המדרש באו ושאלום. ולא יתכן לומר זה אחר זה, שאם משה לא היה יודע, אהרן מנין לו:
@368 **למה נגרע.** אמר להם אין קדשים קרבים בטמאה. אמרו לו יזרק הדם עלינו בכהנים טהורים ויאכל הבשר לטהורים. אמר להם עמדו ואשמעה, כתלמיד המבטח לשמוע מפי רבו. אשרי ילוד אשה שכך מבטח, שכל זמן שהיה רוצה היה מדבר עם השכינה. וראויה היתה פרשה זו להאמר על ידי משה כשאר כל התורה כלה, אלא שזכו אלו שתאמר על ידיהן, שמגלגלין זכות על ידי זכאי:
@371 **או בדרך רחקה.** נקוד עליו, לומר לא שרחוקה ודאי, אלא שהיה חוץ לאסקפת העזרה כל זמן שחיטה. פסח שני מצה וחמץ עמו בבית ואין שם יום טוב, ואין אסור חמץ אלא עמו באכילתו:
@375 **וכי יגור אתכם גר ועשה פסח.** יכול כל המתגייר יעשה פסח מיד, תלמוד לומר חקה אחת וגו', אלא כך משמעו, וכי יגור אתכם גר ובא עת לעשות פסח עם חבריו כחקה וכמשפט יעשה:
@376 **המשכן לאהל העדת.** המשכן העשוי להיות אהל ללוחות העדות: **יהיה על המשכן.** כמו הוה על המשכן, וכן כל לשון הפרשה:
@378 **העלות הענן.** כתרגומו אסתלקות, וכן ונעלה הענן. ולא יתכן לכתוב ולפי עלות הענן ועלה הענן, שאין זה לשון סלוק אלא צמוח ועליה, כמו (מלכים א' יח, מד) והנה עב קטנה ככף איש עלה מים:
@379 **על פי ה' יסעו.** שנינו במלאכת המשכן, כיון שהיו ישראל נוסעים היה עמוד הענן מתקפל ונמשך על גבי בני יהודה כמין קורה, תקעו והריעו ותקעו ולא היה מהלך עד שמשה אומר קומה ה', ונסע דגל מחנה יהודה, זו בספרי: **ועל פי ה' יחנו.** כיון שהיו ישראל חונים, עמוד הענן מתמר ועולה ונמשך על גבי בני יהודה כמין סכה, ולא היה נפרש עד שמשה אומר שובה ה' רבבות אלפי ישראל, הוי אומר על פי ה' וביד משה:
@381 **ויש.** כלומר ופעמים: **ימים מספר.** ימים מועטים:
@383 **או ימים.** שנה, כמו (ויקרא כה, כט) ימים תהיה גאלתו:
@386 **עשה לך.** שיהיו תוקעין לפניך כמלך, כמו שנאמר (דברים לג, ה) ויהי בישרון מלך: **עשה לך.** משלך: [ **עשה לך.** אתה עושה ומשתמש בהם ולא אחר] : **למקרא העדה.** כשתרצה לדבר עם הסנהדרין ושאר העם ותקראם לאסף אליך, תקראם על ידי חצוצרות: **ולמסע את המחנות.** בשעת סלוק מסעות תתקעו בהם לסימן, נמצאת אתה אומר על פי שלשה היו נוסעים, על פי הקדוש ברוך הוא ועל פי משה ועל פי חצוצרות: **מקשה.** מהעשת תעשה בהקשת הקרנס:
@387 **ותקעו בהן.** בשתיהן והוא סימן למקרא העדה, שנאמר ונועדו אליך כל העדה אל פתח אהל מועד:
@388 **ואם באחת יתקעו.** הוא סימן למקרא הנשיאים, שנאמר ונועדו אליך הנשיאים. ואף הן יעידתן אל פתח אהל מועד. ומגזרה שוה הוא בא בספרי:
@389 **ותקעתם תרועה.** סימן מסע המחנות תקיעה תרועה ותקיעה, כך הוא נדרש בספרי מן המקראות היתרים:
@391 **ובהקהיל את הקהל** וגו' **.** לפי שהוא אומר והיו לך למקרא העדה ולמסע את המחנות מה מקרא העדה, תוקע בשני כהנים ובשתיהן, שנאמר ותקעו בהן וגו' , אף מסע המחנות בשתיהן, יכול מה מסע המחנות תוקע ומריע ותוקע אף מקרא העדה תוקע ומריע ותוקע, ומעתה אין חלוק בין מקרא העדה למסע את המחנות תלמוד לומר ובהקהיל את הקהל וגו' , למד שאין תרועה למקרא העדה והוא הדין לנשיאים. הרי סימן לשלשתם, מקרא העדה בשתים, ושל נשיאים באחת, וזו וזו אין בהם תרועה, ומסע המחנות בשתים על ידי תרועה ותקיעה:
@392 **ובני אהרן יתקעו.** במקראות ובמסעות הללו:
@394 **על עלתיכם.** בקרבן צבור הכתוב מדבר: **אני ה' אלהיכם.** מכאן למדנו מלכיות עם זכרונות ושופרות, שנאמר ותקעתם הרי שופרות, לזכרון הרי זכרונות, אני ה' אלהיכם זה מלכיות וכו' :
@395 **בחדש השני.** נמצאת אומר שנים עשר חדש חסר עשרה ימים עשו בחורב, שהרי בראש חדש סיון חנו שם ולא נסעו עד עשרים באיר לשנה הבאה:
@396 **למסעיהם.** כמשפט המפורש למסע דגליהם מי ראשון ומי אחרון: **במדבר פארן.** קברות התאוה במדבר פארן היה ושם חנו ממסע זה:
@401 **והורד המשכן.** כיון שנוסע דגל יהודה נכנסו אהרן ובניו ופרקו את הפרכת וכסו בה את הארון, שנאמר (במדבר ד, ה) ובא אהרן ובניו בנסוע המחנה, ובני גרשון ובני מררי פורקין המשכן וטוענין אותו בעגלות ונוסעים, והארון וכלי הקדש של משא בני קהת עומדים מכסין ונתונין על המוטות עד שנסע דגל מחנה ראובן, ואחר כך ונסעו הקהתים:
@405 **נשאי המקדש.** נושאי הדברים המקדשים: **והקימו את המשכן.** בני גרשון ובני מררי, שהיו קודמים להם מסע שני דגלים, היו מקימין את המשכן, כשהיה הענן שוכן, וסימן החניה נראה בדגל מחנה יהודה והם חונים, ועדין בני קהת באים מאחריהם עם שני דגלים האחרונים, היו בני גרשון ובני מררי מקימין את המשכן, וכשבאים בני קהת מוצאים אותו על מכונו, ומכניסין בו הארון והשלחן והמנורה והמזבחות, וזהו משמעות המקרא והקימו מקימי המשכן אותו עד טרם בואם של בני קהת:
@409 **מאסף לכל המחנות.** תלמוד ירושלמי לפי שהיה שבטו של דן מרבה באכלוסין היה נוסע באחרונה וכל מי שהיה מאבד דבר היה מחזירו לו. אית מאן [אתיא כמאן] דאמר כתיבה היו מהלכין, ומפיק לה מן (במדבר ב, יז) כאשר יחנו כן יסעו. ואית דאמרי כקורה היו מהלכין ומפיק לה מן מאסף לכל המחנות:
@412 **אלה מסעי.** זה סדר מסעיהם: **ויסעו.** ביום ההוא נסעו:
@413 **חבב.** הוא יתרו, שנאמר (שופטים ד, יא) מבני חבב חותן משה, ומה תלמוד לומר (שמות ב, יח) ותבאנה אל רעואל אביהן, מלמד שהתינוקות קורין לאבי אביהן אבא. ושמות הרבה [ושני שמות] היו לו יתר על שם שיתר פרשה אחת בתורה. חובב על שחבב את התורה וכו' : **נסעים אנחנו אל המקום.** מיד עד שלשה ימים אנו נכנסין לארץ, שבמסע זה הראשון נסעו על מנת להכנס לארץ ישראל, אלא שחטאו במתאוננים. ומפני מה שתף משה עצמו עמהם, שעדין לא נגזרה גזרה עליו וכסבור שהוא נכנס:
@414 **אל ארצי ואל מולדתי.** אם בשביל נכסי, אם בשביל משפחתי:
@415 **אל נא תעזב.** אין נא אלא לשון בקשה, שלא יאמרו לא נתגיר יתרו מחבה, סבור היה שיש לגרים חלק בארץ, עכשו שראה שאין להם חלק הניחם והלך לו: **כי על כן ידעת חנתנו במדבר.** כי נאה לך לעשות זאת על אשר ידעת חנותנו במדבר וראית נסים וגבורות שנעשו לנו: **כי על כן ידעת.** כמו על אשר ידעת, כמו (בראשית לח, כו) כי על כן לא נתתיה לשלה בני, כי על כן עברתם (שם יח, ה) , כי על כן באו (שם יט, ח) , כי על כן ראיתי פניך (שם לג, י) : **והיית לנו לעינים.** לשון עבר כתרגומו. דבר אחר לשון עתיד, כל דבר ודבר שיתעלם מעינינו תהיה מאיר עינינו. דבר אחר שתהא חביב עלינו כגלגל עינינו, שנאמר (דברים י, יט) ואהבתם את הגר:
@416 **והיה הטוב ההוא** וגו' **.** מה טובה הטיבו לו, אמרו כשהיו ישראל מחלקין את הארץ היה דשנה של יריחו חמש מאות אמה על חמש מאות אמה והניחוהו מלחלוק, אמרו מי שיבנה בית המקדש בחלקו הוא יטלנו, בין כך ובין כך נתנוהו לבני יתרו ליונדב בן רכב, שנאמר ובני קני חותן משה עלו מעיר התמרים וגו' (שופטים א, טז) :
@417 **דרך שלשת ימים.** מהלך שלשת ימים הלכו ביום אחד, שהיה הקדוש ברוך הוא חפץ להכניסם לארץ מיד: **וארון ברית ה' נסע לפניהם דרך שלשת ימים.** זה הארון היוצא עמהם למלחמה ובו שברי לוחות מנחים ומקדים לפניהם דרך שלשת ימים לתקן להם מקום חניה:
@418 **וענן ה' עליהם יומם.** שבעה עננים כתובים במסעיהם. ארבע מארבע רוחות, ואחד למעלה, ואחד למטה, ואחד לפניהם מנמיך את הגבוה ומגביה את הנמוך והורג נחשים ועקרבים: **מן המחנה.** ממקום חניתן:
@419 **ויהי בנסע הארן.** עשה לו סימניות מלפניו ומלאחריו, לומר שאין זה מקומו. ולמה נכתב כאן, כדי להפסיק בין פרענות לפרענות וכו' כדאיתא בכל כתבי הקדש (שבת קטז, א) : **קומה ה'.** לפי שהיה מקדים לפניהם מהלך שלשת ימים, היה משה אומר עמוד והמתן לנו ואל תתרחק יותר במדרש תנחומא בויקהל: **ויפוצו אויביך.** המכנסין: **וינסו משנאיך.** אלו הרודפים: **משנאיך.** אלו שונאי ישראל, שכל השונא את ישראל שונא את מי שאמר והיה העולם, שנאמר (תהלים פג, ג) ומשנאיך נשאו ראש, ומי הם, על עמך יערימו סוד:
@420 **שובה ה'.** מנחם תרגמו לשון מרגוע וכן (ישעיה ל, טו) בשובה ונחת תושעון: **רבבות אלפי ישראל.** מגיד שאין השכינה שורה בישראל פחותים משני אלפים ושתי רבבות:
@421 **ויהי העם כמתאננים.** אין העם אלא רשעים. וכן הוא אומר (שמות יז, ד) מה אעשה לעם הזה, ואומר (ירמיה יג, י) העם הרע הזה. וכשהם כשרים קרואים עמי, שנאמר (שמות ה) שלח את עמי, (מיכה ו ג) עמי מה עשיתי לך: **כמתאננים.** אין מתאוננים אלא לשון עלילה מבקשים עלילה היאך לפרוש מאחרי המקום וכן הוא אומר בשמשון (שופטים יד ד) כי תאנה הוא מבקש: **רע באזני ה'.** תואנה שהיא רעה באזני ה' שמתכונים שתבא באזניו ויקניט. אמרו אוי לנו כמה לבטנו בדרך הזה שלשה ימים, שלא נחנו מענוי הדרך: **ויחר אפו.** אני הייתי מתכון לטובתכם שתכנסו לארץ מיד: **בקצה המחנה.** במקצין שבהם לשפלות, אלו ערב רב. רבי שמעון בן מנסיא אומר בקצינים שבהם ובגדולים:
@422 **ויצעק העם אל משה.** משל למלך בשר ודם שכעס על בנו והלך הבן אצל אוהבו של אביו ואמר לו צא ובקש עלי מאבא: **ותשקע האש.** שקעה במקומה בארץ שאלו חזרה לאחת הרוחות היתה מקפלת והולכת כל אותו הרוח:
@424 **והאספסף.** אלו ערב רב שנאספו אליהם בצאתם ממצרים: **וישבו.** גם בני ישראל ויבכו עמהם: **מי יאכלנו בשר.** וכי לא היה להם בשר, והלא כבר נאמר (שמות יב, לח) וגם ערב רב עלה אתם וצאן ובקר וגו' . ואם תאמר אכלום, והלא בכניסתם לארץ נאמר (במדבר לב, א) ומקנה רב היה לבני ראובן וגו' , אלא שמבקשים עלילה:
@425 **אשר נאכל במצרים חנם.** אם תאמר שמצריים נותנים להם דגים חנם, והלא כבר נאמר (שמות ה, יח) ותבן לא ינתן לכם, אם תבן לא היו נותנין להם חנם, דגים היו נותנין להם חנם, ומהו אומר חנם, חנם מן המצות: **את הקשאים.** אמר ר' שמעון מפני מה המן משתנה לכל דבר חוץ מאלו, מפני שהן קשים למניקות, אומרים לאשה אל תאכלי שום ובצל מפני התינוק. משל למלך וכו' , כדאיתא בספרי: **הקשאים.** הם קוקומברי''ש בלע''ז [מלפפנים] : **אבטחים.** בורק''ש **החציר.** כרישין פוריל''ש ותרגומו ית בוציניא וכו' :
@426 **אל המן עינינו.** מן בשחר מן בערב:
@427 **והמן כזרע גד.** מי שאמר זה לא אמר זה, ישראל אומרים בלתי אל המן עינינו, והקדוש ברוך הוא הכתיב בתורה והמן כזרע גד וגו' , כלומר ראו באי עולם על מה מתלוננים בני, והמן כך וכך הוא חשוב: **כזרע גד.** עגול כגדא זרע אליינדר''א [כוסבר] : **הבדלח.** שם אבן טובה קריסט''ל :
@428 **שטו.** אין שיט אלא לשון טיול אישבני''ר בלא עמל: **וטחנו ברחים** וגו' **.** לא ירד בריחים ולא בקדירה ולא במדוכה אלא משתנה היה טעמו לנטחנין ולנדוכין ולמבשלין: **בפרור.** קדרה: **לשד השמן.** לחלוח של שמן, כך פרשו דונש. ודומה לו (תהלים לב, ד) נהפך לשדי בחרבוני קיץ. והלמ''ד יסוד, נהפך לחלוחי בחרבוני קיץ. ורבותינו פרשוהו לשון שדים, אך אין ענין שדים אצל שמן. ואי אפשר לומר לשד השמן לשון (דברים לב, טו) וישמן ישורון, שאם כן היה המי''ם נקוד קמ''ץ קטן וטעמו למטה תחת המי''ם, עכשיו שהמי''ם נקוד פת''ח קטן והטעם תחת השי''ן, לשון שמן הוא, והשי''ן הנקודה בקמץ גדול ואינה נקודה בפתח קטן מפני שהוא סוף פסוק. דבר אחר לשד לשון נוטריקון ליש שמן דבש, כעיסה הנלושה בשמן וקטופה בדבש. ותרגום של אונקלוס דמתרגם דליש במשחא, נוטה לפתרונו של דונש, שהעיסה הנלושה בשמן, לחלוחית שמן יש בה:
@430 **בכה למשפחתיו.** משפחות משפחות נאספים ובוכים לפרסם תרעמתן בגלוי. ורבותינו אמרו למשפחתיו על עסקי משפחות, על עריות הנאסרות להם:
@432 **כי תאמר אלי.** שאתה אומר אלי שאהו בחיקך. והיכן אמר לו כן, לך נחה את העם (שמות לב) , ואומר (שם ו) ויצום אל בני ישראל, על מנת שיהיו סוקלים אתכם ומחרפים אתכם: **על האדמה אשר נשבעת לאבתיו.** אתה אומר לי לשאתם בחיקי:
@435 **ואם ככה את עשה לי.** תשש כחו של משה כנקבה כשהראהו הקדוש ברוך הוא הפרענות שהוא עתיד להביא עליהם על זאת. אמר לפניו, אם כן הרגני תחלה: **ואל אראה ברעתי.** ברעתם היה לו לכתוב, אלא שכנה הכתוב. וזה אחד מתקוני סופרים בתורה לכנוי ולתקון הלשון:
@436 **אספה לי.** הרי תשובה לתלנתך שאמרת לא אוכל אנכי לבדי. והזקנים הראשונים היכן היו, והלא אף במצרים ישבו עמהם, שנאמר (שמות ג, טז) לך ואספת את זקני ישראל, אלא באש תבערה מתו. וראויים היו לכך מסיני, דכתיב (שמות כד) ויחזו את האלהים, שנהגו קלות ראש, כנושך פתו ומדבר בפני המלך. וזהו (שם) ויאכלו וישתו, ולא רצה הקדוש ברוך הוא לתן אבלות במתן תורה ופרע להם כאן: **אשר ידעת כי הם** וגו' **.** אותם שאתה מכיר שנתמנו עליהם שוטרים במצרים בעבודת פרך והיו מרחמים עליהם ומכים על ידם, שנאמר (שמות ה, יד) ויכו שוטרי בני ישראל, עתה יתמנו בגדלתן כדרך שנצטערו בצרתן: **ולקחת אתם.** קחם בדברים, אשריכם שנתמניתם פרנסים על בניו של מקום: **והתיצבו שם עמך.** כדי שיראו ישראל וינהגו בהם גדלה וכבוד ויאמרו חביבין אלה שנכנסו עם משה לשמוע דבור מפי הקב,, ה:
@437 **וירדתי.** זו אחת מעשר ירידות הכתובות בתורה: **ודברתי עמך.** ולא עמהם: **ואצלתי.** כתרגומו וארבי, כמו (שמות כד, יא) ואל אצילי בני ישראל: **ושמתי עליהם.** למה משה דומה באותה שעה, לנר שמנח על גבי מנורה והכל מדליקין המנו, ואין אורו חסר כלום: **ונשאו אתך.** התנה עמהם על מנת שיקבלו עליהם טורח בני, שהם טרחנים וסרבנים: **ולא תשא אתה לבדך.** הרי תשובה למה שאמרת לא אוכל אנכי לבדי:
@438 **התקדשו.** הזמינו עצמכם לפרענות, וכן הוא אומר (ירמיה יב, ג) והקדשם ליום הרגה:
@440 **עד חדש ימים.** זו בכשרים שמתמצין על מטותיהן ואחר כך נשמתן יוצאה, וברשעים הוא אומר הבשר עודנו בין שניהם, כך היא שנויה בספרי, אבל במכילתא שנויה חלוף הרשעים אוכלין ומצטערין שלשים יום והכשרים הבשר עודנו בין שניהם: **עד אשר יצא מאפכם.** כתרגומו דתקוצון ביה, יהא דומה לכם כאלו אכלתם ממנו יותר מדאי עד שיוצא ונגעל לחוץ דרך האף: **והיה לכם לזרא.** שתהיו מרחקין אותו יותר ממה שקרבתם. ובדברי רבי משה הדרשן ראיתי שיש לשון שקורין לחרב זרא: **את ה' אשר בקרבכם.** אם לא שנטעתי שכינתי ביניכם, לא גבה לבבכם לכנס לכל הדברים הללו:
@441 **שש מאות אלף רגלי.** לא חש למנות את הפרט שלשת אלפים היתרים. ור' משה הדרשן פרש שלא בכו אלא אותן שיצאו ממצרים:
@442 **הצאן ובקר ישחט.** זה אחד מארבעה דברים שהיה רבי עקיבא דורש ואין רבי שמעון דורש כמותו. רבי עקיבא אומר שש מאות אלף רגלי, ואתה אמרת בשר אתן להם ואכלו חדש ימים, הצאן ובקר וגו' , הכל כמשמעו, מי יספיק להם, כענין שנאמר (ויק' כה) ומצא כדי גאלתו. ואיזו קשה, זו או (במ' כ) שמעו נא המרים, אלא לפי שלא אמר ברבים חסך לו הכתוב ולא נפרע ממנו, וזו של מריבה היתה בגלוי, לפיכך לא חסך לו הכתוב. רבי שמעון אומר חס ושלום לא עלתה על דעתו של אותו צדיק כך, מי שכתוב בו (במ' יב) בכל ביתי נאמן הוא, יאמר אין המקום מספיק לנו, אלא כך אמר שש מאות אלף רגלי וגו' ואתה אמרת בשר אתן לחדש ימים, ואחר כך תהרוג אמה גדולה כזו, הצאן ובקר ישחט להם כדי שיהרגו, ותהא אכילה זו מספקתן עד עולם, וכי שבחך הוא זה, אומרים לו לחמור טול כור שעורים ונחתוך ראשך. השיבו הקדוש ברוך הוא ואם לא אתן יאמרו שקצרה ידי, הטוב בעיניך שיד ה' תקצר בעיניהם, יאבדו הם ומאה כיוצא בהם ואל תהי ידי קצרה לפניהם אפלו שעה אחת:
@443 **עתה תראה היקרך דברי.** רבן גמליאל בנו של רבי יהודה הנשיא אומר אי אפשר לעמוד על התפל, מאחר שאינן מבקשים אלא עלילה לא תספיק להם, סופן לדון אחריך, אם אתה נותן להם בשר בהמה גסה, יאמרו דקה בקשנו, ואם אתה נותן להם דקה, יאמרו גסה בקשנו, חיה ועוף בקשנו, דגים וחגבים בקשנו, אמר לו אם כן יאמרו שקצרה ידי. אמר לפניו הריני הולך ומפיסן. אמר לו עתה תראה היקרך דברי, שלא ישמעו לך. הלך משה לפיסן אמר להם היד ה' תקצר, (תהלים עח, כ) הן הכה צור ויזובו מים וגו' הגם לחם יוכל תת, אמרו פשרה היא זו, אין בו כח למלאת שאלתנו. וזהו שנאמר ויצא משה וידבר אל העם, כיון שלא שמעו לו ויאסף שבעים איש וגו' :
@445 **ולא יספו.** לא נתנבאו אלא אותו היום לבדו, כך מפורש בספרי, ואונקלוס תרגם ולא פסקין, שלא פסקה נבואה מהם:
@446 **וישארו שני אנשים.** מאותן שנבחרו. אמרו אין אנו כדאין לגדלה זו: **והמה בכתבים.** במבוררים שבהם לסנהדרין, ונכתבו כלם נקובים בשמות, ועל ידי גורל, לפי שהחשבון עולה לשנים עשר שבטים, ששה ששה לכל שבט ושבט חוץ משני שבטים שאין מגיע אליהם אלא חמשה חמשה. אמר משה, אין שבט שומע לי לפחות משבטו זקן אחד. מה עשה, נטל שבעים ושנים פתקין וכתב על שבעים זקן, ועל שנים חלק וברר מכל שבט ושבט ששה, והיו שבעים ושנים. אמר להם טלו פתקיכם מתוך קלפי, מי שעלה בידו זקן, נתקדש, ומי שעלה בידו חלק אמר לו המקום לאחפץ בך:
@447 **וירץ הנער.** יש אומרים גרשום בן משה היה:
@448 **כלאם.** הטל עליהם צרכי צבור והם כלים מאליהם. דבר אחר תנם אל בית הכלא, לפי שהיו מתנבאים משה מת ויהושע מכניס את ישראל לארץ:
@449 **המקנא אתה לי.** הקנאי אתה לי הקנאתי אתה מקנא: **לי.** כמו בשבילי. כל לשון קנאה אדם הנותן לב על הדבר או לנקום או לעזור אינפרינמינ''ט בלע''ז אוחז בעבי המשא:
@450 **ויאסף משה.** מפתח אהל מועד: **אל המחנה.** נכנסו איש לאהלו: **ויאסף.** לשון כניסה אל הבית, כמו (דברים כב, ב) ואספתו אל תוך ביתך, ואב לכלם (תהלים לט) יצבר ולא ידע מי אספם, מלמד שלא הביא עליהם פרענות עד שנכנסו הצדיקים איש לאהלו:
@451 **ויגז.** ויפריח, וכן (תהלים צ, י) כי גז חיש, וכן (נחום א, יב) נגזו ועבר: **ויטש.** ויפשוט, כמו (שמואל א' ל, טז) והנה נטשים על פני כל הארץ, (יחזקאל כט, ה) ונטשתיך המדברה: **וכאמתים.** פורחות בגובה עד שהן כנגד לבו של אדם, כדי שלא יהא טורח באסיפתן לא להגביה ולא לשחות:
@452 **הממעיט.** מי שאוסף פחות מכלם, העצלים והחגרים, אסף עשרה חמרים: **וישטחו.** עשו אותן משטיחין משטיחין:
@453 **טרם יכרת.** כתרגומו עד לא פסק. דבר אחר אינו מספיק לפסקו בשניו עד שנשמתו יוצאה:
@456 **ותדבר.** אין דבור בכל מקום אלא לשון קשה, וכן הוא אומר (בראשית מב, ל) דבר האיש אדני הארץ אתנו קשות, ואין אמירה בכל מקום אלא לשון תחנונים, וכן הוא אומר (בראשית יט, ז) ויאמר אל נא אחי תרעו, (במדבר יב, ו) ויאמר שמעו נא דברי, כל נא לשון בקשה: **ותדבר מרים ואהרן.** היא פתחה בדבור תחלה, לפיכך הקדימה הכתוב תחלה, ומנין היתה יודעת מרים שפרש משה מן האשה, רבי נתן אומר, מרים היתה בצד צפורה בשעה שנאמר למשה אלדד ומידד מתנבאים במחנה, כיון ששמעה צפורה, אמרה אוי לנשותיהן של אלו אם הם נזקקים לנבואה שיהיו פורשין מנשותיהן כדרך שפרש בעלי ממני, ומשם ידעה מרים והגידה לאהרן. ומה מרים שלא נתכונה לגנותו, כך נענשה, קל וחמר למספר בגנותו של חברו: **האשה הכשית.** מגיד שהכל מודים ביפיה, כשם שהכל מודים בשחרותו של כושי: **כושית.** בגימטריא יפת מראה: **על אדות האשה.** על אודות גרושיה: **כי אשה כשית לקח.** מה תלמוד לומר, אלא יש לך אשה נאה ביפיה ואינה נאה במעשיה, במעשיה ולא ביפיה, אבל זאת נאה בכל: **האשה הכשית.** על שם נויה נקראת כושית כאדם הקורא את בנו נאה כושי, כדי שלא תשלט בו עין רעה: **כי אשה כשית לקח.** ועתה גרשה:
@457 **הרק אך.** עמו לבדו דבר ה': **הלא גם בנו דבר.** ולא פרשנו מדרך ארץ:
@458 **ענו.** שפל וסבלן:
@459 **פתאם.** נגלה עליהם פתאם, והם טמאים בדרך ארץ, והיו צועקים מים מים, להודיעם שיפה עשה משה שפרש מן האשה, מאחר שנגלית עליו שכינה תדיר ואין עת קבועה לדבור: **צאו שלשתכם.** מגיד ששלשתן נקראו בדבור אחד, מה שאי אפשר לפה לומר ולאזן לשמוע:
@460 **בעמוד ענן.** יצא יחידי, שלא כמדת בשר ודם. מלך בשר ודם כשיוצא למלחמה יוצא באכלוסין, וכשיוצא לשלום יוצא במועטים, ומדת הקדוש ברוך הוא יוצא למלחמה יחידי, שנאמר (שמות טו, ג) ה' איש מלחמה, ויוצא לשלום באכלוסין, שנאמר (תהלים סח, יח) רכב אלהים רבתים אלפי שנאן: **ויקרא אהרן ומרים.** שהיו נמשכין ויוצאין מן החצר לקראת הדבור: **ויצאו שניהם.** ומפני מה משכן והפרידן ממשה, לפי שאומרים מקצת שבחו של אדם בפניו וכלו שלא בפניו, וכן מצינו בנח, שלא בפניו נאמר (בראשית ו, ט) איש צדיק תמים, ובפניו נאמר (בראשית ז, א) כי אתך ראיתי צדיק לפני. דבר אחר שלא ישמע בנזיפתו של אהרן:
@461 **שמעו נא דברי.** אין נא אלא לשון בקשה: **אם יהיה נביאכם.** אם יהיו לכם נביאים: **ה' במראה אליו אתודע.** שכינת שמי אין נגלית עליו באספקלריא המאירה אלא בחלום וחזיון:
@463 **פה אל פה.** אמרתי לו לפרוש מן האשה. והיכן אמרתי לו, בסיני (דברים ה, כז) לך אמר להם שובו לכם לאהליכם, ואתה פה עמד עמדי: **ומראה ולא בחידת.** מראה זה מראה דבור, שאני מפרש לו דבורי במראית פנים שבו ואיני סותמו לו בחידות, כענין שנאמר ליחזקאל (יחזקאל יז, ב) חוד חידה וגו' , יכול מראה שכינה, תלמוד לומר (שמות לג, כ) לא תוכל לראות את פני: **ותמנת ה' יביט.** זה מראה אחורים, כענין שנאמר (שמות לג, כג) וראית את אחרי: **בעבדי במשה.** אינו אומר בעבדי משה, אלא בעבדי במשה, בעבדי אף על פי שאינו משה, במשה אפלו אינו עבדי, כדאי הייתם לירא מפניו, וכל שכן שהוא עבדי ועבד מלך מלך, היה לכם לומר אין המלך אוהבו חנם. ואם תאמרו איני מכיר במעשיו, זו קשה מן הראשונה:
@464 **ויחר אף ה' בם וילך.** מאחר שהודיעם סרחונם גזר עליהם נדוי, קל וחמר לבשר ודם שלא יכעס על חברו עד שיודיענו סרחונו:
@465 **והענן סר.** ואחר כך והנה מרים מצרעת כשלג, משל למלך שאמר לפדגוג, רדה את בני, אבל לא תרדנו עד שאלך מאצלך, שרחמי עליו:
@466 **נואלנו.** כתרגומו לשון אויל:
@467 **אל נא תהי.** אחותנו זו: **כמת.** שהמצורע חשוב כמת, מה מת מטמא בביאה, אף מצורע מטמא בביאה: **אשר בצאתו מרחם אמו.** אמנו היה לו לומר, אלא שכנה הכתוב. וכן חצי בשרו, חצי בשרנו היה לו לומר, אלא שכנה הכתוב. מאחר שיצאה מרחם אמנו היא לנו כאלו נאכל חצי בשרנו, כענין שנאמר (בראשית לז, כז) כי אחינו בשרנו הוא. ולפי משמעו אף הוא נראה כן, אין ראוי לאח להניח את אחותו להיות כמת: **אשר בצאתו.** מאחר שיצא זה מרחם אמו של זה שיש כח בידו לעזור ואינו עוזרו, הרי נאכל חצי בשרו, שאחיו בשרו הוא. דבר אחר אל נא תהי כמת, אם אינך רופאה בתפלה, מי מסגירה ומי מטהרה, אני אי אפשר לראותה, שאני קרוב ואין קרוב רואה את הנגעים, וכהן אחר אין בעולם, וזהו אשר בצאתו מרחם אמו:
@468 **אל נא רפא נא לה.** בא הכתוב ללמדך דרך ארץ, שהשואל דבר מחברו צריך לומר שנים או שלשה דברי תחנונים ואחר כן יבקש שאלותיו: **לאמר.** מה תלמוד לומר, אמר לו השיבני אם אתה מרפא אותה אם לאו, עד שהשיבו ואביה ירק ירק וגו' . רבי אלעזר בן עזריה אומר בארבעה מקומות בקש משה מלפני הקדוש ברוך הוא להשיבו אם יעשה שאלותיו אם לאו, כיוצא בו (שמות ו, יב) וידבר משה לפני ה' לאמר וגו' , מה תלמוד לומר לאמר, השיבני אם גואלם אתה אם לאו, עד שהשיבו עתה תראה וגו' . כיוצא בו (במדבר כז, טו. טז) וידבר משה אל ה' לאמר יפקד ה' אלהי הרוחות לכל בשר, השיבו קח לך (במד' כז, יח) . כיוצא בו (דברים ג) ואתחנן אל ה' בעת ההיא לאמר, השיבו רב לך: **רפא נא לה.** מפני מה לא האריך משה בתפלה, שלא יהיו ישראל אומרים אחותו נתונה בצרה והוא עומד ומרבה בתפלה [דבר אחר שלא יאמרו ישראל בשביל אחותו הוא מאריך בתפלה, אבל בשבילנו אינו מאריך בתפלה] :
@469 **ואביה ירק ירק בפניה.** ואם אביה הראה לה פנים זועפות הלא תכלם שבעת ימים, קל וחמר לשכינה ארבעה עשר יום, אלא דיו לבא מן הדין להיות כנדון, לפיכך אף בנזיפתי תסגר שבעת ימים: **ואחר תאסף.** אומר אני כל האסיפות האמורות במצורעים על שם שהוא משלח מחוץ למחנה, וכשהוא נרפא נאסף אל המחנה לכך כתוב בו אסיפה לשון הכנסה:
@470 **והעם לא נסע.** זה הכבוד חלק לה המקום בשביל שעה אחת שנתעכבה למשה כשהשלך ליאור, שנאמר (שמות ב, ד) ותתצב אחותו מרחק וגו' :
@473 **שלח לך אנשים.** למה נסמכה פרשת מרגלים לפרשת מרים, לפי שלקתה על עסקי דבה שדברה באחיה, ורשעים הללו ראו ולא לקחו מוסר: **שלח לך.** לדעתך, אני איני מצוה לך, אם תרצה שלח, לפי שבאו ישראל ואמרו (דברים א, כב) נשלחה אנשים לפנינו, כמה שנאמר (שם) ותקרבון אלי כלכם וגו' , ומשה נמלך בשכינה. אמר אני אמרתי להם שהיא טובה, שנאמר (שמות ג, יז) אעלה אתכם מעני מצרים וגו' , חייהם שאני נותן להם מקום לטעות בדברי המרגלים למען לא יירשוה:
@474 **על פי ה'.** ברשותו, שלא עכב על ידו: **כלם אנשים.** כל אנשים שבמקרא לשון חשיבות, ואותה שעה כשרים היו:
@487 **ויקרא משה להושע** וגו' **.** התפלל עליו יה יושיעך מעצת מרגלים:
@488 **עלו זה בנגב.** הוא היה הפסולת של ארץ ישראל, שכן דרך התגרים מראין את הפסולת תחלה ואחר כך מראין את השבח:
@489 **את הארץ מה היא.** יש ארץ מגדלת גבורים ויש ארץ מגדלת חלשים יש מגדלת אכלוסין ויש ממעטת אכלוסין: **החזק הוא הרפה.** סימן מסר להם, אם בפרזים יושבין, חזקים הם שסומכין על גבורתם, ואם בערים בצורות הם יושבין, חלשים הם:
@490 **הבמחנים.** תרגומו הבפצחין, כרכין פצוחין ופתוחין מאין חומה: **הטובה היא.** במעינות ותהומות טובים ובריאים:
@491 **היש בה עץ.** אם יש בהם אדם כשר שיגין עליהם בזכותו: **בכורי ענבים.** ימים שהענבים מתבשלין בבכור:
@492 **ממדבר צן עד רחב לבא חמת.** הלכו בגבוליה באורך וברוחב כמין גאם, הלכו רוח גבול דרומית ממקצוע מזרח עד מקצוע מערב, כמו שצוה משה עלו זה בנגב, דרך גבול דרומית מזרחית עד הים, שהים הוא גבול מערבי. ומשם חזרו והלכו כל גבול מערבי על שפת הים עד לבא חמת, שהוא אצל הר ההר במקצוע מערבית צפונית, כמו שמפורש בגבולות הארץ בפרשת אלה מסעי:
@493 **ויבא עד חברון.** כלב לבדו הלך שם ונשתטח על קברי אבות, שלא יהא נסת לחבריו להיות בעצתם, וכן הוא אומר (דברים א, לו) ולו אתן את הארץ אשר דרך בה, וכתיב (שופטים א, כ) ויתנו לכלב את חברון: **שבע שנים נבנתה.** אפשר שבנה חם את חברון לכנען בנו הקטן קודם שיבנה את צוען למצרים בנו הגדול, אלא שהיתה מבנה בכל טוב על אחד משבעה בצוען. ובא להודיעך שבחה של ארץ ישראל, שאין לך טרשין בארץ ישראל יותר מחברון, לפיכך הקצוה לקברות מתים, ואין לך מעלה בכל ארצות כמצרים, שנאמר (בראשית יג, י) כגן ה' כארץ מצרים, וצוען היא המעלה שבארץ מצרים ששם מושב המלכים, שנאמר (ישעיה ל, ד) כי היו בצוען שריו, והיתה חברון טובה ממנה שבעה חלקים:
@494 **זמורה.** שוכת גפן ואשכול של ענבים תלוי בה: **וישאהו במוט בשנים.** ממשמע שנאמר וישאהו במוט איני יודע שהוא בשנים, מה תלמוד לומר בשנים, בשני מוטות. הא כיצד, שמונה נטלו אשכול, אחד נטל תאנה ואחד רמון, יהושע וכלב לא נטלו כלום, לפי שכל עצמם להוציא דבה נתכונו, כשם שפריה משנה כך עמה משנה. ואם חפץ אתה לידע כמה משאוי אחד מהם צא ולמד מאבנים שהקימו בגלגל, (יהושע ד ה) והרימו לכם איש אבן אחת על שכמו, והקימוה בגלגל. ושקלום רבותינו משקל כל אחת ארבעים סאה. וגמירי, טונא דמדלי אנש על כתפיה, אינו אלא שליש משאוי ממשאוי שמסיעין אותו להרים:
@496 **וישבו מתור הארץ מקץ ארבעים יום.** והלא ארבע מאות פרסה על ארבע מאות פרסה היא, ומהלך אדם בינוני עשרה פרסאות ליום, הרי מהלך ארבעים יום מן המזרח למערב והם הלכו ארכה ורחבה, אלא שגלוי לפני הקדוש ברוך הוא שיגזור עליהם יום לשנה, קצר לפניהם את הדרך:
@497 **וילכו ויבאו.** מהו וילכו, להקיש הליכתן לביאתן, מה ביאתן בעצה רעה, אף הליכתן בעצה רעה: **וישיבו אתם דבר.** את משה ואת אהרן:
@498 **זבת חלב ודבש הוא.** כל דבר שקר שאין אומרים בו קצת אמת בתחלתו, אין מתקים בסופו:
@499 **בצרות.** לשון חזק, ותרגומו כריכן, לשון בירניות עגלות, ובלשון ארמי כריך. עגול:
@500 **עמלק יושב** וגו' **.** לפי שנכוו בעמלק כבר, הזכירוהו מרגלים כדי ליראם: **על יד הירדן.** יד כמשמעו, אצל הירדן, ולא תוכלו לעבור:
@501 **ויהס כלב.** השתיק את כלם: **אל משה.** לשמוע מה שידבר במשה. צוח ואמר וכי זו בלבד עשה לנו בן עמרם. השומע היה סבור שבא לספר בגנותו, מתוך שהיה בלבם על משה בשביל דברי המרגלים. שתקו כלם לשמוע גנותו, אמר והלא קרע לנו את הים והוריד לנו את המן והגיז לנו את השלו: **עלה נעלה.** אפלו בשמים והוא אומר עשו סלמות ועלו שם נצליח בכל דבריו: **ויהס.** לשון שתיקה, וכן (זכריה ב, יז) הס כל בשר, (עמוס ו, י) הס כי לא להזכיר. כן דרך בני אדם הרוצה לשתק אגדת אנשים אומר הס:
@502 **חזק הוא ממנו.** כביכול כלפי מעלה אמרו:
@503 **אוכלת יושביה.** בכל מקום שעברנו מצאנום קוברי מתים, והקדוש ברוך הוא עשה לטובה כדי לטרדם באבלם ולא יתנו לב לאלו: **אנשי מדות.** גדולים וגבוהים וצריך לתת להם מדה, כגון גלית (שמואל א' יז, ד) גבהו שש אמות וזרת, וכן (שמואל ב' כא, כ) איש מדון, (ד''ה א' יא, כג) איש מדה:
@504 **הנפילים.** ענקים מבני שמחזאי ועזאל שנפלו מן השמים בימי דור אנוש: **וכן היינו בעיניהם.** שמענו אומרים זה לזה נמלים יש בכרמים כאנשים: **ענק.** שמעניקים חמה בקומתן:
@505 **כל העדה.** סנהדראות:
@506 **לו מתנו.** הלואי ומתנו:
@508 **נתנה ראש.** כתרגומו נמני רישא, נשים עלינו מלך, ורבותינו פרשו לשון עבודה זרה:
@513 **אל תמרדו.** ושוב ואתם אל תיראו: **כי לחמנו הם.** נאכלם כלחם: **סר צלם.** מגנם וחזקם. כשרים שבהם מתו, איוב שהיה מגין עליהם. דבר אחר צלו של מקום סר מעליהם:
@514 **לרגום אתם.** את יהושע וכלב: **וכבוד ה'.** הענן ירד שם:
@515 **עד אנה.** עד היכן: **ינאצני.** ירגיזוני: **בכל האתות.** בשביל כל הנסים שעשיתי להם היה להם להאמין שהיכולת בידי לקים הבטחתי:
@516 **ואורשנו.** לשון תרוכין. ואם תאמר מה אעשה לשבועת אבות: **ואעשה אתך לגוי גדול.** שאתה מזרעם:
@517 **ושמעו מצרים.** ושמעו את אשר תהרגם: **כי העלית.** כי משמש בלשון אשר, והם ראו אשר העלית בכחך הגדול אותם מקרבם וכשישמעו שאתה הורגם לא יאמרו שחטאו לך, אלא יאמרו שכנגדם יכלת להלחם אבל כנגד יושבי הארץ לא יכלת להלחם. וזה הוא:
@518 **ואמרו אל יושב הארץ הזאת.** כמו על יושב הארץ הזאת. ומה יאמרו עליהם, מה שאמור בסוף הענין, מבלתי יכלת ה', בשביל ששמעו כי אתה ה' שוכן בקרבם, ועין בעין אתה ה' נראה להם, והכל בדרך חבה, ולא הכירו בך שנתקה אהבתך מהם עד הנה:
@519 **והמתה את העם הזה כאיש אחד.** פתאום, ומתוך כך יאמרו הגוים אשר שמעו את שמעך וגו' :
@520 **מבלתי יכלת** וגו' **.** לפי שיושבי הארץ חזקים וגבורים, ואינו דומה פרעה לשלשים ואחד מלכים, זאת יאמרו על יושב הארץ הזאת: **מבלתי יכלת.** מתוך שלא היה יכלת בידו להביאם שחטם: **יכלת.** שם דבר הוא:
@521 **יגדל נא כח ה'.** לעשות דבורך: **כאשר דברת לאמר.** ומהו הדבור:
@522 **ה' ארך אפים.** לצדיקים ולרשעים. כשעלה משה למרום מצאו משה להקדוש ברוך הוא שהיה יושב וכותב ה' ארך אפים. אמר לו לצדיקים. אמר לו הקדוש ברוך הוא אף לרשעים. אמר לו רשעים יאבדו. אמר לו הקדוש ברוך הוא חייך שתצטרך לדבר. כשחטאו ישראל בעגל ובמרגלים התפלל משה לפניו בארך אפים, אמר לו הקב''ה והלא אמרת לי לצדיקים. אמר לו והלא אמרת לי אף לרשעים: **ונקה.** לשבים: **לא ינקה.** לשאינן שבים:
@524 **כדברך.** בשביל מה שאמרת פן יאמרו מבלתי יכלת ה':
@525 **ואולם.** כמו אבל זאת אעשה להם: **חי אני.** לשון שבועה. כשם שאני חי וכבודי ימלא את כל הארץ, כך אקים להם, כי כל האנשים הרואים וגו' אם יראו את הארץ. הרי זה מקרא מסורס, חי אני כי כל האנשים אם יראו את הארץ וכבודי ימלא את כל הארץ, שלא יתחלל שמי במגפה הזאת לומר מבלתי יכלת ה' להביאם, שלא אמיתם פתאום כאיש אחד אלא באחור ארבעים שנה מעט מעט:
@526 **וינסו.** כמשמעו: **זה עשר פעמים.** שנים בים שנים במן ושנים בשלו וכו' , כדאיתא במסכת ערכין (טו, א) :
@527 **אם יראו.** לא יראו: **לא יראוה.** לא יראו את הארץ:
@528 **רוח אחרת.** שתי רוחות אחת בפה ואחת בלב, למרגלים אמר, אני עמכם בעצה, ובלבו היה לומר האמת ועל ידי כן היה בו כח להשתיקם, כמו שנאמר (לעיל יג, ל) ויהס כלב, שהיו סבורים שיאמר כמותם, זהו שנאמר בספר (יהושע יד, ז) ואשב אתו דבר כאשר עם לבבי, ולא כאשר עם פי: **וימלא אחרי.** וימלא את לבו אחרי וזה מקרא קצר: **אשר בא שמה.** חברון תנתן לו: **יורשנה.** כתרגומו יתרכינה, יורישו את הענקים ואת העם אשר בה, ואין לתרגמו יירתינה, אלא במקום יירשנה:
@529 **והעמלקי** וגו' **.** אם תלכו שם יהרגו אתכם, מאחר שאיני עמכם: **מחר פנו.** לאחוריכם וסעו לכם וגו' :
@531 **לעדה הרעה** וגו' **.** אלו המרגלים, מכאן לעדה שהיא עשרה: **אשר המה מלינים.** את ישראל עלי: **את תלנות בני ישראל אשר המה מלינים.** המרגלים מלינים אותם עלי שמעתי:
@532 **חי אני.** לשון שבועה: **אם לא** וגו' **כן אעשה.** כביכול איני חי: **כאשר דברתם.** שבקשתם ממני או במדבר הזה לו מתנו (פסוק ב) :
@533 **וכל פקדיכם לכל מספרכם.** כל הנמנה לכל מספר, שאתם נמנין בו, כגון לצאת ולבא לצבא ולתת שקלים, כל המנויים לכל אותן מספרות ימותו, ואלו הן מבן כ' שנה וגו', להוציא שבטו של לוי שאין פקודיהם מבן עשרים:
@536 **ופגריכם אתם.** כתרגומו לפי שדבר על הבנים להכניסם לארץ ובקש לומר ואתם תמותו, נופל לשון זה כאן לומר אתם:
@537 **ארבעים שנה.** לא מת אחד מהם פחות מבן ששים, לכך נגזר ארבעים, כדי שיהיו אותם של בני עשרים מגיעין לכלל ששים. ושנה ראשונה היתה בכלל, ואף על פי שקדמה לשלוח המרגלים, לפי שמשעשו את העגל עלתה גזרה זו במחשבה אלא שהמתין להם עד שתתמלא סאתם, וזהו שנאמר (שמות לב, לד) וביום פקדי, במרגלים, ופקדתי עליהם חטאתם, ואף כאן נאמר תשאו את עונתיכם, שתי עונות של עגל ושל תלונה. וחשב להם במנין חייהם מקצת שנה ככלה, וכשנכנסו לשנת ששים מתו אותם של בני עשרים: **ונשאו את זנותיכם.** כתרגומו ויקבלון ית חוביכון:
@538 **את תנואתי.** שהניאותם את לבבכם מאחרי. תנואה לשון הסרה, כמו (במדבר ל, ו) כי הניא אביה אתה:
@540 **וישבו וילינו עליו.** וכששבו מתור הארץ הרעימו עליו את כל העדה בהוצאת דבה אותם אנשים וימותו. כל הוצאת דבה לשון חנוך דברים, שמלקיחים לשונם לאדם לדבר בו, כמו (שה''ש ז, י) דובב שפתי ישנים. וישנה לטובה וישנה לרעה, לכך נאמר כאן מוצאי דבת הארץ רעה, שיש דבה שהיא טובה: **דבה.** פרלדי''ץ בלע''ז [לשון הרע] :
@541 **במגפה לפני ה'.** באותה מיתה ההגונה להם מדה כנגד מדה. הם חטאו בלשון, ונשתרבב לשונם עד טבורם ותולעים יוצאים מלשונם ובאין לתוך טבורם, לכך נאמר במגפה ולא במגפה, וזהו לפני ה', באותה הראויה להם על פי מדותיו של הקדוש ברוך הוא, שהוא מודד מדה כנגד מדה:
@542 **ויהושע וכלב חיו** וגו' **.** מה תלמוד לומר חיו מן האנשים ההם, אלא מלמד שנטלו חלקם של מרגלים בארץ וקמו תחתיהם לחיים:
@544 **אל ראש ההר.** והוא הדרך העולה לארץ ישראל: **הננו ועלינו אל המקום.** לארץ ישראל: **אשר אמר ה'.** לתתה לנו שם נעלה: **כי חטאנו.** על אשר אמרנו הלא טוב לנו שוב מצרימה:
@545 **והוא לא תצלח.** זו שאתם עושין לא תצלח:
@547 **כי על כן שבתם.** כלומר כי זאת תבא לכם על אשר שבתם וגו' :
@548 **ויעפלו.** לשון חוזק וכן (חבקוק ב, ד) הנה עפלה. אינגרי''ש בלע''ז [עזי רוח] לשון עזות, וכן (מיכה ד, ח) עפל בת ציון, (ישעיה לב, יד) עפל ובחן. ומדרש תנחומא מפרשו לשון אופל, הלכו חשכים שלא ברשות:
@549 **ויכתום.** כמו (דברים ט, כא) ואכת אתו טחון, מכה אחר מכה: **עד החרמה.** שם המקום נקרא על שם המאורע:
@551 **כי תבאו.** בשר להם שיכנסו לארץ:
@552 **ועשיתם אשה.** אין זה צווי אלא כשתבאו שם ותעלה על לבבכם לעשות אשה לה': **ריח ניחח.** שיהיה נחת רוח לפני: **לפלא נדר או בנדבה** וגו' **.** או שתעשו האשה בשביל חובת מועדיכם שחייבתי אתכם לעשות במועד:
@553 **והקריב המקריב.** תקריבו נסכים ומנחה לכל בהמה המנחה כליל, והשמן נבלל בתוכה, והיין לספלים, כמו ששנינו במסכת סכה (סוכה מח, א) :
@554 **לכבש האחד.** על כל האמור למעלה הוא מוסב על המנחה ועל השמן ועל היין:
@555 **או לאיל.** ואם איל הוא. ורבותינו דרשו או לרבות את הפלגס לנסכי איל:
@559 **אשה ריח.** אינו מוסב אלא על המנחה והשמן, אבל היין אינו אשה, שאינו נתן על האש:
@560 **או לשה.** בין שהוא בכבשים בין שהוא בעזים כבש ושה קרוים בתוך שנתם: **איל.** בן שלשה עשר חדש ויום אחד:
@561 **כמספר אשר תעשו.** כמספר הבהמות אשר תקריבו לקרבן, ככה תעשו נסכים לכל אחד מהם: **כמספרם.** של בהמות מספרם של נסכים:
@564 **ככם כגר.** כמותכם כן גר וכן דרך לשון עברית, (בראשית יג, י) כגן ה' כארץ מצרים, כן ארץ מצרים, (מ''א כב, ד) כמוני כמוך כעמי כעמך:
@567 **בבאכם אל הארץ.** משנה ביאה זו מכל ביאות שבתורה, שבכלן נאמר כי תבא, כי תבאו, לפיכך כלן למדות זו מזו וכיון שפרט לך הכתוב באחת מהן שאינה אלא לאחר ירשה וישיבה, אף כלן כן, אבל זו נאמר בה בבאכם, משנכנסו בה ואכלו מלחמה נתחיבו בחלה:
@569 **ראשית ערסתכם.** כשתלושו כדי עיסתכם שאתם רגילין ללוש במדבר. וכמה היא, (שמות טז, טז) וימדו בעמר עמר לגלגלת, תרימו מראשיתה, כלומר קודם שתאכלו ממנה, ראשית תלקח חלה אחת תרומה לשם ה': **חלה.** טורטי''ל בלע''ז [עוגה] : **כתרומת גרן.** שלא נאמר בה שעור ולא כתרומת מעשר שנאמר בה שעור, אבל חכמים נתנו שעור, לבעל הבית אחד מעשרים וארבעה, ולנחתום אחד מארבעים ושמונה:
@570 **מראשית ערסתיכם.** למה נאמר, לפי שנאמר ראשית עריסותיכם, שומע אני ראשונה שבעיסות, תלמוד לומר מראשית, מקצתה ולא כלה: **תתנו לה' תרומה.** לפי שלא שמענו שעור לחלה, נאמר תתנו, שיהא בה כדי נתינה:
@571 **וכי תשגו ולא תעשו.** עבודה זרה היתה בכלל כל המצות שהצבור מביאין עליהן פר, והרי הכתוב מוציאה כאן מכללן לדון בפר לעולה ושעיר לחטאת: **וכי תשגו** וגו' **.** בעבודה זרה הכתוב מדבר, או אינו אלא באחת מכל המצות, תלמוד לומר את כל המצות האלה, מצוה אחת שהיא ככל המצות, מה העובר על כל המצות פורק עול ומפר ברית ומגלה פנים, אף מצוה זו פורק בה עול ומפר ברית ומגלה פנים ואיזו, זו עבודה זרה: **אשר דבר ה' אל משה.** אנכי ולא יהיה לך מפי הגבורה שמענום, (תהלים סב, יב) אחת דבר אלהים שתים זו שמעתי:
@572 **את כל אשר צוה** וגו' **.** מגיד שכל המודה בעבודה זרה ככופר בכל התורה כלה ובכל מה שנתנבאו הנביאים, שנאמר למן היום אשר צוה ה' והלאה:
@573 **אם מעיני העדה נעשתה לשגגה.** אם מעיני העדה נעשתה עברה זו על ידי שוגג, כגון ששגגו והורו על אחת מן העבודות שהיא מתרת לעבוד עבודה זרה בכך: **לחטת.** חסר א' שאינו כשאר חטאות, שכל חטאות שבתורה הבאות עם עולה החטאת קודמת לעולה, שנאמר (ויקרא ה, י) ואת השני יעשה עולה, וזו עולה קודמת לחטאת:
@574 **הביאו את קרבנם אשה לה'.** זה האמור בפרשה הוא פר העולה שנאמר אשה לה': **וחטאתם.** זה השעיר:
@576 **תחטא בשגגה.** בעבודה זרה: **עז בת שנתה.** שאר עברות יחיד מביא כשבה או שעירה ובזו קבע לה שעירה:
@579 **ביד רמה.** במזיד: **מגדף.** מחרף, כמו (יחזקאל ה, טו) והיתה חרפה וגדופה, (ישעיה לז, ו) אשר גדפו נערי מלך אשור. עוד דרשו רבותינו מכאן למברך את השם שהוא בכרת:
@580 **דבר ה'.** אזהרת עבודה זרה מפי הגבורה, והשאר מפי משה: **עונה בה.** בזמן שעונה בה שלא עשה תשובה:
@581 **ויהיו בני ישראל במדבר וימצאו.** בגנותן של ישראל דבר הכתוב, שלא שמרו אלא שבת ראשונה, ובשניה בא זה וחללה:
@582 **המצאים אתו מקושש.** שהתרו בו ולא הניח מלקושש אף משמצאוהו והתרו בו:
@583 **כי לא פרש מה יעשה לו.** לא היו יודעים באיזו מיתה ימות, אבל יודעים היו שהמחלל שבת במיתה:
@584 **רגום.** כמו עשה פיישנ''ט בלע''ז וכן הלוך אלנ''ט וכן זכור ושמור:
@585 **ויציאו אתו.** מכאן שבית הסקילה חוץ ורחוק מבית דין:
@587 **ועשו להם ציצת.** על שם הפתילים התלויים בה, כמו (יחזקאל ח, ג) ויקחני בציצית ראשי. דבר אחר ציצית על שם וראיתם אתו, כמו (שה''ש ב, ט) מציץ מן החרכים: **על כנפי בגדיהם.** כנגד (שמות יט, ד) ואשא אתכם על כנפי נשרים. על ארבע כנפות ולא בעלת שלש ולא בעלת חמש, כנגד ארבע לשונות של גאלה שנאמר במצרים (שמות ו) והוצאתי והצלתי וגאלתי ולקחתי: **פתיל תכלת.** על שם שכול בכורות. תרגומו של שכול תכלא. ומכתם היתה בלילה וכן צבע התכלת דומה לצבע רקיע המשחיר לעת ערב. ושמונה חוטים שבה, כנגד שמונה ימים ששהו ישראל משיצאו ממצרים עד שאמרו שירה על הים: **תכלת.** צבע ירוק של חלזון:
@588 **וזכרתם את כל מצות ה'.** שמנין גימטריא של ציצית שש מאות, ושמונה חוטים וחמשה קשרים הרי תרי''ג: **ולא תתורו אחרי לבבכם.** כמו (לעיל יג, כה) מתור הארץ. הלב והעינים הם מרגלים לגוף ומסרסרים לו את העברות, העין רואה והלב חומד והגוף עושה את העברות:
@590 **אני ה'.** נאמן לשלם שכר: **אלהיכם.** נאמן לפרע: **אשר הוצאתי אתכם.** על מנת כן פדיתי אתכם שתקבלו עליכם גזרתי: **אני ה' אלהיכם.** עוד למה נאמר, כדי שלא יאמרו ישראל מפני מה אמר המקום, לא שנעשה ונטל שכר, אנו לא עושים ולא נוטלים שכר, על כרחכם אני מלככם. וכן הוא אומר (יחזקאל כ, לג) אם לא ביד חזקה וגו' אמלך עליכם. דבר אחר למה נאמר יציאת מצרים, אני הוא שהבחנתי במצרים בין טפה של בכור לשאינה של בכור, אני הוא עתיד להבחין ולהפרע מן התולה קלא אילן בבגדו ואומר תכלת היא. ומיסודו של רבי משה הדרשן העתקתי, למה נסמכה פרשת מקושש לפרשת עבודה זרה, לומר שהמחלל את השבת כעובד עבודה זרה, שאף היא שקולה ככל המצות, וכן הוא אומר בעזרא (נחמי' ט, יג. טו) ועל הר סיני ירדת ותתן לעמך תורה ומצות ואת שבת קדשך הודעת להם, ואף פרשת ציצית לכך נסמכה לאלו לפי שאף היא שקולה כנגד כל המצות, שנאמר ועשיתם את כל מצותי:
@591 **ויקח קרח.** פרשה זו יפה נדרשת במדרש רבי תנחומא: **ויקח קרח.** לקח את עצמו לצד אחד להיות נחלק מתוך העדה לעורר על הכהנה, וזהו שתרגם אנקלוס ואתפלג נחלק משאר העדה להחזיק במחלוקת, וכן (איוב טו, יב) מה יקחך לבך, לוקח אתך להפליגך משאר בני אדם. דבר אחר ויקח קרח משך ראשי סנהדראות שבהם בדברים, כמו שנאמר (במדבר כ, כה) קח את אהרן, (הושע יד, ג) קחו עמכם דברים: **בן יצהר בן קהת בן לוי.** ולא הזכיר בן יעקב, שבקש רחמים על עצמו שלא יזכר שמו על מחלקתם, שנאמר (בראשית מט, ו) בקהלם אל תחד כבדי. והיכן נזכר שמו על קרח, בהתיחסם על הדוכן בדברי הימים, שנאמר (ד''ה א' ו, כב. כג) בן אביאסף בן קרח בן יצהר בן קהת בן לוי בן ישראל: **ודתן ואבירם.** בשביל שהיה שבט ראובן שרוי בחניתם תימנה, שכן לקהת ובניו החונים תימנה, נשתתפו עם קרח במחלקתו, אוי לרשע אוי לשכנו. ומה ראה קרח לחלוק עם משה, נתקנא על נשיאותו של אליצפן בן עזיאל שמנהו משה נשיא על בני קהת על פי הדבור. אמר קרח, אחי אבא ארבעה היו, שנאמר (שמות ו, יח) ובני קהת וגו' . עמרם הבכור נטלו שני בניו גדלה, אחד מלך ואחד כהן גדול, מי ראוי לטול את השניה, לא אני שאני בן יצהר שהוא שני לעמרם, והוא מנה נשיא את בן אחיו הקטן מכלם, הריני חולק עליו ומבטל את דבריו. מה עשה, עמד וכנס מאתים חמשים ראשי סנהדראות, רבן משבט ראובן שכניו, והם אליצור בן שדיאור וחבריו וכיוצא בו, שנאמר נשיאי עדה קראי מועד, ולהלן הוא אומר (במדבר א, טז) אלה קרואי העדה, והלבישן טליתות שכלן תכלת. באו ועמדו לפני משה. אמרו לו טלית שכלה של תכלת חיבת בציצית או פטורה. אמר להם חיבת. התחילו לשחק עליו, אפשר טלית של מין אחר חוט אחד של תכלת פוטרה, זו שכלה תכלת לא תפטור את עצמה: **בני ראובן.** דתן ואבירם ואון בן פלת:
@593 **רב לכם.** הרבה יותר מדאי לקחתם לעצמכם גדלה: **כלם קדשים.** כלם שמעו דברים בסיני מפי הגבורה: **ומדוע תתנשאו.** אם לקחת אתה מלכות לא היה לך לברר לאחיך כהנה, לא אתם לבדכם שמעתם בסיני אנכי ה' אלהיך (שמות כ, ב) , כל העדה שמעו:
@594 **ויפל על פניו.** מפני המחלקת, שכבר זה בידם סרחון רביעי, חטאו בעגל (שמות לב, יא) ויחל משה, במתאוננים (במדבר יא, יב) ויתפלל משה, במרגלים (שם יד, יג) ויאמר משה אל ה' ושמעו מצרים, במחלקתו של קרח נתרשלו ידיו. משל לבן מלך שסרח על אביו ופייס עליו אוהבו פעם ושתים ושלש, כשסרח רביעית נתרשלו ידי האוהב ההוא. אמר עד מתי אטריח על המלך, שמא לא יקבל עוד ממני:
@595 **בקר וידע** וגו' **.** עתה עת שכרות הוא לנו ולא נכון להראות לפניו והוא היה מתכון לדחותם שמא יחזרו בהם: **בקר וידע ה' את אשר לו.** לעבודת לויה: **ואת הקדוש.** לכהנה: **והקריב.** אותם אליו. והתרגום מוכיח כן ויקריב לקדמוהי יקריב לשמושיה. ומדרשו בקר, אמר לו משה, גבולות חלק הקדוש ברוך הוא בעולמו, יכולים אתם להפוך בקר לערב, כן תוכלו לבטל את זו, שנאמר (בראשית א, ה. ז) ויהי ערב ויהי בקר ויבדל, כך (דה''א כג, יג) ויבדל אהרן להקדישו וגו' :
@596 **זאת עשו קחו לכם מחתות.** מה ראה לומר להם כך, אמר להם בדרכי הגוים יש נמוסים הרבה וכומרים הרבה ואין כלם מתקבצים בבית אחד, אנו אין לנו אלא ה' אחד, ארון אחד ותורה אחת ומזבח אחד וכהן גדול אחד ואתם מאתים וחמשים איש מבקשים כהנה גדולה, אף אני רוצה בכך, הא לכם תשמיש חביב מכל, היא הקטרת החביבה מכל הקרבנות וסם המות נתון בתוכו שבו נשרפו נדב ואביהוא, לפיכך התרה בהם והיה האיש אשר יבחר ה' הוא הקדוש, כבר הוא בקדשתו. וכי אין אנו יודעים שמי שיבחר הוא הקדוש, אלא אמר להם משה הריני אומר לכם שלא תתחיבו, מי שיבחר בו יצא חי, וכלכם אובדים: **מחתות.** כלים שחותין בהם גחלים ויש להם בית יד:
@597 **רב לכם בני לוי.** דבר גדול אמרתי לכם. ולא טפשים היו שכך התרה בהם וקבלו עליהם לקרב, אלא הם חטאו על נפשותם, שנאמר את מחתות החטאים האלה בנפשתם. וקרח שפקח היה מה ראה לשטות זה, עינו הטעתו, ראה שלשלת גדולה יוצאה ממנו, שמואל ששקול כנגד משה ואהרן. אמר בשבילו אני נמלט, ועשרים וארבע משמרות עומדות לבני בניו כלם מתנבאים ברוח הקדש, שנאמר (ד''ה א' כה, ה) כל אלה בנים להימן, אמר אפשר כל הגדלה הזאת עתידה לעמוד ממני ואני אדום, לכך נשתתף לבוא לאותה חזקה, ששמע מפי משה שכלם אובדים ואחד נמלט. אשר יבחר ה' הוא הקדוש, טעה ותלה בעצמו, ולא ראה יפה, לפי שבניו עשו תשובה, ומשה היה רואה. תנחומא: **רב לכם.** דבר גדול נטלתם בעצמכם לחלוק על הקדוש ברוך הוא:
@598 **ויאמר משה אל קרח שמעו נא בני לוי.** התחיל לדבר עמו דברים רכים, כיון שראהו קשה ערף, אמר עד שלא ישתתפו שאר השבטים ויאבדו עמו, אדבר גם אל כלם, התחיל לזרז בהם שמעו נא בני לוי:
@599 **ולעמד לפני העדה.** לשיר על הדוכן:
@600 **ויקרב אתך.** לאותו שרות שהרחיק ממנו שאר עדת ישראל:
@601 **לכן.** בשביל כך אתה וכל עדתך הנעדים אתך על ה' כי בשליחותו עשיתי לתת כהנה לאהרן ולא לנו היא המחלוקת הזו:
@602 **וישלח משה** וגו' **.** מכאן שאין מחזיקין במחלוקת, שהיה משה מחזר אחריהם להשלימם בדברי שלום: **לא נעלה.** פיהם הכשילם, שאין להם אלא ירידה:
@604 **ותתן לנו.** הדבר מוסב על לא האמור למעלה, כלומר לא הביאותנו ולא נתת לנו נחלת שדה וכרם, אמרת לנו (שמות ג, יז) אעלה אתכם מעני מצרים אל ארץ וגו' , משם הוצאתנו ולא אל ארץ זבת חלב ודבש הביאתנו, אלא גזרת עלינו להמיתנו במדבר, שאמרת לנו (במדבר יד, כט) במדבר הזה יפלו פגריכם: **העיני האנשים ההם תנקר** וגו' **.** אפלו אתה שולח לנקר את עינינו אם לא נעלה אליך, לא נעלה: **האנשים ההם.** כאדם התולה קללתו בחברו:
@605 **ויחר למשה מאד.** נצטער עד למאד: **אל תפן אל מנחתם.** לפי פשוטו הקטרת שהם מקריבים לפניך מחר אל תפן אליהם. והמדרש אומר יודע אני שיש להם חלק בתמידי צבור, אף חלקם לא יקבל לפניך לרצון, תניחנו האש ולא תאכלנו: **לא חמור אחד מהם נשאתי.** לא חמורו של אחד מהם נטלתי. אפלו כשהלכתי ממדין למצרים והרכבתי את אשתי ואת בני על החמור, והיה לי לטול אותו החמור משלהם, לא נטלתי אלא משלי. ותרגום אנקלוס, שחרית, לשון ארמי, כך נקראת אנגריא של מלך שחוור:
@606 **והם.** עדתך:
@607 **והקרבתם** וגו' **איש מחתתו.** החמשים ומאתים איש שבכם:
@609 **ויקהל עליהם קרח.** בדברי ליצנות. כל הלילה ההוא הלך אצל השבטים ופתה אותם כסבורין אתם שעלי לבדי אני מקפיד, איני מקפיד אלא בשביל כלכם. אלו באין ונוטלין כל הגדלות, לו המלכות ולאחיו הכהנה, עד שנתפתו כלם: **וירא כבוד ה'.** בא בעמוד ענן:
@612 **אל אלהי הרוחת.** יודע מחשבות. אין מדתך כמדת בשר ודם, מלך בשר ודם שסרחה עליו מקצת מדינה אינו יודע מי החוטא, לפיכך כשהוא כועס נפרע מכלם, אבל אתה לפניך גלויות כל המחשבות ויודע אתה מי החוטא: **האיש אחד.** הוא החוטא ואתה על כל העדה תקצוף. אמר הקדוש ברוך הוא יפה אמרת, אני יודע ומודיע מי חטא ומי לא חטא:
@614 **העלו** וגו' **.** כתרגומו הסתלקו מסביבות משכן קרח:
@615 **ויקם משה.** כסבור שישאו לו פנים ולא עשו:
@617 **יצאו נצבים.** בקומה זקופה לחרף ולגדף, כמו (שמואל א' יז, טז) ויתיצב ארבעים יום דגלית: **ונשיהם ובניהם וטפם.** בא וראה כמה קשה המחלוקת, שהרי בית דין של מטה אין עונשין אלא עד שיביא שתי שערות, ובית דין של מעלה עד עשרים שנה, וכאן אבדו אף יונקי שדים:
@618 **לעשות את כל המעשים האלה.** שעשיתי על פי הדבור לתת לאהרן כהנה גדולה ובניו סגני כהנה ואליצפן נשיא הקהתי:
@619 **לא ה' שלחני.** אלא אני עשיתי הכל מדעתי ובדין הוא חולק עלי:
@620 **ואם בריאה.** חדשה: **יברא ה'.** להמית אותם במיתה שלא מת בה אדם עד הנה, ומה היא הבריאה, ופצתה האדמה את פיה ותבלעם, אז וידעתם כי נאצו הם את ה', ואני מפי הגבורה אמרתי. ורבותינו פרשו אם בריאה. פה לארץ מששת ימי בראשית מוטב, ואם לאו יברא ה':
@624 **נסו לקולם.** בשביל הקול היוצא על בליעתן:
@627 **ואת האש.** שבתוך המחתות: **זרה הלאה.** לארץ מעל המחתות: **כי קדשו.** המחתות ואסורין בהנאה, שהרי עשאום כלי שרת:
@628 **החטאים האלה בנפשתם.** שנעשו פושעים בנפשתם, שנחלקו על הקדוש ברוך הוא: **רקעי.** רדידין: **פחים.** טסין מרדדין טינבי''ש בלע''ז : **צפוי למזבח.** למזבח הנחשת: **ויהיו לאות.** לזכרון, שיאמרו אלו היו מאותן שנחלקו על הכהנה ונשרפו:
@629 **וירקעום.** אטינבירנ ''ט בלע ''ז:
@630 **ולא יהיה כקרח.** כדי שלא יהיה כקרח: **כאשר דבר ה' ביד משה לו.** כמו עליו, על אהרן דבר אל משה, שיהיה הוא ובניו כהנים, לפיכך לא יקרב איש זר אשר לא מזרע אהרן וגו' , וכן כל לי ולו ולהם הסמוכים אצל דבור פתרונם כמו על. ומדרשו על קרח. ומהו ביד משה ולא כתב אל משה, רמז לחולקים על הכהנה שלוקין בצרעת, כמו שלקה משה בידו שנאמר (שמות ד, ו) ויוציאה והנה ידו מצרעת כשלג, ועל כן לקה עזיה בצרעת:
@636 **וכפר עליהם.** רז זה מסר לו מלאך המות כשעלה לרקיע, שהקטרת עוצר המגפה כדאיתא במסכת שבת (שבת פט א) :
@638 **ויעמד בין המתים** וגו' **.** אחז את המלאך והעמידו על כרחו. אמר לו המלאך הנח לי לעשות שליחותי. אמר לו משה צוני לעכב על ידך. אמר לו אני שלוחו של מקום ואתה שלוחו של משה. אמר לו אין משה אומר כלום מלבו אלא מפי הגבורה, אם אין אתה מאמין הרי הקדוש ברוך הוא ומשה אל פתח אהל מועד בא עמי ושאל. וזהו שנאמר וישב אהרן אל משה. דבר אחר למה בקטרת, לפי שהיו ישראל מליזין ומרננים אחר הקטרת לומר סם המות הוא, על ידו מתו נדב ואביהוא, על ידו נשרפו חמשים ומאתים איש, אמר הקדוש ברוך הוא תראו שעוצר מגפה הוא, והחטא הוא הממית:
@643 **כי מטה אחד.** אף על פי שחלקתים לשתי משפחות משפחת כהנה לבד ולויה לבד מכל מקום שבט אחד הוא:
@645 **והשכתי.** כמו וישכו המים (בראשית ח, א) , וחמת המלך שככה: (אסתר ז, י) כא **בתוך מטותם.** הניחו באמצע, שלא יאמרו מפני שהניחו בצד שכינה פרח:
@648 **ויצא פרח.** כמשמעו: **ציץ.** הוא חנטת הפרי כשהפרח נופל: **ויגמל שקדים.** כשהכר הפרי הכר שהן שקדים, לשון (בראשית כא, ח) ויגדל הילד ויגמל, ולשון זה מצוי בפרי האילן, כמו (ישעיה יח, ה) ובסר גמל יהיה נצה. ולמה שקדים, הוא הפרי הממהר להפריח מכל הפרות, אף המעורר על הכהנה פרענותו ממהרת לבא, כמו שמצינו בעזיה (ד''ה ב' כו, יט) והצרעת זרחה במצחו. ותרגומו וכפית שגדין, כמין אשכול שקדים יחד כפותים זה על זה:
@650 **למשמרת לאות.** לזכרון שבחרתי באהרן הכהן ולא ילונו עוד על הכהנה: **ותכל תלונתם.** כמו ותכלה תלונתם, לשון שם מפעל יחיד לנקבה כמו תלנתם מורמורי''ץ בלע''ז [תלנות] ויש חלוק בין תלנותם לתלנתם, תלנתם תלנה אחת, תלנותם שם דבר בלשון יחיד, ואפלו הם תלנות הרבה:
@653 **כל הקרב הקרב** וגו' **.** אין אנו יכולין להיות זהירין בכך, כלנו רשאין להכנס לחצר אהל מועד ואחד שיקריב עצמו יותר מחברו ויכנס לתוך אהל מועד ימות: **האם תמנו לגוע.** שמא הפקרנו למיתה:
@654 **ויאמר ה' אל אהרן.** למשה אמר שיאמר לאהרן להזהירו על תקנת ישראל שלא יכנסו למקדש: **אתה ובניך ובית אביך.** הם בני קהת אבי עמרם: **תשאו את עון המקדש.** עליכם אני מטיל ענש הזרים שיחטאו בעסקי הדברים המקדשים המסורים לכם הוא האהל והארון והשלחן וכלי הקדש אתם תשבו ותזהירו על כל זר הבא לגע: **ואתה ובניך.** הכהנים: **תשאו את עון כהנתכם.** שאינה מסורה ללוים ותזהירו הלוים השוגגים שלא יגעו אליכם בעבודתכם:
@655 **וגם את אחיך.** בני גרשון ובני מררי: **וילוו.** ויתחברו אליכם להזהיר גם את הזרים מלקרב אליהם: **וישרתוך.** בשמירת השערים ולמנות מהם גזברין ואמרכלין:
@657 **וזר לא יקרב אליכם.** אתכם אני מזהיר על כך:
@658 **ולא יהיה עוד קצף.** כמו שהיה כבר, שנאמר (במדבר יז, יא) כי יצא הקצף:
@659 **לכם מתנה נתנים.** יכול לעבודתכם של הדיוט, תלמוד לומר לה', כמו שמפורש למעלה, לשמור משמרת גזברין ואמרכלין:
@660 **עבדת מתנה.** במתנה נתתיה לכם:
@661 **ואני הנה נתתי לך.** בשמחה. לשון שמחה הוא זה, כמו (שמות ד, יד) הנה הוא יוצא לקראתך וראך ושמח בלבו, משל למלך שנתן שדה לאוהבו ולא כתב ולא חתם ולא העלה בערכאין. בא אחד וערער על השדה. אמר לו המלך כל מי שירצה יבא ויערער לנגדך, הריני כותב וחותם לך ומעלה בערכאין, אף כאן לפי שבא קרח וערער כנגד אהרן על הכהנה, בא הכתוב ונתן לו עשרים וארבע מתנות כהנה בברית מלח עולם, ולכך נסמכה פרשה זו לכאן: **משמרת תרומתי.** שאתה צריך לשמרן בטהרה: **למשחה.** לגדלה:
@662 **מן האש.** לאחר הקטרת האשים: **כל קרבנם.** כגון זבחי שלמי צבור: **מנחתם חטאתם ואשמם.** כמשמעו: **אשר ישיבו לי.** זה גזל הגר:
@663 **בקדש הקדשים תאכלנו** וגו' **.** למד על קדשי קדשים שאין נאכלין אלא בעזרה ולזכרי כהנה:
@664 **תרומת מתנם.** המורם מן התודה ומהשלמים ואיל נזיר: **לכל תנופת.** שהרי אלו טעונין תנופה: **כל טהור.** ולא טמאים. דבר אחר כל טהור לרבות אשתו:
@665 **ראשיתם.** היא תרומה גדולה:
@671 **כחזה התנופה וכשוק הימין.** של שלמים שנאכלים לכהנים לנשיהם ולבניהם ולעבדיהם לשני ימים ולילה אחד, אף הבכור נאכל לשני ימים ולילה אחד: **לך יהיה.** בא רבי עקיבא ולמד הוסיף לך הכתוב הויה אחרת, שלא תאמר כחזה ושוק של תודה, שאינו נאכל אלא ליום ולילה:
@672 **כל תרומת הקדשים.** מחבתה של פרשה זו כללה בתחלה וכללה בסוף ופרט באמצע: **ברית מלח עולם.** כרת ברית עם אהרן בדבר הבריא ומתקיים ומבריא את אחרים: **ברית מלח.** כברית הכרותה למלח שאינו מסריח לעולם:
@673 **וחלק לא יהיה לך בתוכם.** אף בבזה:
@676 **והם.** הלוים ישאו עונם של ישראל, שעליהם להזהיר הזרים מגשת אליהם:
@677 **אשר ירימו לה' תרומה.** הכתוב קראו תרומה עד שיפריש ממנו תרומת מעשר:
@680 **ונחשב לכם תרומתכם כדגן מן הגרן.** תרומת מעשר שלכם אסורה לזרים ולטמאים וחייבין עליה מיתה וחמש כתרומה גדולה שנקראת ראשית דגן מן הגרן: **וכמלאה מן היקב.** כתרומת תירוש ויצהר הנטלת מן היקבים: **מלאה.** לשון בשול תבואה שנתמלאת: **יקב.** הוא הבור שלפני הגת שהיין יורד לתוכו. וכל לשון יקב חפירת קרקע הוא, וכן (זכריה יד, י) יקבי המלך, הוא ים אוקיינוס חפירה שחפר מלכו של עולם:
@681 **כן תרימו גם אתם.** כמו שישראל מרימים מגרנם ומיקביהם תרימו גם אתם ממעשר שלכם, כי הוא נחלתכם:
@682 **מכל מתנתיכם תרימו את כל תרומת ה'.** בתרומה גדולה הכתוב מדבר, שאם הקדים לוי את הכהן בכרי וקבל מעשרותיו קודם שיטול כהן תרומה גדולה מן הכרי, צריך להפריש הלוי מן המעשר תחלה אחד מחמשים לתרומה גדולה, ויחזור ויפריש תרומת מעשר:
@683 **בהרימכם את חלבו ממנו.** לאחר שתרימו תרומת מעשר ממנו: **ונחשב.** המותר ללוים חלין גמורין: **כתבואת גרן.** לישראל, שלא תאמר הואיל וקראו הכתוב תרומה שנאמר כי את מעשר בני ישראל אשר ירימו לה' תרומה, יכול יהא כלו אסור, תלמוד לומר ונחשב ללוים כתבואת גרן, מה של ישראל חלין, אף של לוי חלין:
@684 **בכל מקום.** אפלו בבית הקברות:
@685 **ולא תשאו עליו חטא** וגו' **.** הא אם לא תרימו תשאו חטא: **ולא תמותו.** הא אם תחללו תמותו:
@687 **זאת חקת התורה.** לפי שהשטן ואמות העולם מונין את ישראל לומר מה המצוה הזאת ומה טעם יש בה, לפיכך כתב בה חקה, גזרה היא מלפני ואין לך רשות להרהר אחריה: **ויקחו אליך.** לעולם היא נקראת על שמך, פרה שעשה משה במדבר: **אדמה תמימה.** שתהא תמימה באדמימות, שאם היו בה שתי שערות שחורות פסולה: **ויקחו אליך.** משלהם כשם שהם פרקו נזמי הזהב לעגל משלהם כך יביאו זו לכפרה משלהם: **פרה אדמה.** משל לבן שפחה שטנף פלטין של מלך. אמרו תבא אמו ותקנח הצואה, כך תבא פרה ותכפר על העגל: **אדמה.** על שם (ישעיה א, יח) אם יאדימו כתולע, שהחטא קרוי אדום: **תמימה.** על שם ישראל שהיו תמימים ונעשו בו בעלי מומין, תבא זו ותכפר עליהם ויחזרו לתמותם: **לא עלה עליה על.** כשם שפרקו מעליהם עול שמים:
@688 **אלעזר.** מצותה בסגן: **אל מחוץ למחנה.** חוץ לשלש מחנות: **ושחט אתה לפניו.** זר שוחט ואלעזר רואה: **אל אלעזר הכהן.** כשם שנקהלו על אהרן, שהוא כהן, לעשות העגל. ולפי שאהרן עשה את העגל לא נעשית עבודה זו על ידו, שאין קטיגור נעשהסניגור:
@689 **אל נכח פני אהל מועד.** עומד במזרחו של ירושלים ומתכון ורואה פתחו של היכל בשעת הזאה הדם: **ושרף את הפרה.** כשם שנשרף העגל:
@691 **עץ ארז ואזוב ושני תולעת.** שלשה מינין הללו כנגד שלשת אלפי איש שנפלו בעגל. וארז הוא הגבוה מכל האילנות ואזוב נמוך מכלם, סימן שהגבוה שנתגאה וחטא, ישפיל את עצמו כאזוב ותולעת ויתכפר לו:
@692 **אל המחנה.** למחנה שכינה, שאין טמא משלח חוץ לשתי מחנות אלא זב ובעל קרי ומצורע: **וטמא הכהן עד הערב.** סרסהו ודרשהו וטמא עד הערב ואחר יבוא אל המחנה:
@694 **והניח מחוץ למחנה.** לשלשה חלקים מחלקה, אחד נתן בהר המשחה, ואחד מתחלק לכל המשמרות, ואחד נתן בחיל. זה של משמרות היה חוץ לעזרה לטול ממנו בני העירות וכל הצריכין להטהר, וזה שבהר המשחה כהנים גדולים לפרות אחרות מקדשין המנו, וזה שבחיל נתון למשמרת מגזרת הכתוב, שנאמר והיתה לעדת בני ישראל למשמרת: **למי נדה.** למי הזיה, כמו (איכה ג, נג) וידו אבן בי, (זכריה ב, ד) לידות את קרנות הגוים, לשון זריקה: **חטאת הוא.** לשון חטוי כפשוטו, ולפי הלכותיו קראה הכתוב חטאת, לומר, שהיא כקדשים להאסר בהנאה: **למשמרת.** כמו שפשע העגל שמור לדורות לפרענות, שאין לך פקודה שאין בה מפקודת העגל, שנאמר (שמות לב, לד) וביום פקדי ופקדתי וגו' . וכשם שהעגל טמא כל העוסקין בו, כך פרה מטמאה כל העוסקין בה, וכשם שנטהרו באפרו, שנאמר (שמות לב, כ) ויזר על פני המים וגו' , כך ולקחו לטמא מעפר שרפת החטאת וגו' :
@697 **הוא יתחטא בו.** באפר הזה:
@698 **במת בנפש.** ואי זה מת, של נפש האדם, להוציא נפש בהמה, שאין טמאתה צריכה הזאה. דבר אחר בנפש זו רביעית דם: **את משכן ה' טמא.** אם נכנס לעזרה אפלו בטבילה בלא הזאת שלישי ושביעי: **עוד טמאתו בו.** אף על פי שטבל:
@699 **כל הבא אל האהל.** בעוד שהמת בתוכו:
@700 **וכל כלי פתוח.** בכלי חרס הכתוב מדבר, שאין מקבל טמאה מגבו אלא מתוכו, לפיכך אם אין מגופת צמידתו פתולה עליו יפה בחבור, טמא הוא, הא אם יש צמיד פתיל עליו טהור: **פתיל.** לשון מחבר בלשון עברי, וכן (בראשית ל, ח) נפתולי אלהים נפתלתי, נתחברתי עם אחותי:
@701 **על פני השדה.** רבותינו דרשו לרבות גולל ודופק. ופשוטו על פני השדה, שאין שם אהל, מטמא המת שם בנגיעה:
@704 **וחטאו ביום השביעי.** הוא גמר טהרתו:
@705 **ואיש אשר יטמא** וגו' **.** אם נאמר מקדש למה נאמר משכן וכו' כדאיתא בשבועות (דף טז ב) :
@706 **ומזה מי הנדה.** רבותינו אמרו שהמזה טהור, וזה בא ללמד שהנושא מי חטאת טמא טמאה חמורה לטמא בגדים שעליו, מה שאין כן בנוגע. וזה שהוציאו בלשון מזה, לומר לך, שאינן מטמאין עד שיהא בהן שעור הזאה: **והנגע** וגו' **יטמא.** ואין טעון כבוס בגדים:
@707 **וכל אשר יגע בו.** הטמא הזה שנטמא במת יטמא: **והנפש הנגעת.** בו בטמא מת: **תטמא עד הערב.** מכאן למדנו שהמת אבי אבות הטמאה והנוגע בו אב הטמאה ומטמא אדם, זהו פרושה לפי משמעה והלכותיה: ומדרש אגדה העתקתי מיסודו שלר' משה הדרשן וזהו:
@708 **כל העדה.** עדה השלמה, שכבר מתו מתי מדבר ואלו פרשו לחיים: **ותמת שם מרים.** למה נסמכה פרשת מיתת מרים לפרשת פרה אדמה, לומר לך מה קרבנות מכפרין אף מיתת צדיקים מכפרת: **ותמת שם מרים.** אף היא בנשיקה מתה ומפני מה לא נאמר בה על פי ה', שאינו דרך כבוד של מעלה. ובאהרן נאמר על פי ה', באלה מסעי (במדבר לג, לח) :
@709 **ולא היה מים לעדה.** מכאן שכל ארבעים שנה היה להם הבאר בזכות מרים:
@710 **ולו גוענו.** הלואי שגוענו: **בגוע אחינו.** במיתת אחינו בדבר, למד שמיתת צמא מגנה ממנה: **בגוע.** שם דבר הוא, כמו במיתת אחינו, ולא יתכן לפרשו כשמתו אחינו, שאם כן היה לו להנקד בגוע:
@715 **ואת בעירם.** מכאן שחס הקדוש ברוך הוא על ממונם של ישראל:
@717 **ויקהלו** וגו' **.** זה אחד מן המקומות שהחזיק מועט את המרבה: **המן הסלע הזה נוציא.** לפי שלא היו מכירין אותו, לפי שהלך הסלע וישב לו בין הסלעים, כשנסתלק הבאר, והיו ישראל אומרים להם מה לכם מאיזה סלע תוציאו לנו מים, לכך אמר להם המרים סרבנים, לשון יוני שוטים, מורים את מוריהם, המן הסלע הזה שלא נצטוינו עליו נוציא לכם מים:
@718 **פעמים.** לפי שבראשונה לא הוציא אלא טפין, לפי שלא צוה המקום להכותו אלא ודברתם אל הסלע, והמה דברו אל סלע אחר ולא הוציא, אמרו שמא צריך להכות כבראשונה, שנאמר (שמות יז, ו) והכית בצור, ונזדמן להם אותו סלע והכהו:
@719 **יען לא האמנתם בי.** גלה הכתוב שאלולי חטא זה בלבד היו נכנסין לארץ, כדי שלא יאמרו עליהם כעון שאר דור המדבר, שנגזר עליהם שלא יכנסו לארץ, כך היה עון משה ואהרן. והלא (במדבר יא, כב) הצאן ובקר ישחט קשה מזו, אלא לפי שבסתר חסך עליו הכתוב, וכאן שבמעמד כל ישראל, לא חסך עליו הכתוב מפני קדוש השם: **להקדישני.** שאלו דברתם אל הסלע והוציא הייתי מקדש לעיני העדה ואומרים מה סלע זה שאינו מדבר ואינו שומע ואינו צריך לפרנסה מקים דבורו של מקום, קל וחמר אנו: **לכן לא תביאו.** בשבועה, כמו (שמואל א' ג, יד) לכן נשבעתי לבית עלי, נשבע בקפיצה כדי שלא ירבו בתפלה על כך:
@720 **המה מי מריבה.** הם הנזכרים במקום אחר, את אלו ראו אצטגניני פרעה שמושיען של ישראל לוקה במים, לכך גזרו (שמות א) כל הבן הילוד היאורה תשליכוהו: **ויקדש בם.** שמתו משה ואהרן על ידם. שכשהקדוש ברוך הוא עושה דין במקדשיו הוא יראוי ומתקדש על הבריות, וכן הוא אומר (תהלים סח, לו) נורא אלהים ממקדשיך, וכן הוא אומר (ויקרא י, ג) בקרובי אקדש:
@721 **אחיך ישראל.** מה ראה להזכיר כאן אחוה, אלא אמר לו אחים אנחנו בני אברהם, שנאמר לו (בראשית טו, יג) כי גר יהיה זרעך, ועל שנינו היה אותו החוב לפרעו: **אתה ידעת את כל התלאה.** לפיכך פרש אביכם מעל אבינו (שם לו, ו) וילך אל ארץ מפני יעקב אחיו, מפני השטר חוב המטל עליהם והטילו על יעקב:
@722 **וירעו לנו.** סבלנו צרות רבות: **ולאבותינו.** מכאן שהאבות מצטערים בקבר, כשפרענות באה על ישראל:
@723 **וישמע קלנו.** בברכה שברכנו אבינו (בראשית כז, כב) הקול קול יעקב, שאנו צועקים ונענים: **מלאך.** זה משה מכאן שהנביאים קרואים מלאכים, ואומר (ד''ה ב' לו, טז) ויהיו מלעיבים במלאכי האלהים:
@724 **נעברה נא בארצך.** אין לך לעורר על הירשה של ארץ ישראל, כשם שלא פרעת החוב. עשה לנו עזר מעט לעבור דרך ארצך: **ולא נשתה מי באר.** מי בורות היה צריך לומר אלא כך אמר משה אף על פי שיש בידינו מן לאכול ובאר לשתות, לא נשתה ממנו אלא נקנה מכם אוכל ומים להנאתכם, מכאן לאכסנאי שאף על פי שיש בידו לאכול, יקנה מן החנוני כדי להנות את אשפיזו: **דרך המלך נלך** וגו' **.** אנו חוסמים את בהמתנו ולא יטו לכאן ולכאן לאכול:
@725 **פן בחרב אצא לקראתך.** אתם מתגאים בקול שהורישכם אביכם, אמרתם (דברים כו, ז) ונצעק אל ה' וישמע קולנו, ואני אצא עליכם במה שהורישני אבי (בראשית כז, מ) ועל חרבך תחיה:
@726 **רק אין דבר.** אין שום דבר מזיקך:
@727 **וביד חזקה.** בהבטחת זקננו והידים ידי עשו:
@729 **כל העדה.** כלם שלמים ועומדים להכנס לארץ שלא היה בהן אחד מאותם שנגזרה גזרה עליהם שכבר כלו מתי מדבר, ואלו מאותן שכתוב בהן (דברים ד, ד) חיים כלכם היום: **הר ההר.** הר על גבי הר כתפוח קטן על גבי תפוח גדול, ואף על פי שהענן הולך לפניהם ומשוה את ההרים, שלשה נשארו בהן הר סיני לתורה והר נבו לקבורת משה והר ההר לקבורת אהרן:
@730 **על גבול ארץ אדום.** מגיד שמפני שנתחברו כאן להתקרב לעשו הרשע, נפרצו מעשיהם וחסרו הצדיק הזה, וכן הנביא אומר ליהושפט (דברי הימים ב' כ, לז) כהתחברך עם אחזיהו פרץ ה' את מעשיך:
@732 **קח את אהרן.** בדברי נחומים. אמור לו אשריך שתראה כתרך נתון לבנך מה שאין אני זכאי לכך:
@733 **את בגדיו.** את בגדי כהנה גדולה הלבישהו והפשיטם מעליו לתתם על בנו בפניו. אמר לו הכנס למערה, ונכנס. ראה מטה מצעת ונר דלוק. אמר לו עלה למטה, ועלה. פשוט ידיך, ופשט. קמוץ פיך, וקמץ. עצום עיניך, ועצם. מיד חמד משה לאותה מיתה, וזהו שנאמר לו (דברים לב, נ) כאשר מת אהרן אחיך, מיתה שנתאוית לה:
@734 **ויעש משה.** אף על פי שהדבר קשה לו לא עכב:
@736 **ויראו כל העדה** וגו' **.** כשראו משה ואלעזר יורדים ואהרן לא ירד, אמרו היכן הוא אהרן. אמר להם מת. אמרו לו אפשר מי שעמד כנגד המלאך ועצר את המגפה ישלוט בו מלאך המות. מיד בקש משה רחמים והראוהו מלאכי השרת להם מטל במטה, ראו והאמינו: **כל בית ישראל.** האנשים והנשים, לפי שהיה אהרן רודף שלום ומטיל אהבה בין בעלי מריבה ובין איש לאשתו: **כי גוע.** אומר אני שהמתרגם דהא מית טועה הוא, אלא אם כן מתרגם ויראו ואתחזיאו, שלא אמרו רבותינו זכרונם לברכה כי זה משמש בלשון דהא אלא על מדרש שנסתלקו ענני כבוד, וכדאמר ר' אבהו (ראש השנה ג, א) , דאמר רבי אבהו אל תקרי ויראו אלא ויראו ועל לשון זה נופל לשון דהא, לפי שהוא נתינת טעם למה של מעלה המנו. למה ויראו, לפי שהרי מת אהרן. אבל על תרגום וחזו כל כנישתא, אין לשון דהא נופל אלא לשון אשר, שהוא מגזרת שמוש אי, שמצינו אם משמש בלשון אשר, כמו (איוב כא, ד) ואם מדוע לא תקצר רוחי, והרבה מפורשים כזה הלשון (שם יד, ה) אם חרוצים ימיו:
@737 **וישמע הכנעני.** שמע שמת אהרן ונסתלקו ענני כבוד וכו' , כדאיתא בראש השנה (דף ג א) . ועמלק מעולם רצועת מרדות לישראל, מזמן בכל עת לפרענות: **ישב הנגב.** זה עמלק, שנאמר (במדבר יג, כט) עמלק יושב בארץ הנגב. ושנה את לשונו לדבר בלשון כנען, כדי שיהיו ישראל מתפללים להקדוש ברוך הוא לתת כנענים בידם והם אינם כנענים, ראו ישראל לבושיהם כלבושי עמלקים ולשונם לשון כנען, אמרו נתפלל סתם, שנאמר אם נתן תתן את העם הזה בידי: **דרך האתרים.** דרך הנגב שהלכו בה המרגלים שנאמר (במדבר יג, כב) ויעלו בנגב. דבר אחר דרך האתרים דרך התיר הגדול הנוסע לפניהם, שנאמר (במדבר י, לג) דרך שלשת ימים לתור להם מנוחה: **וישב ממנו שבי.** אינה אלא שפחה אחת:
@738 **והחרמתי.** אקדיש שללם לגבוה:
@739 **ויחרם אתהם.** בהריגה: **ואת עריהם.** חרמי גבוה:
@740 **דרך ים סוף.** כיון שמת אהרן ובאה עליהם מלחמה זו חזרו לאחוריהם דרך ים סוף, הוא הדרך שחזרו להם כשנגזר עליהם גזרת מרגלים, שנאמר (דברים א, מ) ויסעו המדברה דרך ים סוף. וכאן חזרו לאחוריהם שבע מסעות, שנאמר (שם י, ו) ובני ישראל נסעו מבארות בני יעקן מוסרה שם מת אהרן. וכי במוסרה מת, והלא בהר ההר מת, אלא שם חזרו והתאבלו עליו והספידוהו כאלו הוא בפניהם. וצא ובדוק במסעות ותמצא שבע מסעות מן מוסרה עד הר ההר: **לסבב את ארץ אדום.** שלא נתנם לעבור בארצו: **ותקצר נפש העם בדרך.** בטורח הדרך שהקשה להם. אמרו עכשו היינו קרובים להכנס לארץ ואנו חוזרים לאחורינו כך חזרו אבותינו ונשתהו שלשים ושמונה שנה עד היום, לפיכך קצרה נפשם בענוי הדרך. ובלשון לע''ז אינקרו''ט לו''ר . ולא יתכן לומר ותקצר נפש העם בדרך בהיותו בדרך. ולא פרש בו במה קצרה, שכל מקום שתמצא קצור נפש במקרא מפורש שם במה קצרה, כגון (זכריה יא, ח) ותקצר נפשי בהם, וכגון (שופטים י, טז) ותקצר נפשו בעמל ישראל, וכל דבר הקשה על אדם נופל בו לשון קצור נפש, כאדם שהטורח בא עליו ואין דעתו רחבה לקבל אותו הדבר, ואין לו מקום בתוך לבו לגור שם אותו הצער, ובדבר המטריח נופל לשון גדל, שגדול הוא וכבד על האדם, כגון (זכריה יא, ח) וגם נפשם בחלה בי, גדלה עלי, (איוב י, טז) ויגאה כשחל תצודני, כללו של פרוש כל לשון קצור נפש בדבר, לשון שאין יכול לסבלו הוא, שאין הדעת סובלתו:
@741 **באלהים ובמשה.** השוו עבד לקונו: **למה העליתנו.** שניהם שוים: **ונפשנו קצה.** אף זה לשון קצור נפש ומאוס: **בלחם הקלקל.** לפי שהמן נבלע באיברים קראוהו קלקל. אמרו עתיד המן הזה שיתפח במעינו, כלום יש ילוד אשה שמכניס ואינו מוציא:
@742 **את הנחשים השרפים.** ששורפים את האדם בארס שניהם: **וינשכו את העם.** יבא נחש שלקה על הוצאת דבה ויפרע ממוציאי דבה. יבא נחש שכל המינין נטעמים לו טעם אחד ויפרע מכפויי טובה, שדבר אחד משתנה להם לכמה טעמים:
@743 **ויתפלל משה.** מכאן למי שמבקשים ממנו מחילה שלא יהא אכזרי מלמחול:
@744 **על נס.** על כלונס שקורים פירק''א בלע''ז [מוט] וכן (ישעיה ל, יז) וכנס על הגבעה, (שם מט, כב) ארים נסי, (שם יג, ב) שאו נס, ולפי שהוא גבוה לאות ולראיה קראו נס: **כל הנשוך.** אפלו כלב או חמור נושכו היה נזוק ומתנונה והולך, אלא שנשיכת הנחש ממהרת להמית, לכך נאמר כאן וראה אתו ראיה בעלמא, ובנשיכת הנחש נאמר והביט, והיה אם נשך הנחש את איש והביט וגו' , שלא היה ממהר נשוך הנחש להתרפאות אלא אם כן מביט בו בכונה. ואמרו רבותינו וכי נחש ממית או מחיה, אלא בזמן שהיו ישראל מסתכלין כלפי מעלה ומשעבדין את לבם לאביהם שבשמים היו מתרפאים, ואם לאו היו נמוקים:
@745 **נחש נחשת.** לא נאמר לו לעשותו של נחשת, אלא אמר משה הקדוש ברוך הוא קוראו נחש, ואני אעשנו של נחשת, לשון נופל על לשון:
@747 **בעיי העברים.** לא ידעתי למה נקרא שמם עיים. ועי לשון חרבה הוא דבר הטאוט במטאטא, והעי''ן בו יסוד לבדה והוא מלשון יעים, (ישעיה כח, יז) ויעה ברד: **העברים.** דרך מעבר העוברים שם את הר נבו אל ארץ כנען, שהוא מפסיק בין ארץ מואב לארץ אמורי: **על פני מואב ממזרח השמש.** במזרחה של ארץ מואב:
@749 **מגבל האמרי.** תחום סוף מצר שלהם, וכן (דברים ב, יח) גבול מואב, לשון קצה וסוף: **מעבר ארנון.** הקיפו ארץ מואב כל דרומה ומזרחה עד שבאו מעבר השני לארנון בתוך ארץ האמורי בצפונה של ארץ מואב: **היוצא מגבל האמרי.** רצועה יוצאה מגבול האמורי והיא של אמוריים ונכנסת לגבול מואב עד ארנון, שהוא גבול מואב ושם חנו ישראל, ולא באו לגבול מואב, כי ארנון גבול מואב, והם לא נתנו להם רשות לעבור בארצם. ואף על פי שלא פרשה משה, פרשה יפתח, כמו שאמר יפתח (שופטים יא, יז) וגם אל מלך מואב שלח ולא אבה. ומשה רמזה (דברים ב, כט) כאשר עשו לי בני עשו היושבים בשעיר והמואבים היושבים בער, מה אלו לא נתנום לעבור בתוך ארצם אלא הקיפום סביב, אף מואב כן:
@750 **על כן יאמר.** על חניה זו ונסים שנעשו בה יאמר בספר מלחמות ה', כשמספרים נסים שנעשו לאבותינו יספרו את והב וגו' : **את והב.** כמו את יהב, כמו שיאמר מן יעד ועד, כן יאמר מן יהב והב. והוי''ו יסוד הוא, כלומר את אשר יהב להם הרבה נסים בים סוף: **ואת הנחלים ארנון.** כשם שמספרים בנסי ים סוף, כך יש לספר בנסי נחלי ארנון, שאף כאן נעשו נסים גדולים. ומה הם הנסים:
@751 **ואשד הנחלים.** תרגום של שפך אשד. שפך הנחלים שנשפך שם דם אמוריים שהיו נחבאים שם, לפי שהיו ההרים גבוהים והנחל עמוק וקצר וההרים סמוכים זה לזה, אדם עומד על ההר מזה ומדבר עם חברו בהר מזה, והדרך עובר תוך הנחל. אמרו אמוריים כשיכנסו ישראל לתוך הנחל לעבור, נצא מן המערות בהרים שלמעלה מהם ונהרגם בחצים ואבני בליסטראות. והיו אותן הנקעים בהר של צד מואב ובהר של צד אמוריים היו כנגד אותן נקעים כמין קרנות ושדים בולטין לחוץ, כיון שבאו ישראל לעבור נזדעזע ההר של ארץ ישראל, כשפחה היוצאת להקביל פני גברתה, ונתקרב לצד הר של מואב ונכנסו אותן השדים לתוך אותן נקעים והרגום. וזהו אשר נטה לשבת ער, שההר נטה ממקומו ונתקרב לצד גבול מואב ונדבק בו, וזהו ונשען לגבול מואב:
@752 **ומשם בארה.** משם בא האשד אל הבאר. כיצד, אמר הקדוש ברוך הוא מי מודיע לבני הנסים הללו. המשל אומר נתת פת לתינוק הודיע לאמו. לאחר שעברו חזרו ההרים למקומם והבאר ירדה לתוך הנחל והעלתה משם דם ההרוגים וזרועות ואיברים ומוליכתן סביב המחנה וישראל, ראו ואמרו שירה:
@753 **עלי באר.** מתוך הנחל והעלי מה שאת מעלה. ומנין שהבאר הודיעה להם, שנאמר ומשם בארה. וכי משם היתה, והלא מתחלת ארבעים שנה היתה עמהם, אלא שירדה לפרסם את הנסים, וכן אז ישיר ישראל. השירה הזאת נאמרה בסוף ארבעים, והבאר נתנה להם מתחלת ארבעים, ומה ראה לכתב כאן, אלא הענין הזה נדרש למעלה המנו:
@754 **באר חפרוה.** זאת היא הבאר אשר חפרוה שרים משה ואהרן: **במשענותם.** במטה: **וממדבר.** נתנה להם:
@755 **וממתנה נחליאל.** כתרגומו:
@756 **ומבמות הגיא אשר בשדה מואב.** כי שם מת משה ושם בטלה הבאר. דבר אחר כרוה נדיבי העם כל נשיא ונשיא כשהיו חונים נוטל מקלו ומושך אצל דגלו ומחנהו ומי הבאר נמשכין דרך אותו סימן ובאין לפני חנית כל שבט ושבט: **במחקק.** על פי משה שנקרא מחוקק, שנאמר (דברים לג, כא) כי שם חלקת מחקק ספון. ולמה לא נזכרמשה בשירה זו, לפי שלקה על ידי הבאר. וכיון שלא נזכר שמו של משה לא נזכר שמו של הקדוש ברוך הוא. משל למלך שהיו מזמנין אותו לסעודה, אמר אם אוהבי שם אני שם, ואם לאו איני הולך: **ראש הפסגה.** כתרגומו ריש רמתא: **פסגה.** לשון גובה, וכן (תהלים מח, יד) פסגו ארמנותיה, הגביהו ארמנותיה: **ונשקפה.** אותה הפסגה על פני המקום ששמו ישימון, והוא לשון מדבר שהוא שמם. דבר אחר ונשקפה הבאר על פני הישימון שנגנזה בימה של טבריה והעומד על הישימון מביט ורואה כמין כברה בים והיא הבאר, כך דרש רבי תנחומא:
@757 **וישלח ישראל מלאכים.** ובמקום אחר תולה השליחות במשה, שנאמר (דברים ב, כו) ואשלח מלאכים ממדבר קדמות, וכן (במדבר כ, יד) וישלח משה מלאכים מקדש אל מלך אדום, וביפתח הוא אומר (שופטים יא, יז) וישלח ישראל מלאכים אל מלך אדום וגו' , הכתובים הללו צריכים זה לזה, זה נועל וזה פותח, שמשה הוא ישראל וישראל הם משה, לומר לך שנשיא הדור הוא ככל הדור, כי הנשיא הוא הכל:
@758 **אעברה בארצך.** אף על פי שלא נצטוו לפתח להם בשלום בקשו מהם שלום:
@759 **ולא נתן סיחן** וגו' **.** לפי שכל מלכי כנען היו מעלין לו מס שהיה שומרם שלא יעברו עליהם גיסות, כיון שאמרו לו ישראל אעברה בארצך אמר להם כל עצמי איני יושב כאן אלא לשמרם מפניכם ואתם אומרים כך: **ויצא לקראת ישראל.** אלו היתה חשבון מלאה יתושין, אין כל בריה יכולה לכבשה, ואם היה סיחון בכפר חלש אין כל אדם יכול לכבשו, וכל שכן אלו שהיה בחשבון. אמר הקדוש ברוך הוא מה אני מטריח על בני כל זאת לצור על כל עיר ועיר, נתן בלב כל אנשי המלחמה לצאת מן העירות ונתקבצו כלם למקום אחד, ושם נפלו. ומשם הלכו ישראל אל הערים ואין עומד לנגדם כי אין שם איש, אלא נשים וטף:
@760 **כי עז.** ומהו חזקו, התראתו של הקדוש ברוך הוא, שאמר להם (דברים ב, יט) אל תצרם וגו' :
@761 **בנתיה.** כפרים הסמוכים לה:
@762 **והוא נלחם.** למה הצרך להכתב, לפי שנאמר (דברים ב, ט) אל תצר את מואב, וחשבון משל מואב היתה, כתב לנו שסיחון לקחה מהם ועל ידו טהרה לישראל: **מידו.** מרשותו:
@763 **על כן.** על אותה מלחמה שנלחם סיחון במואב: **יאמרו המשלים.** בלעם, שנאמר בו (במדבר כג, ז) וישא משלו: **המשלים.** בלעם ובעור. והם אמרו: **באו חשבון.** שלא היה סיחון יכול לכבשה והלך ושכר את בלעם לקללו, וזהו שאמר לו בלק (שם כב, ו) כי ידעתי את אשר תברך מברך וגו' : **תבנה ותכונן.** חשבון בשם סיחון להיות עירו:
@764 **כי אש יצאה מחשבון.** משכבשה סיחון: **אכלה ער מואב.** שם אותה המדינה קרוי ער בלשון עברי, ולחית בלשון ארמי: **ער מואב.** ער של מואב:
@765 **אוי לך מואב.** שקללו את מואב שימסרו בידו: **כמוש.** שם אלהי מואב: **נתן.** הנותן את בניו של מואב: **פליטם.** נסים ופליטים מחרב ואת בנותיו בשבית וגו' :
@766 **ונירם.** מלכות שלהם: **אבד חשבון עד דיבן.** מלכות ועול שהיה למואב בחשבון אבד משם, וכן עד דיבן. תרגום שלסר, עד. כלומר סר ניר מדיבון. ניר לשון מלכות ועול וממשלת איש, כמו (מלכים א' יא, לו) למען היות ניר לדוד עבדי: **ונשים.** שי''ן דגושה לשון שממה, כך יאמרו המושלים ונשים אותם: **עד נפח.** השמונום עד נפח:
@768 **וישלח משה לרגל את יעזר.** המרגלים לכדוה. אמרו לא נעשה כראשונים, בטוחים אנו בכח תפלתו של משה להלחם:
@770 **אל תירא אתו.** שהיה משה ירא להלחם, שמא תעמד לו זכותו של אברהם, שנאמר (בראשית יד, יג) ויבא הפליט, הוא עוג, שפלט מן הרפאים שהכו כדרלעומר וחבריו בעשתרות קרנים, שנאמר (דברים ג, יא) כי רק עוג מלך הבשן נשאר מיתר הרפאים:
@771 **ויכו אתו.** משה הרגו, כדאיתא בברכות בהרואה (דף נד, ב) עקר טורא בת תלתא פרסי וכו' :
@773 **וירא בלק בן צפור את כל אשר עשה ישראל לאמרי.** אמר אלו שני מלכים שהיינו בטוחים עליהם לא עמדו בפניהם, אנו על אחת כמה וכמה. לפיכך ויגר מואב:
@774 **ויגר.** לשון מורא, כמו (איוב יט, כט) גורו לכם: **ויקץ מואב.** קצו בחייהם:
@775 **אל זקני מדין.** והלא מעולם היו שונאים זה את זה, שנאמר (בראשית לו, לה) המכה את מדין בשדה מואב, שבאו מדין על מואב למלחמה. אלא מיראתן של ישראל עשו שלום ביניהם. ומה ראה מואב לטול עצה ממדין, כיון שראו את ישראל נוצחים שלא כמנהג העולם, אמרו מנהיגם של אלו במדין נתגדל, נשאל מהם מה מדתו. אמרו לו אין כחו אלא בפיו. אמרו אף אנו נבא עליהם באדם שכחו בפיו: **כלחוך השור.** כל מה שהשור מלחך אין בו ברכה: **בעת ההוא.** לא היה ראוי למלכות. מנסיכי מדין היה, וכיון שמת סיחון מנוהו עליהם לצורך שעה:
@776 **פתורה.** כשלחני הזה שהכל מריצין לו מעות, כך כל המלכים מריצין לו אגרותיהם. ולפי פשוטו של מקרא כך שם המקום: **ארץ בני עמו.** של בלק. משם היה, וזה היה מתנבא ואומר לו עתיד אתה למלוך. ואם תאמר מפני מה השרה הקדוש ברוך הוא שכינתו על גוי רשע, כדי שלא יהא פתחון פה לאמות לומר אלו היו לנו נביאים חזרנו למוטב, העמיד להם נביאים והם פרצו גדר העולם, שבתחלה היו גדורים בעריות וזה נתן להם עצה להפקיר עצמן לזנות: **לקרא לו.** הקריאה שלו היתה ולהנאתו, שהיה פוסק לו ממון הרבה: **עם יצא ממצרים.** ואם תאמר מה מזיקך: **הנה כסה את עין הארץ.** סיחון ועוג שהיו שומרים אותנו עמדו עליהם והרגום: **והוא ישב ממלי.** חסר כתיב, קרובים הם להכריתני, כמו (תהלים קיח, י) כי אמילם:
@777 **נכה בו.** אני ועמי נכה לו בהם. דבר אחר לשון משנה היא (ב''מ קה ב) מנכה לו מן הדמים, לחסר מהם מעט: **כי ידעתי** וגו' **.** על ידי מלחמת סיחון שעזרתו להכות את מואב:
@778 **וקסמים בידם.** כל מיני קסמים, שלא יאמר אין כלי תשמישי עמי. דבר אחר קסם זה נטלו בידם זקני מדין, אמרו אם יבא עמנו בפעם הזאת יש בו ממש, ואם ידחנו אין בו תועלת, לפיכך כשאמר להם לינו פה הלילה, אמרו אין בו תקוה, הניחוהו והלכו להם, שנאמר וישבו שרי מואב עם בלעם, אבל זקני מדין הלכו להם:
@779 **לינו פה הלילה.** אין רוח הקדש שורה עליו אלא בלילה, וכן לכל נביאי אמות העולם, וכן לבן בחלום הלילה, שנאמר (בראשית לא, כד) ויבא אלהים אל לבן הארמי בחלם הלילה. כאדם ההולך אצל פלגשו בהחבא: **כאשר ידבר ה' אלי.** אם ימליכני ללכת עם בני אדם כמותכם אלך עמכם, שמא אין כבודו לתתי להלך אלא עם שרים גדולים מכם: **וישבו.** לשון עכבה:
@780 **מי האנשים האלה עמך.** להטעותו בא. אמר פעמים שאין הכל גלוי לפניו, אין דעתו שוה עליו, אף אני אראה עת שאוכל לקלל ולא יבין:
@781 **בלק בן צפור** וגו' **.** אף על פי שאיני חשוב בעיניך, חשוב אני בעיני המלכים:
@782 **קבה לי.** זו קשה מארה לי, שהוא נוקב ומפרש: **וגרשתיו.** מן העולם. ובלק לא אמר אלא ואגרשנו מן הארץ, איני מבקש אלא להסיעם מעלי, ובלעם היה שונאם יותר מבלק:
@783 **לא תלך עמהם.** אמר לו אם כן אקללם במקומי. אמר לו לא תאר את העם. אמר לו אם כן אברכם. אמר לו אינם צריכין לברכתך, כי ברוך הוא. משל אומרים לצרעה לא מדבשיך ולא מעקציך:
@784 **להלך עמכם.** אלא עם שרים גדולים מכם. למדנו שרוחו גבוהה ולא רצה לגלות שהוא ברשותו של מקום אלא בלשון גסות, לפיכך ויוסף עוד בלק:
@788 **כי כבד אכבדך מאד.** יותר ממה שהיית נוטל לשעבר אני נותן לך:
@789 **מלא ביתו כסף וזהב.** למדנו שנפשו רחבה ומחמד ממון אחרים. אמר, ראוי לו לתן לי כל כסף וזהב שלו, שהרי צריך לשכור חילות רבות, ספק נוצח ספק אינו נוצח, ואני ודאי נוצח: **לא אוכל לעבר.** על כרחו גלה שהוא ברשות אחרים, ונתנבא כאן שאינו יכול לבטל הברכות שנתברכו האבות מפי השכינה:
@790 **גם אתם.** פיו הכשילו, גם אתם סופכם לילך בפחי נפש כראשונים: **מה יסף.** לא ישנה דבריו מברכה לקללה הלואי שלא יוסיף לברך, כאן נתנבא שעתיד להוסיף להם ברכות על ידו:
@791 **אם לקרא לך.** אם הקריאה שלך וסבור אתה לטול עליה שכר, קום לך אתם: **ואך.** על כרחך את הדבר אשר אדבר אליך אתו תעשה, ואף על פי כן וילך בלעם, אמר שמא אפתנו ויתרצה:
@792 **ויחבש את אתנו.** מכאן שהשנאה מקלקלת את השורה, שחבש הוא בעצמו. אמר הקדוש ברוך הוא רשע כבר קדמך אברהם אביהם, שנאמר (בראשית כב, ג) וישכם אברהם בבקר ויחבש את חמורו: **עם שרי מואב.** לבו כלבם שוה:
@793 **כי הולך הוא.** ראה שהדבר רע בעיני המקום ונתאוה לילך: **לשטן לו.** מלאך של רחמים היה והיה רוצה למנעו מלחטוא, שלא יחטא ויאבד: **ושני נעריו עמו.** מכאן לאדם חשוב היוצא לדרך יוליך עמו שני אנשים לשמשו וחוזרים ומשמשים זה את זה:
@794 **ותרא האתון.** והוא לא ראה, שנתן הקדוש ברוך הוא רשות לבהמה לראות יותר מן האדם, שמתוך שיש בו דעת תטרף דעתו כשיראה מזיקין: **וחרבו שלופה בידו.** אמר רשע זה הניח כלי אמנותו, שכלי זינן של אמות העולם בחרב, והוא בא עליהם בפיו, שהוא אמנות שלהם, אף אני אתפוש את שלו ואבוא עליו באמנותו. וכן היה סופו (במדבר לא, ח) ואת בלעם בן בעור הרגו בחרב:
@795 **במשעול.** כתרגומו בשביל. וכן (מ''א כ, י) אם ישפק עפר שומרון לשעלים. עפר הנדבק בכפות הרגלים בהלוכן, וכן (ישעיה מ, יב) מי מדד בשעלו מים, ברגליו ובהלוכו: **גדר מזה וגדר מזה.** סתם גדר של אבנים הוא:
@796 **ותלחץ.** היא עצמה: **ותלחץ.** את אחרים, את רגל בלעם:
@797 **ויוסף מלאך ה' עבור.** לעבור עוד לפניו להלוך להיות לפניו במקום אחר, כמו (בראשית לג, ג) והוא עבר לפניהם. ומדרש אגדה יש בתנחומא מה ראה לעמוד בשלשה מקומות, סימני אבות הראהו:
@799 **זה שלש רגלים.** רמז לו אתה מבקש לעקור אמה החוגגת שלש רגלים בשנה:
@800 **התעללת.** כתרגומו לשון גנאי ובזיון: **לו יש חרב בידי.** גנות גדולה היה לו דבר זה בעיני השרים, זה הולך להרוג אמה שלמה בפיו, ולאתון זו צריך לכלי זין:
@801 **ההסכן הסכנתי.** כתרגומו, וכן (איוב כב, ב) הלאל יסכן גבר. ורבותינו דרשו מקרא זה בגמרא אמרו ליה, מאי טעמא לא רכבת אסוסיא. אמר להון ברטיבא שדאי ליה וכו' , כדאיתא במסכת עבודה זרה (ד, ב) :
@803 **כי ירט הדרך לנגדי.** רבותינו חכמי המשנה דרשוהו (שבת קה, א) נוטריקון יראה ראתה, נטתה, בשביל שהדרך לנגדי, כלומר לקנאתי ולהקניטני. ולפי משמעו כי חרד הדרך לנגדי לשון רטט, כי ראיתי בעל הדרך שחרד ומהר הדרך שהוא לכעסי ולהמרותי [ולהמראתי] . ומקרא קצר הוא, כמו (ש''ב יג, לט) ותכל דוד. לישנא אחרינא ירט לשון רצון, וכן (איוב טז) ועל ידי רשעים ירטני, מפייס ומנחם אותי על ידי רשעים, שאינן אלא מקניטים:
@804 **אולי נטתה.** כמו לולא, פעמים שאולי משמש בלשון לולא: **גם אתכה הרגתי.** הרי זה מקרא מסורס, והוא כמו גם הרגתי אותך, כלומר לא העכבה בלבד קראתך על ידי, כי גם ההריגה: **ואותה החייתי.** ועתה מפני שדברה והוכיחתך ולא יכלת לעמוד בתוכחתה, כמו שכתוב (פסוק ל) ויאמר לא. על כן הרגתיה, שלא יאמרו זו היא שסלקה את בלעם בתוכחתה ולא יכול להשיב, שחס המקום על כבוד הבריות, וכן (ויקרא כ, טו. טז) ואת הבהמה תהרגו, וכן (שם) והרגת את האשה ואת הבהמה:
@805 **כי לא ידעתי.** גם זה גנותו, ועל כרחו הודה, שהוא היה משתבח שיודע דעת עליון, ופיו העיד לא ידעתי: **אם רע בעיניך אשובה לי.** להתריס נגד המקום היא תשובה זו. אמר לו הוא בעצמו צוני ללכת, ואתה מלאך מבטל את דבריו, למוד הוא בכך, שאמר דבר ומלאך מחזירו, אמר לאברהם (בראשית כב, ב) קח נא את בנך וגו' , ועל ידי מלאך בטל את דברו, אף אני אם רע בעיניך צריך אני לשוב:
@806 **לך עם האנשים.** בדרך שאדם רוצה לילך בה, מוליכין אותו. **לך עם האנשים.** כי חלקך עמהם וסופך להאבד מן העולם: **ואפס.** על כרחך את הדבר אשר אדבר וגו' : **עם שרי בלק.** שמח לקללם כמותם:
@807 **וישמע בלק.** שלח שלוחים לבשרו: **אל עיר מואב.** אל מטרופולין שלו, עיר החשובה שלו, לומר ראה מה אלו מבקשים לעקור:
@808 **האמנם לא אוכל כבדך.** נתנבא שסופו לצאת מעמו בקלון:
@810 **קרית חצות.** עיר מלאה שוקים אנשים ונשים וטף בחוצותיה, לומר ראה ורחם שלא יעקרו אלו:
@811 **בקר וצאן.** דבר מועט, בקר אחד וצאן אחד בלבד:
@812 **במות בעל.** כתרגומו לרמת דחלתיה, שם עבודה זרה:
@815 **אולי יקרה ה' לקראתי.** אינו רגיל לדבר עמי ביום: **וילך שפי.** כתרגומו יחידי, לשון שופי ושקט, שאין עמו אלא שתיקה:
@816 **ויקר.** לשון עראי, לשון גנאי, לשון טמאת קרי, כלומר בקושי ובבזיון, ולא היה נגלה עליו ביום אלא בשביל להראות חבתן של ישראל: **את שבעת המזבחת.** שבעה מזבחות ערכתי אין כתיב כאן, אלא את שבעת המזבחות, אמר לפניו אבותיהם של אלו בנו לפניך שבעה מזבחות, ואני ערכתי כנגד כלן. אברהם בנה ארבעה (בראשית יב, ז) ויבן שם מזבח לה' הנראה אליו, (שם יב, ח) ויעתק משם ההרה וגו' , (שם יג, יח) ויאהל אברם וגו' ואחד בהר המוריה. ויצחק בנה אחד (שם כו, כה) ויבן שם מזבח וגו' . ויעקב בנה שתים, אחד בשכם ואחד בבית אל: **ואעל פר ואיל במזבח.** ואברהם לא העלה אלא איל אחד:
@819 **ארה לי יעקב ולכה זעמה ישראל.** בשני שמותיהם אמר לו לקללם, שמא אחד מהם אינו מבהק:
@820 **מה אקב לא קבה אל.** כשהיו ראוים להתקלל לא נתקללו, כשהזכיר אביהם את עונם, כי באפם הרגו איש. לא קלל אלא אפם, שנאמר (בראשית מט) ארור אפם. כשנכנס אביהם במרמה אצל אביו היה ראוי להתקלל, מה נאמר שם (שם כז, לג) גם ברוך יהיה. במברכים נאמר (דברים כז, יב) אלה יעמדו לברך את העם. במקללים לא נאמר ואלה יעמדו לקלל את העם, אלא על הקללה, לא רצה להזכיר עליהם שם קללה: **לא זעם ה'.** אני אין כחי אלא שאני יודע לכון השעה שהקדוש ברוך הוא כועס בה, והוא לא כעס כל הימים הללו שבאתי אליך, וזהו שנאמר (מיכה ו, ה) עמי זכר נא מה יעץ וגו' ומה ענה אתו בלעם וגו' למען דעת צדקות ה':
@821 **כי מראש צרים אראנו.** אני מסתכל בראשיתם ובתחלת שרשיהם, ואני רואה אותם מיסדים וחזקים כצורים וגבעות הללו על ידי אבות ואמהות: **הן עם לבדד ישכן.** הוא אשר זכו לו אבותיו לשכון בדד, כתרגומו: **ובגוים לא יתחשב.** כתרגומו, לא יהיו נעשין כלה עם שאר האמות, שנאמר (ירמיה ל, יא) כי אעשה כלה בכל הגוים וגו' אינן נמנין עם השאר. דבר אחר כשהן שמחין אין אמה שמחה עמהם, שנאמר (דברים לב, יב) ה' בדד ינחנו. וכשהאמות בטובה, הם אוכלין עם כל אחד ואחד ואין עולה להם מן החשבון, וזהו, ובגוים לא יתחשב:
@822 **מי מנה עפר יעקב** וגו' **.** כתרגומו, דעדקיא דבית יעקב וכו' מארבע משריתא, מארבע דגלים. דבר אחר עפר יעקב אין חשבון במצות שהם מקימין בעפר (דברים כב, י) לא תחרוש בשור ובחמור, (ויקרא יט, יט) לא תזרע כלאים, אפר פרה, ועפר סוטה וכיוצא בהם: **ומספר את רבע ישראל.** רביעותיהן, זרע היוצא מן התשמיש שלהם: **תמת נפשי מות ישרים.** שבהם:
@825 **וקבנו לי.** לשון צווי, קללהו לי:
@826 **שדה צופים.** מקום גבוה היה ששם הצופה עומד לשמור אם יבא חיל על העיר: **ראש הפסגה.** בלעם לא היה קוסם כבלק, ראה בלק שעתידה פרצה להפרץ בישראל משם ששם מת משה. כסבור ששם תחול עליהם הקללה, וזו היא הפרצה שאני רואה:
@827 **אקרה כה.** מאת הקדוש ברוך הוא: **אקרה.** לשון אתפעל:
@828 **וישם דבר בפיו.** ומה היא השימה הזאת, ומה חסר המקרא באמרו שוב אל בלק וכה תדבר, אלא כשהיה שומע שאינו נרשה לקלל, אמר מה אני חוזר אצל בלק לצערו. ונתן לו הקדוש ברוך הוא רסן וחכה בפיו כאדם הפוקס בהמה בחכה להוליכה אל אשר ירצה. אמר לו על כרחך תשוב אל בלק:
@829 **ושרי מואב אתו.** ולמעלה הוא אומר וכל שרי מואב, כיון שראו שאין בו תקוה הלכו להם מקצתם, ולא נשארו אלא מקצתם: **מה דבר ה'.** לשון צחוק הוא זה, כלומר אינך ברשותך:
@830 **קום בלק.** כיון שראהו מצחק בו, נתכון לצערו עמוד על רגליך, אינך רשאי לישב ואני שלוח אליך בשליחותו של מקום: **בנו צפר.** לשון מקרא הוא זה, כמו (תהלים קד, כ) חיתו יער, (בראשית א, כד) וחיתו ארץ, (תהלים קיד, ח) למעינו מים:
@831 **לא איש אל** וגו' **.** כבר נשבע להם להביאם ולהורישם ארץ שבעה אמות, ואתה סבור להמיתם במדבר: **ההוא אמר** וגו' **.** בלשון תמה, ותרגומו תיבין ומתמלכין, חוזרים ונמלכין לחזור בהם:
@832 **הנה ברך לקחתי.** אתה שואלני מה דבר ה', קבלתי ממנו לברך אותם: **וברך ולא אשיבנה.** הוא ברך אותם ואני לא אשיב את ברכתו: **וברך.** כמו וברך וכן הוא גזרת רי''ש, כמו (תהלים עד, יח) אויב חרף, כמו חרף, וכן (שם י, ג) ובוצע ברך, המהלל ומברך את הגוזל ואומר, אל תירא כי לא תענש, שלום יהיה לך, מרגיז הוא להקדוש ברוך הוא. ואין לומר ברך שם דבר, שאם כן היה נקוד בפתח קטן וטעמו למעלה, אבל לפי שהוא לשון פעל הוא נקוד קמץ, וטעמו למטה:
@833 **לא הביט און ביעקב** וגו' **.** כתרגומו. דבר אחר אחרי פשוטו הוא נדרש מדרש נאה. **לא הביט.** הקדוש ברוך הוא און שביעקב, כשהן עוברין על דבריו אינו מדקדק אחריהם להתבונן באוניות [באון] שלהם ובעמלן שהן עוברין על דתו: **עמל.** לשון עברה, כמו והרה עמל (תהלים ז, טו) , כי אתה עמל וכעס תביט (שם י, יד) לפי שהעברה היא עמל לפני המקום: **ה' אלהיו עמו.** אפלו מכעיסין וממרים לפניו אינו זז מתוכן: **ותרועת מלך בו.** לשון חבה ורעות כמו רעה דוד (שמואל ב' טו, לז) אוהב דוד, ויתנה למרעהו (שופטים טו, ו) וכן תרגם אנקלוס ושכינת מלכהון ביניהון:
@834 **אל מוציאם ממצרים.** אתה אמרת הנה עם יצא ממצרים, לא יצא מעצמו אלא האלהים הוציאם: **כתועפות ראם לו.** כתוקף רום וגובה שלו, וכן וכסף תועפות (איוב כב כה) , לשון מעוז המה, ואומר אני שהוא לשון ועוף יעופף (בראשית א כ) , המעופף ברום וגובה ותקף רב הוא זה ותועפות ראם עפיפת גובה. דבר אחר, **תועפות ראם.** תקף ראמים, ואמרו רבותינו אלו השדים:
@835 **כי לא נחש ביעקב.** כי ראוים הם לברכה שאין בהם מנחשים וקוסמים: **כעת יאמר ליעקב** וגו' **.** עוד עתיד להיות עת כעת הזאת אשר תגלה חבתן לעין כל שהן יושבין לפניו ולומדים תורה מפיו ומחצתן לפנים ממלאכי השרת, והם ישאלו להם מה פעל אל, וזהו שנאמר והיו עיניך רואות את מוריך (ישעיה ל, כ) . דבר אחר יאמר ליעקב אינו לשון עתיד, אלא לשון הוה, אינן צריכין למנחש וקוסם כי בכל עת שצריך להאמר ליעקב ולישראל מה פעל הקדוש ברוך הוא ומה גזרותיו במרום, אינן מנחשים וקוסמים אלא נאמר להם על פי נביאיהם מה היא גזרת המקום, או אורים ותמים מגידים להם, ואונקלוס לא תרגם כן:
@836 **הן עם כלביא יקום** וגו' **.** כשהן עומדים משנתם שחרית, הן מתגברין כלביא וכארי לחטוף את המצות, ללבוש טלית לקרא את שמע ולהניח תפלין: **לא ישכב.** בלילה על מטתו עד שהוא אוכל ומחבל כל מזיק הבא לטרפו. כיצד, קורא את שמע על מטתו ומפקיד רוחו ביד המקום, בא מחנה וגיס להזיקם, הקדוש ברוך הוא שומרם ונלחם מלחמותם ומפילם חללים. דבר אחר הן עם כלביא יקום וגו' . כתרגומו: **ודם חללים ישתה.** נתנבא שאין משה מת עד שיפיל מלכי מדין חללים ויהרג הוא עמהם, שנאמר (יהושע יג, כב) ואת בלעם בן בעור הקוסם הרגו בני ישראל בחרב אל חלליהם:
@837 **גם קב לא תקבנו.** גם ראשון מוסיף על גם השני, וגם השני על גם ראשון, וכן גם לי גם לך לא יהיה (מלכים א' ג, כו) , וכן גם בחור גם בתולה (דברים לב, כה) :
@839 **וקבותו לי.** אין זה לשון צווי, כמו וקבנו, אלא לשון עתיד, אולי יישר בעיניו ותקבנו לי משם, מלדי''רש מי''י בלע''ז [תקלל אותו] :
@840 **ראש הפעור.** קוסם היה בלק וראה שהן עתידין ללקות על ידי פעור ולא היה יודע במה, אמר שמא הקללה תחול עליהם משם, וכן כל החוזים בכוכבים רואים ואינם יודעים מה רואים:
@843 **וירא בלעם כי טוב** וגו' **.** אמר איני צריך לבדוק בהקדוש ברוך הוא כי לא יחפוץ לקללם: **ולא הלך כפעם בפעם.** כאשר עשה שתי פעמים: **לקראת נחשים.** לנחש אולי יקרה ה' לקראתו כרצונו, אמר רוצה ואינו רוצה לקללם, אזכיר עונותיהם, והקללה על הזכרת העברה תחול: **וישת אל המדבר פניו.** כתרגומו:
@844 **וישא בלעם את עיניו.** בקש להכניס בהם עין רעה, והרי יש לך שלש מדותיו עין רעה ורוח גבוהה ונפש רחבה האמורים למעלה: **שוכן לשבטיו.** ראה כל שבט ושבט שוכן לעצמו ואינן מעורבין, ראה שאין פתחיהם מכונין זה כנגד זה, שלא יציץ לתוך אהל חברו: **ותהי עליו רוח אלהים.** עלה בלבו שלא יקללם:
@845 **בנו בער.** כמו למעינו מים (תהלים קיד, ח) . ומדרש אגדה שניהם היו גדולים מאבותיהם, בלק בנו צפור, אביו בנו הוא במלכות, ובלעם גדול מאביו בנביאות, מנה בן פרס היה: **שתם העין.** עינו נקורה ומוצאת לחוץ וחור שלה נראה פתוח, ולשון משנה הוא כדי שישתום ויסתום ויגוב (ע''ז סט.) ורבותינו אמרו לפי שאמר ומספר את רבע ישראל, שהקדוש ברוך הוא יושב ומונה רביעיותיהן של ישראל מתי תבא טפה שנלד הצדיק ממנה, אמר בלבו מי שהוא קדוש ומשרתיו קדושים יסתכל בדברים הללו, ועל דבר זה נסמת עינו של בלעם. ויש מפרשים שתום העין פתוח העין, כמו שתרגם אנקלוס, ועל שאמר שתום העין, ולא אמר שתום העינים, למדנו שסומא באחת מעיניו היה:
@846 **נפל וגלוי עינים.** פשוטו כתרגומו, שאין נראה עליו אלא בלילה כשהוא שוכב. ומדרשו כשהיה נגלה עליו לא היה בו כח לעמוד על רגליו ונופל על פניו, לפי שהיה ערל ומאוס להיות נגלה עליו בקומה זקופה לפניו:
@847 **מה טבו אהליך.** על שראה פתחיהם שאינן מכונין זה מול זה: **משכנתיך.** חניותיך, כתרגומו. דבר אחר מה טבו אהליך. מה טבו אהל שילה ובית עולמים בישובן שמקריבין בהן קרבנות לכפר עליהם: **משכנתיך.** אף כשהן חרבין, לפי שהן משכון עליכם, וחרבנן כפרה על הנפשות, שנאמר כלה ה' את חמתו (איכה ד) , ובמה כלה, ויצת אש בציון:
@848 **כנחלים נטיו.** שנארכו ונמשכו לנטות למרחוק, אמרו רבותינו מברכותיו של אותו רשע אנו למדים מה היה בלבו לקללם כשאמר (פסוק א) וישת אל המדבר פניו, וכשהפך המקום את פיו ברכם מעין אותן קללות שבקש לומר כו', כדאיתא בחלק (סנהדרין קה, א) : **כאהלים.** כתרגומו, לשון מור ואהלות (תהלים מה, ט) : **נטע ה'.** בגן עדן. לשון אחר כאהלים נטע ה', כשמים המתוחין כאהל: **נטע ה'.** לשון נטיעה מצינו באהלים, שנאמר ויטע אהלי אפדנו (דניאל יא, מה) :
@849 **מדליו.** מבארותיו. ופירושו כתרגומו: **וזרעו במים רבים.** לשון הצלחה הוא זה, כזרע הזרוע על פני המים: **וירם מאגג מלכו.** מלך ראשון שלהם יכבוש את אגג מלך עמלק: **ותנשא מלכותו.** של יעקב יותר ויותר, שיבא אחריו דוד ושלמה:
@850 **אל מוציאו ממצרים.** מי גורם להם הגדלה הזאת, אל המוציאם ממצרים, בתוקף ורום שלו יאכל את הגוים שהם צריו: **ועצמותיהם.** של צרים: **יגרם.** מנחם פתר בו לשון שבירה, וכן (צפניה ג, ג) לא גרמו לבקר, וכן (יחזקאל כג, לד) את חרשיה תגרמי, ואני אומר לשון עצם הוא שמגרר הבשר בשניו מסביב והמוח שבפנים, ומעמיד העצם על ערמימותה: **וחציו ימחץ.** אנקלוס תרגם חציו של צרים, חלוקה שלהם כמו (בראשית מט, כג) בעלי חצים, מרי פלוגתא, וכן ימחץ, לשון (שופטים ה, כו) ומחצה וחלפה רקתו, שיחצו את ארצם. ויש לפתור לשון חצים ממש, חציו של הקדוש ברוך הוא ימחץ בדמם של צרים, יטבול ויצטבע בדמם, כמו (תהלים סח, כד) למען תמחץ רגלך בדם. ואינו זז מלשון מכה, כמו מחצתי, שהצבוע בדם נראה כאלו מחוץ ונגוע:
@851 **כרע שכב כארי.** כתרגומו, יתישבו בארצם בכח וגבורה:
@852 **ויספק.** הכה זו על זו:
@855 **לעבר את פי ה'.** כאן לא נאמר אלהי, כמו שנאמר בראשונה, לפי שידע שנבאש בהקדוש ברוך הוא ונטרד:
@856 **הולך לעמי.** מעתה הריני כשאר עמי, שנסתלק הקדוש ברוך הוא מעליו: **לכה איעצך.** מה לך לעשות. ומה היא העצה, אלהיהם של אלו שונא זמה הוא כו' , כדאיתא בחלק (סנהדרין קו.) תדע שבלעם השיא עצה זו להכשילם בזמה, שהרי נאמר הן הנה היו לבני ישראל בדבר בלעם (לקמן לא, טז) : **אשר יעשה העם הזה לעמך.** מקרא קצר הוא זה, איעצך להכשילם, ואומר לך מה שהן עתידין להרע למואב באחרית הימים:
@858 **וידע דעת עליון.** לכון השעה שכועס בה:
@859 **אראנו.** רואה אני שבחו של יעקב וגדלתן, אך לא עתה היא, אלא לאחר זמן: **דרך כוכב.** כתרגומו, לשון דרך קשתו (איכה ב, ד) , שהכוכב עובר כחץ, ובלע''ז דישטנ''ט [מזנק] כלומר יקום מזל: **וקם שבט.** מלך רודה ומושל: **ומחץ פאתי מואב.** זה דוד, שנאמר בו השכב אותם ארצה וימדד שני חבלים להמית וגו' (שמואל ב' ח, ב) : **וקרקר.** לשון קורה כמו אני קרתי (מלכים ב' יט, כד) מקבת בור נקרתם (ישעיה נא, א) יקרוה עורבי נחל (משלי ל, יז) פורי''יר בלע''ז [לנקב] : **כל בני שת.** כל האמות, שכלם יצאו מן שת בנו של אדם הראשון:
@860 **והיה ירשה שעיר איביו.** ישראל:
@861 **וירד מיעקב.** ועוד יהיה מושל אחר מיעקב: **והאביד שריד מעיר.** מעיר החשובה של אדום והיא רומי, ועל מלך המשיח אומר כן, שנאמר בו וירד מים עד ים (תה' עב) ולא יהיה שריד לבית עשו (עוב' א) :
@862 **וירא את עמלק.** נסתכל בפרענותו של עמלק: **ראשית גוים עמלק.** הוא קדם את כלם להלחם בישראל, וכך תרגם אנקלוס ואחריתו לאבד בידם, שנאמר תמחה את זכר עמלק (דברים כה, יט) :
@863 **וירא את הקיני.** לפי שהיה קיני תקוע אצל עמלק, כענין שנאמר ויאמר שאול אל הקיני וגו' (שמואל א' טו, ו) הזכירו אחר עמלק, נסתכל בגדלתן של בני יתרו שנאמר בהם תרעתים שמעתים שוכתים (דברי הימים א' ב, נה) : **איתן מושבך.** תמה אני מהיכן זכית לכך הלא אתה עמי היית בעצת הבה נתחכמה לו (שמות א, י) , ועתה נתישבת באיתן ומעוז של ישראל:
@864 **כי אם יהיה לבער קין** וגו' **.** אשרך שנתקעת לתוקף זה שאינך נטרד עוד מן העולם, כי אף אם אתה עתיד לגלות עם עשרת השבטים ותהיה לבער ממקום שנתישבת שם, מה בכך: **עד מה אשור תשבך.** עד היכן הוא מגלה אותך, שמא ללחלח וחבור, אין זה טרוד מן העולם, אלא טלטול ממקום למקום ותשוב עם שאר הגליות:
@865 **וישא משלו** וגו' **.** כיון שהזכיר את שבית אשור אמר, **אוי מי יחיה משמו אל.** מי יכול להחיות את עצמו משמו את אלה שלא ישים עליו הגוזר את אלה, שיעמוד סנחריב ויבלבל את כל האמות, ועוד יבואו:
@866 **וצים מיד כתים.** ויעברו כתיים שהן רומיים בבירניות גדולות על אשור: **וענו עבר.** וענו אותם שבעבר הנהר: **וגם הוא עדי אבד.** וכן פרש דניאל עד די קטילת חיותא והובד גשמה (דניאל ז, יא) : **וצים.** ספינות גדולות, כדכתיב וצי אדיר (ישעיה לג, כא) תרגומו ובורני רבתא:
@868 **בשטים.** כך שמה: **לזנות אל בנות מואב.** על ידי עצת בלעם כדאיתא בחלק:
@869 **וישתחוו לאלהיהן.** כשתקף יצרו עליו ואמר לה השמעי לי, והיא מוציאה לו דמות פעור מחיקה ואומרת לו השתחוה לזה:
@870 **פעור.** על שם שפוערין לפניו פי הטבעת ומוציאין רעי, וזו היא עבודתו: **ויחר אף ה' בישראל.** שלח בהם מגפה:
@871 **קח את כל ראשי העם.** לשפוט את העובדים לפעור: **והוקע אותם.** את העובדים: **והוקע.** היא תליה, כמו שמצינו בבני שאול והוקענום לה' (שמואל ב' כא, ו) ושם תליה מפורשת בעבודה זרה בסקילה, וכל הנסקלין נתלין: **נגד השמש.** לעין כל. ומדרש אגדה השמש מודיע את החוטאים, הענן נקפל מכנגדו והחמה זורחת עליו:
@872 **הרגו איש אנשיו.** כל אחד ואחד מדיני ישראל היה הורג שנים, ודיני ישראל שמונת רבוא ושמונת אלפים, כדאיתא בסנהדרין (יח.) :
@873 **והנה איש מבני ישראל בא.** נתקבצו שבטו של שמעון אצל זמרי שהיה נשיא שלהם, אמרו לו אנו נדונין במיתה ואתה יושב וכו' , כדאיתא באלו הן הנשרפין (סנהדרין דף פב, א) : **את המדינית.** כזבי בת צור: **לעיני משה.** אמרו לו משה, זו אסורה או מתרת, אם תאמר אסורה, בת יתרו מי התירה לך וכו' , כדאיתא התם: **והמה בוכים.** נתעלמה ממנו הלכה כל הבועל ארמית קנאים פוגעים בו געו כלם בבכיה. בעגל עמד משה כנגד ששים רבוא, שנאמר (שמות לב, כ) ויטחן עד אשר דק וגו' וכאן רפו ידיו, אלא כדי שיבא פנחס ויטול את הראוי לו:
@874 **וירא פנחס.** ראה מעשה ונזכר הלכה, אמר לו למשה מקבלני ממך הבועל ארמית קנאין פוגעין בו, אמר לו קריינא דאגרתא איהו ליהוי פרוונקא, מיד ויקח רמח בידו וגו' :
@875 **אל הקבה.** אל האהל: **אל קבתה.** [אל הקבה] כמו הלחיים והקיבה כון בתוך זכרות של זמרי ונקבות שלה, וראו כלם שלא לחנם הרגם, והרבה נסים נעשו לו כו', כדאיתא התם (סנהד' פב:) :
@878 **פנחס בן אלעזר בן אהרן הכהן.** לפי שהיו השבטים מבזים אותו, הראיתם בן פוטי זה שפטם אבי אמו עגלים לעבודה זרה והרג נשיא שבט מישראל, לפיכך בא הכתוב ויחסו אחר אהרן: **בקנאו את קנאתי.** בנקמו את נקמתי, בקצפו את הקצף שהיה לי לקצוף. כל לשון קנאה הוא המתחרה לנקום נקמת דבר, אנפרימנ''ט בלע''ז :
@879 **את בריתי שלום.** שתהא לו לברית שלום, כאדם המחזיק טובה וחנות למי שעשה עמו טובה, אף כאן פרש לו הקדוש ברוך הוא שלומותיו:
@880 **והיתה לו.** בריתי זאת: **ברית כהנת עולם.** שאף על פי שכבר נתנה כהנה לזרעו של אהרן, לא נתנה אלא לאהרן ולבניו, שנמשחו עמו ולתולדותיהם שיולידו אחר המשחתן, אבל פנחס שנלד קודם לכן ולא נמשח, לא בא לכלל כהנה עד כאן. וכן שנינו בזבחים (קא, ב) לא נתכהן פנחס עד שהרגו לזמרי: **לאלהיו.** בשביל אלהיו, כמו (במד' יא) המקנא אתה לי, (זכר' ח) קנאתי לציון, בשביל ציון:
@881 **ושם איש ישראל** וגו' **.** במקום שייחס את הצדיק לשבח יחס את הרשע לגנאי: **נשיא בית אב לשמעני.** לאחד מחמשת בתי אבות שהיו לשבט שמעון. דבר אחר להודיע שבחו של פנחס, שאף על פי שזה היה נשיא, לא מנע את עצמו מלקנא לחלול השם, לכך הודיעך הכתוב מי הואהמכה:
@882 **ושם האשה המכה** וגו' **.** להודיעך שנאתם של מדינים שהפקירו בת מלך לזנות, כדי להחטיא את ישראל: **ראש אמות.** אחד מחמשת (במד' לא) מלכי מדין את אוי ואת רקם ואת צור וגו' , והוא היה חשוב מכלם, שנאמר ראש אמות, ולפי שנהג בזיון בעצמו להפקיר בתו מנאו שלישי: **בית אב.** חמשה בתי אבות היו למדין עיפה ועפר וחנוך ואבידע ואלדעה, וזה היה מלך לאחד מהם:
@884 **צרור.** כמו זכור, שמור, לשון הוה. עליכם לאייב אותם:
@885 **כי צוררים הם לכם** וגו' **על דבר פעור.** שהפקירו בנותיהם לזנות, כדי להטעותכם אחר פעור. ואת מואב לא צוה להשמיד, מפני רות שהיתה עתידה לצאת מהם, כדאמרינן בבבא קמא (לח, ב) :
@887 **ויהי אחרי המגפה** וגו' **.** משל לרועה שנכנסו זאבים לתוך עדרו והרגו בהן והוא מונה אותן לידע מנין הנותרות. דבר אחר כשיצאו ממצרים ונמסרו למשה, נמסר לו במנין, עכשו שקרב למות ולהחזיר צאנו, מחזירם במנין:
@888 **לבית אבתם.** על שבט האב יתיחסו, ולא אחר האם:
@889 **וידבר משה ואלעזר הכהן אתם.** דברו עמם על זאת שצוה המקום למנותם: **לאמר.** אמרו להם צריכים אתם להמנות:
@890 **מבן עשרים שנה ומעלה כאשר צוה** וגו' **.** שיהא מנינם מבן עשרים שנה ומעלה, שנאמר (שמות ל, יג) כל העבר על הפקדים וגו' :
@891 **משפחת החנכי.** לפי שהיו האמות מבזין אותם ואומרים מה אלו מתיחסין על שבטיהם, סבורין הם שלא שלטו המצריים באמותיהם, אם בגופם היו מושלים קל וחומר בנשותיהם, לפיכך הטיל הקדוש ברוך הוא שמו עליהם, ה''א מצד זה ויו''ד מצד זה, לומר, מעיד אני עליהם שהם בני אבותיהם. וזהו הוא שמפורש על ידי דוד (תהלים קכב, ד) שבטי יה עדות לישראל. השם הזה מעיד עליהם לשבטיהם, לפיכך בכלם כתיב החנכי הפלאי, אבל בימנה לא הצרך לומר משפחת הימני, לפי שהשם קבוע בו יו''ד בראש וה''א בסוף:
@895 **אשר הצו.** את ישראל על משה: **בהצתם.** את העם על ה': **הצו.** השיאו את ישראל לריב על משה, לשון הפעילו:
@896 **ויהיו לנס.** לאות ולזכרון (במדבר יז, ה) למען אשר לא יקרב איש זר, לחלוק עוד על הכהנה:
@897 **ובני קרח לא מתו.** הם היו בעצה תחלה, ובשעת המחלוקת הרהרו תשובה בלבם, לפיכך נתבצר להם מקום גבוה בגיהנם וישבו שם:
@899 **לזרח.** הוא צוחר, לשון צוהר. אבל משפחת אהד בטלה, וכן חמשה משבט בנימין, שהרי בעשרה בנים ירד למצרים וכאן לא מנה אלא חמשה, וכן אצבון לגד, הרי שבע משפחות. ומצאתי בגמרא ירושלמית, שכשמת אהרן נסתלקו ענני כבוד ובאו הכנענים להלחם בישראל ונתנו לב לחזור למצרים וחזרו לאחוריהם שמנה מסעות מהר ההר למוסרה, שנאמר (דברים י, ו) ובני ישראל נסעו מבארות בני יעקן מוסרה שם מת אהרן, והלא בהר ההר מת, וממוסרה עד הר ההר שמונה מסעות יש למפרע, אלא שחזרו לאחוריהם ורדפו בני לוי אחריהם להחזירם, והרגו מהם שבע משפחות, ומבני לוי נפלו ארבע משפחות משפחת שמעי ועזיאלי, ומבני יצהר לא נמנו כאן אלא משפחת הקרחי, והרביעית לא ידעתי מה היא. ורבי תנחומא דרש שמתו במגפה בדבר בלעם, אבל לפי החסרון שחסר משבט שמעון במנין זה ממנין הראשון שבמדבר סיני, נראה שכל עשרים וארבעה אלף נפלו משבטו של שמעון:
@902 **לאזני.** אומר אני שזו משפחת אצבון, ואיני יודע למה לא נקראת משפחתו על שמו:
@910 **לישוב.** הוא יוב האמור ביורדי מצרים, כי כל המשפחות נקראו על שם יורדי מצרים. והנלדין משם והלאה לא נקראו המשפחות על שמם, חוץ ממשפחות אפרים ומנשה שנלדו כלם במצרים, וארד ונעמן בני בלע בן בנימין. ומצאתי ביסודו של רבי משה הדרשן שירדה אמן למצרים כשהיתה מעברת מהם, לכך נחלקו למשפחות, כחצרון וחמול, שהיו בני בנים ליהודה, וחבר ומלכיאל שהיו בני בנים של אשר. ואם אגדה היא הרי טוב, ואם לאו, אומר אני, שהיו לבלע בני בנים הרבה, ומשנים הללו ארד ונעמן יצאה מכל אחד משפחה רבה ונקראו תולדות שאר הבנים על שם בלע, ותולדות השנים הללו נקראו על שמם. וכן אני אומר בבני מכיר, שנחלקו לשתי משפחות, אחת נקראת על שמו ואחת נקראת על שם גלעד בנו. חמש משפחות חסרו מבניו של בנימין, כאן נתקימה מקצת נבואת אמו שקראתו בן אוני, בן אנינותי ובפלגש בגבעה נתקימה כלה. זו מצאתי ביסודו של ר' משה הדרשן:
@922 **ואלה בני שותלח** וגו' **.** שאר בני שותלח נקראו תולדותיהם על שם שותלח. ומערן יצאה משפחה רבה ונקראת על שמו. ונחשבו בני שותלח לשתי משפחות. צא וחשוב ותמצא בפרשה זו חמשים ושבע משפחות, ומבני לוי שמונה, הרי ששים וחמש, וזהו שנאמר (דברים ז, ז) כי אתם המעט וגו' , ה''א מעט, חמשה אתם חסרים ממשפחות כל העמים, שהן שבעים, אף זה הבנתי מיסודו של ר' משה הדרשן. אך הצרכתי לפחות ולהוסיף בדבריו:
@924 **לאחירם.** הוא אחי שירד למצרים, ולפי שנקרא על שם יוסף שהיה אחיו ורם ממנו נקרא אחירם:
@925 **לשפופם.** הוא מפים, על שהיה יוסף שפוף בין האמות:
@928 **לשוחם.** הוא חשים:
@932 **ושם בת אשר שרח.** לפי שהיתה קימת בחיים מנאה כאן:
@939 **לאלה תחלק הארץ.** ולא לפחותים מבן עשרים, אף על פי שבאו לכלל עשרים בטרם חלוק הארץ, שהרי שבע שנים כבשו ושבע חלקו, לא נטלו חלק בארץ אלא אלו שש מאות אלף ואלף, ואם היה לאחד מהם ששה בנים, לא נטלו אלא חלק אביהם לבדו:
@940 **לרב תרבה נחלתו.** לשבט שהיה מרבה באכלוסין נתנו חלק רב, ואף על פי שלא היו החלקים שוים, שהרי הכל לפי רבוי השבט חלקו החלקים, לא עשו אלא על ידי גורל, והגורל היה על פי רוח הקדש, כמו שמפורש בבבא בתרא (קכב, א) אלעזר הכהן היה מלבש באורים ותמים, ואומר ברוח הקדש אם שבט פלוני עולה, תחום פלוני עולה עמו. והשבטים היו כתובים בשנים עשר פתקין, ושנים עשר גבולים בשנים עשר פתקין, ובללום בקלפי והנשיא מכניס ידו לתוכה ונוטל שני פתקין, עולה בידו פתק של שם שבטו, ופתק של גבול המפורש לו, והגורל עצמו היה צווח ואומר אני הגורל עליתי לגבול פלוני, לשבט פלוני, שנאמר על פי הגורל, ולא נתחלקה הארץ במדה, לפי שיש גבול משבח מחברו, אלא בשומא, בית כור רע כנגד בית סאה טוב, הכל לפי הדמים:
@941 **לשמות מטות אבתם.** אלו יוצאי מצרים. שנה הכתוב נחלה זו מכל הנחלות שבתורה, שכל הנחלות החיים יורשים את המתים וכאן מתים יורשים את החיים. כיצד, שני אחים מיוצאי מצרים, שהיו להם בנים בבאי הארץ, לזה אחד ולזה שלשה, האחד נטל חלק אחד, והשלשה נטלו שלשה, שנאמר לאלה תחלק הארץ, חזרה נחלתן אצל אבי אביהן וחלקו הכל בשוה. וזהו שנאמר לשמות מטות אבתם ינחלו. שאחר שנטלו הבנים חלקוה לפי האבות שיצאו ממצרים, ואלו מתחלה חלקוה למנין יוצאי מצרים לא היו נוטלין אלו הארבעה, אלא שני חלקים, עכשו נטלו ארבעה חלקים: **אך בגורל.** יצאו יהושע וכלב, וכן הוא אומר (שופ' א) ויתנו לכלב את חברון כאשר דבר משה, ואומר (יהושע יט) על פי ה' נתנו לו את העיר אשר שאל: **מטות אבתם.** יצאו גרים ועבדים:
@942 **על פי הגורל.** הגורל היה מדבר, כמו שפרשתי, מגיד שנתחלקה ברוח הקדש, לכך נאמר על פי ה':
@944 **אלה משפחת לוי.** חסר כאן משפחות השמעי והעזיאלי וקצת מן היצהרי:
@945 **אשר ילדה אתה ללוי במצרים.** לידתה במצרים ואין הורתה במצרים. כשנכנסו לתוך החומה ילדתה, והיא השלימה מנין שבעים, שהרי בפרטן אי אתה מוצא אלא ששים ותשע:
@948 **כי לא התפקדו בתוך בני ישראל.** להיות נמנין בני עשרים שנה, ומה טעם: **כי לא נתן להם נחלה.** והנמנין מבן עשרים שנה היו בני נחלה, שנאמר איש לפי פקדיו יתן נחלתו:
@950 **ובאלה לא היה איש** וגו' **.** אבל על הנשים לא נגזרה גזרת המרגלים, לפי שהן היו מחבבות את הארץ. האנשים אומרים (במדבר יד, ד) נתנה ראש ונשובה מצרימה, והנשים אומרות (במד' כז) תנה לנו אחזה. לכך נסמכה פרשת בנות צלפחד לכאן:
@952 **למשפחת מנשה בן יוסף.** למה נאמר, והלא כבר נאמר בן מנשה, אלא לומר לך יוסף חבב את הארץ, שנאמר (בראשית נ, כה) והעליתם את עצמתי וגו' , ובנותיו חבבו את הארץ, שנאמר (במדבר כז, ד) תנה לנו אחזה. וללמדך שהיו כלם צדיקים, שכל מי שמעשיו ומעשה אבותיו סתומים ופרט לך הכתוב באחד מהם ליחסו לשבח, הרי זה צדיק בן צדיק. ואם יחסו לגנאי כגון (מלכים ב' כה, כה) בא ישמעאל בן נתניה בן אלישמע, בידוע שכל הנזכרים עמו רשעים היו: **מחלה נעה** וגו' **.** ולהלן הוא אומר (במדבר לו, יא) ותהיינה מחלה תרצה, מגיד שכלן שקולות זו כזו, לפיכך שנה את סדרן:
@953 **לפני משה ולפני אלעזר.** מגיד שלא עמדו לפניהם אלא בשנת הארבעים, אחר שמת אהרן: **לפני משה.** ואחר כך לפני אלעזר, אפשר אם משה לא ידע אלעזר יודע, אלא סרס המקרא ודרשהו, דברי רבי יאשיה. אבא חנן משום רבי אלעזר אומר בבית המדרש היו יושבים, ועמדו לפני כלם:
@954 **והוא לא היה** וגו' **.** לפי שהיו באות לומר בחטאו מת, נזקקו לומר לא בחטא מתלוננים ולא בעדת קרח שהצו על הקדוש ברוך הוא, אלא בחטאו לבדו מת, ולא החטיא את אחרים עמו. ר' עקיבא אומר מקושש עצים היה. ור' שמעון אומר מן המעפילים היה:
@955 **למה יגרע שם אבינו.** אנו במקום בן עומדות, ואם אין הנקבות חשובות זרע, תתיבם אמנו ליבם: **כי אין לו בן.** הא אם היה לו בן לא היו תובעות כלום. מגיד שחכמניות היו:
@956 **ויקרב משה את משפטן.** נתעלמה הלכה ממנו וכאן נפרע על שנטל עטרה לומר (דברים א, יז) והדבר אשר יקשה מכם תקרבון אלי. דבר אחר ראויה היתה פרשה זו להכתב על ידי משה, אלא שזכו בנות צלפחד ונכתבה על ידן:
@958 **כן בנות צלפחד דברת.** כתרגומו יאות, כך כתובה פרשה זו לפני במרום, מגיד שראתה עינן מה שלא ראתה עינו של משה: **כן בנות צלפחד דברת.** יפה תבעו. אשרי אדם שהקדוש ברוך הוא מודה לדבריו: **נתן תתן.** שני חלקים, חלק אביהן, שהיה מיוצאי מצרים, וחלקו עם אחיו בנכסי חפר: **והעברת.** לשון עברה הוא במי שאינו מניח בן לירשו. דבר אחר על שם שהבת מעברת נחלה משבט לשבט שבנה ובעלה יורשין אותה. שלא תסוב נחלה לא נצטוה אלא לאותו הדור בלבד וכן והעברתם את נחלתו לבתו, בכלן הוא אומר ונתתם, ובבת הוא אומר והעברתם:
@962 **לשארו הקרב אליו ממשפחתו.** ואין משפחה קרויה אלא משפחת האב:
@963 **עלה אל הר העברים.** למה נסמכה לכאן, כיון שאמר הקדוש ברוך הוא נתן תתן להם, אמר אותי צוה המקום להנחיל, שמא התרה הגזרה ואכנס לארץ. אמר לו הקדוש ברוך הוא גזרתי במקומה עומדת. דבר אחר כיון שנכנס משה לנחלת בני גד ובני ראובן שמח ואמר כמדמה שהתר לי נדרי, משל למלך שגזר על בנו שלא יכנס לפתח פלטין שלו, נכנס לשער והוא אחריו, לחצר והוא אחריו, לטרקלין והוא אחריו, כיון שבא לכנס לקיטון, אמר לו בני מכאן ואלך אתה אסור לכנס:
@964 **כאשר נאסף אהרן אחיך.** מכאן שנתאוה משה למיתתו של אהרן. דבר אחר אין אתה טוב ממנו, (דברים לב, נא) על אשר לא קדשתם, הא אם קדשתם אותי עדין לא הגיע זמנכם להפטר. בכל מקום שכתב מיתתם כתב סרחונם, לפי שנגזרה גזרה על דור המדבר למות במדבר בעון שלא האמינו, לכך בקש משה שיכתב סרחונו, שלא יאמרו אף הוא מן הממרים היה. משל לשתי נשים שלוקות בבית דין אחת קלקלה ואחת אכלה פגי שביעית וכו' , אף כאן בכל מקום שהזכיר מיתתן הזכיר סרחונם, להודיע שלא היתה בהם אלא זו בלבד:
@965 **הם מי מריבת קדש.** הם לבדם אין בהם עון אחר. דבר אחר הם שהמרו במרה, הם היו שהמרו בים סוף, הם עצמם שהמרו במדבר צין:
@966 **וידבר משה אל ה'** וגו' **.** להודיע שבחן של צדיקים שכשנפטרין מן העולם מניחין צרכן ועוסקין בצרכי צבור: **לאמר.** אמר לו השיבני אם אתה ממנה להם פרנס אם לאו:
@967 **יפקד ה'.** כיון ששמע משה שאמר לו המקום תן נחלת צלפחד לבנותיו אמר הגיע שעה שאתבע צרכי שיירשו בני את גדלתי. אמר לו הקדוש ברוך הוא לא כך עלתה במחשבה לפני, כדאי הוא יהושע לטול שכר שמושו שלא מש מתוך האהל. וזהו שאמר שלמה (משלי כז, יח) נצר תאנה יאכל פריה: **אלהי הרוחת.** למה נאמר, אמר לפניו: רבונו של עולם, גלוי וידוע לפניך דעתו של כל אחד ואחד ואינן דומין זה לזה, מנה עליהם מנהיג שיהא סובל כל אחד ואחד לפי דעתו:
@968 **אשר יצא לפניהם.** לא כדרך מלכי האמות שיושבים בבתיהם ומשלחין את חילותיהם למלחמה, אלא כמו שעשיתי אני שנלחמתי בסיחון ועוג, שנאמר אל תירא אתו. (במדבר כא, לד) וכדרך שעשה יהושע, שנאמר (יהושע ה, יג) וילך יהושע אליו ויאמר לו הלנו אתה וגו' . וכן בדוד הוא אומר (ש''א יח, טז) כי הוא יוצא ובא לפניהם, יוצא בראש ונכנס בראש: **ואשר יוציאם.** בזכיותיו: **ואשר יביאם.** בזכיותיו. דבר אחר ואשר יביאם שלא תעשה לו כדרך שאתה עושה לי, שאיני מכניסן לארץ:
@969 **קח לך.** קחנו בדברים אשריך שזכית להנהיג בניו של מקום: **לך.** את שבדוק לך את זה אתה מכיר: **אשר רוח בו.** כאשר שאלת שיוכל להלוך כנגד רוחו של כל אחד ואחד: **וסמכת את ידך עליו.** תן לו מתרגמן שידרוש בחייך, שלא יאמרו עליו, לא היה לו להרים ראש בימי משה:
@970 **וצויתה אתו.** על ישראל, דע שטרחנין הם סרבנים הם, על מנת שתקבל עליך:
@971 **ונתתה מהודך עליו.** זה קרון עור פנים: **מהודך.** ולא כל הודך נמצינו למדין פני משה כחמה פני יהושע כלבנה: **למען ישמעו כל עדת בני ישראל.** שיהיו נוהגין בו כבוד ויראה כדרך שנוהגין בך:
@972 **ולפני אלעזר הכהן יעמד.** הרי שאלתך ששאלת שאין הכבוד הזה זז מבית אביך, שאף יהושע יהא צריך לאלעזר: **ושאל לו.** כשיצטרך לצאת למלחמה: **על פיו.** של אלעזר: **וכל העדה.** סנהדרין:
@973 **ויקח את יהושע.** לקחו בדברים והודיעו מתן שכר פרנסי ישראל לעולם הבא:
@974 **ויסמך את ידיו עליו.** בעין יפה יותר ויותר ממה שנצטוה. שהקדוש ברוך הוא אמר לו וסמכת את ידך, והוא עשה בשתי ידיו, ועשאו ככלי מלא וגדוש ומלאו חכמתו בעין יפה: **כאשר דבר ה'.** אף לענין ההוד נתן מהודו עליו:
@976 **צו את בני ישראל.** מה אמור למעלה (כז, טז) יפקד ה'. אמר לו הקדוש ברוך הוא עד שאתה מצוני על בני, צוה את בני עלי. משל לבת מלך שהיתה נפטרת מן העולם והיתה מפקדת לבעלה על בניה וכו' , כדאיתא בספרי: **קרבני.** זה הדם: **לחמי.** אלו אמורין, וכן הוא אומר (ויקרא ג, טז) והקטירם הכהן המזבחה לחם אשה: **לאשי.** הנתנין לאשי מזבחי: **תשמרו.** שיהיו כהנים ולוים וישראלים עומדין על גביו מכאן למדו ותקנו מעמדות: **במועדו.** בכל יום הוא מועד התמידים:
@977 **ואמרת להם.** אזהרה לבית דין: **שנים ליום.** כפשוטו ועיקרו בא ללמד שיהיו נשחטין כנגד היום, תמיד של שחר במערב ושלבין הערבים במזרחן של טבעות:
@978 **את הכבש אחד.** אף על פי שכבר נאמר בפרשת ואתה תצוה, וזה אשר תעשה וגו' (שמות כט, לח) , היא היתה אזהרה לימי המלואים, וכאן צוה לדורות:
@979 **סלת למנחה.** מנחת נסכים:
@980 **העשיה בהר סיני.** כאותן שנעשו בימי המלואים. דבר אחר העשיה בהר סיני, הקיש עולת תמיד לעולת הר סיני אותה שנתקרבה לפני מתן תורה שכתוב בה (שמות כד, ו) וישם באגנות מלמד שטעונה כלי:
@981 **ונסכו.** יין: **בקדש הסך.** על המזבח יתנסכו: **נסך שכר.** יין המשכר פרט ליין מגתו:
@982 **ריח ניחח.** נחת רוח לפני שאמרתי ונעשה רצוני:
@984 **עלת שבת בשבתו.** ולא עולת שבת זו בשבת אחרת, הרי שלא הקריב בשבת זו שומע אני יקריב שתים לשבת הבאה, תלמוד לומר בשבתו, מגיד שאם עבר יומו בטל קרבנו: **על עלת התמיד.** אלו מוספין, לבד אותן שני כבשים של עולת התמיד. ומגיד שאין קרבין אלא בין שני התמידין, וכן בכל המוספין נאמר על עולת התמיד לתלמוד זה:
@986 **ושלשה עשרונים.** כמשפט נסכי פר, שכן הן קצובין בפרשת נסכים:
@988 **זאת עלת חדש בחדשו.** שאם עבר יומו בטל קרבנו ושוב אין לו תשלומין:
@989 **ושעיר עזים** וגו' **.** כל שעירי המוספין באין לכפר על טמאת מקדש וקדשיו, הכל כמו שמפורש במס' שבועות (דף ט, א) . ונשתנה שעיר ראש חדש שנאמר בו לה', ללמדך שמכפר על שאין בו ידיעה לא בתחלה ולא בסוף, שאין מכיר בחטא אלא הקדוש ברוך הוא בלבד, ושאר השעירין למדין ממנו. ומדרשו באגדה אמר הקדוש ברוך הוא, הביאו כפרה עלי על שמעטתי את הירח: **על עלת התמיד יעשה.** כל הקרבן הזה: **ונסכו.** אין ונסכו מוסב על השעיר, שאין נסכים לחטאת:
@992 **כל מלאכת עבדה.** אפלו מלאכה הצריכה לכם, כגון דבר האבד המתרת בחלו של מועד אסורה ביום טוב:
@993 **פרים.** כנגד אברהם, שנאמר (בראשית יח, ז) ואל הבקר רץ אברהם: **ואיל.** כנגד אילו של יצחק: **כבשים.** כנגד יעקב שנאמר (בראשית ל, מ) והכשבים הפריד יעקב. ביסודו של רבי משה הדרשן ראיתי זאת:
@998 **כאלה תעשו ליום.** שלא יהיו פוחתין והולכין כפרי החג:
@1000 **וביום הבכורים.** חג השבועות קרוי בכורי קציר חטים על שם שתי הלחם, שהם ראשונים למנחת חטים הבאים מן החדש:
@1005 **תמימים יהיו לכם ונסכיהם.** אף הנסכים יהיו תמימים. למדו רבותינו מכאן שהיין שהעלה קמחין פסול לנסכים:
@1011 **מלבד עלת החדש.** מוספי ראש חדש שהוא ביום ראש השנה:
@1016 **מלבד חטאת הכפרים.** שעיר הנעשה בפנים האמור באחרי מות, שגם הוא חטאת: **ועלת התמיד.** ומלבד עולת התמיד תעשו עולות הללו: **ונסכיהם.** מוסב על המוספין הכתובים ועל תעשו והוא לשון צווי מלבד עולת התמיד ומנחתה תעשו את אלה ונסכיהם. וכן כל ונסכיהם האמורים בכל המועדות חוץ משל קרבנות החג שכל ונסכה ונסכיהם ונסכיה שבהם מוסבים על התמיד ואינן לשון צווי, שהרי נסכיהם של מוספין כתובין לעצמן בכל יום ויום:
@1023 **ומנחתם ונסכיהם לפרים.** פרי החג שבעים הם. כנגד שבעים אמות שמתמעטים והולכים, סימן כליה להם, ובימי המקדש היו מגינין עליהם מן היסורין: **ולכבשים.** כנגד ישראל שנקראו (ירמיה נ, יז) שה פזורה, והם קבועים ומנינם תשעים ושמונה לכלות מהם תשעים ושמונה קללות שבמשנה תורה. בשני נאמר ונסכיהם על שני תמידי היום ולא שנה הלשון אלא לדרוש, כמו שאמרו רבותינו זכרונם לברכה בשני ונסכיהם, בששי ונסכיה, בשביעי כמשפטם, מ''ם יו''ד מ''ם, הרי כאן מים, רמז לנסוך המים מן התורה בחג:
@1040 **עצרת תהיה לכם.** עצורים בעשית מלאכה. דבר אחר עצרת עצרו מלצאת, מלמד שטעון לינה. ומדרשו באגדה לפי שכל ימות הרגל הקריבו כנגד שבעים אמות וכשבאין ללכת, אמר להם המקום בבקשה מכם עשו לי סעודה קטנה כדי שאהנה מכם:
@1041 **פר אחד איל אחד.** אלו כנגד ישראל, התעכבו לי מעט עוד. ולשון חבה הוא זה, כבנים הנפטרים מאביהם והוא אומר להם קשה עלי פרידתכם עכבו עוד יום אחד. משל למלך שעשה סעודה וכו', כדאיתא במסכת סכה (דף נה, ב) ובמדרש רבי תנחומא למדה תורה דרך ארץ, שמי שיש לו אכסנאי יום ראשון יאכילו פטומות, למחר מאכילו דגים, למחר מאכילו בשר בהמה, למחר מאכילו קטניות, למחר מאכילו ירק, פוחת והולך כפרי החג:
@1044 **אלה תעשו לה' במועדיכם.** דבר הקצוב לחובה: **לבד מנדריכם.** אם באתם לדור קרבנות ברגל, מצוה היא בידכם או נדרים או נדבות שנדרתם כל השנה תקריבום ברגל, שמא יקשה לו לחזור ולעלות לירושלים ולהקריב נדריו, ונמצא עובר בבל תאחר:
@1045 **ויאמר משה אל בני ישראל.** להפסיק הענין, דברי רבי ישמעאל, לפי שעד כאן דבריו של מקום ופרשת נדרים מתחלת בדבורו של משה, הצרך להפסיק תחלה ולומר שחזר משה ואמר פרשה זו לישראל, שאם לא כן יש במשמע שלא אמר להם זו אלא בפרשת נדרים התחיל דבריו:
@1046 **ראשי המטות.** חלק כבוד לנשיאים ללמדם תחלה ואחר כך לכל בני ישראל. ומנין שאף שאר הדברות כן, תלמוד לומר (שמות לד, לא. לב) וישבו אליו אהרן וכל הנשאים בעדה וידבר משה אליהם ואחרי כן נגשו כל בני ישראל. ומה ראה לאמרה כאן, למד שהפרת נדרים ביחיד ממחה ואם אין יחיד ממחה מפר בשלשה הדיוטות. או יכול שלא אמר משה פרשה זו אלא לנשיאים בלבד, נאמר כאן זה הדבר, ונאמר בשחוטי חוץ (ויקרא יז, ב) זה הדבר, מה להלן נאמרה לאהרן ולבניו ולכל בני ישראל, שנאמר דבר אל אהרן וגו' , אף זו נאמרה לכלן: **זה הדבר.** משה נתנבא (שמות יא, ד) בכה אמר ה' כחצות הלילה, והנביאים נתנבאו בכה אמר ה', מוסף עליהם משה שנתנבא בלשון זה הדבר. דבר אחר זה הדבר מעוט הוא, לומר שהחכם בלשון התרה ובעל בלשון הפרה, כלשון הכתוב כאן, ואם חלפו אין מתר ואין מופר:
@1047 **נדר.** האומר הרי עלי קנם שלא אוכל או שלא אעשה דבר פלוני, יכול אפלו נשבע שיאכל נבלות אני קורא עליו ככל היוצא מפיו יעשה, תלמוד לומר לאסר אסר את המתר ולא להתיר את האסור: **לא יחל דברו.** כמו לא יחלל דברו, לא יעשה דבריו חלין:
@1048 **בבית אביה.** ברשות אביה ואפלו אינה בביתו: **בנעריה.** ולא קטנה ולא בוגרת, שהקטנה אין נדרה נדר והבוגרת אינה ברשותו של אביה להפר נדריה. ואי זו היא קטנה, אמרו רבותינו בת אחת עשרה שנה ויום אחד נדריה נבדקין. אם ידעה לשם מי נדרה ולשם מי הקדישה נדרה נדר. בת שתים עשרה שנה ויום אחד אינה צריכה להבדק:
@1050 **ואם הניא אביה אתה.** אם מנע אותה מן הנדר, כלומר שהפר לה. הנאה זו איני יודע מה היא, כשהוא אומר ואם ביום שמע אישה יניא אותה והפר, הוי אומר הנאה זו הפרה. ופשוטו לשון מניעה והסרה וכן (במדבר לב, ז) ולמה תניאון, וכן (תהלים קמא, ה) שמן ראש אל יני ראשי, וכן (במדבר יד, לד) וידעתם את תנואתי, את אשר סרתם מעלי: **וה' יסלח לה.** במה הכתוב מדבר באשה שנדרה בנזיר ושמע בעלה והפר לה והיא לא ידעה ועוברת על נדרה ושותה יין ומטמאה למתים, זו היא שצריכה סליחה, ואף על פי שהוא מופר. ואם המופרים צריכים סליחה, קל וחמר לשאינן מופרים:
@1051 **ואם היו תהיה לאיש.** זו ארוסה או אינו אלא נשואה, כשהוא אומר ואם בית אישה נדרה, הרי נשואה אמור וכאן בארוסה, ובא לחלק בה, שאביה ובעלה מפירין נדרה. הפר האב ולא הפר הבעל או הפר הבעל ולא הפר האב, הרי זה אינו מופר, ואין צריך לומר אם קים אחד מהם: **ונדריה עליה.** שנדרה בבית אביה ולא שמע בהן אביה ולא הופרו ולא הוקמו:
@1052 **ושמע אישה** וגו' **.** הרי לך שאם קים הבעל שהוא קים:
@1053 **והפר את נדרה אשר עליה.** יכול אפלו לא הפר האב, תלמוד למר בנעריה בית אביה, כל שבנעוריה ברשות אביה היא:
@1054 **כל אשר אסרה על נפשה יקום עליה.** לפי שאינה לא ברשות אב ולא ברשות בעל, ובאלמנה מן הנשואין הכתוב מדבר, אבל אלמנה מן האירוסין, מת הבעל נתרוקנה וחזרה לרשות האב:
@1055 **ואם בית אישה נדרה.** בנשואה הכתוב מדבר:
@1058 **כל נדר וכל שבעת אסר** וגו' **.** לפי שאמר שהבעל מפר, יכול כל נדרים במשמע, תלמוד לומר לענות נפש, אינו מפר אלא נדרי ענוי נפש בלבד. והם מפורשים במסכת נדרים (דף עט, א) :
@1059 **מיום אל יום.** שלא תאמר מעת לעת, לכך נאמר מיום אל יום, ללמדך שאין מפר אלא עד שתחשך:
@1060 **אחרי שמעו.** אחרי ששמע וקים, שאמר אפשי בו, וחזר והפר לה אפלו בו ביום: **ונשא את עונה.** הוא נכנס תחתיה. למדנו מכאן שהגורם תקלה לחברו הוא נכנס תחתיו לכל ענשין:
@1063 **מאת המדינים.** ולא מאת המואבים, שהמואבים נכנסו לדבר מחמת יראה שהיו יראים מהם, שיהיו שוללים אותם, שלא נאמר אלא (דברים ב, ט) אל תתגר בם מלחמה. אבל מדינים נתעברו על ריב לא להם. דבר אחר מפני שתי פרידות טובות שיש לי להוציא מהם, רות המואביה ונעמה העמונית:
@1064 **וידבר משה** וגו' **.** אף על פי ששמע שמיתתו תלויה בדבר עשה בשמחה ולא אחר: **החלצו.** כתרגומו לשון חלוצי צבא מזינים: **אנשים.** צדיקים, וכן (שמות יז, ט) בחר לנו אנשים, וכן (דברים א, טו) אנשים חכמים וידעים: **נקמת ה'.** שהעומד כנגד ישראל, כאלו עומד כנגד הקדוש ברוך הוא:
@1065 **לכל מטות ישראל.** לרבות שבט לוי:
@1066 **וימסרו.** להודיעך שבחן של רועי ישראל כמה הם חביבים על ישראל, עד שלא שמעו במיתתו מה הוא אומר (שמות יז, ד) עוד מעט וסקלני, ומששמעו שמיתת משה תלויה בנקמת מדין, לא רצו ללכת עד שנמסרו על כרחן:
@1067 **אתם ואת פנחס.** מגיד שהיה פנחס שקול כנגד כלם. ומפני מה הלך פנחס ולא הלך אלעזר. אמר הקדוש ברוך הוא מי שהתחיל במצוה, שהרג כזבי בת צור, יגמור. דבר אחר שהלך לנקום נקמת יוסף אבי אמו, שנאמר (בראשית לז, לו) והמדנים מכרו אתו. ומנין שהיתה אמו של פנחס משל יוסף, שנאמר (שמות ו, כה) מבנות פוטיאל, מזרע יתרו שפטם עגלים לעבודה זרה ומזרע יוסף שפטפט ביצרו. דבר אחר שהיה משוח מלחמה: **וכלי הקדש.** זה הארון והציץ. שהיה בלעם עמהם ומפריח מלכי מדין בכשפים, והוא עצמו פורח עמהם. הראה להם את הציץ, שהשם חקוק בו, והם נופלים, לכך נאמר על חלליהם במלכי מדין, שנופלים על החללים מן האויר, וכן בבלעם כתיב (יהושע יג, כב) אל חלליהם: **בידו.** ברשותו וכן (במדבר כא, כז) ויקח את כל ארצו מידו:
@1069 **חמשת מלכי מדין.** וכי איני רואה שחמשה מנה הכתוב, למה הזקק לומר חמשת, אלא ללמדך ששוו כלם בעצה והשוו כלם בפרענות. בלעם הלך שם לטול שכר עשרים וארבעה אלף שהפיל מישראל בעצתו, ויצא ממדין לקראת ישראל ומשיאן עצה רעה. אמר להם אם כשהייתם ששים רבוא לא יכלתם להם, ועכשיו בשנים עשר אלף אתם באים להלחם. נתנו לו שכרו משלם ולא קפחוהו: **בחרב.** הוא בא על ישראל, והחליף אמנותו באמנותם, שאין נושעים אלא בפיהם על ידי תפלה ובקשה. ובא הוא ותפש אמנותם לקללם בפיו, אף הם באו עליו והחליפו אמנותם באמנות האמות, שבאין בחרב, שנאמר (בראשית כז, מ) ועל חרבך תחיה:
@1071 **טירתם.** מקום פלטרין שלהם, שהוא לשון מושב כומרים יודעי חקיהם. דבר אחר לשון מושב שריהם, כמו שמתרגם סרני פלשתים טורני פלשתאי:
@1072 **ויקחו את כל השלל** וגו' **.** מגיד שהיו כשרים וצדיקים ולא נחשדו על הגזל לשלוח יד בבזה שלא ברשות, שנאמר את כל השלל וגו' , ועליהם מפורש בקבלה שניך כעדר הרחלים וגו' , אף אנשי המלחמה שביך כלם צדיקים: **שלל.** הן מטלטלין של מלבוש ותכשיטין: **בז.** הוא בזת מטלטלין שאינם תכשיטין: **מלקוח.** אדם ובהמה. ובמקום שכתוב שבי אצל מלקוח, שבי באדם ומלקוח בבהמה:
@1074 **ויצאו משה ואלעזר הכהן.** לפי שראו את נערי ישראל יוצאים לחטף מן הבזה:
@1075 **ויקצף משה על פקודי החיל.** ממנים על החיל, ללמדך שכל סרחון הדור תלוי בגדולים שיש כח בידם למחות:
@1077 **הן הנה.** מגיד שהיו מכירין אותן. זו היא שנכשל פלוני בה: **בדבר בלעם.** אמר להם אפלו אתם מכניסים כל המונות [האמות] שבעולם אין אתם יכולים להם, שמא מרבים אתם מן המצרים שהיו שש מאות רכב בחור. בואו ואשיאכם עצה. אלהיהם של אלו שונא זמה הוא וכו' , כדאיתא בחלק (סנהדרין קו.) ובספרי:
@1078 **וכל אשה ידעת איש.** ראויה להבעל אף על פי שלא נבעלה. ולפני הציץ העבירום והראויה להבעל פניה מוריקות: **הרגו.** למה חזר ואמר, להפסיק הענין, דברי ר' ישמעאל, שאם אני קורא הרגו כל זכר בטף וכל אשה ידעת איש וכל הטף בנשים וגו' איני יודע אם להרוג עם הזכרים או להחיות עם הטף, לכך נאמר הרגו:
@1080 **מחוץ למחנה.** שלא יכנסו לעזרה: **כל הרג נפש.** ר' מאיר אומר בהורג בדבר המקבל טמאה הכתוב מדבר, ולמדך הכתוב שהכלי מטמא אדם בחבורי המת, כאלו נוגע במת עצמו, או יכול אפלו זרק בו חץ והרגו, תלמוד לומר וכל נגע בחלל, מקיש הורג לנוגע, מה נוגע על ידי חבורו, אף הורג על ידי חבורו: **תתחטאו.** במי נדה, כדין שאר טמאי מתים, שאף לדברי האומרים קברי גוים אינן מטמאין באהל, שנאמר (יחזקאל לד, לא) ואתן צאני צאן מרעיתי אדם אתם, אתם קרויין אדם ואין הגוים קרויין אדם, מודה הוא שהגוים מטמאין במגע ובמשא, שלא נאמר אדם אלא אצל טמאת אהלים, שנאמר אדם כי ימות באהל: (במדבר יט, יד) **אתם ושביכם.** לא שהנכרים מקבלין טמאה וצריכין הזאה, אלא מה אתם בני ברית, אף שביכם כשיבואו לברית ויטמאו, צריכין הזאה:
@1081 **וכל מעשה עזים.** להביא כלי הקרנים והטלפים והעצמות:
@1082 **ויאמר אלעזר הכהן** וגו' **.** לפי שבא משה לכלל כעס בא לכלל טעות, שנתעלמו ממנו הלכות גיעולי נכרים. וכן אתה מוצא בשמיני למלואים, שנאמר (ויקרא י, טז) ויקצף על אלעזר ועל איתמר, בא לכלל כעס, בא לכלל טעות, וכן (במדבר כ, י. יא) בשמעו נא המרים ויך את הסלע, על ידי הכעס טעה: **אשר צוה ה'** וגו' **.** תלה ההוראה ברבו:
@1083 **אך את הזהב** וגו' **.** אף על פי שלא הזהיר לכם משה אלא על הלכות טמאה, עוד יש להזהיר לכם על הלכות געול. ואך לשון מעוט, כלומר ממועטין אתם מלהשתמש בכלים אפלו לאחר טהרתן מטמאת המת, עד שיטהרו מבליעת אסור נבלות. ורבותינו אמרו אך את הזהב לומר שצריך להעביר חלודה שלו קודם שיגעילנו, וזהו לשון אך, שלא יהא שם חלודה, אך המתכת יהיה כמות שהוא:
@1084 **כל דבר אשר יבא באש.** לבשל בו כלום: **תעבירו באש.** כדרך תשמישו הגעלתו, מה שתשמישו על ידי חמין, יגעילנו בחמין, ומה שתשמישו על ידי צלי, כגון השפוד והאסכלה, ילבננו באור: **אך במי נדה יתחטא.** לפי פשוטו חטוי זה לטהרו מטמאת מת. אמר להם צריכין הכלים געול לטהרם מן האסור, וחטוי לטהרן מן הטמאה. ורבותינו דרשו מכאן, שאף להכשירן מן האסור הטעין טבילה לכלי מתכות. ומי נדה הכתובין כאן דרשו מים הראוים לטבול בהם נדה. וכמה הם, ארבעים סאה: **וכל אשר לא יבא באש.** כל דבר שאין תשמישו על ידי האור, כגון כוסות וצלוחיות שתשמישן בצונן ולא בלעו אסור: **תעבירו במים.** מטבילן ודיו ודוקא כלי מתכות:
@1085 **אל המחנה.** למחנה שכינה, שאין טמא מת טעון שלוח ממחנה לויה וממחנה ישראל:
@1087 **שא את ראש.** קח את החשבון:
@1088 **וחצית את המלקוח בין תפשי המלחמה** וגו' **.** חציו לאלו וחציו לאלו:
@1093 **ויהי המלקוח יתר הבז.** לפי שלא נצטוו להרים מכס מן המטלטלין אלא מן המלקוח, כתב את הלשון הזה, ויהי המלקוח שבא לכלל חלקה ולכלל מכס, שהיה עודף על בז המטלטלין אשר בזזו עם הצבא איש לו, ולא בא לכלל חלקה מספר הצאן וגו' :
@1103 **וממחצית בני ישראל אשר חצה משה.** לעדה והוציאה להם מן האנשים הצובאים:
@1104 **ותהי מחצת העדה.** כך וכך:
@1109 **ויקח משה** וגו' **הפקדים.** הממנים:
@1110 **ולא נפקד.** ולא נחסר ותרגומו ולא שגא, אף הוא בלשון ארמי חסרון, כמו אנכי אחטנה, (בראשית לא, לט) תרגומו דהות שגיא ממנינא, וכן כי יפקד מושבך (שמואל א' כ, יח) , יחסר מקום מושבך, איש הרגיל לישב שם. וכן (שם כ, כז) ויפקד מקום דוד, נחסר מקומו ואין איש יושב שם:
@1111 **אצעדה.** אלו צמידים של רגל: **וצמיד.** של יד: **עגיל.** נזמי אזן: **וכומז.** דפוס של בית הרחם לכפר על הרהור הלב של בנות מדין:
@1118 **עטרות ודיבון** וגו' **.** מארץ סיחון ועוג היו:
@1121 **האחיכם.** לשון תמיהה הוא:
@1122 **ולמה תניאון.** תסירו ותמניעו לבם מעבור שיהיו סבורים שאתם יראים לעבור מפני המלחמה וחוזק הערים והעם:
@1123 **מקדש ברנע.** כך שמה, ושני קדש היו:
@1127 **הקנזי.** חורגו של קנז היה, וילדה לו אמו של כלב את עתניאל:
@1128 **וינעם.** ויטלטלם. מן נע ונד:
@1129 **לספות.** כמו (ישעיה כט, א) ספו שנה על שנה, (ירמיה ז, כא) עולותיכם ספו וגו' , לשון תוספת:
@1131 **נבנה למקננו פה.** חסים היו על ממונם יותר מבניהם ובנותיהם, שהקדימו מקניהם לטפם. אמר להם משה לא כן עשו, העיקר עיקר והטפל טפל, בנו לכם תחלה ערים לטפכם ואחר כך גדרות לצאנכם:
@1132 **ואנחנו נחלץ חשים.** נזדרז מהירים, כמו (ישעיה ח, א) מהר שלל חש בז, (ישעיה ה, יט) ימהר יחישה: **לפני בני ישראל.** בראשי גיסות, מתוך שגבורים היו, שכן נאמר בגד (דברים לג, כ) וטרף זרוע אף קדקד, ואף משה חזר ופרש להם באלה הדברים (דברים ג, יח) ואצו אתכם בעת ההיא וגו' חלוצים תעברו לפני אחיכם בני ישראל כל בני חיל. וביריחו כתיב (יהושע ו, יג) והחלוץ הולך לפניהם, זה ראובן וגד שקימו תנאם: **וישב טפנו.** בעודנו אצל אחינו: **בערי המבצר.** שנבנה עכשיו:
@1134 **מעבר לירדן** וגו' **.** בעבר המערבי: **כי באה נחלתנו.** כבר קבלנוה בעבר המזרחי:
@1139 **לצנאכם.** תיבה זו מגזרת (תהלים ח, ח) צנה ואלפים כלם, שאין בו אל''ף מפסיק בין נו''ן לצד''י, ואל''ף שבא כאן אחר הנו''ן במקום ה''א של צנה הוא. מיסודו של ר' משה הדרשן למדתי כן: **והיצא מפיכם תעשו.** לגבוה שקבלתם עליכם לעבור למלחמה עד כבוש וחלוק. שמשה לא בקש מהם אלא ונכבשה ואחר תשבו, והם קבלו עליהם עד התנחל, הרי הוסיפו להתעכב שבע שחלקו, וכן עשו:
@1140 **ויאמר בני גד.** כלם כאיש אחד:
@1143 **ויצו להם.** כמו עליהם, ועל תנאם מנה אלעזר ויהושע, כמו (שמות יד, יד) ה' ילחם לכם:
@1147 **ואתנו אחזת נחלתנו.** כלומר בידינו וברשותנו תהי אחזת נחלתנו מעבר הזה:
@1151 **ערי מבצר וגדרות צאן.** זה סוף הפסוק מוסב על תחלת הענין, ויבנו בני גד את הערים הללו להיות ערי מבצר וגדרות צאן:
@1153 **ואת נבו ואת בעל מעון מוסבת שם.** נבו ובעל מעון שמות עבודה זרה הם, והיו האמוריים קורים עריהם על שם עבודה זרה שלהם, ובני ראובן הסבו את שמם לשמות אחרים, וזהו מסבות שם, נבו ובעל מעון מוסבות לשם אחר: **ואת שבמה.** בנו שבמה והיא שבם האמורה למעלה:
@1154 **ויורש.** כתרגומו ותריך. שתבת רי''ש משמשת שתי חלקות לשון ירשה ולשון הורשה, שהוא טירוד ותירוך:
@1156 **חותיהם.** כפרניהון: **ויקרא אתהן חות יאיר.** לפי שלא היו לו בנים קראם בשמו לזכרון:
@1157 **ויקרא לה נבח.** לה אינו מפיק ה''א. וראיתי ביסודו של רבי משה הדרשן לפי שלא נתקים לה שם זה, לפיכך הוא רפה, שמשמע מדרשו כמו לא. ותמהני מה ידרוש בשתי תיבות הדומות לה (רות ב, יד) ויאמר לה בעז, (זכריה ה, יא) לבנות לה בית:
@1158 **אלה מסעי.** למה נכתבו המסעות הללו, להודיע חסדיו של מקום, שאף על פי שגזר עליהם לטלטלם ולהניעם במדבר, לא תאמר שהיו נעים ומטלטלים ממסע למסע כל ארבעים שנה ולא היתה להם מנוחה, שהרי אין כאן אלא ארבעים ושתים מסעות. צא מהם ארבעה עשר, שכלם היו בשנה ראשונה, קודם גזרה, משנסעו מרעמסס עד שבאו לרתמה. שמשם נשתלחו המרגלים, שנאמר (במדבר יב, טז) ואחר נסעו העם מחצרות וגו' (שם יג, ב) שלח לך אנשים וגו' . וכאן הוא אומר ויסעו מחצרות ויחנו ברתמה, למדת שהיא במדבר פארן. ועוד הוצא משם שמונה מסעות שהיו לאחר מיתת אהרן מהר ההר עד ערבות מואב בשנת הארבעים, נמצא שכל שמנה ושלשים שנה לא נסעו אלא עשרים מסעות. זה מיסודו של רבי משה הדרשן. ורבי תנחומא דרש בו דרשה אחרת משל למלך שהיה בנו חולה והוליכו למקום רחוק לרפאותו, כיון שהיו חוזרין התחיל אביו מונה כל המסעות. אמר לו כאן ישנו, כאן הוקרנו, כאן חששת את ראשך וכו' :
@1161 **ומצרים מקברים.** טרודים באבלם:
@1175 **ויחנו ברתמה.** על שם לשון הרע של מרגלים, שנאמר (תהלים קכ, ג) מה יתן לך ומה יוסיף לך לשון רמיה חצי גבור שנונים עם גחלי רתמים:
@1195 **על פי ה'.** מלמד שמת בנשיקה:
@1197 **וישמע הכנעני.** כאן למדך שמיתת אהרן היא השמועה, שנסתלקו ענני הכבוד וכסבור שנתנה רשות להלחם בישראל, לפיכך חזר וכתבה:
@1201 **בעיי העברים.** לשון חרבות וגלים, כמו לעי השדה, (מיכה א, ו) שמו את ירושלים לעיים (תהלים עט, א) :
@1206 **מבית הישמת עד אבל השטים.** כאן למדך שעור מחנה ישראל שנים עשר מיל. דאמר רבה בר בר חנה לדידי חזי לי ההוא אתרא וכו' (ערובין נה, ב) : **אבל השטים.** מישור של שטים אבל שמו:
@1208 **כי אתם עברים את הירדן** וגו' **והורשתם** וגו' **.** והלא כמה פעמים הזהרו על כך, אלא כך אמר להם משה כשאתם עוברים בירדן ביבשה, על מנת כן תעברו, ואם לאו מים באין ושוטפין אתכם, וכן מצינו שאמר להם יהושע בעודם בירדן:
@1209 **והורשתם.** וגרשתם: **משכיתם.** כתרגומו בית סגדתהון, על שם שהיו מסככין את הקרקע ברצפת אבנים של שיש להשתחוות עליהם בפשוט ידים ורגלים, כדכתיב (ויקרא כו, א) ואבן משכית לא תתנו בארצכם להשתחוות עליה: **מסכתם.** כתרגומו מתכתהון:
@1210 **והורשתם את הארץ.** והורשתם אותה מיושביה ואז וישבתם בה, תוכלו להתקים בה, ואם לאו לא תוכלו להתקים בה:
@1211 **אל אשר יצא לו שמה.** מקרא קצר הוא זה, אל מקום אשר יצא לו שמה הגורל לו יהיה: **למטות אבותיכם.** לפי חשבון יוצאי מצרים. דבר אחר בשנים עשר גבולין כמנין השבטים:
@1212 **והיה אשר תותירו מהם.** יהיו לכם לרעה: **לשכים בעיניכם.** ליתדות המנקרות עיניכם. תרגום של יתדות שיכיא: **ולצנינם.** פותרים בו הפותרים לשון מסוכת קוצים הסוככת אתכם לסגור ולכלוא אתכם מאין יוצא ובא: **וצררו אתכם.** כתרגומו:
@1215 **זאת הארץ אשר תפל לכם** וגו' **.** לפי שהרבה מצות נוהגות בארץ ואין נוהגות בחוצה לארץ, הצרך לכתוב מצרני גבולי רוחותיה סביב, לומר לך מן הגבולים הללו ולפנים המצות נוהגות: **תפל לכם.** על שם שנתחלקה בגורל נקראת חלקה לשון נפילה. ומדרש אגדה אומר על ידי שהפיל הקדוש ברוך הוא שריהם של שבע אמות מן השמים וכפתן לפני משה, אמר לו ראה אין בהם עוד כח:
@1216 **והיה לכם פאת נגב.** רוח דרומית אשר מן המזרח למערב: **ממדבר צן.** אשר אצל אדום מתחלת מקצוע דרומית מזרחית של ארץ תשעת המטות. כיצד, שלש ארצות יושבות בדרומה של ארץ ישראל זו אצל זו קצת ארץ מצרים, וארץ אדום כלה וארץ מואב כלה. ארץ מצרים במקצוע דרומית מערבית, שנאמר בפרשה זו מעצמון נחלה מצרים והיו תוצאותיו הימה. ונחל מצרים היה מהלך על פני כל ארץ מצרים, שנאמר (יהושע יג, ג) מן השיחור אשר על פני מצרים. ומפסיק בין ארץ מצרים לארץ ישראל וארץ אדום אצלה לצד המזרח וארץ מואב אצל ארץ אדום בסוף הדרום למזרח, וכשיצאו ישראל ממצרים, אם רצה המקום לקרב את כניסתם לארץ היה מעבירם את הנילוס לצד צפון ובאין לארץ ישראל, ולא עשה כן, וזהו שנאמר (שמות יג, יז) ולא נחם אלהים דרך ארץ פלשתים, שהם יושבים על הים במערבה של ארץ כנען, כענין שנאמר בפלשתים (צפניה ב, ה) יושבי חבל הים גוי כרתים. ולא נחם אותו הדרך אלא הסבן והוציאם דרך דרומה אל המדבר, והוא שקראו יחזקאל (יחזקאל כ, לה) מדבר העמים, לפי שהיו כמה אמות יושבות בצדו והולכין אצל דרומה מן המערב כלפי מזרח תמיד, עד שבאו לדרומה של ארץ אדום ובקשו ממלך אדום שיניחם להכנס בארצו ולעבור דרך רחבה ולהכנס לארץ, ולא רצה. והצרכו לסבוב את כל דרומה של אדום עד בואם לדרומה של ארץ מואב, שנאמר (שופטים יא, יז) וגם אל מלך מואב שלח ולא אבה. והלכו כל דרומה של מואב עד סופה ומשם הפכו פניהם לצפון עד שסבבו כל מצר מזרחי שלה לרחבה וכשכלו את מזרחה מצאו את ארץ סיחון ועוג שהיו יושבין במזרחה של ארץ כנען והירדן מפסיק ביניהם. וזהו שנאמר ביפתח (שופטים יא, יח) וילך במדבר ויסב את ארץ אדום ואת ארץ מואב ויבא ממזרח שמש לארץ מואב. וכבשו את ארץ סיחון ועוג שהיתה בצפונה של ארץ מואב. וקרבו עד הירדן והוא כנגד מקצוע צפונית מערבית של ארץ מואב, נמצא שארץ כנען שבעבר הירדן למערב היה מקצוע דרומית מזרחית שלה אצל אדום:
@1217 **ונסב לכם הגבול מנגב למעלה עקרבים.** כל מקום שנאמר ונסב או ויצא, מלמד שלא היה המצר שווה אלא הולך ויוצא לחוץ, יוצא המצר ועוקם לצד צפונו של עולם באלכסון למערב ועובר המצר בדרומה של מעלה עקרבים, נמצא מעלה עקרבים לפנים מן המצר: **ועבר צנה.** אל צין כמו מצרימה: **והיו תוצאותיו.** קצותיו. בדרומה של קדש ברנע: **ויצא חצר אדר.** מתפשט המצר ומרחיב לצד צפון של עולם ונמשך עוד באלכסון למערב ובא לו לחצר אדר ומשם לעצמון ומשם לנחל מצרים. ולשון ונסב האמור כאן לפי שכתב ויצא חצר אדר שהתחיל להרחיב משעבר את קדש ברנע ורוחב אותה רצועה שבלטה לצד צפון היתה מקדש ברנע עד עצמון ומשם והלאה נתקצר המצר ונסב לצד הדרום ובא לו לנחל מצרים ומשם לצד המערב אל הים הגדול שהוא מצר מערבה של כל ארץ ישראל. נמצא שנחל מצרים במקצוע מערבית דרומית:
@1218 **והיו תוצאותיו הימה.** אל מצר המערב שאין עוד גבול נגב מאריך לצד המערב משם והלאה:
@1219 **וגבול ים.** ומצר מערבי מהו: **והיה לכם הים הגדול.** למצר: **וגבול.** הנסין שבתוך הים אף הם מן הגבול והם איים, שקורין אישלי''ש [איים] :
@1220 **גבול צפון.** מצר צפון: **מן הים הגדול תתאו לכם הר ההר.** שהוא במקצוע צפונית מערבית. וראשו משפיע ונכנס לתוך הים ויש מרוחב הים לפנים המנו וחוצה המנו: **תתאו.** תשפעו לכם לנטות ממערב לצפון אל הר ההר: **תתאו.** לשון סבה, כמו (ד''ה ב' יב, יא) אל תא הרצים, (יחזקאל מ, י) ותאי השער היציע, שקורין אפינדי''ץ , שהוא מוסב ומשפע:
@1221 **מהר ההר.** תסבו ותלכו אל מצר הצפון לצד המזרח ותפגעו בלבא חמת, זו אנטוכיא: **תוצאות הגבול.** סופי הגבול. כל מקום שנאמר תוצאות הגבול, או המצר כלה שם לגמרי ואינו עובר להלן כלל, או משם מתפשט ומרחיב ויוצא לאחוריו להמשיך להלן באלכסון יותר מן הרוחב הראשון, ולענין רוחב המדה הראשון קראו תוצאות, ששם כלתה אותה מדה:
@1222 **והיו תוצאתיו חצר עינן.** הוא היה סוף המצר הצפוני. ונמצאת חצר עינן במקצוע צפונית מזרחית. ומשם והתאויתם לכם אל מצר המזרחי:
@1223 **והתאויתם.** לשון הסבה ונטיה כמו תתאו: **שפמה.** במצר המזרחי ומשם הרבלה:
@1224 **מקדם לעין.** שם מקום. והמצר הולך במזרחו נמצא העין לפנים מן המצר ומארץ ישראל הוא: **וירד הגבל.** כל שהגבול הולך מצפון לדרום הוא יורד והולך: **ומחה על כתף.** אל עבר: **ים כנרת קדמה.** שיהא ים כנרת תוך לגבול במערב, והגבול במזרח ים כנרת, ומשם יורד אל הירדן והירדן מושך ובא מן הצפון לדרום באלכסון נוטה לצד מזרח ומתקרב לצד ארץ כנען כנגד ים כנרת ומושך לצד מזרחה של ארץ ישראל כנגד ים כנרת עד שנופל בים המלח ומשם כולה הגבול בתוצאותיו אל ים המלח, שממנו התחלת מצר מקצוע דרומית מזרחית. הרי סובבת אותה לארבע רוחותיה:
@1228 **קדמה מזרחה.** אל פני העולם שהם במזרח, שרוח מזרחית קרויה פנים, ומערבית קרויה אחור, לפיכך דרום לימין וצפון לשמאל:
@1230 **אשר ינחלו לכם.** בשבילכם כל נשיא ונשיא אפטורפוס לשבטו ומחלק נחלת השבט למשפחות ולגברים ובורר לכל אחד ואחד חלק הגון. ומה שהם עושין יהיה עשוי כאלו עשאום שלוחים. ולא יתכן לפרש לכם זה ככל לכם שבמקרא, שאם כן היה לו לכתוב ינחילו לכם. ינחלו משמע שהם נוחלים לכם בשבילכם ובמקומכם, כמו (שמות יד, יד) ה' ילחם לכם:
@1231 **לנחל את הארץ.** שיהא נוחל וחולק אותה במקומכם:
@1242 **לנחל את בני ישראל.** שהם ינחילו אותה לכם למחלקותיה:
@1244 **ומגרש.** רוח מקום חלק חוץ לעיר סביב להיות לנוי לעיר, ואין רשאין לבנות שם בית ולא לנטוע כרם ולא לזרוע זריעה:
@1245 **ולכל חיתם.** ולכל צרכיהם:
@1246 **אלף אמה סביב.** ואחריו הוא אומר אלפים באמה, הא כיצד אלפים, הוא נותן להם סביב, ומהם אלף הפנימיים למגרש והחיצונים לשדות וכרמים:
@1253 **והקריתם.** אין הקריה אלא לשון הזמנה וכן הוא אומר (בראשית כז, כ) כי הקרה ה' אלהיך לפני:
@1254 **מגאל.** מפני גואל הדם שהוא קרוב לנרצח:
@1255 **שש ערי מקלט.** מגיד שאף על פי שהבדיל משה בחייו שלש ערים בעבר הירדן, לא היו קולטות עד שנבחרו שלש שנתן יהושע בארץ כנען:
@1256 **את שלש הערים** וגו' **.** אף על פי שבארץ כנען תשעה שבטים וכאן אינן אלא שנים וחצי, השוה מנין ערי מקלט שלהם משום דבגלעד נפישי רוצחים, דכתיב (הושע ו, ח) גלעד קרית פועלי און עקבה מדם:
@1258 **ואם בכלי ברזל הכהו.** אין זה מדבר בהורג בשוגג הסמוך לו, אלא בהורג במזיד. ובא ללמד, שההורג בכל דבר צריך שיהא בו שעור כדי להמית, שנאמר בכלם אשר ימות בו, דמתרגמינן דהיא כמסת דימות ביה, חוץ מן הברזל, שגלוי וידוע לפני הקדוש ברוך הוא שהברזל ממית בכל שהוא אפלו מחט, לפיכך לא נתנה בו תורה שעור לכתוב בו אשר ימות בו. ואם תאמר בהורג בשוגג הכתוב מדבר, הרי הוא אומר למטה או בכל אבן אשר ימות בה בלא ראות וגו' , למד על האמורים למעלה שבהורג במזיד הכתוב מדבר:
@1259 **באבן יד.** שיש בה מלא יד: **אשר ימות בה.** שיש בה שעור להמית, כתרגומו. לפי שנאמר (שמות כא, יח) והכה איש את רעהו באבן, ולא נתן בה שעור, יכול כל שהוא, לכך נאמר אשר ימות בה:
@1260 **או בכלי עץ יד.** לפי שנאמר וכי יכה איש את עבדו או את אמתו בשבט (שמות כא) , יכול כל שהוא, לכך נאמר בעץ אשר ימות בו, שיהא בו כדי להמית:
@1261 **בפגעו בו.** אפלו בתוך ערי מקלט:
@1262 **בצדיה.** כתרגומו, בכמנא. במארב:
@1264 **בפתע.** באונס. ותרגומו בתכיף, שהיה סמוך לו, ולא היה לו שהות להזהר עליו:
@1265 **או בכל אבן אשר ימות בה.** הכהו: **בלא ראות.** שלא ראהו: **ויפל עליו.** מכאן אמרו ההורג דרך ירידה גולה, דרך עליה אינו גולה:
@1267 **עד מות הכהן הגדול.** שהוא בא להשרות שכינה בישראל ולהאריך ימיהם, והרוצח בא לסלק את השכינה מישראל ומקצר את ימי החיים. אינו כדאי שיהא לפני כהן גדול. דבר אחר לפי שהיה לו לכהן גדול להתפלל שלא תארע תקלה זו לישראל בחייו: **אשר משח אתו בשמן הקדש.** לפי פשוטו מן המקראות הקצרים הוא, שלא פרש מי משחו, אלא כמו אשר משחו המושח אותו בשמן הקדש. ורבותינו דרשוהו במסכת מכות (יא, ב) לראיית דבר, ללמד שאם עד שלא נגמר דינו מת כהן גדול ומנו אחר תחתיו ולאחר מכאן נגמר דינו, חוזר במיתתו של שני, שנאמר אשר משח אתו, וכי הוא משחו לכהן או הכהן משח אותו, אלא להביא את הנמשח בימיו שמחזירו במיתתו:
@1269 **אין לו דם.** הרי הוא כהורג את המת שאין לו דם:
@1271 **בכל מושבתיכם.** למד שתהא סנהדרין קטנה נוהגת בחוצה לארץ כל זמן שנוהגת בארץ ישראל:
@1272 **כל מכה נפש** וגו' **.** הבא להרגו על שהכה את הנפש: **לפי עדים ירצח.** שיעידו שבמזיד ובהתראה הרגו:
@1273 **ולא תקחו כפר.** לא יפטר בממון:
@1274 **ולא תקחו כפר לנוס אל עיר מקלטו.** למי שנס אל עיר מקלטו שהרג בשוגג אינו נפטר מגלות בממון לתן כפר לשוב לשבת בארץ בטרם ימות הכהן: **לנוס.** כמו לנס, כמו (מיכה ב, ח) שובי מלחמה, ששבו מן המלחמה, וכן (צפניה ג, יח) נוגי ממועד, וכן (יהושע ה, ה) כי מלים היו, כאשר תאמר שוב על מי ששב כבר, ומול על מי שמל כבר, כן תאמר לנוס על מי שנס כבר, וקורהו נוס כלומר מברח. ואם תאמר לנוס לברוח, ותפרשהו לא תקחו כפר למי שיש לו לברוח לפטרו מן הגלות, לא ידעתי היאך יאמר לשוב לשבת בארץ, הרי עדין לא נס ומהיכן ישוב:
@1275 **ולא תחניפו.** ולא תרשיעו, כתרגומו ולא תחיבון:
@1276 **אשר אני שכן בתוכה.** שלא תשכינו אותי בטמאתה: **כי אני ה' שכן בתוך בני ישראל.** אף בזמן שהם טמאים שכינה ביניהם:
@1279 **ונוסף על נחלת המטה.** שהרי בנה יורשה והבן מתיחס על שבט אביו:
@1280 **ואם יהיה היובל.** מכאן היה רבי יהודה אומר עתיד היובל שיפסוק: **ואם יהיה היובל.** כלומר אין זו מכירה שחוזרת ביובל, שהירשה אינה חוזרת, ואפלו אם יהיה היובל לא תחזור הנחלה לשבטו, ונמצא שנוספה על נחלת המטה אשר תהיינה להם:
@1284 **וכל בת ירשת נחלה.** שלא היה בן לאביה:
@1287 **מחלה תרצה** וגו' **.** כאן מנאן לפי גדלתן זו מזו בשנים ונשאו כסדר תולדותן, ובכל המקרא מנאן לפי חכמתן ומגיד ששקולות זו כזו:

@56 וחנו בזה האופן והיה אפשר מפני זה שיעזרו אנשי המשפחה קצתם בקצת לכל מה שיצטרך מפני היותם חונים זה אצל זה עם שבזה גם כן הכלל מהתועלת שהיה כל עניינים מוגבל באופן שלא תהיה קטטה בעניין חנייתם והנה הגבילה התורה כשיעמוד היותר נכבד שבשבטים במקום היותר נכבד ולזה היו הלויים עומדים סביב למשכן העדות לגודל מעלתם בעבודת השם יתעלה והנה היותר נכבדים מהם היו חונים לפאת מזרח והם משה אהרן ובניו כמו שנזכר בזאת הפרשה והנה היתה הפאה ההיא יותר נכבדת לפי ששם פני הקדש וקדשי הקדשים ר"ל שפתחיהם היו לפאת מזרח והנה אחר הפאה המזרחית היתה הפאה הדרומית היותר נכבדת וזה מבואר מאד לפי מה שקדם בעניין הקרבנות ולזה היו חובים שם בני קהת שהיתה עבודתם יותר נכבדת מהדרומית כך המערבית המקבלת לה יותר נכבדת מהצפונית שהיא המקבלת לפאה הדרומית ולזה היו חונים בני גרשון לפאת המערבית ובני מררי בפאה הצפונית כי עבודת בני גרשון יותר נכבדת באופן מה מעבודת בני מררי כמו שיתבאר בזאת הפרשה ובזה האופן גם כן היו חונים השבטים סביב למחנה לוייה ולזה היה שבט יהודה חונה לפאת מזרח להיותו היותר נכבד כי ממנו הוגבלה להיות המלוכה והיו חונים עמו השבטים שנולדו אחריו מלאה על מדרגותיהם והם יששכר וזבולון ולהיותו ראובן היותר נכבד אחריו כי הוא הבכור ליעקב וללאה היה חונה לפאת דרום והיה חונה עמו שם השבט שנולד אחריו והוא שמעון והיה שם עמהם גד שהוא הראשון שנולד משפחות לאה ואחריו היו בני רחל היותר נכבדים ונתנה הגדולה לאפרי' כמו שהתבאר מברכת יעקב לו והיו חונים לפאת מערב והיו חונים אצלו מנשה ובנימן כי הם מבני רחל ונשארו השבטים הנשארים בני השפחות והם היותר נכבד מהם דן כי הוא הראשון שנולד מבני השפחות וממנו עתיד להיות שופט מושיע ישראל כמו שהתבאר מברכת יעקב ולזה היה זה הדגל בשמו והיה אצלו מטה אשר שהיה בן שפחת לאה לכבוד לאה ואחריו היה מטה נפתלי שהוא משפחת רחל:
@94 והנה נתייחד שבט לוי לשמור משמר' בית המקדש ולעבוד עבודתו להוסיף מעלה למשכן בנפש כי זה השבט הנבחר נתייחד לבד לזאת העבודה וכבר נתבאר עניין השמירה והעבודה בג"ה בפרשת קרח כי ענייניה היה גם כן לתת גדולה לבית הקדוש בנפש כי מדרך הבתים הגדולים שיהיו בו שומרים ושוערים. והנה להראות מעלת הלוים שכבר נתייחדו מבין שאר השבטים לעבודת השם יתעלה לא התפקדו בתוך בני ישראל וכן לתת מעלה גדולה בנפש לעבודה הנכבדת אשר במקדש נתייחדו העובדים מזולתם מהאנשים והנה הזר הקרב במיתה בידי שמי':
@100 **ואני הנה לקחתי את הלויים מתוך בני ישראל וגומ'.** כבר בארנו במה שקדם בפרשת בא אל פרעה שבכור אדם נוהג בחוצה לארץ ואמנם בכור בהמה אינו נוהג אלא בארץ והנה פטרו הלוים הבכורות מישראל לפי המספר ושאר הבכורות נתנו כל אחד מהם חמשת שקלים לאהרן ולבניו והם חמשת סלעים של כס צרוף שהם כמו ארבע אונקיות שלנו ואולם בבכורות הבהמה לפי שאין עיקרם נוהג בחוצה לארץ לא נמנו אבל לוקחו בכללו' הלויים ובהמתם תחת בכורות ישראל ובכורות בהמותיהם מזולת מניין בבכורות הבהמות ואמנם הוצרך להזכיר בכורות הבהמה ואם אינם נוהגי' בחוצה לארץ לפי שהוא ראוי שהבכורות בעצמם שהוצלו מהנגף בנגוף השם כל בכור בהמה יותר ליי' בהם כבוד באופן מה ואם לא היה אפשר שיהיו קדושים בעצמם ולזה אמר בכללות שכבר נלקח לש' ית' בהמת הלויים תחת בכורות הבהמה וכבר הרחבנו המאמר בזה בפרשת בא אל פרעה.
@113 והנה תמצא בזה המקום במשמרת בני גרשון שהוא למטה ממשמרת בני קהת כי משמרת בני קהת היתה בדברים הפנימיים שהיתה בהם יותר מהקדושה ואמנם היה במשמרת מזבח החיצון להתיחסות אשר לו עם מזבח הזהב כמו שזכרנו במה שקדם עם שממנו ילקח האש אשר יקטירו בו קטרת הסמים במזבח ולזה נעשו בני אהרן כשהקטירו קטרת הסמים במזבח הזהב באש זרה שלא לוקחה ממזבח הנחשת ואולם משמרת בני גרשון היתה בדברים היותר נכבדים שבדברים החיצוניים והפנימיים מהם כי קלעי החצר הם יותר נכבדים מהקדשים כי הם פנימיים מהם ולזאת הסבה התבאר שהאהל ומכסהו יותר נכבדים מהקדשים והבריחים והעמודי' והאדני' ולזה התבאר שמשמרת בני גרשון יותר נכבדת ממשמרת בני מררי כי משמרת בני גרשון היתה המשכן והאהל מכסהו ומסך פתח אוהל מועד וקלעי החצר ומסך פתח החצר ואת מיתריו משמרת בני מררי היתה קרשי המשכן ובריחיו ועמודיו ואדניו וכל כליו וכל עבודתו ועמודי החצר ואדנים ויתדותם ומתריהם ויסדה התורה שיהיה הזר הקרב במיתה כדי שישלם בסדור אלו הדברים הנכבדי' אשר במקדש באופן שיהיה איש על עבודתו ועל משאו ושיסדרו זה אהרן ובניו וישימו איש על עבודתו ועל משאו להסיר מהם המחלוקת ולסבב שישלם הסדור באלו הדברים.
@141 והנה למעלת הדברים היו משמרת בני קהת מכסים אותם
@144 **אהרן ובניו** תחלה קודם שיגעו בהם בני קהת כדי שלא יגעו אל הקדש זולתי הכהנים שהיו מיוחדים לעבודות הנכבדות
@155 ואולם **שמן המאור וקטרת הסמים ומנחת התמיד** והוא מנחת חביתין של כהן גדול ושמן המשחה לא היו נושאים אותם בני קהת לסבה הנזכרת והיה זה נשא על ידי הכהנים
@161 **נשא את ראש בני גרשון גם הם לבית אבותם למשפחותם.** כבר זכרנו הסבה בהיות עבודת הלויים על פי אהרן ובניו ולהיות עבודת בני קהת יותר נכבדת היתה משמרתם ביד אלעזר להיותו יותר נכבד מאיתמר ועבודת בני גרשון ובני מררי היתה משמרתם ביד איתמר:
@162 והנה היו הלויים פסולין לזאת העבודה בהיותם יותר מבני חמשים שנה להיותם אז חלושי כח מלשאת הדברים הכבדים ובהיותם בפחות משלשים שנה ג"כ היו פסולין כי לא היו שלמי ההויה והמוסר ולזה לא היו עובדים אז באלו העבודות וכבר יתבאר זה ביאור יותר ארוך במה שיבא בג"ה:
@190 **צו את בני ישראל וישלחו מן החנה כל צרוע וכל זב וכל טמא לנפש.** אחר שסדר עניין המחנה במה שיישיר אל השלמות והטוב זכר מה שיסיר ממנו הרע והפסד הסדר וכבר ביארנו בספר ויקרא התועלת המגיע מעניין הטמאות על מדרגותיהם וזכר תחלה שלוחם מן המחנה על מדרגותיהם והתחיל מהחמור וסיים בקל וזה כי הצרוע ישולח חוץ למחנה ישראל כמו שקדם להיות עניין טומאתו יותר רב ההפסד. ולזה אמר בדד ישב מחוץ למחנה מושבו ואולם הטמא מת אין שלוחו כי אם חוץ למחנה שכינה להיות עניינו מעטי ההפסד ואמנם היה זה להעיר על מה שזכרנו בספר ויקרא מענייני הטומאות ולזה מצאנו שגם המת אפשר שיכנס במחנה לויה שנאמ' ויקח משה את עצמות יוסף עמו ולפי שממחנה אח צוה לשלח אלו הטמאים בכללם ואין שם מחנה יחייבנו כולם לצאת חוץ זולת מחנה שכינה. הנה הוא מבואר שהמחנה הנזכר בזה המקום הוא מחנה שכינה וזה גם כן דבר למד מעניינו כי הדברים היו קודם זה בעניין זה המחנה בעבודת בני קהת ובני גרשון ובני מררי והנה זה השלוח ממחנה שכינה הוא מצות עשה ולא הבדיל באלו הטמאות בין זכר לנקבה ובין קטון לגדול וזה אמרו מזכר עד נקבה תשלחו מחוץ למחנה והוא מבואר שהאנדרוגינוס הוא נכלל בזה וכל שכן הטומטום וזה מבואר מעצם אלו הטמאו' ומהלשון הנזכר בזה המקו' וזה כי האנדרוגינוס אם היה כמו ממוצע בין הזכר והנקבה הנה הוא נכלל במה שאמר מזכר ועד נקבה תשלחו כי הזכר והנקבה הם הקצוות והוא מה שביניהם והנה מההדרגה הנזכרת בזה המקו' בעניין אלו הטמאו' למדנו שהזב ישולח חוץ למחנה לויה וזה כי המצורע שזכר ראשונה יחוייב שישולח חוץ לשלש מחנות והטמא מת שזכר באחרונה לא ישולח כי אם חוץ למחנה שכינה הנה יחוייב שיהיה האמצעי ביניהם כיצד טומאתו שהיא יותר קלה מטומאת צרעת ויותר חמורה מטומאת טמא מת ואמרו לא יטמאו את מחניהם אשר אני שוכן בתוכם הוא אזהרה לגדולים שהם טמאים שלא יטמאו המחנה שולחו ממנו אלו הטמאים בכללם והוא המקדש:
@194 **איש או אשה כי יעשו מכל חטאות האדם למעול מעל ביי' וגומ'.** ר"ל בחטאת האדם מה שיחטא האדם לחבירו כמו שגזל ממנו או שכחש בעמיתו בפקדון או בתשומת יד ואמר למעול מעל בה' שכחש בעמיתו ונשבע על שקר וכבר נתבאר בסוף פרשת ויקרא דין זה העניין בכללות ולא נשנית זאת הפרשה בזה המקום כי אם מפני מה שנתחדש בה והוא שאם מת הנגזל ואין לאיש גואל להשיב האשם אליו הנה ישיב האשם עם החומש לכהן ואחר יביא אשמו לכפר עליו כי לא תשלם לו הכפרה בעוד שהוא מחזיק הגזל ומה שאמ' והתודו את חטאתם אשר עשו למדנו שחייב החוטא להתודו' על חטאו ואף על פי שכבר נענש עליו הלא תראה שזה הגוזל שהו' משיב הגזלה ומוסיף חומש ומביא קרבן חייב להתודות ולזה יתבאר שכל חייבי מיתה חייבי' להתודות כדי שתהיה להם כפרה כי העונש לא יכפר עליהם בזולת הווידוי וכבר יתבאר זה גם כן בכללות לפי מה שמצאנו שעל קרבנות היו הבעלים מתוודים וזה מבואר בהרבה מהם והנה החומש אינו מעכב הכפרה שנאמר האשם המושב ליי' לכהן והנה האשם הוא קרבן שנ' והשיב אשמו בראשו וידמה שזכר בזה המקום בזאת הפרשה להסיר הרע מהמחנה אשר יביא למריבה וקטטה והוא שיהיה האדם נזהר מלהחזיק בממון חבירו שלא כדין ולא יסמך על חולשת שכנגדו שאין לו גואלים כי התורה שמה גואליו היותר נכבדים שבישראל להשיב האשם עליהם כדי שלא יהנו לו מעשיו המגונים:
@196 **וראוי** שתדע שהכהן המכפר עליו באיל האשם זוכה בכסף הגזל אם מת הנגזל ואין לו גואל שנאמ' והיה האשם המושב ליי' לכהן מלבד איל הכפורים אשר יכפר בו עליו. למדנו מזה שהכהן הזוכה באיל האשם זוכה עוד בכסף האשם ולזה אמר מלבד וזהו סבת זכותו בו מפני שהוא יכפר בו עליו ולפי שבארנו בפרשת צו באשם שאשר יכפר בו לו יהיה ביאר בכאן שגם הכסף אשר עליו בא האשם יזכה בו הכהן המכפר בו והם אנשי המשמרת המשמשים אז כי כבר נקרא מכפר הראוי לכפר אז כמו שנתבאר במה שקדם.
@197 **וכל תרומה לכל קדשי בני ישראל אשר יקריבו לכהן לו יהיה.** לפי שזכר כסף האשם מחוייב לתת לכהנים העובדים אז זכר בזה המקום הדברים שהם בבחירת הבעלים לתתם לכל כהן שירצו והם הדברים שלא יהיו מצורפים לקרבן כמו תרומה גדולה וחלה ומה שידמה לה מהמתנות שלא יצורפו לקרבן ואולם התרומה לכל קדשי בני ישראל אשר יקריבו לכהן קדש הקדשים שהם להקריב קרבן כמו העניין בחלות תודה הנה תהיה תרומת החלות ההם לכהן המקריב התודה כמו שנזכר בפרשת צו ולזה סמך זה העניין לכסף האשם שזוכה בו הכהן המקריב האשם כי כמו כן יזכה בתרומת חלות התודה ההן המקריב התורה ואולם קדשיו שאין נמשכין לקרבן הם לבעלים לתתם למי שירצו מן הכהנים ולזה אמר איש את קדשיו לו יהיו איש אשר יתן לכהן לו יהיה:
@200 **איש איש כי תשטה אשתו ומעלה בו מעל.** הנה סמך זאת הפרשה לפרשה הקודמת שהיתה תכליתה להסיר מחלוקת וקטטה מישראל בכללם כי זאת הפרשה הוא להסיר הקטטה מהבית הנה שלום הבית קודם לשלום העם לפי מה שנתבאר בפילוסופיא המדינית ואולם התחילה התורה מהשלום היותר נכבד המאוחר בסדר וסיימה בקודם בסדר כמו שנבאר וזה ממנהג התורה במקומות רבים ולפי שבסוף העניין ביאר שהעניין הוא בספק אם נטמא אם לא נטמאה ולברר האמת ישקוה מי המרים המאררים הוא מבואר שצרך שיפורש זה המאמר באופן יסכים אל שיהיה העניין בספק אם נטמאת אם לט נטמאת והנה השטייה והמעילה היא לפי הנראה מזאת הפרשה שעברה על צואתו ונסתרה עם מי שקנא לה ואמר שלא תסתר עמו לחשדו אותה שתזנה עמו וזה מבואר מצד הוראת הגדר כי הרצון בקנוי הנזכר בזאת הפרש הוא מה שזכרנו והנה הקנוי צריך שיהיה ידוע על פי עדים שנאמר וקנא את אשתו ואולם בסתירה יספיק עד אחד שנאמר ועד אין בה והנה התנה בזה בזאת הפרשה תנאים רבים כי לא תשלם השקאתה מי המרים אם נפל אחד מהם. התנאי הראשון הוא שיהיה עניין מעילתה במה שמביא לחשוד שישכב איש אותה אבל אם עברה על צואתו בדברים אחרים אין להם רושם בזה לא ישקנה מי סוטה. והשני הוא שיהיה איש מי שקנא לה בעלה ממנו יתכן כי שישכב איש אותה שכתב זרע ולזה אם היה קטן או סריס או שקנא לה שלא תסתר עם בהמה לא ישקנה מי סוטה. הג' הוא שיהיה נעלם מעיני אישה אם שכב איש אותה אם לא שאם היה יודע בודאי שהיא טמאה או שהיא טהורה לא ישקנה מי סוטה. הרביעי הוא שתסתר עם מי שקנא לה זמן יתכן בו שנטמאה שנאמר ונסתרה והיא נטמאה ואין הרצון בו שנטמאה ודאי שהרי יחוייב שיהיה הדבר בספק כמו שזכרנו אבל ירצה בזה שתסתר עמו שיעור טומאה. החמישי הוא שלא יהיה עד בה שנטמאה שאם העידו עדים שנטמאה בודאי אינה שותה וזהו אמרו ועד אין בה ואפשר שירצה בזה שאע"פ שאין שם עד שלם על הסתירה ר"ל שאין שם שני עדים אבל יש שם עד אחד הנה יביאה עד ההוא לשתות מי סוטה וזה כי עד האחד מביא לשבועה שנאמר לא יקום עד אחד באיש לכל עון ולכל חטאת הוא דאינו קם אבל קם הוא לשבועה כ"ש בזה המקום שרגלים לדבר שהרי קנא לה ונסתרה. הששי הוא שלא תהיה אנוסה וזה שאם נטמאה באונס אין צריך לומ' שאינה שותה שאפילו נטמאה ברצון אינה שותה כיון שנטמאה בודאי אבל אינה אסורה לבעלה מפני זה כיון שהיא אנוסה. ואולם אשת כהן אסורה לו אם נבעלה אפילו באונס כיון שבעלה בעילה אסורה כמו שנתבאר בפרשת אמור אל הכהנים. השביעי הוא שעבר עליו רוח קנאה וקנא את אשו קודם זה באופן שנתבאר ונודע שכבר קנא לה וזה יהיה בשני דרכים האחד שיהיה קנויו לו בסבת חשד טומאה שיש לבעלה עליה. והב' הוא שיקנא לה מזולת שראה בה דבר יביאהו לחשוד אותה ולזה אמר ועבר עליו רוח קנאה וקנא את אשו והיא נטמאה או עבר עליו רוח קנאה וקנא את אשו והיא לא נטמאה ונסתרה אחר זה ונסתפק אם נטמאה אם לא נטמאה. וכבר ידענו שהקנוי הוא קודם לסתירה והוא סבה שתשתה האשה מי סוטה מצד הסתירה כי כבר קרא המנחה מנחת קנאות למדנו שהקנוי הוא הסבה להיותה שותה מפני הסתירה ואילו היה קנוי מאוחר לא יהיה הקנוי סבה לזה כיון שלא חטאה אחר הקנוי אך תהיה הסתירה סבתו ולזאת הסבה גם כן אמר בסוף זאת תורת הקנאות למדנו שהקנוי הוא הסבה להיות בכל זה. ויתבאר זה ביאור שלם ממה שאמ' או עבר עליו רוח קנאה וקנא את אשתו שבזולת סבה אחרת קנא לה. ואם לא עשתה אחר הקנוי דבר למה תשתה ואין שם מה שיביא לחשוב בה שנטמאת והנה כשהיה הענין כן יביא האיש את אשתו אל הכה לברר הענין וכדי שישמע ה' ית' לקולו להראות ברור הענין כן יביא את קרבנה עשירית האפה והנה יהיה קרבנה קמח שעורים ולא סלת מצד גנות הפועל הזה רצתה התורה שיהיה קרבנה היותר פחות שאפשר. ולזה היתה מנחתה באה מן השעורים ומן הקמח שלהם לא מן הסלת והזהירה התורה שיוסר היופי מזאת המנחה ר"ל שלא תהיה בלולה בשמן ולא יתן אצלה לבונה כי היא אינה רק להזכיר עונה אם חטאה. ולזאת הסבה רצתה התורה שיתנו המים הקדושים אל כלי חרש להסיר הכבוד מזה העניין הנעשה בסוטה כדי ליסרה ומזה המקום למדנו כי כל הנעשה בזה העניין ראוי שיעשה בצד היותר מגונה שאפשר והנה יהיו המים קדושים בשיניחום תחלה בכלי שרת:
@205 **ומן העפר אשר יהיה בקרקע המשכן יקח הכהן.** רצה הש' ית' שילקחו העפר מהמקום ההוא הקדוש להוסיף מעלה למי המרים כדי שתירא האשה מהקל בעניין אלו המים. ולזאת הסבה נמחה בהם השם הכתב בקדושה עם שמצד הקדושה יהיה העניין בשתיית אלו המים יותר נאות להעשות בו זה המופת הנפלא כמו שראינו בעניין הארון מצד קדושתו אמר ולא יבואו לראות כבלע את הקדש ומתו וראינו שמתו מאנשי בית שמש כי ראו את אדון יי' ולפי שסמך העפר שיהיה בקרקע המשכן אל המם הקדושים וידענו שהמים יתקדשו לפי שעה כשישימום בכלי שרת כן העפר אם הושם לפי שעה בקרקע המשכן יספיק לעניין מי סוטה ואמר ונתן הכהן אל המים להורות שצריך שיהיו המים תחלה בכלי חרס קודם שישים בהם העפר ולפי שאמר אל המים למדנו שיהיה בו מן העפר שיעור מתיחס לפי המים ולזה הוא מבואר שצריך שיהיה העפר נראה במים בדרך שישאר שם המים על המים ההם כי כבר נקראו מים אחר נתינת העפר בהם אמ' ומחה אל מי המרים ולפי שנקרא מי המרים קודם שימחו בהן האלות ידמה שיהיה משים בהן דבר מר נקראו בעבורו מרי' וכל זה יהיה להוסיף זרות וקושי בזה העניין כדי שיוסרו הנשים מעשות כזאת ולזאת הסבה ג"כ היה מנוולה כשהיה פורע את ראש ואי אפשר שנקראו מרים על שם סופם כי אולי לא נטמאה ולא ישיגנה מרירות מזה ועוד כי אין באלו המים עדין מה שישיגנה מרירות בסבתם כל זמן שלא נמחו בהן האלות:
@206 **והעמיד הכהן את האשה לפני יי'.** ר"ל שהיה מעמיד פניה לפאת מערב שיה בו קדש קדשים והיא היתה לפאת מזרח:
@206 **ופרע את ראש האשה.** כדי לנוולה וראוי שתדע שאם היתה נדה אינה שותה שנאמר ונתן על כפיה את מנחת הזכרון ואם היתה טמאה לא יתכן שתושם המנחה על כפיה. והנה צוה לתת על כפיה את מנחת הזכרון כדי ליגעה להוסיף בזה העניין קושי וזרות והנה היה בזה תועלת עוד כי אולי תחרד מפני הקושי המגיע לה בכל אלו הדברים מהבושת והצער ואולי יביאה זה אל שתודה האמת ולא ימרה השם ונכתב בקדושה על המים ומזה למדו רז"ל שהיו מתחכמים בכל עוז שתודה האמת כדי שלא ימחה השם הנכתב בקדושה על המים אם לא לאשר היא טהורה להראות שלא נטמאה:
@207 **והשביע הכהן את אשה.** לא שתשבע מעצמה כי למעלת הכהן יהיה רושם כשתחול עליה הקללה הזאת אם נטמאה יותר מהרושם המגיע אם תקלל את עצמה:
@207 **ואמר אל האשה אם לא שכב איש אותך ואם לא שטית.** שטייה של טומאה בהיותך תחת אישך עם אי זה שיהיה הנה תהיה נקייה ממי המרים המאררים שלא יזיקו אותך האלות הנחמות בהם והנה הקדים המאמר בהיותה נקייה לפי שזה הוא הראוי לה עם שצריך שתהיה הפתיחה בטוב ואחר זה ביאר איך יהיה העניין אם נטמאת ואמ' ואת כי סטית מעת היותך תחת אישך וכי נטמאת בזאת השטייה עם איזה שיהיה ונתן איש בך את שכבתו מבלעדי אישך:
@209 **יתן יי' אותך לאלה ולשבועה.** למדנו מזה המקום שהקללה עם הזכרת השם הנכבד תקרא שבועת האלה והנה זאת ההשבעה הוא שתאמר אמן אמן ותקבל עליה אלו הקללות אם נטמאה. ר"ל שתהיה ירכה נופלת ובטנה צבה לזה תאמר אמן אמן על שתי אלו הקללות ולמדנו מזה המקום גלגל שבועה כי הוא לא השביע אותה אם נטמאת מאיש זה אבל נטמאת משום איש שבעולם שנאמר ויתן איש בך את שכבתו והנה הזכיר הירך תחלה כי הוא התחיל בעבירה תחלה בפסקה רגליה לזה הנואף ושלמות העבירה היה בבטן ואחר זה הפך הסדר להיות עיקר העבירה בבטן ושם ג"כ יבואו המים תחלה:
@211 **וכתב את האלות.** הוא מאמר הכהן אם לא שכב אותך וגו' עד סוף דברי הכהן. ואמנם אמר האלות האלה כי הכתוב קרא שבועה אמרו אם לא שכב ג"כ קרא שבועה אמרו וכי שטית:
@211 **ומחה אל מי המרים.** למדנו מזה שהוא ראוי שיהיה זה הכתב ראוי להמחות שנ' וכתב ומחה ולפי שנ' אחר זה והשקה את האשה למדנו שהוא ראוי כשיכתוב האלות האלה למחותם אל מי המרי' שיהיה מבואר לו שהיא תשת' את מי המרי' שנ' וכתב ומחה והשק' ולזה הוא מבואר שראוי שנחקור תחלה אם היא טמאה בכל הפני' שאפשר להביאה שתודה זה העניין אם היה אמת כדי שלא יביא העניין בסוף אל שיחה הש' הנכתב בקדושה ולא תשתה:
@213 **והניף את המנח' לפני יי'.** כמשפט שאר המנחו' שטעונו' תנופה:
@213 **והקריב אותה.** את המנחה. למדנו שטעונה הגשה כשאר מנחות:
@214 **וקמץ הכהן מן המנחה את אזכרתה.** הוא שיקח מהקמח מלא קמצו והוא הנקרא אזכרתה מצד היותו למזבח כי אין שם לבונה והקטיר המזבח הקומץ ההו' ואחר ישקה את האשה רוצה לומר כי מה שאמרנו שישקה את האשה את המים לא היה אלא אחר השבעת הכהן אותה באופן הנזכר והנפת המנחה והקטרת הקומץ כמשפט והנה עניין זאת המנחה הוא כאלו יבקש הכהן מהש' יתעלה להזכיר את עונה בשיתן את ירכה נופלת ובטנה צבה כששותה אלו המים:
@215 **והשקה את המים.** לא היה צריך לומר שכבר אמר ואחר ישקה את האשה את המים ולזה יחוייב שלא יהיה הרצון בו לצוות הכהן שישקנה אך יהיה עניינו שאם היה שהשקה אותה הכהן הנה יתברר בהם אם נטמאת אם לא נטמאת והנה למדנו מזה המקום שאם אמרה איני שותה אחר כל זה הרשות בידה כיו שתודה שנטמאה ועוד כי כל עצמם לא באו המים אלא לברר אם נטמאת אם לא נטמאת וכיון שנתברר זה על פיה לא נצטרך להשקותה:
@216 **ואם לא נטמא' האשה וטהורה היא ונקתה.** ר"ל שתנקה ממי המרים המאררים שלא תנזק בהם כמו שאמר הנקי ממי המרים ואמר אחר זה ונזרעה זרע להורות שקודם שיתברר שהיא טהורה אי אפשר שתזרע זרע כי היא אסורה לבעלה כי הדברים ק"ו אם מספק נאסרה לבעלה כ"ש כשהיה ודאי שנטמאה:
@217 **זאת תורת הקנאות וגו'.** שיהיה סבה היותו מקנא לה חשדו אותה ששטתה מעת היותו תחתיו ונטמאה עם איש אחר מצד מה שראה מעניינה עם האיש ההוא אשר יפול בו אצלו ספק שמא היא נטמא כגון שראה שנתייחדה עמו ועמדו כשעור טומאה ולזה קנא לה שלא תסתר עם מי שחשד אותה שזנתה עמו:
@218 **או איש אשר תעבור עליו רוח קנאה.** בזולת סבה אחרת תביאהו אל זה ר"ל שלא ראה בה דבר מגונה אבל עברה עליו רוח קנא וקנא אותה באון הנזכר אין הבדל בין שני אלו הדברים בעניין השקאת הסוטה כיון שקנא לה ונסתרה כי אולי יחשוב חושב כי כשהיה הענין בזה האופן השני שלא יצטרך לגלגל עליה שבועה אם שטית טומאה מעת היותה תחת אישה ולזה הוצרכה התורה להזכיר כי הדין אחד בשני אלו הדברים:
@219 **ונקה האיש מעון.** ר"ל שהאיש ההוא ינקה מעון אל החשד שהיה חושד אשתו כי זה הדבר יסיר החשד ההוא מלבו:
@219 **והאשה ההיא תשא את עונה.** אם נטמאת. ומזה המקום נלמד שיש קצת עון בחשד שיחשד אדם זולתו בדבר שקר או ירצה בזה שהאיש ההוא ינקה מעונש בזאת השקאה וזה שאם לא יקפיד האדם באשתו כשתמעול בו מעל ותשטה טומאה תחתיו הנה באמת ישיגהו עונש על זה מהשם יתעלה כי היא אסורה לו ויהיה עמה באיסור ועל ידי ההשקאה הזאת תשא היא לבדה העונש הראוי ונקה בעלה ממנו וכבר בארו רז"ל שאם נקה האיש ההוא מעון בזה המים בודקין את אשתו לא בזולת זה כעניין לא אפקוד על בנותיכם כי תזנינה ועל כלותיכם כי תנאפנ' גו'. וזה דבר אמתי בלי ספק נלמד אותו מדברי הנביאים והסבה בזה כי הבאת העונש על המרי הוא השגחה מה מהש' יתע' ומי שהוא בתכלית הרוע יסתיר השם יתעלה פניו ממנו ולא יוכיחנו על עונו להשיבו לטוב כמו שאמר מיעד רע ואנכי הסתר אסתיר פני מהם:
@221 **איש או אשה כי יפליא לנדור נדר נזיר להזיר יי'.** ר"ל שיבאר שהוא נודר נדר נזירות ותהיה כונתו לשמים והנה סמך זאת הפרשה לפרשת סוטה שעניינה להסיר הקטטה וההפסד מהבית ולפי שזאת הפרשה הוא להשקיט הריב והפסד מהאד' בעצמו מצד תשוקתו הגופית אשר יביאהו לחטא ושקטת זה הריב הוא ממה שיקדם בסדר בענין שלום הבית ושלום המדינה ולזה שמתהו התורה אחרון בסדר ועניין זאת הפרשה הוא לרפואת מי שיצרו גובר עליו כי הוא צריך שיזיר עצמו מן היין כי היין הוא סבת חזקה להגביר היצר הרע ולהמשך ממנו ההספד והגנות במדות ובעיון ולזה יהיה תועלת עוד בסמיכות זאת הפרשה לפרשת סוטה אמרו ז"ל כל הרואה סוטה בקלקולה יזיר עצמו מן היין והיה זה כן כי היין הוא סבה חזקה להמשך אל המשגל והנה אמר כי יפליא לפי שאמר איש או אשה היה חושב יחשב שלא ינהג זה הדין אלא בגדולים ולזה אמר אחר כן כי יפליא ר"ל שמעת אשר מדרכו שיפליא יכנס בחק זאת המצוה וכן הענין במה שאמר ואיש כי תצא ממנו שכבת זרע. ואשה כי ישכב איש אותה שכבת זרע. ואשה כי תהיה זבה מבשרה שהרצון בכל אלו אפילו קטן או קטנה כשתגיע לזמן שיכן שימצא זה בהם וכן בזה המקום אף על פי שאמר איש או אשה כיון שאמר אחריהם כי יפליא ולא אמר כי ידור נדר למדנו שמעת שיתכן בו שיפליא הוא נכנס בגדר זאת המצוה והנה שערו חכמים שה ישלם בכמו שנה אחת קודם היותו גדול וזה יהיה כשיאסר הקטן מעצמו אמנם האב מזיר את בנו בנזיר קודם זה הזמן אם יראה שיצטרך לו והראיה שהאב מזיר את בנו בנזיר מה שראינו בשמשון ושמואל שנהגו בנזירות מזולת שנדרו בנזיר אבל הסכימו אבותיהם בזה ואם תאמר שגם האם תזיר את בנה בנזיר כמו שראינו בחנה ואשת מנוח אמרנו לך שמצאנו שנדרי הבת תלתה התורה קיומם והפרתם באב ולא באם ומזה המקום נתבאר שאין רושם להם בעניין נדרי זרעה ואיך יהיה זה והנה אינה מושלת גם על נדרי עצמה כי הבעל מיפר נדריה אם ירצה כמו שיתבאר והנה בארה התורה שאם נדר בנזיר סתם כל דיני נזירות חלים עליו והסבה בזה כי עניין הנזירות לא ישלם התועלת בו בזולת כל אלו הדברים הנזכרים בו כמו שנבאר בג"ה אחר באורינו דברי זאת הפרשה. ומזה המקום למדנו שמי שנדר לקיים קצת דיני נזירות יחוייב לו שינהג בכלם כי התורה חייבה זה:
@222 **מיין ושכר יזיר.** ר"ל מכל יין חדש או ישן ונקרא היין ישן שכר להיותו יותר חזק ויותר משכר וכן היין או השכר שנשתנה ונעשה חומץ אסור לנזיר לשתות מהחומץ שנאמר וחומץ שכר לא ישתה ואין צריך לומר החומץ שהוא מן היין בעצמו אבל אפילו נשרו ענבים במים או במשקה אחר אסור לו לשתותו שנאמר וכל משרת ענבים לא ישתה ואין צריך לומר זה שהוא באופן מה מסוג היין אבל גם הענבים אסור לו לאכלם לא הלחים לבד אלא אפילו היבשי' שנ' וענבים לחים ויבשים לא יאכל:
@223 **כל ימי נזרו.** הם הימים שנדר שינהג בהם בנזיר ואפילו הם אלף יום או יותר אלא שאי אפשר שיהיו פחותים משלשים יום כמו שיתבאר בזאת הפרשה והוזהר עוד שלא יאכל והנה החרצנים הם הגרעינים אשר בתוך גרגיר הענבים והזג הוא הקליפה אשר מחוץ וזה כלו להבדילו מגפן היין תכלית ההבדל והנה אמר כל ימי נזרו מכל אשר יעשה מגפן היין ר"ל כל הימים שהוא נפרש מכל אשר יעשה מגפן היין לפי מה שקדם הוא מוזהר שלא יאכל גם הפסולת כמו החרצנים והזגים:
@224 **כל ימי נדר נזרו תער לא יעבור על ראשו.** אין ראוי שתבין שיהיה מותר לו להסיר תערו כדהר אבר זולת התער שהרי ביאר אחר זה שהוא מחוייב לגדל שערו כל ימי נדר נזרו ואמנם דבר הכתוב בחוה ואחר תער ואחר שאר הדברים המסירים השער כלם באזהרה ולפי שאמר לא יעבור על ראשו ולא אמר לא יעביר על ראשו למדנו שהמעביר תער על ראש הזיר עובר בלאו אחד המגלח ואחד המתגלח:
@224 **עד מלאת הימים אשר יזיר להשם קדוש יהיה.** למדנו שאם היה נזיר כל ימיו כמו שמשון אסור לגלח כלל והנה זאת הקדושה הוא שיגדל פרע שער ראשו והנה הרצון בפרע הוא גדול השער כמו שאמ' במצורע וראשו יהיה פרוע שאין הרצון בו גלוי הראש שהרי נאמר ועל שפם יעטה אבל הרצון בו השבתת הגלוח וההשבתה זו הוא גדול השער כי כשלא יגלחוהו יגדל ולפי שגדול השער לא יהיה באופן שיתכן שנאמ' שנשבת הגלוח ממנו בפחות משלשים יום למדנו מזה שהנזירות אינו נוהג פחות משלשים יום כי לא יהיה גדול פרע פחות מזה לפי מה שנתברר מהוראת הגדר ולזה יתבאר שמי שנדר בנזירות יום אחד או פחות משלשים יום הנה הוא חייב שינהיג בנזירות שלשים יום כי אין נזירות פחות משלשים יום אבל אפשר שיהיה יותר לפי מה שנדר שנאמר כל ימי נדרו:
@225 **כל ימי הזירו ליי' על נפש מת לא יבא.** לפי שטמאת מת הוא להעיר על חסרון החמר כמו שזכרנו במה שקדם והיתה הכונה בנזיר שיהיה נבדל מעניינים חמריים שהוא נוטה אליה לפי היכולת הנה מפני זה הוזהר מלהטמא למים ואפילו לקרובים כמו הענין בכהן גדל ואמר לא יטמא להם במותם לפי שאינו מוזהר כי אם על טמאת מת לא לצרעתם ולזיבתם:
@226 **כי נזר אלהיו על ראשו.** אמר זה להורות על קדושתו שנתקדש בה מפני זה הנדר שנדר כשהיה הזירו להשם:
@227 **כל ימי נזרו קדוש הוא ליי'.** הורה בזה שהוא קדוש ליי' ואף על פי שאין לו שער אבל מצד עצמו:
@228 **וכי ימות מת עליו בפתע פתאום.** ר"ל שימות מת אצלו בפתע פתאום בדרך שלא היה יכול להמלט מלהטמא כי מצד מהירות בא המות למת ההוא והיה הנזיר במקו' שנטמא בו בהכרח אם מצד המגע והמשא ואם מצד האהל ובאר בזה שאף על פי שהו' אנוס הוא חייב בתגלחת ובקרבן והוא הדין בשוגג כי השגגה הוא אונס מה והוא מבואר:
@228 **וטמא את ראש נזרו.** הורה שבהתחלת נזירתו היה טהור מזאת הטומאה ולפי שטמא ראש נזרו חייב בתגלחת ובקרבן להוציא מי שבאה לו נזירותו כשהוא טמא כמו שנדר נזירות בקבר שאינו מגלח ומביא קרבן על טמאתו:
@228 **וגלח ראשו ביום טהרתו ביום השביעי יגלחנו.** ר"ל אחר שהזה עליו ממי חטאת בשלישי ובשביעי כדי שיהיה טהור בעת התגלחת שנאמר ביום טהרתו לפיכך אם לא הזה עליו ביו השביעי אינו מגלח עד שיהיה טהור:
@229 **וביום השמיני יביא שתי תורים.** למדנו שהתגלחת קודם להבאת הקרבן כי הוא בא לקדש את ראשו שנטמא. ולא יתכן שיקדש ראשו אם לא יוסר תחלה השער שנטמא:
@229 **שתי תורים או שני בני יונה.** ולא תור ובן יונה:
@229 **אל הכהן אל פתח אהל מועד.** למדנו שהעלים מיטפלין בהבאתם עד שיביאם אל הכהן אל פתח אהל מועד:
@230 **ועשה הכהן אחד לחטאת ואחד לעולה.** למדנו מזה שחטאת קודם לעולה וכבר בארנו סבת זה בפרשת ויקרא:
@230 **וכפר עליו מאשר חטא על הנפש.** רוצה לומר שנטמא למת:
@231 **והזיר ליי' את ימי נזרו.** ר"ל מכאן ואילם ולמדנו מזה שאין הבאת האשם מעכב נזירותו:
@231 **והביא כבש בן שנתו לאשם.** להשלים כפרתו:
@231 **והימים הראשונים יפלו כי טמא נזרו.** ר"ל הימים שנהג בהם נזירות לפי שכבר טמא נזרו וישוב להתחיל ימי מניין נזירותו ואין מתנאי הימים הראשונים שישארו ימים אחרונים מנזירותו כי כבר יקראו ימים ראשונים אף על פי שלא נשאר אלא יום אחד או קצתו:
@232 **וזאת תורת הנזיר ביום מלאת ימי נזרו יביא אותו אל פתח אהל מועד.** ר"ל יביא את עצמו או אפשר שהרצון בזה שאם לא רצה לבא שם להביא קרבנותיו יכריחוהו על זה כדי שיביא קרבנותיו שהוא מחוייב בהם וכבר נתבאר סדר מעשה הקרבנות במה שקדם ושהחטאת הוא קודם לעולה ויביא עשר מצות ועשר רקיקין כמו שזכרנו בלחמי תודה והנה הבאת קרבנותיו קודם לתגלחתו בהפך מה שהיה בתגלחת הטומאה:
@237 **וגלח הנזיר פתח אהל מועד את ראש נזרו.** אי אפשר לומר שיגלח הנזיר בפתח אהל מועד ראש נזרו שנאמר ולקח את שער ראש נזרו ונתן על האש אשר תחת זבח השלמי' וזה מורה שאצל מקום האש שתחת זבח השלמים יהיה התגלחת והוא מבואר שאין הבעלים מבשלים השלמים במקדש ועוד שזה יהיה בזיון לאהל מועד שיגלח הנזיר את ראשו שם וכבר דקדקה התורה שלא לעלות במעלות על המזבח וכ"ש שראוי להשמר שם מהתגלחת:
@238 **ולקח הכהן את זרוע בשלה מן האיל.** רוצה לומר אחר שהוסר ממנו חזה ושוק שהוא לכהן יבשלו האיל בכללו ועמו יתבשל הזרוע שהוא לכהן ואף על פי שכבר נתבשל הזרוע שהוא לכהנים עם השאר שהוא לבעלים ולא נאסר מה שהוא לבעלים למדנו שבכמו זה השיעור לא יאסר הקדש מה שנתבשל עמו אבל בפחות מזה השיעור הנה יאסר השאר לבעלים והנה שערו ובמי' שהזרוע אחד מששים הוא מהשאר. ולזה למדנו מזה שמין במינו שנתבשלו יחד היה שיעורו בששים:
@238 **וחלת מצה אחת.** למדנו מזה שאם היתה פרוסה פסולה לפי שאינה אחת וכן העניין אם היתה חסרה וכן העניין ברקיק המצה:
@238 **ונתן על כפי הנזיר אחר התגלחו את נזרו.** לא היה צריך לומר אחר התגלחו את נזרו כי הזרוע הוא בשלה וכבר הושם באש שנתבשלה בו שער ראש הנזיר כמו שקדם ואולם בא ללמדנו כי זה לבד יעשה מענין קרבנותיו קודם תגלחתו לא הבאת קרבנותיו והסבה כשהיה זאת התגלחת אחר הבאת הקרבנות כי השיער הוא קדוש שכבר גדלו ליי' ולזה ראוי שיהיה עמו עם שלמות הבאת הקרבנות והסבה בגדול זה השער ליי' להעיר שגם במותרות החומר נשתדל שנשתמש בהם לעבודת השם יתע' וזה יהיה כשיכבוש תאות החומר כפי היכולת וישתמש בהכרחי לבד לעבודת השם יתעלה ולזה התבשל באש שנשרף בו השיער איל הנזיר עם הזרוע שהוא לכהן:
@239 **והניף אותם הכהן תנופה לפני יי'.** כבר התבאר במה שקדם בספר ויקרא שהתנופה הוא כשיהיה מוליך ומביא מעלה ומוריד ושם התבארה הסבה בזה:
@239 **ואחר ישתה הנזיר יין.** למדנו מזה שקודם זה הוא אסור בשתיית היין כי כל אלו הדברים יש להם מבא ברפואתו על תגבורת יצרו כמו שביארנו ולא ישוב לשתיית היין כי אם אחר השלם אלו דברים:
@240 **זאת תורת הנזיר אשר ידור ליי'.** רוצה לומר שהוא צריך שינהג איסור בכל הדברים שהנזיר מהם כאלו תאמר שיהיה נפרש מכל אשר יעשה מגפן היין ומהטמא למתי' ומלגלח ראשו:
@240 **קרבנו ליי' על נדרו.** רוצה לומר שזאת קרבנו ליי' על נדרו שאי אפשר לו לשנות דבר בדבר הקרבנות לא לתוספ' ולא לגרעון:
@240 **מלבד אשר תשיג ידו.** ר"ל שאם רצה להקריב לו בנדר ונדבה אפשר לו אבל לא יהיה קרבנו ליי' על נדרו זולת מה שנזכר והם הכבש והכבשה האיל כפי נדרו אשר ידור כן יעשה על תורת נזרו ר"ל שאם נדר נזירות הרבה צריך שינהג בכל אחד מהם כמו זה המנהג ואחר שזכר מה שיביא להסיר מלחמת האדם עם נפשו ויסיר הריב והקטטה וההפסד מהבית והעם בכללו וזכר זאת הפרשה והוא ברכת כהנים שהיא מעירה הערה נפלאה על עניין השלמות והשלום האמתי:
@242 **דבר אל אהרן ואל בניו.** למדנו שזאת המצוה היא לאהרן לבניו לבד והוא לברך את ישראל בכל יום בזה האופן הנזכר בזה המקום והנה לעומק זאת הערה לא תרגם בה אנקלוס דבר:
@242 **כה תברכו את בני ישראל.** רוצה לומר בזה הלשון שהו' לשון הקדש והיה זה כן כי אם יעתיקו זה המאמר ללשון אחר אולי תפסד הכונה ותבלבל ובשם המפורש שנאמר ושמו את שמי על בני ישראל ואני אברכם וכבר נתבאר שזאת הברכה היא בעמידה ממה שנאמר בפרשת כי תבא עלה יעמדו לברך גומ'. ואם בברכה ההיא דקדקה התורה שתהיה בעמידה כ"ש בזאת הברכה למעלתה וכבר נתבאר במה שדם שאהרן ברך בנשיאות כפים שנאמר וישא אהרן את ידיו אל העם ויברכם ולפי שזה הדבור נאמר יחד לאהרן ולבניו למדנו שבתאר אחד יהיה זאת הברכה מהם ולזה יחוייב שתהיה ברכת כהנים בנשיאות כפים אלא שהכהן גדול לא היה מגביה ידו למעלה מהציץ כי בציץ היה כתוב קדש ליי' ואם היה מגביה ידו למעלה יביא לחשוב שיהיה שם גבוה על השם יתעלה וזה בתכלית מהכפירה בו יתע' ולזה היו ידיו למטה מהציץ והנה ההערה בנשיאות כפים הוא להעיר שאם נשא לבבנו אל השם להשכיל ולדעת אותו כפי היכולת נתיישר לזאת הברכה והנה זאת הברכה צריך שתהיה פנים כנגד פנים שנאמר אמור להם ומדר המספר עם חברו שיהיו פניו כנגד פניו והיה זה כן כדי שיתבוננו ישראל בענין זאת הברכה ובנשיאות כפי הכהנים:
@243 **יברכך יי' וישמרך.** הנה עניין הברכה היא תוספת בטוב והשמירה הוא התמדת הטוב והנה הרצון בו לפי מה שאחשוב שבעת החיים תבא לנו הברכה השם יתע' בהשלמת הנפש המשכלת אשר נבראת בזולת שום שלמות וחכמה כמו שנתבאר בטבעיות ומהשפע השופע להם מה' יתעלה תשיב המושכלו' ובזה יתמיד להוסיף לה שלמות מה שהתמידו החיים האנושית ואחר המות יתמיד לה בזה השלמות ותשאר נצחיית בקיום השגותיה שהשיגה בחיים ולא תשיג זולת מה שהשיגה בחיים וזהו על דרך מה שאמר שלמה בשכבך תשמור עליך וגו'. או יהיה הרצון בזה יברכך יי' מברכות הכתובות בתורה והוא מה שאמר ברוך אתה בעיר וברוך אתה בשדה ובשאר הברכות הנמשכות לה וישמרך מכל רע והביאור הראשון נראה לנו יותר:
@244 **יאר יי' פניו אליך ויחונך.** ר"ל שזאת הברכה שזכרנו הוא משם יתעלה ואף על פי שכבר נשיג המוכלות באמצעות הרגש כאשר יכפל בדבר כמו שנתבאר בחכמת הטבע הנה לא יספיק זה לקנות המושכלו' אם לא נעזר בזה כשפע השופע מהשם יתע' באמצעות השכל הפועל כמו שבארנו בראשון מספר מלחמו' השם וזה השפע כנה אותו בזה המקום בהארת השם יתעלה פנים אלינו והנה פניו הם השכלים הנפרדים כי הם הנמצאות היותר נכבדות אשר השגחת השם יתעלה ופניו ראוי שתהיה בהם והארת פניו הוא השפע השופע באמצעותם שיכין לנו הדרך להשיג המוכלות על אמתתם ואמר שה איננו מהש' יתע' על צד החיוב ר"ל שאינו מחוייב כשנכפל לנו ההרגש בדבר מה שיגיע לנו המושכל תכף אבל ישפיע זה מהש' יתעלה על צד החסד והחנינה שנ' ויחונך וזאת היא פנה גדולה מפנות התוריות וזה שאם אמרנו שיהיה מה שישפע מהשם יתע' שופע בחיוב היה מחוייב שישפע ממנו זה המציאות תמיד ויהיה אם כן העולם קדום אבל ראוי שנאמין שמה שישפע מהשם יתעלה שופע על צד החנינה והחסד לא על צד החיוב ולזה יתכן שישפע ממנו המציאות תמיד בעת מה ולא ישפע בעת אחרת ואפשר שאמר יברכך על מה שישפע לנו מהחכמה אשר אצלנו וההתחלות מן החוש כי כמו זה יקרא ברכה כשישיג השגתינו החלושה השגה שלמה ואמר יאר על מה שישפיע לנו שאין אצלנו ההתחלות כמו הענין בנבואה וקרא זה העניין חנינה כי על צד החנינה יגיע זה ממנו כמו שבארנו בשני מספר מלחמות השם:
@245 **ישא יי' פניו אליך וישם לך שלום.** ר"ל כי כשתהיה במקומות הסכנה והטעות בעיון הנה יגיע מחסד הש' יתע' שיביא אליך השפע האלהי באמצעות פניו והם המלאכים:
@245 **וישם לך שלום.** בדעות וכן גם כן ישים לך שלום בעניינים הגופיים מצד דבקות ההשגחה האלהית בך:
@246 **ושמו את שמי על בני ישראל וגו'.** ר"ל שהכהנים יסדרו סוד שמי על בני ישראל באופן שידעוהו כלם ואז אברכם מצד דבקות השגחתי בהם:
@247 **ויהי ביום כלות משה להקים וגו'.** הנה זה היה בסוף שבעת ימי המלואים שנזכרו בפרשת צו והנה נזכר בפרשה אלא פקודי כי בשנה השנית באחת לחדש ניסן הוקם המשכן ר"ל שנשלמה אז הקמתו ונדמה שזאת ההקמה היתה מה שהקים משה את המשכן וקדשו עם כל כליו והמזבח וכל כליו כשמשח אותם בשמן המשחה ביום ראשון משבעה ימי המלואים וקדשם בדרך ששמש בהם ז' ימי המלואים כי אז נשלם לו קיומו על עניינו לדורות ע"י אהרן ובניו כי כהונת משה רבינו ע"ה היתה לפי שעה וכבר פירשו בספרי שבכל יום מימי המלואים היה משה מפרק המשכן אחר שהעמידו ומשחו וגם ביום שמיני הוצרך להקימו לזאת הסבה ואפשר שיחזק זה הפירוש מה שאמ' בסוף פרשת צו כאשר עשה ביום הזה צוה השם לעשות לכפר עליכם כי זה יורה כי כמו שעשה משה ביום ראשון עשה בכל ימי המלואים ולפי שביום הראשון הוקם המשכן ומשחו וקדשו עם כל כליו הנה יראה מזה שהקימו בכל אחד מהימים ההם אלא שכבר יראה לפי הפשט שלא שב לעשות משה בשאר ימי המלואים כי אם מה שהיה לכפר עליהם והם קרבנות אהרן ובניו ודי במשיחת פעם אחת המשכן וכליו והמזבח וכליו לקדשם לפי מה שיראה מהגשת הכלים הנעשים במקדש והנה אפשר שנאמר שנמשחו לכל שבעת ימי המילואים כמו שנבאר אחר זה והנה אמר וימשחם ויקדש להורות כי לא נשלמה הקדושה עד שנמשחו כלם וזה מחוייב כי כל אלו הדברים הם מתאחדים לתכלי' אחת כמו שביארנו מעניני' ולזה אפשר שיתקדשו לחצאין והמשל כי השלחן בעצמו אי אפשר שתהיה לו קדוש' השלחן שהו' חלק מענייני המקדש אם לא בשילות לשאר הדברים אשר שם והנה יתבאר ממה שאמר שאי אפשר שנפר' ביום כלות משה ביום הראשון משבעת ימי המילואי' וזה שקרבנות הנשיאים נעשו תכף ובשבעת ימי המלואים לא כפר משה רק על אהרן ובניו ואח"כ כפר אהרן ובניו על כל ישראל ולזה יחוייב שיהיה העניין ביום השמיני והנה הראשון שהתחילה ממנו עבודת אהרן ובניו היה בראש חדש ניסן והוא היה ראש השנה לעניין עבודת אהל מועד ולזה היו השקלים נגבים אז.
@248 והנה הביאו הנשיאים קרבנם לפני ה' שש עגלות צב לנדבה וי"ב בקר והתנדבו אותם בעבור הלוים שישאו בהם המקדש וכליו ולא רצה משה לקבל מהן זה לולי שצוהו השם יתעלה על זה והנה הרצון בעגלות צב עגלות מהיפות לכבוד הדברים שהיו משימים בהם:
@254 **ביד איתמר בן אהרן הכהן.** שב לבני גרשון ולבני מררי ולבני קהת לא נתן דבר כי עבודת הקדש עליהם בכתף ישאו באה המצוה להם בזה המקום שישאו משאם בכתף מצד קדושת הארון ויתר הדברים שהיו נושאים וכבר נתבאר שזה המאמר מצוה ממה שאמר בספר דברי הימים ויקרא דוד לצדוק ולאביתר הכהן וגו'. ויעלו את ארון השם ואלה פקודתם וגו'. כאשר צוה השם אלהי ישראל ולא מצאנו מקום שצוה בו השם יתעלה שישאו משאם בכתף לולי זה המקום ובכאן שגג דוד בהביאו אליו ארון האלהים שהרכיבוהו על העגלה חדשה והיה זה סבה אל שפרץ השם פרץ בעזא ולזה שב בסוף להביאו בכתף ע"י הלויים ולזה אמר כי למבראשונה לא אתם פרץ יי' וגו':
@256 **ויקרבו הנשיאים את חנוכת המזבח וגו'.** הנה יבאר מזה שכבר נמשח בכל אחד מימי המלואים וביום השמיני כמו שאמרו ז"ל או ירצה ביום המשח אותו ביום שנשלם עניין משיחתו בצד שיתכן שיקריבו בו קרבנו לכפר על ישר' כמו שקד' כי בימי המלואים לא כפר משה רק על אהרן ובניו והנה הקריבו הנשיאים קרבנם אצל המזבח בדרך שוה ר"ל שהסכימו כלם בכל אחד מהמינים שהביאו כאשר הביא זה הביא זה וכן הענין בעגלות והבקר כי כן היה ראוי בדרך שלא יהיה התפאר האחד על חברו ועל פי הגבורה הסכים משה שיקריבו קרבנם כל אחד ביומו והנה הביאו אלה הקרבנות בסדור כדרך שהיו נוסעים ולזה היתה ההתחלה משבט יהודה ואחריו הקריבו שני הנשיאים אשר בדגלו לסדרן וכן בזה הדרך היה סדר אלו ההקרבות. והנה האריך בזכירת זה הקרבן בכל נשיא ונשיא להורות שכלם היו שוים בזה לא היה יתרון לאחד על חבירו שכל אחד מהן התעורר מעצמו לזאת הנדבה והנה היה זה העניין חדוש שהתנדבו קטרת ואין היחיד מתנדב קטרת ושיהיה זה הקרבן דוחה את השבת ואין קרבן יחיד דוחה את השבת כ"ש כשהיה נדבה שאין נדבה דוחה את השבת אלא שכבר היה זה על פי הגבורה והנה החטאת לא נצטרך לכפר עליהם לפי שכבר כפר אהרן בעדו ובעד ביתו ובעד העם כמו שנזכר בפרשת שמיני ולזה אמרו רז"ל שהיה בא לכפר על קבר התהום כי השעירים מצאנו בהם שהן באי' לכפר על הטמאות ועל מדרגותיהם כמו שביארנו במה שקדם ונמשך מן ההארכה בזה הספור תועלת כבר זכרנוהו במה שקדם:
@335 **ובבא משה אל אהל מועד וגו'.** הרצון בזה שבכל עת שהיה רוצה משה שתבא לו הנבואה היה בא אל אהל מועד והיה שומע את הקול מדבר אליו מעל הכפרת מבין שני הכרובים לפרסם לישראל עניין הנבואה ולזה אמר בפרשת שמיני כי היום יי' נראה אליכם והיה נראה כבוד השם לכל ישראל בדרך שיהיו מרגישים שמשם היתה הנבואה באה למשה והנה עניין הרובים היה מעיר גם כן לחכמים על אפשרות הגעת הנבואה ואיך תגיע כמו שביארנו במה שקדם ואמנם היו צריכים ההמון לזה הפרסום כדי שיתאמת יותר בלבבם עניין הנבואה.
@337 **בהעלותך את הנרות וגו'.** אע"פ שנ' דבר אל אהרן ויעש כן אהרן אין ראוי שתחשוב שדקדק' התור' להיות זאת העבודה בכהן גדול שכבר התבאר בפרשת ואתה תצוה שאין העלאת הנרו' בכהן גדול לבדו שנ' יערוך אותו אהרן ובניו מערב ועד בקר וכן ראוי שתבין הענין בקטרת שנאמר בפרשת תרומה והקטיר עליו אהרן קטרת סמים בבקר בבקר בהטיבו הנרות וגומר. למדנו שהראוי להדלקת המנורה ראוי להקטרת הקטרת למדנו מזה המקום שהוא ראוי שיהיו הנרות דולקות תמיד ואולם מה שנאמר בפרשת ואתה תצוה מערב ועד בקר אינו אלא לשעור השמן שישימו בו מה שיספיק מערב עד בקר ושיערו חכמים חצי לוג:
@337 **אל מול פני המנורה.** הוא לאחורי פני המנורה כדי שיהיו הנרות דולקות כנגד הארון וזה כי פני המנור היה לפני הכהן ואחוריה לצד הארון וזה אמנ' היה כשהיו נרותיה פונים לצד הנר האמצעי והנר האמצעי לצד הארון:
@339 **וזה מעשה המנורה מקשה זהב וגו' מקש' היא.** למדנו שאין מתנאה שתהיה זהב אלא שתהיה מקשה ולזה יחוייב שתהיה של מתכת והתבאר עוד שלא יחוייב שיהיו בה הפרחים והנמשך להם אלא כשהיתה של זהב שנאמ' מקשה זהב עד יריכה עד פרחה מקשה היא למדנו כי כשהיתה של זהב יצטרך בה פרח וכשלא היתה של זהב לא תצטרך בה זאת הצורה ר"ל גביעיה כפתוריה ופרחיה והסבה לפי שזאת המנורה הנכבדת אשר בזה הציור לא תשלם אלא כשהיתה המנורה של זהב כי הזהב לחשיבותו יביא להעיר על שהוא משל לדבר הנכבד אשר בעבורו נעשה זה הציור ידמה שכבר באה זאת הפרשה בזה המקום לפי שכבר זכר היות הקול מדבר עם משה מעל הכפרת מבין שני הכרובים להישיר איך יתכן שתגיע הנבואה לנביא ולפי שעניין המנור' מישיר בזה כמו שביארנו בהמ שקדם בעניין המנורה סמך זאת הפרשה עניין המנורה:
@341 **קח אל הלוי' מתוך בני ישראל.** הנה מפני שרצה להכניס הלוים בזאת הקדושה שהיו מיוחדים לעבוד עבודתם במקדש צוה הש"י לטהרם ראשונה ולכפר עליהם כדי שתתיישב בלב ישראל יותר ענין קדושתם והנה הזו עליהם מי חטאת לטהרם כאלו היו טמאי מת וזה לאות שנשרפה אז הפרה האדומה הנזכרת במה שיבא וידמה שעש זה להעירם על מה שהיתה בו ההערה בזה בטהרה טומאת מת לפי מה שנתבאר מדברינו בספר ויקרא לזאת הסבה צוה אותם לגלח את כל ערם כאלו יעירם זה שיעזבו את הדברים החמריים כפי היכולת וישתדלו בעבודת ה' יתעלה. והנה צוה שיסמכו כל ישראל את ידיהם על הלויים ושיניפם אהרן תנופה לפני יי' כאלו הקריבום ישראל ליי' והיו קדש במדרגת הקרבן כי הם היו ליי' תחת פטרת כל רחם כמו שזכר ולזה צוה לטהרם להניפם תנופה:
@346 **והיו לעבוד את עבודת יי'.** הנה עבודתם היה למשא ולשמור משמרת ולשורר בעת הקרבנות כמו שיתבאר במה שיבא:
@347 **והלויים יסמכו את ידיהם על ראש הפרים.** לכפר על חטאיהם:
@354 **לעבוד את עבודת בני ישראל באהל מועד.** הוא משא המקדש וכליו ושמירת המקדש ולכפר על בני ישראל אפשר שהוא רמז לשיר שהיו משוררים הלויים בעת עשיית הקרבן או יהיה הכונה בו כי בעבודתם זאת יכפרו על בני ישראל שלא יהיה בהם נגף בגשת בני ישראל אל הקדש כי הלויים ישמרום שלא יגשו אל הקדש עם שבראות ישראל כי הענין נעשה בשלמות ע"י הלויים לא תשיגם שגגה לגשת אל הקדש לשאת הכלים הקדושי':
@359 **וזאת אשר ללויי' מכן חמש ועשרים שנה ומעלה יבא לצבא צבא לעבודת אוהל מועד.** ידמה שתהיה בזה סתירה לפי מה שזכר מזה העניין בפרשת נשא שמנה הלויים מבן שלשים שנה ועד בן חמשים שנה ובאר שם שאלו הם כל הבאים לצבא בעבודת אהל מועד ואמנ' התירו רז"ל זה הספק כשאמרו שאלו החמש שנים אשר מעשרים וחמש שנה עד שלשים שנה יבואו הלוים לצבא צבא בעניין עבודת אהל מועד לא לעבוד אבל התקבצו ללמוד סדר עבודתם איך תהיה וכשיהיו בני שלשים שנה יעבדו עם אחיהם:
@360 **ומבני חמשים שנה ישוב מצבא העבודה ולא יעבוד עוד.** ר"ל עבודת משא כי בסבת זקנתו יהיה חלוש. ואמנם ישרת את אחיו באהל מועד לשמור משמרת ר"ל לשמור המקדש על האופן שנבא' בפרשת קרח בגזרת הצור:
@361 **ועבודה לא יעבוד.** ר"ל עבודת המשא ומזה המקום נתבאר ששנים פוסלים בלויים ולא מומין ואמנם בכהנים נזכר שהמומין פוסלים בהם ולא השנים:
@363 **ויעשו בני ישראל את הפסח במועדו.** למדנו מזה שהפסח דוחה את השבת:
@364 **בכל חקותיו ובכל משפטיו תעשו אותו.** חקות אלו הדברים שבגוף הפסח כמו שראינו בפרשת בא אל פרעה שאמר זאת חקת הפסח ולא זכר אחר זה כי אם הדברים שבגוף הפסח ואלו הדברים הם שיהיה תמים זכר בן שנה ושיאכל בבית אחת ושלא ישברו בו עצם ושלא יאכל ממנו בן נכר ושאר מה שדומ' לזה ואולם משפטיו הם המצות הנלוות לו כמו מצה ובעור חמץ:
@367 **ויהי אנשים אשר היו טמאים לנפש אדם וגו'.** כבר ביארנו בפרשת בא אל פרעה שלא ישחט הפסח על מי שאי אפשר לו לאכלו ולזה הוא מבואר שאם לא היה אפשר שיטהרו בערב לעת אכילת הפסח לא היו צריכים לשאל למה נגרע לבלתי הקריב את קרבן השם במועדו ולא יה מסופק זה למשה עד שיצטרך לומר עמדו ואשמעה מה יצוה ה' לכם ולזה הוא מבואר שכבר חל שביעי שלהם בערב הפסח והיו ראויי' לאכול את הפסח בזמן אכילתו ועם כל זה נדחו לפסח שני לפי שלא היו ראוים בעת שחיטת הפסח ולפי שאמר אשר היו טמאים לנפש אדם ולא אמר טמאים במוחלט למדנו שלא ינהג זה הדין בשאר הטמאות כמו זבים וזבות ובועלי נדות ושאר הטמאות וזה שכיון שיכולים לאכול מהפסח בערב בשעת אכילתו הנה ישחט עליהם הפסח ואף על פי שעדיין לא טהרו והנה נלמד ממה שאמר ויהי אנשי' אשר היו טמאים וממה שאמר אחר זה איש איש כי יהיה טמא וגו' כי לא ינהג זה הדין שידחו הטמאי' לנפש לפסח שני אלא כשהיו יחידים ואמנם אם היו רוב הקהל טמאי מת אינם נדחים לפסח שני אבל שוחטים את הפסח עליהם בטמאה ואוכלים אותו אפילו בטמאה ר"ל אף על פי שאי אפשר שיטהרו בערב והנה לא יותר לשחוט את הפסח על הטמאים ולאכול אותו בטמאה אלא כשיהיו הטמאים טמאים מטמאת מת והראיה על שנדחית הטמאה בצבור מה שאמר בספר דברי הימים על הפסח שעש חזקיה בחדש השני כי רבת הקהל אשר לא נתקדשו והלוים על שחיטת הפסחים לכל לא טהור כי מרבית העם מאפרים וממנשה ויששכר וזבולון לא הטהרו ונאמר כי אכלו את הפסח בערב בלא ככתוב לפי שחזקיה וסיעתו דחו את הפסח לפסח שני שנאמר ויועץ המלך ושריו לכל הקהל בירושלים לעשות הפסח בחדש השני כי לא יכלו לעשותו בעת ההיא כי הכהנים לא התקדשו למדנו מזה ששגגתם היתה על שדחו את הפסח מפני הטומאה והראי' שלא תדחה הטומאה מפני הפסח כשהיו רוב הצבור טמאי' אלא בטמאת מת לפי שכבר אמר איש איש כי יהיה טמא לנפש ולא נצטרך לזה התנאי בזה המקום לבאר ששאר הטמאים אינם נדחים לפסח שני שכבר נתבאר במה שאמר אחר זה והאיש אשר הוא טהור ובדרך לא היה וחדל מעשות הפסח אבל מי שאינו טהור בפסח ראשון יחדל מעשיית הפסח וכיון שלא עשה הפסח במועדו ידחה לפסח שני שאפילו הגר שהתגייר בין פסח ראשון לפסח שני עוש' פסח שני כמו שיתבאר כי פסח שני הוא רגל בפני עצמו ואין תשלומי ראשון ולזה ינהג בו מי שלא היה חייב בפסח ראשון ואולם נצטרך לזה התנאי שיהיה טמא מת להודיע שמה שיתחייב מזה הוא שהאיש נדחה לפסח שני מפני טומאת מת ואין הצבור נדחין לפסח שני מפני טומאת מת ולא נלמד מזה שאר הטמאו' כי בטומאת מת הקלה התורה לבד בזה עם שטמאתו יותר קלה כמו שזכרנו בפרשת וישלחו מן המחנה כל צרוע וכל זב וכל טמא לנפש:
@371 **איש איש כי יהיה טמא לנפש.** הוא הדין לשאר הטמאות שידחה עליהם לפסח שני כמו שביארנו ממה שאמר בסוף והאיש אשר הוא טהור ואולם אמר טמא לנפש כי עליו הית' השאלה ובעבור מה שזכרנו שיתבאר מזה שדחויה טומאת מת בצבור:
@371 **או בדרך רחוקה.** לפי שהשאלה היתה למשה ביום י"ד כמו שאמר ויקרבו לפני משה ולפני אהרן ביום ההוא למדנו שדרך רחוקה תוגבל לפי היום ההוא שהוא בתכלית מה שאפשר מעת הזריחה עד חצות שנכנס זמן חיוב שחיטת הפסח ולזה שיערו חכמים שזה השעור ההוא ט"ו מיל כי כן מהלך אדם בינוני מעת הזריחה עד חצות ואם היה רחוק מירושלם בעת הזריחה ביום י"ד יותר מט"ו מיל הנה הוא נדחה לפסח שני:
@373 **ככל חקת הפסח יעשו.** אלו המצות שבגופו כמו שביארנו ולא תנהג בו מצוה שאינה בגופו אלא אכילתו על מצות ומרורים:
@374 **והאיש אשר הוא טהור ובדרך לא היה.** ר"ל בפסח ראשון:
@374 **וחדל מעשות הפסח.** רוצה לומר במוחלט שלא עשה לא פסח ראשון ולא פסח שני הנה הוא בכרת אם עשה זה במזיד באי זה שיהיה מהם שהרי חדל מעשות הפסח אבל אם לא היה מזיד באחד מהן פטור מן הכרת ואולם בטמא או שהיה בדרך רחוקה בפסח ראשון ולא נזכר כרת אפילו הזיד בשני וזה מבואר מלשון התורה:
@374 **כי קרבן השם לא הקריב במועדו.** לפי שזה נאמר גם כן בפסח שני כמו שזכרנו למדנו שפסח שני דוחה שבת כמו שנאמר בו במועדו:
@375 **וכי יגור אתכם גר ועשה פסח ליי'.** ר"ל פסח שני כיון שלא נתחייב בראשון שהרי לא היה גר בראשון ולא נתחייב בו:
@375 **כחוקת הפסח וכמשפטו.** חקת הפסח אלו המצות שבגופו כמו שזכרנו וכמשפטו הוא מצות על מצות ומרורים ולזה לא נאמר וככל משפטיו כי לא היה נוהג בפסח שני ממשפט הפסח כי אם אכילתו על מצות ומרורים. מכאן למדנו שהקטן לא נתחייב בראשון והגדיל כשבא שני חייב בפסח שני. וראוי שתדע שארש אירע בו פסול אחר שנשחט עליו הפסח פטור מפסח שני שהרי הקריב קרבן השם במועדו. יש לשואל שישאל איך עשו בני ישראל את הפסח בשנה השנית והנה לא מלו בניהם הילודים במדבר כמו שנזכר בספר יהושע והנה מילת בניהם היתה מעכבת אותם משחיטת הפסח כמו שביארנו בפרשת בא אל פרעה. ואי אפשר שלא נולדו רבים בשנה הראשונה והנה היתר זה הספק הוא לפי דעתי כי בשנה הראשונה לא ידעו ממדבר סיני אך עמדו שם ימים רבים כמו שזכר בזאת הפרשה כי בשנה השני' בחודש השני בעשרים לחדש נסעו ממדבר סיני. ולפי שעמדו שם ימים רבים יתכן שמלו שם הילודים במדבר אז ולזה היה אפשר להם לעשות. ואמנם מן אז והנה לא היה אפשר למול כי לא נודע להם שיתעכבו שם במקום אחד שלשה ימים ולזה לא מלו עד בא יהושע:
@376 **וביום הקים את המשכן כסה הענן.** אחשוב שהרצון בזה שתכף שהוקם המשכן בשלמות על יד משה כסה הענן את המשכן וזה אמנם היה אחר שבעת ימי המלואים ביום השמיני כמו שאמר שם כי היום יי' נראה אליכם. וזה המופת אמנם התמיד אחר זה בזה האופן שזכר הענן יכסנו יומם ומראה אש לילה וכאשר רצה השם יתעלה שיסעו נסע הענן מעל המשכן וכאשר ישכון הענן שם יחנו בני ישראל. ובזה האופן היו חונים ונוסעים על פי יי' והנה ביאר שפעם ישכון שם הענן זמן רב ופעם זמן מועט ולפי הזמן ההוא היו חונים ונוסעים. והנה ביאר בסוף הענין שלא יסעו עם כל זה כי אם על פי יי' שהיה שולח ביד משה וכאשר היה מצוה אותם משה היו נוסעים בסדור מוגבל על האופן הנזכר אחר זה:
@386 **עשה לך שתי חצוצרות כסף מקשה תעשה אותם.** התורה הקפידה שתהיו שתים לא פחות ולא יותר ושתהיינה של כסף לא ממתכת אחר ושתהיינה מסכימות אחת אל אחת כי האחדים הנמנים הם מסכימים ושתהיינה מקשה לכבוד השם יתע' ולכבוד הצבור והנה היה השתמשותם לדברים שהיו נוהגים אז ולדברים שהם נוהגים לדורות אמנם הדברים שהם נוהגים או לבד הוא מה שהיו משמשים בהם למקרא העדה ולמסע המחנות ושאר הדברים הנזכרים בזה היו נוהגים לדורות:
@387 **ותקעו בהם.** ר"ל בשתיהן תקיעה ולא תרועה שנאמר ובהקהיל הקהל תתקעו ולא תריעו והנה התקיעה הוא קול נמשך ומתדבק והתרועה הוא קול בלתי מתדבק נשבר:
@388 **ואם באחת יתקעו.** ר"ל לבדה אז הוא סימן שמשה ע"ז היה קורא הנשיאים לבדם והנה זה התקיעה בלא תרועה:
@389 **ותקעתם תרועה ונסעו המחנות וגומ'.** ר"ל כשיתקעו בחצוצרות והריעו אחר התקיעה ויתבאר שכבר היו תוקעים עוד אחר התרועה ממה שאמר תרועה יתקעו למסעיהם. למדנו שפשוטה לפניה ופשוטה לאחריה ואין לאומר שיאמר שהרצון באמרו ותקעתם תרועה שיתקעו בחצוצרות באופן שיעשו תרוע' אך לא יעשו זולת תרועה וכן הענין באמרו תרועה יתקעו לפי שכבר אמר אחר זה ובהקהיל את הקהל תתקעו ולא תריעו ביאר שההבדל היה בין ענין המסע ובין מקרא העדה שבמקר' העדה תהיה שם תקיעה לבד בזולת תרועה אחריה ואמנם בעניין המסע היתה תרועה אחריה ואלו היה הרצון שתהיה התרועה לבד הנה היה ההבדל מבואר בין שני העניינים ולזה לא היה צריך לומר ובהקהיל את העדה תתקעו ולא תריעו. ואין לאומר שיאמר שהתקיעה הראשונה שהיתה למסע המחנות היתה תקיעה ותרוע' לאחריה והאחרונה היתה תרועה ותקיעה לאחרי' שהרי כבר נאמר ותקעתם תרועה שנית וגו'. ולמדנו מזה שכלם היו בסגנון אחד ר"ל התקיעות אשר היו למסע המחנות:
@392 **ובני אהרן הכהנים יתקעו בחצוצרות והיו לכם לחקת עולם לדורותיכם.** ר"ל כי במה שישמשו החצוצרות שיהיה חקת עולם לדורות והם הדברים הנזכרים אחר זה צריך לדקדק שיהיו התוקעים בני אהרן הכהנים ר"ל הראויים לשמש בכהונה פרט לבעלי מומין ואולם בדברים הקודמים שהם למקר' ולמסע לא דקדקה התור' מי יהיה התוקע ומזה המקו' דקדקו שיהיה מותר להקהיל את הקהל בפרשת הקהל לתקוע בחצוצרות כהן בעל מום:
@393 **וכי תבאו מלחמה בארצכם על הצר וגו'.** ר"ל אם תבאו למלחמה בארצכם שהיא ארץ ישראל והוא ידוע כי המלחמה תהיה עם האויב לא עם האוהב ולזה לא היה צריך לומר על הצר הצורר אתכם אלא להודיע שבאיזה צר שיצור ישראל יעשו כן להריע בחצוצרות ע"י הכהנים כמו שזכרנו ויזכרו בזה הפעל לפני השם יתעלה. ר"ל במקדש וזה שבזה הפעל יהיה לבם נשבר ונדכה וישובו אל השם יתעלה וירחמם בהתפללם אליו כי התפלה עם זאת התרועה היא סבת היותם נזכרים לסבה שזכרנו כי הקול המרעיד יחריד לב האנשים כמו שאמר אם יתקע שופר בעיר ועם לא יחרדו ובזה האופן תהיה תשובתם ותפלתם שלמה וכבר יתבאר שהתפלה היתה שם עם זה ושכבר היה זה על כל צרה כדי שלא תבא עליה' כמו שביארנו שכבר זכר שלמה בהנגף עמך ישראל לפני אויב אשר יחטאו לך ושבו אליך והודו את שמך והתפללו והתחננו אליך בבית הזה וגו'. בהעצר שמים וגו'. רעב כי יהיה בארץ וגומ'. דבר כי יהיה שדפון ירקון ארבה חסיל כי יהיה וגו'. והנה שתקה התורה בזה המקום מהתשובה והתפלה לפי שכבר אמרה על צד התנאי ונזכרתם ר"ל עשו בדרך שתהיו נזכרים וזה אמנם יהיה בתשובה ותפלה כי הם סבת ההשגחה האלהית בהם ולפי שאמר לפני ה' אלהיכם למדנו שענין החצוצרו' לא היה נעשה כי אם במקדש כי היא עבודה מן העבודו' כי התורה דקדקה שתהיה ע"י בני אהרן הכהנים ואולם התשובה והתפלה אין מקום מוגבל כמו שאמר שלמה והתפללו אליך דרך ארצם וגו'. ונתבאר עוד שזאת התרועה לא היתה נוהגת אלא במקדש ממה שאמר דוד עליו השלום בחצוצרות ובקול שופר הריעו לפני המלך השם. ואמר שכאשר יעשו זה יהיו נושעים מאויביהם וראוי שתדע שענין הזכירה הזאת יכלול גם כן ההתענו' וזה שכבר ראינו מכונת התורה שהתשובה והכפרה השלמה תהיה אחר הענוי והתרועה ולזה כאשר רצה השם יתע' שתהיה הכפרה בעשור לחדש השביעי הקדים התרועה מראש החדש כדי שיכנע לבם מחטאיהם וישובו להם תשובה שלמה ובסוף העניין יענו נפשותיהם ביום העשירי ולזה תכלול גם כן זאת התרועה ההתענות וראוי שתדע שאחר שהגיע ההיזק מהצרה ההוא לא יתריעו שנאמר על הצר הצורר אתכם ולא שכבר צרר ולזה גם כן הוא מבואר שאין ראוי להתפלל על הצרה שכבר עברה כי מה שהיה אין להשיב. וראוי שתדע שכבר היה שם גם כן שופר בזאת התרועה ובתרועת ראש השנה היו גם ככן חצוצרות שנאמר בחצוצרות וקול שופר הריעו לפני המלך השם. למדנו מזה שהיו שם יחד חצוצרות וקול שופר ואמנם נזכרו בכאן חצוצרות להורות שהמצוה בחצוצרות ונזכר בראש השנה שופר להורות שהמצוה בשופר:
@394 **וביום שמחתכם ומועדיכם וגו'.** ראוי שתדע שכל אלו הדברי שזכרנו שיתקעו עליהם בחצוצרות במקדש הם כשהיו כוללים כמו ימי השמחה והמועדים וראשי חדשים שהם כוללים ולזה יחוייב שיהיו אלו העולות עולות צבור והשלמים זבחי שלמי צבור ואולם על עולת יחיד ושלמי יחיד לא יהיה זה וכן ראוי שנבין העניין בענין התרועה על הצרות שלא יבאו על הצבור:
@394 **והיו לכם לזכרון לפני יי' אלהיכם.** מגיד שזאת התקיעה אינה מעכבת ענין הקרבנות האלו שכבר נרצו בזולת זה אבל תהיה זאת ההערה להיות לכם לזכרון רוצה לומר לישראל כי זה ישימם מושגחים מהשם יתעלה וידוע כי בעת הזאת היו הלוי' משוררים שיר ליי' לזאת הכונה בעינה כי הכונה באלו הקרבנות כבר נשלמה בזולת זה אמר בספר עזרא השיר משורר וחצוצרות מחצצרים למדנו שבעת התקיעה בחצוצרות היה זה השיר והלוים היו משוררים שנאמר ושרת בשם ה' אלהיו והנה השירות הוא בשם יתעלה הוא השיר אשר בפה:
@405 **והקימו את המשכן עד באם.** זכר שלזאת הסבה היו קודמים ליסע בני גרשון ובני מררי כדי שיקימו המשכן קודם שיבאו בני קהת כדי שימצאו בני קהת המשכן מוקם ולא יתעכב בידם ארון העדות אך יושם תכף במקומו:
@413 **ויאמר משה לחובב בן רעואל.** חובב הוא יתרו. ולמדנו מזה שכבר נתעכב שם יתרו עד העת שנסעו ממדבר סיני ומה שאמר נוסעים אנחנו אל המקום אשר אמר ה' אותו אתן לכם והם לא נכנסו לארץ כי אם בימי יהושע כך עלה במחשבה שיירשו ישראל את הארץ אחר שקבלו התורה בשנה השנית לצאתם מארץ מצרים אלא שגרם החטא ע"י המרגלים ונתאחרו ישראל במדבר עד שלמות מ' שנה מעת יציאת מצרים כמו שנזכר בפרש' שלח לך:
@413 **לכה אתנו והטבנו לך וגו'.** אמר זה להודיע יתרו שעתידין ישראל לירש הארץ והודיעו שכבר יטיבו לו מהטוב ההוא וענה יתרו שלא ילך עמהם בעבור ירושת הארץ אבל ילך אל ארצו ואל מולדתו וידמה שיתרו נפרד מע"ז ולזה מצאנו בניו שהיו יושבים בארץ ישראל כמו שנזכר בספר שופטים ובני קיני חותן משה עלו מעיר התמרים את בני יהודה מדבר יהודה אשר בנגב ערד וילך וישב את העם ונזכר שם עוד וחבר הקני נפרד מקין מבני חובב חותן משה ויט אהלו על אילון בצעננים אשר את קדש וזה מורה שהם היו נלוים לישראל ונאמר בספר ירמיה הלוך אל בית הרכבים והשקית אותם יין למדנו משם שהם היו מישראל וידענו שהרכבים היו מבני יתרו שנאמר וממשפחת סופרים יושבי יעבץ תרעתים שמעתים סוכתים הם הקנים הבאים מחמת אבי בית רכב ולזה הוא מבואר שכבר נתגייר יתרו ולזה היה אמרו כי אם אל ארצי ואל מולדתי אלך למשוך לב כל בני ארצו אל השם יתעלה אם יוכל ואם לא יוכל על זה ימשוך לב אנשי משפחתו:
@415 **אל נא תעזוב אותנו.** הראה משה מדבריו כאלו ישראל צריכין ליתרו להעיד על מעלתו:
@415 **על כן ידעת חנותנו במדבר והיית לנו לעינים.** ר"ל שאם לא תעזוב אותנו תדע ענייני חנייתנו במדבר ותהיה לנו לעינים לתת העצה הנכונה במצטרך כמו שעשית בעניין מנוי השופטים והנה אמר משה זה על צד הענוה כי לא נצטרך ליתרו בזה:
@417 **ויסעו מהרי יי' דרך שלשת ימים.** הר יי' הוא סיני והנה זכר שהמסע הראשון שנסע הארון נסע לפניהם דרך ג' ימים לתור להם מנוחה והנה חנו אז בקברות התאוה לפי מה שנזכר בפרשת מסעי והנה הודיע גם בעת שהיו נוסעים והולכים בדרך היה ענן יי' עליהם יומם:
@419 **ויהי בנסוע הארון.** הנה נזכר בכאן כי ממנהג משה היה שבעת שהיה נוסע הארון היה מתפלל משה שיקום השם יתעלה ויפוצו הנה והנה מפחדו אויבי ישראל בראותם הפלא העצום שהשם יתעלה עושה לישראל ולזה ינוסו משנאי ישראל מפני השם יתעלה והנה קראם אויבי השם יתעלה ומשנאי השם יתעלה כי אויבי ישראל ושונאיו הם אויבי השם יתע' ושונאיו ואמר זה משה כי לולי יד השם יתעלה לא הגיע העת עדין שינצחו ישראל את אויביהם כי לא הגיע קץ עדיין כמו שביארנו בספר ואלה שמות והנה חשב משה שינחלו ישראל את הארץ תכף כמו שאמר ליתרו אלא שגרם החטא ונתעכבו במדבר עד תום מ' שנה:
@420 **ובנחה יאמר.** ובנוח הארון היה אומר אנא השם שובה רבבות אלפי ישראל אל הארץ אשר נשבעת לאבותיהם והנה אמר שוב בעבור האבות הקדושים שישבו בארץ ישראל או יהיה הרצון בזה שישיב השם יתעלה אלפי ישראל לרבבות כשיוסיף עליהם כהם עשר פעמים והנה היה שני אלו הפסוקים נקוד מלמעלה ומלמטה להעיר שלא על ענין זה המסע והחניה הפרטית היתה התפילה הזאת למשה אבל היתה על התכלית שהיה מכוון מעת צאתם ממצרים והוא כדי שיירשו ישראל את הארץ וזה כי מפני שכבר קבלו ישראל את התורה ונהיו לשם יתעלה לעם קדוש הנה נתיישרו לירש הארץ אז:
@421 **ויהי העם כמתאוננים.** כמוצאים תואנה רעה על השם יתעלה כשהיו אומרים איננו שומע את הדברים אשר בכאן ואינו יודע אותם וזהו אמרו שהיו מתאוננים רע באזני השם והנה חרה אף השם יתעלה בזה והראה להם כי הוא שומע הדברים האלה וידעם וזה היה כשהביא עליהם אש גדולה ואכל בקצה המחנה והם היותר רחוקים ממחנה שכינה וידמה שבפחותים שבהם אכלה אש והם היו אומרים הרע בעיני ה' או יהיה אמרו כמתאוננים רע באזני השם שהיו חושבים מחשבות רעות בינן לבין עצמן ולא היה שומע כי אם השם יתעלה לבדו ולא נתברר מה היו אלו הרעות וידמה מהעונש שהביא עליהם השם שיהיו אלו התואנות בעניני האמונה ונראה זה גם כן ממה שאמר בספר ואלה הדברים ובתבערה ובמסה וגו'. ממרים הייתם עם ח' ויזעק העם על משה שיתפלל בעבורם אל השם יתעלה ותשקע האש ולפרסם עניין זה המופת קרא שם המקום ההוא תבערה כי בערה שם אש ה':
@424 **והאספסוף אשר בקרבו.** זה ערברב שעלה עמם ממצרים:
@424 **התאוו תאוה.** מגיד שלא נתאוו על דבר הכרחי להם אם לא לרדיפת התאוה כי המן היה מספיק להם והנה אלו הפחותים היו סבה שלמדו מהם ישראל ובכו ואמרו שהם מתאוי' מאד לאכל בשר ואף על פי שכבר היה להם מקנה רב הנה רצו למצא תואנה אם יוכל שם יתעלה לתת להם בשר:
@425 **זכרנו את הדגה אשר נאכל במצרים חנם.** יתכן לפי הפשט שלרבוי הדגים שם יהיו בזול גדול ולזה אמר חנם ואמר להורות על פחיתותם שכבר נתן להם השם יתעלה מזון ערב מאד במראהו ובטעמו ובתכלית הנקיות כי היה יורד הטל תחלה ואחר ירד המן עליו.
@425 והנה נתרעם משה על ששם השם יתעלה משא כל העם עליו ועל שאלתם ממנו שהיה בתכלית הקושי ר"ל במה ששאלו לתת להם בשר ואכלו ועל הדבר הראשון ענהו השם יתעלה שיאסוף לו שבעים איש מזקני ישראל הראויין למעלה ויעדו השם יתעלה שעל דרך המופת ישפיע הש' ית' שפע נבוא בדרך שישתתו עם משה בהנהגת העם. ועל דבר השני ענהו השם שיאמר אל העם שיהיו מוכנים למחר כי אז ימלא ה' יתע' תאות' עד שימאסו בהמה שהתאוו בו וזהו הגמול שהיה ראוי להם כי הם התאוו תאוה שלא לצורך למאסם עבודת השם יתעלה ונענשו בשימאסו במה שהתאוו בו וענה משה ואמר הנה העם הזה רב מאד ואיך תמצא להם בשר לאכל חדש ימים האם צאן ובקר ישחט להם או אם כל דגי הים יאסף להם היספיק להם והנה אמר בצאן ובקר שחיטה ובדגי הים אסיפה להורות שהבהמה תהיה השחיטה מתרת אותה ואולם הדגים הנה אסיפתם היא המתרת אותם כי תכף שיצאו מהמים ימותו ולפי שהעוף הוא כמו ממוצע בין הדגי' והבהמה הנה עניינו ממוצע בזה ביניהם ולזה למדנו רבותינו ז"ל שהעוף הוא נתר בשחיטת סימן אחד יש למספק שיספק איך לא גנה השם יתעלה משה על זה המאמר שידמה בלתי מאמין במה שייעד לו הש"י ולא מצאנו שנחשב זה לעון למשה ומצאנו שנחשב לעון לו עניין מי מריבה עם היותו לפי מה שאחשוב למטה מזה העניין ונאמר שכבר אמרו בהיתר זה הספק כי עניין מי מריבה היה בפרהסיא וזה המאמר היה בין הקב"ה ובין משה אלא שזה גם כן לא יספיק כי איך ידעו העם שחטא משה כאשר הכה במטהו על הסלע הלא יחשבו כי כן צווה מהשם יתעלה וכבר התירו זה הספק באופן אחר ואמרו שלא רצה לומר משה שלא יהיה כח בשם יתעלה לתת להם רבוי בשר הצריך לזה אבל רצה כי מפני רוע תכונתם לא יתפייסו לזה וזה אמרו ומצא להם אלא שלפי הפשט לא יקשר לפי זאת הכוונה מה שאמר תחלה שש מאות אלף רגלי העם אשר אנכי בקרבו והנראה לנו בהיתר זה הספק שיש מיעודי הנבואה הטובים אשר בכחם תנאי ואם לא נזכר ולזה מצאנו שלא כעס השם יתעלה על אברהם כשאמר במה אדע כי אירשנה כי בזאת הירושה היה תנאי כמו שביארנו והוא שיהיו רעו באופן מהשלמו' שתדבק בהם ההשגחה האלהית בזה האופן הנפלא הצריך להם בעניין ירושת הארץ לזה הרהר אברהם בזה לא נחשב לו לעון וכך מצאנו שהרהר משה במה שאמר לו השם יתעלה שיהיה עם פיו ולא נענש על זה לפי שזה הייעוד לא יחוייב שלא יהיה בו תנאי כמו שביארנו בפרשת ואלה שמות וכן אפשר שאמר בזה הייעוד שהיה שיש בו תנאי והוא שהיה הנביא מוכן אל שיעשה על ידו מופת כזה כי נראה כי כל מה שהיתה מעלת הנביא יותר בוהה אפשר שיעשו על ידו מופתים יותר גבוהים ולזה אמר ולא קם נביא עוד בישראל כמשה וגומ'. ולכל האותות והמופתים וגו'. ומזה הצד היה אפשר שהרר משה בזה המופת עם ראותו שמצד ההשגחה על ישראל לא יתכן שיעשה זה המופת כי זאת השאלה היתה מהם בסבת מרי כמו שזכרנו ועוד כי המופת יעשה לתועלת מה וזה המופת ולא היה תכליתו להועיל לישראל אבל היה העניין בהפך באופן מה ולאלו הסבות כלם היה חשבה משה שהוא רחוק שיעשה על ידו כמו זה המופת הנפלא וענהו השם יתעלה כי ידו לא תקצר מעשו' זה ואף על פי שאין המקבלים ראויים.:
@444 **ויאסוף ע' איש וגו'.** ידמה ממה שראינו מספורי התורה שלא הטילה קנאה בין השבטים שעלו ששה לכל שבט ועלה חשבון ע"ב זקנים כדי שלא תהיה שם קנאה ולזה חוייב שיפילו הגורל מי הם השנים שנשאר מזה המניין ולזה היו הכתובים ע"ב ונשתיירו מהם ב' והם אלדד ומדד כן אמר בספרי ולפי הפשט נראה שאלדד ודד היו מהשבעי' זקנים ונשארו במחנה על צד הענוה שהיו בורחים מן השררה:
@445 **ויתנבאו ולא יספו.** ר"ל שלא יספו עוד להתנבאת רק הפעם ההיא וכן ידמה שיהיה אמרו אלדד ומדד מתנבאים במחנה שאז היו מתנבאים לפי שעה:
@448 **אדני משה כלאם.** אמר זה יהושע לחשבו שיהיה זה העניין מהם אפקדותה כנגד משה וענה לו שזה ישר בעיניו שיהיו אלו נביאים כדי שישאו עמו במשא העם וידמה שבהם נעזר משה עזר מעט בזה המופת ולזה אמר ויאסף משה אל המחנה הוא וזקני ישראל:
@451 **ורוח נסע מאת ה' וגו'.** והנה היה תועלת לישראל בעניין נבואתם שיכנעו במה שעתיד לשמוע דבריהם אשר יצוום להמשך למה שירצה משה מענין הנהגתם ובזה האופן היה זה השפע הנבואיי שהגיע להם אז מישיר אותם אל שישאו עם משה במשא העם:
@451 **וכאמתים על פני הארץ.** זה מורה על רבוי העופות ההם עד שמחוזק דחיית הרוח אותם היה מהם אחת על אחת כאמתים ואפשר שירצה בזה שיהיו בורחים בשפל לא גבוה על הארץ יותר מב' אמות וכן פירשו בספרי והוא נאות מאד אלא שמה שאמר אח"כ שהממעיט אסף עשרה חמרים מורה שהיו העופות ההם אחת אחת על הארץ באופן שהיו בגובה זה על זה תחתיים שניי' ושלישי' וכן בזה הדרך על שתי אמות:
@453 **הבשר עודנו בין שיניהם טרם יכרת.** ר"ל שלא נשלם עכולו בפה ומזה המקום למדנו שהוא נקרא בשר עד שישלם עכולו בפה:
@456 **ותדבר מרים ואהרן במשה וגו'.** ממה שאמר אחר זה הענין והוא שכר פירש משה מן האשה ואמרו מרים ואהרן אם בשביל הנבואה פירש וכי לו לבדו דבר הקב"ה הלא גם בנו דבר ואין אנו פורשים מפריה ורביה והנה קראה כושית מצד יפיה וכמו זה נקרא שאול כוש בן ימיני מצד יופיו כי המנהג לתאר הדבר בהפכו ולזה נקרא העור סגי נהור:
@458 **והאיש משה ענו מאד וגו'.** אמר זה להורות שלא היו מתרעמים על משה מפני גאוה והשתרר מפני דבור השם יתעלה עמו ולא היה ראוי שיקנאו בו מזה הצד:
@459 **צאו שלשתכם.** לכל אחד ואחד בפני עצמו נאמר בנבואה שיצא אל אהל מועד או אמר למשה והוא אמר העניין לאהרן ומרים כי לא יתכן שהיתה הנבואה אחת במספר יחד לרבים:
@460 **ויקרא אהרן ומרים.** לכל אחת ואחר קרא בדרך הנבואה או היתה הנבואה בדרך מופת בקול מורגש ואמר להם השם יתעלה מה אתם מתפארים בנבואה כמשה אם יהיה נביאכם נביא השם הנה אתודע אליו בעת השינה במראה הנבואה או אדבר בו בחלום בזולת השתמש החושים על מנהגיהם ולזה תגיע להם הנבואה על המעט ואולם עבדי משה אינו כן כי הוא עם השתמשו בחושיו תגיע לו הנבואה כשירצה ובמה שירצה כמו שאמר עמדו ואשמעה מה וגו'. ולזה הוא נאמן וקיים בכל ביתי והנה זה הבדל אחד בין נבואת משה לנבואת שאר הנביאים וההבדל השני הוא שאני מדבר בו פה אל פה בזולת אמצעי שאמ' בסוף וזאת הברכה אשר ידעו יי' פני' אל פנים. ר"ל שלא היה אמצעי ביניהם ואמנם אמר זה לפי שכל הנביאים ימצא למדמה בהם רושם בהגעת הנבואה מצד היות מושגיהם דברים פרטיים אשר אין שם כח יתכן בו ציורים זולת הדמיון כמו שביארנו בב' מספר מלחמות ה' ואולם השגות משה הנבואות אשר נתיחד בהם מבין שאר הנביאים היו השגות כוללות ונימוסים כוללים כמו הענין במצות התורה ובמה שנז' במעשה בראשית ולזה לא היה שם נביא תורה זולת משה. וההבדל הג' הוא שמה שהיה רואה מהדברים הפרטיים היה מגיע לו בלשון מבואר לא בחידות וזה יורה על שלמות השגתו בנבואה ואולם שאר הנביאים היה מגיע להם בחידות וכל מה שהיתה נבואתו יותר חלושה היו החידות יותר עמוקות ויותר סתומות כי כל מה שהיתה החידה יותר עמוקה היתה הידיעה המגעת מנה בענין הנרצה יותר חסרה וכבר ביארנו זה בב' מספר מלחמו' ה' וההבדל הד' הוא מה שאמר ותמונת ה' יביט והנה ההבדל בזה הוא לפי מה שאחשוב ששאר הנביאים מפני דבקותם לחמר יקרה להם שלא ישיגו מנימוס הנמצאות וסדרם אשר אצל השם יתעלה כי אם החלק שתטה אליו מחשבתם ואולם משה היה משיג יחד מה שאפשר שיושג לאדם מזה הנימוס המושכל ובזאת ההשגה הנפלאה היה דבק בשם יתעלה ומשיג תמונתו הנפלאה באופן מה והיה זה כן לקלות התבודדות שכלו מבין שאר הכחות הנפשיות עד שכבר היה תמיד עם הש"י ולא היה יכול להפריד הדבקו ההוא כי אם בקושי נפלא כמו שביארנו בראש ספר ואלה שמות אשרי ילוד אשה שזכה לזאת המעלה הנפלאה והנה במה שזכרנו בזה המקום מזה העניין יש עומק נפלא יתבאר למי שראה דברינו בב' וה' ממ"י ולו באנו להרחיב הביאור בזה יאריך יותר מן הראוי עם שכבר יצטרך להקדמות רבות לא יכילם זה הספר:
@463 **ומדוע לא יראתם לדבר בעבדי במשה.** ר"ל שהיה לכם לירא מהשוות נבואתכם לנבואת משה וזה כי משה להיותו תמיד עם השם יתעלה חוייב לו שיהיה פורש מן האשה והוא מה שדברו עליו מרים ואהרן והנה זכר שחרה אף השם יתעלה בם ונסתלקה הנבואה מהם ואז סר הענן הענן מעל האהל ונגלה שכבר נשארה מרים מצורעת כשלג וזה לאות כי מרים לבדה דברה כנגד משה זה המאמר הנזכר ואולם אהרן נתגנה על שלא הוכיח אחותו על זה וחזק את דבריה ועל זה הקדים מרים לאהרן במה שאמר ותדבר מרים ואהרן במשה והנה בקש אהרן מחילה ממשה על מה שהטיחו דברים כנגדו הוא ואחותו ואמר לו שלא ישית עליהם חטאת מה שנו אלו בו וחטאו והנה התפלל משה לשם יתעלה בעבור אחותו במלות קצרות מאד לפי שלא נצטרך יותר מזה בזאת התפלה כי הש' יתע' עשה זה לכבוד משה וכבר מחל להם משה על מה שחטאו לו כמו שבקש ממנו אהרן והנה הראה שמחל להם זה בהתפללו לה' ית' שירפא מרים אחותו ובאהו המענה על זה שאלו היתה מרים נזופה מאביה היה ראוי שתכלם ז' ימים ולזאת הסבה רצה השם ית' שתסגר ז' ימים מחוץ למחנה כמשפט המצורע ביום טהרתו והנה לכבוד מרים לא נסע העם עד האספה וזה אמנם היה שסבב ה' ית' שלא נסע עמוד הענן מעל המשכן באותם שבעה ימים ואחר זה נעלה הענן מעל המשכן ונסעו ישראל מחצרות וחנו במדבר פארן:
@473 **שלח לך אנשים ויתרו את ארץ כנען אשר אני נותן לבני ישראל וגו'.** יתבאר ממה שנזכר בפרשת ואלה הדברים שישראל שאלו למשה לשלוח אליהם מרגלים שנאמר ותקרבון אלי כלכם ותאמרו נשלחה אנשים לפנינו ונמלך משה בגבורה ובא הצווי שישלח ראשי העם והם נשיאי המטות כי לשלמותם יתכן בהם יותר שלא יאמרו דבר יניאו בו לב העם ולזה אמר כלם אנשים ראשי אלפי ישראל המה להורות שהיו אנשים חשובים וכאלו השתדל השם יתעלה לברוח במה שנפלו בו עם שכבר היה ראוי שיבטחו בהש' יתעלה שכבר יורישם את הארץ מצד ראותם עוצם נפלאותיו במצרים ועל הים ובכל המקומות אשר באו שם עם שבחצרות ראו מופתים רבם מה' כמו שנזכר בזה הספור ולזה לא היה ראוי שיהיה תורם את הארץ כי אם לראות טובה ויופיה ומאי זה צד יתכן להם יותר לכבשה עם יד השם הטובה עליהם אך לא היה ראוי שייראו שתקצר יד השם יתעלה מלתתה אליהם ואם היה שיחקרו מאי זה צד יקל יותר לכבשה כי השם יתעלה כשיביא הצורך לעשיית המופתים יחבר להם הסבות אשר יהיה בהם יותר מעט מהזרות במופתי' ההם כמו שביארנו בששי מספר מלחמות יי':
@487 **ויקרא משה להושע בן נון יהושע.** ידמה שהוסיף אות על שמו לסבה כמו שמצאנו כשרצה ה' ית' לשנות דבר לאברהם ושרה אל שיהיה להם זרע ששינה שמם וידמה שכבר נגלה למשה סוף דבר המרגלים יהיה להניא לבם ולזה שנה שם הושע בן נון כדדי שיעמוד כנגדם וינצחם וזה יהיה סבה אל שינצלו בני ישראל מהנאת לבם על יד המרגלים וכל זה לא הועיל והנה הניא ישראל אל כל זה הרע מיעוט האמתנם בשם ית' עד שבקשו לשלוח שם מרגלים לחקור אם יתכן להם לכבוש את הארץ. אולי יספק מספק ויאמ' שלא חטא ישראל בזאת השאלה לפי שאנחנו מצאנו יהושע בן נון ששלח מרגלים לירחו ולעי אלא שהיתר זה הספק לא ישה עם מה שאבאר מזה כי זה ריגול יריחו לא היה כי אם לחקור אם נמוגו יושבי מפניהם כמו שביארנו שם וריגול העי היה לחקור מאי זה מקום יתכן להם לכבשם בקלות ואיך. לא שתהיה כונתם שאם יהיו חזקים ישמרו מלהלחם בהם:
@489 **וראיתם את הארץ מה היא.** ר"ל אם היא ארץ הרים ובקעים או יא ארץ מישור:
@489 **ואת העם היושב עליה.** ר"ל שיחקרו אם הם גבורים או חלושים ואם הם רבי המספר או מיעוטי המספר:
@490 **ומה הארץ אשר הוא יושב בה הטוב' היא אם רעה.** ר"ל אם אוירה טוב שיעמדו האנשים שם בריאים או העניין בהפך:
@490 **הבמחנים.** הם המקומות הבלתי מוקפים חומה:
@490 **אם במבצרים.** הם המקומות המוקפים חומה:
@493 **וחברון שבע שנים נבנתה לפני צען מצרים.** אחשוב שיהיה זה המאמר להורות על חשיבות המקום הזה כי צוען היה מקום חשוב מאד בארץ מצרים ועם כל זה היה יותר חשוב חברון כי כשנפוצו על פני כל הארץ בוני המגדל ופרו ורבו מעט עד שמלאו הארץ הנה בלי ספק כשהיו בוני' במקו' אחד היו בונים במקום היותר חשוב אשר בו וכאשר היה צר להם המקום היו בונים במקום אחר שם ואם הוא למטה מהראשון בחשיבות ולזה הוא מבואר שלא נבנתה חברון קודם צוען מצרים אלא מפני היותה חשובה ממנה:
@494 **וישאוהו במוט בשנים.** הנה לפי הפשט יראה ששנים נשאו המוט שהיה בו אשכול האחד מן הראש האחד והאחר מן הראש השני או ירצה בזה שהמוט היה בשנים מוטות והיו נושאי' אותו ד' והביאור הראשון נראה יותר לפי הפשט ואולם לרבותי' ז"ל על צד ההפלגה והגוזמא שהיו טורטני וטורטני דטורטני:
@497 **ויבאו אל משה ואל אהרן ואל כל עדת בני ישראל וגומ'.** הנה אמר זה כי אלו היו מספרי' זה תחלה למשה ולאהרן כמו שהיה ראוי לא היה מתחדש מפני דבתם מה שאירע מן הרע כי כבר היה נקל למשה ולאהרן לישב לבם שיסמכו בש' יתעלה עם שיהושע וכלב היו מחזיקים את ידיהם אבל הם השיבו אותם ואת כל העדה ובזה הניאו את לב העם בדרך שלא יוכלו לתקן עותתם והנה אמרו למשה בפני כל העם שהארץ ההיא היה זבת חלב ודבש מרב דשנה ורעננותה לטוב המרעה אשר שם לצאן ולדבורם או יהיה הדבש דבש תמרים כמו שאמרו רז"ל ואמנם העם אשר שם הם גבורים מאד ויש להם עוז ותוקף גדול והנה באמרו כי עז העם העידו גבורתם והיותם רבי המספר כי העז יהיה לעם משני אלו הצדדים והורו עוד על רבוי העם במספר מה שספרו בערים שהם גדולות מאד כי הערים תהיינה גדולות כשהיו העם אשר בה רבי המספר ובאמרם שהערים בצורות הורו שהם חזקות ומוקפות חומה וספרו עוד להבהיל העם שכבר ראו שם ילידי הענק והבהילום עוד במה שספרו להם שעמלק היה יושב בארץ הנגב כי כבר ראו מלחמת עמלק והכירו שעמלק היו מנצחים אותם באשר משה מניח ידו וזה ממה שהוא ראוי שיפול אימה עליהם כשיראו שיצטרכו ללכת להלחם עם עם עמלק בארצם שהם כה יותר חזקים מאד מחזקם חוץ לארצם כשנלחם בהם יהושע וספרו להם עם זה רבוי האומות שהיו בהר שהיה קשה מאד ללכת להלחם עמהם שם. והכנעני גם כן היה במקום חזק כי היה יושב אצל הים ואצל יד הירדן ויקשה ללכת שם להלחם עמו ועדין לא ספרו מאויר הארץ אם הוא טוב לבריות אם אין וזכרו זה אח' זה כמה שאמרו ארץ אוכלת יושביה ר"ל שהיא משחתת יושביה ומכלה אותם מצד רוע אוירה:
@501 **ויהס כלב את העם אל משה.** ידמה שתכף ששמעו העם זה הענין מפי מרגלים היו מתלוננים ואומרים שלא יעלו שם כמו שנגלה אחר זה והנה שתק כלב את העם בעבור משה ואמר עלה נעלה וירשנו אותה כי יכול נוכל לה ר"ל לפי מה שנתפרסם לנו מנפלאות הש' יתעלה על ידי משה:
@503 **אנשי מדות.** ר"ל רבי הקומה:
@505 **ויבכו העם בלילה ההוא.** ר"ל שלא סרו מלבכות ולהתאונן על זה הענין עד עבור הלילה שאחר היום ההוא ואמרו איש אל אחיו נתנה ראש ונשובה מצרים בכאן נגלית הסבה אשר בעבורה סבב ה' ית' שייראו מלשוב למצרים וזה שעם כל מה שסבב השם יתע' למנעם מלשוב למצרים היו נכשלים בזה ראה מה היו עושים לולי הסבות ההם ואולם הסבות שסבב הש' ית' למנעם מזה הנה הראשונה התנצלם את מצרים. ר"ל שלקחו משכיניהם שם כלי כסף וכלי זהב ושמלות כי זה ממה שהיה ראוי בעבורו שייראו מלשוב למצרים. והשנית היתה טביעת פרעה וחילו בים סוף כי מפני זה ראוי שייראו מלשוב בידם פן יקחו מהם נקמתם. והסבה השלישית הוא מה שהנחה הש' יתע' את ישראל דרך המדבר ולא רצה לנחותם דרך ארץ פלשתים כי קרוב הוא ויקל לעם לשוב למצרים:
@509 **קהל עדת בני ישראל.** ר"ל קבוץ העדות כי כל שבט ושבט היה עדה אחת מיוחדת:
@513 **כי לחמנו הם.** ר"ל בידנו הם לאכלם כמו הלחם אשר הוא בידנו:
@513 **סר צלם מעליהם.** לפי שאמרו המרגלים ארץ אוכלת יושביה היא להורות על שהארץ היתה בלתי טובה לעמוד בה בבריאות ואמרו זה לפי שראו שמתו רבים שם ושהיו שם חולים רבים הנה אמרו יהושע וכלב שזה הדבר ורבוי החולאים לא היה בהם מפני היותו אויר הארץ ההיא בלתי זך אך היה לפי שבא קץ האומות ההם למות כי סר מהם המגן והמחסה שהיה מגין עליהם ולרוע מזל האומות ההם היה זה לא לרוע הארץ ולזה יתבאר שזה העניין אינו מה שראוי שיפיל מורך בלב ישראל מהלחם עם הגוים ההם אבל הוא מה שראוי שיחזק לכם בראותם רוע מזל האומות ההם והיות השם יתע' עם ישראל והנה הגיע מרוע ישראל והנה הגיע מרוע ישראל שאמרו כל העדה לרגום יהושע וכלב באבנים והוא אפשר שגם כנגד משה ואהרן אמרו כי הם היו רוצים לבחור ראש אחד במה שאמרו נתנה ראש ונשובה מצרים ולמנעם מזה נראה תכף כבוד יי' באהל מועד אל כל בני ישראל באופן שהיו מרגישי' בבא דבר ה' ית' למשה:
@516 **אכנו בדבר ואורישנו.** ר"ל אין לחוש מפני כלותי את העם הזה שתופר בריתי עם האבות במה שנשבעתי להם מעניין ירושת הארץ כי כבר אעשה אותך לגוי גדול ועצם ממנו ובזרעך יתקיים הברית ההוא והוא מבואר שאין כלותו אותם תנאי במה שייעד לו שיעשה אותו לגוי גדול ועצום ולזה נתקיים למשה זה הייעוד אף על פי שלא כלה השם יתעלה את ישראל כמו שדקדקו רז"ל ממה שאמר ובני רחביה רבו למעלה:
@517 **ויאמר משה אל יי'.** שאין ראוי שיעשה זה פן יביא זה אל שיחשבו הגוים שמפני שלא היה להשם ית' כח לנצח האומות האלו באופן שיירשו ישראל ארצם קם והרגם במדבר והנה בעניין העגל אמר משה מה יאמרו מצרים לאמר ברעה הוציאם ובזאת התפלה אמר כי כל הגוים אשר שמעו את שמע הש' ית' יאמרו זה ולהשלים ביאור בזה אמר מש ושמעו מצרים את הדבר הזה אשר תעשה לישראל עתה מהכליון החרוץ ושתק מלספר מה שיאמרו על זה עד סוף העניין שאמר בכלל כל שומעי שמע השם יתע' יאמרו שמבלי יכולת השם יתעלה להורישם הארץ כלה אותם במדבר זה שכבר הוצאת בכחך את ישר' מקרבו ויספרו המצריי' אל יושבי הארץ הזאת להורות על חוזק השגחתך בישראל ויושבי הארץ הזאת שמעו ונתפרסם להם כי עין בעין נראה אתה לישראל במעמד ההר סיני ובזולתו שהיו רואים ישראל בבא ה' לדבר עם משה ועננך עומד אצלם בעת הגעת הנבואה למשה ובעמוד ענן הולך לפניהם יומם ובעמוד אש לילה וזה כלו מורה על יתרון השגחתך בהם בחזקת היד ואחר שכן הוא הנה יאמרו כלם אלו היה יכול השם יתעלה להורישם האר לא היה נמנע מזה הרי הוא מראה שהוא אוהב אותם אהבה יתרה אך מפני שלא יכול על זה קם והרגם במדבר ועתה יתבאר לכל גודל כחך שדברת כי למען ספר שמך בכל הארץ עשית נפלאות בארץ מצרים ולזה ראוי שתשמר מלעשות מה שיביא לחשוב האנשים שידך תקצר מעשות אשר יעדת מהטוב לעמך.
@522 אתה השם שהוא **ארך אפים.** ר"ל האף שהוא מצד ההשגחה הכללית במקרה והאף שהוא מצד ההשגחה הפרטית על דרך התוכחת והוא מצד מה שהוא טוב כי השם יתעלה לא יעשה רע כי אם מהצד שהוא טוב והנה השם יתעלה מאריך כל אחד משל האף המגיע במקרה מצד השגחה הכללית מה שיגיע מהרעות באמצעות הגרמים השמימיים אשר שמם הש' יתעלה להשגיח במין האנושי בכללות כמו שביארנו במאמר הב' והה' מספר מ"י והנה השתדל השם יתעלה להרחיק הרעות ההם בחזקת היד מחד השכל אשר נתן לאדם אשר הוא כלי להצילו מהם ואמנם הרע אשר הוא על דרך התוכחת יאריכהו גם כן השם יתעלה כשיוכיח תחלה בתוכחת קל ואחר כך בקשה ממנו או בשישלח השם לחוטאים ההם על ידי נביאיו שאם לא ישובו אליו יחול עליהם הרע ולזה ראוי שלא תמהר להביא עליהם זה הרע הנפלא:
@522 **ורב חסד.** רוצה לומר אתה השם אשר מדרכך להשפיע רבוי הטוב לא זולת זה וזה מבואר ונגלה ממה שהפלגת להשגיח ביצירת הבעלי חיי' וזולתם בזאת ההשגחה הנפלאה אשר ילאו השכלים האנושיים להשיג ממנה כי אם שיעור מעט ביחס אל מה שבהם בכללות מיתרון ההשגחה ולזה גם כן ראוי שלא יגיע ממך זה הרע הנפלא:
@522 **נושא עון ופשע.** רוצה לומר אתה השם אשר מדרכך לשאת עון ופשע כשישובו החוטאים איך או כאשר יגיע צער נפלא למושגחים ממך ברעה אשר תמצא אותם כמו שביארנו בפרשת כי תשא ולזה ראוי שלא תגיע לישראל זה הרע הנפלא בעבור אהבתך אותי שאצער מאד בזה:
@522 **ונקה לא ינקה.** ר"ל שאין מדרכו להגיע מהרע על צד התוכחת שיכרת בהם הנוכח מכל וכל שאם יהיה הענין כן לא יהיה התוכחת ההיא לטוב והמשל שמי שירצה להוכיח בנו לא יהרגנו כדי שיקבל תוכחת אבל יכנו או יחסרנו אבר וכן העניין במי שירצה להוכיח עם אחד כאחד הנה יתכן להוכיח העם שימותו קצתם ונוסרו הנשארים אך לא ימיתם כלם להוכיח את העם ולזה גם כן ראוי שלא תכלה זה העם בזה האופן:
@522 **פוקד עון אבות על בנים.** ר"ל אתה ה' ית' כשרצית שתשלם התוכחת פוקד עון אבו' וזה שכאשר נסתבך האדם בחטא הסתבכות רב יצטרך לתוכחת רב להוסר מהחטא ההוא כי כשהיה החטא ההוא לאדם קנין חזק יצטרך להסירו ממנו לתוכחת רב יותר ולזאת הסבה אם היה האב חוטא בזה החטא שחטא הבן יצטרך הבן לתוכחת יותר רב מצד חטא האב כי זאת התכונה שבה להם כמו קנין חזק ובהיות הענין כן שה' ית' לא יעשה רע בעצמות כי אם בסבה תוכחת והוא מבואר מענין התוכחת שאין ראוי שיכרתו בו אשר להם התוכחת והוא מבואר שאין ראוי לך שתכרית ישראל ולזה התפלל משה לה' ית' שיסלח לעון העם הזה כגודל חסדו:
@525 **ואולם חי אני.** ר"ל עם שימלא כבוד יי' את כל הארץ ותסור הטענה שטענת מחלול כבודי הנה נשבעתי שאקח נקמתי מהעם הזה מזולת שאכלם והוא שלא יראה אחד מהם את הארץ אשר נשבעתי לאבותם ר"ל מהעם המורדים בי ומן המרגלים המוציאי' הדבה וזה ראוי להם כי כבר ראו את כבודי ואת אותותי הנפלאים שעשיתי במצרים ובמדבר ונסו אותי עוד בנסיונות רבים לבחון אם אני שליט לעשות כל אשר ארצה ומצאו בהם גבורתי הנפלאה ועם זה לא שמעו בקולי ואולם עבדי כלב לפי שנפרד מעצתם ומלא אחרי אביאנו אל הארץ אשר בא שמה והוא חברון וזרעו יירשנה וכן היה לפי מה שנזכר בספר יהושע:
@529 **והעמלקי והכנעי יושבי בעמק.** ולזה הוא מבואר שלא תכבד מאד המלחמה עמהם כי אינם במקומו' חזקים מאד כמו העניין ביושבי ההר אלא שמפני זה שלא שמעו בקולי לא אוליכם שם אבל אניעם במדבר עד תום כל הדור הרע הזה ולזה צוה הש' ית' ואמר מחר פנו וסעו לכם המדברה דרך ים סוף ואע"פ שכבר נזכר במה שאחר זה שהעמלקי והכנעני הוא יושב בהר הנה ידמה שהיו עולים אליו מצד אחד ויורדים אליו מצד אחר ואפשר שנאמר שזה הפסוק דבק אל הפסוק הקודם לו והוא שזרעו יירשנה ויוריש גם כן העמלקי והכנעני הוא יושב בעמק אצל ההר ההוא:
@537 **ובניכם יהיו רועים במדבר ארבעים שנה.** ר"ל עד מ' שנה הוא מיציאת מצרים והנה אחרם הש' ית' שם עד מ' שנה כדי שלא ימיתם בזולת עתם כי הקטנים שבהם שהיו אז מבן עשרים שנה ומעלה יהיו להם קרוב לס' שנה בעת ההוא ואיננו זר אם ימותו אלו בהיותם קרובים להיות להם ס' שנה כי אשר היו בני כ' שנה היו מעטי המספר ואולם מוציאי הדבה רצה ה' ית' שימותו תכף לפרסם שכבר נענשו על זה המרי:
@548 **ויעפילו לעלות על ראש ההר.** ר"ל שכבר הגביהו לעלו' שם בתכלית מה שאפשר והוא שיהיה בראש ההר:
@551 **כי תבואו אל ארץ מושבותיכם.** מגיד שאין הקרבנות והנסכים נוהגים אלא בארץ:
@552 **ועשיתם אשה ליי'.** ר"ל עולת בהמה או זבח שלמי' למדנו מזה שחטאת ואשם אינן טעונין נסכים שהרי אין באים בנדר ונדבה והכתוב אומר לפלא נדר או נדבה והנה אמרנו שכתו' מדבר בעולת בהמה לפי שכבר ביאר זה ואמר מן הבקר או מן הצאן ללמד על עולת העוף שאינ' טעונה נסכים והנה לפי הוראת הגדר הרצון בנדבה שיתנדב האדם הבהמה ההיא ויאמר הרי זו עולה והרצון בנדר הוא שיאמר הנודר הרי עלי עולה ולזה אמר בפרש' אמור אל הכהנים על בעל מום נדבה תעשה אותו ולנדר לא ירצה והנה הוצרך לומר או בנדבה כי מפני שהבעל מום יתכן שיהיה נדבה ולא יתחייב הנודר בזולת הבהמה ההיא ר"ל שלא יתחייב בנסכים היה אפשר שיחשב שלא יתחייב המתנדב בזולת מה שהתנדב ולא יתחייב בנסכים:
@552 **או במועדיכם.** הוצרך להזכיר במועדיכם שלא יחשב חושב כי מפני שלא הותר לעשו' בהם אלה מה שהוא לצורך אוכל נפש לא ידחה יום טוב ושבת אלא לקרבנות בעצמם שהוגבל בהם זמן ולא יהיו בהם מנחות לזה בא ללמדנו שהמנחות גם כן מותר לעשות אז ומזה המקום למדנו שהמנחות אינם מעכבו' ממה שנזכר במעשה העולה והמשלמים בפרש' ויקרא ולזה אמרו שאם לא קרבו המנחות היום יקרבו למחר:
@553 **והקריב המקריב קרבנו.** למד שלכבש אחד היה שיהיה עולה או זבח. תהיה המנחה עשרון אחת סלת. שיהיה בלול ברביעית ההין שהם ג' לוגים ויהיה שם יין לנסך רביעית ההין ג"כ ויתבאר במה שיבא איך יהיה עניין הניסוך הזה וכן אם היו הקרבים כבשים רבים תהיה מנחת כל אחת מהן ככה כמו שאמר אחר זה כמספר אשר תעשה ככה תעשו לאחד כמספרם או לאיל תעשה מנחה לפי שכבר הקדימה התורה זכירת מנחת הכבש למדנו שתכלי' מה שיהיה מזה המין שיספיק לו זה השיעור המעט מהמנחה הוא הכבש ולזה יתבאר שמה שהיא למעלה מהכבש יתחייב בנסכי איל וזכר האיל והוא הדין לפלגם ואלו היה מתחיל להזכיר נסכי האיל היה מתבאר שמה שהוא קטן מאיל יפטר בנסכי כבש והתבונן זה המקום כי הוא נפלא עם שכבר ידמה שכבר ישולח על הפלגם שם איל:
@557 **וכי תעשה בן בקר עולה או זבח.** למדנו שלא חלק הכתוב בבקר בין קטני' לגדולים בעניין הנסכים' והמנחה והנה היתה מנחתו ג' עשרונים סלת בלול בשמן חצי ההין שהוא ששת לוגין:
@559 **ויין תקריב לנסך חצי ההין אשה ריח ניחוח ליי'.** למדנו שהיין בכללו היה אשה ריח ניחוח ליי' והנה אם כן איננו לבלילת הסלת אבל היה שופך אותו על המזבח שהיו מקריבין שם הקרבנות ולפי שאי אפשר לשפכו על האש אשר על המזבח כי התורה הזהירה מלכבותו כמו שנתבאר בפרש' צו הנה הוא מבואר שהיו במזבח כמין חוטמין שמשם יורד היין למטה במקום שלא יתלכלך המקדש לכבוד הש' ית' וכן ראוי שנבין מהדמים הנשפכים אל יסוד המזבח שכבר היה מחוייב שיהיה שם מקום יכנסו בו כדי שלא יתלכלך המקדש ולא יהיה שם עפוש:
@560 **ככה יעשה לשור האחד.** למדנו שלא הבדיל הכתוב בשור בין קטן לגדול והנה שור בן יומו קרוי שור שנאמר שור או כשב או עז כי יולד:
@560 **או לשה בכשבים או בעזים.** לפי שלא זכר עזים כי אם אצל שה למדנו שלא הבדיל הכתוב בעזים בין קטן לגדול:
@561 **כמספר אשר תעשו ככה תעשו לאחד במספרם.** לפי שהמספר לא יהיה אלא באחדים המסכימים למדנו מזה שאין מערבין נסכי כבש בנסכי איל ר"ל נסכי מין אחד בנסכי מין אחר ואולם אשר ממין אחד יתערבו כי התורה לא דקדקה אלא שיהיו כמספרם ולפי שהמנחה היות' קטנה הוא עשרון למדנו שהמתנדב מנחה אינו פחות מעשרון ולפי שהמעט שמצאנו בנסכי' הוא לוג כמו שנזכר בפר' מצורע הוא מבואר שאין ראוי שיתנדב אדם פחו' מלוג שמן:
@562 **כל האזרח יעשה ככה.** ר"ל על הקרבת אשה יעשו אלו המנחו' והנסכים ולמדנו מזה שהאזרח הוא שיתחייב בנסכים לא הגוי אע"פ שהוא מקריב עולות לפי מה שנתבאר בפרש' אמור אל הכהנים ולזה נצטרך לבאר אחר זה שהגר שנתגייר חייב במנחות ונסכים:
@563 **וכי יגור אתכם גר וגו'.** הרצון בזה שהגר שיתגייר או הגר שכבר נתגייר יחוייבו במנחות ונסכים כמו העניין בישר' והנה מזה המקו' למדנו כי הגר בעת שיתגייר יקריב קרבן ולפי שכבר מצאנו בישראל בעת שנכנסו תחת כנפי שכינה שהקריבו עולות ושלמים כמו שנתבאר בסוף פרשת ואלה המשפטים למדנו מזה שהגר גם כן יחוייב בקרבן בעת הכנסו תחת כנפי שכינה ולפי שנאמר בכאן ועשה אשה ריח ניחוח ליי' ואין שם קרבן שיהיה כלו אשה ריח ניחוח ליי' זולת העולה למדנו מזה שהגר מתחייב בעולה ולפי שהעולה כבר נתבאר שתהיה מן העוף כמו שנתבאר בפרש' ויקרא הנה יספיק לגר שיביא עולת העוף וכבר יתבאר גם כן כי הגר יחוייב להביא קרבן ממה שראינו ממנהג התורה כאשר תרה להעתיק האדם מלא קדושה לקדושה שתעשה בזה האופן כמו שמצאנו בישראל כשקיבלו את התורה ונתקדשו בה שהקריבו וכמו שמצאנו בישראל כשקיבלו את התורה ונתקדשו בה שהקריבו וכמו שמצאנו באהרן ובניו כשנכנסו לקדושת הכהונה וכמו שמצאנו בלויים כשנכנסו לקדושת הלויה. ולפי שכבר מצאנו בלויים שהקריבו חטאת ועולה ובכהנים שהקריבו חטאת ועולה ושלמים ובישראל שהקריבו עולת ושלמים למדנו מזה שלא יחוייב בכמו זה הענין כי אם עולה כי מה שנשתתפו בו אלו כלם הוא העולה ולזה הוא מבואר שראוי שנדע שלא יתחייב הגר כי אם בעולה ונלמד שהוא מחוייב בטבילה ממה שראינו גם כן בישראל בעת מתן תורה ובכהנים והלויים ונלמד שהוא מחויב במילה ממה שנזכר בסו' פרשת לך לך אלא שהמילה אינה מעכבת הגרות כי כבר מצאנו שאפילו ישראל יתכן שימנעו מהמילה כאשר היתה שם סבה כמו שנזכר בספר יהושע שלא מלו העם היוצאים ממצרים. ועוד שכבר מצאנו מה שהוא משותף באלו הדברים שזכרנו הוא הטבילה והקרבן ולזה הוא מבואר שהטבילה היא מעכב לא המילה:
@564 **הקהל חקה אחת לכם ולגר הגר.** למדנו מזה שהגר לא יתכן שיתגייר כדי לקיים קצת מצות התורה אבל ראוי שיקיימם כלם כשיתגייר. וזה כי התורה הוא נימוס אח' שלם מכוין לתכלית אחת אי אפשר בו התוספת ולא הגרעון ולזה לא יתכן שיקובל קצת הנימוס ההוא לבד. ולפי שאמר לכם ולגר הגר למדנו שהוא מדבר בגר בעת היותו מתגייר כי זה הלשון מסכים אל מה שאמר תחלה וכי יגור אתכם גר ואמר ככם כגר יהיה לפני יי' ר"ל במה שהוא מהקרבנות לפני יי' והוא העולה כי השלמים אינם לפני יי' כי אם מה שהוא מהם כליל לאישים:
@567 **דבר אל בני ישראל ואמרת אליהם בבאכם אל הארץ והיה באכלכם מלחם הארץ.** למדנו מזה שתכף שנכנסו ישראל לארץ ואכלו מלחם הארץ נתחייבו בחלה ולפי שלא יאמר לחם לפי הנהוג לפי מה שיורה עליו הגדר אלא על מה שהוא מחמשת המינים למדנו מזה שחלה אינו נוהגת אלא בחמשת המינים:
@569 **ראשית עריסותיכם חלה תרימו תרומה.** מאשר אמר ראשית עריסותיכם במוחלט למדנו מזה שאיך שיעשו בארץ עיסה הנה היא חייבת בחלה ואף על פי שהיא מתבואת חוצה לארץ ועניין החלה הוא שירימו מהעסה חלה אחת תהיה תרומה והיא נתנת לכהן כמו שיתבאר במה שיבא והוא מבואר שאין ראוי שתהיה כל העסה חלה כמו שלא יהיה כל הכרי תרומה וכבר אמר בתרומת גורן כן תרימו אותה והוא מבואר מהשרשים הכוללים שקטן השיעור שיהיה נהוג לעשות ממנו עיסה יתחייב בחלה שנאמר עריסותיכם שיהיה נהוג להעשות עיסה בכמו זה השיעור וכבר נתבאר מצד הוראת הגדר שלא יפול זה השם על פחות ממלא העומר כי כבר הוגבל זה השיעור לאיש אחד ביום אחד בענין המן. והנה זה השיעור הוא עשירי' האיפה כמו שנזכר בתורה והעומר עשירית האיפה הוא והאיפה הוא ע"ב לוגין ולזה יהיה זה השעור שעור ז' לוגין וחומש הלוג. והוא מבואר שכבר יקרא לפי הנהוג עסה מה שלא נשלמה הלישה בו כיון שהתחילו ללושו ומן אז יתחייב בחלה והנה לא הגבילה התורה שיעור לזאת התרומה וכבר נתבאר בתורה בחלות תודה שהתרומה תהיה אחד מעשרה וכן הענין בתרומת מעשר שנאמ' והרמותם ממנו תרומת יי' מעשר מן המעשר ובמלקות השבי בפרשת מדין מצאנו במקום אחד שהתרומה תהיה אחד מחמשי' ובמקום אחר מצאנו שם שהתרומה תהיה אחד מחמש מאות ולפי ששם התרומה לא יפול על חלק מוגבל לפי הלשון הנה הוא מבואר שאי זה חלק שירימו מהעסה שיתכן שיפול עליו שם חלה יספיק לפי משפט התורה אמנם מדברי החכמי' היה שיתן בעל הבית אחד מכ"ד ונחתום אחד ממ"ח לפי שהנחתום מדרכו שיאפה יותר בבת אחת מבעל הבית לפי שהוא מוכר לאנשים רבים ואולם בתרומת גורן יספיק אפי' חטה אחת לפי לשון התורה ואולם מדברי חכמים הוא אחד מחמשים והוא השיעור הבינוני שנמצא בו לשון תרומה כמו שזכרנו כי הוא פחות מאחד מעשרה ויותר מאחד מחמש מאות ולפי שהעין רעה תתחלף בשיעור הדבר שיבואו בו על צד האומר בחמשית השעור ולזה רצתה התורה שהבעלים יוסיפו חומש בדברים שנזכר בהם בתורה הנה תהיה עין רעה פחות מזה החומש ועין יפה יותר על זה החומש ולזה אמרו עין יפה אח' מארבעים עין רעה אחד מששים:
@571 **וכי תשגו ולא תעשו את כל המצות האלה.** ראוי שתדע שאין הכונה בזה שתהיה השגגה בכל המצו' שאם היה העניין כן היה מתחייב ממה שנתבאר בפרשת ויקרא שיתחייבו על כל מצוה ומצוה קרבן אם מעיני העדה נעשתה בשגגה ועוד שכבר מצאנו בסוף העניין מה שיורה בביאור שהעבירה הוא על מצוה אחת שחייבין על זדונה כרת שנאמר והנפש אשר תעשה ביד רמה ונכרתה הנפש ההיא כי דבר יי' בזה ואת מצותו הפר ולא אמר זאת מצותיו הפר. ובכלל הנה הוא מבואר מזה שלא היתה העבירה כי אם על מצוה אחת והנה תאר זאת המצוה שהעובר עליה הוא מגדף את יי' כמו שאמ' את יי' הוא מגדף ושהעובר עליה עובר על כל המצו' שבתורה והנה המצוה שזה דרכה היא ע"ז שהעובר עליה כופר בכל התורה כי כשלא יאמן בשם יתעלה סרה ההאמנה במצותיו ומזה המקום למדנו שהמצות הנזכרות בפרשת ויקרא שיתחייבו על שגגתן חטאת הם אשר יתחייבו על זדונם כרת כמו שזכרנו שם:
@573 **והיה אם מעיני העדה נעשתה בשגגה.** כבר ביארנו התנאים הנכללים בזאת הפרשה בפרש' ויקרא ילקח משם והנה הרצון בעיני העדה בית דין הגדול:
@573 **ועשו כל העדה.** רוצה לומר כל עדה ועדה והרצון בו כל שבט ושבט כי השבט יקרא קהל אל עדה להיות כל אחד מהם מיוחד ונפרד מהאחר כי ישראל היה שוכן לשבטיו וכבר מצאנו בביאור שהשבט יקרא קהל שנאמ' ויעמוד יהושפט בקהל יהודה הנה היה בזאת העברה פר ושעיר לכל שבט ושבט מה שאין כן בשאר העבירות שחייבין על שדונן כרת כמו שנתבאר בפרשת ויקרא והנה יתבאר ממה שזכרנו ששבט יהודה נקרא קהל שכל שבט שנשתלשל מאחד מבני יעקב נקרא קהל ואמנם מנשה ואפרים שנשתלשלו שניהם מיוסף לא יהיו שניהם כי אם שבט אחד:
@574 **וכפר הכהן על כל עדת בני ישראל.** הנה יאמר' במשפטי' התוריים כל על הרוב והנה מצד התאחד בני ישראל יהיה רב המספר ומצד כללות העדות ומספרם יהיה הרוב רוב השבטים והנה אי אפשר שנאמר שיהיה הרצון במה שאמר ועשו כל העדה שיהיו העושים זה הקרבן ב"ד הגדול שהרי אמר בפרשת ויקרא וסמכו זקני העדה ואם היה רומז אל בית דין הגדול לא היה אומר זקני העדה כי כלם היו זקנים ולזה הוא מבואר שהם זקני ישראל ולפי שאמר זקני העדה ולא אמר זקני ישראל למדנו שכל עדה ועדה מביאה קרבן ולזה התבאר שכל שבט ושבט מביא קרבן כיון שעשו בשגגה רוב ישראל על פי בית דין הגדול:
@574 **ונסלח להם כי שגגה היא וגו' כי לכל העם בשגגה.** ראוי שתדע שכבר יתבאר מזה שאם לא היה שגג' לעוש' העברה כגון שידע בודאי שכבר טעו ב"ד בהוראתם הנה אם עשה זה במזיד את יי' הוא מגדף ולא תהיה לו כפרה מפני זה הקרבן ואם שגג כשחשב שאף על פי שטעו ב"ד הגדול מצוה לשמוע להוראתם הנה לא נצטרף שגגתו לשגגת הקהל שסמכו על הוראת ב"ד כשחשבו שכל היוצא מפיהם מסכי' לכונת התורה כי אין שגגתו ממין שגגם והכתוב אומר כי לכל העם בשגגה שמורה שהיה השגגה אחת לכל העם ולזה יתחייב חטאת יחיד על שגגתו:
@575 **ולגר הגר בתוכם.** הנה הוצרך לומר ולגר הגר בתוכם לפי שכל שבט ושבט הוא מביא קרבן ולזה היה לחושב שיחשוב שלא יהיו נכללים הגרים באלו הקרבנות ולמדה התורה כי הגרים נמנים עם השבט שהם אצלו:
@576 **ואם נפש אחת תחטא בשגגה.** לא הבדיל בזה המקום בין כהן משיח או נשיא להדיוט וכבר הבדיל בזה בפרשת ויקרא ואחשוב שהסבה בזה כי בעבודה זרה יהיה דין הכהן משיח והנשיא שעבר עליה כדין ההדיוט כי ההעברה הזאת תסיר מהמשיח ומהנשיא יתרונו על הדיוט והכבוד הראוי לתת לו ולזה רצה שיהיה קרבן המשיח והנשיא שוה לקרבן ההדיוט בשגגת ע"ז:
@580 **הכרת תכרת הנפש ההיא.** הכרת הוא אבדון הנפש והפסק ממנה שלמותה:
@581 **וימצאו איש מקושש עצים ביום השבת.** ידמה שסמך חלול שבת לעניין עבודה זרה להדמות מה אשר ביניהם וזה כי המחלל את השבת כופר בפנים מה מהתורה בכללה כי שרש התורה היה נבנה על האמנת החדוש כי זה ייסד לנו שני שרשים כוללים גדולים האחד שה' ית' הוא נמצא והשני שהוא חדש העולם וכשנאמין זה יביאנו זה להאמין מה שצונו בתורה ולהורות על שני אלו השרשים באה מצות שבת ולזה יהיה המחלל שבת כאלו פורק מעליו עול מצות התורה בכללם והנה הרצון במקושש שיהיה תולש את העצים ומחבר מהתלוש אגודה או שהיה מאסף העצים הנתלשים ומעתיק אותם ממקום למקום והנה היה זה מלאכה מצד ההעתקה ממקום למקום כמו שבאר בפרשת ויהי בשלח במה שאמר אל יצא איש ממקומו ביום השביעי:
@583 **כי לא פורש מה יעשה לו.** ר"ל שלא נתפרש עדיין באי זו מיתה ימות והנה החמירה התורה בזאת המיתה שתהיה בסקילה מצד מעלת מצות שבת והוא מבואר שזאת הפר' הכתבת בזולת מקומה לפי הזמן שהיה בו זה המקרה וזה שכבר יתבאר ממה שאמר ויהיו בני ישראל במדבר שתכף שהיו ישראל במדבר מצאו זה ר"ל אחר שנתן להם השבת הנה היה זה בהכרח בשבת השנייה כי השבת הראשון לא היה מתבאר להם חיובה כמו שביארנו שם ואם לא יהיה הפירוש כן מה בא ללמדנו אמרו ויהיו בני ישראל במדבר הלא ידענו שכבר עמדו שם ארבעי' שנה ולא יתבאר מזה באי זה זמן היה ולזה הוא מבואר שזה בא ללמדנו שתכף שהיו ישראל במדבר נהיה זה העניין:
@584 **רגום ירגמו אותו באבנים.** כבר התבאר בפרשת יתרו כי הסקילה והירייה דינם אחד כי אין הבדל בין שיכו מהאבן על האדם או מהאדם על האבן ולפי שהוא ראוי בעניין הטלת העונשין שננהג בהם ביותר קל שאפשר עם שמירת מצות התורה כמו שהתבאר בשרשים הכוללים והיה מבואר שהמיתה בירייה היא יותר קלה מהמיתה בהשלכת האבנים עליו הנה היו יורים אותו ממקום גבוה שיתכן שימות מהנפילה ההיא שנאמר יד העדים תהיה בו בראשונה להמיתו והנה שערו חכמים שזה היה אפשר כשיונח בית הסקילה גבוה שתי קומות ואם לא מת בזה הנה אין ראוי שיפילוהו שנית כשישיבוהו שם אבל ראוי שיפיל העד השני עליו אבן שתהיה בה כדי להמית שנאמ' יד העדים תהיה בו בראשונה להמיתו והנה היה זה המשפט נעשה מחוץ למחנה לפי שזה החוטא ראוי שיצא מחוץ למחנה כמו שיצא המצורע מחוץ למחנה לשמור אנשי המחנה מהתגאל בחלאת החטא העצום אשר עליו שצותה התורה להמיתו.
@587 **ועשו להם ציצית על כנפי בגדיהם לדורו'.** אחר שכבר זכר העבירות שבהם רושם מה לסור מכל מצות התורה זכר המצוה אשר יש לה רושם בקיום מצות התורה בכללם כמו שאמר וראיתם אותו וזכרתם את כל מצות יי' וזה ימשך בכלל מצות הציצית לפימה שאחשוב לשתי סבות האח' הוא כי הלבוש ילבשהו האדם תמיד ויהיו עיניו בו וכאשר יראה בו מצוה אחד ממצות השם יתעלה יזכור את בוראו וירא מלסור מאחרי ה' יתע' לבלתי קיי' מצותיו כמו שספרו רז"ל מאיש אחד היה רוצה להכשל בזמה עם זונה אחת יפה מאד וכשעת מעשה ראה ארבע ציציותיו וזכר את בוראו ונמנע מהתגאל בזאת העברה המגונה והשנית היא כי זאת המצוה תישיר האדם להודות במציאות השם יתעלה אשר הודאה בו תישיר להאמין בכל מצות התורה כמו שהכפירה בו תהיה סבה לעבור על כל מצות התורה וזה כי ארבע כנפות יעירו על עניין היסודות אשר בעולם השפל והציציות מורים על רבוי הדברים המסתעפים מהם וחוט התכלת הקושר הציציות ומחבר אותם מורה על הגרמים השמימיים שמראיהם אצל החוש במראה תכלת ויורה שכל אחד מהם יסתעפו ממנו פעולות רבות ולזה היו הציציות בכל אחד מארבע כנפות ולפי שזה בלתי אפשר בהם אלא מצד רבוי היחסים המתחלפים אשר להם עם אלו הנמצאות השפלות וזה אמנם יהיה ברבוי התנועות אשר לאחד אחד מהם ומה שזה דרכו יחוייב שיהיה עלול לא עלה ראשונה כמו שהתבאר במקומותיו הנה זה יורה כי גבוה עליה' ויורה שהוא אחד מצד הקשר כל הפעולות הנאצלות מהם לתכלית אחד כי כולם פועלי' בענייני זה העולם השפל לפי מה שנתן להם מהכח ביום הבראם וישלמו אלו הפעולות במה שישפע מכלם ואם לא היתה שם עלה אחת תישירם אל זה איך יתכן שיהיו כלם משתתפים בפעלה אחת מצד מה שהיא אחת ונכלל הנה זה מה שיישיר באופן שלם אל שבכאן סבה אחת עליונה יסודרו ממנה כל אלו הדברים הוא השם יתעלה וכבר בארנו זה מזה המקום בשלמות בה' מספר המלחמות ה' ולזה נהגנו לעשות בציציות מהקשרים והחליות מה שיעיר על השם שנקרא בו השם יתע' או לעשותם במספר הגרמים השמימיים להורות שכלם משתתפים בפעלה אחת כי זה ממה שיביא להורות אל שיש בכאן עליהם סבה תישירם אל זה והוא האלוה יתעלה:
@587 **על כנפי בגדיהם.** כבר נתבאר במשנה תורה שלא ינהג זה כי אם בבגד שיש לו ארבע כנפות שנאמר על ארבע כנפות כסותך אשר תכסה בה והסבה מבוארת ממה שזכרנו ואם היו לטלית ארבע כנפות או יותר יחויי' לעשות ציצית על ארבע כנפות לבד מהבגד ההוא אבל אם לא היו לו ארבע כנפות אינו מחוייב ציצית ומשם יתבאר שזה הציצית הוא עשוי במעשה גדילים להורות על מה שיקשור רבוי הפעולות וישימם כלם בענין אחד. והנה התכלת הוא לפי הוראת הגדר צמר צבוע בדם חלזון ואמר ועשו להם ציצית להורות על שבעת העשייה ראוי שיהיה נעשה לשם ציצית כמו שבארנו בדומה לזה במעשה הפסח והחטאת:
@587 **על כנפי בגדיהם.** ר"ל אצל כנף בגדיהם והנה לא נתנה התורה שעור לכתחילה אמנם שיריו וגרדומיו בכל שהו והנה הוגבל מספר החוטים להיותם שמנה במספר. רוצה ללומר ששם ארבעה חוטים יכנסו בכנף הבגד ולזה יהיו שמנה כשהיה קצתם מעבר זה וקצם מהצד השני וזה נמשך לכוונת התורה ששמה מספר הכנפות ארבעה לסבה שזכרנו ובפתיל התכלת יתחברו כלם בחליות הנעשות ממנו על החוטין להעיר על עניין הגרם החמישי שישפיע ה' ית' באמצעיתו אלו הפעלו' והיה לכם לציצית. ביאר בזה עוד שהעשייה בתכלת יחוייב שתהיה לשם ציצית וזה כלו הוא כדי שיעמיקו יותר בכוונת זאת המצוה:
@588 **וראיתם אותו.** למדנו מזה שלא תנהג זאת המצוה אלא ביום שהוא עת ראיית הדברים לפי הנהוג ועוד למדנו ממה שאמר וראיתם אותו ולא אותו וחברו. ר"ל אין ראוי לאדם שישא יחד שני טליתות מצוייני' וכן למדנו זה ממה שאמר אשר תכסה בה והנה מפני שהיתה הצואה הזאת לבני ישראל למדנו שאין הנשי' חייבות בציצית וראוי היה להיות כן כי הענין אשר העיר עליו זאת המצוה הוא רב העומק ולא יתכן שיגיע אליו שכל הנשים לקלות דעתן:
@588 **וזכרתם את כל מצות יי'.** לפי שזאת המצוה מורה על מציאות השם יתעלה כמו שביארנו:
@588 **ולא תתורו אחרי לבבכם.** ר"ל שזה ישמרכם מלתור אחרי לבבכם אם יש שם אלוה אם לא ומלתור אחרי עיניכם אי זה מהדברים הנראים הוא יותר ראוי שיהיה אלוה כי העינים לא ישיגו אלא הגופות כי זה יישירכם להשיג שיש שם אלוה הוא המנהיג עולם הגלגלים והעולם השפל והנה ידמה שאין לאו זה אזהרה תמנה מכלל המצות כמו שאין אמרו וזכרתם את כל מצות יי' מצות עשה אבל הגידה התורה התועלת הנמשך ממצות ציצית והתועלת המגיע מהמצוה לא ימנה מצוה:
@589 **והייתם קדושים לאלהיכם.** רוצה לומר בעשותכם מצות התורה תהיו קדושים לש' ית' כי כוונתם בכללם להישיר לעבודת השם ית' ולהתקדש מטומאת התאוות הגופיות:
@590 **אשר הוצאתי אתכם מארץ מצרים וגו'.** ר"ל שכר הוציאם מארץ מצרים באופן שיהיה להם לאלהים מצד עוצם הנפלאות שראו אז ישראל והנה רמז עם זה בזה המאמר אל מה שביארנו בעניין ברית בין הבתרים והוא כי אברהם כששאל אות על ירושת הארץ לפי שזה הייעוד יחוייב שיהיה בו תנאי והיא שיהיה זרעו באופן מהשלמות שיתכן שידבק בו זאת ההשגחה הנפלאה מה' ית' ובאהו המענה כי השם ית' יישירם אל השלמות כשישימם גרים בארץ לא להם ובעבדות נפלא ואחר זה יהיה דן את הגוי ההוא אשר יעבודו ויוציאם ברכוש גדול ובאלו הדינין. והמכות אשר דן הגוי ההוא הישיר ישראל אל השלמות באופן שהיו ראויים לקבל התורה שיהיה בהם השם ית' להם לאלהים והם לו לעם.
@591 **ויקח קרח.** הרצון בו עניין לקיחת הנפשות באופן שימשך לב רבים מישראל אליו לקנאתו על גדולת משה ואהרן והנה לא ספרה התורה הפתויים אשר פתה בהן לב החמשים ומאתים איש אשר היו מגדולי העם ומהנכבדים שבהם וכבר זכרו מזה רז"ל קצת ספורים במדרשיהן והוא מבואר שכבר משכו לבם כשאמרו שכל הגדולה נטל משה לעצמו ולאחיו אהרן כי הוא יה מלך ואהרן כהן גדול והיתה הכהונ' לו ולזרעו אחריו ולא עבר זר בתוכם וידמה מזה הספור שלא היו מרעמים על מלכות משה רק על כהונת אהרן ולזה אמר ובקשתם גם כהונה:
@595 **בקר ויודע יי' את אשר לו.** ר"ל שהגדולה הזאת לא נתתי לאהרן מעצמי רק ה' יתע' בחרו וזה יתבאר בבקר היום הבא אחר זה והנה הודיעם בזה המאמר כי ה' יתע' לא יבחר כי אם באחד לבד ולזה היה לירא מהקריב הקטרת כי לא יבחר בכלן רק באחד לבד:
@597 **ותנו בהן אש ושימו בהם קטרת.** אחשוב שהאש לקחו מהמזבח הנחשת שאם היה שם אש זרה לא יהיה שם אות מפני מיתתם שאינן ראויים לכהונה כי גם בני אהרן עם היותם כהנים מתו בהקריבם אש זרה לפני יי' ולזאת הסבה בעינה אחשוב גם כן שלקחו מהקטרת שהיו מקטירים ממנה במזבח הפנימי לא קטרת זרה שאם היו מקטירים שם קטרת זרה לא תהיה מיתתם על זה מורה שלא בחר השם ית' בהם להיותם כהני' כי אפילו זרע אהרן היו מתים אם היו עושים כן:
@597 **רב לכם בני לוי.** אמר זה להצילם שלא יבקשו גדולות כי די להם במה שנתן השם ית' מהגדולה כי הוא היה חומל עליהם אף על פי שהיו מעצבים אותו וכאשר ראה שלא נתפייסו בזה אך היו מחזיקין בבקשתם אמ' להן מש שמעו נא בני לוי המעט מכם מה שנתן לכם הש' ית' מהגדולה שהבדיל אתכם מעדת ישראל להקריב אתכם אליו יתע' יותר משאר העם וששם אתכם עובדים עבודת משכן השם ית' באופן שקדם בראש זה הספר רוצה לומר לעבוד ולמשא ולשמור משמרת המשכן והבדיל אתכם לעמוד לפני העדה לשרתם ידמה שזה השרות הוא השיר שהיו הלוים אומרים בפה כמו שנתבאר בעזרא ולמדנו מזה שהשרו' הוא בעמידה עם שזה דבר מבואר בעצמו כי הישיבה מורה אדונות ושררה לא שירות ויקרב אותך ואת כל אחיך בני לוי אתך. שהם ממשפחת קהת יותר משאר משפחות הלויים בששם עבודתכם בקדש הקדשים ולא די לכם זה אלא שאתם מבקשים עוד כהנה ואחר שכן הוא שזה העניין היה כלו מה' יתע' הנה אתה וכל עדתך נועדים לעשות כנגד השם יתעלה לא כנגד אהרן כי לא היה זה מצדו אך השם ית' בחר אותו להיות לו לכהן:
@604 **ותתן לנו נחלת שדה וכרם.** רוצה לומר שלא די שלא הביאותנו אל ארץ זבת חלב ודבש כמו שיעדת לנו אפילו שדה וכרם לא נתת לנו ועם זה התחשוב לעשותנו כעורים שלא נראה כי הבטחתנו בדברי שקר:
@605 **אל תפן אל מנחתם.** אחשוב שאין זה בקשה ממשה כי זה בלי ספק לא היה צריך לזאת הבקשה כי הם היו עושים כנגד ה' ית' ואין ספק שהוא לא יפנה אל מנחתם ולזה ידמה שיהיה עניינו כמו זכור מלחמה אל תוסף שאינו בקשה אך הוא ספור העניין וכזה אמר משה הנה אין ספק שאתה אל תפן אל מנחתם כי לא עשיתי להם שום דבר שיהיה להם בעבורו מקום להתרעם על שררותי:
@609 **ויקהל עליהם קרח את כל העדה את פתח אהל מועד.** ידמה שמשך קרח בדבריו החמשים ומאתים איש לעשות זה כי אולי הם יראים ממה שאמר מזה שאשר יבחר בו השם ית' הוא הקדוש כי זה מורה שכלם ימותו זולת אחד מהם או יהיה אמרו כל העדה שב אל ישראל כשהיה מושך את לבבם להתרעם על משה על דבר זאת השררה:
@612 **אל אלהי הרחו' לכל בשר.** הרצון אמרו לכל בשר לכל אישי האדם כטעם אמרו יבא כל בשר להשתחות לפני והנה הרצון בזה אל שהוא שופט הרוחות אשר לכל בשר בשיודע לאיש ואיש מהם צדקו ורשעתו היהיה נכון שתקצוף על העדה בעבור חטא איש אחד חלילה לך מעשו' זאת:
@618 **בזאת תדעון כי השם שלחני וגו'.** נתן להם משה אות אשר יכירו בו כי זה פעל אלהי והוא שאלו לא ימותו כמות כל האנשים אך שהשם יתעלה יברא בריאה בעבורן תתחדש ממנה פתיחת הארץ את פיה ותבלע אותם ואת כל אשר להם באופן שירדו חיים בעומק הארץ והוא שקרא שאול והנה היתה זאת הבריאה בהשם יתעלה אז על דרך מופת בבטן הארץ אשר תחתיהם מה שנה חדש ממנו בקיעת הארץ והנה היה ענין זה המופת שמה שיעשה על דרך הטבע בזמן ארוך אורך נפלא עשה השם יתעלה על דרך המופת בזמן רגע וכן דרך שאר המופתים הנעשים על ידי נביא כמו שביארנו בששי מספר מ"י וכן אמרו זה רז"ל אם נברא פה לגהנם מוטב ואם לא יברא יי' ובסוף הענין אמרו שהמופת היה לקרובי פתחא אול יספק מספק ויאמ' כי עדיין היה אפשר שיהרהרו שמא היה משה יודע על דרך הנבואה כי המקום ההוא שהיה בו הגיע עתו להבקע שם הארץ ולא יהיה מזה אם כן מופת על שזה הענש הגיע להם מפני מרדם אלא שהיתר זה הספק הוא ממה שיקל וזה כי לא יתכן שיאמר שזה היה במקרה ויסכים זה למקום שהיו בו אלו האנשים לבד כי מה שבמקרה בזה האופן הוא מעטי אבל שיסכי' לרבוי מה ויבחרם מבין השאר הנה זה בלתי אפשר שיוחס אל המקרה עם שכבר נגלה להם שימותו האנשים החמשים ומאתים איש מקריבי הקטרת וזה ממה שיורה שכל זה היה להם על צד העונש מהש"י כי החוטאים לבד מתו לא זולתם והיותר נפלא מכל זה שבמקום בעינו שנבקע הארץ עשה השם יתע' שהשאיר ממנה המקום שהיו בני קרח כי הם לא מתו כמו שיבא בפרשת פינחס והנה היה זה כן מפני שלא היו נמשכים עצת אביהם והנה אמרו רבותינו ז"ל שמקום נתבצר להם בגהנם והנה מה שאמר ואת כל האדם אשר לקרח. רוצה לומר בני ביתו הנמשכים לעצתו:
@627 **ואת האש זרה הלאה כי קדש.** ידמה מזה המקום שכלי שרת מתקדשי' אפילו בזולת משיחה כשישימו בהם מה שהם משמשים בו תדע שאלו הכלם קדשו כי הקריבום לפני השם כששמו בהם הקטרת אך עבודתם לא קדשה אותם כי היא לא היתה עבודה והנה רצה הש' ית' שירקעום צפוי למזבח לפרסם זה העניין באופן שיירא מי שאינו מזרע אהרן להקטיר קטרת לפני יי' פן יקרה לו כמו מה שקרה לקרח ועדתו על עשותם כן:
@630 **כאשר דבר השם ביד משה.** רוצה לומר אל אלעזר כי השם ית' דבר לו ביד משה שיקח את המחתות ויעשה אותם רקועי פחים צפוי למזבח:
@636 **קח את המחתות ותן עליה אש מעל המזבח.** ר"ל מעל מזבח החיצון כי כן היה משפט בהקטרת הקטרת על מזבח הזהב שהיו לוקחים אש מעל מזבח החיצון כמו שהתבאר במה שקדם וזה לאות שזה הקטרת היה קטרת הסמים שהיו מקטירים על מזבח הזהב. ויעתר לו השם יתע'. עד שכבר נעצרה המגפה תכף שהקטיר הקטרת:
@642 **וקח מאתם מטה מטה לבית אב וגו'.** הנה עשה זה המופת הנפלא שהוציא מטה אהרן פרח וצץ ציץ וגמל שקדים בזמן קצר מאד כדי שיתפרסם לישראל כלם כי השם ית' בחר באהרן לבדו להיות לו לכהן השב את מטה אהרן לפני העדות למשמרת כן מצאנו גם כן בצנצנת המן ששמהו אהרן לפני העדות למשמרת ולפי שהארון נקרא ארון העדות מצד הלוחות שהיו בתוכו שהן עדות לעניין התורה ואמר לפני העדות ולא אמ' לפני הארון למדנו מזה שבתוך הארון היו שאם היו חוץ ממנה היה ראוי שיאמר לפני הארון ולא לפני העדות עם שכבר יתכן יותר שהוא למשמרת כשהיה תוך הארון:
@654 **אתה ובניך ובית אביך אתך תשאו את עון המקדש.** הרצון בזה שאין לירוא לישראל שימותו על דבר משכן ה' כמו שאמר כל הקרב אל משכן ה' ימות האם תמנו לנוע וזה כי אתה ובניך והם הכהנים ובית אביך אתך והם הלוים תשאו עליכם עון המקדש אם יקרב אחד מכם במקום שאין לו רשות להכנס כאלו תאמר אם יכנס כהן גדול לפני לפנים בזולת יום הכפורים או אם יבאו אל אהל מעד או אם יגשו אל המזבח הבלתי ראוים לזה וכן תעשו בלויים אם יקרבו במה שאין להם רשות בו מהמשכן אבל איש על עבודתו ועל משאו:
@654 **ואתה ובניך אתך תשאו את עון כהונתכם.** ר"ל מה שהיה מהשגגה בענין העבודות שיעשו הכהנים במקדש יהיה משא העון על אהרן ועל בניו:
@655 **וילוו עליך וישרתוך.** ר"ל בעניין הכהונה וזה השרות הוא בעניין השיר שהיו משוררים הלוים בשעה שהיו הכהנים עובדים עבודתם אלא שהלוים לא יהיו לפני אהל העדות לעבוד עבודת הכהנה אבל יהיו הכהנים מבפנים לפני אהל העדות והלוים מבחוץ ולמדנו גם כן מזה המאמר שאמר ואתה ובניך אתך לפני אהל העדות שהוא ראוי שישמרו הכהנים בית המקדש תמיד ובזאת השמירה ילוו עליהם הלויים כמו שאמר ושמרו את משמרתך ומשמרת כל האהל אבל יהיו בזאת השמירה הכהנים לפני אהל העדות והלוים מבחוץ וכבר למדנו שזה ההלוות שהלוו הלוים לכהנים הוא עניין העבודה בשיר מאשר אמר אך אל כל כלי הקדש ואל המזבח לא יקרבו והנה כלי הקדש הם החצוצרות שהכהני' היו תוקעים בהם בשעת העבודה. והמזבח היא העבודה הנעשית בענין הקרבנות ויתר הדברים הבאים באחת מהמזבחות ומאשר לא הוציאם כי אם מאלו הענינים למדנו שהם משתתפים להם בענין אינו בכל הקדש ואינו קרב למזבח וכבר נתפרסם עוד ענין שרות הלו' בשיר בספר עזרא:
@656 **ושמרו את משמרתך ומשמרת כל האהל.** הוא משמרת כל העבודה המיוחדת להן ומש שימנום עליהם הכהנים בשמירתם כשיעשו להן גזברים ואמר כלים לשמירת הדברים אשר בבית ומשמרת כל האהל כשיהיו מהם שוערים ביום לשמור הבית ובלילה שלא ישנו קצתם כדי שתשלם לו השמירה תמיד ולא ימותו גם הם גם אתם. ולמדנו מזה שהלוים שנכנסו בעבודת הכהנים חייבים מיתה ולזה אמר גם הם ואמר גם אתם להורות שאם לא הקריבו הכהנים אליהם הלוים לעבוד עבודתם המיוחדת להם אבל עבדו הכהנים אותם העבודות הנה הכהנים חייבים מיתה ומזה המקום למדנו שכל מי שנכנס בעבוד' חברו כאלו תאמר שעבדו בני קהת עבודת בני גרשון או הפך:
@657 **ונלוו עליך ושמרו וגו'.** אחשוב שהרצון בעבודת האהל פירוקו והקמתו ומשאו על האופן הקודם ר"ל שהכהנים היו משימין הלוים איש על עבודתם ועל משאם:
@657 **וזר לא יקרב אליכם.** זו אזהרה כוללת לכל העבודות המיוחסות לכהנים וכבר ביאר בסוף זאת הפרשה העונש והוא אמרו והזר הקרב יומת וזאת המיתה היא חנק לפי מה שהתבאר מהשרשים הכוללים:
@658 **ושמרו את משמרת הקדש ואת משמרת המזבח וגו'.** הוא האזהרה שלא להתעצל בשמירתן כדי שלא יקרה עון בעניני שמיר' המקדש ובעניני העבוד' שתעש' במזבח ובזה האופן יהיו ישראל נשמרים ממה שהיו יראי' באמרם כל הקרב הקרב אל משכן ה' ימות כי הכהנים והלוים ישמרום מלהכנס במקדש ובעבדה באופן הנזכר אחר זה:
@659 **ואני הנה לקחתי את אחיכם הלוים מתו בני ישראל.** ר"ל שרבתי אותם לי ובחרתי בהם לעבודתי ולזאת הסבה לא היה ללוי חלק ונחלה בתוך בני ישראל והיו נתונים להם המעשרות כדי שיחיו בהם בזולת עמל ויהיה להם פנאי בחכמה ובתורה לעבוד השם יתע':
@659 **לכם מתנה נותנים להשם.** אמר שהלוים הם מתנה לכהנים אך לא שיעבדו הלוים הכהנים אלא בדברים שהם לה' והם העבודות הנזכרות שהיו מיוחדין ללוים והיו הכהנים משימין אותן עליהם לעבודת אהן מועד:
@660 **ואתה ובניך אתך תשמרו את כהונתכם וגו'.** ר"ל שאהרן ובניו לבדם יתעסקו בעבודת הקרבנות והנלוה אליהם ובקטרת ובמה שהוא מבית לפרכת יתעסק בו אהרן לבדו אחת בשנה כמו שקדם:
@660 **עבדת מתנה אתן את כהנתכם.** א"ל שזאת העבודה הוא לכם מתנה ואין מנהגה כמנהג העבודות שיכבדו על העובד אבל הנני נותן לכם מתנה נפלאה כזאת הכהונה אם מצד עצמותם לפי מה שהתבאר מדברינו בענין הקרבנות אם מצד המתנות הנתנות לכם מישראל בסבת הכהונה כמו שזכרנו בסמוך:
@660 **והזר הקרב יומת.** מפני 'סמך זה המאמר לעניין העבודה למדנו שלא יתחייב זר מיתה כי אם על העבודה ודבר העבודה הוא מה שהוא מכוון בעצמותו כמו נתינת האש על המזבח ועריכת העצים ומה שידמה לזה ואולם מה שאינו מכוון בעצמותו כמו הרמת הדשן ומה שידמה לו לא יתחייב מיתה עליו הזר וכבר ביארו זה ז"ל ממה שאמר עבודת מתנה אמרו עבודת מתנה עבודת מתנה ולא עבודת סלוק:
@661 **וידבר השם אל אהרן.** ראוי שלא יעלם ממנו שזה המאמר היה למשה בעבור אהרן וכן העניין בכל מה שדומה לזה כי התורה בכללה נתנה לנו ע"פ משה מפי הגבורה:
@661 **ואני הנה נתתי לך את משמרת תרומותי.** בעבור שמצאנו בזה המקום לך נתתים למשחה ולבניך לחק עלם ובמה שכלל בזאת הפרשה מעניין אלו התרומות אמר נתתי לך ולבניך ולבנותיך אתך ידענו שאין הכונה לזכרי כהנה לבד ומה שזכר נתנו לזכרים ולנקבות ולפי שמצאנו שמה שהוא לזכרי כהנה לבד הוא קדש הקדשים ידענו כי בו העיד בזה הפסוק ולזה המשיך הספור אחריו בענין קדש הקדשים ולפי שהתרומה אשר בקדש הקדשים היו לשם יתע' והנותר הוא לכהנים ולא יזכו הכהנים בנותר אם לא זכה המזבח תחלה באלו התרומות אמר שכבר נתתי לך את משמר' תרומותי שתעשה מה מה שצויתי להקטיר על המזבח זה המורם:
@661 **לכל קדשי בני ישראל לך נתתים למשחה.** ר"ל הקדשים ההן שנשארו אחר התרומה לך יהיה לאכלה ולבניך כי לא יאכלו אותם כי אם זכרי כהנה או אפשר שנאמר שיכלול בזה המאמר גם כן חלק הכהנים מקדשים קלים כי הם לא יזכור בו גם כן כי אם אחר' שזכה המזבח במורם מהם להשם ואמר ולבניך לבד לפי שזה דבר כולל לכל חלק הכהנים מן הכהנים היו קדשים היו קדשי הקדשים או קדשים קלים ואין הענין כן בבנות כי לא יאכלו מקדשי הקדשים:
@661 **לך נתתים למשחה.** ר"ל לגדולה ולזה ראוי שלא יקל בהם לאכלם כמנהג מאכל הפחותים אבל ראוי שינהגו באכילתם בכבוד לכבוד השם יתעלה:
@661 **ולבניך לחק עולם.** ידמה שרמז בה לקדשי הקדשים שינם נאכלים כי אם לזכרי כהונה שמהם הורם להשם כמו שביארנו והנותר הוא לאהרן ולבניו ואמר תרומותי לפי מה שירימו בהם בזה מתחלף למה שירימו להש' והמשל כי המורם מהמנחה היא זולת מה שמורם מהחטאת ואם הובן זה לפי הכונה השנית שזכר יהיה יותר מבואר ההבדל באלו התרומות בין קצתם קדש וקצתם קדש קדשים ואין ראוי לספק עלינו איך יקרא הכתוב קדשי בני ישראל מה שהוא קדש הקדשים וזה כי כל קדשי הקדשים קודש ואין כל קדש קדש קדשים ועוד על כל פנים צריך להודות שכבר נכלל בזה המאמר קדש קדשים אחר שזכרה התורה בפרטו זה הכלל:
@662 **זה יהיה לך מקדש הקדשים מן האש.** לפי שאמר זאת תחלה באופן כולל שב לבאר הבדל אלו התרומו' במה שיוחדו קצתם מן קצת ואמר מן האש להעיר שמן האש יזכו בו הכהנים ר"ל כי אחר שזכה המזבח בחלקו יזכו הם בחלקם וזה יורה על האמתת הביאור שביארנו במה שאמר ואני הנה נתתי לך את משמרת תרומותי:
@662 **כל קרבנם לכל מנחתם.** ר"ל הקרב לכהנים כל המנחות לפי מה שנתבארו דיניהם כמו שתי הלחם של עצרת ולחם הפנים ומנחת חוטא ומנחת נדבה:
@662 **וכל חטאתם.** זהו הקרב לכהנים מחטאת יחיד או חטאת צבור היה שיהיו עוף ולא בהמה:
@662 **ולכל אשמם.** זה הקרב לכהנים מכל אשם היה שיהיה אשם גזלות או אשם מעילה או אשם ודאי או אשם תלוי ואשם נזיר ואשם מצורע ונכלל עמו לוג שמן של מצורע שכבר היה בא עם האשם אחר שלקח המזבח חלקו מכל אחד מאלו:
@662 **קדש קדשים לך הוא ולבניך.** זה שב לכל אלו הדברים שכל אחד מהם הוא קדש קדשים לפי מה שהתבאר במקומו והם לאהרן ולבניו הנזכרים לבד או לבנותיו:
@663 **בקדש הקדשים תאכלנו.** אחשוב שיהיה הרצון בזה שיאכל אותו במדרגת קדש הקדשים שהוא נאכל במקום קדוש וזה שכבר נתבאר בספר ויקרא שאלו נאכלים במקום קדוש והנה קצת רבותינו ביארו מזה שאם לא יוכלו הכהנים לאכלו בקדש כגון שהקיפו גוים את כל העזרה הנה יותר להם לאכלו בהיכל שהוא קדש הקדשים והנה יהיה הרצון נאמרו בקדש הקדשים תאכלנו שם תוכל לאכלו לא למנוע ממנו אכילתו בקדש כי כבר נתבאר בספר ויקרא כי הוא נאכל בקדש:
@663 **קדש יהיה לך.** מגיד שאם לא יאכלנו ראוי שינהג בו קדושה ר"ל גם במה שאינו נאכל ממנו:
@664 **וזה לך תרומת מתנם וגו'.** כלל בזה חזה ושוק של שלמים ותודה והוא מה שאמר לכל תנופות בני ישראל כי היה בו תרומה ותנופה נכלל בזה גם כן המורם מאיל נזיר' כי הוא נקרא תרומה וזכר שזה נאכל לכל טהור בית הכהן היה זכר או נקבה לא לבלתי טהור ואח"כ זכר התורה במה שאמר כל חלב יצהר וכל חלב תירוש ודגן וגומ'. לפי שהתרומה אינה נוהגת אלא בדבר שנגמרה מלאכתו כגון דגן תירוש ויצהר ובזה נכללה תרומה מעשר וזאת התרומה נקראת ראשית כמו שאמר דגנך תירושך ויצהריך ראשיתם אשר תתנו לה' כלל בה עם אלו הדברים הנזכרים חלה כי היא נקראת ראשית ותנתן לכבוד השם ואפשר לאומר שיאמר שכבר נכללו בזה גם כן ראשית הגז כי היא נקראת ראשית בפרשת שופטים והזרוע והלחיים והקבה כי הן כמו ראשיות לדברים שלוקחו מהן כמו שנבאר בג"ה בפרשת שופטים ולזה נזכרו שם שאר הדברים המתוארי' בשהם ראשיו' כמו ראשית דגן תירוש ויצהר וראשית הגז וכבר אמרו ז"ל בספרי אמנם יתבאר שהו' לא דבר בכאן מראשית גז כי אמר בסוף כל טהור בביתך יאכלנו ואין ראשית הגז נאכל ולזה יהיה אמרו ראשיתם אשר תתנו להשם שם אל חלב יצהר ולא חלב תירוש ודגן ר"ל התרומה ולזה לא יכלל בזה הזרוע והלחיים והקבה לפי הפשט וכלל החלה בזה כי הוא מחלב דגן והוא גם כן ראשית בכורי כל אשר בארצם למדנו מזה שהבכורי' הם מתנה לכהנים והוא מבואר שהקדושה חלה בבכורים אם קרא להם שם אף על פי שלא נגמרה מלאכתם כי לא נאמר בהם דגן תירוש ויצהר כמו העניין בתרומה ולא עוד אלא אפילו קרא להם שם במחובר לקרקע קדושה חלה עליהם וזה מבואר ממה שהישרנו אליו ורז"ל למדו זה מזה הפסוק רוצה לומר שאף על פי שהוא בארצם נקרא בכורים וראוי שלא יעלם ממנו כי הכונה בזאת המצוה לתת בכורים מהפירות ששבח בהם ארץ ישראל במה שספרה התורה ארץ חטה ושעורה וגפן ותאנה ורמון ארץ זית שמן ודבש והוא דבש תמרים כי דבש הדבורים אינו מיוחס לארץ אך הדבורים יחדשוהו ולזה רמז באמרו כל אשר בארצם ר"ל כי מהפירות המיוחדים לארצם על צד השבח יביאו בכורים לא מזולתם וזה יתבאר יותר ממה שנזכר מזה בפרשת והיה כי תבא שהיה אומר מביא בכורים כמו שנבאר שם בג"ה:
@666 **כל טהור בביתך יאכלנו.** מגיד שאין התרומ' והחלה והבכורי' נאכלים בטומאה ולא הוצרך להזכיר זה בקדש הקדשים כי הדברים ק"ו וראוי שיספק מספק איך כפלה התורה זה התנאי לזכור אותם במורם מקדשים קלים ואחר זה שבה לזכרו בתרומה וחלה ובכורים וכבר יספיק שתזכור אותו פעם אחת לבד לכל אלו הדברים אחר שאין הבדל ביניהם בזה התנאי ונאמ' כי אנחנו לא נסכים שלא יהיה הבדל בין טהור הנזכר בחלה ותרומה ובכורים ובין טהור הנזכר במורם מקדשי' קלים אבל הוא מבוא מההדרגה אשר זכרה בה התורה ענין אלו קדשים בגדול החלה ובקטן כלה שהענין כתנאי אכילתם הוא גם כן בזאת ההדרגה ולזה החמירה יותר באכילת קדשי הקדשים שלא יאכלו מהם כי אם הזכרים ובקדש ולא הוצרך להזכיר שלא יאכלוהו בטומאה כי בקדש אי אפשר שיכנסו טמאים שם עם שהדברים ק"ו כמו שזכרנו ואח"כ התנה במורם מקדשים קלים שלא יאכל מהם כי אם טהור היה זכר או נקבה וכן התנית באכילת תרומה חלה ובכורים ולזה הוא מבואר שהטהרה הנזכרת באכילת המורם מהקדשי' היא למעלה מהטהר' הנזכרת באכילת תרומ' וחלה ובכורי' ולפי שמצאנו בתורה ב' מינים מהטהרה האחרת ידענו שהטהרה היותר שלמה היא אשר תצטרך לאכילת המורם מהקדשים ושלמטה ממנו תצטרך לאכילת תרומה וחלה ובכורי' והנה הטהרה היותר שפלה שנזכרה לאכילת הקדשים היא הערב השמש באמרו ובא השמש וטהר ואחר יאכל מן הקדשים והיא תהיה לאכילת תרומה וחלה ובכורים ולזה גם כן אמר כי לחמו הוא והטהרה היותר שלמה ההיא אחר הערב שמש בהבאת הכפרה כמו שמצאנו ביולדת שגם אחר שטבלה והעריבה שמשה הוזהרה מנגיעת קדשים עד מלאת ימי טהרה ולא תצא מזאת הטמאה לאלו הקדשים עד שתביא כפרתה כאמרו וכפר עליה הכהן וטהרה ולזה הוא מבואר שזאת הטהרה תצטרך לאכילת המורם מהקדשים קלים ובכאן הותר זה הספק:
@668 **כל פטר רחם.** ר"ל הראשון שפתח הרחם בלידתו והוא הבכור ולמדנו מזה שאם היה הראשון יוצא דופן הנה הבא אחריו דרך הרחם הוא הבכור לזה העניין לכל בשר אשר יקריבו להשם הוא בכור שור וכבש ועז כי בהם לבד נוגע זה העניין ר"ל עניין הבכורה וענין ההקרבה כי מזולתם מהבהמות לא יקריבו כמו שהתבאר בראש ספר ויקרא:
@668 **באדם ובבהמה לך יהיה.** ר"ל כל פשר רחם באדם ובבהמה והרצון בבהמה בהמה טמאה והוא החמור לבדו כמו שהתבאר בפרשת בא אל פרעה ולזה לא הקפידה התורה לבאר זה בזה המקום:
@668 **אך פדה תפדה את בכור וגו'.** ביאר שאין קדושת אלו כקדושת בהמה אשר יקריבו ממנה קרבן לה' היא קדושה קדושת הגוף ואלו קדושים קדושת דמים וזה כי בכור האדם יפדה ה' שקלים כמו שנתבאר במה שקדם והנה השקל הוא כ' גרה והוא מעה משקל היה אז מפורסם וזה המשקל היה נותן בפדיונו בכסף צרוף כי לא יקרא כסף על האמת מה שהיה בו ערוב מתכת אחר ובכור הבהמה הטמאה היה נפדה בשה כאמרו ופטר חמור תפדה בשה והנה הקלה התרה בזכירת מה שיפדה בו כי סמכה על מה שזכרה מזה במה שדם עם שלא יהיה הדבר הכרחי שיגיע הפדיון לכהן כמו העניין בשאר המתנות שזכר וזה שכבר אפשר שלא יפדוהו הבעלים ולא יהיה בזה תועלת לכהן אבל יערוף פטר חמור אם ירצה ולא יפדהו כמו שאמר ואם לא תפדה וערפתו ולזה לא הקפידה התורה מאד בזכירת הדבר שיפדה בזה המקום שזכר בו מתנות כהונה. והנה התנית התורה בבכור אדם שיפדה אחר היותו בן חדש לפי שהבכור ראוי שיתבאר מעניינו שיהיה שלם ההויה כרחם כי היוצא מהרחם לפי הנהוג ובאופן השלם לא יהיה כי אם בזה האופן ולזה יהיה הנפל פטור מהבכורה כי לא נשלמה חויתו ואי אפשר בו גם כן שיהיה והנה לא נתבאר מהולד שלא יהיה נפל אם לא אחר היותו בן חדש כי כבר נתאמ' בנסיון כי לא יחיה הנפל ל' יום ועוד יתבאר זה מהדבר שעליו באה זאת המצוה והיא מכת בכורות והמתתם וזה לא יתכן שיאמר בנפל כי הוא כמו מת ולא יתכן לומר שהמית השם ית' המת ומזה בעינו יתבאר שלא ינהג דין בכורה בבהמה טמאה בנפל כי בכלם נאמר פטר רחם כמו שביארנו והנה למדו רבותינו ז"ל מזה המקום שהבעלים מטפלין בבכור בהמה טמאה שלשים יום אמ' שמקיש אדם לבהמה במה שאמר באדם ובבהמה מה בכור אדם מטפל בו שלשים יום אף בכור בהמה מטפל שלשים יום ולמדו מזה גם כן שהלוים פטורים מבכור בהמה שנאמר באדם ובבהמה את שיש לך בו באדם יש לך בו בבהמה יצאו הלוים שאין להם באדם לא יהיה להם בבהמה וזה מבואר בזולת ביאור מהמקו' שלמדנו ממנו שהלוים פטורים מבכור אדם לפי שהן פטרו את בכורות ישראל כמו שנזכר בפרשת במדבר סיני כ"ש שיהיו פטורי' בכוריהן ובזה יתבאר שבהמות שלהן פטורות מן הבכורה כי הם פטרו בכורות בהמתם של ישראל כ"ש שיפטרו בכורות בהמותיהם בעצמם:
@670 **אך בכור שור או בכור כשב או עז לא תפדה קדש הם.** זהו להזהיר שלא יפדה בכור בהמה טהורה ומגיד שאם פדאו אינו פדוי לפי שהוא קדש וקדוש קדושת הגוף וכן מצאנו במעשר בהמה בסוף פרשת אם בחקותי והחמיר שם יותר והוא שאם ימירנו והיה הוא ותמורתו קודש והנה היה לו לומר קודש הוא אך הוא אמר קדש הם לפי מה שזכרו רז"ל להעיר שה הדין ינהג בכל מה שקדוש קדושת הגוף כמו הפסח והמעשר וכן מה שאמר את דמם תזרוק על המזבח ואת חלבם תקטיר ויקשה לפי הפשט לפי זה הביאור ממה שאמר אחר זה ובשרם יהיה לך כחזה התנופה וכשוק הימין כי זה בלתי אפשר שישוב כי אם לבכור ולזה נאמר אנחנו כי אמרו קדש הם שב לאלו השלשה מינים מבכור רוצה לומר בכור שור וכבש ועז:
@670 **ואת דמם זרוק על המזבח.** לפי שלא אמר על קרנות למדנו שאין טעון אלא זריקה אחת וזה דבר לא ימנע ממנו אחד מהקרבנות כמו שאמר בפרשת ראה אנכי ודם זבחיך ישפך על מזבח השם אלהיך וגומ' וכבר אמר תחלה רק קדשיך אשר יהיו לך וגו'. וזה יכלול בלי ספק הפסח והמעשר. רוצה לומר מעשר בהמה ועליהם גם כן יתכן יותר שיאמר והבשר תאכל כי הבשר כלו הוא לבעלים ולזה למדנו מזה שהפסח והמעשר טעונין שפיכה אחת. ולזה גם כן דקדקה התור בפרשת ראה בזביחת הפסח שתהיה במקום אשר יבחר יי' כדי שיהיה הדם למזבח וכבר נלמד מזה המקום שפסח והמעשר הם גם כן טעונין הקטר חלבי' כמו העניין בבכור כי לזאת הבה היו קדש לש' מצד החלק שאוכל מהם המזבח והדברים גם כן קל וחומר אם הכהנים שזכו בבכור והוא ממונם הוכרחו מפני היות וקדש שיהיה המזבח אוכל חלק ממנו כ"ש בקדשי ישראל שיחוייב להם שיהיה המזבח אוכל ממנו אם לא יהיה בכאן צד יהיה בו קדש והמשל כי הלחמים היו קדש כי חלק מהם נאכל למזבח וחלק אחר נאכל לכהנים אבל הפסח והמעשר למה זה יהיו קדש כי הם כלם לבעלים ולא יהיה מהם חלק למזבח ולא לכהנים ואם אמ' אומר שמעשר שני נקרא קדש אף על פי שאין בו חלק לשם יתע' ולא לכהנים אמרנו שההבדל מבואר בין קדושת מעשר בהמה ובין קדושת מעשר שני כי מעש' שי יש רשות לבעלים לגאול אותו ואין העניין כן במעשר בהמה כי היא בעצמה קדש כמו שהתבאר בסוף פרשת אם בחקותי ולזה אי אפשר במעשר בהמה שיגאל כי בו חלק לגבוה וכבר נלמד זה גם כן ממה שאמר בפרש ראה אנכי שכלל בו אלו הקדשים כמו שזכרנו כי תמצא ששתק שם מזכירת החלב בעולה ואמר ועשית עולותיך הבשר והדם על מזבח ה' אלהיך והנה היה החלב גם כן קרב למזבח ואחר כך אמר ודם זבחיך ישפך על מזבח יי' אלהיך והבשר תאכל למדנו שאין הבעלים זוכין אלא בבשר ונשען כשלא זכר החלב להשענו שזה ידוע שחלבי הזבחים הם כלם למזבח ולזה לא מצא ההבדל בין העולה והזבחים כי אם בבשר שבשר העולה הוא למזבח ובשר הזבחים הוא לבעלים:
@671 **ובשרם יהיה לך כחזה התנופה וגומר.** למדנו מזה שהבכור נאכל לב' ימים ולילה אחד כמו העניין בחזה ושוק של שלים ואין לאומר שיאמר שיהיה רצון התורה בזה בחזה ושוק של תודה שאינם נאכלים כי אם ליום ולילה אחד וזה כי מצאנו בשפיכת הדם שהשלמים הם למעלה מהבכור כי הם טעונין שתי מתנות שהם ארבע והבכור אינו טעון כי אם מתנה אחת ולזה ראוי שנתפש בזמנו זמן השלמים לא זמן התודה ולזאת הסבה גם כן יתבאר שזמן אכילת מעשר בהמה הוא ב' ימים ולילה אחד כשלמים כי הוא זמן הנתן לאכילת היותר קל שבקדשי':
@672 **כל תרומות הקדשי' אשר ירימו בני ישראל לה' לך נתתים ולבניך ולבנותיך אתך לחוק עולם.** ר"ל שהמורם משלמים ותודה ואיל נזיר אחר שזכה המזבח בחלקו כי אלו נאכלם לזכרים ולנקבות ושב להזכיר בזה המקום זה הענין דרך כלל:
@672 **ברית מלח עולם הוא לפני ה'.** הנה המלח ייוחד שאינו נסד גם שומר מההפסד הדברים שיומלחו בו ולזה אמר להורות על הקיום לזה הברית שהוא ברית מלח ולזה סמך לו לעולם להורות על המצחיות ואמר לפני יי' להעיר שזה הברית יתקיים מה שיתמיד הש' יתעלה להיות קיים כטעם לו ישמעאל יהיה לפניך לפי מה שביארנו שם וככה כונת יהי שמו לעולם לפני שמש ולפני ירח דור דורים:
@673 **בארצם לא תנחל וגו'.** זה אמנם היה מיושר התורה כי די להם באלו המתנות למה שיצטרך להם למחיתם וכן הענין בלויים רוצה לומר שדי להם במעשר שנותנים להם ישראל מכל תבואותיהם למחיתם והיתה כונת התורה בזה שלא יהיו אלו טרודי' במזונותיהם ויהיה להם פנאי לעסוק בתור ולהזכיר את בוראם ואמנם היו להם ערים לשבת כי בזולת זה אי אפשר להן ועם שבענין נתינת המעשר הערה להשיג השם יתעלה והנה היה בענינו מהיושר בנתינת זה השעור ישראל ללוים כי הוא חלק קרוב למה שהיה ראוי להם מנחלת הארץ לפי מספר השבטים ומזה יתבאר שחובה לישראל לתת המעשר מפירותיהם ללוים שלא תאמר שאי זה מישראל שיפריש מעשר הוא ללוי' ואם רצה יפריש ואם לא יפריש כאמרו כל חרם בישראל לך יהיה שאם רצה מחרים ואם לא רצה אינו מחרים וזה שאם היה הדבר כן אולי לא יהיה שם מי שיפריש מעש' ויעדר מזו הלוי' ולא יהיה זה גמולם הראוי להם על עבודת' ה' ית':
@674 **ולבני לוי הנה נתתי את כל מעשר בישראל לנחלה חלף עבודתם.** מגיד שאם עבד יטול ואם לא עבד לא יטול מכאן אמר בן לוי שקבל עליו עבודת הלוים חוץ מדבר אחד שאין לו חלק בלויה וכבר התבארו אופני עבודת הלוים במה שקדם:
@675 **ולא יקרבו עוד בני ישראל אל אהל מועד.** ר"ל לעבוד עבודה וזו היא אזהרה שלא יקרב זר:
@675 **לשאת חטא למות.** מגיד שזר שעבד חייב מיתה בידי שמים ובזה יהיו ישראל נצולים ממה שפחדו ממנו באמרם כל הקרב הקרב אל משכן השם יומת וגו'. וזה כי כבר בחר השם ית' באהרן ובזרעו בזאת העבודה ובלויי' בעבודה המיוחדת להם:
@676 **ועבד הלוי הוא עבודת אהל מועד.** זו היא מצות עשה שיעבדו הלוים העבודה המיוחדת להם:
@676 **והם ישאו את עונם.** ר"ל במה שיחטאו בזאת העבודה וישראל יהיו נקיים מזה החטא:
@676 **ובתוך בני ישראל לא ינחלו נחלה.** רוצה לומר שלא יהיה להם חלק בארץ לפי שיש להן מעשר פירות בכל תבואות שאר השבטים כמו שזכר בפסוק אחר זה:
@677 **אשר ירימו ליי' תרומה.** ר"ל עשר פירות אשר הרימו מהם תרומה גדולה:
@677 **נתתי ללוי' לנחלה.** לפי שזאת הנחלה היא תמורת חלק נחלתם בארץ ונחלת הארץ נוהגת בין בפני הבית בין שלא בפני הבית כן לקיחת הלוי' מעשר ראשון מישראל מפירות הארץ נוהגת בין בפני הבית בין שלא בפני הבית וזה מבואר חיובו:
@679 **והרמותם ממנו תרומת יי'.** הנה יתבאר ממה שאמר ממנו שלא יתרום ממין על שאינו מינו ולפי שבמעשר ראשון דקדקה התורה שלא יעשרו מן החדש על הישן ולא מן הישן על החדש שנאמר עשר תעשר את כל תבואת זרעך היוצא השדה שנה שהוא מבואר שיותר ראוי לדקדק בזה בתרומות מעשר זה גם כן יתבאר מאמרו ממנו ויתבאר גם כן שהמעשר אינו נוהג אלא בפירות הארץ ממה שאמר בסוף פרשת אם בחקותי וכל מעשר הארץ מזרע הארץ ולזה גם כן יתבאר מאמרו ממנו שאין מעשרין מפירות חוצה לארץ על פירות ארץ. והנה קרא אותם תרומת ה' להורות שהוא קדש:
@680 **ונחשב לכם תרומתכם כדגן הגרן וכמלאה מן היקב.** ר"ל שהם דברים שנגמרה מלאכתן אבל לא יתרומו שבלים על החטים וזתים על שמן כמו הענין בתרומה שמפרישין ישר' לתת לכהנים כי הוא בדבר שנגמרה מלאכתו ולפי שכבר צוה אותם בזה המאמר להפריש תרומת מעשר אחר שנגמרה מלאכתו והיה לחושב שיחשוב שאם לקח הלוי מישראל מעשר ראשון קודם שנגמרה מלאכתו שלא נתן עדיין הישראל תרומה גדולה לכהן שכבר יפטר הלוי כשיתן לכהן תרומה מעשר לבד ויפטר מתרומה גדולה אמר כן תרימו גם אתם תרומת יי' וגומ' ר"ל שלא תחשבו שאינכם מחוייבים בתרומה גדולה לפי שאתם לויים ולא חייבה אתכם התור כי כן בודאי גם כן מחוייבים להפרישה אחר שלא הופרשה ביד הישראל וגמר מלאכת הפירות ההם בידיכם ותתנו התרומה לאהרן הכהן ולפי שהתרומות הם בכללם לאהרן ולבניו כמו שנתבאר במה שקדם הנה אין ראוי שנבין מזה המקום שלא יתנו הלוים ואת התרומה כי אם לכהן גדול אבל נבין מזה המקום שהוא קודם לבניו כמו שבארנו במה שקדם וכבר למדו' רבותי' ז"ל מזה שאין ראוי לתת' כי אם לכהן חבר כמו הענין באהרן לא לכהן עם הארץ וזה באמת דבר ראוי לכל המתנות כאמרו לתת מנה לכהנים למען יחזקו בתורת ה' ויתבאר מזה שהמחזיקים בתורת השם הם אשר יש להם כמו שארז"ל:
@682 **מכל מתנותיכם תרימו תרומה וגו'.** אחר שביאר שאם הקדים הלוי לקחת המעשר קודם שנגמרה מלאכת הפירות ההם שהוא חייב לתת לכהן תרומה גדולה מלבד תרומת מעשר ביאר שם שאם היה שיתנו להם ישראל מפירותיהם קודם שנגמרה מלאכתם מלבד המעשר הנה גם מהמתנות ההם יחוייב ללוים לתת כל תרומת ה' הראויה להם אחר שנגמר מלאכתם כי אין הנתנ' ללוים פוטר הפירות ההם מתרומה גדולה והנה הוצרך לבאר זה כי אולי יחשוב חושב כי מה שנתחייבו בו בתרומת מעשר יתחייבו גם כן בתרומה גדולה אחר שהערים הלוי והקדים לקחת המעשר בשבולים אבל מה שנתן ללוים שאינו מעשר יפטר מתרומה גדולה כי התורה לא צותה זה כי אם לישראל ולזה באר שגם בזה חייב הלוי לתת תרומה גדולה זהו הביאור שנראה לנו בזה והו' נאות מאד לפי מה שנחשוב להמלט שלא יהיה בזאת הפרשה כפל דברים ללא תועלת:
@682 **מכל חלבו את מקדשו.** הנה קרא חלבו הפרי שנגמרה מלאכתו שהוא נקי מהפסולת והוא מקדשו הקדש שיש בו שאוסרו ומקדש אותו והכונה בזה מבוארת ממה שקדם. ואמרת אליהם בהרימכם את חלבו וגו'. זה שב אל המעשר ראשון שזכר תחלה וזהו אמרו אחר זה כי שכר הוא לכם חלף עובדתכם והרצון בזה שכאש' תרימו ממנו מעשר שנגמר' מלאכתו אז יחשב הנשאר ללוים כתבואת גורן וכתבואת יקב לישראל שאין בו שום קדוש' אך קודם זה לא יותר להם לאכל ממנו כי הוא בלתי מתוקן ומקדשו הוא בתוכו וזהו אמרו ואכלתם אותו בכל מקום ר"ל אפילו חוץ לירושלם ואפילו במקום טמא כי אין בו שום קדושה:
@685 **ולא תשאו עליו חטא וגו'.** מזה התבאר שאם לא ירימו ממנו תרומת מעשר ישאו עליו חטא באכלם אותו בטבלו ויהיו חייבים מיתה בידי שמים כי הם מחללים קדשי בני ישראל בנהגם בהם מנהג חולין ולזה הוא מבואר שאף על פי שנטמא המעשר הם חייבים להפריש ממנו תרומת מעשר כדי שלא ישאו עליו חטא. ובכאן נשלם הביאור בזאת הפרשה.
@687 **דבר אל בני ישראל ויקחו אליך פרה אדומה תמימה.** למד מזה שמשל צבור היתה באה והנה הרצון באמרו אדומה תמימה הוא שתהיה תמימה ושלמה באודם ומפני זה למדנו שאם היה בה שער לבן או שחור שהיא פסולה וכבר התבאר מהשרשים הכוללים שלא יפסול בה פחות משתי שערות כי החלק הראשון בשער הוא שתי שערות ואי אפשר שנא' שיהיה הרצון באמרו תמימה שלא יהיה בה מום שהרי אמר אחר זה אשר אין בה מום ויהיה אם כן אמרו תמימה לבטלה ולזה הוא מבואר שאמרו תמימה שב אל האדמימות והנה נתבאר מצד הוראת הגדר כי פרה תקרא כשהיא בת ג' שנים וראוי שתהיה פרה כשיקנו אותה שנאמר ויקח אליך פרה:
@687 **אשר לא עלה עליה עול.** ביאר בזה שאף על פי שלא משכה בעול כיון שעלה עול עליה נפסלה מה שאין כן בעגלה ערופה שנאמר בה אשר לא עבד בה ולא משכה בעל ולזה היתה פרה אדומה בזה יותר חמור' מעגלה ערופה וראוי שתדע שהמלאכה פוסלת בה גם כן כמו הענין בעגלה ערופה אך שתקה התורה מזה כי כבר הגידה שאף על פי שעלה עליה עול בזולת שמשכה בו היא נפסלת כ"ש אם נעשה בה מלאכה ועוד שהמום פוסל בה שאין כן בעגלה ערופה ולזה ראוי שינהג בה כי אם מה שהוא להנאת הבעלים כמו העניין במשיכת העול ויתר העבודות אשר יעשו בו דומות לזה שהם שלא לצרכה וברצון הבעלים אבל מה שהוא לצרכה לבד כשרה ולזה אם עלה עליה זכר פסולה שתכלית זה הפועל הוא שלא לצרכה והיא היותה מתעברת:
@688 **ונתתם אותה אל אלעזר הכהן.** לפי שלא היה אלעזר כהן גדול כי כבר היה אהרן קיים למדנו מזה שהפרה נעשית בין בכהן גדול בין בכהן הדיוט ולזה אמר אחר זה ולקח הכהן וכבס בגדיו ולא אמר אהרן להורות כי לא הקפידה התורה אלא שיהיה כהן או דקדקה שיהיה כהן גדול וסגל אך לפי שעה נעשית זאת ע"י אלעזר והנה הקדים לומר ונתתם אותה אל אלעזר הכהן להורות שכל מעשיה בכהן:
@688 **והוציא אותה אל מחוץ למחנה.** למדנו מזה שאין מוציאין אותה וחבירת' יחד מכאן אמרו ז"ל לא היה פרה רוצה לצאת אין מוציאין עמה שחורה שמא יאמרו שחורה שחטו ולא אדומה שמא יאמרו אדומה שחטו ובכלל הנה כמו שהעבודה פוסלת בה כדי שיביא זה לחשוב שלא נבראת זאת הפרה כי אם לזה התכלית כן דקדקה התורה בהוצאתה ובשחיטתה ובשריפתה שלא תהיה בהם כוונה אחרת ולזה אמרה התורה והוציא אותה ושחט אותה ושרף את הפרה שכל מעשיה צריך שיהיו מכוונים לזה לבד וגם במי הנדה דקדקה שלא תהיה נעשית בהם מלאכה שנאמר מים חיים אל כלי וזה ממה שיגלה ממנו שהמלאכה פוסלת בפרה ובכל מעשיה והנה היה מוציא אותה במקום שריפת פרים הנשרפים:
@688 **ושחט אותה לפניו.** מגיד שאין שוחטין שנים יחד וסבת זה כי הוא יהיה מתעסק במלאכה אחרת עמה ולמדנו מזה שצריך שישחט אותה לשמח כדי שתהיה מחשבתו בה כי אז יתכן שיאמר בו שהוא שוחט אותה ולמדנו מאמרו ושחט אותה לפניו שיהיה השוחט שוחט אותה לפני אלעזר אשר לו נתנה הפרה כדי שיהיה אלעזר רואה כשהאחר שוחט והטעם בזה ישתן אל לבו לכוין דעתו בעניין הפרה שהוא עמוק ונפלא מאד ולפי שאמר ושחט הוא מבואר שאם נתנבלה בידו היא פסולה שהרי אינה שחוטה:
@689 **ולקח אלעזר הכהן מדמה באצבעו.** למדנו מזה שצריך שיהי' בכהונו ר"ל שילבש בגדי כהונה והם בגדי לבן כי הוא היה כהן הדיוט ואולם מפני זה דקדק בזה המקום שתהיה נעשית ע"י אלעזר להעיר שאפילו כהן גדול אם יעשה אותה יעשנה בבגדי לבן לא בבגדי זהב וזה יתבאר עוד משלשה צדדין האחד שלא מצאנו שישמש כהן גדול בבגדי לבן רק כשהיה משמש לפני לפנים ביום הכפורים והיה זה כן כדי שיכון לבו יותר בעבודתו כי מה שהיה כתוב על החושן ועל האפוד היה מביא אותו להרהר תמיד וגם קול הפעמונים אשר על שולי המעיל כי זה כלו היה כלי לכוין בענייני ישראל תמיד כדי שימצא עצמו מוכן להשיב כראוי כשישאלוהו באורים ותומים ולפי שבעניין הפרה צריך שתהיה כונתו בה לא בדברים אחרים הוא ראוי שאם יעשה אותה כהן גדול שיעשה אותה בבגדי לבן והצד השני הוא שכבר הראתה בתורה כוונתה להסיר היופי מעניין הפרה ולזה היו כל מעשיה בחוץ והיתה נשרפת עורה ובשרה ואת דמה על פרשה ובהיות העניין כן הוא מבאר שאין ראוי שיעשנה כהן גדול בבגדי זהב כדי שלא ינהג בכבוד וביופי במה שכוונה בו התורה להסיר הכבוד והיופי והצד השלישי הוא כי כמו שעבודת יום הכיפורים שהיתה הכוונה בה הטהרה והכפרה היתה בבגדי לבן כן ראוי בעניין הפרה שהיא מכונת לטהרת טומאה חמור' שתהיה בבגדי לבן:
@689 **מדמה באצבעו.** ראוי שנבין מזה שיקח מדם הפרה בעצמה באצבעו הימנית שאם קבל אותו בכלי ואחר טבל שם אצבעו אינו מדמה אבל יחובר לו שם אחר ר"ל שהוא מדם הכלי אלא שאם התנינו שיקח מדמה באצבעו שבע פעמים מעצם הפרח בעצמה הנה אפשר שיצא כל דם הפרה קודם שישלים הזאותיו ולזה נלמד זה הענין לוג שמן של מצורע שהטהרה ההיא מתיחסת לזאת הטהרה ונתבאר שם שהוא היה לוקח השמן על כפו השמאלית וכה היה טובל אצבעו הימנית ומזה שבע פעמים וכן ראוי שנאמין שהיה העניין בזה המקום שהכהן מקבל מדם הפרה בכפו השמאלית וטובל בה אצבעו הימנית ומזה:
@689 **והזה אל נכח פני אהל מועד.** ראוי מזה שנבין שצריך שיכון להזות אל נכח פני אהל מועד ושיראה פני אהל מועד כדי שיתבאר לו מזה שהוא מזה נוכח פני אהל מועד:
@689 **מדמה שבע פעמים.** למדנו מזה שצריך שיקח באצבעו מדמה שבע פעמים בכל הזאה טבילה וזה צריך לו שיקנח אצבעו בעור הפרה אח' כל הזאה והזאה כדי שלא יזה כי אם ממה שלוקח עתה מהדם באצבע ולפי שצריך לשרוף כל דמה לבד המוזה ממנו שנ' ואת דמה על פרשה ישרוף למדנו מזה שצריך לקנח אצבעו בפרה בעצמה כדי שישרוף דם הקנוח עמה ואחר זה יקנח גם כן כפו השמאלית בפרה בעצמה ולזאת הסבה בעינה:
@690 **ושרף אל הפרה לעיניו.** אחר שהצית הכהן את האור בעצי המערכ' דקדקה התורה שיהיה עיניו בשריפת הפרה כדי שלא יתעסק במלאכה האחרת כי המלאכה פוסלת בה כמו שביארנו והוא מבואר מזה הלשון שראוי שישרוף הפרה לא אותה וחבירתה כדי שלא יתעסק במלאכה אחרת וראוי שישרוף אותה כלה במקום אחד לא בשתי מערכות וזה לשתי סבות האחת שאינו שורף את הפרה באש שהצית שם אבל קצתה לבד והשנית שאי אפשר שיהיו עיניו יחד בשתי המערכות והנה לא דקדקה התורה בעצים אשר תשרף הפרה בהם אפילו בקש או בגבבה או בעצים שירצה:
@690 **את עורה ואת בשרה ואת דמה על פרשה ישרוף.** לפי שדקדקה התורה בשערה שיהיה אדום והוא מחובר לעורה למדנו שכונת התורה שישרף יחד עם עורה והנה בבשרה נכלל החלב והקרב. ולפי שכבר אמר תחלה ושרף את הפרה ובשם הפרח נכלל כל הנלוה לה כמו הקרנים והטלפים למדנו שראוי שישרוף הכל יחד אלא שאם פקע מעורה או מהשער הנלוה לו כזית או מבשרה או מדמה חייב להחזיר כי התורה דקדקה שישרפו אלו בכלל ואולם אם פקע מהקרנים והטלפים אינו חייב להחזיר כי לא זכרה אותם התורה בפרטים שזכרה והנה אמרו על פרשה ישרוף. ר"ל אצל פרשה כדי שישרף פרשה עמה והנה נכלל בזה גם הפרש שפירש ממנה על מערכתה כמו העניין בדמה שכולל גם הדם שפירש ממנה על מערכתה בעת שחיטתה והנה הפרש הזה הוא במקום המערכה בהכרח ולזה יחוייב שתהיה שריפת עורה ובשרה ודמה במקום מערכתה ואם פקע מהם חוץ למערכת צריך לשרפו במקומו:
@691 **ולקח הכהן עץ ארז ואזוב ושני תולעת.** שני תולעת הוא צמר צבוע בתולעת הוא שקורין גרא"נה בלעז. וכבר בארנו עניין אלו המינים בפרשת מצורע:
@691 **והשליך אל תוך שריפת הפרה.** לפי שהוא אומר שריפת הפרה למדנו שלא סר שם הפרה ממנה מכל וכל רוצה לומר שלא נשלמה שריפתה ולזה יחוייב שיצית האש ברובה ואחר כן ישליך אל תוך שריפתה ולזה יחוייב שיצית האש ברובה ואחר כן ישליך אל תוך שריפתה אלו השלשה מינים כדי שישרפו יחד עמה:
@692 **וכבס בגדיו הכהן ורחוץ בשרו במים וגומ'.** למדנו מזה שהמשליך עץ הארז והאזוב ושני התולעת אל תוך שריפת הפרה טעון כבוס בגדים ואחר זה שב לבאר שהשורף את הפרה טעון גם כן כבוס בגדים והאוסף את אפר הפרה גם כן טעון כבוס בגדים והנושא את מי הנדה גם כן וזה ממה שיורה שכל העוסקים בפרה טעונין כבוס בגדים עם שהוא אפשר שיהיה אמרו וכבס בגדיו הכהן שב אל המוציא אותה והשוחט אותה והמזה מדמה ויהיה אמרו והשורף אותה שב אל השורף הפרה והמשליך אל תוך שרפתה אלו השלשה מיני' שזכר וזה דבר אפשר שיתבאר גם כן משעיר המשתלח שמטמא המשלח אותו אף על פי שהוא חי כי אלו הטמאות הם מתיחסות וידמה היותם לכונה אחת:
@694 **ואסף איש טהור את אפר הפרה.** הנה קרא הכתוב כל הנשרף עמה אפר הפרה כי הם דברים נטפלים לה ולזה הוא מבואר שאחר שנשרפה הפרה אין ראוי להוסיף בעצים כלל כי אפרם לא יהיה אפר הפרה והנה לא הקפיד הכתוב באסיפת האפר שתהיה בכהן אבל הקפיד שיהיה טהור ושיהיה גדול ושיהיה בן דעת להניח האפר מחוץ למחנה במקום טהור שנ' והניח מחוץ למחנה במקום טהור ולזה זכר איש להוציא את הקטן לא להוציא את האשה אחר שיש לה דעת להניח אולפי שאסיפת אפר הפרה שהקלה בו התורה להעשות שלא על ידי כהן הקפידה בו שיהיה טהור הנה נלמד מזה שכל העסוקים בפרה ראוי שיהיו טהורים ולפי שהטהור הוא נאמר בפנים שונות בתורה וזה כי ממנו שהוא טהור לקדשים וממנו טהור לתרומה לא לקדשים וממנו טהור למעשר שני ולא לתרומה ולא לקדשים הנה יתבאר שראוי שנבין מלת טהור הפחות שיפול עליו שם טהור. ר"ל שכיון שהו' טהור למעשר דין בו באסיפת אפר הפרה וזה כי כמו שנקח במלת איש הפחות שיפול עליו שם איש בתורה והוא הישראלי ולא נדקדק בו שיהיה כהן ואף על פי שנקרא כהן איש בתורה כאומרו איש מזרעך לדורותם אשר יהיה בו מום כן לקח במלת טהור הפחות שיפול עליו שם טהור ולזה הסכימו רז"ל שכל מעשה פרה אפשר היותם בטבול יום וכ"ש אם היו טהורים לתרומה לא לקדשים ולפי שהקלה התורה בזה הפעל להעשות שלא על ידי כהן הנה אינו כמו עבודה ולזה יהיה נעשה אפילו בלילה:
@694 **והניח מחוץ למחנה במקום טהור.** רוצה לומר שלא יהיה המקום ההוא טמא ולזה יתבאר שאם היה האפר תוך כלי חרש מוקף צמיד פתיל באהל המת הרי הוא טמא שהרי אינו במקום טהור והתורה דקדקה על מקומו שיהיה טהור:
@694 **והיתה לעדת בין ישראל למשמרת למי נדה חטאת היא.** רוצה לומר שמכניסין אותו במקום הנשמר כדי שיהיה לעדת בני ישראל שמור בעבור מי נדה לטהרו מטמאת מת כמו שיתבאר אחר זה ואמר חטאת היא להעיר שמעשיה הן כעין עבודת אלא שאינה נפסלת בלינה הרי אפרה נשמר למי נדה ימים ושנים עד שלא עשו כי אם אחת בימי משה ולזה הוא מבואר שאם שחטה והזה מדמה היום ושרפה למחרת אינה נפסלת:
@695 **והיתה לבני ישראל ולגר הגר בתוכם לחקת עולם.** כבר דקדקה התורה שיהיו מעשיה בזה האופן ואם שנה בדבר הרי היא פסולה כי כל הנזכר בה הוא מעכב:
@696 **הנוגע במת לכל נפש אדם.** כבר ביאר אחר זה שעניין זה המת שהיה מטמא הוא שהיא בלתי מפרכס אבל הטרפה אינו מטמא אף על פי שסופו לו' ולזה יהיה הרצון במלת מת בזה המקום שיהיה מת בפעל לא אשר דרכו שימות והנה אמר לכל נפש אדם לכלול בזה הזכרים והנקבות הגדולים והקטנים ואפילו הנפלים שהרי הם נכללים במה שאמר לכל נפש אדם:
@696 **וטמא שבעת ימים.** ביאר שהמת מטמא במגע טמאת שבעה:
@697 **הוא יתחטא בו ביום השלישי וביום השביעי יטהר.** ר"ל שביום השלישי לטומאתו יזו עליו ממי הנדה ואחר ישובו להזות ממנו עליו ממי הנדה ביום השביעי ויטהר לערב אחר שטבל וזה דבר כולל לאדם וכלים שנגעו בו מת כי כבר נתבאר בפרשת ביום השמיני שהכלים מקבלים טומאה ממה שיקבלם האדם:
@697 **ואם לא יתחטא ביום השלישי.** ביאר שלא יתכן שתשלם הטהרה לו אם לא יזו עליו ביום השביעי וביום השלישי והנה היום הזה הוא מעלות השחר כאמרו ואנחנו עושים במלאכה. ר"ל מעלות השחר ועד צאת הכוכבים ואומר והיה לנו הלילה משמר והיום מלאכה ואין ספק שאין שהה ימים רבים מעת טומאתו שכבר יזו עליו לאלתר שהרי היה ראוי לזאת ההזאה קודם זה וכ"ש שהוא ראוי לה עתה ועושה היום ההוא כמו יום שלישי וימנה אחריו ארבעה ימים ויזו עליו ויטבול ויטהר לערב וכן אם שה ימים רבי' אחר ההזאה הראשונה מזין עליו לאלתר וטובל ויטהר לערב:
@698 **כל הנוגע במת בנפש האדם אשר ימות.** אמר אשר ימות להעיר שהרצון בזה שיהיה מת בפעל ולולי זה היה אמרו אשר ימות לבטלה וכבר יתבאר מצד הוראת הגדר כי המגע לא יהיה אלא אם נגע בחצוני הגוף ולזה יתבאר שמגע בית הסתרים אינו מטמא כאלו תאמר שתחב הטומאה בכוש והכניס בגרונו וכבר יתבאר זה גם כן ממה שאמר בסוף פרשת ויהי ביום השמיני הנוגע בנבלתה יטמא עד הערב והאוכל מנבלתה יכבס בגדיו והוא מבואר שאי אפשר באוכל שלא יגע בדבר הנאכל מגע בית הסתרים אלא שזה אינו מגע ולזה שם דינו כדין המשא ולפי שאמר בנפש האדם והיה הדם נקרא נפש כמו שאמר כי הדם הוא הנפש למדנו שהדם היוצא מהמת שאפשר שתתלה בו הנפש הוא מטמא כמת ושערו חכמים שהוא רביעית דם:
@698 **ולא יתחטא את משכן יי' וגו'.** ר"ל שאף על פי שטבל כיון שלא הזו עליו ממי הנדה באופן הנזכר אם נכנס למקדש הרי הו בכרת כי עדין הוא בטמאתו כיון שלא זורק עליו מי נדה באופן הנזכר:
@699 **זאת התורה אדם כי ימות באהל.** למדנו מזה שהמת מטמא באהל:
@699 **כל הבא אל האהל וכל אשר באהל יטמא שבעת ימים.** לפי שלא גזר בזה המקום טמאה על האהל אבל על מה שבתוכו ואמר במה שאחר זה והזה על האהל למדנו שיש מן האהלים שאינו מטמא ומן האהלים שמטמא וכולם משתתפים בהבאת הטומאה לכל מה שתחתיהם. והנה האהל שאינו מטמא הוא מציל מה שעליו והאהל המטמא אינו חוצץ כי הטומאה תעבירהו ולזה יטמא כל מה שהוא על הטומאה לפי שהוא מאהיל עליה עד שיגיע העניין לאהל בלתי מקבל טומאה והנ' האהל המקבל טומאה הוא נעש' מארוג או עור כמו העניין באהל המשכן והוא יטמא משום אהל והאהל שאינו מתטמא משום אהל כמו הבית ומה שידמה לו וראוי שתדע שלא יקרא אהל לפי הורא' הגדר אם לא יהיה בו חלל טפח על טפח ברום טפח ולזה לא יהיה חוצץ בפני הטמאה אם לא היה בזה התואר וראוי שתדע כי מה שנתבאר בזה המקום באל הטהור שהוא חוצץ בפני הטומאה אם היתה חוצה לו ר"ל למעלה או למטה וראוי שתדע שמגדר האהל שיהיה מתקיים וקיים במקום אחר ולזה אם היה מתנועע כמו הספינה או שלא היה לו קיום כמו עלי הירק ומה שידמה להם לא יכנס בגדר האהל להביא הטומאה למה שתחתיו או לחוץ בפני הטומאה:
@699 **כל הבא אל האהל.** ראוי שתדע שכיון שבא שם מקצת האדם או הכלי נטמא כלו כמו העניין בנגיעה שאינו מתנאה שיגע הטומאה בכל הכלי אבל כיון שנגע אותה בחלק ממנו נטמא כלו וזה בלתי צריך אל ביאור ולפי שאמר כל הבא אלא האהל ולא אמר הנוגע באהל כמו שאמר בקבר למדנו שאהל פתוח אינו מטמא אלא דרך פתחו ואם לא היה פתוח היה מטמא מכל הצדדין בדמיון הקרב:
@699 **וכל אשר באהל.** למדנו מזה כי כל מה שתחת האהל מטמא במת עד התהום אלא שאם היה שם אהל אחר יציל על מה שתחתיו כמו העניין במה שיזכור בכאן בצמיד פתיל לפי מה שנבאר אחר זה ולפי שהתורה תדבר דבריה בעצמות מדרך מה הוא למדנו שבצד אחר לא יטמא המת מה שסביביו אלא על ידי אהל או קבר שהוא בדמיון אל כמו שנתב' אחר זה. וראוי שתדע שאף על פי שאמר כל אשר באהל יטמא הנה לא יהיה הרצון בזה שיטמא בזאת הטומאה כי אם מה שדרכו לקבל זאת הטמאה והם אדם וכלים כי אוכלין ומשקין לא יטמאו טמאת שבעה ולזה אמר אחר זה והזה על האהל ועל כל הכלים ועל הנפשות אשר היו שם ללמד שלא תתפשט זאת הטמאה בזולה אדם וכלים:
@700 **וכל כלי פתוח אשר אין צמיד פתיל עליו טמא הוא.** לפי שלא מצאנו רושם בצמיד פתיל כל אם בכלי חרש כמו שנתבאר בפרשת ויהי ביום השמיני והיתה הסבה בזה להיותו בלתי מטמא אלא מאוירו למדנו כי בכלי חרש דבר הכתו' כי שאר הכלים לא יועיל להם צמיד כי הם מטמאין מגבן ואולם כלי חרש כיון שאינו מקבל טמאה אלא מאוירו הרי הוא טהור כיון שיש צמיד פתיל עליו ולזה הוא מבואר שאם היו כלים בתוכו שהם גם כן טהורים שאם היו מטמאין מפני האל היו הם מטמאים הכלי חרש כי הם מאוירו והתורה הגידה מכח דבריה שאם יש שם צמיד פתיל עליו הרי הוא טהור ולא הבדילה בזה בין שיהיו בתוכו כלים ובין שלא יהיו בתוכו כלים ולזה הוא מבואר שהוא מציל על הכלים שבתוכו ולפי שאמר תחלה כל אשר באהל יטמא שהיה כולל אפילו הכלים הבלועים ואחר כך הוציא מזה הבלועים שבצמיד פתיל למדנו מזה שאין הבלועים בכלים נצלים אלא בצמיד פתיל:
@701 **וכל אשר יגע על פני השדה.** ר"ל במקום שאין דבר מאהיל עליו הנה אם נגע באחד מאלו המינים שיזכור מן המת יטמא שבעת ימים:
@701 **בחלל חרב אם במת או בעצם אדם או בקבר.** לפי שהתורה לא תדבר דבריה לבטלה ראוי שנבין זה המאמר בדרך שלא יהיה בדברי תורה דבר ללא ענין ונשלים הסבה עם זה למה לא היה הסדור אחר זה בזכירת אלו המינים כמו הסדור שבזה המקום אמר וכל הנוגע בעצם או בחלל או במת או בקבר והוא ידוע ששם החלל יפול על האבר האחד אמר לבי חלל בקרבי ולפי שהנהוג על הרוב ממיתת האבר האחד הוא שיהיה זה באמצעות החרב קראט האבר ההוא חלל חרב ואמר אחר כן או במת להמשיל האבר למת ואף על פי שהוא לקוח מן החי ולולי זה היה אומרו בחלל חרב לבטלה כי מת יקרא המת מעצמו על יד זולתו אמר יומת המת והנה זה ע"י בית דין ועוד כי אין זה הבדל יהיה בזה העניין בין המת בחרב ובין המת באן או באגרוף או בזולת זה ואיך יעלה על דעת שיהיה הבדל בזה שתצטרך בעבורו התורה לזכור זה ולזה הסכמנו שיהיה הביאור בזה שב אל האבר שפלטתו החרב ומזה המקום יתבאר שאבר מן המת יטמא גם כן במגע טמאת שבעה והנה באיברם אשר מדרך החרב לפלטן תמצאם שיש בהם בשר גידים ועצמות ולזה לא יהיה באבר דין המת אם לה היה בו בשר גידים ועצמות:
@701 **או בעצם אדם.** ביאר שאפילו העצם בזולת בשר מטמא כשיוכר בו שהוא עצם אדם או כשאפש' בו שיקרא עצם אדם וזה אמנם יהיה בעצם הגולגולת השלמה כי הוא יוכר בו בין גולגולת אדם וזולתו וכן העניין בשדרה השלמה והנה רוב בנינו של אדם יקרא עצם אדם והשמל שבנינו הוא על אלו העצמות שוקים והיריכים והצלעות והשדרה ורבם יקרא עצם אדם וכן רב עצמותיו בכללם וזה שכל עצמות האדם יקראו יחד עצם אדם ולזה יקראו רובם עצם אדם וראוי שלא יעלם ממנו שחלק מבזר מת יטמא טומאת מת וזה יתבאר מעניין נבלה ושרצי' שנאמר בהם מנבלתם ואשר יפול עליו מהם וקל וחומ' בטומאת מת החמור ועוד שאם העצמות מטמאין טומאת מת שאין בהם חיות ולא הרגש כ"ש שיטמא הבשר שהחיו' וההרגש הוא בו בעצמות וראשונ' ולזה יתבאר שחלק מהכשר יטמא טומאת מת וזה החלק ראוי שיהיה החלק הראשון שיהיה בו החיות והוא כזית כי שערו חכמים כי האדם בתחלת ברייתו הוא כזית:
@701 **או בקבר.** למדנו מעניין הקבר שהוא מטמא אם נגעו בו מסביביו לפי שהוא סתום ואולם אם הוא פתוח אינו מטמא כי אם דרך פתחו כמו העניין באהל וראוי שיתבאר מזה שאם היה בקבר אהל והיה המאהיל בלתי מקבל טומאה כמו נסרי' הנה הוא חוצץ בפני הטומאה ויהיה מה שעליו טהור. ולפי שהקבר יקרא קבר גם אחר שהרקיב המת למדנו מזה שאין הבדל בטמאת מת בין לח בין יבש ורואי שיבאר מזה שכל אלו מטמאין באהל שהרי אמר תחלה וכל אשר יגע על פני השדה ביאר בזה שאם היו באהל הנה הם מטמאים באהל וראוי שתדע שהמת כמו שמטמא בנגע כן מטמא במשא ואמנם שתקה התורה לפי שיא בארה בפרשת ויהי ביום השמיני בטמאת נבלה שטומאת משא חמורה מטומאת מגע כי היא טעונ כבוס בגדים מה שאין כן בטמאת מגע והסבה בזה כי הנוגע אינו נוגע כי אם בשטח הגוף הטמא ואמנם הנושא נושא עצם הגוף הטמא ובהיות העניין כן והיה בלתי אפשר בטומאת מת להחמיר יותר בטמאת משא מטמאת מגע כי טמאת מגע טעונה כבוס בגדים כאמרו וחטאו ביום השביעי וכבס בגדיו ורחץ במים וטהר בערב הנה שתקה התורה מהמשא לפי שהוא מבואר שאי אפשר בטמאתה שתהיה למטה מטומאת מגל ולזה הוא מבואר שהמת מטמא במשא מן התורה:
@702 **ולקחו לטמא מעפר שריפת החטאת ונתן עליו מים חיים אל כלי.** לפי שדקדקה התורה שיהיו המים בהיותם נתנים אל כלי למדנו שלא יעשה במים מלאכה למדו גם כן שהוא מחוייב שלא יתעסק במלאכה אחרת בנתינתו המים אל הכלי כדי שתהיה כוונתו לתת המים אל כלי בעבור עפר שריפת החטאת כי אמרו ונתן עליו אי אפשר שיהיה הרצון בו שיתן העפר בכלי ואחר יתן על העפר מים חיים וזה כי מפני שהעקר הגדול בזה הוא עפר שריפת החטאת הנה ראוי שיתן האפר על המים כדי שיוכר ויתערב במים כמו העניין במי סוטה שבארה התורה בפרשת נשא שהעפר הוא שנתן על המים כי בזולת זה ישאר למטה לכבדותו ולא יוכר העפר במים ההם ולזה יהיה הרצון באמרו ונתן עליו ונתן בעבורו כטעם על שאול ועל בית הדמים ומזה יתחייב שתהיה נתינתו חמים החיים אל הכלי בעבור תכלית שינתן בהם עפר שריפת החטאת ולזה הוא מבואר שאם נתעסק במלאכה אחרת עם מלוי הכלי הנה אותם המים פסולין למי חטאת כי אי אפשר שיכוין אדם לבו בשני מלאכות מתחלפות יחד וצריך שיהיה כלי מה שינתן בו המים חיים ואם לא ידבק בו גדר הכלי אשר יתכן שישתמשו בו בנתינת המים הנה אותם המים הם פסולין והנה קראה התורה זה האפר עפר להורות שאם נשתנה האפר לעפר מפני רוב הזמן שעמד הנה הוא כשר למי נדה ולפי שלא דקדקה התורה בנותן המים חיים אל כלי שיהיה כהן למדנו מזה שכל בן דעת כשר למלא ולפ שאין זה העניין עבודה יהיה המלוא כשר אפי' בלילה ולפי שלא בארה התור' שיהיה עפר שריפת החטאת נתן על הכלי הראשון שמלא אותו מים חיים בעבורו למדנו מזה שמותר לעדות המים מהכלי ההוא אל כלי אחר לשים בו עפר שריפת החטאת אלא שהוא ראוי גם כן שינתנו המים הלו בכלי השני בעבור עפר שרפת החטאת כי מן השקר שתדקדק התורה בזאת הכונה במלוא הכלי הראשון ולא תדקדק בכונה הזאת בכלי השני אשר בו ינתן האפר שהוא השרש והעיקר בזאת הטהרה ובכלל הנה יתבאר ממה שזכרנו שראוי שלא יתעסק במלאכה אחרת עד נתינתו האפר על המים שאם היה עושה כן לא יתאמת שנתן בעבור האפר מים חיים אל כלי כי הוא מניח המים ועוסק במלאכה אחרת קודם נתינתו העפר והתורה דקדקה שיהיה זה העניין מלאכה אחת ויכוין מראשיתה זה התכלית וראוי שלא יעלם ממנו כי עם זה לא ימנע שתהיה זאת המלאכה נעשית על יד שנים זה אחר זה כי המלאכה האחת כבר יקרה בה זה ולזה אפשר אחר שנתן המים אל כלי שיטוש המים אל יד שומר ויוכל הוא לעשות מלאכה כיון שהשומר אינו עושה מלאכה ולא תקרא מלאכה אחרת מה שהוא הכרח הולכת המים לקדשן בעפר בעבור שריפת החטאת וצרך המקדש שיכוין ויתן האפר בידו על המים לטהר הטמא שנאמר ולקחו לטמא לזה צריך שיכוין לקדש המים ולהזות מהם על הטמא אלא שלא יחוייב שתהיה הכונה לטהר זה הטמא שהרי לא הקפיד הכתוב אלא שיזרקו על הטמא מי נדה מכל מקום וכבר מצאנו גם כן שהתורה ביארה שהמים אשר קדשם יזה מהם על דברי' רבים וזה ממה שיורה שלא יחוייב שיכוין בקדשו המים באפר לכל הטמאים אשר יטהרו באלו המים ולזה גם כן ביאר שההזאה אפשר שתהיה על יד אחר וזה כלו ממה שיורה שלא יחוייב שתהיה כונתו אלא לטהר המים אשר יקדש אי זה טמא אשר הזדמן וזה יתבאר ביאור יותר שלם כשנתן הסבות בכל אלו הענינים שזכרה התורה בזה:
@703 **ולקח אזוב וטבל במים איש טהור.** לפי שלא התנה באזוב שלא יהיה בו מלאכה נעשית כמו שהתנה במים למדנו שאחר זה לא תהיה המלאכה שיעשו הבעלים פוסלת מי נדה אפילו בגוף האזוב לא תהיה המלאכה פוסלת וג"כ לפי שבדיל זאת המלאכה מהאחרת למדנו שאחר שנתקדשו המים באפר אין המלאכה שיעשו הבעלים קודם ההזאה פוסלת המים ההם אלא שהוא מבואר שוא צריך שלא יעשה מלאכה בגוף המים ההם כי הכתוב קראם מי נדה שלא ישתמש בהם אלא לזה התכלית כדי שלא יסור שם נדה מהם וצריך ג"כ שיהיו מי נדה נשמרים שנאמר למשמרת למי נדה וזה שאם היה זה אפר צריך שמור בעבור תכלית שיהיו ממנו מי נדה כ"ש שמי נדה צריכין שימור ועוד שהרי יש בהם אפר שהוא צריך שימור ומזה המקום יתבאר שאם לא הונחו מי נדה במקום טהור הרי הן פסולין ואע"פ שהיו בתך כי חרס מוקף צמיד פיל כמו הענין באפר והנה האזוב הוא הנקרא אזוב בלי שום לווי לא אזוביון ולא אזוב מדברי והדומה להם ומה שהתנה שיהיה הטובל האזוב במי' אשר טהור הנה אמר זה להוציא את האשה שנכללה במעשי' הקודמים ולפי שלא בא להוציא את הקטן שב לתאר אותו שנית בזולת מלת איש ואמר והזה הטהור על הטמא ולזה צריך בקטן שיהיה בן דעת כי ההזאה צריכה כונה שיהיה בעבור הטמא וזאת לא תשלם בקטן שאינו בן דעת כבר בארנו שמלת טהור תאמר בענייני הפרה במי שהו' טהור למעשר שני אע"פ שהו' טמא לתרומ' והנה הוצרכה התורה להזכיר בזה המקו' זה התנאי כי אולי יחשב חושב שלא יצטרך זה לפי שמי חטאת אין מטמאין כמו שיזכור אחר זה ועוד שלולי זה התנאי היינו אומרים שהטהור שהזה הוא טמא ולזה למדתנו התורה שהנוגע במי חטאת לצורך הזאת אינו טמא שנאמר ולקח אזוב וטבל במים איש טהור ואומר והזה הטהור על הטמא ללמדנו שמפני הזותו על הטמא לא נטמא וראוי שתדע שלא יחויב במקדש המים באפשר שיהיה הוא המזה כי התורה שמה זה העניין מלאכה אחרת ולזה אמרה ולקח אזוב וטבל במים איש טהור והזה על האהל ועל כל הכלי' ועל הנפשות אשר היו שם למדנו מזה שאף על פי שיטמא האהל הנה הוא מביא הטומאה בכל מה שתחתיו ואף עלפי שאינו חוצץ בפני הטומאה ולמדנו מזה שאינו צריך על כל הזאה טבילה אבל בטבילה אחת יזה על דברים רבים זה אחר זה מה שהתמיד האזוב להיות בו מים להזות ולמדנו מזה גם כן שבהזאה אחת יוכל להזות על דברים רבים אך שיוזה על כל אחד מהם שנאמר ועל כל הכים ועל הנפשות. וצריך שתהיה ההזאה בקצת הנגלה משטח הטמא לא מבית הסתרים שנאמר על האהל ועל כל הנפשות לא בתוכם ולמדנו מאמרו ועל הנפשות אשר היו שם כי גם הקטנים יטמאו בזאת הטומאה ולמדנו גם כן שצריך שיוכין להזות על הטמאים שהוא מזה עליהם כי לא אמרה והזה על הטמאים אבל אמרה והזה על האהל לבאר שצריך שיכוין להזו' על האהל ועל כל דבר שיזה עליו ומזה יתבאר שצריך שתהיה ההזאה במי שמזה עליו מכח המזה לא מכח כחו ולזה אם הזה על האחד ונטפו המים על השני הזאתו פסולה וצריך גם כן שתהיה ההזאה מהאזוב לא מיד המזה ולא מחוט הנאבד בו:
@703 **ועל הנגע בעצם או בחלל או במת או בקבר.** הנה הקדים העצם לחלל כי העצים אינו אבר והחלל הוא אבר שלם שיש בו בשר גידין ועצמות ואחר כן זכר המת שהוא כלל הגוף והנה עלה בזה בהדרגה מהקטן אל הגדו' ולפי שעניין הנגיעה בקבר הוא בלי מתיחסת לנגיעה בעצם או בכלל או במת כי היא אינה נגיעה במת ולא בחלק ממנו אבל נגיעה אהל סתום אשר בו כלל המת הנה לזאת סבה לא זכר אתו קודם המת:
@704 **והזה הטהור על הטמא ביום השלישי.** למדנו מזה שההזאה לא תהיה אלא ביום:
@704 **וחטאו ביום השביעי וכבס בגדיו ורחץ במים.** למדנו מזה שההזאה קודמת לטבילה לא טבילה להזאה כשהיתה הזאה ביום השביעי אבל אם לא הזו עליו ביום השביעי הנה יזו עליו אחר זה אם קודם טבילה או אחריה אך צריך שתהיה ההזאה ביום איך שתהיה כי התורה הקפידה בזה:
@705 **ואיש אשר יטמא ולא יתחטא ונכרתה וגומ'.** ר"ל אם נכנס למקדש כמו שביאר ואמר כי את מקדש ה' טמא ומזה מי הנדה יכבס בגדיו. אי אפשר שנבין מזה שיהיה המזה טמא שהרי בארה התורה שטהור כי התנית בהזאה שתהיה על ידי טהור ואמרה שהוא יזה על האהל ועל כל הכלים ועל הנפשות ואם היה המזה טמא הנה אחר שהזה על האהל לא יוכל להזות על השאר ולזה יהיה הרצון בו שאם היה אפשר בו לחזות במי הנדה שהוא וגע רוצה לומר שהיה בהן כדי הזאה הנה הוא טעון כבוס בגדים אם לא היה בהן כדי הזאה ונגע בהם יטמא עד הערב וטעון כבוס בגדים:
@707 **וכל אשר יגע בו הטמא יטמא וגומ'.** רוצה לומר שמי שנטמא במת ונגע באחר הנה זה שנגע בו הוא גם כן טמא ולזה הוא מבואר שהטמא מת הוא אב הטומאה לטמא אדם כלים:
@707 **והנפש הנוגעת תטמא עד הערב.** למדנו מזה שהנוגע בטמא מת אינו טמא בטומאת שבעה אבל טומאת ערב.
@709 **ולא היה מים לעדה.** הנה סמך זה למיתת מרים להעיר שמיתת הצדיקים עושה רושם ואחשוב שגם מרים היה מושכת לב ישראל בחכמתה לעבוד השם יתעלה וכאלו אמר שאם היתה מרים בחיים לא הרסו ישראל בזה האופן לשאל המים ממשה בדברי קנטורין כאלה או יהיה הרצון בזה להעיר שאלו היתה מרים בחיים היו נמלכים בה משה ואהרן במה שצוה השם יתעלה אותם ודברתם אל הסלע והיתה היא סבה לשמרם מהשכל בזאת המצוה כי היא היתה נביאה גם כן והיתה גדולת השני' מהם וידמה שהיו חולקים כבד לה לקחת עצה ממנה או יהיה הסמיכות בזה להעיר שיחד נגזרה מיתתם על שלשתם כי בעת מיתתה בא זה המקרה אשר נמשך ממנו גזרת המות על משה ועל אהרן ובמעט זמן מתו כלם כאמרו ואכחיד את שלשת הרועים בירח אחד ואיננו רחוק מה שאמ' רז"ל על צד הדרש שהמים היו באים להם בזכות מרים כי המופתי' יתכן שיתחדשו ע"י אי זה שיהיה נביא והנה הראו העם בדבריהם כי יותר נבחר היה להם המות מאלו החיים שהם חיי צער עם שימשך להם המות בסבת הצמא והתרעמו על משה בהוציאו אותם מארץ מצרים למות במדבר וזכר כי משה ואהרן להתרחק משמוע אלו הדברים הקשים מהעם נתרחקו מהם ובאו אל פתח אהל מועד ונפלו על פניהם לשם ית' לתת לישראל בקשתן כי המופתים יתחדשו ע"י הנביא באמצעות תפילתו לש"י או אפשר שנפלו על פניהם לקהל לבקש מהם על דרך תחנוני' שלא יכשלו בכמו אלו הדברים ליראתם פן יחרה אף הש"י בהם וכבר היה תועלת עוד בהתקרבם אל פתח אהל מועד כי השם יתע' אמר למשה שכבר ידבר עמו מעל הכפרת מבין שני הכרובים את כל אשר יצוה אותו אל בני ישראל והיו בזה שתי תועלות האחד להישיר ולישב בלבם דבר הקדושה הנפלאה אשר במקום ההוא והב' כי מזה יישרו גם כן לעמוד על הכונה אשר בעבורה צותה התורה לשום על ארון העדות הכפרת ושני הכרובים:
@715 **קח את המטה.** ידוע שיאן הצואה בלקיחת המטה ראיה שירצ' הש' ית'. שיכה במטה הלא תראה אמרו ואת המטה הזה תקח בידיך וגומ'. וכבר היו בו אותות רבים בזולת הכאה ועוד כי במכת הברד זכר בביארו שלקח משה המטה בידו ולא הכה בו ולזה הוא מבואר שלא היה מחוייב מזה המאמר שיהיה רצון ה' ית' שיכה משה במטהו על הסלע:
@715 **ודברתם אל הסלע וגו'.** הנה זה המאמ' יסבול שתי כונות מפני שתוף לת אל האחד הוא שידברו לסלע ויאמרו לו שיוציאו מימיו מזולת שיכו בו והשני הוא שידברו בעבור הסלע כטעם אמרי לי אחי הוא ובזאת הכונה השנית הבינו משה ואהרן זה המאמר ומפני שצוה ה' ית' לקחת המטה הבינו שיהיה הרצון בזה שיכה בו משה את הסלע כי הוא צוה בלקיחת המטה ומשה ואהרן צוו בדבור אל הסלע ואמנם רצון ה' ית' היתה בזה הכונה הראשונה שזכר בו כדי להישיר ישראל יותר להאמין בו בדרך שיהיו ראוים. לירושת הארץ בשלם שבפני' כי בהכאה במטה היה אפשר שיפול בלבם קצת בספק ויחשבו כי אולי היה מטבע זה המטה שיבקע הסלע בהכותו בו כמו שאמרו רז"ל ולזה אמר יען לא האמנתם בי לקדישנו ולפי שחסרון אמונת ישראל בש' ית' היתה סבה אל שצוה ה' ית' לדבר אל הסלע כדי שיתפרסם להם עוצם גבורת ה' ית' הנה אם כן יתאמת שהן היו סבה לכעוס ה' ית' במשה ואהרן ולזה ספר שה בפרשת ואלה הדברים גם בי התאנף ה' בגללכם לאמר גם אתה וגו' ואמר בפרשת ואתחנן. ויי' התאנף בי על דבריכם וישבע לבלתי עברי וגו'. ואפשר עוד שתהיה הכונה בזה כי הם היו סבה לכעוס משה עליהם והכעס היה סבה אל שנעלמה ממשה כונת השם יתע' במה שצוהו ואמר ודברתם אל הסלע ונתן מימיו ואפשר שכר נתחברה לזה סבה אחרת והוא כי מפני שישראל לא היו באון מהמעלה והחשיבות שהיו ראוים שתנתן להם הארץ על ידי משה רבינו היה רצון ה' ית' שלא יביא ואתם משה אל הארץ וזהו אמרו בפרשת ואתחנן ויתעבר יי' בי למענכם וגומ' ואולם היה זה על צד העונש לישראל כי לו היה זה על ידי משה היה מכלה אותם האומות כרגע לעוצם דבקותו וש"י ולחריצותו להיטיב לישר' ולזה תראה שכבר כלה במעט זמן אנשי הארץ אשר נתנה להם לנחלה לראובני ולגדי ולחצי שבט המנשי. אמנם יהושע בן נון לא היה כחו יפה כל כך ונתעצל במלחמות ההם כמו שנתבאר בספר יהושע ולזה נשארו מהאומות ההם מה שהיה סבה למכשול ישר' בתועבותיהן ולהביא עליהם מכות גדולות כמו שנתבאר בספר שופטים כי השם ית' השאירם לנסות בם את ישראל:
@717 **המן הסלע הזה נוציא לכם מים.** ר"ל שלא יתכן זה אם לא מצד פלא יחדשהו הש' ית':
@718 **ויך את הסלע במטהו פעמים.** ידמה שפעם ראשונה לא יצא ממנו מים לפי שכבר עבר על מצות הש' ית' ואחר זה התפלל משה לש' ית' והכה שנית ויצאו ממנו מים רבים די שלא יתבייש משה ולא יתחלל השם הכבד שלולא זה אללי היו אומ' בו מבלתי יכולת השם ית' לתת להם מים קרח זה לא בסבת עבור משה על דברי ה' ית' ולזה שמע השם ית' לקולו ואע"פ שלא היה זה הנרצח ממנו וכמו זה אמר מקים דבר עבדו ועצת מלאכיו ישלים. וכזה תמצא שאמ' משה לפרעה התפאר עלי למתי אעתיר לך להשענו שהשם ית' יקים את דבריו:
@720 **אשר רבו בני ישראל את יי' ויקדש בם.** ר"ל שנקדש בם לגזור מיתה על משה ואהרן כטעם בקרובי אקדש או יהיה שב אמרו בם אל משה ואהרן שזכר בפסוק הקודם עם היות ריב ישראל ומעוט אמונה בשם ית' סבה לזה כי נענשו מפני זה שיפקדו מהם משה ואהרן כדי שלא תהיה להם ירושת הארץ באופן שלם שלא היו ראוים לזה מצד מרים כמו שזכרנו:
@723 **וישלח מלאך ויוציאנו ממצרים.** רמז בזה למשה כי הנביא יקרא מלאך וכבר אמר אחיך ישראל כי אח עשו ליעקב ועשו הוא אבי אדום:
@724 **לא נעבור בשדה ובכרם.** להשחית הפירות:
@724 **ולא נשתה מי באר.** שלא יחסרו המים הראוים לשתיה לאנשי הארץ אך ישתו ממי הנהרות והאגמים הם ומקניהם כי בזה לא יגיע נזק באנשי הארץ כאשר ראו ישראל שלא נתרצה בזה חשבו כי אולי ירצו שיגיע להם תועלת מהמים שישתו שם ישראל ומקניהם ולזה שלחו להם שינת שאם ישתו מימיו ישראל ומקניהם יתנו מכרם וספר שאחר זה כשנסעו מקדש באו הר ההר ושם רצה השם ית' שימות אהרן ונתקדש אלעזר להיות כהן גדול בלבישת בגדי אהרן ומזה המקום אפשר ללמוד שבזולת משיחה יתקדש כהן גדול בלבישת בגדי כהונה לבד וכבר נתבאר זה ג"כ במה שקדם והנה היה זה לפי הנראה בזולת חלי קדם לאהרן אך שרצה ה' ית' שיאסף אל עמיו אהרן בעבור מי מריבה וזאת המיתה היתה כשנפקד ממנו אך הוא עלה במדרגה גבוה מהחיים האמיתיים בהפרד נפשו מהחמר:
@736 **ויראו כל העדה כי גוע אהרן.** אפשר שירצה בזה כי מפני שהיה מותו בראש ההר שהיה מקו' נראה מרחוק ראו זה כל העד או ירה בזה והוא היותר נכון. כי כלם הבינו וראו מה שנפקד מהם במותו כי הוא היה משתדל בחריצות בהנהגת ישראל והיה מישיר אותם אל הטוב ומרחיק מהרע בתכלית מה שאפשר ולזה בכו אותו כל בית ישראל ל' יום:
@737 **וישמע הכנעני מלך ערד יושב הנגב.** סמך ספור זה המקרה לספור מיתת אהרן ללמדנו שני דברים האחד שמיתת צדיק עושה רושם ולזה הגיעם תכף מהנזק שנלחם הכנעני בישראל ושבו ממנו שבי והשני שנתן ה' ית' שכרם לישר' על ספדם אהרן בזה האופן הנפלא ולזה נצחון הכנעני ההוא והחרימו אותו ואת עריו כאלו הזהירתנו התורה בזה שלא נתרשל בהספדו של צדיק:
@737 **כי בא ישראל דרך האתרים.** ר"ל דרך התרים הארץ ומרגלים אותה מהיכן היתה נוחה ליכבש ולזה חשב שירצו להלחם עמו והכין עצמו להלחם עם ישראל:
@738 **והחרמתי את עריהם.** הנה זה החרם הוא להשם כמו העניין בחרם עכן ועניינו לכלות ולהחרים הערים ההם:
@741 **וידבר העם באלהים ובמשה.** הנה אלו נתרעמו בזולת סבה כי לא היו צמאים למים ולזה לא תמצא שישתדל משה לתת להם מים והם גם כן לא שאלו אלא להסיר מעליהם הנחשים השרפים ולזה יהיה הרצון באמרו אין להם ואין מים כי אין מדרך המדבר להמצא בו לחם ולא מים כי היא ארץ ציה וכמו שהיה אמרו אין לחם בלתי מחוייב שיהיו חסרים לחם כי כבר היה להם לחם והוא המן כאמרם ונפשינו קצה בלחם הקלוקל כן אמרם ואין מים לא יחויב שיהיו חסרים מים ולפי שהיו מתרעמים על הש"י ועל משה בזולת סבה הביאם על זה שלח הש' ית' בהן הנחשים השרפים הנושכים ומזיקים בזולת שיצטרכו אל זה למחיתם וזה כי הב"ח הטורפים משחיתים זולתם בעבור השגת טרפם אבל הנחש לא יזון ממה שישחיתהו ולזה תהיה השחתתו זולתו מפני רוע טבעו כי אין שם סבה תביאהו אל זה:
@744 **עשה לך שרף ושים אותו על נס וגו'.** אחשוב שכבר רצה הש"י שישאר רושם מזה העניין לישראל להיותם להם לזכרון לשמרם שלא יספרו לשון הרע הלא תראה כי נחש הנחשת היה נשאר עד ימי חזקיהו והוא כתת אותם כמו שנזכר בספר דברי הימים ואל צד הפלא רצה הש"י שכאשר יביט אל נחש הנחשת כל מי שהוא נשוך ימלט מהמות וכדי שיוכלו להביט בו כלם הושם על נס והנה היה בקיו' מציאות נחש הנחשת תועלת ליסר ישר' מלשון הרע ולישב בלבם ענין המופתי' אשר ההאמנה בהם הוא הגדולה שבפנות התוריות:
@749 **כי ארנון גבול מואב.** ר"ל שהעיר ההיא הוא גבול מואב בין מואב ובין האמורי וזה שהעיר היא היתה ממואב ומשם ואילך היתה מהאמורי ולזה נקר' גבול מוא' ואמר ג"כ שהו' יוצא מגבול האמורי:
@750 **בספר מלחמות ה'.** אחשוב שהיה זה הספר נכתבו בו כל ספורי מלחמות יי':
@750 **את והב בסופה ואת הנחלים ארנון.** ר"ל שעיר את והב היתה בסופה והוא הסוף שיגדל סמוך לנהרות וארנון היה את הנחלים וכלן היו מגבול מואב והוצרכו ישראל לסבוב גבול מואב שלא יכנסו בארץ מואב כי לא רצה הש"י שיסבכו להתגרות בם מלחמה וכן היה מגבול מואב מה שהיה מתקבץ מהנחלים שהיו נשפכים יחד למקום אחד והיה המקובץ נחל גדול והיה נקרא אשר הנחלים וזה הנחל היה נוטה בתנועתו לשבת ער ר"ל לשבת ער ויהיה שבת שם מקום וכן ער והנה אשר הנחלים היה סמוך לגבול מואב ולזה נתבאר מזה שאלו המקומות כלם הם בגבול מואב וזהו אמרו על כן יאמר בספר מלחמות השם וגו'. להביא עדות שארנון היה גבול מואב ומזה המקום יתבאר שישראל היו הולכים סביב ארץ מואב ומזה המקום יתבאר שישראל היו הולכים סביב ארץ מואב ולא רצו עבור בגבולו ולזה אמר בלק והוא יושב ממולי:
@752 **ומשם בארה.** ר"ל כי מעבר ארנון נסעו וחנו אל מקו' הבאר והוא במדבר כמו שאמר אחר זה וממדבר מתנה והוא המקום שצוה השם יתע' שיחפרו בו באר ויתן להם מים ואפשר כי לזאת הסבה נקרא המקום שחנו בו באר ולפי שהיה המקום ההוא בלתי ראוי שיצאו ממנו מים שרו ישראל על הפלא שעשה להם השם יתעלה בנתינתו להם מים מהבאר ההוא.
@753 והנה דבר השירה הזאת **עלי באר ענו לה.** ר"ל כאלו היה אומר זה לזה שוררו בעבור הבאר זה השיר והוא אמר באר חפירות שרים כרוה נדיבי העם במחוקק משענותם ואמר חלה עלי באר ענו לה כאלו דברו עם הבאר שיעלה ר"ל מי הבאר להעיר על עליית המים בגבורה מהמקום ההוא שלא היה ראוי לזה:
@754 **באר חפרוה שרים וגומ'.** ר"ל כי להיות העפר ההוא עפר תיחוח לא הוצרך למי שיתעמל בחפירתו אבל השרים ונדיבי העם כרוהו וחפרוהו במשענותם והוא המטה אשר בידם כמו המחוקק שיכתוב בעט הסופר בזולת עמל כן חפרוה וכרוה בקלות במשענותם ומעפר כזה לא היה ראוי שיצאו להם מים ועם זה היו עולים מים רבים ממנו שהספיק לכל עדה.
@754 וממדבר נסעו ובאו אל מתנה וממתנה לנחליאל ומנחליאל לבמות ומבמות לגיא אשר בשדה מואב בראש מקום גבוה וחזק שם היה מביט אל פני הישימון והוא ארץ שממה והנה אלו כלם הם שמשות מקומות והנה לכל אלו המקומות שמות אחרים בפרשת אלה מסעי:
@757 **וישלח ישראל מלאכים אל סיחון מלך האמורי וגו' וירש את ארצו מארנון ועד יבוק ועד בני עמון כי עז גבול בני עמון.** אחשוב שארנון היה למואב אז כמו שספר בפרשה הקודמת ויהיה הרצון באמרו מארנון כי משם יתחיל גבול האמורי מהצד הזה וכאלו אמר שלא נשאר לסיחון דבר מהצד הזה שלא ירשוהו ישר' וירשו ממנו עד יבוק ועד בני עמון והוא הארץ שירש סיחון מבני עמון במלחמ' וספר כי לא יירשו הארץ ההיא כי עז גבול בני עמון וחזק מאד וכמו זה אמר בספר יהושע כי לא להוריש את יושבי העמק כי רכב ברזל להם ויש לספק בזה מדוע לא לקחו ג"כ ישראל אז מידו ארץ בני עמון והנה יד השם תקצר והנה אע"פ שהיה חזק היה יכולת ביד הש"י לסבב שינצחוהו ישראל והנה היתר זה הספק הוא כי הש"י אע"פ שיש בידו לעשות כל אשר חפץ הנה לא יעשה הש"י המופתים רק בעת הצרך ולראויים להם ויחבר אליהם עם זה כל הסבות הנאותות לפי מה שאפשר כמו שזכרנו פעמים רבות ולולי זה לא היו צריכים ישראל למלחמה אבל היה אפשר שישלח השם מלאכו וימיתם כמו הענין בחיל סנחריב ולזה היה רצון הש"י שיהיה זה דרך מלחמה ולזה נמלטו מהם המקומות החזקים מאד כמו שנזכר בזה המקום ובספר יהושע עם שישראל לא היו ראויים כמו זאת ההשגחה הנפלאה כמו שזכרנו בזאת הפרשה ולפי שהתורה הזהירתנו שלא נקרב לארץ עמון ולארץ מואב כי לא יתן לנו מארצם נחלה שום דבר הוצרך להזכיר בכאן שהמקומות שישבו בהם ישראל שהיה מפורסם היותה ממואב מקדם כבר לקחם מסיחון לא ממואב ומזה לא הזהירה התורה את ישר' כי אחר שירש את האמורי הארץ ההיא לא היתה הארץ ההיא ארץ מואב ולזאת הסבה ג"כ הותרה להן ארץ בני עמון אשר כבש סיחון ולא נמנעו מלקיחתה אלא מפני שהיה עז גבול בני עמון וחזק מאד וכמו זה אמר בספר יהושע כי לא להוריש את יושבי העמק כי רכב ברזל להם ויש לספק בזה מדוע לא לקחו ג"כ ישראל אז מידו ארץ בני עמון והנה יד השם לא תקצר והנה אע"פ שהיה חזק היה יכולת ביד הש"י לסבב שינצחוהו ישראל והנה היתר זה הספק הוא כי הש"י אע"פ שיש בידו לעשות כל אשר חפץ הנה לא יעשה הש"י המופתים רק בעת הצורך ולראויים להם ויחבר אליהם עם זה כל הסבות הנאותות לפי מה שאפשר כמו שזכרנו פעמים רבות ולולי זה לא היו צריכים ישראל למלחמה אבל היה אפשר שישלח השם מלאכו וימיתם כמו הענין בחיל סנחריב ולזה היה רצון הש"י שיהיה זה דרך מלחמה ולזה נמלטו מהם המקומות החזקים מאד כמו שזכר בזה המקום ובספר יהושע עם שישראל לא היו ראויים כמו זאת ההשגחה הנפלאה כמו שזכרנו בזאת הפרשה ולפי שהתורה הזהירתנו שלא נקרב לארץ עמון ולארץ מואב כי לא יתן לנו מארצם נחלה שום דבר הוצרך להזכיר בכאן שהמקומות שישבו בהם ישראל שהיה מפורסם היותר ממואב מקדם כבר לקחום מסיחון לא ממואב ומזה לא הזהירה התורה את ישר' כי אחר שירש את האמורי הארץ ההיא לא היתה הארץ ההיא ארץ מואב ולזאת הסבה ג"כ הותרה להן ארץ בני עמון אשר כבש סיחון ולא נמנעו מלקיחתה אלא מפני שהיה עד גבול בני עמון:
@762 **ויקח את כל ארצו מידו עד ארנון.** ר"ל שלא לקח ארנון אך לקח ארצו עד המקום ההוא כטעם עד בני עמון הנזכר למעלה שמבואר שם שלא לקחוהו כי עז גבול בני עמון וזה יתבאר גם כן ממה שנזכר בפרשת ואלה הדברים על זה העניין שכבר כבשו מערוער אשר על שפת נחל ארנון וזה ראיה שלא כבשו ארנון אך כבשו ערוע שהיא על שפת נחל ארנון כי ארנון היה את הנחלי' ומשם היה מתחיל גבול האמורי:
@763 **על כן יאמרו המושלים.** ממשלי המשלים והיו מעם סיחון כמו שיתבאר והם עשו אלו המשלים בימי מלחמת סיחון עם מלך מואב הראשון:
@763 **באו חשבון תבנה ותכונן עיר סיחון.** ר"ל באו להלחם בחשבון כי משללה תבנה ותכונן עיר סיחון כי אש יצאה מחשבון וגו'. יתכן שקשרו אנשים מחשבון על מלכם כמו שכתב החכם אבן עזרא והם שלחו לסיחון ולעמו באו חשבון כי בתחבולותיהם הכניסום שם והנה הלהבה שיצאת מקרית סיחון הוא סיחון וחילו והם השחיתו ער שהוא למואב והשחיתו האנשים שהיו שרי הבמות הבצורות שבארנון וזה הוראה שלא כבשו ארנון אך המיתו שריה הנלחמים בהם לעזור למלך מואב ואפשר ג"כ שלא לקחו ער ולזה קראו ער מואב אך המיתו אנשי העיר במלחמה בצאתם להלחם לשמור חשבון שלא יקחוהו סיחון וכן דעת אונקלוס:
@765 **עם כמוש.** כמוש היה שם אלהי מואב ר"ל העד שלהם כאמרו אשר יורישך כמוש אלהיך אותו תירש ולזה קרא מואב עם כמוש כי הם עובדים זה האליל:
@765 **נתן בניו פלטים.** הם הבורחים מהחרב והנשארים לא נהרגו והרצון בו פליטי חרב:
@765 **בשבית.** ר"ל בשבי:
@766 **ונירם אבד חשבון עד דיבון.** ר"ל שאף על פי שבניו היו פליטי חרב וברחו למלך אמורי ובנותיו היו בשבי בידו הנה לא החיה אותם אך ידינו אותם והשלכנו לאבדם כדרך שאבד עם חשבון בכללו עד דיבון:
@766 **ונשים עד נופח אשר עד מידבא.** הנה השמונו אותם ואמרנום רוצה לומ' המואבים עד נופח שהוא סמוך למידבא או יהיה הרצון בזה השימונו גם כן כל המואבים אשר עד מידבא והוא יותר נכון והנה זכרו הגבולים עד אי זה מהמקומות השחיתום מכל הצדדים והנה אלו הדברים לאות כי אלו המושלים היו מחיל סיחון והנה הנמשך לזה עד סוף הפרשה מבואר.
@774 **ויקץ מואב מפני בני ישראל.** ר"ל שהיה במצוקה גדולה וביראה פן ישחיתוהו ישראל כמו שהשחיתו את האמורי:
@775 **כלחוך השור את ירק השדה.** אמ' זה לפי שהשור הוא רב המזון וכאש' יבא אל עשב השד' יכלנו ויאכלנו בשלמות מזולת שישאיר בו דבר והוצרך להזכיר שבלק בן צפור היה מלך למואב בעת ההיא בעבור מה שרצה להזכיר מדברי בלעם ובלק:
@776 **והנה כסה את עין הארץ.** ר"ל כי לרבוים יכסו את מראה הארץ שלא יוכל איש לראות את הארץ כי היא כלה מכוסה בהם:
@776 **והוא יושב ממולי.** אמר זה לפי שהם היו אז בערבות מואב ושם חנו אצל הירדן מבית הישימות עד אבל השטים כמו שנזכר בפרשת ואלה מסעי:
@777 **לכה נא ארה לי את העם הזה וגו'.** אחשוב כי מפני שהיה בלעם קוסם כאמרו זאת בלעם בן בעור הקוסם הרגו לפי חרב ולזאת הסבה גם כן הביאו לו קסמים הנה היה יודע בקסם העתיד לבא על איש ואיש ביותר שלם שאפשר שתגיע זאת הידיעה לקוסם ולזה נתיחד בזה העניין מבין שאר הקוסמים שבדברים רבים מדבריו נתקיימו ומצד תחבולותיו כאשר היה יודע מצד הקסם שיגיע רע לאיש מה היה מקלל אותו וכאשר היה יודע העת הראוי שיגיע בו לאיש מהטוב היה מברך אותו והיה מביא זה האנשים להאמין כי מבורכיו הם מבורכים ומקולליו הם מקוללים ואפשר עוד שהיה עושה מעשים ממין הנחש והכשוף להזיק למי שירצה ולהועיל למי שירצה כמו שנבאר עם זכירתנו תועלות זאת הפרשה:
@778 **וקסמים בידם.** הם כלים מה יעורר בהם הקוסם כח הדמיון להגיע אליו הקסם וראוי שתדע כי אלו הדברים הנזכרים מזאת הפרשה מבלעים הם נבואות לא קסמים וזה יתבאר במה שבארנו מסגולות הקסם והנבואה ומה שיוכר בו אחד אחד מהם בב' מספר מ"י ואחשוב כי ה' ית' השיבו נביא בזה הזמן בעבור עוצם השגחתו על ישראל כי היה ראוי שתשמרהו זאת המעלה מנתינת העצה להכשיל ישראל בדברים מגונים כמו הזמה וע"ז ועם כל זה לא נשמר מזה כי הוא נתן עצה למואבים להפקיר בנותיהם לזנות עם ישר' כדי שיפתו אותם לעבוד ע"ז כמו שנתבאר בפרשת ראשי המטות אמר הן הנה היו לבני ישראל למסור מעל ביי' על דבר פעור:
@780 **מי האנשים האלה עמך.** אל על פי שהש' ית' יודע הכל הנה יבואו ממנו השאלות לדבר כלשון בני אדם ולהישיר השופטים שנתיישבו בידיעת אמתת הדבר קודם שישפטו בו:
@784 **כי מאן יי' לתתי להלוך עמכם.** לפי שהיה רצון בלעם ללכת שם לא רצה להגיד למלאכי בלק מה שאמר השם ית' לו לא תאור את העם כי ברוך הוא כי חשב שאם היה בלק יודע זה לא היה מוסיף לשלוח לו אך אמר להם כי מאן יי' לתתי להלוך עמכם כאלו אמר כי לא היה רצון ה' למנוע ממנו ההליכה שם אבל מנע ממנו ההליכה עמהם והנה היה חושב בלעם כי אולי בעת אחר יאות השם יתע' להניחו ללכת שם לקוב את העם ולפי שהרגיש בלק בזה רוצני שזה המאמר לא היה מחייב שלא יתרצה ללכת לבלק אבל היה מחייב שלא יתרצה ללכת עם אלו ששלח לו ראשונה חשב כי אולי היה זה לבקשת הכבוד ולזה הוסיף בלק לשלוח שרים רבים במספר ויותר נכבדים מהראשונים ושלח לו בביאור כי כבד יכבדהו מאד כדי שיתרצה עכ"פ לבא ליקוב את העם:
@789 **מלא ביתו.** הרצון בו בית מלא כמו שפירש החכם אבן עזרא כי לא יהיה תועלת לבלעם אם יתן לו בלק פעל מלא הבית כסף וזהב:
@790 **שבו נא בזה גם אתם הלילה.** אמר זה לבאר להם כי לא אמר מה שאמר לשרים הראשונים לבקשה הכבוד כמו שחשב בלק אך אמר זה לפי שאינו יכול לעשות דבר אם לא ימלך בשכינה ואשר יאמר לו השם ית' יעשה ולזה אמר יצטרך לכם גם כן להתעכב פה הלילה כי אז בעת השינה יותר נכון לקבל כח עליון כמו שבארנו בב' מספר מ"י ואז יודיעני ה' מה אעשה:
@791 **אם לקרא לך באו האנשים קום לך אתם.** ר"ל אם הם רוצים לקרא לך שתבא אצל בלק קום לך אתם אך לא תלך שם לקוב את העם כמו ששאל בלק אך את הדבר אשר אדבר אליך אותו תעשה ואמנם אמר לו כך כי תחלה אמר השם ית' לא תלך עמהם לא תאור את העם כי ברוך הוא וחשב בלעם מזה המאמר שהשם ית' מנע ממנו ההליכה עמהם אע"פ שלא יאור את העם ולזה אמר אל שרי מואב כי מאן יי' לתי להלוך עמכם ולזה אמ' לו עתה שאינו מונע ממנו ההליכה אל בלק אך מונע ממנו מה ששאל ממנו לקוב את העם:
@792 **ויקם בלעם בבקר ויחבוש את אתונו.** יש בזה הספור שאלות קשו' מאד הא' איך יתכן שתראה האתון את מלאך יי' והנה לא יראהו מי שאינו נביא כמו שנתבאר שם בסוף דניאל והאנשים אשר היו עמו לא ראו את המראה אבל חרדה גדולה נפלה עליהם ולא תטעה בענין המלאך שנראה למנוח ולאשתו כי הוא היה איש נביא כמו שביארנו שם ואם אמרנו שהש"י עשה זה על דרך המופת הנה ישאל שואל איזה תועלת היה בזה המופת והנה לא היה המכוון מזה אלא שיאמר המלאך לבלעם כי הוא יצא לשטן לו אם תהיה כונתו לקוב את העם ובהיות הענין כן למה לא נראה לו המלאך ראשונה וחרבו שלופה בידו ויגיע מזה התכלית המכוון מהשם ית' בזה ולא נצטרך לחדוש זה המופת הנפלא ר"ל שתראה האתון אל מלאך יי'. ואם אמרנו שזה המלאך היה נביא הנה יפול הספק עדיין לאי זה תועלת הוצרך להתחדש אז על דרך המופת שתדבר האתון עם שלא יוכל לומר מי היה זה הנביא ועוד איך לא ראוהו שרי בלק ולא נערי בלעם כי לא נזכר פה שראוהו אחר זולתי האתון ובלעם אחריה. והוא מבואר שהשם יתעלה לא יחדש המופתים ללא צורך אמר שלמה האלהים עשה שייראו מלפניו והנה דעת רבותינו ז"ל הוא שזה הענין היה כפשוטו ולזה אמרו שפי האתון היה מהדברים שנבראו בין השמשות והנראה בעינינו לפי השרשים האמתיים הנראים מדברי הנביאים ומהעיון שזה הספור היה עניין שקרה לבלעם במראה הנבואה כמו העניין בספור לקיחת הושע גומר בל דבלים ושאר מה שנמשך בספור ההוא אשר הוא בהכרח דבר נראה לו במראה הנבואה לא דבר שקרה והנה נדמה לבלעם בחלומו של נבואה שכבר יה לילה כשבאהו דבר ה' ית' במה שאמר לו אם לקרא לך באו האנשים קום לך אתם ואחר זה נדמה לו בחלומו שהיה בקר ושהוא קם וחשב את אתונו והלך עם שרי מואב כי כן היה הסכמתו אם היה מקיץ לפי שאן מראין לו לאדם אלא מהרהורי לבו ולזה תמצא כי תכונת האדם בחלומו הם מתיחסות לתכונותיו בהקיץ והנה סבב השם יתעלה שיקרה לו בהליכתו מה שהורה לו שלא הסכימו מן השמים שילך שם לתכלית אשר הוא פונה אליו כי היה דעתו עכ"פ להשתדל להזיק לישראל לפי היכולת ולזה ספר שקרה לו זה המקרה כי האתון נטתה מן הדרך והלכה בשדה וכאשר הכה בלעם אותה להטותה הדרך נלחצה אל הקיר ולחצה רגל בלעם אל הקיר ושב להכותה ואחר זה רבצה תחתיו ושב להכותה ונדמה לו בחלומו כאלו פתח השם יתעלה פי האתון ודברה עמו שתי פעמים והוא השיב לה כדבר איש לאיש אחר ואחד נראה לו המלאך ונתבאר לו מדברי המלאך בחלומו שנטיית האתון מן הדרך היתה מפני ראותה מלאך יי' והנה אמר אם רע בעיניך אשובה לי לפי שהיה דומה לו שכבר החזיק בדרך ובא לו הצווי שנית שילך עם האנשים אך לא ידבר רק מה שידבר אליו השם יתעלה וזה כולו היה מהשגחת השם יתע' על ישראל כמו שזכרנו כי זה היה הראוי שיוסיף אימה לבלעם מעבור את פי השם יתע' בהשתדלותו לגרום נזק לישראל והנה מה שאמר אחר זה וילך בלעם עם שרי בלק הוא ענין שהיה בהקיץ ולזה הוצרך להגיד זה כי הראשון היה במראה הנבואה ולולי זה הפירוש לא היה צריך לומר שנית ולך עם שרי מואב:
@793 **ויחר אף יי' כי הולך.** הוא רוצה לומר לפי מה שנתבאר להשם ית' שהוא היה הולך לא לתכלית שיזהר מה שהזהירו השם יתעלה חרה אפו עליו ורצה להראותו דבר מפחד ימנע בעבורו מהשתדל להזיק לישראל:
@793 **לשטן לו.** הוא מענין שטה מעליו ועבור והרצון בו למנעו ממה שהיה מכוין אליו ולהטותו ממנו:
@793 **ושני נעריו עמו.** לפי שממנהגו היה כשהיה הולך היה מוליך עמו שני נעריו נדמה לו כך:
@795 **במשעול הכרמים.** הוא השביל שבין הכרמי' והיו הכרמים ההם מוקפים גדר:
@800 **כי התעללת בי.** ר"ל שעשית כנגדי פעולות קשות כטעם את שר התעללתי במצרים:
@801 **ההסכן הסכנתי.** ההרגל הרגלתי:
@803 **כי ירט הדרך לנגדי.** ר"ל נטה ונתעות הדרך כי אתה רוצה להחטיא כונתי ולנטות מן הדרך אשר צויתי לך:
@804 **אולי נטתה מפני וגומ'.** ר"ל לולא שנטתה מפני כשהייתי מוצא אותך תכף מרוב חרון אפי על הסכמתך זאת הייתי חורג אותך לבדך לא היא כי היא אינה חוטאת בזה והנה בנטותה מפני הצילה אותך מהמות כי שקטה חמתי בין הזמן הזה ואתה הכית אותה על זה שלש פעמים בהצילה אותך הנה בודאי לא היה זה מן הראוי והנה אמר גם אותכה הרגתי כי הוא היה מתרעם על מה שהתעללה בו האתון וכאלו אמר לא הספיק לך מה שהתעללה בך האתון כי יותר קשה ממנו הייתי עושה לך ואמר ואותה החייתי לפי שהיה מפורסם שלא יראה אחד מלאך יי' ויחי'. אמר יעקב אבינו כאשר ראה פנואל כי ראיתי אלהי' פנים אל פנים ותנצל נפשי. ואמ' מנוח מות נמות כי אלהי' ראינו וכאלו אמר שלא די שלא הרגתי אותה אבל הצלתיה מהמות הראוי לה מפני ראותה אותי:
@807 **ויצא בלק לקראתו אל עיר מואב.** הנה יצא עד קצה גבול ארצו לקראת בלעם לכבדו כי כן שלח לו כי כבד אכבדך מאד ולכבודו גם כן זבח בלק בקר וצאן ושלח לבלעם ולשרים אשר אתו:
@812 **ויעלהו במות בעל וירא משם קצה העם.** יש לשאול בכאן שאלה עמוקה והוא שכבר יראה מזה המקום ומה שאמר אחר זה אפס קצהו תראה וכלו לא תראה ומה שאמר וישא בלעם את עיניו וירא את ישראל שוכן לשבטיו שכבר היה מדקדק בלעם שיראה את ישראל כדי שיהיה זה כלי לקוב את ישראל. והנה יפול בזה ספק חזק אי זה רושם היה בראותו ישראל להגיע להם קללה ועונש ואם אמרנו כי אולי בעין הרע היה מגיע היזק למי שיביט בהם מצד איד ארסיי נתך ממנו הנה ידמה כי ממקום רחוק כל כך לא היה אפשר שיגיע הפעלות למובטים מבני האיד הנתך מעין בלעם כי הוא לא יפעל באי זה מרחק הזדמן ועוד איך לא היו נזוקים העומדים לפניו ועוד איזה רושם היה בזה אל שיהיו מבורכים אשר יברכם והנה מצאנו שאמר לו בלק גם קוב לא תקבנו גם ברוך לא תברכנו והנראה בעיני שהוא היה רוצה לראותם כדי שתתבודד מחשבתו בהם ויהיה זה סבה אל שיודע לו מה שראוי שיקרה לחלק חלק מהם מרע או מטוב כי זה מתנאי הנבואה והקסם כמו שבארנו בב' מספר מ"י והנה היה במות בעל מקום גבוה אצל גבול מואב היה יכול בלעם לראות משם קצה העם. ואמר החכם אבן עזרא כי הוא בעל במות ארנון ונכון הוא:
@813 **בנה לי בזה ז' מזבחות והכל לי בזה שבעה פרים ושבעה אילים.** כבר ביארנו בפרשת נח כי העלאת העולה מישרת להגעת הנבואה וכ"ש כאשר נכפל עניינה זה ההכפל הנפלא והנה ספר שבלעם ובלק העלו עולות אך כשהעלו אותן אמר בלעם לבלק שיתיצב על עולתו לשמרה לכבוד השם יתעלה והוא יראה אם תקרה לו נבואה מצד זאת ההישרה שהישיר עצמו אליה:
@815 **וילך שפי.** רוצה לומר שהלך אל מקום גבוה לראות משם ישראל:
@816 **את שבעה המזבחות ערכתי.** ידמה שצוהו השם יתעלה לעשות כן קודם זה כדי להמשיך אליו הנבואה ולזה אמר את שבעת המזבחות ערכתי ולא אמר שבעת מזבחות ערכתי:
@819 **מהררי קדם.** רוצה לומר מהרים מזרחיים:
@819 **לכה ארה לי יעקב.** רוצה לומר ששלח לו שיקלל יעקב והרצון בו בני ישראל כי כבר נקראו יעקב כמו שנקראו ישראל:
@819 **ולכה זועמה ישראל.** רוצה לומר הביא הזעם והקללה על ישראל:
@820 **מה אקוב.** הנה השם יתעלה לא קללהו ומה מועיל קללתי אותו:
@821 **כי מראש צורים אראנו וגומ'.** אמר זה לפי שהוא היה רואה אותם למקום גבוה מאד כמו שאמר וילך שפי והרצון בו כאשר אראנו מראש צורים ומגבעות רמות הנה מצאתי שזה העם ישכון לבדד להיות נבדל משאר האומות וקדוש מהם ולזה לא יתחשב בגוים שיהיה נמנה עם שאר הגוים והיה זה כן כי ההמנות ישיג הדברים מצד מה שהם מסכימים והמשל שלא ימנה המונה סוס והשחרות שנים ולא הסוס והחמור מהצד שהם בו בלתי מסכימים אבל ימנה הסוס והסוס וימנה הסוס והחמור מצד מה שהם בעלי חיים שהם מסכימין בו והמשל שאם ישאל אדם כמה בעלי חיים שם והיה שם סוס וחמור יאמר שנים והנה אמר זה על צד ההפלגה להורות שאין יחס בין ישראל ובין שאר האומות:
@822 **מי מנה עפר יעקב.** ר"ל כי למעלתם והצלחתם ירבו מאד כעפר כאמרו והיה זרעך כעפר הארץ ולזה לא יוכל למנות אותם וגם לא יוכל לספור מספר רובע ישראל. ר"ל הדגל שלכל רוח שהיה בו ג' שבטים:
@822 **תמות נפשי מות ישרים ותהי אחריתי כמוהו.** אמר מורה על טוב הצלחת ישראל לקנות החיים הנצחיים מצד מה שהישירה אותם התורה אל זה מי יתן שתמות נפשי מות ישרים בישראל ותהי אחריתי כמוהו אחרית ישראל לקנות העולם הבא:
@829 **ויאמר לו בלק מה דבר יי'.** אמר לו זה לפי שכבר אמר לו בלעם כי אשר ישים יי' בפי אותו אשמור לדבר:
@830 **קום בלק ושמע.** ר"ל קום ממקומך ובא אלי לשמוע דברי וכן הרצון באמרו האזינה עדי שיתקרב אליו להאזין קולו:
@831 **לא איש אל ויכזב.** הרצון בו למה תחשוב שיסכים עתה השם יתעלה לקללם וכבר גלה דעתו קודם זה שאין רצונו לקללם כאמרו מה אקוב לא קבה אל הנה השם יתעלה אינו במדרגה שיכזב בדבריו כי אין אצלו כי אם אמת ואינו מתחרט גם כן ממה שגמר בלבו לעשותו כי אינו בן אדם שיתנחם האם הוא יתע' אמר לעשות דבר ולא יעשהו או דבר דבר ולא יקימנו.
@832 הנה לקחתי מהשם יתעלה לברך אותם והנה ברך אותם השם יתעלה ולא אשוב אחור הברכה ההיא כי לא אוכל:
@833 **לא הביט און ביעקב ולא ראה עמל בישראל.** ר"ל כאשר לא הביט השם יתעלה עול ועמל בישראל והוא בלכתם בדרכי התורה אז השם אלהיו עמו להשגיח בו ולהפיל לפניו אויביו בתרועה חזקה ומקרים מרעידים והנה זה האלוה שהו' עמם הוא האל המוציא אותם מארץ מצרים באותות ובמופתים לא באמצעות מערכת הכוכבים אך בגבורה חזקה והמשילה לתוקף הראם לדבר כלשון בני אדם והנה העיר בזה על שהצלחות ישראל הם למעלה מהצלחות שאר האומות בי בכל עת שילכו בדרכי השם יתעלה בדרך שלא יראה בהם און ועמל הם מושגחים ממנו בצד שלא תועיל לאויביהם ההצלחה שתהיה להם מפאת הכוכבים כי האל המשגיח בם הוא שליט על הכל ועושה כרצונו מהכל וזה גם כן ממה שימנע מהקוסם ידיעת מה שיתכן שיקרה לישראל מטוב או רע וזה כי הקוסם יעמוד על זה מצד שפע הכוכבים כמו שבארנו בספר מלחמות השם וישראל אינם תחת ממשלת הככבים בעת שהם טובים ולזה אמר כי לא נחש ביעקב ולא קסם בישראל רוצה לומר שאין כח בנחש ובקסם לעמוד על אמתת מה שיתחדש להם לסבה שזכרנו ולזאת הסבה הנה כאשר יאמר ליעקב ולישר' מה פעל אל ר"ל מה גזר לפעול במה שעתיד לא יבאו לידיעת זה מצד הנחש והקסם אבל יודע להם זה מצד הנבואה:
@836 **הן עם כלביא יקום וכארי יתנשא.** ר"ל מצד עוצם השגחת השם יתעלה בהם יקומו בגבורה נפלאה לכלו' אויביהם במהירות כמו הלביא והאריה שלגבורתם יטרפו תמיד ובזריזות גדול כן זה העם לא ישכב עד יאכל טרף ודם חללים ישתה כי השם יתעלה המשגיח בם לא תקצר ידו מעשות כל אשר חפץ והנה בזה המאמר הישיר בלעם את בלק לדעת מאי זה מקום יבא הטוב לישראל ובסבת אי זה דבר ר"ל שזה יהיה להם כשישמרו מחטא ליי' בדרך שלא יראה בהם און ועמל ומזה המקום נתישר בלק לקחת עצה להחטיא ישראל או אפשר שבלעם נתן לו בביאור העצה ההיא ר"ל להפקיר בנות מואב לישראל כדי שיסיתום לטעות אחר ע"ז:
@839 **אולי יישר בעיני האלהים וקבותו לי משם.** ראוי לספק בזה איך אמר זה בלק לבלעם וכבר אמר לו בלעם לא איש אל ויכזב ובן אדם ויתנחם ואיך השיב לו בלעם בנה לי בזה שבעה מזבחו' והנה היה ראוי שישיב לו כי לשוא הוא טור בזה כי אין השם יתע' בן אדם ויתנחם. אלא שהיתר זה הספק אינו ממה שיקשה כי אולי חטאו ישראל אחר זה ויישר בעיני השם יתעלה עם שהוא אפשר ששער בלק על צד הקסם כי מהמקום ההוא נכון לבא רע על ישראל והסכים לו בלעם בזה ואם לא נזכר.
@843 ולפי שכבר ראה בלעם כי טוב בעיני ה' לברך את ישראל לפי שהשגחתו דבקה בהם הנה הלך כפעם בפעם לקראת נחשים ר"ל להשתדל לדעת על צד הנחש מה שיתכן שיקרה לישראל כי אין כח בנחש להודיע זה כמו שהקדים ואמר כי לא נחש ביעקב אך יהיה כח בנחש ובקסם להודיע זה בעת סור ההשגחה מהם ולפי שראה בלעם שהשגחת השם יתעלה דבקה בהם עזב עניין הנחשים ושת אל המדבר פניו לראות ישראל כדי שיעמוד בנבואה על מה שיתכן שיקרה להם מטוב או רע:
@845 **שתום העין.** ר"ל פתוח העין:
@846 **נופל גלוי עינים.** זאת ראיה שאף על פי שהיתה הנבואה מגעת לו בהקיץ היה נופל מרוב ההתבודדות ולא היה בו כח לעמוד על רגליו:
@848 **כנחלים נטיו.** ר"ל נמשכו ממקורותיהם המשך רב עד שנטו במקומות רבים שכל מה שירוצו מימיהם יעמדו אחריהם תחתיהם והוא מעניין נוטה שמים כיריעה:
@848 **כאהלים נטע יי'.** מצאנו נטיעה באהלים כאמרו ויטע אהלי אפדנו והנה רמז בזה אל השמים כאמרו וימתחם כאהל לשב:
@849 **יזל מים מדליו.** אמר זה על צד הפלא וההפלגה לפי שהדולה ממים נובעים הנה המים שבדלי אינם נובעים ולזה יכלו מהדלי ולזה אמר שגם מדליו יזלו מים והרצון בו שבכל אחד מהם תמצא הברכה עד שזרעו יהיה תמיד במים רבים להפרות ולהרבות או יהיה הרצון באמרו מדליו מדליותיו. ר"ל מסעפים וזה יהיה מרוב המים אשר הוא גדל בהם ועצמותיהם יגרם יפרק וישבר העצמות והנה הגרם הוא עצם כאמרו גרמיו במטיל ברזל:
@850 **חציו ימחץ.** ר"ל שכל אחד מחצי השם יתעלה ימחץ אויבי ישראל:
@853 **ברח לך אל מקומך.** לך לך במהירות אל מקומך:
@856 **לכה איעצך אשר יעשה והעם זזה לעמך באחרית הימים.** הנה קרא הודעת העתידות עצה לפי שהתועלת בזאת ההודעה הוא הישרה ללקיחת עצה כדברים טרם בואם וכן הכונה במה שאמר עצות מרחוק. ונדיב נדיבות יעץ. פלא יועץ. כמו שפירשנו בספר ישעיה או יהיה חסר ותהיה הכונה בו איעצך מה תעשה ואודיעך את אשר יעשה העם הזה לעמך באחרית הימים והנה הביאור הראשון הוא היותר נכון לפי מה שאחשוב:
@859 **אראנו ולא עתה.** ר"ל שאחר זמן רב יהיה זה לפי מה שזכר תחלה ממואב לא היה כי אם אחר זה כמו ארבע מאות שנה כי כשנבנה הבית היו ארבע מאות ושמונים שנה מעת צאת בני ישראל מארץ מצרים:
@859 **אשורנו ולא קרוב.** כפל הענין במלות שונות או הוא שב למה שזכר מלך המשיח שיהיה אחר כן זמן ארוך אורך נפלא והוא היותר נכון ולזה שנה לשונו ממה שאמר תחלה ולא עתה כי כבר יצדק על מה שיהיה אחר זמן קרוב שהוא לא עתה ולא יצדק עליו שהוא לא קרוב ולזה הורה אמרו ולא קרוב על מרחק יותר עצום:
@859 **דרך כוכב.** רמז למלך המשיח שיגלו ויראו פעולותיו בקצות הארץ ולזה המשילו לכוכב שהוא נגלה ונראה לכל להורות גם כן על עליונותיו ורוממותו ועוד שכמו שמהכוכב יושפעו פעולות רבות בזה העולם מזולת שיפגש במתפעלים ממנו כן יושפעו מהמשיח פעולות רבות בזולת פגישה כאמרו והכה ארץ בשבט פיו וברוח שפתיו ימית רשע. ולזה אמר דרך להתפשט פעולותיו בקצה הארץ:
@859 **וקם שבט מישראל.** רמז לדוד והנה קראו שבט שיכה בפגישה וכן העניין במלחמת דוד ואמר עליו וקם להורות שפעלותיו במלחמותיו לא יתפשטו בקצות הארץ אבל יעמוד במקומו וילחם בסביבותיו ולפי שאמר לו שיודיעהו מה יעשה העם הזה לעמו באחרית הימים הקדים לזכור תחלה מלחמת דוד על מואב שמדרם בחבל שני חבלים להמית וחבל אחד להיות וידמה שהחבל שהיה להחיות היה באמצע ולזה אמר שהוא הכה פאות מואב ואחר זה זכר במלחמת המשיח על כל הגוים כי הם בני שת כי לו לבדו נתקיים המציאות ונח היה מזרעו.
@859 וטעם **וקרקר כל בני שת** שיהרוס אותם וירמסם כטעם מקרקר קיר:
@860 **והיה אדום ירשה.** ר"ל ע"י דוד כי הוא הכרית כל זכר באדום:
@860 **והיה ירשה שעיר אויביו.** ר"ל אויביו. ר"ל אויבי ישראל והוא אדום שזכר תחלה כי הר שעיר היה לבני אדום כמו שנזכר בפרשת ואלה הדברים:
@860 **וישראל עושה חיל.** רוצה לומר כי בימי דוד ינצחו ישראל כל מי שילחם עמו כמו שנתבאר זה בספר שמואל:
@861 **וירד מיעקב והאביד שריד מעיר.** רוצה לומר מכל עיר מארץ אדום וכן היה בימי דוד שנאמר כי ששה חדשים ישב שם יואב עד הכרית כל זכר באדום והיה אמרו וירד מיעקב רמז לדוד ואפשר עוד שיהיה הרצון באמרו ישראל עושה חיל כי קודם המשח דוד היה ישראל עושה חיל על ידי שאול כאומרו ויעש חיל ויצל את ישראל מיד סוסיהו אך כאשר ימשול דוד הוא יכלה זאת האומ' באופן שיאביד שריד מכל עיר ממנה:
@862 **וירא את עמלק ראשית גוים עמלק.** ר"ל שהוא הראשון שנלחם בישראל:
@862 **ואחריתו עדי אובד.** ע"י שאול:
@863 **וירא את הקני.** הוא היה ממשפחת יתרו והנה היה מושבו סמוך לישראל כמו שנתבאר בספר שופטים ובין ישראל היה יושב והגלהו מלך אשור ונהג אותו בשבי ולאורך ימי שביו אמר זה המאמר הנה מושביך הזק וקנך שמת בסלע שהוא מקום תקיף וכל זה לא יצילך כי יהיה לכליון קין ועד מה אשור תשבך מחנה אשור הנה מאורך השבי ידמה שיהיה התכלית היות קין לכליון או ירצה בזה אם יהיה קין לכליון יותר טוב להם מהיות בזה השבי כל זה הזמן הארוך:
@865 **וישא משלו ויאמר איו מי יחיה משומו.** אלה הדברים על לבו ממלך אשור כי הוא יעשה רעות רבות לגוים רבים:
@866 **וצים מיד כתים.** ידוע כי כתים היו מבני יון כי כן כתוב ובני יון אלישה ותרשיש כתים ודודנים ואמר שממקום כתים יצאו אנשים דומים לחיות מדבריות מצד רוב אכזריותם והם יענו אשור. ויענו העברים אשר שבה מלך אשור:
@866 **וגם הוא עדי אובד.** כמו עמלק ר"ל אשור כי בו היו דבריו:
@868 **וישב ישראל בשטים.** שם היה מושבם כי הוא היה בערבות מואב כו שזכרנו והתחילו תחלה להתפרץ בעריות ומשם נתפתו לאכל בזבח ע"ז והשתחוו לאלהי מואב:
@870 **ויצמד ישראל לבעל פעור.** רוצה לומר נתחבר לעובדי בעל פעור כטעם אמרו ובעל בת אל נכר:
@871 **והוקע אותם ליי' נגד השמש.** הוא בענין אמרו והוקענום ליי' והרצן בזה קח את כל ראשי העם והם השופטים שהיו שרי אלפים ושרי מאות שרי חמשים ושרי עשרות שיעשו אלו המשפטים מהעובדים והוקע את החוטאים ליי' לעיני הקהל כדי שיוסרו השאר וזכר ההוקעה הוא ההריגה והמתה אם בתלייה אם בזולת זה:
@872 **הרגו איש אנשיו הנצמדים לבעל פעור.** ר"ל העוברים אשר תח הנהגתו:
@873 **הנה איש מבני ישראל בא.** הוא היה נשיא שבט שמעון כמו שזכר:
@873 **ויקרב אל אחיו המדינית.** ר"ל שהביאה במחנה ישראל בפרהסיא שהיו רואים זה משה וכל העדה והביאה לאהלו לשכב עמה והיה עושה זה בעת שהיו ישר' מתים במגפת והיו מומתים על ידי השופטים ולזה היו בוכים פתח אהל מועד ונכון הוא מה שאמרו ז"ל שומרי היה מריב עם משה בעובר שלקח בת יתרו והוא מצוה עתה להרוג הנזקק לבת אל נכר ולזה הביא אותה לעיני מש במחנה ישראל:
@874 **וירא פינחס בן אלעזר.** למדנו מזה שהבועל ארמית קנאין פוגעים בו אך בתנאי שיעשה זה בשעת מעשה כמו שמצינו בפנחס שדיקר את שניהם בשעת מעשה באופן שהיה עדות שהוא היה שוכב עמה אז ולזה ספר שבדקרו את איש ישראל דקר עמו האשה בדרך שנכנס הרומח במעיה והנה בזה הפועל נעצרה המגפה מעל בני ישראל וידמה שהמתים בזאת המגפה היו כלם משבט שמעון כי תמצא במספרם בפרשת פינחס שהוא יותר חסר מאד ממה שהיה בפרשת במדב' סיני מאי זה שיהיה משאר השבטים ולזה הסכימו רבותינו ז"ל כי אלו היו כלם משבטו של שמעון. ובכאן נשלם הביאור בזאת הפרשה.
@879 **את בריתי שלום.** ר"ל שכמו ששם שלום בין ישראל ובין השם יתעלה כן יהיה לו בריצת שלום והיתה לו ולזרעו אחריו ברית כהונת עולם. ר"ל שלא תפסק הכהונה ממנו ומזרעו לעולם וזאת הברכה היא להשאיר זרעו תמיד שבזולת זה לא תהיה בכאן ברכה כי כל הבאים מזרע אהרן הם כהנים ואפשר שרמז זה לכהונה גדולה הוא היותר נכון ואמר שתהיה לו להבטיחו שלא ימות קודם אלעזר אביו ויהיה הוא כהן גדול אחרי אביו וזרעו אחריו יהיו כהנים גדולים לא תפסק זאת הכהונה מהם והנה ידענו כי פינחס היה כהן גדול ומזרעו היו כהנים גדולים רבים כמו שנתבאר בספר דברי הימים ואין לספק על זה ממה שמצאנו שהיו כהנים גדולים מבני איתמר וזה כי אלו היעודים הכוללים ומקיפים בכל הזמן יש בהם תנאי בהכרח ולזה אפשר שסר זה היעוד עת מה בסור התנאי כמו שסרה קצת המלכו' מזרע שלמה בן דוד בסור התנאי:
@880 **תחת אשר קנא לאלהיו.** ושמר ישראל מהכליון יהיה לו ברית שלום ותחת אשר כפר על בני ישראל נתן לו ולזרעו שיהיה מכפר על בני ישראל ולזה נתן לו כהנה גדולה כי הכהן הגדול יכפר על בני ישראל פעם אחת בשנה כמו שהתבאר בפרשת אחרי מות.
@881 והנה זכר שהאיש המוכה היה נשיא שבט שמעון והאשה המוכה היתה בת מלך ממלכי מדין כי צור היה שם אחד מהמלכים באמרו את אוי ואת רקם ואת צור להורות על חזק קנאת פנחס לשם יתעלה עד ששם נפשו בכפו להרוג נשיא שבט אחד ובת מלך:
@884 **צרור את המדינים וגו' כי צוררים הם לכם.** צוה השם יתעלה שישנאו ישראל את המדיינים ויכו אותם לפי שהם היו שונאים את ישראל במחשבתם הרעה שהשתדלו להכשיל את ישראל בבנותיהן ובע"ז כדי שיכלם השם יתעלה וזה היה בעצת בלעם עד שכבר נמשכו לזה כלם וגם המלכים אשר שם הפקירו בנותיהם לישראל להכשילם כמו שנתבאר בדברי כזבי ועתה נוספה שנאתם בעבור כזבי שנהרגה שהיתה בת מלך א' ממלכי מדין. ולזה הוא מבואר שאם לא תמהרו להכותם ישתדלו בצדדים אחרים להזיק לישראל ועוד שזאת המלחמה תשלם ע"י משה באופן יותר שלם לכלות את המדינים ממה שיעשה ע"י יהושע לחזק ההבדל שבין משה ליהושע ולזה תמצא בזאת המלחמה מהפלא מה שלא ימצא כמוהו במלחמה אחת ממלחמו' יהושע כי בעם ממעט נצחו תכף עם גדול ורב לא החיו כל נשמה מהזכרים והיו באופן מהרבוי שהיה מספר הנקבות מהטף אשר לא ידעו משכב זכר ל"ב אלף ועם כל זה לא נפקד איש מאנשי המלחמה אשר באו שם ולזה רצה הש' יתע' שתעשה זאת המלחמה קודם שיאסף משה אל עמיו וזה ממה שיורה על עוצם העונש שנענשו ישראל כשלא היתה להם הארץ ירושה ע"י משה רבינו כמו שזכרנו במה שקדם:
@887 **ויהי אחרי המגפה וגומ'.** רצה השם יתעלה שימנו ישראל אחר המגפה מבן עשרים שנה ומעלה לפי שרצה לצוות ע"י משה רבינו איך תחלק הארץ באופן שלא יתחדש אחריו מחלוקת בזה ולזה מנאם והגביל שלאלה הנמנים תחלק הארץ והם הראויים לצאת לצבא והנה נבאר איך יהיה זה במה שיבא בג"ה:
@887 **ויאמר ה' אל משה ואל אלעזר וגו'.** אמר השם יתעלה זה למשה שיאמר אותו לאלעזר והנה היה אלעזר לפה משה במקום אהרן אביו:
@889 **וידבר משה ואלעזר הכהן אום.** הוא כמו עמם וכמוהו דברו לשלום כמו שזכר החכם א"ע:
@890 **מבן עשרים שנה ומעלה כאשר צוה ה' את משה.** ר"ל שאמרו להם למנותם מבן עשרים שנה ומעלה וכן עשו כאשר צוה יי' את משה והכתוב אחז דרך קצרה להיות זה העניין מובן בעצמו:
@890 **ובני ישראל היוצאים מארץ מצרים.** לפי שלא נגזרה מיתה במדבר על יוצאי מצרים כי אם על אשר היו מבן עשרים שנה ומעלה בשנה השנית לצאתם מארץ מצרים וכבר היו אז שם רבים למט' מעשרי' שנה בא להגיד בזה המקו' של מתו אלה במדבר ולזה היו בספורם בזה המקום רבים שהיו מיוצאי מצרים ולזה אמר שימנום עתה ואין לאומ' שיאמר שלא ימנו עתה כי אם הנשארים מיוצאי מצרים שלא היו בני עשרים שנה במספר האחד כי כבר אמר שאו את ראש כל עדת בני ישראל וגו'. ולזה יחוייב שימנום כלם רוצה לומר מה שהיה מהם מבן עשרים שנה ומעלה ואין צורך עוד להאריך בזה:
@891 והנה הגיע מהתועלת בזה המכפ' להודיע שיותר חסר שבטו של שמעון מכל שאר השבטים שחסר מספרן וזה כי שבט שמעון חסר ל"ז אלף ומאה ושלשים על שאר השבטים שחסר מספרן והם ראובן וגד ואפרים ונפתלי לא חסר ממנו כי אם כ"ג אלף ותשע מאות ועשרים וזה הורה שרוב התלונות אשר היו במדבר היו מהאנשים אשר משבטו של שמעון ולזה נפקדה ברכתו בפרש' וזאת הברכה ולזה גם כן אמר יעקב בסודם אל תבא נפשי ובקהלם אל תחד כבודי להתבאר לו שהם היו קנטרנים והגיע עוד מהתועלת בזה המספר השני להודיע שכבר נתקיימה הברכה שבירך יעקב את יוסף לתת לו שכם אחת על אחיו כי ראובן היה בכור ויוסף בכו' וכבר היה נחלת יוסף יותר מנחלת ראובן כמו נחלת שמעון ויותר מזה כמו שאמר אפרים ומנשה כראובן ושמעון יהיה לי וזה כי אלו שנחלקה להם הארץ תמצא במספרם שכבר היה מספר מנשה ואפרים יותר ממספר ראובן ושמעון וזה כי מספר ראובן ושמעון לא היה כי אם שישים וחמשה אל ותשע מאות ושלשים ומספר מנשה ואפרים היו חמשה ושמונים אלף ומאתים ולא היה כן העניין במספר הראשון שנזכר בפרשת מדבר סיני וזה שמספר ראובן ושמעון היה אז מאה אלף וחמשים אלף ושמונה מאות ומספר מנשה ואפרים לא היה אז כי אם ע"ב אלף ות"ש והנה זכר שם בנות צלפחד בעבור מה שספר מענינם אחר זה בענין דיני הנחלות והנה הסכים בקרוב זה המספר השני למספר הראשון לא חסר כי אם אלף ושמונה מאות ועשרים:
@895 **הוא דתן ואבירם קרואי העדה אשר הצו על משה ועל אהרן וגו'.** למדנו בזה שהם היו בזאת המריבה והמחלקת כמו התחלה ושרש יותר מקרח ולזה אמ' ותבלע אותם ואת קרח להעיר שהם היו הסבה הראשונה והם סבבו השחתת החמשים ומאתים איש ואולם הקדים קרח בפרש' קרח למעלתו ולזה תמצא שדתן ואבירם מתו הם וכל אשר להן ואין העניין כן בקרח כי בניו לא מתו כמו שספר בזאת הפרש' והער שמהם היו משוררי' רבים בימי דוד וידמה שהם היו במקום בעינו שהיה קרח כשפתחה הארץ את פיה ונתבצר ונתחזק המקום אשר תחת כפות רגליהם בדרך שלא בלעה אותם הארץ לזה הוצרך לומר ובני קרח לא מתו כי היו במקום שהיו ראויים מות ולזה אמרו רז"ל מקום נתבצר להם בגיהנם כי המקומות הנפתחי' בזה האופן שנפתחה הארץ בעת היותה פתוחה יקראו גיהנם או גיא בן הנום:
@896 **ויהיו לנס.** רוצה לומר שהיו לאות ולזכרון לבני ישראל להזהירם שלא יקרב איש אשר לא מזרע אהרן הוא לעבודת המקדש.
@939 **לאלה תחלק הארץ.** ר"ל לאלו הנמנים והנה לא זכר פקודי לוי כי אם אחר המאמר הזה כי כבר ביאר במה שקדם כי שבט לוי לא ינחל נחלה בתוך בני ישראל ולזה אמר לאלה להוציא שבט לוי ולהוציא הגרים והעבדים כי אלו לא נמנים כי לא היו מתיחסים לאחד מהשבטים והנמנים היו מיחסים בכללם לשבטים כמו שנתבאר מהדברים אשר בזה המספר:
@939 **במספר שמות.** לא רצתה התורה שימנו הם בעצם אבל ימנו שמותיהם כמו שנזכר בפרשת במדבר סיני וכבר נתבארה הסבה בפרשת כי תשא ובזה האופן גם כן מנאום בזה המקום ואם לא נזכר:
@940 **לרב תרבה נחלתו ולמעט תמעיט נחלתו וגו'.** ירצה לפי מה שאחשוב שכאשר יחלקו בני השבט ביניהם נחלת שבט יותן ממנו לאיש ולאיש לפי פקודיו ואין הרצון שלא ינחלו עמהם הקטנים מכ' שנה שלא נמנו עמהם כי זה דבר בלתי ראוי אך תהיה הנחלה מגעת לאיש מחלק השבט לפי יחס פקודי ביתו לפקודי כל השבט ואחר זה תהיה זאת הנחלה מתחלקת בין כל בני הבית הקטנים מכ' שנה ואש מעשרי' שנה ומעלה כאלו היתה להם זאת הנחלה מאביהם ולזה אמרו רז"ל שהמתי' היו יורשים החיים בזאת הנחלה ולפי שאמר איש לפי פקודיו למדנו שהנקבות אינם נוחלות אבל ינחל האיש ולזה באו בנות צלפחד להתרעם על זה העניין לפני משה:
@941 **אך בגורל יחלק הארץ.** להורות שהחלוקה ההיא גם כן תהיה ע"פ הגורל ואין טענת מנחלת כלב ויהושע שלא היו בגורל לפי שהם היו ע"פ יי' כמו שנזכר שם וענין הגורל אינו כי אם לבאר שזה המוגבל מהשם יתעלה כמו שאמר בחוק יוטל את הגורל ומיי' כל משפטו:
@941 **אך בגורל יחלק הארץ וגו'.** למדנו מזה כי החלוקה שנתחלקה הארץ תחלה לשבטים היתה ע"פ הגורל וכן מצאנו בספר יהושע ויש לשאול איך יתכן שתהיה זאת החלוקה ע"פ הגורל והנה אין החלקים שוים ואם אמרנו שחלקוה תחלה לחלקים שוים ע"פ הגורל לדעת באי זה מקום שתהי' נחלת השבט וכאר ידעו באיזה מקום תהיה נחלת השבט הוסיפו עליהם אם היה רב מספרו או מעט ממנ' אם היה מעט הנה יתחייב מזה שיהיה אפשר שתסור מהשבט כל הנחלה לו בגורל והמשל שאם היה בא הגורל מיששכר ויהודה ודן וזבולון זה אצל זה הנה יכנס כל הגורל החמישי בנחלתן לפי שמספרן היה יותר משליש מספר כל ישראל יותר מחצית ששית שהוא חלק שבט אחד ולזה ידמה שהיה זה כשחקרו על פי הגורל בחלק מה מהארץ לאי זה שבט יהיה והמשיכו לו שם מהארץ לפי הראוי לו לפי פקודי השבט לצדדים אשר ידעום ע"פ הגורל ואחר זה הפילו גורל השני במה שנמשך לנחלת אותו המטה לדעת אי זה שבט ינחילנו והמשיכו לו ג"כ שם ע"פ הגורל הראוי לו לפי פקודי השבט ההוא ולזה אמר בספר יהושע ויהי הגורל הראשון ומה שאמר שם שיחלקו הארץ לשבע' חלקים לא היה שיפילו הגורל בין השבטים הנשארים בחלקי' ההם כי זה יהיה בלתי אפשר אם לא ידעו בתחלה למי יהיה כל חלק וחלק מהם בדרך שיחלקו זה לפי פקודי כל שבט אבל היה העניין להודיע כל חלקי הארץ ההיא כדי שיוכלו להשות החלוקה לפי פקודיהם על פי הגורל ולזה הביאו עמם זכרון הערים אשר בכל חלק וחלק ועמדו על יחסם ויחס קצתם אל קצת ואחר כך חלקוה בגורלות זה אחר זה באופן שזכרנו ולזה כתוב גם כן ויהי הגורל כך:
@942 **על פי הגורל תחלק נחלתו בין רב למעט.** ר"ל שנחלת המטה גם כן חלק בין בני המטה בגורל ולזה גם כן אמר אחר אמרו איש לפי פקודיו יותן נחלתו:
@945 **אשר ילדה אותה ללוי במצרים.** זה אינו מחויי' שלא תהיה הורתה גם כן במצרים כמו שלא יחייב אמרו ויולד ליוסף בארץ מצרים:
@948 **ויהיו פקודיהם שלשה ועשרים אלף כל זכר מבן חדש ומעלה.** מזה המקום יש קצת ראיה כי המתים במדבר לא מתו בזולת עתם ולזה הגביל השם יתע' זמן כלותם עד מ' שנה ולו היה רוצה להמיתם בלא עתם היה ממית אותם במעט זמן אלא שלא היה ענשם דבר דמות כי סופם היה למות גם כן אבל היה ענשם מיתם במדבר שנתעכבו שם ישראל בעבור זה עד מ' שנה ולזאת הסבה תמצא שפקודי בני לוי לא הוסיפו על פקודיהם במספר הראשון כי אם שבע מאות ואף על פי שלא נגזר עליהם שימותו פקודיהם במדבר ובני ישראל עם מות פקודיהם במדבר היה המספר השני מסכים בקרוב למספר הראשון ואין טענה על זה מיהושע וכלב שהיו מן האנשים ההם אשר אפשר שיורה שהשאר מתו על צד העונש וזה כי הם היו מהמרגלים אשר נגזר עליהם שימותו תכף במגפה לפני יי' וכמו שנגזר על אלו שימותו בלא עתם על צד העונש מצד הדבה שהוציאו על הארץ כן נתן השם יתעלה ליהושע וכלב ארך חיים בעבור שלא הסכימו עם המרגלים ונפרדו מעצתם ואפשר שנאמר שקצת מתי מדבר מתו כלא עתם אלא שמעטי המספר היו ולזה האריך השם יתעלה זמן עמידתם במדבר מ' שנה כדי שיהיו על המעט ארש מתו בסוף זה הזמן כמו בני ס' בקרוב:
@954 **אבינו מת במדבר והוא לא היה וגו'.** חשבו שאם היה שם היה ראוי שיענש שלא יהיה מזרעו חלק ונחלה בארץ:
@954 **כי בחטאו מת ובנים לא היו לו.** ר"ל שחטאו היה סבה שמת בלא בנים כי כל עונש ראוי שייוחס אל החטא:
@955 **למה יגרע שם אבינו מתוך משפחתו כי אין לו בן וגו'.** לפי שהמתים היו יורשים החיים בזאת הירושה כמו שזכרנו אמרו כן כי לא היו בזרע צלפחד פקודים וזה יהיה סבה אל שיגרע שמו מתוך משפחתו בזאת הנחלה אם לא תשוב הירושה לאבי אביהן ולזה שאלו להם שתשוב הירושה לאבי אביהן כדרך שתהיינה יורשות ירושת אביהן:
@958 **כן בנות צלפחד דוברות.** דבר ראוי וצודק הן אומרות:
@958 **נתון תתן להם אחוזת נחלה בתוך אחי אביהן.** כאלו אחי אביהן ואביהן יורשים אבי אביהן והוא חפר אלא שזאת הירושה תהיה לאחי אביהן ואביהם לפי הפקודים אשר בהם בזה המספר אשר נמנו בערבו' מואב ואח"כ יחלקו הנחלה ביניהן כראוי לפי מה שזכרנו:
@959 **ואל בני ישראל תדבר לאמר איש כי ימות ובן אין לו וגו'.** לפי שהתחיל על דבר בנות צלפחד לבאר קצת דיני הנחלה רצה להשלים ביאורם וביאר בז שאם שם בן קודם לבת ולזה לא תהיה הבת יורשת בין האחים אך אם אין שם בן הנה תהיה הבת יורשת נחלת אביהן ואם אין לו בת חזרה הנחלה לאביו ולזה מחלקין אותה אחיו מאביו ביניהם וכבר יתבאר שלא תבא הירוש' לאחיו מאמו מאמרו אחר זה לאחי אביו מורה שכבר דקדק שיהיה מהאב ואמר גם כן שאם אין אחים לאביו תנתן נחלתו ליותר קרוב אליו מאביו ממשפחתו ולזה לא יאמר כי אם על משפחת האב כי משפחת האב קרויה לבדה משפחה אמר למשפחותם לבית אבותם ולזה תמצא כי בכל המשפחות שזכרה התורה זכר לבד המשפחות המסתעפות מהאב ואל האב ייחס תמיד שם המשפחה:
@961 **ואם אין לו אחים ונתת' את נחלתו לאחיו אביו.** וזה כי הירושה תשוב לאבי האב וממנו תהיה לבניו הראויים לירשו:
@962 **ואם אין אחים לאביו ונתתם את נחלתו וגו'.** הנה הירושה תשוב לאבי אבי האב וירשו זאת הירושה כל הראויים לירשו וכן בזה הדרך יעלה ממדרג' אחר מדרגה בדרך שתהיה הירושה ליותר קרוב לו ממשפחתו ומזה יתבאר שכמו שהבן יורש האב כן האב יורש את הבן ואם אי אפשר שתשוב הירושה לאב כי אין לו יורש וכבר מת הנה תשוב הירושה לאבי האב וירשו זאת הירושה כל הראויים לירשו כן ימשך בזה הדרך עניין הנחלה לשוב לאבי אבי האב או למעלה ממנו עד שתגיע לקרוב אליו ממשפחתו וראוי שיתבאר מזה שאם שבה הירושה דרך משל לבן בן הבנות ומת בלא יורש חזרה הירושה לאביו וממנו תשוב לבנותיו שהם אחיות המת כי אין לו בן אך אם נשאר לו אח הה תהיה הירושה לאח כמו שנזכר בזה המקו' ואולם אם תירש האם את הבן אם לא הנה יתבאר מזה המקום שאין האם יורשת הבן שאם היתה האם יורשת את הבן הנה ראוי שתשוב הנחלה לאחיו מאמו אם אין לו אחים מאביו והתורה דקדקה בהפך זה ר"ל שלא תצא הנחלה ממשפחת אביו ולזה אמר שאם אין לו אחים תשוב הנחלה לאחי אביו ואול' אם ירש הבן את אמו אם לא הנה זה ממה שיתבאר בג"ה בסוף פרשת אלה מסעי והנה לא נתבאר מן התורה אם הבעל יורש את אשתו אם לא אבל חכמי' תקנו שיהיה הבעל יורש את אשתו:
@965 **כאשר מריתם פי וגומ'.** הנה המרי היה שלא הקדישו השם יתעלה במים לעיני העדה לפי שהם הבינו ממה שאמר להם השם יתעלה ודברתם אל הסלע בזולת כונה שכיון בו השם יתעלה והיה זה סבה אל שלא יקדישוהו במים ההם באופן שהיה רצון השם יתעלה בו:
@967 **יפקוד יי' אלהי הרוחות לכל בשר וגו'.** לפי שהיה שואל ממנו דבר הוא מיוחס אל ההשגחה הפרטית והיא תהיה מצד השכל קראו אלהי הרוחות לכל בשר ר"ל מנהיג הנפשות אשר לכל אחד מהאנשים והנה שאל ממנו שיתן לישראל מנהיג ורועה יצא לפניהם במלחמה ויבא לפניהם ויוציאם כשירצה ויביאם בדרך שתהיה הנהגתם שלמה ויהיו כלם בהסכמה אחת ולא תהיה עדת השם יתעלה כצאן אשר אין להן רועה והנה צוה לו השם יתעלה שיקח את יהושע בן נון וישימהו רועה אל העם:
@969 **איש אשר רוח בו.** ר"ל רוח אלהים כי הוא היה ראוי לנבואה:
@969 **וסמכת את ידך עליו.** להעיר שאליו תתן הגדולה והשררה שיש לך כמו שיסמוך האדם על קרבן להעיר שעליו נתן את חטאיו:
@970 **והעמדת אותו לפני אלעזר הכהן ולפני כל העדה.** כדי שיתפרסם להם שאתה מקים אותו להיות במקומך ולזה גם כן צוהו השם יתעלה שיצוה את יהושע לעיניהם איך יתנהג בהנהגה הזאת:
@971 **ונתת מהדך וגומר.** ר"ל מיופי תכונותיך ועניניך בהנהגה והודם להגיע בה הטוב למונהגים ביותר שלם שאפשר:
@971 **למען ישמעו כל עדת בני ישראל.** ר"ל הנה תצוה אותו לעיניהם ותתן מהודך עליו גם כן לעיני העדה למען ישמעו כל עדת בני ישראל אל דבריו מפני ידיעתם שאתה הקמות אותו תחתך והנה לפני אלעזר יעמד ר"ל על דבר הגדת העתידות:
@972 **ושאל לו במשפט האורי' לפני יי'.** הנה הוצרך לזה יהושע לפי שלא היה כחו בנבואה ככח משה רבינו ע"ה שתגיע לו הנבואה בהקיץ בכל מה שירצה ולזה היה צריך אל שיעזר בשאלותיו באורים ותומים על ידי אלעזר שהיה כהן גדול והיה נושא החשן והאפוד לפני יי' ר"ל אצל בית קדשי הקדשים:
@972 **על פיו יצאו ועל פיו יבאו.** ר"ל על פי יהושע יצאו ויבאו אע"פ שהוא שואל העתידות לאלעזר במשפט האורים והוא מה ששאל משה אשר יוציאם ואשר יביאם:
@972 **הוא וכל בני ישראל אתו.** הוא מה ששאל משה אשר יצא לפניהם ואשר יבא לפניהם כי הוא יצא או יבא וכל בני ישראל יהיו אתו בדרך שיצא לפניהם ויבא לפניהם ובצאתו ובבאו יהיו כל בני ישראל אתו וכל העדה יצאו ויבאו על פיו אף על פי שלא יצא ויבא לפניה' או יהיה הרצון באמרו וכל העדה סנהדרי גדולה כי הם נקראו עדה כמו שביארנו באמרו ואם כל עדת ישראל ישגו או יהיה הרצון באמרו הוא וכל בני ישראל אתו שאלעזר הכהן יצא גם כן על פי יהושע ויבא וכל בני ישראל אתו וכל העדה שהם הסנהדרין כולם יצאו ויבאו ע"פ יהושע כי לו נתנה ההנהגה בזה ואף על פי שהוא שואל במשפט האורים לאלעזר או יהיה אמרו וכל העדה שב לעדה מיוחדת שבישראל שאם יצוה לה לצאת ולבא יחויב לה לשמוע בקולו ואף על פי שלא יצוה זה לכל ישראל והמשל שאם רצ לשלח במלחמה אלף או אלפים או כמה שירצה יחוייבו בם לשמוע בקולו והנה עשה משה כאשר צוהו השם יתע'. ולא היתה עינו צרה בתת שררתו ליהושע בן נון. זה ביאור דברי זאת הפרשה הצריכים אל ביאור.
@976 **צו את בני ישראל ואמרת אליהם את קרבני לחמי וגומר.** לפי שלא הקריבו במדבר עולות כמו שאמר עולת תמיד העשויה בהר סיני הוצרך להזכיר עתה שנית דבר או הקרבנות ועוד כי מפני שהיו הקרבנות מוכנים ומכוונים להגיע הנבואה בצד שיהיה הכהן יותר ראוי אל שיגיד העתידות כשישאלוהו במשפט האורים כמו שביארנו במה שקדם והיו עתה ישראל מאד צריכים אל זה לפי שנבואת משה עומדת לפסק ונבואת יהושע לא תספיק לפי שנבואת יהושע לא תספיק אם לא יעזר לשאלות במשפט האורים לאלעזר הכהן הנה הוצרך להזכיר את דבר הקרבנות ואמר צו את בני ישראל ואמרת אליהם וגו'. להעיר שעליהם המצוה הזאת אעפ"י שהיתה נעשית על יד הכהנים וזה עדות שאלו הקרבנות אשר זכר בזה המקום הם באים משל צבור ואמר את קרבני לחמי כי הלחם הוא הבשר היה כלו קרב לשם יתעלה כי היתה העולה כלה כליל ואמר לאשי ר"ל לקרבני ואמר זה בלשון רבים לפי ששני התמידין אשר היו קרבים ביום אחד הם יחד מעירים בדבר נפלא לא יעיד בה אחד מהן ביחוד כמן ושביארנו בפרשת אתה תצוה ולזה יצטרך בכל יום לפי שהיו זריזים על זה בשניהם ואמרו במועדו הוא להזהיר שיקרבום בכל יום בזמנו הקצוב לכל אחד מהן והוא גם כן ראיה שאפילו בשב יקריבוהו אלא שכבר נתבאר זה בביאור במה שאמר וביום השב שני כבשים וגו'. על עולת התמיד ונסכה והנה ביארנו זאת המצוה בפרשת ואתה תצוה:
@980 **עולת תמיד העשויה בהר סיני.** אמר זה לפי שלא הקריבו עולה במדבר זולתי בהר סיני כמו שכתב החכ' א"ע:
@981 **בקדש הסך נסך שכר לה'.** למדנו מזה המקום שנסוך היין לא יהיה מן היין החדש ולזה אמר שכר שהוא יין ישן ושיערו חכמים כי עד ארבעים יום הוא פסול לעניין זה. ואמנ' אחר זה נקרא שכר כי כבר נתבררו שמריו וזה הביאור הוא מצד הוראת הגדר והנה אמר שיהיה זה הנסוך בקדש להורות שלא יהיה הנסוך הזה במזבח על המערכ' אשר יערכו עליה אברי התמיד עם שהוא מבואר גם כן בצד אחר כי התורה הזהירה שלא לכבות אש המערכה ולזה היה הנסוך בזה המקום כמו שביארנו בפרשת תצוה ובפרשת שלח לך כי התורה ידמה שכונה בה להסיר העפוש והלכלוך מהבית הקדוש ההוא:
@983 **וביום השבת שני כבשי בני שנה תמימים.** הנה דין הקרבתם כדין התמידין בשוה אין הבדל ביניהם אלא שלא יבאו עמהם שני גזירי עצים כי זה לא חייבה התורה אלא בתמיד של שחר ושל בין הערבים כמו שנתב' בפרשת וירא ובפרשת צו ולא חייבה זה בהקרבנות שביניהם כמו שביארנו והנה המוספין היו קרבים בין תמיד של שחר ושל בין הערבי' כי לא היה שם קרבן קרב קודם תמיד של שחר ולא אחר תמיד של בין הערבים כמו שביארנו שם עול' שבת בשבתו למדנו מזה שאם שכחו או נאנסו ולא הקריב עולת שבת זו אי אפשר להם שיקריבו ביום אחר או בשב אחר אך בשבתו לבד:
@984 **על עולת התמיד ונסכה.** זה מרה שעולת התמיד קרבה ראשונה קודם המוספין והנה דבר הנסכין התבאר בפרשת שלח לך:
@985 **ובראשי חדשיכם תקריבו עולה לה' פרים בני בקר שנים וגומ'.** אלו העשר עולות היה מוסיף בראש חדש עם נסכיהם הראוי להם לפי מה שנתבאר בפרשת שלח לך ומעשיהם במעשה התמידי אלא שהם קרבים בין שני התמידין כמו שזכרנו מוסף של שבת:
@988 **זאת עולת חדש בחדשו לחדשי השנה.** מגיד שבכל ר"ח יקריבו כך מן העולות יותר על התמידין ומגיד גם כן שאם לא הקריבם ביום ההוא אין להם תשלומין לא בר"ח ולא יום אחר:
@989 **ושעיר עזים אחת לחטאת לה' על עולת התמיד יעשה ונסכו.** מגיד שאחר עולת התמיד היה מקריב החטאת לפי שהחטאת קודם לעולת כמו שביארנו במה שקדם ואחר כך היה מקריב עולות המוסף והנה מצאנו כי ההשעיר היה בא בצבור לכפר על טומאת מקדש וקדשיו כשעיר הנשחט של יום הכפורים שהיה חטאת. ומצאנו גם כן בשעירי הרגלים שנאמר בהם ושעיר עזים אחד חטאת לכפר עליהם ולזה למדנו שכלם באים לכפר על הטמאה ומהם נלמד ששעיר של ר"ח בא גם כן לכפר על הטמאה והו' מבואר שיחוייב מזה ששעירי הרגלי' מכפרים מהטומאה מה שלא יוכל שעיר ר"ל לכפר ולזה יצטרך ג"כ להקריב שניהם בר"ח ושעיר של יום הכפורי' מכפר מהטומאה מה שלא יוכלו שעירי הרגלים לכפר. והנה הוצרכה התורה אל זה לפי שכבר סדרה התורה לסוג מה משגגת טומאת מקדש וקדשיו קרבן עולה ויורד כמו שביארנו בפרשת ויקרא ולפי שנשארו שם סוגים אחרים לא יכפר עליהם זה הקרבן הנה סדרה התורה אלו החטאות של צבור לכפר על הטומאות ההם בהדרגה והנה אחשוב שאמר בשעיר של ר"ח לחטאת ליי' ובשעירי הרגלים נאמר ושעיר חטאת אחד לכפר עליכם לפי שהוא בא לכפר על הטמאה שלא היתה בה ידיעה כלל לבעלים והוא ידועה לשם לבדו ולזה אמרו שהוא בא לכפר על קבר התהום שאין בו ידיעה לא בתחלה ולא בסף ובשעירי הרגלים אמר לכפר עליכם כי הוא מכפר על שגגת מקדש וקדשיו שהיתה בה ידיעה מה ושעיר של יום הכיפורים מכפר אפיו על הזדון:
@990 **ובחדש הראשון.** כבר התבאר אופן מעש הפסח בארבעה עשר לחדש ניסן במה שקדם והתבארו גם כן דיני החגיגה ודין אכילת המצות בז ההרגל והמלאכות האסורות בראשון ושביעי של פסח והמותרות והם המלאכות שהם לצורך אוכל נפש ואולם המוסף הנעשה בכל יום מימי הרגל הזה לא נתבאר במה שקדם אך אמר בכללות בפרשת אמור אל הכהנים על דבר המוסף הזה והקרבתם אשה ליי' שבעת ימים ובמקום הזה ביאר עניין זה האשה והוא שוה למוסף ר"ח וזה ממה שיחזק שיהיו אלו השעירים באים על דברי מתיחסים כמו שזכרנו והנה יתבאר ממה שאמר בזה המקום שבעת ימים מצות יאכל שאכילת המצה שבעת ימים רשות אך הרצון בו שמה שיאכל מלחם יהיה מצה ואין שם חיוב באכילת מצה כי אם בלילה הראשונה כמו שביארנו בפרשת בא אל פרעה. וראוי שתדע שמה שהקפידה התורה במניין אלו העולות במוספי' אינו לעכב אך על צד היותר טוב כמו שנבאר בג"ה בזכרון תועלת אלו המוספין. ולזה אם לא מצאו אלא פרים יקריבו פרים לא מצאו אלא איל יקריבו איל לא מצאו אלא בשים יקריבו שבעה כבשים לא מצאו שבעה יקריבו מה שמצאו שנאמר בפרשת אמור אל הכהנים והקרבתם אשה ליי' שבעת ימים לא הקפידה התורה אלא שיקרבו אשה ואמר בזה המקום שבעת ימים לחם אשה ואמר על עולת התמיד יעשה ונסכו מגיד שא לא מצאו אלא אחד מאלו העשרה יקריבוהו וכן אמר במוסף ר"ח ובמסוף השבת נאמר על עולת התמיד ונסכה מגיד אם לא מצאו אלא כבש אחד מקריבים אותו:
@1000 **ובים הבכורים בהקריבכם מנחה חדשה ליי'.** למדנו שהיא הראשונה לכל המנחות הבאות מן החדש ואף עלפי שהעומד מתיר את החרש להדיוט לא הותר לגבוה לכתחלה עד הקרבת זאת המנחה אלא שאם הביא לא פסל כיון שקרב העומר שהרי קרא הכתוב מנחת העומר מנחת בכורים בפרשת ויקרא אלא שהוא ראוי שימתינו למנחות הבאות מהחטים עם שתי לחם של עצרת ולזה קראה הכתוב מנחה חדשה:
@1005 **תמימים יהיו לכם ונסכיהם.** למדנו מזה שהנסכים צריך שיהיו תמימים. ורואי שתדע שזה המוסף הנזכר בזה המקו' הוא זולת הנזכר בפרשת אמור אל הכהנים כי הוא היה קרב על הלחם כמו שנזכר שם והעד כי שם צוה להקריב פר אחד ואלים שנים ושבעה כבשים בני שנה לעולה ושעיר עזים אחד לחטאת. ובזה המקום צוה שני פרים ואיל אחד ושבע כבשים לעולה ולזה יהיו קרבים ביום הזה לעולה ארבעה עשר כבשים ושלשה פרים ושלשה אלים ושני שעירי עזים לחטאת ולפי שהיו בכאן שני מוספין אמר ונסכיהם וכן העניין במוסף ראש השנה:
@1006 **ובחדש השביעי באחד לחדש וגומ'.** כבר התבארו דיני היום הזה במה שקדם לו נתחדש בו בזה המקום אלא המוספין וכבר נתבאר עניין מוסף ראש חדש וכמוהו הוא זה המוסף אלא שבזה המוסף לא יהיה כי אם פר אחד ובמוסף ראש חדש יהיו שני פרים:
@1011 **מלבד עולת החדש.** למדנו זה שמוסף ראש חדש קרב קודם מוסף ראש השנה ומזה המקום יש ללמוד כי תדיר ושאינו תדיר תדיר קודם והנה אמר בו בפרשת אמור אל הכהנים והקרבתם אשה ליי' וכן ביום הכפורים ובחג הסכות אמר שם שבעת ימים תקריבו אשה ליי' להגיד שאין זה המספר הנזכר בזה המקום לעכב אלא למצוה ולזה גם כן כתב אלו המוספין בזה המקום ולא זכר אותו במקום אשר זכר הדברים העצמיים באלו הימים להורות שאין זה לעכב אלא למצוה ואולם המעכב הוא מה שנזכר במקומו והוא שיקריבו אשה להשם:
@1012 **ובעשורי לחדש השביעי הזה.** כבר נתבארו דיני הנעשה בזה במה שקדם לא נתחדש בו בזה המקום אלא המוסף והוא שוה למוסף ר"ה הנזכר בזה המקום:
@1016 **מלבד חטאת הכפורים.** למדנו שחטאת הכפורים קודם לזה ולפי שאמר מלבד חטאת הכפורי' ונזכר בפרשת אחרי מות כבר היה בא עם חטאת הכפורים שיה בא מן הצבור איל אחד לעולה והוא הנקרא שם איל העם למדנו שהאיל ההוא הוא איל הנזכר בזה המקום ולזה לא יקריבו בזה המקום כי אם איל אחד לעולה והוא הנקרא שם איל העם למדנו שהאיל ההוא הוא איל הנזכר בזה המקום ולזה לא יקריבו בזה המקום כי אם איל אחד לעולה לא שני אילים:
@1017 **ובחמשה עשר יום לחדש השביעי וגו'.** מצאנו בו בזה חדוש במספר העולות בפרים ובאילים לא בכבשים כי בר"ה ובחג השבועות יעלו גם כן י"ד כבשים אלא ששם היו ג' אילים ובזה המקום ב' אילים ושם היו מהפרים ג' בחג השבועות ובר"ה ב' ובזה המקום מצאנו מהפרים ביום הראשון י"ג ואחר כך מתמעטים והולכים באופן שהיו הפרים ביום שביעי שבע פרים ואולם בשמיני עצרת היה המוסף בשוה כמוספי ר"ה ויום הכפורים הנזכרים בזה המקום והנה נתחדש בכל מוספי חג הסכות שתמצא בהם כמשפטם או כמשפט קודם זכירת החטאת ולזה למדנו מזה שמעשה העולות קודם למעשה החטא כי לא הקפידה התורה בזה בכל אלו הימים לבד ללא ענין ועוד למדנו מזה שמעשה הפרים קודם למעשה האילים ומעשה האילים קודם למעשה הכבשים אף על פי שאינם מעכבים זה את זה כמו שביארנו הנה כשיעשו יעשו בסדר הנזכר בזה המקום:
@1044 **לבד מנדריכם.** זה ביאור מה שצריך בזאת הפרשה.
@1046 **אל ראשי המטות לבני ישראל.** אמר משה זה הדבור לנשיאי' בעבור בני ישראל או שיגידו זה המשפט לבני ישראל כי פעמים היה קורא משה הנשיאי' לבדם כאמרו בפרשת בהעלותך ואם באחת יתקעו ונועדו אליך הנשיאים וזה בחיי היה ראוי בהרבה מהדברים שהיה מדבר משה לבני ישראל כי לא היה ראוי שידבר דבריו לכל העדה גם לא יוכלו כלם לשמוע דבריו ואולם זכר זה בזה המקום לפי שמעצם משפט הנדרי' והשבועות היה שיהיה מסור לראשי המטות שהיו אנשים חכמים וידועים לפי מה שזכר בפרשת יתרו:
@1047 **איש כי ידור נדר ליי'.** הנה עניין הנדר הוא שידור הרי בהמה זו עולה או חרס או מה שאפשר שידור אותו או יהיה זה כשידור אם יהיה כך אעשה כך כמו שמצאנו ביעקב שנדר נדר שאם יהיה מה ששאל מהש"י תהיה האבן ההיא בית אלהים ויתן לש"י מעשר מכל מה שיתן לו או שידור אם יהיה כך יהיה דבר כך אסור לו כמו שנדר ישראל אם נתון תתן את העם הזה בידי והחרמתי את עריהם והנה החרם הוא דבר הנדור כמו שנתבאר בפרשת בחקותי וכן אמר יפתח והעליתיו עולה ליי' כי העולה היא דבר הנדור והוא מה שאפשר שידוע אותו האדם והנה כבר נת ואשה כי תדור נדר ליי' ואסרה בארו דיני אלו הנדרים במה שקדם ויש עוד מין מהנדרים הם לאסור אסר על נפש הנודר כמו שאמר בזה המקום לאסור אסר על נפשו. ואשה כי תדור נדר ליי' ואסרה אסר. וזה הנדר אינו נדר שיהיה עצם הדבר נדור מצד עצמותו אבל הו נדור לאסרו על נפש הנודר לבד ויורה על זה שהבעל או האב מפירין נדרי האשה בעת שהוא ראוי שיהיו נדריה קיימים לפי שאין זה הנדר בעצם הדבר ולזה אמר לאסור אסר על נפשו והוא מבואר שזה הנדר לא יהיה אלא בדבר שיהיה בו נדר בעצמו' הדבר כי זה הוא מגדר הנדרים והמשל שכמו שאפשר לו לידור שתהיה בהמה זו עולה ותהיה אסורה לו ולכל אדם כן אפשר לו לומ' שהוא עליו כעולה ולזה תהיה אסורה לו לבד וזה ג"כ יהיה בשני פנים כמו העניין בנדרים האמתיים אם שלא יתלה נדרו בדבר אבל יאמר שהדבר ההוא יהיה עליו כעולה או כחרם ומה שידמה לזה אם שיאמר אם אעשה כך או יהיה כך הרי הדבר הפלו' אסור עלי כעולה או כחרם ומה שידמה לזה אם שיאמר אם אעשה או יהיה כך הרי הדבר הפלונית אסורה עלי ומה שידמה לה שיהיה נאסר בנדר וכמו שאי אפשר לאדם שידור שיהיה בהמה זו חזיר כי זה בלתי אפשר כן אי אפשר שיאסרה על נפשו כשיאמר הרי הוא עלי כחזיר וזה מבואר מאד כי זה הנדר הוא מאוחר מהנדר אשר יהיה בעצם הדבר והנה אמר ליי' כי הנדרים אשר יאסר בהם הדבר הם ליי' כמו העניין בקרבנות ובחרמות ובהקדשות:
@1047 **או השבע שבועה.** הנה תהיה השבועה גם כן לאסור על נפשו הדבר בשבועה באחד משני מינים הנזכרים האחד הוא שיאמר הנני נשבע ביי' שלא אעשה כך או אעשה כך כי השבועה תחייבהו לקיים זה המאמר והשני הו' שיתלה השבועה בדבר אם אשה כך או יהיה כך אם עשיתי כך או היה כך הרי אני נשבע ביי' שלא אעשה כך או שאעשה כך:
@1047 **לאסור אסר על נפשו.** ר"ל שלא יאסור הדבר כי אם על נפשו וזה יהיה בצד שספרנו. ולפי שאמ' לאסור אסר למדנו שאין הנדר הזה והשבועה הזאת להתיר לעצמו האסור אבל הוא לאסור המותר ולזה הוא מבואר שאם נשבע שלא לקיים את המצוה אין השבועה חלה כי אין זה אסר וגדר אבל הוא פרצת הגדר כאלו נשבע שלא ישב בסכה כי כמו זה אינו לאסור על אסר נפשו אבל הוא לסלק מנפשו חיובה ואולם בנדרים יקרה שיחולו על דבר מצוה והמשל שכבר יתכן שיאסור אדם על עצמו הנאת מצות סוכה עליו כקרבן והנה יחול זה הנדר לפי שאין מתנאי המצוה שיהנה האדם בהם כי כבר ידומה שיקיים המצוה ולא יהיה לו הנאה גופיית ממנה וזה יחולו הנדרים על דבר מצוה מה שאין כן בשבועות והנה זה ג"כ בנדרים כשהיו על דבר מצוה לא יהיה מקיומם עקירת המצוה כי אם במקרה ואמנם השבועות יהיה מקיומם עקירת המצוה בעצם וכמו שהו' מבואר שאם נשבע אדם שיעשה כך אחר נשבע שלא יעשהו 'שאין השבועה השנית חלה עליו כן אי אפשר שתחול השבועה שתהיה לעבור על שבועת סיני:
@1047 **לא יחל דברו.** ר"ל שלא ישיב דבר חולין והרצון בזה שאף על פי שאנחנו רואים בהרבה מהדברים שהאדם עושה אותן קדש בעצמותן שהוא בעצמו יכול להשיבם חולין בפדותו אותם כמו שהתבאר בסוף פרשת בחקותי מעניין מעשר שני וההקדשות והיה זה ממה שיביא לחשוב שכל שכן שיוכל להשיב חולין דבריו בנדרים שאין הדבר בעצמותם קדש אבל הם אסורים לו לבד ולזה הצטרך לבאר שהוא מוזהר מלהשיב דברו חולין אבל יקיים ככל היוצא מפיו ועוד הצטרך לזה מצד אח' והוא שכבר ביאר שיש לבעל להפר נדרי אשו שהם לענות נפש מצד שענוי נפשה נוגע לו ויביא זה לחשוב שכל שכן שיוכל להפר נדרי עצמו ולזה אמרה ורה לא יחל דברו ונתחייב מזה שדברו אינו מחלל אבל דברים אחרים יוכל להשיב חולין כמו שראינו באב שמפר נדרי בתו והבעל נדרי אשתו ובכלל הנה ידמה שלזאת הסבה מסר משה זה המשפט לראשי המטות להורות שהראשים והם החכמי' מחללים דברי זולתם ר"ל שהם יוכלו להשיבם חולין כשרצה זה הנודר כי התורה מנעה ממנו שכאשר רצה לא יוכל להשיב דברו חולין כמו שהיה לו לעשות זה בקצת ההקדשות ומזה יתחייב שכאשר ירצה יוכלו אחרים להשיב דברו חולין אך האב והבעל לא יצטרך להם בחללם דברו שיהיה זה ברצונו ר"ל שיתחרט מהנדר ההוא או השבועה ההיא ולזה אמרו רז"ל שהחכם מתיר את הנדר כי הוא משיב את הדבר חולין ולזה יתבאר שהוא עוקר הנדר מעיקרו ולזה נכלל באמרו לא יחל את דברו שהוא מוזהר שלא יעבור על דבריו ויחללנו אבל יעשה ככל היוצר מפיו ויקיים אותו והוא אמו ככל היוצא מפיו יעשה והנה אמ' איש כי ידור נדר ליי' להוציא את הקטן שאינו איש ואינו בא להוצי' את האשה שהרי ביאר שנדריה קיימי' מה שלא הפרו אותם אביה או בעלה או נדר אלמנה או גרושה הוא קיים אע"פ שיש לה אב ולזה הוא מבואר שמי שהגיע לכלל איש ימי שהגיע לכלל אשה נדריהם קיימים:
@1047 **ככל היוצא מפיו יעשה.** למדנו מזה שאע"פ שגמר בלבו צריך הוציא בשפתיו אבל דברים שבלב אינם דברים ומזה יתבאר עוד שאם הוציא בפיו מה שאינו בלבו אינו כלום כי ממגדר הדבור אשר הנדר אחד ממיניו שיוציא בו בפה מה שמכוין בלב ולפי שהדבור הוא מורה לפי ההסכמה הוא מבואר שאם היתה ההסכמה אצל המון מלות שיורו מהדבר אינם מורות עליו לפי טבע הלשון והוא הנודר אלו המלות בפיו להורות על מה שיורו עליו אצל ההמון הנה יהיה הנדר קיים כאלו אמר זה בלשון מורה בעצמותו לפי טבע הלשון על זה העניין כאלו תאמר שמצד פלגות ההמון יאמרו תמורת מלת שבועה שבואה או שבותה איך שהניחוהו כדומה לזה ואמ' הנשבע אלו המלות להורות בהם עניין שבועה הנה הוא נקשר בזה כאלו יאמ שבועה כי זה יקרא יוצא מפיו מצד הסכמת ההמון על זה ומצד כונת הנשבע שחשב להוציא בפיו מה שכוין בלבו בכמו אלו המלות:
@1048 **ואשה כי תדור נדר ליי'.** להוציא את הקטנה וכבר ביארנו עניין זה הנדר והאסר בפסוק הקודם:
@1048 **בבית אביה בנעוריה.** הנה הרצון באמרו בבית אביה שהוא ברשות אביה שאם היתה ברשו' בעל אין לאביה רשות בה כמו שאמר אחר זה ואם בית אישה נדר והוא מבואר מהעניין בעצמו שאין הכוונה באמרו בבית אביה כשתהיה תוך בית אביה כי אין רושם לבית בזה הענין אבל מה שיש לו רושם בו הוא השולטנות והממשלה שיש לאביה עליה כי זה ראוי שימנעה מלעשו' כל מה שתרצה וכן העניין בשולטנו' הבעל עליה בהיותה תחתיו והנה התנה שתהיה בנעוריה לפי שאח' עבור נעוריה יצאת מרשות אב והוא הזמן הנקרא בגרות והנה למדנו זה מזה המקום והנה ימי נעוריה הם לפי הוראת הגדר מהיותה בת שתים עשרה שנה ויום אחד עד ששה חדשים אחר זה קודם זה היא קטנה ואח' זה היא בוגרת לפי מה שהתבאר בשרשי' הכוללים ותכף שתהיה נערה תקרא אשה כי אז יצאתה מגדר הקטנות:
@1049 **ושמע אביה את נדרה ואסרה אשר אסרה על נפשה.** הנה שמיעת האב את נדרה יהיה באחד משני פנים אם שישמע זה מפיה אם שיודיעוהו אחים כמו שאמ' יעקב לבניו הנה שמעתי כי יש שבר במצרים ולמדנו מאמרו את נדרה שצריך לשמוע נדרה או אסרה קודם שיפר:
@1049 **והחריש לה אביה.** למדנו שאם שתק ולא הפר הנדר או האסר הנה הנדר או האסר קיים אך בתנאי שיהיה שתיקתו לה ר"ל שידע שבתו נדרה או אסרה אסר על נפשה והחריש לה ולא הפר נדרה ואסרה אך אם לא היה שתיקתו לה ר"ל ששמע ענין הנדר אבל לא ידע שבתו נדרה זה הנדר אע"פ שהחריש הנה הוא יכול להפר אחר זה כשידע שבתו היא שנדרה זה הנדר כי בתחלה לא החריש לה:
@1050 **ואם הניא אביה אותה ביום שמעו.** הרצון בהנאה הפרה כמו שיתבא' מאמרו אחר זה יניא אותה והפר את נדרה ועניין ההפרה הוא בטול הנדר והאסר מאז ולהבא מאמרו אח' זה יניא אותה ותופר וידעו כן עניי הצאן השומרי' את דברי. ובכלל הנה הוא מבואר מצד הוראת הנדר מלת ההפרה והנה למדנו מזה שביום שמעו לבד יוכל להפר לא אחר זה ואע"פ שלא שמע הנדר אלא אחר כמה ימים יוכל להפר ביום שמעו והכונה באמרו ביום שמעו מעת לעת כמו שאמר אחר זה מיום אל יום אם הפר אע"פ שאין בתו יודעת הנה אין נדריה ואסריה קיימים:
@1050 **ויי' יסלח לה כי הניא אביה אותה.** לפי שאין הסליחה אלא במקום חטא וידענו שאין חטא לבת אם עברה על דברי נדריה ואסריה אחר שהפר אותה האב לפי שהם מבוטלים וכאלו אינם הנה יחוייב שהרצון יהיה בזה שאם היה שלא תדע הבת בזו ההפרה ועשה כנגד נדרה ואסרה ונתכוונה לעבור על דרה ואסרה הנה יי' יסלח לה על זאת המחשבה אחר שכר הופר נדרה ואסרה וראוי שתדע שההקם יהיה באחד משני פנים אם שיחריש ביום שמעו ואחר זה הוקם מעצמו והנה זה ההקם אין לו היתר כי כבר בא מעצמו והמון השני הוא שיאמר שהוא מקיים את הנדר או את האסר תוך הזמן שהיה לו להפר אותו לפי שזה העניין שהוציא מפיו הוא כמו נדר הנה נשאל עליו לחכם ויתירהו מההקם ואחר זה יוכל להפר נדרי בתו כיון שהוא עדין ביום שמעו ואולם אם הפר אינו נשאל על ההפר כי אין זה נדר ולא מתיחס לנדר אבל הוא בטול נדר והנה ההפרה יתכן שתהיה ע"י שליח כי שלוחו של אדם כמותו בכמו אלו הדברים אשר יסבלו שליחות וזה מבואר מצד הוראת הגדר:
@1051 **ואם היו תהיה לאיש ונדריה עליה.** הוא מבואר מצד הוראת הגדר שהאשה תהיה לאיש מעת שנתארסה והיא גם כן אז בבית אביה כמו שנתבאר בפרש' כי תצא למלחמה שאביה זוכה בקנס שנותן הבעל בהוציאו שם רע עליה למדנו מזה שלא יצאת מרשות אב עד שנשאת ולזה הוא מבואר שאי זה שיהיה מהם יוכל להפר אז את נדרה בעודה נערה ואולם אחר זה לא יוכל להפר נדרה זולת הבעל והנה הרצון באמרו ונדריה עליה שלא נתחדש בהם דבר מצד האב ר"ל שלא נתקיימו ולא הופרו כי אז הם נדריה ואסריה אשר אסרה על נפשה לא אחר שהקומו כי אז אסרוהו אחרים על נפשה וכ"ש שלא יהיה זה אחר שהורו כי אז אינם עליה והנה למדנו מזה שאפי' הדברי' שדרה קודם שנתארסה מפר הבעל ביום שמעו כיון שהחריש לה אביה מיום אל יום באופן שיהיו מקויימים כ"ש בנדרים שנדרה אחר שנתארסה:
@1051 **מבטא שפתיה.** ר"ל שבועה כמו שאמר בשבועה לבטא בשפתים בפרשת ויקרא ולזה אמר אחר זה כל נדר וכל שבועת אסר להורות שמה שאמ' ואסרה אשר אסרה על נפשה ומבטא שפיה אשר אסרה על נפשה הנה הרצון בו שבועה והוצרך לבאר זה כי אולי יחשוב חושב כי בנדר לבד נתנה התורה זה הכח לאב ולבעל לא בשבועה כי היא יותר חמורה והנה הנמשך לזה מבואר ממה שקדם עד אמו ונדר אלמנה וגרושה וראוי שתדע שהרצון בזה באלמנה וגרושה שנתאלמנה או שנתגרשה מן הנישואין ועדיי היא נערה ולזה הוצרך לומר כל אשר אסרה על נפשה יקום עליה כי היה לחושב שיחשב שכיון שהיא נערה עדין תשוב לרשו' האב אע"פ שנתאלמנה או נתגרשה עדיין אני קורא בה בנעוריה בית אביה ולזה הוצרכה התורה לבאר זה ולמדתנו בזה שכיון שיצאת מרשות אב הנה אינה שבה תחת רשותו במיתת הבעל או בגט אבל היא קונה את עצמה באלו הדרכים מהבעל ואולם אם נתאלמנה או נתגרשה מן האירוסין והיא נערה הנה הוא מבואר שעדיין לא יצאתה מרשות האב כי גם בהיותה תחת רשות ארוסה היא עדיין תחת רשות האב להפר נדריה ולקיימם כמו שביארנו אף כי בצאתה מרשות ארוסה וזה ממה שאינו ריך ביאור למעיין בזה הספר וראוי שתדע שהפרת הנדר או השבועה לא יתכן היותו קודם היותם חלים כי אין זה הפר וזה מבואר בעצמו וכן העניין בהיתר החכם הנדר או השבועה כי לא יתכן לחלל הדבר שלא נתקדש:
@1055 **ואם בית אישה נדרה.** ר"ל אחר שנשאת כי אז היא בבית אישה ושאר מה שנמשך לזה מבוא' ממה שקדם עד אמרו כל נדר וכל שבועת אסר לענות נפש והנה הסבה בזה לפי שהנדרים שיש בהם ענוי נפש הנה הבעל נוגע בדבר מפני היותר קניין מקנייניו והיא פוחתת בזה קניין הבעל וטוב לבעל שתהיה אשתו בזולת ענוי נפש כי בצרתה לו צר ומזה יתבא' שכ"ש שיש לבעל להפר נדרים שבינו לבינה כי היא יותר נוגעת בדבר ההא ממה שהוא נוגע בדברים שיש בהם ענוי נפש כאלו תאמר שנדרה שלא תרחץ מטומאתה או שאסרה על נפשה הנאת משכב בעלה וזה מבואר מאד:
@1060 **ואם הפר יפר אותם אחרי שמעו ונשא את עונה.** ר"ל אחר יום שמעו יכריח אותה לבטל נדרה או שיאמר לה שהוא מיפר נדריה ויביא אותה לחשב שנדריה מופרין הנה החטא ההוא הוא עליו:
@1061 **אלה החקים אשר צוה יי' את משה.** שב עתה לזכור בכללות מה שכללה אותו זאת הפרשה.
@1063 **נקום נקמת בני ישראל מאת המדינים.** בעבור שע"י משה תשלם זאת הנקמה באופן יותר שלם רצה הש' ית' שתעשה ע"י עם שכבר היה ראוי למהר זאת הנקמה בעבור הסבה שזכרה בפרש' פנחס והנה רצה הש"י להראו' עוצם השגחתו בישראל שלא ישלחו לצבא כי אם י"ב אלף אלף לכל מטה מהמטות זולת שבט לוי שלא היו יוצאי' לצבא כי לא היה להם חלק בארץ:
@1067 **אותם ואת פנחס.** ר"ל שכבר שלח אותם משה ואת פינחס:
@1067 **וכלי הקדש וחצוצרות התרועה בידו.** אחשוב שוי"ו תיבת וחצוצרו' היא כפה רפה בלשון ישמעאל שיקרה בה שתהיה ללא עניין כמו ואיה וענה ורכב וסוס. והנה הרצון בו שכלי הקדש שהם חצוצרות התרועה היו ברשותו כי בהם יתקעו במלחמות כמו שנזכר בפרשת בהעלותך.
@1069 והנה זכר שהם הרגו כל זכר במדי' והרגו' עם זה חמשה **מלכי מדין** ובלעם עמה' להורות שכבר היה שקול עניין הריגתו לדבר הריגת המלכים וזכר שכבר היו כל נקבה והטף כלו ושבו אותם וגזזו להם הבהמה והמקנה וכל חילם:
@1071 **ואת כל טירותם.** הם הערי' הבצורות המוקפות חומה ויקחו כל השלל ואת כל המלקוח וגו' העיד הכתוב שלא כבש אחד מהם דב מהשלל ומהמלקוח לעצמו אבל הביאו הכל למשה ולאלעזר הכהן ואל כל עדת בני ישראל:
@1075 **ויקצוף משה על פקודי החיל.** לא כעס אלא על הגדולים המנהיגי' כי אין לאחרים אשם לפי שלא יוכלו לעשו' כי אם מה שיצוום מנהיגיהם והנה צוה משה שיהרגו כל זכר בטף כדי שלא ישאר בהם זכרון ושיהרגו הנקבות היודעות משכב זכר והנה ידעו מי הנקבות שלא ידעו משכב זכר מפי הגבור' או היה להם סימן בזה להושיבם על חבית יין והבעולה היה ריחה נודף כמו שאמרו רבותינו זכרונם לברכה והנה אחשוב שהיודעות איש למשכב זכר הן הנבעלות כדרכן כי כן דרך משכב זכר. או יהיה הרצון באמרו כל אשה יודעת איש למשכב זכר כל הראויה ליבעל אף על פי שלא נבעלה כמו שאמרו רבותינו זכרונם לברכה בסיפרי:
@1080 **ואתם חנו מחוץ למחנה שבעת ימים וגו'.** למד הכתוב על הרוגי מדין שמטמאין כמתי ישראל:
@1080 **אתם ושביכם.** לפי שהשבי נכנס בכלל ישראל עשה דינו להטמא בהרוגי מדין כדין ישראל:
@1081 **וכל בגד וכל כלי וגומ'.** רוצה לומר במי נדה להזות עליהם שלישי ושביעי מפני התטמאם באהל לא יטמאו באל אלא כלים או אדם לא קש ותבן כמו שביארנו בפרשת פרה והנה מעשה עזים הוא בהכרח דבר אינו בגד ולא כלי עור ולזה הוא מבואר שאינו דבר נעשה מנוצה של עזי' ולא מהשער ואינו גם כן נאד נעשה מהעור כי הוא כלי עור אך הוא כלי נעשה מקרן העזים והוא אם כלי שיש בו בית קבול כמו שיחתכו הציירים חלק מהקרן ובבית קבול שבו ישימו הצבע או יעשו ממנו כלים פשוטים כמו המסרק ולוחות העששית ומזה המקום למדנו שכן הדין בכלים הנעשים מהטלפים ומעצמות העזים ומה שידמה להם:
@1083 **אך את הזהב.** למד על כל כלי מתכת שמטמאין כמת והוא מבואר שבכלים הכתוב מדבר שהרי זכר אחר כן צד תשמישן ולמה עוד עליהם שצריכין הכשר מפני מה שבלעו מהמזונות האסורים לנו וביאר שכבר יפלוטו מה שבלעו בדמיון שבלעוהו והמשל שהשפוד אשר יבא באש כאשר יצלו בו הנה יעבירוהו באש לפלו' מה שבלע ואם יבא במים כמו הענין ביורות יעביריהו במים רוצה לומר במים הרוחתין כמו שאמר בחטא ואם בכלי נחשת בושלה ומורק ושוטף במים ומה שזכר אך במי נדה יתחטא ר"ל אחר שטבל הכלי:
@1085 **וכבסתם בגדיכם ביום השמיני וטהרתם.** ילמד בזה שטעונים כבוס בגדים ושהבגדים גם כן טמאים טומאת שבעה מפני שנטמא יחד באהל או מפני היותם מחוברים למחובר למת:
@1087 **שא את ראש מלקוח השבי.** כמו שבמעשר ראשון יקחו הכהנים כמו עשירית חלק הלויים כן היה זה הענין בכמו זה היחס בקירוב כי עשירית חלק אחד מן החמשים הוא חלק אחד מחמש מאות ולזה לקחו הלויים חלק אחד מן החמשים מחצי המלקוח ואלעזר לקח חלק אחד מחמש מאות בו והנה היה כחלק היורד אל המלחמה כחלק היושב על הכלים במלקוח וכבזה ולא חלקו הכל בין כל ישראל לפי שהוא אפשר שזכות הבאים לצבא שהיו כלם אנשים כשרים כמו שהעיד אמו ויקחו את כל השלל היה סבה אל שיהיו נעזרים יותר בשם יתעל ממה שיהיו נעזרים בו אם היו באים כלם לצבא כי בחטא אחד מהם יכשלו כלם כמו שזכרנו בפרשת קרח שלא היה השלל כלו לאנשי הצבא לפי שמצד ההשגחה הדבקה לכלל ישראל נעזרו גם כן בזה הפעל ולזה רצה הש' יתעלה שיהיה כחלק היורד אל המלחמה כחלק היושב על הכלים ואפשר שמזה המקום נתיישר דוד לשום זה הענין לחק כמו שנזכר בספר שמואל. והנה האריך לספר מספר כל זה המלקוח ושכבר נתנו ממנו החלק הראוי לכהנים וללויים כמשפט התורה להאריך בכמו אלו הדברים כמו שבארנו הסבה בפרשת נשא עם שמזה המספר תועלת רב לדעת עוצם ההצלחה בזאת המלחמה עד שבמתי מעט נצחו עם רב כזה היו בטירותם ובעריהם עד שכבר היה מספר חטף מהנשי' אשר לא ידעו משכב זכר שנים ושלשים אלף ולא נפקד איש מאנשי הצבא. והנה ספר שראשי אנשי הצבא בראותם עוצם השגחת הש' יתעלה בהם הסכימו לתת כבוד לשם יתעלה מהונם אשר הציל את נפשותם מהמות ולזה נתנו מכלי הזהב השלמים לש"י שרי האלפים ושרי המאות זה השיעור שזכרה אותו התורה והורה עליו שהכלי' ההם היו שלמים מה שאמר בהם כל כלי מעשה ר"ל שהיו ראויים לשמש למה שנעשו לו והנה הושמו הכלים ההם באהל מועד לזכרון לפני יי' למען ידעו הדורות הבאים עוצם ההצלחה שהגיע בזאת מלחמה שלא היה כמוה בשום מלחמה שסופרה בכתוב.
@1116 ואחר זה ספר כי מפני שהיה מקנה לבני גד לבני ראובן התעוררו לשאול ממשה הארץ אשר הכה הש"י לפני עדת בני ישראל כי היא ארץ מקנה לזה בחרו שתהיה הארץ ההיא לנחלתם ולא יעבירם את הירדן.
@1121 ולפי שידע שכונתם היתה שלא יעברו את הירדן להלחם עם הגוים אשר שם כעס עליהם מאד ואמר להם ששאלתם זאת תניא לב העם מעבור הירדן וכבר היה ראוי להם להשמר מזה כי מפני תנואת המרגלים נתאחרו במדבר עד תום כל הדור ההוא ואם עתה יניאו לב העם יתאחרו עוד במדבר וישחתו כי כמה מקרים קשים קרו להם במדבר בקש הש' יתעלה לכלותם עליהם עם היות משה קיים ואף כי אחרי מותו עם שלא היה שם נביא זולת משה יהיה ראוי להעשות על ידו כמו זה המופת הנפלא לכלכל כל העם הזה במדבר:
@1131 והנה ענו בני גד ובני ראובן כי הם יקחו עצה שלא יניאו כזה לב העם וזה שהם יבנו במהירות גדרות צאן למקניהם וערים לטפיהם וישב טפם בערו המבצר מפני יושבי הארץ ובעבור שלא יניא לב העם יחלצו במהירות לצבא בלי שום עצלה לבאר שהן בוטחים בהש' יתעלה שינצחו הגוים אשר שם ולא ישובו אל בתיהם עד התנחל בני ישראל איש נחלתו:
@1135 והסכים משה לדבריהם אם יעשו הדבר הזה והודיעם עוצם חטאם אם לא יקיימו היוצא מפיהם עד הורישו את אויביו מפניו ונכבשה הארץ לפני יי' הנה התנה משה אלו ב' התנאים כי אפשר שיוריש הש' יתעלה את אויביו מפניו והם באים לחלחם עם ישראל ועדין לא תהיה הארץ נכבשת לפני השם עד שלכדו בני ישראל הערים ההם כמו שמצאנו במלחמות יהושע שהוצרכו אחר זה ללכת אל הערים שהיו מהמלכים שהמיתו במלחמה ללכדן והנה היתה כונת משה שתהיה הארץ נכבשת לפני יי' קודם שישובו בני גד ובני ראובן לנחלתם כי לא יהיה מהיושר שיקחו בני גד ובני ראובן לנחלה הארץ נכבשת לישראל ויניחו לישראל הארץ הבלתי נכבשת להם:
@1143 ואמר משה לאלעזר הכהן וליהושע בן נון ולראשי המטות שאם יקיימו בני גד ובני ראובן התנאי הנזכר תהיה להם הארץ ששאלו לאחזה ר"ל שבה ינתן להם חלקם הראוי מכלל ארץ ישראל ואם לא יקיימו זה התנאי לא תהיה להם הארץ הזאת לאחוזה אבל יאחזו בתוך בני ישראל בארץ כנען על פי הגורל ומזה המקום למדנו רוב דיני התנאי השלם איך יהיה המאמר בו שיועל התנאי והנה אחר זה מפני שהתבאר למשה מפי הגבורה שאין ראוי שתגיע כל הארץ אשר מעבר הירדן מזרחה לבני גד ולבני ראובן שם בזאת הנחלה ג"כ חצי שבט מנשה וזכר אחר זה שכבר בנו בני גד ובני ראובן ערי מבצר וגדרות צאן כמו שהתנה למשה מסבות שם ידמה ששנו השמות שהיו להן תחלה כטעם ויסב את שמו צדקיה ותהיה על דרך משל העיר שקראוה חשבון אינה העיר שנקראת כך תחלה. ואפשר שהרצון בו שהסבו להם השמות הראשונים שהיו להם:
@1154 **וילכו בני מכיר בן מנשה גלעדה וילכדוה.** רוצ' לומ' שלכדו קצת עיר הגלעד וידמה שזה היה בעת מלחמות עוג כי כבר כתוב שם ויירשו את ארצו וכן היה אז כבישת יאיר את הוותיהם וכבישת נובח קנת ובנותיה ולזה הסכים משה מפי הגבורה שתחיינה אלו לאשר כבשום בחלק נחלתם. והנה זכר זה הכתו' במכיר בן מנשה קצר מפני זה הבאור בנבח כי סמך על באור מה שנזכר מזה למכיר בן מנשה ולולי היות אלו לנחלה ללוכדיהם לא קרא יאיר לאלו המקומות חוות יאיר ולא קרא נבח המקום נבח בשמו והוא אפשר גם כן אחר שהגיעה להן נחלתן בהר הגלעד מעבר לירדן מזרחה כבשו אלו המקומת סביב נחלתם כמו שמצאנו בספור יהושע שאמר יהושע לבני יוסף אם עם רב אתה עלה לך היערה בראת לך שם בארץ הפריזי והרפאים כי אין לך הר אפרים למדנו מזה שמה שיכבשו סביב נחלתם הוא שלהם וכל שכן בזה המקום שכבר הגיע בכללות מה שמעבר הירדן מזרחה לשני השבטים וחצי השבט והנה בכאן נשלם מה שצריך לבאר בזאת הפרשה.
@1161 **ומצרים מקברים וגומר.** זכר זה שאף על פי שהמצרים היו מקברים את בכוריהם כי אין בית אשר אין שם מת והיו יודעים שכבר קרה להם זה בסבת ישראל הנה עם כל זה היה מעוצם השגחת השם יתעלה עליהן שנתן את חן העם בעיני מצרים וישאילום והיו יוצאים לעיניהם ביד רמה:
@1166 **ובאלים שתים עשרה עינות מים ושבעים תמרים וגו'.** הנה לפי מה שאחשוב זכר עניין המצא מים להם בזה האופן לפי שזה הי מהשם יתעלה להראותם כי בהדרגה יגיע להם הטובות לפי השעור שיתקרבו אליו ולזה זכר אל שבתחלה הלכו שלשת ימים במדבר ולא מצאו מים ואחר זה מצאו מי במרה והיו מרים והוצרכה שימתקם השם יתעלה ואחר זה הביאם הש"י במקום שנמצאו להם מים לרוב והיו שם גם כן עצי פרי כי בזה מפיוס לב העם וממשיכתו לעבודת הש"י מה שלא יעלם:
@1171 **ויחנו ברפידים ולא היה שם מים לעם לשתות.** הנה זה ממה שיורה כי בכל המקומות שבאו מעת בואם לאלים מצאו מים וזה היה המקום הראשון שלא מצאו בו מים:
@1197 **וישמע הכנעני מלך ערד וגומ'.** זכר בזה המקום להעיר על שמיתת אהרן היתה סבה מה לזה המקרה כי הוא היה מדקדק מאד בהישרת העם לעבוד' הש"י וכאלו אמרה התורה שמות אהרן היה כמו סבה לזה המקרה הרע לישראל:
@1209 **והורשתם את כל יושבי הארץ מפניכם.** צוה לכלותם כלם פן יחטיאו הנשארים את ישראל כמו שאמר אחר זה ואם לא תורישו את יושבי הארץ מפניכם וגומ' וכן היה כמו שנתבאר בספר שופטים כי זה היה סבה אל שעבדו ישראל אלהי הגוים ההם ולזה היה נופלים בידיהם תמיד כמו שנזכר שם:
@1209 **ואבדתם את משכיותם.** צוה לאבד צלמי תועבות הגוים ההם והמקומות אשר היו עובדים שם עבודה זרה רוצה לומר הבמות והמשכיות כדי שלא יטעו ישראל אחר עובדת זרה ולזה רצה שלא יהנו מאלו הדברים כלל כי אולי יהיה סבה להטעותם אחר עובדה זרה כמו שזכר הרב המורה וזה שאם יתיכו הצלמים ההם ויהנו מהמתכת ההוא דרך משל אולי ינחשו אם תמשך להם אחר זה ברכה מאת הש"י ויאמרו כי העבודה זרה הצליחה אותם כי הרבה מה שינחשו ההמון בכמו אלו הדברים:
@1210 **והורשתם את הארץ וישבתם בה וגו'.** אמר זה כי אולי ייראו ישראל שיהיה טבע הארץ כן שיאבדו יושביה ואולי יתרחקו מפני זה מהחזיק בה ליראתם פן יקרה להם כמו שקרה לאלו ולזה רצה השם יתעלה ישבו ישראל בה כי להם נתנה לירושה ואלו הגוים שנאבדו שהיו מחזיקים נאבדו לזאת הסבה עם שרוע מנהגיהם ורוב חטאיהם סבבו אל שיפלו ביד ישראל:
@1211 **והתנחלתם את הארץ בגורל למשפחותיכם וגומ'.** כבר ביארנו בפרש' פנחס איך היה ענין זה הגורל לשבטי' ומשם יתבאר מה שזכרנו מזה בזה המקום ויהיה הרצון באמ' למשפחותיכם למשפחות הכוללו' והם השבטים או יהיה הרצון באמרו למשפחות הפרטיות כי בני השבט האחד היו חולקים גם כן ביניהם נחלתם על פי הגורל ואחשוב שכבר היה זה כשיחלקו תחלה הנחלה ביניהם למשפחות כוללות על פי הגורל ואחר יחלקו המגיע למשפחה הכוללת למשפחות המיוחדות עד שיגיע בסוף אל היותר מיוחדות:
@1213 **והיה כאשר דמיתי לעשות להם כן אעשה לכם.** אין הרצון בזה שיכלה ישראל בכללות שידמה לכלות הגוים ההם כי כבר זכר בפרשת אם בחקותי שכבר יזכור להם השם יתעלה ברית האבות ולזה לא יכלם אך הרצון בזה שכבר יגלם מעל אדמתם כמו שדמה לעשות באלו הגוים כי אם היו רוצים לברוח ולהניח להם ארצם לא היו הורגים אותם כמו שיתבאר במה שיבא.
@1215 **צו את בני ישראל ואמרת אליהם כי אתם באים וגומר.** הה הגביל יי' על יד משה באופן של הארץ אשר השתדלו בכבישתה כדי שלא יניחו דבר ממנה שלא ישתדלו בכבישתו ולא יפנו לכבוש זולתה כי אולי לא יהיו נעזרים מהש"י ולזה הגביל להם הש' יתעלה את הארץ היא מפאת דרום ומפאת מערב ומפאת צפון ומפאת מזרח כדי שיכירו בשלמות הארץ אשר רצה הש' יתעלה שישתדלו בכבישתה:
@1220 **תתאו.** תגבילו:
@1223 **והתאויתם.** והגבלתם:
@1224 **ומחה.** ויגיע:
@1226 והנה הגביל לתת זאת הארץ הנגבלת לגבולותיה סביב לשבעת המטות וחצי המטה והגביל האנשים אשר ינחילו לישראל את הארץ ונקבם בשמות והם אלעזר הכהן ויהושע בן נון ונשיאי תשעת המטות וחצי המטה כדי שיהיה הכל מוגבל ומסודר ולא יפול בזה מחלוקת אחר משה עם שכבר הורה זה על אמות הנבואה שלא מת אחד מאלו האנשים הנקובים בשמות קודם הנחלת הארץ הזאת לישראל:
@1244 ואחר זה צוה לישראל לתת ללוים **מנחלת אחוזתם ערים לשבת** לפי שלא נחלו הלויים בארץ אבל על כל פנים אי אפשר להם בזולת ערים ישבו בהם אך לא נצטרכו לשדות וכרמים כי היה להם מעשר ראשון מכל תבואות ישראל ולפי ששם עיר יאמר בסתם על עיר בינוני כי הכפר יקרא עיר קטנה והכרך היא עיר גדולה למדנו מזה שאלו העירות היו בינוניות לא גדולות ולא קטנות:
@1246 ונתן להם סביב הערים למגרש **אלף אמה סביב** והיה מוגבל להם להיות למרעה לבהמתם ולרכושם ולעשות שם כל צרכיהם ואמר לכל חיתם מורה שלצורך חיותם לבד נתן להם המגרש ולזה יתבאר שאין קוברין שם מתיהם כי אין זה העניין לצורך חיותם והגביל לתת להם סביב העיר לרבועו של עולם אלפי' אמה לרוח והנה היה מהם אלף אמה מגרש והם הסמוכים לעיר והשאר היה להם לשדו' וכרמים והנה הגביל התורה שיהיה זה הריוח סביב העיר להם לנוי ולטחול ואחריו היו שדות וכרמים שעור מעט והנה היה זה כלו כלי להרחקת העפושים מן העיר מהם ומבהמתם כי במקומות מן המגרשים יוכלו לקבץ הזבל ויזבלו ממנו השדות והכרמים והנה לא רצתה התורה שיהיה העניין בהפך רוצה לומר שיהיו השדות והכרמים סביב העיר ואחריהם המגרש כי היה טורח להפנות שם ולהולי שם בהמותם עם שכבר יזוקו בזה השדות והכרמים ויהיה כן שיעור השדות והכרמים מעט מזער ולזה הוא מבואר שאין עושין שדה מגרש ולא מגרש שדה ואין להם לשנות דבר מזה כי התורה דקדקה בהגבלתו בזה האופן וכבר העיר בזה באמרו ושדה מגרש עריהם לא ימכר כמו שביארנו בפרשת בהר סיני:
@1248 והנה זכר ששש ערי המקלט אשר יתנו לנוס שמה הרוצח היו ללוים ואמר שעליהם יתנו ללויים מ"ב עיר מגיד שכל ערי הלוים היו קולטין ולזה גם כן כלל אותם אחר זה עם השש ערי המקלט:
@1249 ואמר **כל הערים אשר תתנו ללויים ארבעים ושמונה עיר** להגיד שהם כלם ללויים בדרך אחד:
@1250 וזכר שהשבטים יתנו הערים האלה בשווי הרב ירבה והממעיט ימעיט ולפי היחס יתנו כל אחד מהם בדרך שיהיו כל ערי הלוים ארבעים ושמונה עיר:
@1252 **כי אתם עוברים את הירדן ארצה כנען.** מזה הענין למדנו שהוא אחר ירושה וישיבה כי קודם זה לא יתכן שיהיה להם למקלט הערים אשר הגביל להבדיל מעבר הירדן ימה. וכן מצאנו ביהושע שכבר הובדלו אחר ירושה וישיבה ועוד שכבר הקישם לשלשה הערים אשר הבדיל מעבר הירדן מזרחה שהובדלו אחר ירושה וישיבה:
@1257 **לבני ישראל ולגר בתוככם.** למדנו שהגר והתושב גולה אם הרג ישראל בשגגה והנה התושב הוא העומד בארץ ישראל שכבר קבל שלא לעבוד עבודה זרה עי העובד עבודה זרה לא הותר לנו לשבת בארצינו שנאמר לא ישבו בארצך פן יחטיאו אותך לי:
@1258 **ואם בכלי ברזל הכהו.** רוצה ללומר שכיון להכותו והכהו בכלי ברזל באופן שמת מהמכה ההוא רוצח הוא מות יומת הרוצח. והנה לא התנה בכלי ברזל שיהיה בו כדי להמית כי דרך כלי ברזל בסתם שיש בו כדי להמית:
@1259 **ואם באבן יד.** התנה באבן שיהיה בה מלא יד כי בזולת זה אין בה כדי להמית ועם כל זה התנה אשר ימות בה שאם אין בה כדי להמית ומת אינו חייב מיתה וראוי ג"כ שיתבאר מזה כי מתנאי זה העניין הוא שיהיה המקו' אשר נתכוון בו להכותו בו ראוי שימות בו האדם כשיוכה בו בזה האבן כי כל זה נכלל באמרו אשר ימות בה:
@1260 **או בכלי עץ יד וגומר.** למדנו מזה שאעפ"י שאין מדרך העץ להמית כמו הברזל והאבן הנה אם יש בהם כדי להמית במקום שהכהו בו ומת הנה הרוצח חייב מיתה והנה אין מתנאי התחייב הרוצח מיתה שיהיה כי הברזל או העץ שהכה בו כי הכונה הוא שיהיה בו כדי להמית היה שיהיה כלי או שלא יהיה כלי אך דברה התורה בהוה ויור' על זה עצם זה העניין עם שכבר אמר אחר זה או השליך עליו בצריה וימות ולא התנה שיהיה כלי מה שהשליך עליו אפילו היה חתכת ברזל או חתכת עץ ובכלל הנה הוא מבואר מהענין בעצמו כי התורה לא דקדקה אלא שיהיה בו כדי להמית איזה דבר שיהיה שהמיתו בו הוא חייב מיתה:
@1261 **גואל הדם הוא ימית את הרוצח.** מגיד שמצוה ביד הגואל הדם להמיתו אחר שנתברר זה ונגמר הדין שהוא חייב מיתה כמו שאמר אחר זה:
@1262 **ואם בשנאה יהדפנו.** מגיד שאע"פ שלא הכהו אבל דחפו מראש הגג בדרך שיהיה בנפילתו מהמקום ההו' עד המקום שיפול כדי להמית או השליך עליו אי זה דבר בכונה הכותו ולהמיתו ומת והיה בו כדי להמית אעפ"י שאין הרוצח מחזיק בידו מה שהוכה בו הנה הוא חייב מיתה ומצוה ביד גואל הדם להמיתו אחר עמדו לפני העד' למשפטו. וראוי שיתבאר מזה שאם כפתו לפני ארי או סבב מיתתו בזה האופן שאינו חייב מיתה בידי אדם כי כל המשלי' שזכרה התורה כלם מסכימים שההמת' הוא בעצמות מהרוצח:
@1264 **ואם בפתע בלא איבה הדפו וגומ'.** כיון שלא נתכוון להרע לו אע"פ שהמיתו בשוגג והעיד העניין שלא נתכוון לזה כי הוא לא היה לאויב לו ומבקש רעתו הנה יצילוהו עדת הדיינים מגואל הדם וישיבוהו אל עיר מקלטו אשר נס שמה תחלה להמלט מיד גואל הדם אשר שפטם על פי המשפטים האלה ובררם אם הרג שוגג או מזיד.
@1264 וראוי שיתבאר מזה המקום שאם היה שונא לו אעפ"י שהרגו בלא צדיה אינו גולה ואינו גם כן נהרג כי מתנאי הנהרג שיהרג בצדיה וראוי גם כן שיתבאר שאם היה השופט שונא אותו אינו כשר לדין זה כי האויב מבקש רעת שכנגדו כמו שאמר והוא לא אויב לו ולא מבקש רעתו ועוד כי הוא אמר ושפטו והצילו. ולזה מחוייב שיהיה הדיין הראוי לשפוט ולהציל והשונא איננו ראוי שיציל כי לבקשו רעת השונא לא יוכל לראות לו זכות. ואפשר שלזה הענין גם כן סמך אמרו והוא לא אויב לו ולא מבקש רעתו אצל אמרו ושפטו העדה והצילו העדה וכבר יתבאר זה ממה שנזכר בגדר הדיינין בפרשת יתרו ולפי שאמר ושפטו העדה והצילו העדה למדנו שהוא מחוייב שיהיה מספר הדיינים באופן שיוכל להיות שם עדה מצלת ועדה שופטת ולפי שאין מכריעים בדיני נפשות אם לא היו המתחייבים יותר על המבכים שנים כאמרו לא תהיה אחרי רבים לרעות הנה יחוייב שיהיה מספר המחייבים י"ב כשהיה מספר המזכין י' ולזה יהיו הדיינים בזה האופן לפחות כ"ב ולפי שהבית דין אינו ראוי שיהיה שקול כי בהרבה ממחלקותיהם דנין על פי הרוב כמו שאמרה התורה אחרי רבים להטות הנה יחוייב שיהיה כל הפחות כ"ג וזו היא הנקראת סנהדרי קטנה. אמנם סנהדרי גדולה היה מספרם שבעים איש המו שמצאנו במשה שאמר לו השם יתעלה אספה לי שבעים איש מזקני ישראל אשר ידעת וגומ'. והוא יה מופלא שבבית דין והיו שבעים ואחד:
@1266 **ושפטו העדה בין המכה ובין גואל הדם על המשפטים האלה.** ואמר גם כן קודם זה ולא ימות הרוצח עד עמדו לפני העדה למשפט והוא מבואר שזאת העדה הוא עדת הדיינים:
@1267 **והשיבו אותו העדה אל עיר מקלטו אשר נס שמה.** הנה דקדקה התורה להשיבו שם להוציא ממנו שם רע במה שנס שם תחילה כי אולי יחשבו בני העיר ההוא שכבר הרג מזיד ואחרי שובו שם יתברר להם שכבר הרג שוגג:
@1267 **וישב בה עד מות הכהן הגדול וגו'.** אין התנאי שיהיה משוח שהרי אמר אחר זה כי בעיר מקלטו ישב עד מות הכהן הגדול:
@1268 **ואם יצא יצא הרוצח את גבול עיר מקלטו וגומ'.** מגיד שאם יצא חוץ לתחום העיר והוא אלפים אמה שזכר ומצאו שם גואל הדם והרגו אין לו דמי' כי התורה התחכמה להשקיט המיית לב גואל הדם שישב שם עד מות הכהן הגדול כי אז יתנחם גואל הדם על מיתת המת בראותו כי שר וגדול כמו הכהן הגדול מת:
@1270 **ישוב הרוצח אל ארץ אחזתו.** למדו מזה רז"ל שאל ארץ אחזתו הוא שב ואינו שב לשררה שהיה בה והיה זה כן כי התורה אמרה במקומות אחרים ושבתם איש אל אחזתו ואיש אל משפחתו תשובו אך בזה המקום לא אמר אלא שישוב אל ארץ אחזתו מגיד שאינו שב לשררת משפחתו:
@1271 **בכל ארץ מושבותיכם.** ר"ל בין בארץ בין בחוצה לארץ ינהגו דיני הרוצח בזה האופן:
@1272 **כל מכה נפש לפי עדים ירצח את הרוצח.** למדנו מזה שאין הרוצח נהרג אלא ע"פ עדים ולפי שצריך גם כן שיהרוג בצדיה הוא מבואר שצריך התראה כדי שיוכלו העדים להבחין אם הוא שוגג או מזיד וזה כי אע"פ שיראוה פועל פעל הרציחה הנה לא ידעו עדין אם הוא מתכוון להרגו אם לא:
@1272 **ועד אחד לא יענה בנפש למות.** הרצון בו לפי מה שאחשוב הוא שאין הרוצח נהרג ע"פ עד אחד ולפי שהוצרך לומר אחד עם אמרו עד למדנו מזה שכל מקום שאמרה התורה עד סתם רוצה בו עדות שלם והוא שני עדים כי העדות לא יהיה בפחות משנים ואם היה הרצון בזה מה שאמרנו הנה לא יהיה בכאן אזהרה לעד. והנראה יותר שהיה זה המאמר אזהרה לעד שלא יענה בנפש למות וזה אמנם יהיה בלמדו חובה לפני הדיינים על הרוצח כי עדותו כשלא יאמר יותר מהשעור ההוא לא יהיה למות אך הגדת מה שקרה אמנם דבר הדיינין בחתכם הדין כנגד הרוצח הוא למות או בטענם עליו טענת חובת ללמד שהדין נותן שנגמר דינו למיתה ומזה המקום למדנו שיש לעדים ללמד זכות על הרוצח כי התורה לא מנעה להם אלא שלא ילמדו עליו חובה ואל זה הביאור נטו רז"ל בזה הפסוק והנ' היה זה כן כי הדיין צריך שיהיה מצד עצמו שיהי' באופן שיטה לזכות כמו שיטה לחובה ודבר זה בלתי אפשר בעוד שראה פעל הרציחה ולא תקחו כפר לנפש רוצח וגומר. אע"פ שאמר במי שחייב בידי שמים אם כפר יושת עליו ללמד שנותן כפר ומתכפר לו ביאר בזה המקום שמי שהוא רשע למות לא יוקח ממנו והוזהרנו שלא נקחהו ממנו ומזה המקום יש ללמוד שאם אינו חייב מיתה בידי אדם נותן כפר ומתכפר לו כאלו תאמר אם כפתו לפני ארי או שסה בו את הכלב והוא שלא יהיה חייב גלות בעיר מקלט כי אז ג"כ הוהרנו שלא לקחת כפר לפטרו מהגלות והוא אמרו ולא תקחו כופר לנוס אל עיר מקלטו וגו':
@1275 **ולא תחניפו את הארץ וגו'.** ר"ל ולא תרשיעו את אנשי הארץ כי בראות' כי בעד כפר יפטרו מהרציחה יקל להם דבר ההריגה:
@1275 **כי הדם הוא יחניף את הארץ.** ר"ל כי שפיכת הדם ירשיע את עם הארץ בראותם שלא תוקח נקמה ממנו והנה אין דרך שיכופר לארץ עון הדם אשר שופך כי אם בדם שופכו ר"ל כשיהרג על רציחתו ולולא זה יהיה החטא על כל אנשי הארץ וכאלו הזהיר בזה שלא יכבשו העדים עדותם במה שראו מהרציחה ובזה המאמר ביאר גם כן שאם נמצא חלל באדמה וערפו שם את העגלה באופן הנזכר בפרשת שופטים ואחר כך נודע מי הכהו הנה לא כופר לארץ את דבר הדם אם לא בדם שופכו כי אולי יחשוב חושב שתשלם הכפרה עם עריפת העגלה כיון שלא נודע מי הכהו בעת עריפתה:
@1276 **ולא תטמא את הארץ אשר אתם יושבים וגו'.** מגיד שהרציחה מטמא' את הארץ לזה היא גורמת שלא ישכון שם הש' יתעלה אשר השרה שכינתו ודבקה השגחתו בעם עליה ודי זה עונש לכלל העם ולזה ראוי שישתדלו בחזקת היד לבער שופכי הדם הנקי לפי משפטי התורה:
@1277 והנה אחר זה זכר שכבר קרבו ראשי האבות למשפחת בני גלעד בן מכיר בן מנשה על דבר הנחלה שגזר השם יתעלה שתתן לבנות צלפחד באופן שקדם אשר נגרעה מנחלת החולקים עמהם כמו שביארנו והנה בקשו שלא תהיינה לנשים למטה אחד וידמה שכבר רצו בזה שלא תהיינה למשפחה אחרת כי המטה או השבט יאמר על המשפחה וזה שאם היה רצונם שלא ינשאו לזות בני השבט הנה עדיין ישאר התרעומת שהיו מתרעמים והוא שכבר תהיה נחלתם נוספת על נחלת המשפחה ההיא מה שגרע מנחלתן בירושת הארץ כי הם יירשו יחד עמהם כאלו היתה הירושה לחפר ואולם כאשר תהיינה לנשים לבני דודיהן לא תצא נחלת חפר מבניו וכן היה מוסכם מהש' יתעלה כמו ששאלו כהוגן והנה הוגבל זה העניין אז לכל בת יורשת נחלה שתגרע נחלתה מהנחלה הבא' לקרוביה לפי פקודיהם שתהיה לאשה לאחד ממשפחת מטה אביה ולזה לא נהג זה הדין כי אם בעת ההיא כי אחר זה לא יקרה בבת יורשת נחלה שתגרע נחלתם מנחלת היורשים עמה וזה מבואר מאד. ואם יהיה היובל לבני ישראל וגו'. אמר זה כי לא יהיה פלא אם נגרע נחלתן ממשפחת אביהן כי זה יקרה גם בנחלת האדם בעצמו שימכרנה לאחר שאינה משפחתו אלא שהנחלה ההיא תשוב לבעליה ביובל אך זאת לא תשוב ביובל ולזה יתבאר אז שזאת הנחלה היא נגרעת מנחלת משפחת אביהן:
@1283 **ממטה אל מטה אחר.** ר"ל ממשפחה אל משפחה וכן ממטה למטה אחר והעד שהרצון במטה בזה המקום הוא משפחה הוא מה שאמר ותהי נחלתם על מטה משפחת אביהן:
@1289 **אלה המשפטים והמצות וגומ'.** הנה המצות הם מה שצוה אותם לאבד ע"ז ובניינה ועובדיה אשר בארץ כנען ולשבת בארץ ולהתנחל אותה בגורל לגבולותיה אשר הגביל בכל הרוחות ושינחילום הארץ אלעזר הכהן יהושע בן נון ועשרה נשיאים נקובים בשמו' לתשעה המטות וחצי המטה ושיתנו ללוי ערים לשבת ומגרשיהם לפי השיעור שהגבילה התורה והבדלת ו' ערי מקלט והנשא כל בת יורשת נחלה למשפחת מי שנגרע נחלתם מנחלתו ואמנם המשפטים הם משפטי פרשת רוצח באמרו ושפטו העדה וגו' על המשפטים האלה ובכאן נשלם הביאור שיצטרך אל ביאור בזאת הפרשה:

@1 וראוי שנחקור בכאן מספק אחד יפול במה שנזכר בזאת הפרשה והוא מה שנמצא מהאריכות וההכפל במה שנזכר בכאן מזה המספר ומעבודת בני קהת ובני מררי ונאמר שכבר יראה שיהיה זה לשתי סבות האחת כי מפני שקצרה התור' בקצת מקומות האריכה במקומות אחרים הנה זה יביאנו לדעת על מה שקצרה בו אינו מצד שמנהג לשון זה הנביא הוא בקצור כי כבר נמצא שהאריך לשונו בדברים המבוארים ולזה יהיה סבה להעמידנו על כונת המקומות שקצרה התורה בהם ויתבאר לנו מפני זה שזה הוא לעומק הדברים ההם ולזה נפליג בחקירה בהם וכאלו יהיה זה סבה להעמידנו על סודם והסבה השנית כי מפני שחלוף עבודת משפחות הלויים היתה מכוונת זאת הסבה שזכרנו התחיל תחלה לסדר זכרון משפחות הלוי לפי תולדותם ולזה זכר עבודת בני גרשון קודם עבודת בני קהת זכר אחריהם עבודת בני מררי כי תולדותם היו בזה הסדור ואחר זה שב לזכור אותם לפי מעלתם ולזה זכר עבוד' בני קהת ראשונה להורות על חוזק ההבד' שיש בין עבוד' בני קהת ועבוד' בני גרשון הפסיק עוד מפסיק הפרשיות בין עבודת בני קהת ובין עבודת בני גרשון. והנה מה שזכרנו בזאת הפרש' מספיק בזכירת התועלו' המגיעות ממנה.
@177 ואולם התועלות המגיעות מזאת הפרשה הם תשעה:
@177 **התועלת** הראשון הוא במצות והוא לשלח מהמקדש הטמאים על מדרגותיהם ולהזהירם שלא יכנסו שם והנה התועלות באלו המצות מבואר ממה שנזכר בספר ויקרא:
@177 **התועלת** השני הוא במצות והוא מה שנתחדש בזה המקום בעניין גזל הגר כדי להרחיק החמסי' מישראל והמריבה והקטטה כי אולי יקל בעיניהם לעכב בידם ממון הגר כדי שיזכו בדין במותו בשלא היה לו יורש ויתחדש מזה ההפסד והמחלוקת הרבה:
@177 **התועלת** השלישי הוא במצות והוא מה שזכר בדיני סוטה וכבר זכרנו תועלתה ותועלת כל האזהרות אשר באו בה בפרשנו זאת הפרשה:
@177 **התועלת** הרביעי הוא במצות והוא מה שנזכר בפרשת נזיר וכבר זכרנו תועלת' ותועלת כל האזהרו' אשר באו בה בביאורנו דברי זאת הפרשה:
@177 **התועלת** החמישי הוא במצות והוא מה שצוה הכהנים לברך את ישראל בזאת הברכה הנפלאה וכבר ביארנו התועלת המגיע ממנה במה שקדם:
@177 **התועלת** הששי הוא במדות והוא שאין ראוי לאדם שישנה ממנהג חביריו כשהסכימו לעשות פעולה טובה מפורסמת כדי שיוכל להתפאר עליהם או לביישם כשיאמר פלוני עשה כך וכך ופלוני לא עשה אלא כך ולזה ספר בנדבות הנשיאים שהיו שוות לא שנה אחד מהן ממנהג חבריו ולזאת הסבה הסכימה דעתם לדעת הם יתע' בזה:
@177 **התועלת** השביעי הוא במצות והוא מה שצוה בני קהת שישאו הארון בכתף ולא על העגלות לכבוד הארון ולקדושתו:
@177 **התועלת** השמיני הוא במדות והוא להודיע שבדברים אשר יהיה בהם כבוד למי שיהיה קודם אין ראוי לדקדק רק בראשון שיהיה היותר נכבד אך אחריו לא נדקדק אלא לפי מצבם ולזה התחיל נחשון בן עמינדב שהיה נשיא השבט היותר נכבד להקריב קרבנו ואחריו נמשך הענין לפי המצב כדי שלא תפול קנאה ביניהם בזה ולולי זה היה ראוי שיקריב נשיא שבט ראובן אחר נשיא שבט יהודה כי ראובן היה הבכור והיה נופלת קטטה ביניהם מי הוא היותר נכבד שבשבטים ההם ואולם כשנמשך הענין לפי מצבם סר המחלוקת והקנא' כי לא יתבאר בזה שתהיה הקדימה מפני המעלה אבל מפני המצב:
@177 **התועלת** התשיעי הוא לפרסם המופת שהיה בענין הגעת הנבואה שהיה מורגש לישראל שכבוד ה' היה על הכפרת ומשם היתה מגעת הנבואה למשה מבין שני הכרובים וכבר זכרנו התועלת שהיה מגיע מזה:
@336 ואולם התועלות המגיעות מזאת הפרשה הם י"ט:
@336 **התועלת** הראשון הוא ליסד ענין קדושת הלוי' והכפרה עליהם בזה האופן הנפלא קודם שיקרבו לעבודת אהל מועד כי זה ממה שייסד יותר בלבנו יראת המקדש והיה זה גם כן מעיר הלוים לנהוג בעניני אהל מועד בתכלית הקדושה והנה רצה בלוים שיהיו השנים פוסלים בהם מה שאין כן בכהנים לב' סבות האחת כי עבודת הנפסלים לה בהיותה למעלה מנ' שנה היא עובדת משא ולמעלה מנ' שנה אינם ראויין לזאת העבודה וכן לזאת הסבה גם כן אינן ראויין לה עד שלשים שנה כי אין האדם שלם בכח עד היותו בן שלשים שנה וזה מפורסם אמרו רז"ל בן שלשים לכח ועוד שאם לא היו שנים פוסלים בהם לא יתנו מעלה גדולה לנפש לזאת העבודה נכבדת שהיו עוברים באופן שיתנו לה מהמעלה בראותן שאין לוי ראוי עד היותו בן ל' שנה ואולם הכהנים מצד ראותם שהם בלתי יכולים לעבוד עבודתם אם לא בלבשם בגדי כהונה יתנו מעל גדולה בנפש לעבודה הזאת ולא נצטרך בהם שיהיו השנים פוסלין בהם והסבה השנית כי הלוים היו משוררים שיר כמו שהתבאר בעזרא ואין ראוי לכמו זה השיר מי שאינו שלם בדעותיו ולזה נבחר להם הזמן שיאות להם בו השלמות הראוי לזאת העבודה והנה זכר בעבודת הלוים שמירת המקדש כי זה ממה שיתן גדולה ומעלה בנפש למקדש רוצה לומר כשיהיו בו שומרים ושוערים:
@336 **התועלת** השני הוא במצו' והוא מה שלמדנו בזה מעניין פסח שני לאשר נדחו לו מפני טומאה או מפני היותם בדרך רחוקה ביו' י"ד. והנה התועלת בעינו שזכרנו בעניין פסח ראשון:
@336 **התועלת** השלישי הוא לפרסם עוצם נפלאות השם ית' על ידי משה נביאו שתכף שהוקם המשכן כסהו ענן הש' ית' ביום ועמוד אש לילה עד שירצה הש' ית' שיסעו ונסע אז הענן עמהם לנחותם הדרך וכאשר ישכן שם הענן שם יחנו בני ישראל ובזה האופן היו נוסעים וחונים על פי יי' והנה אמר בסוף זה העניין על פי יי' ביד משה לב' סבות האחת כי זה המופת עשה השם יתעלה על ידי משה נביאו והשני כי עם כל זה לא היו נוסעים כי אם על פי משה מפי הגבורה כאשר יצוה לתקוע בחצוצרות במסע המחנות:
@336 **התועלת** הרביעי הוא להודיע שראוי למנהיג לסדר עניניו באופן שכאשר ירצה שיבאו לפניו ראשי העם או העם בכללו יסבב שירגישו יחד בעת אחת כדי שלא תפול קנאה ביניהם אם יקרא קצתם קודם קצת ושיוכלו להרגיש זה תכף שירצה וזה אמנם יהיה בכמו אלו הקולות החזקים שישמעום הרחוקים והקרובים בקריאה אחת במספר ואם היה לו לקרא פעם קצתם ופעם קצת אחר יבדיל בין שני הקריאות בדרך שירגישו הנקראים בזה הקול כי הם נקראים כי בזה מטוב הסדור מה שלא יעלם ולזה זכר שהיו תוקעים בחצוצרות אחת כשהיו קוראים הנשיאים ולא היתה שם תרועה ואולם בקראו כל העם היו תוקעים בשתי חצוצרות ומריעים:
@336 **התועלת** הה' הוא להודיע שראוי למנהיג העם והצבא שתהיינה פעולותיו מסודרות באופן שלא תפול קטטה בין המונהגים מנו ולזה ראוי שיסדר עניין נסעם וחנותם ומי יסע תחלה ומי יסע שני ומי יסע שלישי כי בזה מטוב הסדור וההרחקה מהקטטה מה שלא יעלם:
@336 **התועלת** הו' הוא במצות והוא לקרא השם יתעלה בעת הצרות להנצל מהרעות הנכונו' לבא כי קרוב השם יתע' לקוראיו אשר יקראוהו ולהעיר לבם לשוב לש' ית' בכל לבם צוה שבעת תפילתם על זה והתענותם יתקעו בחצוצרות להעיר לב הנרדמי' באופן שיכנעו לבם וישובו לה' ית' כי זה ממה שיישירם אל שתהיה תפילתם נשמעת ויהיו נזכרים לפני יי':
@336 **התועלת** הז' הוא במצות והוא שיתקעו בחצוצרות על הקרבנות כדי שיתנו הכהנים לבם בדבר הקרבן ויבינו מה שהוא מעיר עליו ולזאת הסבה בעינה היו הלויי' משוררים אז בפה את שיר יי' כמו שנתבאר בעזרא ונמצא בתורה במה שאמר ושרת בשם אלהיו כי השירות בכמו זה השיר השלם הוא שירות בשם יתעלה כמו שאמרו רז"ל וידמה שיהיה זה הענין מצוה אחרת זולת ההרעה בחצוצרות על הצר הצורר ואמנם מה שהיו משתמשים בחצוצרות למקרא העדה ולמסע המחנות היה לפי שעה ושתי אלו המצות האחרונות היו לדורות והנה נפלא מהר"ם ז"ל שמנה כל זה מצוה אחת והנה יתבאר מהעיקרים שזכר בזה שהם שתי מצות ואין זה מקור החקירה בזה אבל החקירה תהיה בג"ה בספר המצות אשר לנו.
@336 **התועלת** הח' הוא שראוי לכל שלם להישיר האנשים אל הטוב כפי היכולת ולזה מצאנו שלא היה מספיק למשה מה שידע מטוב לב חותנו והאמינו ביי' כי היה ירא שאם ישוב לארצו ישאירו בניו באמונת' הנפסד' ולזה בקש משה שישאר יתרו חותנו עמהם כדי שיבואו אליו בניו ויתנהגו כלם לפי משפטי התורה וכדי שיתפייס בזה יותר הבטיחו שיטיבו לו מהטוב אשר ייטיב ה' ית' לישראל ולא שמע יתרו לעצתו כי היה נשען שיעתיק בניו אל האמונה האמתית כמו שנגלה מעניינים לפי מה שספרנו:
@336 **התועלת** הט' הוא לפרסם שהשם יתעל' יודע מחשבות האנשים ושופט אותם על כל נעלם לתת לאיש כדרכיו ולזה ספר שתכף שהיו העם מוצאים תונה רעה להסיר מעליהם עבודת השם יתעלה במה שהיו חושבים כי השם יתעלה לא יראה ולא ישמע אלו הדברים אשר בכאן שמע יי' והגיע להם ממנו עונש נפלא על זה ולפרסם זה העניין נקרא שם המקום ההוא תבערה.
@336 **התועלת** הי' הוא להודיע שראוי להשמר מחבר רע וזה כי בהתחבר ישראל אל האספסוף אשר עלה עמהם נשלו כשנמשכו לחסרונתם והתאוו לאכילת הבשר עמה' עם היות להם הערב שבמזונות בזולת עמל וטורח וזהו אמרו והאספסוף אשר בקרבו התאוו תאוה וישובו ויבכו גם בני ישראל:
@336 **התועלת** הי"א הוא להודיע שאין ראוי לאדם שיהיה רודף אחר התאוות הלא תראה מה שקרה לאלו בעבור רדפם אחר התאוות שמתו מהם רבים ואמנם רצה ה' יתע' למלאת שאלתם להראות לעם כי יד יי' לא תקצר כדי שיתחזק אמונתם בש' ית' ונגלה להם שהביא להם בשר לרוב לחדש ימים כי הממעיט אסף עשרה חמרים והנה לא ענשם הש' יתע' כששאלו בשר ולחם במדבר סין כי אז לא היה להם מן והיה ראוי שיבקשו לחם מזון ואולם עתה שהיה להם המן הורה זה על רדיפת התאוות או שהיתה כוונתם לנסות השם יתעלה אם יוכל לתת להם בשר בכמו זה הרבוי:
@336 **התועלת** הי"ב הוא להודיע שכאשר יביא ההכרח לעשות מופת השתדל השם יתעלה שיהיה בו היותר מעט מן הזרות שאפשר ולזה אמר השם יתעלה למשה שיאסוף מזקני העדה שהם החכמים להגיע להם הנבואה ולזה גם כן רצה שיהיו שוטריו שיהיה להם כח להנהיג העם במנהגים המדיניים להיות עיני אלו הדברים מתנאי הנביא כי האנשים שזה דרכם יתכן יותר בהם שתגיע להם הנבואה ולזה לא היה מהזרות בהגעת הנבואה להם מה שהיה מהזרות בהגעת הנבואה אשר אינם חכמים ואם הוא מבואר שלא היו אלו ראויים לנבואה מצד עצמם לפי מה שנתבאר מזה הספור:
@336 **התועלת** הי"ג הוא להודיע זה המופת הנפלא שהיה בהגעת הנבואה לשבעים זקנים ובנתינת השליו לישראל בזה הרבוי הנפלא כי זה כלו ממה שיישיר לקיום הפנות התוריות:
@336 **התועלת** הי"ד הוא להודיע שהאיש השלם מאד לא יהיה תשוקתיו רק לעבודת השם יתע' ויניח כל העניינים הגופיי' לפי מה שאפשר וכ"ש המשגל שאיננו לאדם במה שהוא אדם ולזה ביאר שמשה פירש מן האשה מצד מה שגנוהו על זה מרים ואהרן ואמרו כי מצד הנבואה לא יצטרך לפרוש ממנה כי גם בהם דבר יי' עם התעסקם בצרכי החומר בעת הראוי:
@336 **התועלת** הט"ו הוא להודיע שראוי לאדם שיתנהג במדת הענוה והשפלות בתכלית מה שאפשר הלא תראה כי משה עם שלמותו הנפלא והיותו מלך ונביא העיד עליו הכתוב שהיה עניו מכל האדם:
@336 **התועלת** הי"ו הוא להודיע שאין ראוי לאדם שיתן אל לבו הדברים אשר ישמע שיאמרו כנגדו ואף על פי שיהיה אדון לאשר יאמרו הדברים נגדו הלא תראה כי משה לא התפעל כלל ממה שאמרו כנגדו מרים ואהרן אבל שתק ולזה סמך לזה העניין אמרו והאיש משה עניו מאד ויתבאר עוד שכבר ידע זה משה ממה שאמר לו אהרן אל נא תשת עלינו חטאת אשר נואלנו ואשר חטאנו:
@336 **התועלת** השבע עשרה הוא להודיע עוצם מעלת משה בנבואה מצד ההבדלים הנפלאי' שזכר השם יתעלה שיש בנבואת משה רבינו:
@336 **התועלת** השמנה עשר' הוא להודיע שאין ראוי לשלם לנקום ולנטור על אשר יעליבהו ולא די לו בזה אבל ראוי שיעזור לאשר דבר כנגדו הלא תראה כי משה רבינו עליו השלום לא די שלא התפעל ממה שהטיחה מרים אחותו מהדברים כנגדו אבל עזר אותה בתפלה כפי היכולת:
@336 **התועלת** התשע עשרה הוא להודיע מה שהשגיח השם יתעלה לכבוד משה שלא רצה שיסעו ישראל מחצרות עד האסף מרים כדי שלא תלך יחידה מחוץ לחנה במסע המחנות וישיגנה גנות רב על זה:
@472 ואולם התועלות המגיעות מזאת הפרשה הם י"א:
@472 **התועלת** הראשון הוא לפרסם שכבר היה ידוע אצל ה' ית' פרי שלוח המרגלים ותכליתו לרע ולזה התחכם השם יתעלה לפי מה שאפשר להציל ישראל מהרע ההוא ומפני זה בחר הנכבדים שבעם להיות מרגלים וזהו אמרו כלם אנשים ראשי בני ישראל המה כמו שביארנו כי השם יתעלה לא יקצר מעשיית הטוב לפי מה שאפשר ולזאת הסבה גם כן קרא משה ליהושע בן נון יהושע כמו שביארנו במה שקדם:
@472 **התועלת** השני הוא להודיע שראוי לאדם שישם בה' מבטחו כ"ש כשנתבארו לו כי הוא עמו במה שהוא רוצה לעשות הלא תראה מה שקרה לישראל מהרע מפני שלא רצו להשען על יעוד השם ית' בירושת הארץ ובחרו לשלוח שם מרגלים עם עוצם הנפלאות שעשה להם השם יתע' אשר היה ראוי שישיגו מהם כי יד ה' ית' לא תקצר מעשות כל אשר יחפוץ:
@472 **התועלת** השלישי הוא לפרסם שהש' ית' רואה כל אלו הדברים ולזה גמל טוב לכלב וליהושע בן נון יען היות כוונתם טובה והיו מן האנשים ההם וראו ירושת הארץ והיתה חברון לכלב כמו שיעד לו לפי מה שנזכר בספר יהושע ולזה גם כן מתו תכף מוציאי דבת הארץ וכל העם שהיה רוצה ה' ית' להביאם שם מתו כלם במדבר מפני שלא בטחו בשם ית':
@472 **התועלת** הרביעי הוא לפרסם רוע לב הדור ההוא שעם מה שהמציא השם יתעל מהסבות ימנעום מלהתנחם בראותם מלחמה מלשוב מצרימה עם כל זה אמרו נתנה ראש ונשובה מצרימה:
@472 **התועלת** החמישי הוא להודיע שהוא ראוי למנהיג השלם שיהיה לו כח לסבול המונהגים ממנו פשעיהם כדי שיובילם אל הטוב הלא תראה כי משה לא די שלא כעס עליהם על מרדם בו ברצותם לתת ראש לשוב למצרים בעוצם הטובות שהשפיע להם השם יתעלה על ידו אבל התחנן להם ונפל על פניו לפנים לבקש מהם בחזקת היד שלא יסבבו הם בעצמם השחתתם על מרדן בשם ית' ולא הספקי לו זה אבל הרבה תחנונים לפני הש' יתע' ישא על פשעיהם עד שנעתר לו השם ית' ונחם על הרעה אשר דבר לעשות לעמו. ר"ל שלא כלה אותם בכללם אבל נשארו בניהם לירש הארץ וגם הם לא מתו יחד:
@472 **התועלת** הששי הוא במצות והוא להודיע שכבר יתחייב שתבא עם העולה והשלמים מנחה ונסכים וכבר זכרנו התועלת המגיע מזה בספר ויקרא:
@472 **התועלת** השביעי הוא להודיע שהגר בהתגיירו ראוי שיקריב ליי' עולה כמו שביאר'. וכבר נתבאר במה שקדם התועלת המגיע מזה והוא כי לא יעלה בדמיון האדם שיתהפך עניינו מלא קדושה לקדושה מזולת דבר גדול נרשם בנפש ולזה הוצרך לגר עניין הטבילה והרצאת קרבן:
@472 **התועלת** השמיני הוא במצות והוא להודיע עניין מצות החלה והתועלת המגיע ממנה הוא תחלה להעיר שכל הטובות באות לנו הש' יתע' וצוה לתת תרומת השם מראשית עריסותנו בארץ ישראל להורות על כי ה' ית' נתן לנו את הארץ ההיא וממנו גם כן ישפע נתינתה פריה. והתועלת השני המגיע ממנה והוא כולל כל מתנות כהונה והוא כי השם יתע' רצה שיהיה לכהנים פנאי לעסוק בתורה ולעמוד על סודותיה כדי שיורו משפטיו ליעקב ותורתו לירא ולזה רצה שיהא לחמם נתן ומימיהם נאמנים:
@472 **התועלת** התשיעי הוא להודיע דין הוראת שגגת בית דין הגדו' בע"ז אשר בהודאה בה יהיה ההתרחק מכל המצות והנה היה בקרבן הכפרה בא פר ושעיר ולא היה בשאר המצות כי אם פר כמו שהתבאר בפרשת ויקרא לפי מה שאחשוב שכבר נסתבכו ישראל בדעות המצרים אשר גדלו עליה' שהיו נותנים האלהות למזל טלה כמו שנתבאר בתורה ואמר ג"כ ולא יזבחו עוד את זבחיהם לשעירים וגו' וזה מורה שבזה העטות היו מוכנים לטעות בו וביאר עם זה עונש הטועה בע"ז במזיד.
@472 **התועלת** העשירי הוא להודיע ענש המחלל את השבת שהוא נדון בחמורה שבמיתות ובאר מפני זה הסמיכו' לע"ז שיש בחלול שבת רושם לעבור על כל מצות התורה כמו שביארנו במה שקדם ולהודיע שחלול שבת בכרת אם לא היה שם עדים והתראה:
@472 **התועלת** האחד עשר הוא במצות והוא מה שצוה לעשות ציצית על ארבע כנפות בגדינו וכבר ביארנו התועלת המגיע מזאת המצוה בביאורינו לזאת הפרשה:
@591 ואולם התועלות המגיעות ממנה הנה הם כ"א:
@591 **התועלת** הראשון הוא בדעות והוא שאין ראוי לחלוק עם הגדולים ממנו הלא תראה מה שקרה לקרח מפני מחלוקתו עם משה רבינו אדון הנביאים:
@591 **התועלת** השני הוא במדות והוא שאין ראוי שיקנא האדם בכבוד ומעלה שיש לזולתו יותר ממנו אבל ראוי שיספיק לו מה שחננו השם תעלה מזה וזה כי קרח מפני קנאתו במעלה והכבוד שנתן השם יתעלה לאהרון היה סבה אל שפתה אנשים רבים מישראל ומשכם אליו בה המחלוקת וגרם זה האבוד לו ולהם:
@591 **התועלת** השלישי הוא במדות והוא להודיע שהוא ראוי למנהיג כי כשיראה שהמונהגים ממנו מתיצבים על דרך לא טוב שישתדל בחכמתו להשיבם לטוב ולא יכעס עליהם וגם אם הם בועטים בו הלא תראה איך השתדל משה לפייס קרח בדברים גבוהים בישוב ובזולת כעס במה שהראה לו מדבריו שחננו השם יתעלה מהכבוד והמעלה בעבור אשר נתנה ללוים עבודת אהל מועד ולשבח השם יתע' בשיריהם עם שכבר נתעלה משפחתו בזאת העבודה על שאר משפחות הלוים עלוי רב להיות עבודת בני קהת בקדש הקדשים ואין הענין כן בבני גרשון ובני מררי וכבר הראה לו עם זה ג"כ כי זה לא היה בבחירת אהרן כי מהשם יתעלה נתנה לו הכהונה ולזה היה ראוי שלא יחזיקו עוד בזה המחלוקת ולזאת הסבה בעינה תמצא שקרא משה לדתן ולאבירם לפייסם מפני ידיעתו כי הם היו סבה חזקה לזה המחלוקת ואולי אם יתפייסו הם יהיו זה סבה שיתפייס קרח וינצלו כלם מהעונש:
@591 **התועלת** הרביעי הוא במדו' והוא להודיע שראוי לאדם כשיראה רצון האנשים ברע שיעתיקם מהרע ההוא מעט מעט כי אם רצה להעתיקם יחד ממנו הנה הם לא ישמעו לא לחוזק הסתבכם ברצון ההוא ולזה תמצא שכאשר רצה משה להעתיק קרח ועדתו מהרע שבחרו בו הקדים להם ממה שיה אפשר אצלם שישיגו מבוקשם בו והוא אמרו שהשם יתע' יבחר מי הוא הקדוש הראוי לכהנה עם מה שהיתה מהחכמה בזה המאמר כי הוא הראה להם שמהשם יתעלה נהיה הדבר הזה ולזה יהיה לשוא חלקם עליו וזה היה מיתרון מעלת משה וחכמתו שכבר כלל זה המאמר מה שיתפייסו בו תחלה לפי שלא התיאשו ממבוקשם ואח"כ יתבאר להם מהדברים ההם בעצמם עם מה שהמשיך להם מהמאמרים שיהיה בהם מהפיוס מאד מה שהיה ראוי שיעתיקם בשלמות מהרצון הרע שנשקעו בו ולזאת הסבה נפל משה על פניו לפני קרח לבקש ממנו שלא יחזיק בזה העניין:
@591 **התועלת** החמישי הוא בדעות והוא להודיע שלא תועיל התפילה והקרבת המנחה ליי' להשיג מה שאין ראוי שיושג לפי היושר כי כל דרכיו משפט ולזה תמצא ששפט משה שהשם יתעלה לא יפנה אל מנחת האנשים האלה כי הם מתרעמים ממשה על מה שאין ראוי להתרעם בו כי הוא לא הרע להם בצד מהצדדים ולזה לא היה להם לבעוט בו כ"ש שכבר הטיב להן מאד השם יתעלה על ידו:
@591 **התועלת** הששי הוא בדעות והוא להודיע עניין נפלא בדבר ההשגחה האלהית והו' שהעם המתאחד והיו לאגדה אחת שדבקה בהן ההשגחה הפרטית מהשם יקרה להם כשיחטא איש אחד מהם או אנשים מעטי המספר שיזוקו כלם כשתסור ההשגחה מהם וזה כבר ראוי והמשל שאם היה מלך אחד אוהב שר אחד והיה השר ההוא נלחם עם אדון מה והבטיחו המלך לעזרו במלחמתו ונקשר עם השר ההוא איש אחד שונאו לזה המלך הנה יסור עזר המלך ההוא מזה השר בעבור האיש ההוא שהוא שונאו ולזאת הסבה תמצא שעכן לבדו מעל בחרם ועל כל העדה היה קצף ולזאת הסבה תמצא בזה המקום שבעבור חטא קרח היה השם יתעלה רוצה לכלות ישראל לולא תפלת משה ואהרן:
@591 **התועלת** השביעי הוא בדעות והוא להודיע כי תפלת הנביא הדבק בשם יתעלה תסיר הרע מזולתו כשיקשה בעיניו זה כי בעבור השגחת השם יתעלה בו ישמרהו מזה הצער שיצטער אם ישיג הרע לאיש ההוא או לנשים ההם ולזה תמצא שתכף שהתפללו משה ואהרן על ישראל שב חרון אף השם יתעלה מהם:
@591 **התועלת** השמיני הוא בדעות והוא להודיע שהשם יעלה משגיח ומנהיג נפשות כל אחד מהאנשים ואין השגחתו נתלית בכללות המין לבד כמו שחשב הפילוסוף וזה הוא שאמר אל אלהי הרוחות לכל בשר ויהיה הרצון בזה הנה אתה השם יתעלה אשר השגחתך באיש איש בפרט מצד רוחו ושכלו היתכן שבעבור הכללות וההשתתפו' ישיג רע לכל העדה בעבור חטא איש אחד ולפי שהיה בלתי אפשר זולת זה כמו שקדם אם לא יסור ההשתתפות וההתאחדות מאלו החטאים עם ישראל לקח השם יתעלה עצה בזה כשיסתלקו ישראל סביב משכן אלו האנשים ויסור מפני זה השתתפותם והתאחדותם עמהם עם שזה יהיה סבה שלא יפותו להמשך לעצתם הרעה:
@591 **התועלת** התשיעי הוא לפרסם ענין זה המופת הנפלא שיהיה בפתיחת הארץ את פיה לבלוע אלו החטאים תכף שהשלים משה אלו הדברים שיתאמת בהם כי מהשם היתה זאת כי בהאמנת המופתים קיום אמונת התורה בכללה ויותר נפלא מזה שוב הארץ תכף לעניינה הראשון ר"ל שכסת עליהם הארץ כי פתיחת הארץ פיה כשהיה על דרך הטבע ישאר הפתח ההוא זמן ארוך מאד אך בכאן היו שני מופתים האחד בהמצאת הפתיחה ברגע מה שלא ישלם על דרך הטבע כי אם בזמן ארוך מאד והשני בסלוק זה המציאות וזה דומה לשאר מופתים נתנו זה המנהג כמו שוב המטה נחש ואחר זה שב הנחש מטה ושוב היד מצורעת ואחר זה שבה תכף בבשרו והנה זה התועלת בעינו הוא במה שזכר מהמופת ביציאת אש מאת ה' לאכול את חמשים ומאתים איש מקריבי הקטרת ובמטה אהרן שהוציא פרח ויצץ ציץ ויגמול שקדים:
@591 **התועלת** העשירי הוא להודיע שמי שירצה לחלוק על עניין המעלה והכבוד שגזר השם יתעלה לאיש מהאנשים כל מה שישתדל לחלוק עניין המעלה עליו יוסיף לו שלמות וקיום הלא תראה כי הערעור שערער קרח על הכהונה היה סבה אל שתהיה הכהונה ביותר שלם ממה שהיתה לאהרן ולבניו כי זה היה סבה לבאר לכל ישראל שהזר הקרב יומת בידי שמים ושהכהונה היא לאהרן מהשם יתעלה לא מבחיר' משה באופן שאי אפשר שיפול ספק לאיש מהאנשים ולזה היתה המצוה מהשם יתעלה לעשות המחתות מהאנשים החטאים ההם רקועי פחים צפוי למזבח להשאיר זכר זה הענין לדורות למען אשר לא יקרב איש זר אשר לא מזרע אהרן הוא להקטיר קטורת לפני השם פן יקרה לו דמיון מה שקרה לאלו החטאים ולזה הושם גם כן מטה אהרן שהוציא פרח וצץ צי וגמל שקדים לפני העדו' למשמרת לדורות להשאיר זכר זה העניין:
@591 **התועלת** הי"א הוא במדות והוא להודיע כי ראוי למנהיג השלם להשתדל בשמירת המונהגים ממנו בתכלית מה שאפשר ואף על פי שהם בועטים בו לא יתרשל מהצלתם הלא תראה כי היה מרוע תכונת ישראל להתרעם על משה ועל אהרן מהרע שקרה לחטאים שקמו כנגדם שהיו הם בעצמם סבה להגעתו ועם זה גם כן השתדל משה להצילם ממנו ולהעתיקם מהרצון הרע ההוא לפי היכולת וזה ממה שהיה ראוי שימנעם מהתרעם על משה מזה העניין ועם כל זה כשראה משה שבעיטתם בו היתה סבה אל שיצא הקצף מלפני השם לכלותם מהר להשתדל בהצלתם ולזה צווה אהרן להקטיר קטרת מרה להסיר הנגף מהעם.
@591 **התועלת** הי"ב הוא להסיר החשד שאפשר לישראל שיחשדו שיהיה טבע הקטרת להמית המקטירים אותו עד שאולי היו תולים בזה מיתת החמשים ומאתים איש מקריבי הקטרת ולא יודו שיהיה על דרך המופת מהשם יתעלה ולזה שם הכלי בהצלתם הקטרת כדי שיתאמת להם שלא היה זה העניין מטבע הקטרת אך מהשם יתעלה היתה נסבה בעבור חטאם בזאת ההקרבה:
@591 **התועלת** הי"ג הוא לבאר לישראל עוצם ההבדל שיהיה בין האיש הנבחר שבחר בו השם יתעלה להיות כהן ובין האנשים האלו שתקרבו מעצמם לדבר כהונה כי אלו המיתו עצמם בהקטרת הקטרת ואהרן הציל מהמות כל ישראל והקטרתו הקטורת וזה היה סבה להוסיף אמות בלב ישראל כי מהשם היתה הכהונה לאהרן ולבניו:
@591 **התועלת** הי"ד הוא במצות והוא המצוה בשמירת המקדש והתועלת בזאת המצוה מבואר להוסיף מעלה וחשיבות לבית המקדש בלב ישראל וזה היה סבה אל שלא יקלו בו וייראו ממנו וזה יהיה מבא להעמידנו על אופן החכמה שהיה בענייני זה הבית הנכבד אשר ינהגו בו בזה הכבוד והקדושה עם שזה יהיה כלי לשמירת ישראל שייראו מהכשל בענין המקדש והעבודות והנעשות בו:
@591 **התועלת** הט"ו הוא במצות והוא מה שהזהירה התורה שלא יקרבו זרים לעבודת בית המקדש ושאם יקרב לה ישיגהו עונש המות והנה היה התועלת בזאת המצוה כי העבודות האלו היו מעידות על עניינים עמוקים מאד והוא המכוון כמו שביארנו בספר ויקרא וכאשר תונח לאלו העבודות משפחה מיוחדת לזאת העבודה והיה לחמם נתן ומימיהם נאמנים בדרך שיהיה להן פנאי בעיון ותהיה מגמת פניהם להשתדל בעניין השלמות האנושי כמו העניין במשפחת בני אהרן היה בזה הישרה אל שיעמדו על סודות זאת העבודה הנכבדת עם מה שהישירו בזה קצתם את קצת כ"ש כשהיה הראשון מהם באופן מהשלמות שהיה בו והיו אבותיו כלם אנשים גדולים מאד כי זה יהיה סבה ליתרון ההכנה אבל השלמות בזרע אהרן כי טבע המקור הוא נמצא במה שנחצב ממנו ואלו היה קרב לזאת העבודה כל מי שירצה היה סבה להחטיא כוונת התורה בעניין זאת העבודה הנכבדת עד שכבר יעשו אותה ולא יעמדו על סודה ויהיה זה גם כן סבה אל שיקלו בה ויקרה בזה מההפסד בה מה שלא יעלם:
@591 **התועלת** הי"ו הוא במצות והוא מה שצותה התורה שיעבדו הלוים במקדש העבודה המיוחדת להם לא זולתם והנה התועלת בזאת המצוה הוא מסוג התועלת המצוה אשר לפניה:
@591 **התועלת** הי"ז הוא במצות והוא האזהרה שלא להתעצל משמירת המקדש ותועלת זאת המצוה מבואר ממה שקדם עם שבו תועלת לשמור ישראל מהכשל בעניני המקדש כמו שהתבאר מזה המקום:
@591 **התועלת** הי"ח הוא להודיע מה שסדרה התור' מהמתנו' לכהנים וללוים כדי שיהיה להם פנאי לעסוק בתורה ולעמוד על סודות המציאות לפי מה שאפשר ולזאת הסבה בעינה גם כן לא רצתה התורה שיהיה להם חלק ונחלה בארץ כדי שלא יהיו טרודים בעבודת האדמה ויהיה זה סבה להעדר השלמות מהם ובזה היה תועלת בעניין העבודות שהיו עובדים כמו שזכרנו ועוד בו תועלת להשאיר השלמות בזה העם הנבחר עד שלא יתכן בעת מהעתים שלא ימצא בזה החלק ממנו כאמרו לא תאבד תורה מכהן ואמר יורו משפטיך ליעקב ותורתך לישראל ואמר כי שפתי כהן ישמרו דעת ותורה יבקשו מפיהו:
@591 **התועלת** הי"ט הוא במצות והוא מה שהזהירה התורה שלא יקרבו הלוים לעבודת הכהנים ולא זה לעבודת זה והנה התועלת בזאת המצוה במעט עיון ממה שזכרנו בתועלת הט"ו מאלו התועלות:
@591 **התועלת** כ' הוא במצות והוא האזהרה שהוזהרנו מלפדות בכור בהמה טהורה והנה התועלת בזאת המצוה הוא כי התורה רצתה שיהיה קדוש קדושת הגוף להשאיר זכר המופת הנפלא שעשה השם יתעלה בעניין מכת בכורות ולו היה אפשר שיפדה היה הבא לכהן איננו בכור ויחלש מפני זה זה הזכרון עם שזה יהיה סבה אל שיקלו בנתינתו לכהן ויעכבוהו לעצמם להחשבם שזה העניין הוא לדמים לבד ויענו שבעת מה יפרעוהו לכהנים כאשר תמצא ידם כי הרבה יקלו האנשים בענין הממון שנתחייבו בו כ"ש כשלא היו לו תובעין כמו העניין במתנות כהונה ואולם בבכור פטר חמור לא היה אפשר בו זולת זה כי לא יתכן שיהיה קדושתו קדושת הגוף עם שהתורה התחכמה שעכ"פ יפדוהו הבעלים לפי שאסור להן ליהנות בפטר חמור אם לא יפדוהו אבל יחוייב להם לערפו אם יש בעניינו מהזרות מה שיביאו הבעלים לפדותו ואולם בבכור אדם לא היה אפשר בו יותר כי אי אפשר שיהיה קדוש קדושת הגוף ואיננו נכון שתצוה התורה בהמתתו כמו שצותה בהמתה בפטר חמור:
@591 **התועלת** הכ"א הוא במצות והוא מה שנצטוו הלויים להפריש תרומת מעשר והוא מעשר מן המעשר והנה התועלת בזאת המצוה מבואר בכללות ממה שזכרנו במתנות כהונה ובה עוד תועלת להעיד על מה שיעיר עליו עניין המעשר וכבר ביארנו זה התועלת במה שקדם:
@686 **זאת חקת התורה וגו' עד ויבואו בני ישראל כל העדה מדבר צין:**
@686 **זה ביאור דבר זאת הפרשה:**
@686 **מצד** עצם הדברים שזכרו בה ועוד יתבאר זה ביאור יותר שלם בזה המקום אם זכירתנו הסבות בכל מה שנכלל בזאת הפרש' והנה להעמיד על סבות כל אלו הדברים ר"ל למה היו מעשי הפרה ומי הנדה בזה האופן ולמה היתה טומאת מת בזה האון מהטומאה למעלה משאר הטומאו' אנחנו מקדימים תחלה מה שביארנו בפרשת ויהיה ביום השמיני שכל מה שהיה הב"ח יותר נכבד היתה טומאתו יותר חמורה להורות על מציאות הצורה ושהיא בו נכבדת כי מה שנפקד ממנו דבר יותר נכבד היה ראוי שנחשבהו ביותר חסר מצד ההשקפה אל מה שנעדר ממנו. ובהיות הענין כן והיה צורת האדם יותר נכבדת לאין שעור מצורת שאר הב"ח הנה מן הראוי היה שתהיה טמאת המת ממנו יותר חמורה כמו שביארנו בפרשת שמיני ולפי שבמות האדם נפקדה מחומר הצורה האנושית ונפקדה גם כן מהצורה האנושית מלאכתה המיוחדת בה מאשר היא כח בגוף והוא קנין השגת המושכלות חדשות אשר מדרכם שיושגו באמצעות החוש והדמיון והכח הזוכר כי אחר הפרדה מהחומ' אי אפשר שתשמש בזאת המלאכה כי אין לה כלים שיעמידוהו על זה אבל תשאר אז על מה שהשיגה מהמושכלות בעת דבקותה בחמר הנה להעיר על זה השרש הנפלא אשר הטעות בו מרחיק האדם מן השלמות האנושי התחכמה התורה להרחיק עניין המלאכה מהפרה כאלו העירה בזה שנפקד מזה הב"ח תכליתו מצד מה כי הבעלי חיים נבראו לעבודת האדם כמו שהתבאר במקומותיו וכמו זה העניין נכפל זה העניין בעגלה ערופה שהיתה באה גם כן על מיתת האד' וצוה שם גם כן לזאת הכונה שהמקום שתערף בו לא יעבד בו ולא יזרע ולא רצה שתשחט אבל שתערף כדי להרחיק שלא ישתמשו בה כלל לתועלת האדם אשר הוא בצד מה מהתכלית המכוון בזה ולזה נתבאר מזאת הכונה שהעגלה ערופה אסורה בהנאה ולזאת הכונה בעינה היתה המלאכה פוסלת בכל מעשי הפרה וגם במים שיושם בהם האפר דקדקה התורה בזה כדי להעמידנו על זאת כונ' הנפלאה מצד ראותינו ההכפל בהקפדת התורה בזה בכל מעשי הפרה כי זה מה שיפקח עינינו בזה בהכרח והנה היתה היא עגלה וזאת פרה להעיר על שאשר המיתו היתה סבה אל שמת בלא עתו ר"ל החלל שנמצא באדמה ולא נודע מי הכהו כי כבר יטעון בזה רבים שיחשבו שאי אפשר זה. וזה ממה שימשך ממנו הפסד גדול בדעות התוריות ובעיון ובעניינים המדיניים ויבטל טבע האפשר ואין זה מקום החקירה בזה והנה היתה נקבה זאת הבאה על טומאת מת כי היא חטאת כמו שזכר באמרו והיה לך למשמרת למי נדה חטאת היא ומשפט החטאת שהיתה נקבה ולזאת הסבה התנה שלא יהיה בה מום כמו העניין בשאר החטאו' ולזאת הכבה גם כן היתה באה נקבה בעניין החלל שנמצא באדמה כי הוא כמו חטאת ולפי שסבת המות לא תהיה מצד הצורה כי אם מצד החמר והכחות המתפעלות שיתגברו על הפועלות היה הדם הוא הנושא הראשון לאלו ההפסדים שהם סבת המות אם בסבת היותו בלתי שלם ההויה אם מצד עפוש יתערב הו היתה כונת התורה שתהיה זאת הפרה שלמה באודם והיה זה גם כן צבע הצמר הבא מן הארז והאזוב אדום לזאת הסבה והנה היתה נעשית חוץ לשלשה המחנות להעיר על הטומאה החזקה שהיא מסירה מעל טמא מת וכאלו היא נושא הטומאה ההיא ולזה הושמה בתכלית מהטומאה עד שכל המתעסקין בה בתחלה ועד סוף הם טעונין כבוס בגדים ולזאת הסבה גם כן היו מי הנדה מטמאין הטהורים כשלא ישתמשו בהם לצורך הזאה כי אז אי אפשר וזה כי מן השקר שיהיה הדבר האחד בעצמו מטהר ומטמאו יחד בעת אחד וכבר יתבאר בגזרת הצור הסבה בזה באופן יותר שלם בנמשך לזה מדברינו והנה היתה שחיטתה וההזאה מדמה במקום שיהיה נכח פני אהל מועד להעיר שהצורות כלם הם שופעו' מה' יתע' ועולות אליו בהדרגה ולזה היו שם ז' הזאות על כל הזאה טבילה להורות על שסוגי הצורות הם ז' והם נבדלות מאד זו מזו עד שלא יפול יחס בין הגבוהה לשפלה ממנה והנה היותר שפלה והיא הצורה האחרונה היא צורת היסודות ואחריה תהיה השנית צורת המתדמי החלקים המורכב מהיסודות והם צורת הדומם ואחריה תהיה הג' צורת הצומח ואחריה תהיה הרביעית צורת המרגיש ואחריה תהיה החמישי' צורת האנושי' ר"ל המדברת ואחריה תהיה הו' צורת המלאכים שהיא שכל משכיל בפעל תמיד והיא העלולה מה' יתע' ואחריה תהיה השביעית ית' והיא הצורה הראשונה והוא מבוא' שאלו הצורות הה' הראשונות הם יחד באדם ומצורות האדם נעמוד על מציאות הצורות הנבדלות ומהם נעמוד על מציאות השם יתע' וזה מבואר למי שעיין בפילוסופיא ואין זה מקום זאת החקירה ולפי שענין הטמאה היה לתכלית שנעמוד על מציאות הצורה כמו שהרחבנו הביאור בזה בספר ויקרא הנה ראוי שתסור זאת הטומא' כשימצא לנו דבר אחר יעמידנו על מציאותה כמו שיעמידנו על זה ענין הטומאה ולזה הנה ענין מעשה הפרה מכון לזה התכלית ולזה תמצא שכיון שיעדרו מהפרה כל צורותיה כשתשחט תחלה ואחר היתה נשרפת ואחר הצית האש ברובה היה משליך בתוכה עץ ארז ואזוב ושני תולעת להורות שהמרגשת תעדר תחלה מהחי ואחר תפסד הצומחת וזה יורה על התחלפות מדרגות אלו הצורות זו מזו כי אשר היא במדרגת הצורה והשלמות לא תמצא נפרדת מאשר תהיה מנה במדרגת ההיולי ובזאת ההישרה נתישר אל שצורת האדם היא למעלה מאלו הצורות ושהיא תעדר תחלה בעת המות להעיר על זה רצה שיפקד מהפרה בחייה מה שהוא משל ודמיון מה לשכל האנושי והיא המלאכה הלא תראה שקצת בעלי חיים יעשו מלאכות נפלאות כמו ששיות הדבורים ואריגת העכביש עד שידמו דמיון מה למה שיסודר מהשכל מהמלאכה ולהורות על מלאכת הפסד השכל בקניין מושכלות חדשות אחר המות רצתה התורה שבמעשה הפרה לא יהיה עמהם התעסקות במלאכה זה דבר יעמידנו על שתי פנות גדולות מהעיון האחד כי היא בזה נתיישר אל שהשכל האנושי אינו נפסד בהפרדו מהחמר אבל יפקד ממנו קנין המושכלות שלא השכיל אותם בחייו והנה זאת הפנה הגדולה טעו בה כל הפילוסופי' שהגיעו אלינו דבריהם. והשנית הוא שאח' המות לא יקנה השכל מושכל חדש לא השכילו בהיותו עם החמר וזו היא ג"כ פנה גדולה נבוכו בה רבים מהקודמים בהשארות וזה מבואר למי שעיין בדברנו בספר הנפש ובא' מספר מלחמות השם. וראוי שתדע שהצורות הנפשיות כלם סרו מהחי במותו ואף על פי שנשארו תמונת האברים בעצמם כי אין בהם כח לפעול פעולה מהפעולות אשר להם מאשר הם חלק מבעל נפש וזה דבר יעיד על מציאות הצורה כי לא תמצא במת שנפקד ממנו דבר זולת הצורה והנה להעיר על זה היתה הפרה נשרפת בכללותה על מערכתה ולהעיר על הבדל הנפש הצומחת מהמרגשת כי היא תמצא נבדלת בצמחים הושם בה עץ ארז ואזוב שהם הגדול והקטן מהצמחים להעיר שבכולן תמצא נפרדת וגם בחי תמצא נפרדת בצמר ובשער ולזה הושם שם שני התולעת שהוא צמר צבוע בתולעת שוא ג"כ מהצמחים והנה השתדלה התורה להעמידנו על מציאות הצורה לפי שהוא דבר נעלם מהקודמים לפי מה שנתבאר מדברי הפילוסוף מדעותיהם במה שאחר הטבע ומי שלא יודה במציאותה יסור ממנו כל שלמות אנושי ולא יודה במציאות ה' ית' ולהסירנו אנחנו הנמשכי' לתורתו מהכשל במומי הדעות הנפסדות ההם התחכמה בזה האופן להמציא לנו אלו התחבולות הנפלאות אשר יסירו בהכרח זה העורון ממנו תמיד וכדי שיתבוננו בנרצה בזאת המצוה צותה התורה שישתכלו בשחיטתה ובשריפתה וישימה עיניהם ולבם בה ישתבח יתעלה יוצר הכל שחנן אותנו זאת התורה השלמה אשר תחכימנו עכ"פ ותישירנו אל השלמות האנושי ותמשכנו אליהם בעבותות התחבולות הנפלאות תפקחנה בהם עיני עורי' כל שכן עם מה שהישירה אל קנין השלמת זאת המשפחה המתעסקת בעניינים אלו ר"ל העבודה בקרבנות והסיר הטומאות החמורות והוא משפחת הכהנים וכדי שלא יחשוב אדם כי טומאת המת הוא מפני העפוש שהוא מזיק לקרובים אליו ביארה התורה שאפילו עצם אדם הוא מטמא זאת הטומאה החמורה אף על פי שאין בו עפוש והנה היתה יותר חמורה טמאת המים שיש בהם כדי הזאה מטמאת המים שאין בהם כדי הזאה לפי שהמים שיש בהם כדי הזאה הנה בכחם להסיר טומאת מת וכדי שיתבאר זה מהם רצתה התורה שיטמאו אדם לטמא בגדים שעליו להעיר שהם נושאים הטומאה ומושכין אותה אליהם ואמנם המים שיאן בהם כדי הזאה איך זה בכחה אם לא יחובר להם עוד מהמים ולזה לא היתה עוד טומאתם חמורה כטמאת האחרים ובכאן נשלם מה שכוננו ביאורו בזה המקום מטעם אלו המצות יתברך היכול אשר חננו למצא האמת בזה ויתרומם על כל ברכה ותהלה:
@686 **התועלת** הראשון הוא במצות והוא להודיע דין מצות פרה אדומה ואיך מעשיה ואולם התועלת המגיע ממנה היא הטהרה מטומאת מת החמור' לישב בלב הטמאים שזאת הטמאה הוסרה מהם כי לא ידמו שיסור זה הרושם ממנה בזולת מעשים נפלאים ועם זה כבר יגיעו ממנו תועלות נפלאות בעיון כמו שביארנו בטעמי זאת המצוה:
@686 **התועלת** השני הוא בדעות והוא מה שסמכה התורה עניין פרה אדומה לעניין זכירת הקרבנות ומתנות כהונה כי זה ממה שהישירנו לעמוד על הכונה אשר בעבורה היתה זאת המצוה בזה התואר כי עניין הקרבנות והטומאות והטהרות הם לכונה אחת בעינה כמו שיתבאר מדברינו בביאור ספר ויקרא ולזה זכר שם עניין הטומאות והטהרות אחר זכירתו עניין הקרבנות כמו שביארנו שם:
@686 **התועלת** הג' הוא במצות והוא להודיע עניין טומאת מת ומשפטה והנה התועלת בזאת המצוה מבואר ממה שזכרנו בזה המקום ובפרשת ויהי ביום השמיני:
@686 **התועלת** הד' הוא במצות והוא להודיע דין טומאת מי נדה וטהרתן והנה התועלת בזאת המצוה מבואר ממה שזכרנו והוא גם כן ממה שיפול מבוכה חזקה איך יהיה זה שהמטהר יטמא ויביא זה בהכרח להעמידנו על הכונה אשר בעבורה היא אלו המצות בזה התואר:
@708 **ויבאו בני ישראל כל העדה עד סוף הפרשה:**
@708 **ואולם התועלות המגיעות מזה הספור הם כ"א:**
@708 **התועלת** הראשון הוא במדות והוא להודיע שאין ראוי לגנות האדם מאד במה שיטיח דברים שלא כהוגן בעת הצער והחסרון החזק. הלא תראה כי ישראל כשהיו בצער גדול מהצמא והיו יראי' שימותו מחוזק הצמא הטיחו דברים קשי כנגד משה ולא מצאנו שנענשו על זה אך רצה השם יתע' שינתן להם מים בזה האופן שזכר:
@708 **התועלת** הב' הוא להודי' כי מי שיצטרך לעשו' פעל מה לתכלי' מה אין ראוי שיקצר משיגיע מהפעל ההוא כל התועלות האפשריות ולזה תמצא שכאשר הביא ההכרח שיתן השם יתע' מים לעם היה משתדל שיגיע להן עוד מנתינתו המים להם תועלת עצם להביא אותם אל האמנה בהשם יתעלה ובחזק כחו לעשות מה שירצה ולזאת הסבה גם כן תמצא שלא הסכים השם ית' להסיר הנחש מהעם אבל רצה שירפאו הנשוכים בהביטם אל נחש הנחשת כדי שימשך מזה לישראל התועלת מתמיד יביאם להאמין בעוצם נפלאות הש' יתעלה כמו שביארנו בביאור זאת הפרשה:
@708 **התועלת** השלישי הוא להודיע שאח' מן החבורה שמת ראוי שתדאג כל החבורה. הלא תראה כי כשמתה מרים תכף נגזר המות על אחיה עם עוצם מעלתם עד שכלם מתו בחדש אחד וזה יתבאר ממה שספרנו בזאת הפרשה וכבר התבאר מדברי התורה עם מה שנזכר בספר יהושע כי לא חיה משה אחר אהרן כי אם חדש אחד כי אהרן מת באחד לחדש בשבט בשנת הארבעים לפי מה שהתבאר בפרשת ואלה מסעי ומשה מת באחד לחדש אדר לפי מה שהתבאר מדברי התורה עם מה שנזכר בסוף ספר יהושע כמו שביארו רז"ל וכבר הרחבנו בזה בביאורנו לספר יהושע:
@708 **התועלת** הרביעי הוא להודיע שראוי להתאונן על מיתת הצדיקים כי מיתתם עושה רושם כמו שראינו העניין במיתת מרים ואהרן ואע"פ שהיה נשאר אז משה רבינו אדון הנביאים אף על פי כן הגיע ממיתתם רושם מבואר:
@708 **התועלת** החמישי הוא להודיע שראוי להרחיק מדת הכעס הלא תראה כי הכעס היה סבה אל שלא עמד משה רבינו ע"ה עם עוצם מעלתו והשגת מדותיו בשלמיות על כוונת השם יתעלה במה שצוהו. ואמ' ודברתם אל הסלע ונתן מימיו ונמשך מזה מהרע לישראל עם שהגיע ממנו גם היזק לנביא מה שכבר זכרנו בביאו זאת הפרשה:
@708 **התועלת** הששי והוא במדות והוא להודיע שראוי לאדם שיתיישב מאד בכונת הדברים אשר צווה עליהם בעשייתם מאת מי שהוא מחוייב לעשות את מצותו כי כשלא יתיישב בכונתם אולי יעשה מהם מה שא יגיע בו תועלת המכוון בפעל ההוא הלא תראה כי משה רבינו ע"ה עם עוצם מעלתו הנה כשלא נתיישב על כונת המאמר שהגיע לו מה' יתע' קרה לו שהחטיא כונתו:
@708 **התועלת** השביעי הוא להודיע כי חטא העם היתה סבה שלא יביא אותם משה אל הארץ כמו שביארנו בביאור דברי זאת הפרשה ולזה לא יירשו הארץ באופן מהשלמו' שהיו יורשי' אותה אם היה הפעל נעשה על ידי משה הלא תראה עוצם ההבדל בין מלחמות משה ובין לחמות יהושע כי משה במעט מהזמן שחיה אחר אהרן כבש כל הארץ שהיה לשני שבטים וחצי ויהושע עשה מלחמותיו ימים רבים ולא כבש הארץ אך חלקה קודם שנכבשה:
@708 **התועלת** השמיני הוא להודיע עוצם מעלת משה שאף על פי שלא עשה הדבר כמו שצוהו השם ית' שמע השם יתעלה לקולו להוציא מים רבים מהסלע:
@708 **התועלת** התשיעי הוא להודיע שהחטא הקטן לגדול הוא נחשב לגדול הלא תראה איך נענשו משה ואהרן על יד החטא הקטן אשר לא היה למרות פי השם ית' אבל להמשך למצותו לפי מה שהבינו מדברי השם יתעלה ולזה אמר שכבר נתקדש הש' יתע' בם על דרך אמרו בקרובי אקדש:
@708 **התועלת** העשירי הוא להודיע שראוי למי שיבקש דבר מאחר שימציא כל הסבות העוזרות לו להשיג מבוקשו ממנו. הלא תראה כי משה שלח בעבור ישראל למלך אדום אלו הדברים שהיה בהם מה שאפשר מהפיוס והבאת לב מלך אדום לתתם לעבור בארצו:
@708 **התועלת** הי"א הוא שראוי לאד' לפחד תמיד ולזה ספרה התורה כי כשראו ישראל שאין רצונו לתתם לעבור בגבולו ויצא לקראתם בעם כבד וביד חזקה נטו בעליו ולא רצו להלחם עמו כי פחדו פן ינוצחו ואף על פי שידעו שיד השם לא תקצר עמם לטובה בכל מלחמותיהם ולא האשים השם יתעלה לך אדום על זה כי היה מפחד וירא מישראל פן ישחיתוהו בהיותם בארצו אבל צוה שלא יתגרו בו מלחמה כמו שנזכר בפרשת ואלה הדברים:
@708 **התועלת** הי"ב הוא להודיע מה שהיה מהעדר הצער במיתת אהרן עד שכבר מת בזולת חולי אך הפשיט בגדי כהנה גדולה ולבשם אלעזר בנו ותכף גוע אהרן ולזה אמרו ז"ל כי משה ואהרן ומרים מתו בנשיקה והנה לפרסם זה העניין הנפלא רצה השם ית' שיהיה זה העניין לעיני כל העדה:
@708 **התועלת** הי"ג הוא להודיע שהממשלה והשררה ראוי שתגיע מהמושל לבנו כשהוא ראוי לה ואף על פי שאין מדרך השררה שתבא מאב לבן כמו העניין בכהונה גדולה אלא כשהיה בנו ראוי ראוי שיהיה קודם לכל אדם כמו שביארנו בספר ויקרא ונתבאר עוד בזה המקום ממה שאמר וילבש אותם את אלעזר בנו ללמדנו כי מצד שהוא בנו היה ראוי שיגיע לזאת השררה והממשלה עם שכבר העירנו בזה ללמדנו שאלעזר בנו היה דורך בדרכי אהרן ומחזיק בהנהגותיו הישרות:
@708 **התועלת** הי"ד הוא ללמדנו שאין ראוי להתעצל בהספדו של חכם אבל ראוי שיזדרז בו כי בזה מהתועלת להזדרז להשיג זה השלמות בהכירם מה שנפקד מהם בהפקד זה החכם ולזה ספרה התורה שבכו כל ישראל את אהרן שלשים יום וסמך לזה נצחם הכנעני מלך ערד להודיע שהעושים כך יתן השם יתעלה שכרם:
@708 **התועלת** הט"ו הוא להודיע שאין ראוי לאדם שינכר מה שעשו לו מהטובה אבל ראוי שיכיר הטוב למי שעשהו לו כ"ש אם היה עושה הטוב השם יתע' הלא תראה כי ישראל בעבור שנתנכרו מן הטובות שהגיעו להם מה' ית' ע"י משה שולחו בם הנחשים השרפים והמיתו מהם רבים וזה כי הם לא התרעמו מלחם ומים בעבור צרכם אליהם אבל רוע תכונתם משכה אותם אל שיתרעמו מהשם ית' וממשה על לא דבר יביאם להתרעם מהם אבל היה מהראוי להם לתת תודה לשם יעת' כעל כל אשר גמלם ולמשה נביאו:
@708 **התועלת** הששה עשר הוא להודיע שכאשר יחטא איש לאיש ויתנחם מזה ויכיר חטאו ראוי שיקבלהו האח' תכף וימחול לו חטאו הלא תראה כי תכף שהכירו יש' חטאם והתנחמו ממנו קבלה משה והתפלל עליהם על דבר הנחש:
@708 **התועלת** הי"ז זכרון הפלא שהיה בענין הבאר שחפרוהו במקו' חול ועפר תיהוה במחוקק במשענותם ורצה ה' ית' שיהיה ממנו מים לכל העדה ולהעיר על עוצם המופת הזה ספר השירה ששרו ישראל על דבר הבאר הזה:
@708 **התועלת** הי"ח הוא להודיע יד השם יתעלה הטובה על ישראל על ידי נביא עד שנצחו שני מלכי האמורי שהיו בתכלית הגבורה לפי מה שיתבאר ממה שזכר ממלחמ' סיחו' עם מלך מואב הראשון שלקח את כל ארצו מידו עד ארנון וממה שזכר מגודל עוג מלך הבשן שהיה כגובה ארזי' גובהו:
@708 **התועלת** התשע עשרה הוא להודיע כי השם יתעלה ישלם מדה כנגד מדה וזה עדות חזק על שזה הענין מכוון מהשם יתעלה על צד העונש לא שיהיה על צד הקרי כמו שיחשבו אנשים ומזה ילקח מופת על השגחת הש' יתע' במין האנושי ופקדו אוו על כל מעשיו ולזה תמצא כי סיחון השחית המואבים אשר בעיירות ההם שלקח מהם עד בלתי השאיר להם שריד וכן שלם לו אלהים על ידי ישראל וכן אמר שמואל לאגג כאשר שכלה נשים חרבך כן תשכל מנשים אמך ואמר אדני בשק שבעים מלכים מקוצצי בוהנות ידיהם ורגליהם היו מלקטים תחת שלחני כאשר עשיתי כן שלם לי אלהים:
@708 **התועלת** הכ' הוא להודיע במה שהגיע לישראל מארץ מואב הגיע להם על ידי סיחון כי הש' ית' לא רצה שיקחו מארץ מואב מדרך כף רגל אך היא היתה לסיחון בעת שלקחו ולזה הגידה התורה המשלי' ההם המעידים על אמתת זה:
@708 **התועלת** הכ"א והוא מקיף בכל הספורי' שנזכרו בעניין מסעי בני ישראל במדבר הוא ליישב בלבנו אמתת כל אלו הדברים הנפלאים שבאו באלה הספורים ולזה האריכה בספורי המקרים שארעו להם במדבר במקום מקום מהמקומות ההם וזכרה באריכות תואר המקומות שקרה להם זה בהם כדי שתתישב אמונת כל אלו הדברים בלבנו:
@843 **וירא בלק בן צפור את כל עד סוף הפרשה.**
@843 **ביאור דברי זאת הנבואה:**
@843 **אמר** נאם בלעם בנו בעור ונאם הגבר פתוח העין נאם שומע אמרי אל אשר יחזה מחזה מאת השם יתעלה והוא גלוי עינים בעת הנבואה ואף עלפי שהוא נופל מרוב התבודדות או ירצה בגלוי עינים עיני לבו והביאור הראשון נראה לנו יותר כי ידמה שבהקיץ היתה מגעת לו הנבואה ולזה אמר אולי יקרה יי' לקראתי בדרך. ואנכי אקרה כה כי האדם לא יישן כשירצה ותכף שיישן לא יחוייב שתגיע לו הנבואה עם שהישרת הקרבנות להגיע אליו הנבואה תצטרך להגיעה בהקיץ לא בעת השינה כי אז ימצא התבודדות בזולת השתדלות כמו שביארנו בב' מספר מלחמות השם. מה טובו אהליך יעקב. ר"ל שגם בקבוץ אשר באהל אהל לא ימצא רק טוב כ"ש בקבוץ כלל ישראל ואמר זה לפי שאם ימצא רע באהל אחד מהם יענשו כלם כמו שביארנו בפרשת קרח והיה זה כן מצד היותם כולם מתאחדים ומזה גם כן אפשר שנתיש בלק וכוין להחטיא קצתם כי בחטא אחד מהם יענשו כלם הנה עניין ישראל והסתעפות זרעו דומה לנחלים שנטיו ונתפשטו מימיהם במקומות רבים שלא יכזבו מימיהם כי בסורם יעמדו אחרים תחתיהם דומים לראשונים וכן הענין בישראל כי במות האבות יקומו אחריהם בניהם וילכו בדרכי אבותיהם לעבוד השם יתעלה וכדי שלא יחשוב חושב שיתחייב מזה שלא ירבו ישראל יותר ממה שהיו אז אמר שהם כגנות אצל נחר שיצמיחו זרועיהם ויפרו וירבו תמיד והנה עשה שנית משל אחר דומה לזה ואמר שהם כאהלים ינטע יי' והם השמים הנטוים ומקיפים בכל הארץ להורות על הנצחיות והקיום לישראל ולפי שאן השמים פרים ורבים שב להמשילם עוד לארזים שהם אצל מים שהם אילנות גדולות ופרים ורבים תמיד מצד רוב המצא המזון להם וכל כך ימצא להם המזון שצמחו בו עד שמדליותיו יזל מים וזרע אחר שיפול אחד אחד מהדליות יהיה גם כן במים רבים וזה לאות שהאבות והבנים ובני הבנים והנמשך להם כלם יהיו בזאת ההצלחה עד שהמלך שהמליכו ישראל והוא שאול ירום מאגג מלכו כי הוא ינצח אותו במלחמה ותנשא מלכותו מאד וזה מבואר מעניין מלכות שאול לפי מה שנזכר בספר שמואל והנה כל זאת הצלחה תהיה לישר' מצד ההשגחה הפרטית אשר תדבק בהם מהאל שהוציא אותם מארץ מצרים לא באמצעות שפע הכוכבים אבל מצד תקפו וגבורתו לעשות מה שירצה ולזה הוציאם משם באותות ומופתים גדולים והוא ישחית הגוים שהם אויבי ישראל וישבר עצמותיהם ויפרקם וכל אחד מחציו יכה בהם ר"ל שמינים רבי מהרעות יביא על אויביהם לפי מה שירצה כעת מה ולזה אין דרך להשמר ממנו כי אין מדרכו להביא רע מיוחד שאם היה זה כן היה זה דרך להשמר ממנו ומשל כי מי שיודע שאויבו אינו מזיק כי אם באש הנה יוכל לקחת עצה מזה להמציא אצלו הדברי המכבים האש אבל אם לא ידע באיזה מין יזיקוהו לא יוכל לקחת עצה על זה. גם בעת שישכון ישראל בטח ולא ילחם הנה מי שילך אליו להלח' בו ימצאהו כארי וכלביא שלא יוכל אחר להסירו ממקומו. ואמנם אמר זה כי היושבים בטח ושלום להם מכל עבריהם אינם מורגלים בענייני המלחמה ולזה אינם בקיאים בה במדרגת בקיאות מי שדרכו להלחם תמיד.
@843 וקודם שנזכור התועלות המגיעות ממנה נזכיר ספק אחד בעניין זאת הפרשה והוא איך נזכרה נבואת בלעם וספור דברי בלק עמו בתורה. כ"ש שיתחזק זה הספק מצד מה שמצאנו שכבר היה בלעם קוסם ונאמר שכבר נזכר זאת הפרשה בזה המקו' מצד התועלות המגיעות ממנה כי כבר יתבאר ממנה עוצם השגחת השם יתעלה על ישראל כמו שביארנו ולזה אמר הנביא עמי זכר נא מה יעץ בלק מלך מואב ומה ענה אותו בלעם בן בעור מן השטים ועד הגלגל ובזה גם כן תועלת להודיע מה היתה הסבה בזנות ישר' אחר העריות ואחר עבודת זרה ולמה נצטוו ישראל להרוג את המדינים. וראוי שתדע שאלו הספורים מבלק ומבלעם ידעם כלם משה רבינו ע"ה מפי הגבורה ולא נודעו לו אחר הפרסום כי בזולת זה לא היה ראוי שיכתבו בתורה. הנה כמו שהגיד משה מפי הגבורה דבר הספורים שבאו בספר בראשית כן הגיד זה הספור אשר בזה המקום מפי הגבורה ומזה האופן נתאחדו הספורים עם המצות בתורה לפי שהם כלם מכוני' להביא אל השלמת האנושי הנמשכים לדברי התורה ואל זה כוונו ז"ל באמרם שמשה כתב פרשת בלעם.
@843 **ואולם התועלות המגיעות מזאת הפרשה הם י"ו:**
@843 **התועלת** הראשון הוא להודיע שלא יגונה מי שיפחד לנפשו מאחר אם יבקש סבות בהצלתו באי זה אופן שיוכל ולזה תמצא שלא נענשו המואבים במה שהשתדלו להחטיא ישראל לפי שיראתם ופחדתם פן ישחיתם ישאל היתה הסבה בזה כי כבר היו יראים מאד מישראל כמו שאמר ויגר מואב מפני העם מאד כי רב הוא ולזה נחשב למואב החטיאם ישראל אחד מכלי המלחמה ואמנם המדינים שלא היו יריאים מהן וכונו בדבר בלעם למסר מעל ביי' רצה השם יתעלה שיקחו ישראל נקמתם מהם:
@843 **התועלת** השני הוא להודיע עוצם ההבדל שיש בין נביאי ישראל ובין נביאי אומות העולם וזה שכבר הכיר מזה הספור מתכונות בלעם שהוא היה רודף אחר הכבוד ומבקש אותו והפך זה תמצא בנביאי ישראל עד שמשה עם היותו מלך ונביא ספרה התורה שהוא עניו מאד מכל האדם ותמצא גם כן מתכונות בלעם שיה הומה לאסיפת הקנינים וזה יתבאר ממה שאמר אם יתן לי בלק מלא ביתו כסף וזהב כי לולי זה העניין נכסף לו לא אמר זה המאמר והפך זה תמצא בנביאי ישראל וזה יתבאר לך מדבר אלישע לנעמן ואמר אברהם אם מחוט ועד שרוך נעל ואם אקח מכל אשר לך ואף על פי שזכה בו בדין ותמצא גם כן מתכונות בלעם שלא היה נכנע למה שצוהו השם יתעלה בנבואה ולזה הוצרך השם יתעלה להפחידו על ידי המלאך שכבר יהרגהו אם יעבור על דברו לומר כי אם הדבר אשר השם יתעלה ישים בפיו ותמצא גם כן מתכונותיו שהיה נמשך לתאוות חוש המישוש אשר הוא חרפה לנו כי היות הדבר ההוא בלתי מרוחק אצלו לא נתן עצה להפקיר הנשים בכלל לישראל ובכל הנה נביאי ישראל ישתדלו להישיר האנשים לעבודת השם יתעלה ולשמרם מהחטא והמרי ובלעם היה מישיר אותם בעצתו אל החטא והמרי עם היות כחו יפה מאד בנבואה בזה העת עד שהיתה מגעת לו הנבואה בהקיץ כמו שביאר' ומזה הצד אמרו רבותינו ז"ל על אמרו ולא קם נביא עוד בישראל כמשה אבל באומ' העולם קם ומאי ניהו בלעם ואמרו זה על צד ההפלגה עם טוב הכנתו בנבואה עד שנתקרבה מדרגתו למדרגת משה רבינו בדרך שהית' מגעת לו בהקיץ בדבר שרצה להגיע לו הנה תמשמש בהכנתו בפחיתיות לא להישיר האנשים אל הטוב וגם לא קנה לעצמו המדות הראויות לשלם וראוי שתדע שכבר נתחייב מלשון התורה במה שאמרה ולא קם נביא עוד בישראל כמשה שנאמ' אבל באומות העלם קם ואם לא הנה יהיה אמרו בישראל לבטלה אבל לא יתחייב שיהיה זה הקם באומות העולם בלעם כי לא היה במשה באחד מהדברים שזכרה התורה בזה המקו' שלא קם בהם נביא כמוהו כי לא ידע ה' ית' בלעם פנים בפנים ולא חדש אותות ומופתים כלל כל שכן שלא חדשם במדרגת האותות והמופתים שנעשו מאת הש"י ע"י מש רבינו ואמנם האמת יהיה המתחייב מהפסוק הזה שלא קם נביא עוד כמשה שהיה נביא בישראל לבד אבל יהיה שיהיה עם זה נביא באומו' העולם ג"כ הוא מלך המשיח כמו שאמרו במדרש הנה ישכיל עבדי שכבר יהיה יותר גדול ממשה ויתבאר שנפלאותיו ג"כ תהיינה למעלה מופלאות משה כי משה משך ישראל לבד לעבודת שם ית' בנפלאות שחדש והוא ימשוך כל האומות לעבודת השם ית' באמרו אז אהפוך אל עמים שפה ברורה לקרוא כלם בשם יי' וזה אמנם יהיה באמצעות מופת נפלא יראה בקצות הארץ לכל האומות והוא תחיית המתים:
@843 **התועלת** השלישי הוא להודיע עוצם השגחת השם ית' על ישראל במה שהשתדל לשמור בלעם שלא יקללם בזה אופן הנפלא שספרה התרה עד שעם תשות בלעם לקלל אותם הוכרח להשמר מזה מצד מצות ה' ית' ופחדו שפיל עליו בדבר המלאך שהראה לו בדרך וחרבו שלופה בידו וכבר יסופק על זה למה השתדל הש"י כל זה ההשתדלו' שלא יאור בלעם העם אחר שהש"י אמ' שהוא ברך התזיק להם קללת בלעם ואם אמרנו שעשה זה הש"י להציל בלעם מהבשת איך היה זה העניין על צד החסד לישראל כמו שנראה מדברי הנביא באמרו עמי זכור מה יעץ בלק מלך מואב ואם אמרנו שהש"י עושה זה לפי שגלוי היה וידוע לפניו שישראל היו ממרים את פיו תמיד והיה הש"י כועס עליהם וממית מהם במגפה או בזולת זה כמו שנזכר בתורה ואם היה בלעם מקלל אותם ויקרה להם אחר זה המקרה זה היה חושב בלעם ומוא' שקללתו סבב להם זה הנה עדין ישאר הספק בעינו כי בזה לא יהיה חסד לישראל כשלא קללם אך יהיה בו כבוד לש"י שלא יתפאר בלעם כי קללתו סבב להן זה ואולם התר זה הספק יש בו מהקושי העצו' לפי מה שאחשוב והנראה לי בזה הוא אם שנאמר שהש"י עשה זה לסבה שכאשר יחטאו ויכסה ש"י על צד התוכחת ירגישו כי חטאם היה סבה אל זה העונש הבא עליהם ויחיה זה סבה אל שישובו אל הש"י וריחמם ואם היה בלעם מקלל אותם הנה לרוב הפרסום שהיה בעניינו שאשר יאור יואר הנה יתלו ישר' העונש הבא אליהם אם שיהיה מפני קללה שקללן בלעם ולא ישתדלו לשוב אל הש"י ויהיה זה סבה שיחר אף השם בהם ויכלם. והמשל כי לא לו קללם בלעם הנה בבא המגפה בעדת הש"י על דבר פעור לא היו משתדלי' לשוב אל הש' ולהתנחם מחטאם לחשבם שקללת בלעם ישר' תסבב זה ואם אמר אומ' איך ידעו ישראל זה העניין ר"ל אם קלל אותם בלעם עד שיצטרך ה' לשמרו מלקללם לזאת הסב' אמרנו לו שכבר אפשר זה מפני רוב התמדת' אצל בני מואב כי אצלם היו יושבים ולשגלם עם נשותיהם ולזה יתכן שיספרו להם זה בני מואב להחטיאם יותר ויקרה מזה ליש' מההיזק מה שכבר זכרנו או נאמ' שקללת בלעם האנשי' היה בעשותו מיני כשוף ונחש להמציא להם היזק והם דברים מכחישים פמליא של מעלה והנה רצוני באמרי נחש הנחש המתיחס לכשוף כמו שידמו הסכלים שכבר נודע על דרך נסיון שעשיית תמונת כך מדבר כך בעת כך בתנאים כך מהככבים תזיק לאבר כך או לדבר כך והיה זה חלק גדול מחכמי מצרים וחכמי בכל והנה היה נעזר בזה בלעם מהודעה שתגיע לו בקסם לדעת באי זה מהדברים יתכן שיוזק האיש ההוא או העם ההוא לפי מה שיתבאר לו בקסם שימשך לאי ההוא או לעם ההוא משפע הככבים ולפי שהיה אפשר שימצא באלו הענינים או במה שהוא מסוגם מה שאפשר שיתחדש בו היזק לישראל רצה השם יתעלה להצילם מזה ואף על פי שמהענינים האלו לא יוזק מי שתדבק בו השגחת השם יתעלה כי גם במה שנתחייב בעצמות וראשונה מצד מערכת הככבים ישמרהו השם כמו שביארנו בד' מספר מ"י הנה מפני שישראל לא היו אז באופן מהשלמות שתדבק בהם כמו זאת ההשגחה ויורה על זה התפתותם בקלות לעריות ולע"ז הצטרך הש' יתעלה לשמרם מזאת הקללה:
@843 **התועלת** הד' הוא להודיע שהעלאת העולות הוא ממה שיישיר להגעת הנבואה הלא תראה שבזולת זה היה צריך בלעם כשירצה להגיע לו השפע האלהי להודיע לו הדבר שירצה שימתין שיהיה לילה ואז יהיה לו זאת ההודעה בעת השינה בעת אחד מן הלילה לא בעת מוגבל ממנו ולזה אמר לינו פה הלילה וגומר שבו נא בזה גם אתם הלילה ואמנם עם הקרבת העולות נתחדשה לו ההודעה בהקיץ וכאשר רצה ולזה צוהו השם יתעלה על הקרבתם כמו שביארנו:
@843 **התועלת** הה' בדעו' והוא להודיע שכבר יצטרך לנביא שתתבודד מחשבתו במי שירצה שתגיע לו בנבואה ההודעה מעניניו ולזה ספר בזה המקום שהקפיד בלעם בפעם בפעם שיראה העם אשר רצה שתגיע לו בנבואה ההודעה בעניניהם:
@843 **התועלת** הו' הוא בדעות והוא להודיע שמי שתדבק בו ההשגחה האלהית לא יוזק בכשוף ובמה שיונהג מנהגו ולזה אמר בלעם כשרצה לבאר שקללתו לא תזיק לישראל שהשם יתעלה לא הסכים לקלל את העם כי זה העם נתייחד מבין שאר האומות בשהוא דבק בשם יתעלה ודורך אל החיים הנצחיים וזהו אמרו הן עם לבדד ישכון ובגוים לא יתחשב להעיר על התכלית שישראל פונה אליו לאור באור החיים תמות נפשי מות ישרים ותהי אחריתי כמהו:
@843 **התועלת** הח' הוא בדעות והוא להודיע שאין כח בנחש ובקסם להודיע הדברי' העתידים למי שתדבק בו ההשגחה לפי שענייניהם בלתי מסודרים משפע הכוכבים וזהו אמרו כי לא נחש ביעקב ולא קסם בישראל ולזה גם כן לא הלך בפעם כפעם לקראת נחשים אך הנבואה תודיע זה כי היא מסודרת מהשכל ושופעת ממנו כמו שביארנו בשני מספר מ"י ולזה תמצא שהודיע השם יתעלה לאברהם האותות והמופתים שיתחדשו על דרך ההשגחה הפרטית בעת יציאת ישראל ממצרי' למשכם לעבודתו ולזה אמר לו וגם את הגוי אשר יעבודו דן אנכי ולזה קרא בספר ישעיה שם השם יתעלה פלא יועץ ר"ל שהוא מודיע הפלאים טרם בואם זמן ארוך והנה בזה עיון חזק לא יכיל ביאורו זה הספר:
@843 **התועלת** הט' הוא במצות והוא שכבר למדנו מזה שהדם נקרא משקה אשר ישתה למה שאמר ודם חללים ישתה וזה שאין ראוי שנבין אומרו כל משקה אשר ישתה אשר ראוי שישתה לפי משפטי התורה שאין הטומאה בדברים יותר מפני היותם ראוים למאכל ולמשתה לפי משפטי התורה אבל הענין הוא בהפך שהבהמה הטהורה שנשחטה טהורה מלטמא ואין הענין כן בבהמה הטמאה ולזה הוא מבוא שאמרו אשר ישתה הרצון בו שיהיה מצד עצמות וראוי לשתות ולזה יתבאר שהדם מקבל טומאה כי הוא ראוי לשתות מצד עצמות שנאמר ודם חללים ישתה:
@843 **התועלת** הי' הוא להודיע אמתת הנבואה כי בלעם נתנבא בכמה דברים כבר נתחדשו ויצאו אל הפעל כמו שיתבאר מדברי ביאורינו זאת הפרשה:
@843 **התועלת** הי"א הוא להודיע ענין ביאת מלך המשיח אשר אנחנו מקוים תמיד בו כמו שאמר דרך ככב מיעקב וגו'. כי לא היה מיעקב מי שהרס ורמס כל האומות עדיין ולזה יחוייב שנודה שעליו אמר זה:
@843 **התועלת** הי"ב הוא להודיע שעברה גוררת עברה הלא תראה כי מזנות העם אל בנות מואב נמשך להם שאכלו מזבחי ע"ז והשתחוו לע"ז ולזה ראוי לכל אדם להשמר מעבירה קלה כמו השמרו מהחמורה כי הקלה תביא אליה:
@843 **התועלת** הי"ג הוא להודיע כי כאשר התחל לצמוח רע מה ראוי להשתדל להסירו תכף בלי שום עצלה כדי שלא יצמח יותר לה צוה השם יתעלה למשה שירבה השופטים לישראל להרוג תכף כל הנמצדים לבעל פעור כדי שישיב אפו מישראל וצוה לעשות זה לעיני השמש כדי שיוסרו כל ישראל ויסורו זה הרע מהם לגמרי:
@843 **התועלת** הי"ד הוא במדות והוא להודיע רוע תכונת זמרי שעם ראותו ההרג כל הנמצדים לבעל פעור והיה המגפה בעם ה' על זאת העבירה לא נמנע מלהחזיק בה עד שבפרהסיא הביא המדינית במחנה ישראל והביאה לאהלו להזקק לה תכף אם לרוב רתיחת טבעו והתגבר יצרו הרע עליו אם שכיון להכעיס ולמרות דבר השם יתעלה:
@843 **התועלת** הט"ו הוא להודיע שבועל בת אל נכר מותר להרגו בשעת מעשה ולזה ספר שפנחס דקר את שניהם בשעת מעשה באופן שנתבאר לכל שהם היו נזקקין אז זה לזה:
@843 **התועלת** הי"ו הוא שבכל מקום שיש בו חול השם יתעלה אין חולקן כבוד לרב אבל כל הקודם להסיר המכשול זכה ולזה תמצא שעם היות משה רבינו בזאת המדרגה הנפלאה שהיה בה מהמעלה והשלמות הנה לא לקח פינחס רשות ממנו על זה המעשה אבל התעורר מעצמו לבער הרע בזריזות רב ושם נפשו להרוג נשיא שבט ישראל לקנאתו לאלהיו וכבר היה לו מזה גמול טוב מהש' יתעלה שנתן בריתו אתו החיי' והשלום וזכה להיות מזרעו כהנים גדולים רבים והנה מצאנו לו מארך חיים שכבר היה חי בימי פלגש בגבעה אמר ופנחס בן אלעזר בן אהרן הכהן עומד לפניו בימים ההם גם היה חי בימי דוד אמר ופנחס בן אלעזר בן אהרן נגיד היה עליהם לפני יי' ואמו רז"ל שעדיין הוא חי ויחיה עד תחית המתים ולזה הסכימו שפנחס הוא אליהו כי נמצא לו ארך חיים נפלא כמו שאמר מלאכי הנה אני שולח לכם את אליה הנביא וגומר. והנראה בעינינו שהענין הוא כמו שנזכור הטעם בביאור מלכים בג"ה:
@877 **פינחס בן אלעזר בן אהרן הכהן וגו', עד צו את בני ישראל ואמרת אליהם את קרבני לחמי לאשי:**
@877 **ואולם התועלות המגיעות מזאת הפרשה הם ח':**
@877 **התועלת** הראשון הוא להודיע כי ה' יתע' ישלם לעושה הטוב בטובתו ולזה היה ברית שלום לפינחס תחת שומו בין ישראל ובין השם ית' והיתה לו הכהונה הגדולה לו ולזרעו לכפר על בני ישראל תחת אשר כפר על ישראל בזה המעשה:
@877 **התועלת** השני הוא להודיע שמי שיתאמת לו מאחר שהוא מבקש לכלותו ראוי שיקדים הוא לכלות האחר להציל עצמו ולא תמצא שצוה השם יתע' להכות המדינים מפני ידיעתו שנאתם אל ישראל ובקשם רעתם עם מה שנוספה השנאה בהריגת כזבי בת צור:
@877 **התועלת** השלישי הוא מה שלמדנו מזה המספר שנמנו ישראל בערבות מואב שכבר נתקיימה ברכת יעקב במה שאמר אפרים ומנשה בראובן ושמעון יהיה לי כמו שביארנו בביאור דברי זאת הפרשה:
@877 **התועלת** הרביעי הוא להודיע שראוי להרחיק המחלוקת תכלית ההרחקה ולזה התחכמה התור' לסדר איך תהיה חלוקת הארץ באופן לא יהיה עמה ערער ומחלוקת. ועשתה זה טרם היות להן הארץ כי אולי אחר זה יאמרו קצתן שטרחו יותר במלחמה או הצליחו יותר בו ויבקשו מפני זה שיהיה להם חלק יותר גדול ויהיה זה סבה לחדוש הקטטה והגבילה גם כן זה בתכלית מה שאפשר מהיושר ר"ל שיקח כל אחד מהנחלה לפי פקודיו אשר יתכן בהם שיצאו לצבא כי הם אנשי המלחמה וראוי שיהיה חלקם חלק כחלק ואחר כך ישוו הנחלה ביניהם באופן שזכרנו כדי שלא יהיו הקטנים אשר לא יצאו לצבא בזולת נחלה:
@877 **התועלת** החמישי הוא להודיע שכבר נתקיים יעוד ה' ית' שימותו כל אנשי המלחמה במדבר זולתי כלב בן יפונה ויהושע בן נון:
@877 **התועלת** הששי הוא להודיע שאין ראוי שימנע האדם מפני הבושת מהביא משפטו לפני הגדולים אבל ראוי שישתדל בזה בחריצות ובזריזות כדי שיגיע לו הראוי הלא תראה כי בנות צלפחד לא בשו מהביא משפטן לפני משה ולפני אלעזר הכהן ולפני הנשיאים וכל העדה עד שהשיגו מבוקשן במה שהיו מבקשות מדב' נחלה לפי שכבר שאלו כהוגן כמו שביאר':
@877 **התועלת** השביעי הוא במצו' והוא מה שצוו לדון בדיני נחלות לפי מה שזכרה התורה והנה לא היתה הבת יורשת כי מדרכה שתהיה נקנית לא קונה אלא אם יהיה זה בזה המקום שאין שם בן כי אז ראוי שתהיה הבת יורשת אביה כדי שלא יעזוב לאחרים חילו והנה לא תשוב הנחלה לאחים מן האם כדי שלא תסוב נחלה ממשפחה למשפחה ולזה הוא ראוי שתשאר לבני המשפחה היותר קרובים וכבר נעמוד על היותר קרובים כשנעלה העניין אל האב ואחר אל אבי האב ואחר אל אבי אבי האב כמו שביארנו:
@877 **התועלת** השמיני הוא להודיע שהוא ראוי למנהיג השלם שישתדל בשלום המונהגים ממנו גם בעת העדרו מהם לפי מה שאפשר ולזה מצאנו שכאשר הביא ההכרה שיאסף משה אל עמיו השתדל עם השם יתעלה שיפקוד איש על העדה אשר יוציאם ואשר יביאם ויסדר ענין קבוציהן כדי שלא יהיו כצאן אשר אין להם רועה כי זה יהיה סבה לבלבול עניניהם ושמע השם יתעלה לקולו ונתן על העדה יהושע בן נון אשר למדו משה והכינו ושמחו בגבול מהשלמות שהיה ראוי לנבואה וצוהו משה והישירהו על מה שיעשה ואיך תהיה הנהגתו באופן שלא יחסר בה דבר ממה שיהיה בו תועלת לעם:
@1044 **ואולם התועלות המגיעות ממנה הם י':**
@1044 **התועלת** הראשן הוא להודיע שיש בהקרבת העולות תועלות בהגעת הנבואה ולזה סמך דבר הקרבת העלה למה שזכר מורך הנביא לשאל במשפט האורים לכהן גדל כמו שזכרנו:
@1044 **התועלת** השני הוא במצות והוא לזרז ישראל על מצות התמידים לפי שלא הקריבום במדבר זולתי בהר סיני וכבר זכרנו התועלת המיוחד המגיע מהקרבת התמידים בפר' ואתה תצוה ובספר ויקרא ביארנו התועלת המגיע מהקרבת העולה באופן שזכרה אותו התורה:
@1044 **התועלת** השלישי הוא במצות והוא מה שצותה התורה להוסיף על התמידין בשבת שני כבשים בני שנה תמימה רוצה לומר שלא יוסיפו על שנה ויהיו בלי מום:
@1044 **התועלת** הרביעי הוא במצות והוא מה שצותה התורה להקריב קרבן מוסף בר"ה והוא שני פרי' ואיל אחד ושבעה כבשים בני שנה תמימים לעולה ושעיר עזים אחד לחטאת:
@1044 **התועלת** החמישי הוא במצות והוא מה שצונו להקריב מוסף בחג המצות והוא שני פרים ואיל אחד ושבעה כבשים בני שנה תמימים לעולה ושעיר עזים אחד לחטאת:
@1044 **התועלת** הששי הוא במצות והוא מה שצונו להקריב מוסף בחג השבועות והנה העולות שיקריבו זה היום הם עשרם עשר על הלחם ועשר לחובת היום יתר על התמידים:
@1044 **התועלת** השביעי הוא במצות והוא מה שצונו להקריב מוסף בר"ה על מוסף ר"ח והנה העולות שיקריבו ביום הזה יתר על התמידים הם י"ט עשר למוסף ר"ח ותשע למוסף ר"ה:
@1044 **התועלת** השמיני הוא במצות והוא מה שצונו להקריב מוסף ביום הכפורים והנה העולות שיקריבו יתר על התמידים הם תשעה:
@1044 **התועלת** התשיעי הוא במצות והוא מה שצונו להקריב קרבן מוסף ביי חג הסכות ואולם המוספים מתחלפים במספר העולות כי פרי החג הם מתמעטין והולכי' לפי רבוי הימים:
@1044 **התועלת** העשירי הוא במצו' והוא מה שצונו להקריב קרבן מוסף בשמיני עצרת הנה מספר העולות הקרבות בו הם תשע ואולם התועלת המגיע בהיות המוספין על זה האופן הנזכר פה הנה זה יתבאר כשנציע תחלה קצת דברים ביארנום בה' מספר מ"י וזכרנום במה שקדם מביאורנו זה והוא כי המכוון מהקרבנות הוא להעיר על מציאות הצורה וכ"ש העולות וכן העניין במועדים אלא שהם יעירו על מציאות הצור' הראשונה כמו שביארנו במה שקדם ונאמ' כי הוא מבואר כי בצד מה תהיה הצורה השביעי במדרגה הוא ה' ית' והם צורות היסודו' ואחריה צורת הדומם ואחריה צורת הצומח ואחריה צורת המרגיש ואחריה צורת המדבר ואחריה צורת השכלי' הנפרדי' העלולי' והשביעית הוא האלוה ית' ובצד אחר יותר בורר המדרגו' כאלו תהיה הצורה השמיני' היא ה' ית' וזה שכבר תהיה הצורה הששית מניע הגלגלי' שכל אחד מהם ישיג באופן מה חלק מנימוס הנמצאות וסדרם וישרם כמו שביארנו בה' ממ"י והצורה השביעית השכל הנאצל מהגרמי' השמימיי' והוא בצד מה משיג כללות נימוס הנמצאו' השפלות ויש לו השגה מה בעליונות כמו שביארנו בה' ממ"י ומצד אחר יותר בורר המדרגות האלו תהיה הצורה התשיעי' הוא ' ית' וזה שכבר תהיה הצורה השישית מניעי גלגלי כוכבי לכת והצורה השביעית הוא המגיע לערבות כי הוא עליון מאד על אלו המניעי' ובאופן מה תקיף השגתו בהשגות כלם כמו שביארנו בחמישי ממ"י אלא שהשגת השכל הפועל בנימוס מה שיתחייב מכל אלו המגיעים היא יותר שלמה מהשגת זה המגיע כמו שביארנו שם והנה בצד אחר ימנו בו אלו המניעים הנבדלי' והוא יותר מיוחד מהקודם שיהיה ה' ית' הוא העשירי ויהיו ז' מניעי לז' כוכבת לכת והשמיני מניע גלגל הכוכבים הקיימים והתשיעי הוא השכל הפועל והעשירי הוא השם יתע' ובצד אחר יותר בורר מזה הקודם יהיה השם ית' הוא החמישים כשימנו כל מניעי הגלגלים והראשיי' והמשרתי' להם וכבר ביארנו שהענין הוא כן במופת שאין ספק באמתתו בה' ממ"י ושאם התבאר כי לכל אחד מכוכבי לכת גלגל אחד יניעהו התנועה היומית וגלגל אחר מיוחד יניעהו התנועה המתאחרת וזה ממה שזכרנו אותו על דרך ההצעה לבאר ממנו סבת כל הנזכר באלו המוספין ונאמר שהנראה לנו במוסף שבת שנכפלו בו העולות הקרבות בכל יום הוא מפני מה שיעיר עניין קדושת היום השביעי על מציאות הש"י וההשגה בו מצד מה שנעמוד על זאת המדרגה השביעית מהצורות שהיא הש"י נבדל לעבודת הש"י להעמידנו על זאת הפנה ולפי שמזה הד נכפלה ההכנה להגעת הנבואה לכהן הוכנו בו עוד מהעולות שנים להעיר על מה שראוי שתכפל השגה וההכנה ביום זה להתיחדו לעבודת הש"י ולזה ראוי שישלם בו יותר מתבודדות השכל מבין שאר הכוחות הנפשיות ולהתמיד יותר זה ההתבודדות כדי שישלם ביום הזה וזה שכיון בו וכפלו אלו העולות ואולם מוסף ראש חדש היה ביום ההוא אשר בו חדוש ראיית הלבנה כי חדושו יורה על תנועת הגרמים השמימיים בעצמם כי זה מורה שאין השמי' קיימים והארץ מתנועעת התנועה היומית כמו שחשבו אנשי' וזה שאם היה הדבר כן היה הירח מתמיד במרחק אחד מהשמש ואנחנו רואים הפך זה כי בכל חדש תשיג הירח השמש פעם אחת ואחר תרחק ממנו מעט מעט עוד תשוב להתקרב אליו מעט מעט וכן העניין באור הירח שהוא מוסיף תחלה מעט מטע ועד יחסר אורה מעט מעט עד שיעדר ואחר ישוב להראות ואז הוא חדוש הלבנה וזה ממה שיחייב בהכרח שיהיו השמי' מתנועעי' ולפי שהוא מבואר שיחוייב בכל מתנועע שיהיה לו מניע הנה יחוייב שיהיה לגרמי' השמימיי' מניע ולזה נעמוד על מציאות הצורות הנבדלות ולפי שכאשר יעוין בהם בזה האופן ימצאו בהכרח שבעה מניעים לכוכבי לכת ומניע אחד לגלגל ערבות ושכל אחד כמו משותף ושופע מכלם והוא השכל הפועל והשכל אשר הוא ההתחלה הראשונה לכל נמצאו' היה שם מספר העולות עשר להעמיד על מציאות ההתחלה הראשונה שלא יטעה אחד כשיחשב כי המניע לגלגל ערבות הוא הש"י כמו שחשבו זה קצת גדולי הפילוסופים כי אין העניין כן כמו שביארנו במה שאין ספק בו באמתתו בה' ממ"י ולזה היו שם שבעה כבשי' להעיר על מניעי גלגלי שבעה כוכבי לכת ואיל אחד שהוא יותר שלם מהכבש להעיר על מניע גלגל ערבות שהוא יותר נכבד מאד ממניעי שבעה כוכבי לכת והיו שם שני פרים להעיר על מציאות השכל הפועל ומציאות הש"י ואע"פ שהם מתחלפי המדרגה מאד לאין שיעור הנה מפני קצת שיתוף שיתדמה ביניהם שתפם והנה השתוף ההוא הוא כי אצל השכל הפועל ימצא הנימוס המושכל לכל הנמצאות השפלות ומן הענין בשם ית' אלא שאצלו ימצא הנימוס המושכל לכל הנמצאות במוחלט כמו שביארנו בה' ממ"י ומצד השתוף הזה טעה אלישע אחר וחשב שיהיה השכל הפועל הוא השם יתע' וזה אמרם ז"ל מטטרון חזא ששמו כשם רבו ולהסיר מזה העטות סדרה התורה בזה המוסף ב' פרים להעמידנו על מציאות הסבה הראשונה והנה לבאר ההבדל בין השם ית' ובין השכל הפועל תמצא בקצת המקומות שלא שם בו כי אם פר אחד להעיר על מציאות הש"י ושם בו ב' אלים להעיר על מניע ערבות ועל השכל הפועל מצד שתוף מה ביניהם כי מניע ערבות אצלו ציור כולל הרבה מציורי מניעי כוכבי לכת כמו שביארנו בה' ממ"י ולזה היה אצלו מציור נימוס הנמצאו' השפלות וסדרם וישרם קרוב למה שימצא מזה לשכל הפועל ולפי שהמכוון בטומאת מת הוא להעמיד על מציאות הצורה כמו שקדם והיה בכאן מה שיעמיד באופן שלם על מציאות הצורה הנה מן הראוי היה שיהיה נכלל בזדה מה שיכפר על הטומאה ולזה היו בכאן שעירי עזים לחטאת לכפר על הטומאה והא כולל לשעירי הרגלים ג"כ ובזה ג"כ תשלם הסבה במה שנזכר במוסף הפסח כי הוא מסכי' למה שנזכ' במוסף ראש חדש בשוה והנה היה נעשה בט"ו לחדש כי אז תהיה הלבנה בתכלית המרחק מהשמש ויהיה אורה שלם ויורה עניינ' מפני זה על תנועת השמי' כמו שהורה עליו חדושה וסור אורה ולזאת הסבה ג"כ היה חג הסכות בט"ו יום לחדש והנה היו מספר ימי החג שבעה להורות מצד הימים על מציאות ה' ית' כשנעמוד מהצורה על שבע מדרגותיהם אשר השביעית הוא ה' ית' ולפי שבבחינת עצמם תהיה הראשונה ה' ית' הנה היום הראשון קדש לפי שבבחינת עמידתינו עליהם תהיה האחרונה השם ית' היה היום השביעי שבתון ואולם במוסף חג השבועות נכפלה ההערה הזאת במה שקרב על הלחם ובמסוף היום והיום בעצמו מעיר על המניע החמשים שהוא ה' ית' ולזה היה היום החמשים קדש ולפי שלא יגיע מספר המניעי' לזה המספר אם נניח שלא יהיה לתנועה היומית כי אם גלגל אחד ושאין לתנועה המתאחרת ג"כ כי אם גלגל אח' כמו שחשבו אנשים הנה הישירתנו התור' בזה ההכפל שיש שם שבעה מניעים מסכימים בכוכבי לכת בכל אחד מאלו התנועות ולזה היו בכאן שבעה כבשי' שני פעמים וכבר בארנו במופת אמיתי שהעניין הוא כן בה' ממ"י ולפי שהיה זה להעיר על החמישי' שהוא קדש לא היה החג כי אם יום אחד ואמנם החדש השביעי הנה קדושו מורה על המדרגה השביעית שהוא קדש לפי שהוא שביעי לחדשי' ולפי שהוא ידריך בקדושת היום להעיר על שהעשירי קדש ולזה היה היום העשירי מזה החדש קדש גם כן הנה במוסף היום לא העיר במדרגת הצורו' כי אם על תשע והיה הפר מורה על השכל הפועל והאיל מורה על מניע ערבות והכבשים השבעה על מניעי הגרמים השמימיי' והנה היה היום הראשון קדש לפי שה' ית' הוא הצורה הראשונה בבחינת עצמו הצורות והיה היום העשירי קדש לפי שהשם יתע' הוא הצורה המושגת לנו באחרונ' והנה קדושת היו' הראשון מורה על שהעשירי קדש וט' העולות מורות על ט' הצורות הנשארו' וכן הענין בקדושת היום העשירי ולזה לא היו בו כי אם ט' עולות והנה לא שם הצורה העשירי' במספר העולות להורו' על רוממות ה' ית' על אלו הצורות ולזאת הסבה ג"כ לא היתה שם קדושה נוספת בימי' שבין הראשון והעשירי להורות על עוצם ההבדל שיש בין ה' ית' ובין אלו השכלי' העלולים ממנו ואפשר ג"כ שנאמר שהתשע עולות מורות על תשע מדרגות מהצורו' והתשיעי קדש באופן שזכרנו בהצעה ויהיה הפר להעיר על ה' ית' אלא שהדרך הראשון הוא היותר נכון מצד הסכמת שבעת כבשי' זה לזה במשל והוא מבוא' לפי מה שזכרנו מהתועלת במועדם אשר התחלתם הוא חג המצות ומעיר על התחלת התישר האדם לדעות האמיתיות ולזה ג"כ היה לחמו מצה וחג הביכורים מורה על התישרות יותר ולזה היו בו מתן תורה והיו שתי הלחם בו חמץ והחדש השביעי מעיר על תכלית ההתישרות והוא מבואר כי בהתחלת ההשגה לא ישיג האדם מאד ההבדל בין הש' ית' ובין השכל הפועל ולזה הושמו' העולו' עשר בחג המצות ובחג השבועות ג"כ ואולם אחר התכלית ההשגה יושג מאד ההבדל בזה ולזה לא הושמו העולות בראש השנה וביום הכיפורי' כי אם תשע להפלגת ההבדל הנראה אז בין המדרגה אשר לשם יתעלה ובין מדרגת השכלים העלולים ממנו ולזה הושם המעיר על השם יתעלה יום קדוש והמעיר על שאר השכלים תשע עולות ולפי שזאת ההשגה תתוסף תמיד לא היה ההבדל חזק בין אחד לחדש השביעי ובין שאר הימים שיש בינו ובין העשירי כחזק ההבדל בין היום העשירי לחדש השביעי ובין שאר הימים האלו וזה כי היום העשירי אסור בעשיית כל מלאכה ובו פרישות מכל התענוגים הגופיים וזה כי כל מה שיתחכם האד יותר יכיר יותר עוצם ההבדל בין השם יתעלה ובין שאר הצורות ולזאת הסבה תמצא שבחג הסכות שהיו שבעת ימים להורות על שהצורה הראשונה מאלו המדרגות השבעה מהצורות הוא קדש והוא הש"י הושם היום הראשון קדש כי הוא הצורה הראשונה מצד עוצם מדרג הצורות ולא חששה התורה להשים היום השביעי קדש מפני היותו מאוחר בידיעה לפי שאחר שלמות האדם באלו ההשגות יצוייר בעצם ציורו שהש"י הוא הראשון והנה היה יום אחד לחדש השביעי יום תרועה להעיר האנשים שיקיצו משנת התרדמה ויעיינו בזה עד שיעמדו על אמתת מה שכוונה התורה בזה וכן היה ביום הכפורים בשנת היובל לזאת הסבה כי קדוש היובל יעמוד על קדוש המדרגה החמשי' ועשירי לחדש על קדוש העשיר והנה היו ארבעה עשר כבשים במוספי חג הסכות לסבה שזכרנו בעולות חג השבועות והיו שם שני אלים להורות על שבערבות ג"כ שני מניעי' האחד מניע התנועה היומית והאחר מניע התנועה המתאחרת ושהם זולת המניעים אשר באלו התנועות לאחד אחד מכוכבי לכת והם יותר שלמים מהם לסבות האחד מצד שהם משרתים בכוכבי לכת ואולם בערבות האחד מהם ראשון והשני מצד רוממות הנימוס המסור' מערבות על הנימוס המסודר מאחד אח' מכוכבי לכת וזה כלו ממה שהתבאר באור שלם בה' ממ"י ואולם הפרים כשחוברו באלו הימים היו תמיד י"ד והנה היו שם תמיד שבעה פרים והם מעירים על המניעים הראשיים והם מניעי הגלגל אשר בו כוכב כוכב מכוכבי לכת ולהעיר שהם יותר נכבדות מהשאר היו פרי' העולות המעירים עליהן והנכלל בפרי' הנשארים והימים שהיו תמיד שבעה מורים על מניעים אחרים נעמוד עליהם מצד תנועת החלוף הנמצאת לכל אחד מהם כי זה דבר משותף לכל כוכבי לכת ר"ל שימצא להם תנועת האורך מיוחדת ותנועת חלוף תשימה בלתי שוה והנה כשנתבונן באלו החלופים בכללם נעמוד על מספר המניעים כמו שיתבאר לך מדברינו בה' ממ"י והנה לחלוף עניניהם הושמו המעירים עליהם ימים ופרים ואפשר עוד שנאמר כי הפרים שנוספו בכל יום על שבעה העירו על דברים יעמידונו בצד יותר מיוחד על מספר המניעי' אשר לכוכבי לכת והנה יהיה מה שהורו עליו הששה פרים הנוספים לפי זאת ההנחה זולת מה שהורו עליו החמשה פרים הנוספים ביום השני וזולת מה שהורו עליו הארבעה פרים הנוספים ביום השלישי וזולת מה שהורה עליו השלשה פרים הנוספים ביום הרביעי וזולת מה שהורה עליו השני פרים הנוספים ביום החמישי וזולת מה שהורה עליו הפר הנוסף ביו' השישי ר"ל מה שיעיר עליו הנעשה ביום אחד מהם היה זולת מה שיעיר עליו הנעשה ביום אחר והוא מבואר כי אחר התנועות שהיו מהמניעים הראשיים לכוכבי לכת ימצאו שם תנועות משותפות לששה לבד מכוכבי לכת והוא תנועת החלוף כי היא לכלם זולת השמש ותנועות משותפות לחמשה מהם והוא היות תנועת הרוחב בהם בלתי קיימת ברוחב אחד והנזורות והיושר והעמידה כי היא לכלם זולת השמש והירח ותנועות משותפות לד' מאלו הה' הנבוכי' והוא תנועת הארך המיוחדת שתהיה בגובה בסבוב האחד מפעם אחת ותנועות משותפות לשלשה מהם והוא היות הגזורות בעת נגודם לשמש והיושר בעת היותם עמו כי זה ימצא לשבתאי וצדק ומאדים לבד ותנועות משותפות לשנים מהם והוא היות הככב בגובה בסבוב האחד ב' פעמים כי זה יהיה לירח ולכוכב לבד ובצד האחד יהיה לשנים מהם לבד הגזורות בהיותם עם השמש והנה נוגה וכוכב תנועה לא תמצא כי אם לאחד מהם והוא הרחב הקוים הנמצא לירח וכאשר נתבונן באלו התנועות ובמשיגיהם יתאמת לנו מספר המניעים כמו שביארנו בחמישי מספר מלחמות השם ולזה היו אלו הפרים מתמעטים והולכי' כאלו הישירתנו התורה בזה האופן לעמוד על מספר אלו המניעים כדי שנעמוד על מציאות החמשי' שהוא קדש והוא הש"י והנה היה השמיני עצרת רגל בפני עצמו לפי שאם היה שתהיה הוראתו על שהשמיני הוא קדש רוצה לומר ממדרגו' הצורות כמו שהצענו הנה הורה זה היחוד ליום היה מבין שאר הימים עד שהוא רגל בפני עצמו הבדל זאת המדרגה משאר המדרגות עם שבזה האופן יתישר יותר להיות היום הזה מורה על העשירי שהוא קדש במה שיעלו בו במוסף תשע עולות המורות על שבעה כוכבי לכת ומניע ערבו' והשכל הפועל לפי מדרגותיהם כמו שזכרנו ולזה הבדיל מהם המורה על מציאות העשירי שהוא קדש והושם המרה עליו היו' ההוא הקדוש הנה זה הוא מה שנראה לנו בעניין אלו המוספין והוא נפלא מאד כמו שתראה והוא מעיד מאד על אמתת מה שזכרנו בכונות הקרבנות והטומאות וגם מה שזכרנו מענינם במה שקדם מעיד על אמתת מה שאמרנו בזה המקום וזהו על דרך האמת שהוא מעיד לעצמו מכל צד ומכל פנה יתברך היכול אשר גלה לנו סודו באלו העמוקות ויתרומם על כל ברכה ותהלה:
@1046 וידבר משה אל ראשי המטות לבני ישראל לאמר עד נקום נקמת בני ישראל מאת המדיני'.
@1046 ואולם התועלות המגיעות מזאת הפרשה הם שנים:
@1046 **התועלת** הא' הוא במצות והוא שלא יעבור הנודר נדרי אסר או הנשבע שבועת אסר על דברו אבל יקיים ככל היוצא מפיו ויש בזה שתי מצות האחת מצות לא תעשה והשנית מצות עשה והנה התועלת באלו המצות מבואר כי אם היה מותר לאדם לחלל דברו היה זה מביא להקל באמונת הש' יתעלה כמו שזכרנו בעניין טעם אזהרה שבועת שוא עם שבזה תועלת מהדברים המדיניים לקיים כל דבר בכמו אלו האסרים ובו עוד תועלת כי בהם יזדרז האדם את עצמו בהרבה מהפעולות הטובות ולו היה לאדם להתיר נדרי עצמו יסור התועלת מאלו הדברים:
@1046 **התועלת** הב' הוא במצות והוא לדון בדיני הפרת נדרים בין איש לאשתו בין אב לבתו בנעוריה בית אביה והנה התוע' בזאת המצוה מבואר כי לולי זה תסור הממשלה מהאב על בתו במה שיקוה או מהאיש על אשתו עם שיהיה זה סבה להיות קטטה ביניהם תמיד כי הנשים מצד היות דעתן קלה עליהם מובנות מאד לאלו הנדרים והשבועות והנה נתנה התורה פנאי לזאת ההפרה מעת לעת כדי שיתישב בזה יותר האב או הבעל ואם יקרה שבסבת כעס לא יפר תכף הנה יסור כעסו ויתיישב דעתו תוך יום שלם לפי הנהוג מהאנשים על הרוב:
@1154 ואלו התועלות המגיעים ממנה הם י"ב:
@1154 **התועלת** הראשון הוא להודיע עוצם זריזות משה לעשות מצות השם יתעלה שאף על פי שידע שאחר זאת המלחמה יאסף על עמיו לא נתעצל בה אך מהר לנקום זאת הנקמה לפי מה שאפשר:
@1154 **התועלת** השני הוא להודיע שהשלמים אינם חרדים מהמות כי אינם בוחרים מאד באלו החיים הגופיים כי היותר טוב להם אחר שקנו מן המושכלות שימותו כדי שיתענגו תמיד בהשגת כל המושכלות אשר קנו אותן יחד כי אז לא ימנע החמר זאת ההשגה כמו שנתבאר זה במקומותיו. ולזה לא תמצא שחרד משה מהמות בזה המקום ולא במקום אחר אך בקש משה מהש' ית' שיפקוד איש על עדה אשר ישתדל בהנהגתם כי כונתו כלה היתה אל שימשך מטוב בסבתו מה שאפשר לו.
@1154 **התועלת** הג' הוא להודיע מה שהיה מעצם ההשגחה בזאת המלחמה כי במתי מעט באו על עם רב מאד היו בחצריהן ובטירותם והרגו אותם בכללם ולא נפקד איש מבני הצבא והיו הנהרגים באופן מהרבוי עד שהיה הטף בנשים אשר לא ידעו משכב זכר שלשים ושנים אלף והיה עוד מעוצם ההצלחה בזאת המלחמה שכבר המיתו בה בלעם בן בעור כי אם היה נשאר אולי ישתדל להזיק להם:
@1154 **התועלת** הד' הוא לפרסם הפלגת אהבת ה' ית' לישראל כי בהתפרסם לפניו שעם מדין ידעו ישראל בתכלית מה שאפשר להם השתדל בסבות הנאותות לכלותם בעת היות ישראל נעזרים בהשגחה אלהית הלא תראה איך היה מנהג הנשארים בהן עם ישראל בספר שופטים עם שכבר הרעו לישראל יותר משאר האמות אשר משלו עליהם ולזאת הסבה היתה המצוה להרוג בהם כל זכר עם שהשארת הזכרים בטף אולי יהיה להם למכשול בעניין ירושת הארץ כי בהתאחדם עם כלל ישראל יזוקו ישראל בחטא אלו אשר היו מוכנים לו מצד טבע הצור אשר חוצבו ממנו ומצד המנהג שגדלו בו והנה לזאת הסבה ג"כ צוה הש"י למחו' את זכר עמלק הלא תראה כי מהמעט שנשא בהם יא צפע דמה לכלות עם ה' והוא המן בן המדת האגגי ולזאת הסבה צוה להרוג נקבות מדין אשר ידוע ממשכב זכר פן יכשלו ישראל ויסירום מאחרי השם יתעלה:
@1154 **התועלת** הה' הוא לפרסם יושר אנשי הצבא שלא היה בהם איש שהחביא דבר מהשלל אך הביאו כלו לפני משה והנשיאים וכל העדה כאלו העירנו בזה כי יושר לבבם היה כלי אל שהגיע להם זאת ההצלחה העצומה בזאת המלחמה:
@1154 **התועלת** הששי הוא במדות והוא להודיע כי המתחיל במעשה אחד טוב ראוי שיזכה בהשלמת המעשה ההוא עד תכליתו ולזה ספר כי פינחס היה הראש בזאת המלחמה כי הוא התחיל לתת נקמת השם במדיין במה שהרג כזבי בת צור אשר באה להכשיל ישראל בזנותה והיה בזה גם כן סבה אל שנעצרה המגפה מעם השם ולזה רצה הש"י שיזכה להיות הוא הראש בזאת המלחמה אשר כוון לתת נקמת יי' במדין ולהציל ישראל מהיזקם במה שעתיד לפי מה שאפשר:
@1154 **התועלת** הז' הוא לפרסם כי אין כח בקסם שיגיע ההודעה במה שיתחייב מההשגחה האלהית במה שעתיד לאשר תדבק בהן ולזה זכר שכבר חרגו בלעם בן בעו' עם היותו קוסם לא קדמה לו הידיעה בזה לקחת עצה להציל עצמו בשיצא מהמקומות ההם שהשחיתום ישראל:
@1154 **התועלת** הח' הוא לפרסם שכבר השיב הש' יתע' גמולו לבלעם על זדון לבו במה שנתן עצה להכשיל ישראל בעריות ובע"ז כדי שיחר אף השם יתעלה בהם ויכלם:
@1154 **התועלת** הט' הוא להודיע שמי שהגיע לו טוב מהשם יתעלה ראוי שיכירהו ויודה עליו לשם יתעלה כי בזה מהתועלת מה שלא יעלם ולזה ספר ששרי האלפים והמאות התנדבו לשם יתעלה כלי זהב רבים על כל הטובות אשר גמלם שלא נפקד איש מאנשי המלחמה ולזאת הסבה בעינה הביאם משה אל אהל מועד להשאיר זכר זה המופת הנפלא ולזה ג"כ צוה הש"י שיקחו תרומת השם מהשלל לתת לכהנים וללוים להעיר שה הטוב הנפלא הגיע להם מהש"י לא מצד כחם ועוצם ידם:
@1154 **התועלת** הי' הוא להודיע שראוי לכל אדם להתרחק מעשות מה שאולי יהיה סבה להחטיא זולתו ולזה כעם משה על בני גד ובני ראובן בשאלם להם לנחלה הארץ אשר בעבר הירדן מזרחה מצד מה ששאלתם זו אולי תהיה להניא לב ישראל מעבור הירדן כי אולי יחשבו של זאת הסבה בחרו להם בני גד ובני ראובן זה לשערם שלא יוכלו ישראל להוריש הגוי' אשר שם ולזאת הסבה תמצא שכאשר הסכימו ללכת שם לצבא שלא היה אז לירוא מהנאת לב העם בשאלתם כי הם רואים צאתם עמם לצבא ולולי בטחם בשם יתעלה שיכניע הגוים ההם לפניהם לא נכנסו בזאת המלחמה:
@1154 **התועלת** הי"א הוא במסות והוא להודיע שראוי לכל אדם להרחיב הדברים בעסק שיהיה לו עם זולתו באופן שלא יהיה אפשר שיקרה בו שום מרמה ותחבולה ולזה תמצא שדקדק משה רבינו עליו השלום בזה התנאי שהתנה עם בני גד ובני ראובן והרחי' הדברי' בו בצד שלא יתכן בו שום מרמה:
@1154 **התועלת** השתים עשרה הוא במדות והוא שאין ראוי לאדם שיפותה בעבור תועלות פרטיות לבחר דבר על דבר אם לא אחד התישבות רב הלא תראה כי מפני היות מקנה רב לבני גד ולבני ראובן נפתו לבחור הארץ אשר בעבר הירדן מזרחה להיות המקום מקום מקנה והנה השיגם מזה החרטה אחר שנכבשה הארץ כי ראו שאולי זה יהיה סבה אל שיסורו בניהם מאחרי השם יתעלה והוצרכו מפני זה לבנות המזבח ההוא שנזכר בספר יהושע עם שהם היו יותר מוכנים לנפול ביד מצירי לישראל מזולתם ולזה תמצא שהראשונים שהגלה מלך אשור היו אלו השבטים עם שהמואבים היו לה תמיד לקוץ מכאיב מצד האר' הזאת שנחלו ישר' מהם על יד סיחון כמו שתראה מדברי יפתח הגלעדי:
@1158 **אלה מסעי בני ישראל וגומ' עד סוף הפרשה:**
@1158 **ואולם התועלות המגיעות ממנה הם ט"ו:**
@1158 **התועלת** הראשון הוא להוסיף אמות על מה שספרה התורה מעמידת אבותינו במדבר מ' שנה ולזה זכרה מסעיהם שם איך היו פרט בפרט כי הרבה תמצא בספורים האמתיים שכבר יוסיפו לאמת אותם בכמו אלו הפרטים:
@1158 **התועלת** השני הוא להודיע עוצם נפלאות השם יתע' וקיימו הבטחתו וזה שעם היותו בכל אחד מבתי מצרים מת והיו יודעים שזה הרע בא להם מצד ישראל הנה עם כל זה נתן השם יתעלה את חן העם בעיני מצרים שהשאילום כל חפציהם היותר חשובים באופן שנצלו את מצרים ועם כל זה היו יוצאים ישראל ביד רמה בעת היות המצרים מקברים את בכוריהם:
@1158 **התועלת** השלישי הוא להודיע כי השם יתעלה ברצותו לקרב ישראל לעבודתו והביאם בקלות להאמין בו הביא אותם תחלה אל מקום שלא ימצאו מים כדי שיכירו חסד השם יתעלה להם בתתו להם מים ואח"כ הביאם למקום מי מרים והמתיקם השם יתע' והם מי מרה ואח"כ הביאם למקום שנמצאו להם שם מים לרוב להעיר כי הטובות מסודרות ממנו לא הרעות לבד כמו שחשבו קצת חכמי פרעה ולזה אמר פרעה ראו כי רעה נגד פניכם כמו שביארנו בפרשת וארא:
@1158 **התועלת** הרביעי הוא מה שלמדנו בסמיכות מלך הכנעני למיתת אהרן שמיתת צדיק עושה רושם ולזה ראוי שידאגו האנשים בהפקד הצדיקים:
@1158 **התועלת** החמישי הוא במצות והוא מה שצונו לאבד עבודה זרה ובניינה מארצנו ולאבד משם גם כן עובדי ע"ז כי אם יותירו מהם יהיו לשכים בעיניהם ולצנינים בצדיהם בהחטיאם את ישראל ופתותם אותם לעבוד ע"ז:
@1158 **התועלת** הששי הוא מה שזכר מהגבלת הארץ כנען לכל צדדיה כדי שלא יקצרו ישראל מההשתדלות לכבשה כלה:
@1158 **התועלת** הז' הוא להודיע כי משה אע"פ שנענש שלא לעבור את הירדן הנה מפיו היתה הגבלת כל הנעשה בירושת האץ ולזה הגביל פה השם יתעלה על פיו מי ינחיל את הארץ לישראל ומה הארץ אשר ינחילוה להם ומה הערים אשר יתנו ללוים והוא גם כן הישיר יהושע אל מה שעשהו בעניין ירוש' הארץ וכבשתה כמו שיתב' במעט עיון בספר יהושע:
@1158 **התועלת** השמיני הוא במצות הוא הגבלתו מספר ערי מקלט וערי הלוים ושיעור מגרשיהם ומה שסביבו והנה התועלת בערי המקלט מבואר הוא לנוס שמה רוצח ולזה היה מחויב שיהיה מוכן באופן שיתכן שיהיה מקלט לכל בעת הצורך ולזה היה ראוי שיציינו בדרכים בדרך שיכיר כל עובר אי זה דרך ילך בה אל המקלט והנה היה מושבו שם עד מות הכהן הגדול כי אז יסור חום לב גואל הדם בראותו מיתת הכהן והתועלת בהיות אלו הערים ללויים ובזאת הצורה הוא כי כבר הוכנו להם מהמתנות כדי שיהיו פנויים לעבודת הש' יתעלה ולעמוד על סודות התורה והמציאות ולזה היה ראוי גם כן שיהיה מכונס נאה ובלתי מעופש כי זה ממה שיישיר אל ההשגו' העיוניות:
@1158 **התועלת** התשיעי הוא להודיע שיעור יושר התורה שרצתה שגם התושב אם הרג ישראל בשגגה יהיה פטור ממיתה אך יהיה גולה אל עיר מקלט כמו העניין בישרא':
@1158 **התועלת** העשירי הוא במצות והוא מה שצונו להרוג את הרוצח על פי עדים ועל פי עדת ישראל והו' הב"ד ולא יהרג בזולת זה והסבה בזה הי מבואר' במה שקדם:
@1158 **התועלת** הי"א הוא במצות והוא מה שהוזהר העד מלטעון כנגד הרוצח לחובה וכבר זכרנו סבת זה בביאורנו לזאת הפרשה ואולם לזכות שומעין לו כי לא תהיה טענתו במה שהוא עד בו אבל הוא דבר כנגד עדותו ועוד כי מפני שהוא ראוי שנשמור מהטיל עונש המות בזולת מקומו הראוי לו ראוי שנשמע טענות כל המזכין כדי שישמרונו מחטא בהריגת אדם לא במשפט ומזה יתבאר שאם הרוצח עצמו אמר שיש לו לטעון זכות לעצמו שומעין לו ואם יראו הדיינים כי יש ממש בדבריו יזכוהו:
@1158 **התועלת** הי"ב הוא במצות הוא מה שצונו לחייב גלות על ההורג נפש בשגגה כי בזה תועלת נפלא להביא האנשים אל שיהיו נזהרים מאד שלא לעשות דבר יהיה אפשר שיתחדש ממנו הריגת נפש בשגגה שמא יפלו בחובת זה הגלות הארוך שהוא עד מות הכהן הגדול:
@1158 **התועלת** הי"ג הוא במצות והוא מה שהוזהרנו מלקח כפר לפטור הרוצח מהריגה או מהגלות אפילו כי הטילה התורה כפר במי שיהרג שורו אחד מהאנשים והנה התועלת בזאת האזהרה מבואר מאד ממה שזכרה אותו התורה בזה כמו שביארנו בביאורנו לזאת הפרשה:
@1158 **התועלת** הי"ד הוא בדעות והוא להודיע כי החטאים הם מסירין השגחת השם יתעלה מהאנשים אשר החוטאים ההם מתאחדים עמהם וכבר ביארנו הסבה בזה בפרשת קרח:
@1158 **התועלת** הט"ו הוא במסות הוא להודיע כי כאשר יביא ההכרח אל שיגרע מה מחקו בעבור אחר הנה ראוי שכל מה שנוכל לעשות ביושר שישוב הדבר ההוא לאשר נגרע ממנו בדרך שלא יהיה נגרע ממנו לעולם נעשה אותו כאשר יכולנו על זה בזולת היזק לאשר תגיע אליו זה החק והמשל כי מפני שנגרעה נחלת צלפחד מנחלת בני חפר בכללם והיה אפשר לסבב שלא תהיה נגרעת מהן זאת הנחלה לעולם בזולת היזק לבנות צלפחד וזה יהיה כשינשאו לבני דודיהם הנה רצתה התורה שינשאו לבני דודיהן אחר שאין להם היזק בזה:
@1158 **ובכאן** נשלם זה הביאור מזה הספר והשלמנוהו בזמן קצר מאוד ובזולת ספרים ולזה יצטרך בג"ה לעבור עליו שנית והיתה השלמתו בכ"ג לחדש טבת של שנת צ"ח לאלף הששי והתהלה לאל ית' אשר עזרנו תברך ויתרומם על כל ברכה ותהילה אמן אמן:
@1158 **ונשלם ספר הפקודים ודגלי הצבאות ולאלהים** צבאות שבח והודאות. והוא ברחמיו ינקנו מכל נסתרות ומכל שגיאות ויראנו מתורתו נפלאות. וכן יהי רצון אמן:
